        col += textureSample(inputTex, inputSampler, sampleUV + dx *  0.125 + dy * -0.375);
        col += textureSample(inputTex, inputSampler, sampleUV + dx *  0.375 + dy *  0.125);
        col += textureSample(inputTex, inputSampler, sampleUV + dx * -0.125 + dy *  0.375);
