    var v = seed * 1664525u + 1013904223u;
    v.x = v.x + v.y * v.z;
    v.y = v.y + v.z * v.x;
    v.z = v.z + v.x * v.y;
    v = v ^ (v >> vec3<u32>(16u));
    v.x = v.x + v.y * v.z;
    v.y = v.y + v.z * v.x;
    v.z = v.z + v.x * v.y;
    return v;
}

fn prng(p0: vec3<f32>) -> vec3<f32> {
    var p = p0;
    if (p.x >= 0.0) { p.x = p.x * 2.0; } else { p.x = -p.x * 2.0 + 1.0; }
    if (p.y >= 0.0) { p.y = p.y * 2.0; } else { p.y = -p.y * 2.0 + 1.0; }
    if (p.z >= 0.0) { p.z = p.z * 2.0; } else { p.z = -p.z * 2.0 + 1.0; }
    let u = pcg(vec3<u32>(p));
    return vec3<f32>(u) / f32(0xffffffffu);
}

fn rowTime(row: f32, sd: f32, t: f32) -> f32 {
    let phase = prng(vec3<f32>(row, sd + 777.0, 0.0)).x;
    return floor((t + phase) * 8.0);
}

fn lineHash(line: f32, sd: f32, rt: f32) -> vec3<f32> {
    return prng(vec3<f32>(line, sd, rt));
}

fn pixelSort(uv_in: vec2<f32>, row: f32, sortAmt: f32, rt: f32, sd: f32, resX: f32) -> vec2<f32> {
    var uv = uv_in;
    let rh = lineHash(row, sd, rt);
    let threshold = mix(0.8, 0.2, sortAmt);
    let regionSize = 3.0 + rh.y * 20.0;
    let region = floor(uv.x * resX / regionSize);
    let regionHash = prng(vec3<f32>(region, row, sd + rt));
    let regionPos = fract(uv.x * resX / regionSize);
    let sortShift = regionPos * regionHash.x * sortAmt * 0.15;
    if (regionHash.y > threshold) {
        uv.x = fract(uv.x + sortShift);
    }
    return uv;
}

fn byteShift(uv_in: vec2<f32>, row: f32, shiftAmt: f32, rt: f32, sd: f32, resX: f32) -> vec2<f32> {
    var uv = uv_in;
    let rh = lineHash(row, sd, rt);
    let chunkWidth = 8.0 + rh.x * 80.0;
    let chunk = floor(uv.x * resX / chunkWidth);
    let ch = prng(vec3<f32>(chunk, row + 200.0, sd + rt));
    let shiftPx = (ch.x - 0.5) * 2.0 * shiftAmt * resX * 0.15;
    let sparsity = mix(0.85, 0.3, shiftAmt);
    if (ch.y > sparsity) {
        uv.x = fract(uv.x + shiftPx / resX);
    }
    return uv;
}

fn bitCorrupt(color_in: vec3<f32>, uv: vec2<f32>, row: f32, bitAmt: f32, rt: f32, sd: f32, resX: f32) -> vec3<f32> {
    var color = color_in;
    let bh = lineHash(row + 400.0, sd, rt);
    let levels = mix(256.0, 2.0, bitAmt * bitAmt);
    color = floor(color * levels + 0.5) / levels;
    if (bitAmt > 0.3) {
        let xorStrength = (bitAmt - 0.3) / 0.7;
        let px = floor(uv.x * resX);
        let xorHash = prng(vec3<f32>(px, row, sd + rt + 500.0));
        let mask = step(vec3<f32>(1.0 - xorStrength * 0.5), xorHash);
        color = mix(color, 1.0 - color, mask);
    }
    if (bitAmt > 0.6) {
        let shiftStr = (bitAmt - 0.6) / 0.4;
        let bitShift = floor(bh.x * 4.0) + 1.0;
        let scale = pow(2.0, bitShift);
        color = fract(color * mix(1.0, scale, shiftStr));
    }
    return color;
}

fn meltDisplace(uv_in: vec2<f32>, meltAmt: f32, t: f32, sd: f32, resX: f32) -> vec2<f32> {
    var uv = uv_in;
    let col = floor(uv.x * resX / 3.0);
    let colPhase = prng(vec3<f32>(col, sd + 601.0, 0.0)).x;
    let dripHash = prng(vec3<f32>(col, sd + 600.0, floor((t + colPhase) * 8.0)));
    let gravity = (1.0 - uv.y) * (1.0 - uv.y);
    let dripAmt = dripHash.x * meltAmt * gravity * 0.4;
    let dripProb = mix(0.9, 0.2, meltAmt);
    if (dripHash.y > dripProb) {
        let wobble = sin(uv.y * 20.0 + dripHash.z * TAU + t) * meltAmt * 0.02;
        uv.y = clamp(uv.y + dripAmt, 0.0, 1.0);
        uv.x = fract(uv.x + wobble);
    }
    return uv;
}

fn scatterDisplace(uv_in: vec2<f32>, scatterAmt: f32, t: f32, sd: f32, rs: f32, tileOff: vec2<f32>, fragCoord: vec2<f32>) -> vec2<f32> {
    var uv = uv_in;
    let scaledCoord = floor((fragCoord + tileOff) / rs);
    let phaseHash = prng(vec3<f32>(scaledCoord, sd + 700.0));
    let pixTime = floor((t + phaseHash.x) * 8.0);
    let pixHash = prng(vec3<f32>(scaledCoord, pixTime + sd));
    let threshold = mix(0.98, 0.1, scatterAmt * scatterAmt);
    if (pixHash.x > threshold) {
        let dirHash = prng(vec3<f32>(scaledCoord + vec2<f32>(1000.0), pixTime + sd));
        let dist = scatterAmt * 0.15 * (0.5 + pixHash.y * 0.5);
        uv.x = fract(uv.x + (dirHash.x - 0.5) * dist);
        uv.y = clamp(uv.y + (dirHash.y - 0.5) * dist, 0.0, 1.0);
    }
    return uv;
}

@fragment
fn main(@builtin(position) pos: vec4<f32>) -> @location(0) vec4<f32> {
    let time = uniforms.data[0].x;
    let seed = uniforms.data[0].y;
    let intensity = uniforms.data[0].z;
    let sort = uniforms.data[0].w;

    let shift = uniforms.data[1].x;
    let bits = uniforms.data[1].y;
    let channelShift = uniforms.data[1].z;
    let speed = uniforms.data[1].w;

    let melt = uniforms.data[2].x;
    let scatter = uniforms.data[2].y;
    let bandHeight = uniforms.data[2].z;
    let renderScale = uniforms.data[2].w;

    let tileOffset = uniforms.data[3].xy;
    let fullResolution = uniforms.data[3].zw;

    let tileDims = vec2<f32>(textureDimensions(inputTex));
    let resolution = select(tileDims, fullResolution, fullResolution.x > 0.0);
    let globalCoord = pos.xy + tileOffset;
    let uv = globalCoord / resolution;
    // Scale pixel-space coordinates so corruption patterns maintain their
    // visual size regardless of export resolution
    let rs = max(renderScale, 1.0);
    let resX = resolution.x / rs;
    let spd = floor(speed);
    let t = time * TAU * spd;

    // Scanline grouping - scale band height so rows stay visually consistent
    let rawRow = globalCoord.y / rs;
    let bh = max(1.0, floor(bandHeight * 0.32));
    let row = floor(rawRow / bh);

    // Per-row staggered time
    let rt = rowTime(row, seed, t);

    // Per-scanline corruption probability
    let rowHash = lineHash(row, seed, rt);
    let prob = intensity / 100.0;
    let isCorrupt = rowHash.x < prob;

    var sampleUv = uv;

    // 2D effects (not band-based)
    let meltAmt = melt / 100.0;
    if (meltAmt > 0.0) {
        sampleUv = meltDisplace(sampleUv, meltAmt, t, seed, resX);
    }
    let scatterAmt = scatter / 100.0;
    if (scatterAmt > 0.0) {
        sampleUv = scatterDisplace(sampleUv, scatterAmt, t, seed, rs, tileOffset, pos.xy);
    }

    // Band-based corruption to UV
    if (isCorrupt) {
        let sortAmt = sort / 100.0;
        let shiftAmt = shift / 100.0;
        if (sortAmt > 0.0) {
            sampleUv = pixelSort(sampleUv, row, sortAmt, rt, seed, resX);
        }
        if (shiftAmt > 0.0) {
            sampleUv = byteShift(sampleUv, row, shiftAmt, rt, seed, resX);
        }
    }

    // Sample color from input. Use textureSampleLevel because the channel-shift
    // and bit-corruption branches below depend on per-pixel values, which
    // disqualifies plain textureSample (which requires uniform control flow
    // for implicit derivatives). textureSampleLevel takes an explicit mip
    // level, no derivatives needed. These shaders don't use mipmaps anyway.
    var color = textureSampleLevel(inputTex, samp, sampleUv, 0.0).rgb;

    // Channel separation
    if (channelShift > 0.0 && isCorrupt) {
        let chAmt = channelShift / 100.0;
        let chHash = lineHash(row + 300.0, seed, rt);
        let rShift = (chHash.x - 0.5) * chAmt * 0.08;
        let bShift = (chHash.y - 0.5) * chAmt * 0.08;
        let rUv = vec2<f32>(fract(sampleUv.x + rShift), sampleUv.y);
        let bUv = vec2<f32>(fract(sampleUv.x + bShift), sampleUv.y);
        color.r = textureSampleLevel(inputTex, samp, rUv, 0.0).r;
        color.b = textureSampleLevel(inputTex, samp, bUv, 0.0).b;
    }

    // Bit corruption
    if (bits > 0.0 && isCorrupt) {
        color = bitCorrupt(color, uv, row, bits / 100.0, rt, seed, resX);
    }

    return vec4<f32>(color, 1.0);
}

/*
 * Craquelure - cracked-plaster groove network with carved relief over the
 * image. See craquelure.glsl for the full algorithm derivation (F2-F1
 * crack metric, border wobble, central-difference wall shading via filter/relief's
 * reliefShade, fixed 135-degree light, brightness/depth composition);
 * this is a 1:1 port.
 *
 * tileOffset converts tile-local positions into global procedural
 * coordinates, matching GLSL's `gl_FragCoord.xy + tileOffset`: globalCoord
 * seeds the crack mask's Voronoi hash (via crackMask's wobble/Voronoi
 * chain) so the crack network is continuous across CLI render tiles. It
 * is zero for ordinary full-frame renders (see filter/stipple's WGSL
 * port for the same pattern). The input-texture UV stays tile-local
 * (`pos.xy / texSize`, matching GLSL's `gl_FragCoord.xy / resolution`).
 * The crack pattern is seeded by global pixel position (tileOffset + local
 * coord), never normalized by the full image size, so neither backend
 * declares a fullResolution uniform.
 *
 * Every vector built in this shader (the wobble offset, the Voronoi
 * search cell/seed geometry, the k-gradient sample taps) comes from
 * `floor`/`fract` only (hash-, value-noise-, and Voronoi-derived, no `mod`), which - like GLSL -
 * are floor-based (not truncated) for negative inputs in WGSL, so no
 * floored-mod wrap is needed anywhere here. The light vector L is a
 * plain function of the fixed 135-degree angle constant, not fragment-
 * coordinate-derived at all, so it is textually identical to the GLSL.
 */

struct Uniforms {
    spacing: f32,
    depth: f32,
    brightness: f32,
    seed: i32,
    tileOffset: vec2<f32>,
}

@group(0) @binding(0) var inputSampler: sampler;
@group(0) @binding(1) var inputTex: texture_2d<f32>;
@group(0) @binding(2) var<uniform> uniforms: Uniforms;

// hash - hash / jitter.
fn hash12(p: vec2<f32>) -> f32 {
    var p3 = fract(vec3<f32>(p.xyx) * 0.1031);
    p3 = p3 + dot(p3, p3.yzx + vec3<f32>(33.33));
    return fract((p3.x + p3.y) * p3.z);
}

fn hash22(p: vec2<f32>) -> vec2<f32> {
    var p3 = fract(vec3<f32>(p.xyx) * vec3<f32>(0.1031, 0.1030, 0.0973));
    p3 = p3 + dot(p3, p3.yzx + vec3<f32>(33.33));
    return fract((p3.xx + p3.yz) * p3.zy);
}

// value noise - value noise (fBm not needed here).
fn vnoise(p: vec2<f32>) -> f32 {
    let i = floor(p);
    let f = fract(p);
    let u = f * f * (3.0 - 2.0 * f);
    return mix(mix(hash12(i), hash12(i + vec2<f32>(1.0, 0.0)), u.x),
               mix(hash12(i + vec2<f32>(0.0, 1.0)), hash12(i + vec2<f32>(1.0, 1.0)), u.x), u.y);
}

// Voronoi extended - jittered-grid Voronoi F1/F2: returns x = nearest seed
// distance (F1), y = second-nearest seed distance (F2). The 1-ring
// search is exact for F1; F2 can rarely be under-counted near a cell's
// corner at jitter's [0, 1] maximum. See craquelure.glsl's voronoiF1F2
// for the full derivation.
fn voronoiF1F2(p: vec2<f32>, jitter: f32, seedVal: f32) -> vec2<f32> {
    let g = floor(p);
    let f = p - g;
    var best = 1e9;
    var second = 1e9;
    for (var y = -1; y <= 1; y++) {
        for (var x = -1; x <= 1; x++) {
            let cell = vec2<f32>(f32(x), f32(y));
            let pt = cell + 0.5 + (hash22(g + cell + seedVal * 101.7) - 0.5) * jitter;
            let d = dot(pt - f, pt - f);
            if (d < best) {
                second = best;
                best = d;
            } else if (d < second) {
                second = d;
            }
        }
    }
    return vec2<f32>(sqrt(best), sqrt(second));
}

// Directional relief shading from height.
fn reliefShade(hC: f32, hR: f32, hT: f32, strength: f32, lightAngleDeg: f32) -> f32 {
    let grad = vec2<f32>(hR - hC, hT - hC) * strength;
    let n = normalize(vec3<f32>(-grad, 1.0));
    let a = radians(lightAngleDeg);
    let L = normalize(vec3<f32>(cos(a), sin(a), 0.75));
    return clamp(dot(n, L), 0.0, 1.0);
}

// Crack mask k at global pixel position gc: 1 on a cell border, falling
// to 0 within `edge` px (see craquelure.glsl's file header).
fn crackMask(gc: vec2<f32>, spacingPx: f32, depthPct: f32, seedVal: f32) -> f32 {
    let wob = vec2<f32>(vnoise(gc / 6.0), vnoise(gc / 6.0 + vec2<f32>(37.7, 91.3))) * 2.0;
    let p = (gc + wob) / spacingPx;
    let f1f2 = voronoiF1F2(p, 1.0, seedVal);
    let d = (f1f2.y - f1f2.x) * spacingPx;
    let edge = 1.5 + depthPct / 100.0 * 2.0;
    return 1.0 - smoothstep(0.0, edge, d);
}

@fragment
fn main(@builtin(position) pos: vec4<f32>) -> @location(0) vec4<f32> {
    let texSize = vec2<f32>(textureDimensions(inputTex));
    let globalCoord = pos.xy + uniforms.tileOffset;
    let uv = pos.xy / texSize;
    let src = textureSample(inputTex, inputSampler, uv);
    let seedF = f32(uniforms.seed);

    let kC = crackMask(globalCoord, uniforms.spacing, uniforms.depth, seedF);
    let kR = crackMask(globalCoord + vec2<f32>(1.0, 0.0), uniforms.spacing, uniforms.depth, seedF);
    let kL = crackMask(globalCoord - vec2<f32>(1.0, 0.0), uniforms.spacing, uniforms.depth, seedF);
    let kT = crackMask(globalCoord + vec2<f32>(0.0, 1.0), uniforms.spacing, uniforms.depth, seedF);
    let kB = crackMask(globalCoord - vec2<f32>(0.0, 1.0), uniforms.spacing, uniforms.depth, seedF);

    // Central-difference gradient of k; feeds both reliefShade's synthetic
    // height samples below and wallMask's locality gate.
    let gradK = vec2<f32>((kR - kL) * 0.5, (kT - kB) * 0.5);

    // Height fed to reliefShade is -k: a crack is a carved groove (a dip),
    // not a raised ridge - see craquelure.glsl for the full derivation.
    let hC = -kC;
    let hR = hC - gradK.x;
    let hT = hC - gradK.y;
    let shadeStrength = 6.0;
    let shade = reliefShade(hC, hR, hT, shadeStrength, 135.0);

    // reliefShade's flat-gradient baseline is 0.6, not 0.5 - recenter on
    // it, and gate by wallMask so flat ground gets EXACTLY shadeMul ==
    // 1.0 (gradK saturates to exactly 0 away from any crack).
    let gradMagK = length(gradK);
    let wallMask = smoothstep(0.0, 0.02, gradMagK);
    let shadeMul = 1.0 + (shade - 0.6) * 2.0 * (0.25 * uniforms.depth / 100.0) * wallMask;

    let darkened = src.rgb * mix(1.0, 0.35 + uniforms.brightness / 100.0 * 0.5, kC);
    let result = clamp(darkened * shadeMul, vec3<f32>(0.0), vec3<f32>(1.0));

    return vec4<f32>(result, src.a);
}

// CRT effect - faithful port of Python implementation
// Applies scanlines, lens warp, chromatic aberration, hue shift, saturation boost, and vignette

const PI : f32 = 3.14159265358979323846;
const TAU : f32 = 6.28318530717958647692;
const INV_THREE : f32 = 0.3333333333333333;

struct CRTParams {
    size : vec4<f32>,    // (width, height, channels, unused)
    motion : vec4<f32>,  // (time, speed, seed, unused)
    extra : vec4<f32>,   // (alpha, unused, unused, unused)
};

@group(0) @binding(0) var inputTex : texture_2d<f32>;
@group(0) @binding(1) var<storage, read_write> output_buffer : array<f32>;
@group(0) @binding(2) var<uniform> params : CRTParams;
@group(0) @binding(3) var<uniform> tileOffset : vec2<f32>;
@group(0) @binding(4) var<uniform> fullResolution : vec2<f32>;
@group(0) @binding(5) var<uniform> renderScale : f32;

fn as_u32(value : f32) -> u32 {
    return u32(max(value, 0.0));
}

fn clamp01(value : f32) -> f32 {
    return clamp(value, 0.0, 1.0);
}

fn random_scalar(seed : f32) -> f32 {
    return fract(sin(seed) * 43758.5453123);
}

fn simplex_random(time : f32, speed : f32) -> f32 {
    let angle : f32 = time * TAU;
    let z : f32 = cos(angle) * speed;
    let w : f32 = sin(angle) * speed;
    return fract(sin(z * 157.0 + w * 113.0) * 43758.5453);
}

fn freq_for_shape(base_freq : f32, width : f32, height : f32) -> vec2<f32> {
    let freq : f32 = max(base_freq, 1.0);
    let width_safe : f32 = max(width, 1.0);
    let height_safe : f32 = max(height, 1.0);

    if (abs(width_safe - height_safe) < 1e-5) {
        return vec2<f32>(freq, freq);
    }

    if (height_safe < width_safe) {
        let scaled : f32 = floor(freq * width_safe / height_safe);
        return vec2<f32>(freq, max(scaled, 1.0));
    }

    let scaled : f32 = floor(freq * height_safe / width_safe);
    return vec2<f32>(max(scaled, 1.0), freq);
}

fn normalized_sine(value : f32) -> f32 {
    return sin(value) * 0.5 + 0.5;
}

fn periodic_value(time : f32, value : f32) -> f32 {
    return normalized_sine((time - value) * TAU);
}

fn mod289_vec3(x : vec3<f32>) -> vec3<f32> {
    return x - floor(x * (1.0 / 289.0)) * 289.0;
}

fn mod289_vec4(x : vec4<f32>) -> vec4<f32> {
    return x - floor(x * (1.0 / 289.0)) * 289.0;
}

fn permute(x : vec4<f32>) -> vec4<f32> {
    return mod289_vec4(((x * 34.0) + 1.0) * x);
}

fn taylor_inv_sqrt(r : vec4<f32>) -> vec4<f32> {
    return 1.79284291400159 - 0.85373472095314 * r;
}

fn simplex_noise(v : vec3<f32>) -> f32 {
    let C : vec2<f32> = vec2<f32>(1.0 / 6.0, 1.0 / 3.0);
    let D : vec4<f32> = vec4<f32>(0.0, 0.5, 1.0, 2.0);

    let i0 : vec3<f32> = floor(v + dot(v, vec3<f32>(C.y)));
    let x0 : vec3<f32> = v - i0 + dot(i0, vec3<f32>(C.x));

    let step1 : vec3<f32> = step(vec3<f32>(x0.y, x0.z, x0.x), x0);
    let l : vec3<f32> = vec3<f32>(1.0) - step1;
    let i1 : vec3<f32> = min(step1, vec3<f32>(l.z, l.x, l.y));
    let i2 : vec3<f32> = max(step1, vec3<f32>(l.z, l.x, l.y));

    let x1 : vec3<f32> = x0 - i1 + vec3<f32>(C.x);
    let x2 : vec3<f32> = x0 - i2 + vec3<f32>(C.y);
    let x3 : vec3<f32> = x0 - vec3<f32>(D.y);

    let i = mod289_vec3(i0);
    let p = permute(
        permute(
            permute(i.z + vec4<f32>(0.0, i1.z, i2.z, 1.0))
            + i.y + vec4<f32>(0.0, i1.y, i2.y, 1.0)
        )
        + i.x + vec4<f32>(0.0, i1.x, i2.x, 1.0)
    );

    let n_ : f32 = 0.14285714285714285;
    let ns : vec3<f32> = n_ * vec3<f32>(D.w, D.y, D.z) - vec3<f32>(D.x, D.z, D.x);

    let j : vec4<f32> = p - 49.0 * floor(p * ns.z * ns.z);
    let x_ : vec4<f32> = floor(j * ns.z);
    let y_ : vec4<f32> = floor(j - 7.0 * x_);

    let x = x_ * ns.x + ns.y;
    let y = y_ * ns.x + ns.y;
    let h = 1.0 - abs(x) - abs(y);

    let b0 : vec4<f32> = vec4<f32>(x.x, x.y, y.x, y.y);
    let b1 : vec4<f32> = vec4<f32>(x.z, x.w, y.z, y.w);

    let s0 : vec4<f32> = floor(b0) * 2.0 + 1.0;
    let s1 : vec4<f32> = floor(b1) * 2.0 + 1.0;
    let sh : vec4<f32> = -step(h, vec4<f32>(0.0));

    let a0 : vec4<f32> = vec4<f32>(b0.x, b0.z, b0.y, b0.w)
        + vec4<f32>(s0.x, s0.z, s0.y, s0.w) * vec4<f32>(sh.x, sh.x, sh.y, sh.y);
    let a1 : vec4<f32> = vec4<f32>(b1.x, b1.z, b1.y, b1.w)
        + vec4<f32>(s1.x, s1.z, s1.y, s1.w) * vec4<f32>(sh.z, sh.z, sh.w, sh.w);

    let g0 : vec3<f32> = vec3<f32>(a0.x, a0.y, h.x);
    let g1 : vec3<f32> = vec3<f32>(a0.z, a0.w, h.y);
    let g2 : vec3<f32> = vec3<f32>(a1.x, a1.y, h.z);
    let g3 : vec3<f32> = vec3<f32>(a1.z, a1.w, h.w);

    let norm : vec4<f32> = taylor_inv_sqrt(vec4<f32>(
        dot(g0, g0),
        dot(g1, g1),
        dot(g2, g2),
        dot(g3, g3)
    ));

    let g0n : vec3<f32> = g0 * norm.x;
    let g1n : vec3<f32> = g1 * norm.y;
    let g2n : vec3<f32> = g2 * norm.z;
    let g3n : vec3<f32> = g3 * norm.w;

    let m0 : f32 = max(0.6 - dot(x0, x0), 0.0);
    let m1 : f32 = max(0.6 - dot(x1, x1), 0.0);
    let m2 : f32 = max(0.6 - dot(x2, x2), 0.0);
    let m3 : f32 = max(0.6 - dot(x3, x3), 0.0);

    let m0sq : f32 = m0 * m0;
    let m1sq : f32 = m1 * m1;
    let m2sq : f32 = m2 * m2;
    let m3sq : f32 = m3 * m3;

    return 42.0 * (
        m0sq * m0sq * dot(g0n, x0)
        + m1sq * m1sq * dot(g1n, x1)
        + m2sq * m2sq * dot(g2n, x2)
        + m3sq * m3sq * dot(g3n, x3)
    );
}

fn wrap_float(value : f32, limit : f32) -> f32 {
    if (limit <= 0.0) {
        return 0.0;
    }
    var result : f32 = value - floor(value / limit) * limit;
    if (result < 0.0) {
        result = result + limit;
    }
    return result;
}

fn singularity_mask(uv : vec2<f32>, width : f32, height : f32) -> f32 {
    if (width <= 0.0 || height <= 0.0) {
        return 0.0;
    }

    let delta : vec2<f32> = abs(uv - vec2<f32>(0.5, 0.5));
    let aspect : f32 = width / height;
    let scaled : vec2<f32> = vec2<f32>(delta.x * aspect, delta.y);
    let max_radius : f32 = length(vec2<f32>(aspect * 0.5, 0.5));
    if (max_radius <= 0.0) {
        return 0.0;
    }

    let normalized : f32 = clamp(length(scaled) / max_radius, 0.0, 1.0);
    let masked : f32 = sqrt(normalized);
    return pow(masked, 5.0);
}

fn animated_simplex_value(uv : vec2<f32>, time : f32, speed : f32) -> f32 {
    let angle : f32 = time * TAU;
    let z_base : f32 = cos(angle) * speed;
    let s : f32 = params.motion.z * 73.0;
    let base_seed : vec3<f32> = vec3<f32>(17.0 + s, 29.0 + s * 1.1, 47.0 + s * 0.7);
    let base_noise : f32 = simplex_noise(vec3<f32>(
        uv.x + base_seed.x,
        uv.y + base_seed.y,
        z_base + base_seed.z
    ));
    var value : f32 = clamp(base_noise * 0.5 + 0.5, 0.0, 1.0);

    if (speed != 0.0 && time != 0.0) {
        let time_seed : vec3<f32> = vec3<f32>(
            base_seed.x + 54.0,
            base_seed.y + 82.0,
            base_seed.z + 124.0
        );
        let time_noise : f32 = simplex_noise(vec3<f32>(
            uv.x + time_seed.x,
            uv.y + time_seed.y,
            time_seed.z
        ));
        let time_value : f32 = clamp(time_noise * 0.5 + 0.5, 0.0, 1.0);
        let scaled_time : f32 = periodic_value(time, time_value) * speed;
        value = clamp01(periodic_value(scaled_time, value));
    }

    return clamp01(value);
}

fn compute_lens_offsets(
    sample_pos : vec2<f32>,
    width : f32,
    height : f32,
    freq : vec2<f32>,
    time : f32,
    speed : f32,
    displacement : f32
) -> vec2<f32> {
    let width_safe : f32 = max(width, 1.0);
    let height_safe : f32 = max(height, 1.0);
    let freq_x : f32 = max(freq.y, 1.0);
    let freq_y : f32 = max(freq.x, 1.0);

    let wrapped_pos : vec2<f32> = vec2<f32>(
        wrap_float(sample_pos.x, width_safe),
        wrap_float(sample_pos.y, height_safe)
    );
    let uv : vec2<f32> = vec2<f32>(
        (wrapped_pos.x / width_safe) * freq_x,
        (wrapped_pos.y / height_safe) * freq_y
    );

    let noise_value : f32 = animated_simplex_value(uv, time, speed);

    let uv_centered : vec2<f32> = (wrapped_pos + vec2<f32>(0.5, 0.5)) / vec2<f32>(width_safe, height_safe);
    let mask : f32 = singularity_mask(uv_centered, width_safe, height_safe);
    let distortion : f32 = (noise_value * 2.0 - 1.0) * mask;
    let angle : f32 = distortion * TAU;

    let offsets : vec2<f32> = vec2<f32>(cos(angle), sin(angle))
        * displacement * vec2<f32>(width_safe, height_safe);
    return offsets;
}

// Value noise implementation
fn fade(value : f32) -> f32 {
    return value * value * (3.0 - 2.0 * value);
}

fn fade_vec3(v : vec3<f32>) -> vec3<f32> {
    return vec3<f32>(fade(v.x), fade(v.y), fade(v.z));
}

fn lerp(a : f32, b : f32, t : f32) -> f32 {
    return a + (b - a) * t;
}

fn hash3(coord : vec3<i32>, seed : f32) -> f32 {
    let base : vec3<f32> = vec3<f32>(coord);
    let dot_value : f32 = dot(base, vec3<f32>(12.9898, 78.233, 37.719)) + seed * 0.001;
    return fract(sin(dot_value) * 43758.5453);
}

fn value_noise_3d(coord : vec3<f32>, seed : f32) -> f32 {
    let cell : vec3<i32> = vec3<i32>(floor(coord));
    let local : vec3<f32> = fract(coord);
    let smooth_t : vec3<f32> = fade_vec3(local);

    let c000 : f32 = hash3(cell, seed);
    let c100 : f32 = hash3(cell + vec3<i32>(1, 0, 0), seed);
    let c010 : f32 = hash3(cell + vec3<i32>(0, 1, 0), seed);
    let c110 : f32 = hash3(cell + vec3<i32>(1, 1, 0), seed);
    let c001 : f32 = hash3(cell + vec3<i32>(0, 0, 1), seed);
    let c101 : f32 = hash3(cell + vec3<i32>(1, 0, 1), seed);
    let c011 : f32 = hash3(cell + vec3<i32>(0, 1, 1), seed);
    let c111 : f32 = hash3(cell + vec3<i32>(1, 1, 1), seed);

    let x00 : f32 = lerp(c000, c100, smooth_t.x);
    let x10 : f32 = lerp(c010, c110, smooth_t.x);
    let x01 : f32 = lerp(c001, c101, smooth_t.x);
    let x11 : f32 = lerp(c011, c111, smooth_t.x);
    let y0 : f32 = lerp(x00, x10, smooth_t.y);
    let y1 : f32 = lerp(x01, x11, smooth_t.y);
    return lerp(y0, y1, smooth_t.z);
}

// Singularity (radial distance from center)
fn compute_singularity(x : f32, y : f32, width : f32, height : f32) -> f32 {
    let center_x : f32 = width * 0.5;
    let center_y : f32 = height * 0.5;
    let dx : f32 = (x - center_x) / width;
    let dy : f32 = (y - center_y) / height;
    return length(vec2<f32>(dx, dy));
}

// Helper functions for color space conversion and adjustments
fn wrap_unit(value : f32) -> f32 {
    var wrapped : f32 = value - floor(value);
    if (wrapped < 0.0) {
        wrapped = wrapped + 1.0;
    }
    return wrapped;
}

fn blend_linear(a : f32, b : f32, t : f32) -> f32 {
    return mix(a, b, clamp(t, 0.0, 1.0));
}

fn blend_cosine(a : f32, b : f32, value : f32) -> f32 {
    let clamped : f32 = clamp(value, 0.0, 1.0);
    let weight : f32 = (1.0 - cos(clamped * PI)) * 0.5;
    return mix(a, b, weight);
}

fn clamp_index(value : f32, max_index : f32) -> u32 {
    if (max_index <= 0.0) {
        return 0u;
    }
    let clamped : f32 = clamp(value, 0.0, max_index);
    return u32(clamped);
}

fn rgb_to_hsv(rgb : vec3<f32>) -> vec3<f32> {
    let c_max : f32 = max(max(rgb.x, rgb.y), rgb.z);
    let c_min : f32 = min(min(rgb.x, rgb.y), rgb.z);
    let delta : f32 = c_max - c_min;

    var hue : f32 = 0.0;
    if (delta > 0.0) {
        if (c_max == rgb.x) {
            var segment : f32 = (rgb.y - rgb.z) / delta;
            if (segment < 0.0) {
                segment = segment + 6.0;
            }
            hue = segment;
        } else if (c_max == rgb.y) {
            hue = ((rgb.z - rgb.x) / delta) + 2.0;
        } else {
            hue = ((rgb.x - rgb.y) / delta) + 4.0;
        }
        hue = wrap_unit(hue / 6.0);
    }

    let saturation : f32 = select(0.0, delta / c_max, c_max != 0.0);
    return vec3<f32>(hue, saturation, c_max);
}

fn hsv_to_rgb(hsv : vec3<f32>) -> vec3<f32> {
    let h : f32 = hsv.x;
    let s : f32 = hsv.y;
    let v : f32 = hsv.z;

    let dh : f32 = h * 6.0;
    let r_comp : f32 = clamp01(abs(dh - 3.0) - 1.0);
    let g_comp : f32 = clamp01(-abs(dh - 2.0) + 2.0);
    let b_comp : f32 = clamp01(-abs(dh - 4.0) + 2.0);

    let one_minus_s : f32 = 1.0 - s;
    let sr : f32 = s * r_comp;
    let sg : f32 = s * g_comp;
    let sb : f32 = s * b_comp;

    let r : f32 = clamp01((one_minus_s + sr) * v);
    let g : f32 = clamp01((one_minus_s + sg) * v);
    let b : f32 = clamp01((one_minus_s + sb) * v);

    return vec3<f32>(r, g, b);
}

fn adjust_hue(color : vec3<f32>, amount : f32) -> vec3<f32> {
    var hsv : vec3<f32> = rgb_to_hsv(color);
    hsv.x = wrap_unit(hsv.x + amount);
    hsv.y = clamp01(hsv.y);
    hsv.z = clamp01(hsv.z);
    return clamp(vec3<f32>(hsv_to_rgb(hsv)), vec3<f32>(0.0), vec3<f32>(1.0));
}

fn adjust_saturation(color : vec3<f32>, amount : f32) -> vec3<f32> {
    var hsv : vec3<f32> = rgb_to_hsv(color);
    hsv.y = clamp01(hsv.y * amount);
    hsv.z = clamp01(hsv.z);
    return clamp(vec3<f32>(hsv_to_rgb(hsv)), vec3<f32>(0.0), vec3<f32>(1.0));
}

fn apply_vignette(value : f32, brightness : f32, mask : f32, alpha : f32) -> f32 {
    let edge_mix : f32 = mix(value, brightness, mask);
    return mix(value, edge_mix, clamp(alpha, 0.0, 1.0));
}

// Generate base scanline values (2x1 noise pattern)
fn get_scanline_base_values(time : f32, speed : f32) -> vec2<f32> {
    let time_scaled : f32 = time * speed * 0.1;
    let noise_seed : f32 = 19.37 + params.motion.z * 31.0;
    let noise0 : f32 = value_noise_3d(vec3<f32>(0.0, 0.0, time_scaled), noise_seed);
    let noise1 : f32 = value_noise_3d(vec3<f32>(1.0, 0.0, time_scaled), noise_seed);
    return vec2<f32>(noise0, noise1);
}

// Get interpolated scanline value for a given y coordinate
// The scanline pattern is based on Y position to create horizontal lines
fn get_scanline_value_interpolated(y : f32, height : f32, base_values : vec2<f32>) -> f32 {
    // Goal: ~500 bars for 1000px image = ~2px per bar, increased by 25% = 2.5px per bar
    // Each bar alternates between the 2 base values
    let pixels_per_bar : f32 = 2.5;
    let y_scaled : f32 = y / pixels_per_bar;
    let scanline_index : i32 = i32(floor(y_scaled)) % 2;

    return select(base_values.y, base_values.x, scanline_index == 0);
}

// Sample scanline with bilinear interpolation at fractional coordinates
fn sample_scanline_bilinear(sample_x : f32, sample_y : f32, width : f32, height : f32, base_values : vec2<f32>) -> f32 {
    // Wrap coordinates
    var wrapped_x : f32 = sample_x - floor(sample_x / width) * width;
    var wrapped_y : f32 = sample_y - floor(sample_y / height) * height;

    if (wrapped_x < 0.0) { wrapped_x = wrapped_x + width; }
    if (wrapped_y < 0.0) { wrapped_y = wrapped_y + height; }

    wrapped_x = clamp(wrapped_x, 0.0, width - 1.0);
    wrapped_y = clamp(wrapped_y, 0.0, height - 1.0);

    // Bilinear interpolation
    let x0 : f32 = floor(wrapped_x);
    let y0 : f32 = floor(wrapped_y);
    let x1 : f32 = min(x0 + 1.0, width - 1.0);
    let y1 : f32 = min(y0 + 1.0, height - 1.0);

    let x_fract : f32 = clamp(wrapped_x - x0, 0.0, 1.0);
    let y_fract : f32 = clamp(wrapped_y - y0, 0.0, 1.0);

    // Get scanline values at the 4 corners
    let val_x0_y0 : f32 = get_scanline_value_interpolated(y0, height, base_values);
    let val_x1_y0 : f32 = get_scanline_value_interpolated(y0, height, base_values);
    let val_x0_y1 : f32 = get_scanline_value_interpolated(y1, height, base_values);
    let val_x1_y1 : f32 = get_scanline_value_interpolated(y1, height, base_values);

    // Bilinear blend
    let val_y0 : f32 = mix(val_x0_y0, val_x1_y0, x_fract);
    let val_y1 : f32 = mix(val_x0_y1, val_x1_y1, x_fract);

    return mix(val_y0, val_y1, y_fract);
}

@compute @workgroup_size(8, 8, 1)
fn main(@builtin(global_invocation_id) gid : vec3<u32>) {
    let width : u32 = as_u32(params.size.x);
    let height : u32 = as_u32(params.size.y);
    if (gid.x >= width || gid.y >= height) {
        return;
    }

    let alphaVal : f32 = clamp(params.extra.x, 0.0, 1.0);
    if (alphaVal == 0.0) {
        let passthrough : vec4<f32> = textureLoad(inputTex, vec2<i32>(i32(gid.x), i32(gid.y)), 0);
        let pi : u32 = gid.y * width + gid.x;
        let bi : u32 = pi * 4u;
        output_buffer[bi + 0u] = passthrough.x;
        output_buffer[bi + 1u] = passthrough.y;
        output_buffer[bi + 2u] = passthrough.z;
        output_buffer[bi + 3u] = passthrough.w;
        return;
    }

    // Scale pixel-space dimensions so CRT patterns maintain visual size
    let rs : f32 = max(renderScale, 1.0);
    let fullRes : vec2<f32> = select(params.size.xy, fullResolution, fullResolution.x > 0.0);
    let width_f : f32 = max(fullRes.x / rs, 1.0);
    let height_f : f32 = max(fullRes.y / rs, 1.0);
    let time : f32 = params.motion.x;
    let speed : f32 = params.motion.y;
    let x : f32 = (f32(gid.x) + tileOffset.x) / rs;
    let y : f32 = (f32(gid.y) + tileOffset.y) / rs;

    let displacement : f32 = 0.0625;
    let freq : vec2<f32> = freq_for_shape(2.0, width_f, height_f);
    let base_offsets : vec2<f32> = compute_lens_offsets(
        vec2<f32>(x, y),
        width_f,
        height_f,
        freq,
        time,
        speed,
        displacement
    );

    // Step 2: Sample the procedural scanline texture at the WARPED coordinates.
    // This correctly applies the lens warp to the scanlines.
    let scanline_base : vec2<f32> = get_scanline_base_values(time, speed);
    let scan_value : f32 = sample_scanline_bilinear(x + base_offsets.x, y + base_offsets.y, width_f, height_f, scanline_base);

    // Step 3: Sample the input texture at the ORIGINAL, un-warped coordinates.
    let base_sample : vec4<f32> = textureLoad(inputTex, vec2<i32>(i32(gid.x), i32(gid.y)), 0);
    let base_color : vec3<f32> = base_sample.xyz;
    let alpha : f32 = base_sample.w;

    // Step 4: Blend the original input color with the warped scanlines.
    var color : vec3<f32> = mix(
        base_color,
        (base_color + scan_value) * scan_value,
        0.5
    );
    color = clamp(color, vec3<f32>(0.0), vec3<f32>(1.0));

    // Step 5: Chromatic aberration, hue shift, saturation, and vignette
    if (params.size.z >= 2.5) { // channels == 3
        let seed_base : f32 = 17.0 + params.motion.z * 73.0;
        let displacement_base : f32 = 0.0125 + random_scalar(seed_base + 0.37) * 0.00625;
        let simplex_value : f32 = random_scalar(seed_base + 0.73);
        let displacement_pixels : f32 = displacement_base * width_f * simplex_value;

        let singularity : f32 = compute_singularity(x, y, width_f, height_f);
        let aber_mask : f32 = pow(singularity, 3.0);
        let gradient : f32 = clamp(x / (width_f - 1.0), 0.0, 1.0);

        let hue_shift : f32 = random_scalar(seed_base + 1.91) * 0.25 - 0.125;

        // Red channel sample point (aberration shift)
        var red_x : f32 = min(x + displacement_pixels, width_f - 1.0);
        red_x = blend_linear(red_x, x, gradient);
        let red_sample_x : f32 = blend_cosine(x, red_x, aber_mask);

        let red_sample_global_x : f32 = red_sample_x * renderScale;
        let red_sample_local_x : f32 = red_sample_global_x - tileOffset.x;
        let red_base_col : vec3<f32> = textureLoad(inputTex, vec2<i32>(i32(red_sample_local_x), i32(gid.y)), 0).xyz;
        let red_offsets : vec2<f32> = compute_lens_offsets(
            vec2<f32>(red_sample_x, y),
            width_f,
            height_f,
            freq,
            time,
            speed,
            displacement
        );
        let red_scan_val : f32 = sample_scanline_bilinear(red_sample_x + red_offsets.x, y + red_offsets.y, width_f, height_f, scanline_base);
        let red_blended : vec3<f32> = mix(red_base_col, (red_base_col + red_scan_val) * red_scan_val, 0.5);

        // Green channel is the original computed color for this pixel
        let green_blended : vec3<f32> = color;

        // Blue channel sample point (aberration shift)
        var blue_x : f32 = max(x - displacement_pixels, 0.0);
        blue_x = blend_linear(x, blue_x, gradient);
        let blue_sample_x : f32 = blend_cosine(x, blue_x, aber_mask);

        let blue_sample_global_x : f32 = blue_sample_x * renderScale;
        let blue_sample_local_x : f32 = blue_sample_global_x - tileOffset.x;
        let blue_base_col : vec3<f32> = textureLoad(inputTex, vec2<i32>(i32(blue_sample_local_x), i32(gid.y)), 0).xyz;
        let blue_offsets : vec2<f32> = compute_lens_offsets(
            vec2<f32>(blue_sample_x, y),
            width_f,
            height_f,
            freq,
            time,
            speed,
            displacement
        );
        let blue_scan_val : f32 = sample_scanline_bilinear(blue_sample_x + blue_offsets.x, y + blue_offsets.y, width_f, height_f, scanline_base);
        let blue_blended : vec3<f32> = mix(blue_base_col, (blue_base_col + blue_scan_val) * blue_scan_val, 0.5);

        // Combine, applying hue shift to each component before assembling
        color = vec3<f32>(
            adjust_hue(red_blended, hue_shift).r,
            adjust_hue(green_blended, hue_shift).g,
            adjust_hue(blue_blended, hue_shift).b
        );

        // Restore original hue
        color = adjust_hue(color, -hue_shift);

        // Step 6: Saturation boost
        color = adjust_saturation(color, 1.125);

        // Step 7: Vignette
        let vignette_alpha : f32 = random_scalar(seed_base + 3.17) * 0.175;
        let vignette_mask : f32 = singularity;
        color.x = apply_vignette(color.x, 0.0, vignette_mask, vignette_alpha);
        color.y = apply_vignette(color.y, 0.0, vignette_mask, vignette_alpha);
        color.z = apply_vignette(color.z, 0.0, vignette_mask, vignette_alpha);
    }

    // Step 8: Normalize (contrast adjustment around mean)
    let local_mean : f32 = (color.x + color.y + color.z) * INV_THREE;
    color = clamp((color - local_mean) * 1.25 + local_mean, vec3<f32>(0.0), vec3<f32>(1.0));

    // Write output
    color = mix(base_color, color, alphaVal);
    let pixel_index : u32 = gid.y * width + gid.x;
    let base_index : u32 = pixel_index * 4u;
    output_buffer[base_index + 0u] = color.x;
    output_buffer[base_index + 1u] = color.y;
    output_buffer[base_index + 2u] = color.z;
    output_buffer[base_index + 3u] = base_sample.w;
}

// Degauss: simulate a CRT-style degaussing wobble by lens-warping
// each color channel independently. Based on the Python
// implementation in effects.degauss(), which repeatedly invokes
// lens_warp() with simplex noise-derived displacements.

const TAU : f32 = 6.28318530717958647692;

struct DegaussParams {
    dims0 : vec4<f32>, // (width, height, displacement, time)
    dims1 : vec4<f32>, // (speed, seed, direction, _pad)
    dims2 : vec4<f32>, // (tileOffset.x, tileOffset.y, fullRes.x, fullRes.y)
};

@group(0) @binding(0) var inputTex : texture_2d<f32>;
@group(0) @binding(1) var<storage, read_write> output_buffer : array<f32>;
@group(0) @binding(2) var<uniform> params : DegaussParams;

fn as_u32(value : f32) -> u32 {
    return u32(max(value, 0.0));
}

fn clamp01(value : f32) -> f32 {
    return clamp(value, 0.0, 1.0);
}

fn wrap_index(value : i32, limit : i32) -> i32 {
    if (limit <= 0) {
        return 0;
    }
    var wrapped : i32 = value % limit;
    if (wrapped < 0) {
        wrapped = wrapped + limit;
    }
    return wrapped;
}

fn wrap_float(value : f32, limit : f32) -> f32 {
    if (limit <= 0.0) {
        return 0.0;
    }
    var result : f32 = value - floor(value / limit) * limit;
    if (result < 0.0) {
        result = result + limit;
    }
    return result;
}

fn freq_for_shape(base_freq : f32, width : f32, height : f32) -> vec2<f32> {
    if (base_freq <= 0.0) {
        return vec2<f32>(1.0, 1.0);
    }

    if (abs(width - height) < 1e-5) {
        return vec2<f32>(base_freq, base_freq);
    }

    if (height < width && height > 0.0) {
        return vec2<f32>(base_freq, base_freq * width / height);
    }

    if (width > 0.0) {
        return vec2<f32>(base_freq * height / width, base_freq);
    }

    return vec2<f32>(base_freq, base_freq);
}

fn normalized_sine(value : f32) -> f32 {
    return sin(value) * 0.5 + 0.5;
}

fn periodic_value(time : f32, value : f32) -> f32 {
    return normalized_sine((time - value) * TAU);
}

fn mod289_vec3(x : vec3<f32>) -> vec3<f32> {
    return x - floor(x * (1.0 / 289.0)) * 289.0;
}

fn mod289_vec4(x : vec4<f32>) -> vec4<f32> {
    return x - floor(x * (1.0 / 289.0)) * 289.0;
}

fn permute(x : vec4<f32>) -> vec4<f32> {
    return mod289_vec4(((x * 34.0) + 1.0) * x);
}

fn taylor_inv_sqrt(r : vec4<f32>) -> vec4<f32> {
    return 1.79284291400159 - 0.85373472095314 * r;
}

fn simplex_noise(v : vec3<f32>) -> f32 {
    let C : vec2<f32> = vec2<f32>(1.0 / 6.0, 1.0 / 3.0);
    let D : vec4<f32> = vec4<f32>(0.0, 0.5, 1.0, 2.0);

    let i0 : vec3<f32> = floor(v + dot(v, vec3<f32>(C.y)));
    let x0 : vec3<f32> = v - i0 + dot(i0, vec3<f32>(C.x));

    let step1 : vec3<f32> = step(vec3<f32>(x0.y, x0.z, x0.x), x0);
    let l : vec3<f32> = vec3<f32>(1.0) - step1;
    let i1 : vec3<f32> = min(step1, vec3<f32>(l.z, l.x, l.y));
    let i2 : vec3<f32> = max(step1, vec3<f32>(l.z, l.x, l.y));

    let x1 : vec3<f32> = x0 - i1 + vec3<f32>(C.x);
    let x2 : vec3<f32> = x0 - i2 + vec3<f32>(C.y);
    let x3 : vec3<f32> = x0 - vec3<f32>(D.y);

    let i = mod289_vec3(i0);
    let p = permute(permute(permute(
        i.z + vec4<f32>(0.0, i1.z, i2.z, 1.0))
        + i.y + vec4<f32>(0.0, i1.y, i2.y, 1.0))
        + i.x + vec4<f32>(0.0, i1.x, i2.x, 1.0));

    let n_ : f32 = 0.14285714285714285;
    let ns : vec3<f32> = n_ * vec3<f32>(D.w, D.y, D.z) - vec3<f32>(D.x, D.z, D.x);

    let j : vec4<f32> = p - 49.0 * floor(p * ns.z * ns.z);
    let x_ : vec4<f32> = floor(j * ns.z);
    let y_ : vec4<f32> = floor(j - 7.0 * x_);

    let x = x_ * ns.x + ns.y;
    let y = y_ * ns.x + ns.y;
    let h = 1.0 - abs(x) - abs(y);

    let b0 : vec4<f32> = vec4<f32>(x.x, x.y, y.x, y.y);
    let b1 : vec4<f32> = vec4<f32>(x.z, x.w, y.z, y.w);

    let s0 : vec4<f32> = floor(b0) * 2.0 + 1.0;
    let s1 : vec4<f32> = floor(b1) * 2.0 + 1.0;
    let sh : vec4<f32> = -step(h, vec4<f32>(0.0));

    let a0 : vec4<f32> = vec4<f32>(b0.x, b0.z, b0.y, b0.w)
        + vec4<f32>(s0.x, s0.z, s0.y, s0.w) * vec4<f32>(sh.x, sh.x, sh.y, sh.y);
    let a1 : vec4<f32> = vec4<f32>(b1.x, b1.z, b1.y, b1.w)
        + vec4<f32>(s1.x, s1.z, s1.y, s1.w) * vec4<f32>(sh.z, sh.z, sh.w, sh.w);

    let g0 : vec3<f32> = vec3<f32>(a0.x, a0.y, h.x);
    let g1 : vec3<f32> = vec3<f32>(a0.z, a0.w, h.y);
    let g2 : vec3<f32> = vec3<f32>(a1.x, a1.y, h.z);
    let g3 : vec3<f32> = vec3<f32>(a1.z, a1.w, h.w);

    let norm : vec4<f32> = taylor_inv_sqrt(vec4<f32>(
        dot(g0, g0),
        dot(g1, g1),
        dot(g2, g2),
        dot(g3, g3)
    ));

    let g0n : vec3<f32> = g0 * norm.x;
    let g1n : vec3<f32> = g1 * norm.y;
    let g2n : vec3<f32> = g2 * norm.z;
    let g3n : vec3<f32> = g3 * norm.w;

    let m0 : f32 = max(0.6 - dot(x0, x0), 0.0);
    let m1 : f32 = max(0.6 - dot(x1, x1), 0.0);
    let m2 : f32 = max(0.6 - dot(x2, x2), 0.0);
    let m3 : f32 = max(0.6 - dot(x3, x3), 0.0);

    let m0sq : f32 = m0 * m0;
    let m1sq : f32 = m1 * m1;
    let m2sq : f32 = m2 * m2;
    let m3sq : f32 = m3 * m3;

    return 42.0 * (
        m0sq * m0sq * dot(g0n, x0)
        + m1sq * m1sq * dot(g1n, x1)
        + m2sq * m2sq * dot(g2n, x2)
        + m3sq * m3sq * dot(g3n, x3)
    );
}

fn compute_noise_value(
    coord : vec2<u32>,
    width : f32,
    height : f32,
    freq : vec2<f32>,
    time : f32,
    speed : f32,
    channel : u32,
) -> f32 {
    let width_safe : f32 = max(width, 1.0);
    let height_safe : f32 = max(height, 1.0);
    let freq_x : f32 = max(freq.y, 1.0);
    let freq_y : f32 = max(freq.x, 1.0);

    let uv : vec2<f32> = vec2<f32>(
        (f32(coord.x) / width_safe) * freq_x,
        (f32(coord.y) / height_safe) * freq_y
    );

    let angle : f32 = time * TAU;
    let z_base : f32 = cos(angle) * speed;
    let channel_offset : f32 = f32(channel) * 37.0;
    let seed_offset : f32 = f32(i32(params.dims1.y)) * 73.0;
    let base_seed : vec3<f32> = vec3<f32>(
        17.0 + channel_offset + seed_offset,
        29.0 + channel_offset * 1.3 + seed_offset * 1.1,
        47.0 + channel_offset * 1.7 + seed_offset * 0.7
    );

    let base_noise : f32 = simplex_noise(vec3<f32>(
        uv.x + base_seed.x,
        uv.y + base_seed.y,
        z_base + base_seed.z
    ));

    var value : f32 = clamp(base_noise * 0.5 + 0.5, 0.0, 1.0);

    if (speed != 0.0 && time != 0.0) {
        let time_seed : vec3<f32> = vec3<f32>(
            base_seed.x + 54.0,
            base_seed.y + 82.0,
            base_seed.z + 124.0
        );
        let time_noise : f32 = simplex_noise(vec3<f32>(
            uv.x + time_seed.x,
            uv.y + time_seed.y,
            time_seed.z
        ));
        let time_value : f32 = clamp(time_noise * 0.5 + 0.5, 0.0, 1.0);
        let scaled_time : f32 = periodic_value(time, time_value) * speed;
        value = clamp01(periodic_value(scaled_time, value));
    }

    return clamp01(value);
}

fn singularity_mask(uv : vec2<f32>, width : f32, height : f32) -> f32 {
    if (width <= 0.0 || height <= 0.0) {
        return 0.0;
    }

    let delta : vec2<f32> = abs(uv - vec2<f32>(0.5, 0.5));
    let aspect : f32 = width / height;
    let scaled : vec2<f32> = vec2<f32>(delta.x * aspect, delta.y);
    let max_radius : f32 = length(vec2<f32>(aspect * 0.5, 0.5));
    if (max_radius <= 0.0) {
        return 0.0;
    }

    let normalized : f32 = clamp(length(scaled) / max_radius, 0.0, 1.0);
    let masked : f32 = sqrt(normalized);
    return pow(masked, 5.0);
}

fn sample_bilinear(pos : vec2<f32>, width : f32, height : f32) -> vec4<f32> {
    let width_f : f32 = max(width, 1.0);
    let height_f : f32 = max(height, 1.0);

    let wrapped_x : f32 = wrap_float(pos.x, width_f);
    let wrapped_y : f32 = wrap_float(pos.y, height_f);

    var x0 : i32 = i32(floor(wrapped_x));
    var y0 : i32 = i32(floor(wrapped_y));

    let width_i : i32 = i32(max(width, 1.0));
    let height_i : i32 = i32(max(height, 1.0));

    if (x0 < 0) {
        x0 = 0;
    } else if (x0 >= width_i) {
        x0 = width_i - 1;
    }

    if (y0 < 0) {
        y0 = 0;
    } else if (y0 >= height_i) {
        y0 = height_i - 1;
    }

    let x1 : i32 = wrap_index(x0 + 1, width_i);
    let y1 : i32 = wrap_index(y0 + 1, height_i);

    let fx : f32 = clamp(wrapped_x - f32(x0), 0.0, 1.0);
    let fy : f32 = clamp(wrapped_y - f32(y0), 0.0, 1.0);

    let tex00 : vec4<f32> = textureLoad(inputTex, vec2<i32>(x0, y0), 0);
    let tex10 : vec4<f32> = textureLoad(inputTex, vec2<i32>(x1, y0), 0);
    let tex01 : vec4<f32> = textureLoad(inputTex, vec2<i32>(x0, y1), 0);
    let tex11 : vec4<f32> = textureLoad(inputTex, vec2<i32>(x1, y1), 0);

    let mix_x0 : vec4<f32> = mix(tex00, tex10, vec4<f32>(fx));
    let mix_x1 : vec4<f32> = mix(tex01, tex11, vec4<f32>(fx));
    return mix(mix_x0, mix_x1, vec4<f32>(fy));
}

fn warped_channel_value(
    channel : u32,
    coord : vec2<u32>,
    base_pos : vec2<f32>,
    width : f32,
    height : f32,
    tile_width : f32,
    tile_height : f32,
    freq : vec2<f32>,
    displacement : f32,
    mask : f32,
    time : f32,
    speed : f32,
) -> f32 {
    let noise_value : f32 = compute_noise_value(coord, width, height, freq, time, speed, channel);
    let centered : f32 = (noise_value * 2.0 - 1.0) * mask;
    let angle : f32 = centered * TAU;
    // Offset in GLOBAL pixel space (width/height are fullResolution dims):
    // every tile and the untiled reference must displace by the same
    // absolute print-pixel amount.
    var offset : vec2<f32> = vec2<f32>(cos(angle), sin(angle)) * displacement * vec2<f32>(width, height);

    // Rotate offset by direction
    let dirRad : f32 = params.dims1.z * TAU / 360.0;
    let dc : f32 = cos(dirRad);
    let ds : f32 = sin(dirRad);
    offset = vec2<f32>(offset.x * dc - offset.y * ds, offset.x * ds + offset.y * dc);
    // Sample the tile-local input texture with tile dims.
    let sample : vec4<f32> = sample_bilinear(base_pos + offset, tile_width, tile_height);

    switch channel {
        case 0u: {
            return clamp01(sample.x);
        }
        case 1u: {
            return clamp01(sample.y);
        }
        default: {
            return clamp01(sample.z);
        }
    }
}

fn store_pixel(base_index : u32, value : vec4<f32>) {
    output_buffer[base_index + 0u] = value.x;
    output_buffer[base_index + 1u] = value.y;
    output_buffer[base_index + 2u] = value.z;
    output_buffer[base_index + 3u] = value.w;
}

@compute @workgroup_size(8, 8, 1)
fn main(@builtin(global_invocation_id) gid : vec3<u32>) {
    let tile_w : u32 = as_u32(params.dims0.x);
    let tile_h : u32 = as_u32(params.dims0.y);
    if (gid.x >= tile_w || gid.y >= tile_h) {
        return;
    }

    let pixel_index : u32 = gid.y * tile_w + gid.x;
    let base_index : u32 = pixel_index * 4u;
    let coords : vec2<i32> = vec2<i32>(i32(gid.x), i32(gid.y));
    let original : vec4<f32> = textureLoad(inputTex, coords, 0);

    let displacement : f32 = params.dims0.z;
    if (displacement == 0.0) {
        store_pixel(base_index, original);
        return;
    }

    let tile_w_f : f32 = params.dims0.x;
    let tile_h_f : f32 = params.dims0.y;
    let tile_offset : vec2<f32> = params.dims2.xy;
    // fullResolution defaults to the tile size when not tiling (unity
    // invariant: tileOffset = 0 and fullRes == tile dims).
    let full_res : vec2<f32> = select(
        vec2<f32>(tile_w_f, tile_h_f),
        params.dims2.zw,
        params.dims2.z > 0.0
    );
    // Global pixel coords keep the noise field, mask and offset identical
    // in every tile and in the untiled reference.
    let global_px : vec2<f32> = vec2<f32>(f32(gid.x), f32(gid.y)) + tile_offset;
    let uv : vec2<f32> = (global_px + vec2<f32>(0.5, 0.5))
        / vec2<f32>(max(full_res.x, 1.0), max(full_res.y, 1.0));
    let mask : f32 = singularity_mask(uv, full_res.x, full_res.y);
    if (mask <= 0.0) {
        store_pixel(base_index, original);
        return;
    }

    let render_scale : f32 = full_res.x / max(tile_w_f, 1.0);
    let is_tiling : bool = render_scale > 1.01;
    // Tiling: bound the (global-pixel) offset to the 256px tile-overlap
    // budget, measured against the full-resolution dims the offset scales
    // with. Untiled: keep the historical clamp exactly (full_res == tile
    // dims there, so this is the same formula it always was).
    let max_offset_pixels : f32 = select(max(tile_w_f, tile_h_f), 256.0, is_tiling);
    let max_allowed_displacement : f32 = select(
        max_offset_pixels / max(tile_w_f, 1.0),
        max_offset_pixels / max(full_res.x, full_res.y),
        is_tiling
    );
    let clamped_displacement : f32 = min(displacement, max_allowed_displacement);

    let freq : vec2<f32> = freq_for_shape(2.0, full_res.x, full_res.y);
    let base_pos : vec2<f32> = vec2<f32>(f32(gid.x), f32(gid.y));
    let coord : vec2<u32> = vec2<u32>(global_px);

    let time : f32 = params.dims0.w;
    let speed : f32 = params.dims1.x;

    let red : f32 = warped_channel_value(
        0u,
        coord,
        base_pos,
        full_res.x,
        full_res.y,
        tile_w_f,
        tile_h_f,
        freq,
        clamped_displacement,
        mask,
        time,
        speed,
    );
    let green : f32 = warped_channel_value(
        1u,
        coord,
        base_pos,
        full_res.x,
        full_res.y,
        tile_w_f,
        tile_h_f,
        freq,
        clamped_displacement,
        mask,
        time,
        speed,
    );
    let blue : f32 = warped_channel_value(
        2u,
        coord,
        base_pos,
        full_res.x,
        full_res.y,
        tile_w_f,
        tile_h_f,
        freq,
        clamped_displacement,
        mask,
        time,
        speed,
    );
    let alpha : f32 = clamp01(original.w);

    store_pixel(base_index, vec4<f32>(red, green, blue, alpha));
}

/*
 * Derivative-based edge detection
 * Computes image derivatives to highlight edges
 */

struct Uniforms {
    amount: f32,
    renderScale: f32,
    _pad2: f32,
    _pad3: f32,
}

@group(0) @binding(0) var inputSampler: sampler;
@group(0) @binding(1) var inputTex: texture_2d<f32>;
@group(0) @binding(2) var<uniform> uniforms: Uniforms;

fn desaturate(color: vec3<f32>) -> vec3<f32> {
    let avg = 0.2126 * color.r + 0.7152 * color.g + 0.0722 * color.b;
    return vec3<f32>(avg);
}

@fragment
fn main(@builtin(position) pos: vec4<f32>) -> @location(0) vec4<f32> {
    let texSize = vec2<f32>(textureDimensions(inputTex));
    let uv = pos.xy / texSize;
    let texelSize = 1.0 / texSize;

    var radiusPixels = uniforms.amount * uniforms.renderScale;
    radiusPixels = min(radiusPixels, 256.0);

    let color = textureSample(inputTex, inputSampler, uv);

    // Sample neighbors for derivative calculation
    let center = desaturate(color.rgb);
    let right = desaturate(textureSample(inputTex, inputSampler, uv + vec2<f32>(radiusPixels, 0.0) * texelSize).rgb);
    let bottom = desaturate(textureSample(inputTex, inputSampler, uv + vec2<f32>(0.0, radiusPixels) * texelSize).rgb);

    // Compute derivatives
    let dx = center - right;
    let dy = center - bottom;

    let dist = distance(dx, dy) * 2.5;

    return vec4<f32>(clamp(color.rgb * dist, vec3<f32>(0.0), vec3<f32>(1.0)), color.a);
}

/*
 * Directional Blur - linear motion blur along a fixed angle. Averages a
 * fixed N-tap comb stepped along
 * dir = (cos(angle), sin(angle)), spanning blurDistance px total
 * (t ranges over [-blurDistance/2, blurDistance/2]). A per-pixel hash
 * shifts the whole tap comb by up to half a tap-step to hide banding
 * from the fixed tap count.
 */

struct Uniforms {
    angle: f32,
    blurDistance: f32,
}

@group(0) @binding(0) var inputSampler: sampler;
@group(0) @binding(1) var inputTex: texture_2d<f32>;
@group(0) @binding(2) var<uniform> uniforms: Uniforms;

const N: i32 = 32;

fn hash12(p: vec2<f32>) -> f32 {
    var p3 = fract(vec3<f32>(p.xyx) * 0.1031);
    p3 = p3 + dot(p3, p3.yzx + vec3<f32>(33.33));
    return fract((p3.x + p3.y) * p3.z);
}

@fragment
fn main(@builtin(position) pos: vec4<f32>) -> @location(0) vec4<f32> {
    let texSize = vec2<f32>(textureDimensions(inputTex));
    let a = radians(uniforms.angle);
    let dir = vec2<f32>(cos(a), sin(a));

    let tapStep = uniforms.blurDistance / f32(N - 1);
    let jitter = (hash12(pos.xy) - 0.5) * tapStep;

    var sum = vec4<f32>(0.0);
    for (var i: i32 = 0; i < N; i++) {
        let t = (f32(i) / f32(N - 1) - 0.5) * uniforms.blurDistance + jitter;
        let offset = dir * t;
        sum = sum + textureSample(inputTex, inputSampler, (pos.xy + offset) / texSize);
    }
    return sum / f32(N);
}

/*
 * Ordered dithering effect
 * Applies various dithering patterns and color palettes for retro aesthetics
 */

struct Uniforms {
    ditherType: i32,
    palette: i32,
    _pad0: i32,
    levels: i32,
    threshold: f32,
    matrixScale: f32,
    time: f32,
    mixAmount: f32,
    renderScale: f32,
    _pad1: f32,
    tileOffset: vec2<f32>,
}

@group(0) @binding(0) var inputSampler: sampler;
@group(0) @binding(1) var inputTex: texture_2d<f32>;
@group(0) @binding(2) var<uniform> uniforms: Uniforms;

// Dither type constants
const DITHER_BAYER_2X2: i32 = 0;
const DITHER_BAYER_4X4: i32 = 1;
const DITHER_BAYER_8X8: i32 = 2;
const DITHER_DOT: i32 = 3;
const DITHER_LINE: i32 = 4;
const DITHER_CROSSHATCH: i32 = 5;
const DITHER_NOISE: i32 = 6;
const DITHER_ERROR_DIFFUSION: i32 = 7;

// Palette constants
const PALETTE_INPUT: i32 = 0;
const PALETTE_MONOCHROME: i32 = 1;
const PALETTE_DOT_MATRIX_GREEN: i32 = 2;
const PALETTE_AMBER: i32 = 3;
const PALETTE_PICO8: i32 = 4;
const PALETTE_C64: i32 = 5;
const PALETTE_CGA: i32 = 6;
const PALETTE_ZX_SPECTRUM: i32 = 7;
const PALETTE_APPLE_II: i32 = 8;
const PALETTE_EGA: i32 = 9;

// Bayer 2x2 matrix values
fn getBayer2x2(x: i32, y: i32) -> f32 {
    let bayer = array<f32, 4>(
        0.0/4.0, 2.0/4.0,
        3.0/4.0, 1.0/4.0
    );
    let idx = (y & 1) * 2 + (x & 1);
    return bayer[idx];
}

// Bayer 4x4 matrix values
fn getBayer4x4(x: i32, y: i32) -> f32 {
    let bayer = array<f32, 16>(
         0.0/16.0,  8.0/16.0,  2.0/16.0, 10.0/16.0,
        12.0/16.0,  4.0/16.0, 14.0/16.0,  6.0/16.0,
         3.0/16.0, 11.0/16.0,  1.0/16.0,  9.0/16.0,
        15.0/16.0,  7.0/16.0, 13.0/16.0,  5.0/16.0
    );
    let idx = (y & 3) * 4 + (x & 3);
    return bayer[idx];
}

// 8x8 Bayer matrix - using lookup for correctness
fn getBayer8x8(x: i32, y: i32) -> f32 {
    let xm = x & 7;
    let ym = y & 7;

    // Standard 8x8 ordered dither matrix
    let bayer8 = array<f32, 64>(
         0.0/64.0, 32.0/64.0,  8.0/64.0, 40.0/64.0,  2.0/64.0, 34.0/64.0, 10.0/64.0, 42.0/64.0,
        48.0/64.0, 16.0/64.0, 56.0/64.0, 24.0/64.0, 50.0/64.0, 18.0/64.0, 58.0/64.0, 26.0/64.0,
        12.0/64.0, 44.0/64.0,  4.0/64.0, 36.0/64.0, 14.0/64.0, 46.0/64.0,  6.0/64.0, 38.0/64.0,
        60.0/64.0, 28.0/64.0, 52.0/64.0, 20.0/64.0, 62.0/64.0, 30.0/64.0, 54.0/64.0, 22.0/64.0,
         3.0/64.0, 35.0/64.0, 11.0/64.0, 43.0/64.0,  1.0/64.0, 33.0/64.0,  9.0/64.0, 41.0/64.0,
        51.0/64.0, 19.0/64.0, 59.0/64.0, 27.0/64.0, 49.0/64.0, 17.0/64.0, 57.0/64.0, 25.0/64.0,
        15.0/64.0, 47.0/64.0,  7.0/64.0, 39.0/64.0, 13.0/64.0, 45.0/64.0,  5.0/64.0, 37.0/64.0,
        63.0/64.0, 31.0/64.0, 55.0/64.0, 23.0/64.0, 61.0/64.0, 29.0/64.0, 53.0/64.0, 21.0/64.0
    );

    return bayer8[ym * 8 + xm];
}

// PCG PRNG
fn pcg(seed: vec3<u32>) -> vec3<u32> {
    var v = seed * 1664525u + 1013904223u;
    v.x = v.x + v.y * v.z;
    v.y = v.y + v.z * v.x;
    v.z = v.z + v.x * v.y;
    v = v ^ (v >> vec3<u32>(16u));
    v.x = v.x + v.y * v.z;
    v.y = v.y + v.z * v.x;
    v.z = v.z + v.x * v.y;
    return v;
}

// Hash function for noise dithering
fn hash(p: vec2<f32>) -> f32 {
    let v = pcg(vec3<u32>(
        u32(select(-p.x * 2.0 + 1.0, p.x * 2.0, p.x >= 0.0)),
        u32(select(-p.y * 2.0 + 1.0, p.y * 2.0, p.y >= 0.0)),
        0u
    ));
    return f32(v.x) / f32(0xffffffffu);
}

// Dot pattern dithering
fn dotPattern(uv: vec2<f32>, scale: f32) -> f32 {
    let p = uv * scale;
    let d = length(fract(p) - 0.5);
    return smoothstep(0.5, 0.0, d);
}

// Line pattern dithering
fn linePattern(uv: vec2<f32>, scale: f32) -> f32 {
    let p = uv.y * scale;
    return abs(fract(p) - 0.5) * 2.0;
}

// Crosshatch pattern
fn crosshatchPattern(uv: vec2<f32>, scale: f32) -> f32 {
    let p = uv * scale;
    let line1 = abs(fract(p.x + p.y) - 0.5) * 2.0;
    let line2 = abs(fract(p.x - p.y) - 0.5) * 2.0;
    return min(line1, line2);
}

// Get dither threshold based on type and position
// matrixScale determines how many screen pixels each matrix cell covers
// e.g., scale=1 means 1:1, scale=2 means each cell is 2x2 screen pixels
fn getDitherThreshold(pixelCoord: vec2<f32>, ditherType: i32, scale: f32, time: f32) -> f32 {
    // Scale the pixel coordinate - larger scale = bigger pattern cells
    let scaledCoord = floor(pixelCoord / scale);
    let x = i32(scaledCoord.x);
    let y = i32(scaledCoord.y);

    if (ditherType == DITHER_BAYER_2X2) {
        return getBayer2x2(x, y);
    } else if (ditherType == DITHER_BAYER_4X4) {
        return getBayer4x4(x, y);
    } else if (ditherType == DITHER_BAYER_8X8) {
        return getBayer8x8(x, y);
    } else if (ditherType == DITHER_DOT) {
        // Dot pattern with 8-pixel base, scaled (larger scale = bigger dots)
        return dotPattern(pixelCoord, 1.0 / (8.0 * scale));
    } else if (ditherType == DITHER_LINE) {
        // Line pattern with 8-pixel base
        return linePattern(pixelCoord, 1.0 / (8.0 * scale));
    } else if (ditherType == DITHER_CROSSHATCH) {
        // Crosshatch pattern with 8-pixel base
        return crosshatchPattern(pixelCoord, 1.0 / (8.0 * scale));
    } else if (ditherType == DITHER_NOISE) {
        // Noise pattern: scale determines block size
        return hash(scaledCoord + time * 0.001);
    }

    return 0.5;
}


// Quantize color to specified levels with dithering
fn quantizeWithDither(color: vec3<f32>, levels: f32, ditherValue: f32, thresh: f32) -> vec3<f32> {
    let adjustedDither = ditherValue - 0.5 + thresh;
    let dithered = color + adjustedDither / levels;
    return floor(dithered * levels) / (levels - 1.0);
}

// Color distance in RGB space
fn colorDistance(a: vec3<f32>, b: vec3<f32>) -> f32 {
    let diff = a - b;
    return dot(diff, diff);
}

