// Find closest color in palette
fn findClosestPaletteColor(color: vec3<f32>, paletteType: i32) -> vec3<f32> {
    if (paletteType == PALETTE_MONOCHROME) {
        let luma = dot(color, vec3<f32>(0.299, 0.587, 0.114));
        if (luma > 0.5) {
            return vec3<f32>(1.0);
        } else {
            return vec3<f32>(0.0);
        }
    }

    var closest = vec3<f32>(0.0);
    var minDist = 999999.0;
    var count = 16;

    if (paletteType == PALETTE_DOT_MATRIX_GREEN || paletteType == PALETTE_AMBER || paletteType == PALETTE_CGA) {
        count = 4;
    } else if (paletteType == PALETTE_ZX_SPECTRUM) {
        count = 15;
    }

    for (var i = 0; i < count; i = i + 1) {
        var palColor = vec3<f32>(0.0);

        if (paletteType == PALETTE_DOT_MATRIX_GREEN) {
            palColor = getDotMatrixGreen(i);
        } else if (paletteType == PALETTE_AMBER) {
            palColor = getAmber(i);
        } else if (paletteType == PALETTE_PICO8) {
            palColor = getPico8(i);
        } else if (paletteType == PALETTE_C64) {
            palColor = getC64(i);
        } else if (paletteType == PALETTE_CGA) {
            palColor = getCGA(i);
        } else if (paletteType == PALETTE_ZX_SPECTRUM) {
            palColor = getZXSpectrum(i);
        } else if (paletteType == PALETTE_APPLE_II) {
            palColor = getAppleII(i);
        } else if (paletteType == PALETTE_EGA) {
            palColor = getEGA(i);
        }

        let dist = colorDistance(color, palColor);
        if (dist < minDist) {
            minDist = dist;
            closest = palColor;
        }
    }

    return closest;
}

// Apply palette-based dithering
fn ditherWithPalette(color: vec3<f32>, ditherValue: f32, thresh: f32, paletteType: i32) -> vec3<f32> {
    let dithered = clamp(color + (ditherValue - 0.5 + thresh) * 0.25, vec3<f32>(0.0), vec3<f32>(1.0));
    return findClosestPaletteColor(dithered, paletteType);
}

// Error diffusion (Floyd-Steinberg). Fragments cannot share sequential state,
// so each fragment re-simulates the raster scan over its containing block of
// FS_BLOCK x FS_BLOCK diffusion cells, extended by a burn-in apron on the
// left and top so the error state entering the block is driven by the
// neighboring image content; without it the severed error flow at block
// edges reads as a square grid. Three details keep the block structure
// statistically invisible: the apron length is jittered per block (flat
// regions otherwise phase-lock to the shared scan origin), apron rows are
// seeded with hash noise of typical steady-state magnitude (an all-zero
// start is atypical and phase-aligned), and rows extend FS_RPAD cells past
// the block's right edge (the right column otherwise never receives its
// down-left error taps). A cell covers matrixScale screen pixels, like the
// ordered pattern cells.
const FS_BLOCK: i32 = 4;
const FS_APRON_MIN: i32 = 4;
const FS_APRON_MAX: i32 = 11;
const FS_RPAD: i32 = 2;
// error row width: block + max apron + right pad + one left pad cell
const FS_ERR_W: i32 = FS_BLOCK + FS_APRON_MAX + FS_RPAD + 1;

// Quantize for error diffusion: nearest palette color, or nearest of
// `levels` evenly spaced per-channel levels when palette == input.
fn fsQuantize(v: vec3<f32>, paletteType: i32, levels: f32) -> vec3<f32> {
    if (paletteType == PALETTE_INPUT) {
        let maxLevel = levels - 1.0;
        // floor(x + 0.5) instead of round(): GLSL leaves round-half direction
        // implementation-defined while WGSL rounds half to even, and the
        // chaotic error feedback amplifies any halfway-tie mismatch.
        return floor(v * maxLevel + 0.5) / maxLevel;
    }
    return findClosestPaletteColor(v, paletteType);
}

// Working-value scale shared by the threshold bias and the block seeds,
// matching the ordered paths' scaling at their neutral dither value.
fn fsScale(paletteType: i32, levels: f32) -> f32 {
    if (paletteType == PALETTE_INPUT) {
        return 1.0 / levels;
    }
    return 0.25;
}

// Per-block, per-lane noise in [-0.5, 0.5) for seeding error state.
// Lanes 0..FS_ERR_W-1 seed the incoming error row; higher lanes seed each
// scan row's right-flowing error.
fn fsSeedNoise(blockOrigin: vec2<i32>, lane: i32) -> vec3<f32> {
    let v = pcg(vec3<u32>(u32(blockOrigin.x + 1), u32(blockOrigin.y + 1), u32(lane + 1)));
    return vec3<f32>(v) / f32(0xffffffffu) - 0.5;
}

// Source color for a diffusion cell: its center pixel, clamped to the tile.
fn fsFetchCell(cell: vec2<i32>, cellSize: f32, texSize: vec2<i32>) -> vec3<f32> {
    let pGlobal = (vec2<f32>(cell) + 0.5) * cellSize;
    var pLocal = vec2<i32>(floor(pGlobal)) - vec2<i32>(uniforms.tileOffset);
    pLocal = clamp(pLocal, vec2<i32>(0), texSize - 1);
    return textureLoad(inputTex, pLocal, 0).rgb;
}

fn errorDiffusion(pixelCoord: vec2<f32>, fragCoord: vec2<f32>, cellSize: f32, paletteType: i32, levelsInt: i32, thresh: f32) -> vec3<f32> {
    let texSize = vec2<i32>(textureDimensions(inputTex));
    let levels = f32(levelsInt);
    let cell = vec2<i32>(floor(pixelCoord / cellSize));
    let blockOrigin = (cell / FS_BLOCK) * FS_BLOCK;
    let lx = cell.x - blockOrigin.x;
    let ly = cell.y - blockOrigin.y;

    // Per-block scan-start jitter
    let jitterHash = pcg(vec3<u32>(u32(blockOrigin.x + 1), u32(blockOrigin.y + 1), 0x517cc1b7u));
    let apronX = FS_APRON_MIN + i32(jitterHash.x % u32(FS_APRON_MAX - FS_APRON_MIN + 1));
    let apronY = FS_APRON_MIN + i32(jitterHash.y % u32(FS_APRON_MAX - FS_APRON_MIN + 1));

    let stepScale = fsScale(paletteType, levels);
    let bias = vec3<f32>(thresh * stepScale);
    // Single in-place error row; array index = cell x + FS_APRON_MAX + 1 so
    // every index is a compile-time constant once the inner loop unrolls,
    // letting the row state live in registers instead of scratch memory.
    // Jitter is applied by masking cells left of -apronX instead of by
    // changing the loop bounds.
    var errRow: array<vec3<f32>, 18>;
    for (var i = 0; i < FS_ERR_W; i = i + 1) {
        errRow[i] = fsSeedNoise(blockOrigin, i) * stepScale;
    }

    var carried = vec3<f32>(0.0);
    for (var r = -FS_APRON_MAX; r <= ly; r = r + 1) {
        if (r < -apronY) {
            continue;
        }
        let lastRow = r == ly;
        var rightErr = fsSeedNoise(blockOrigin, FS_ERR_W + FS_APRON_MAX + r) * stepScale;
        var diag = vec3<f32>(0.0);
        for (var c = -FS_APRON_MAX; c < FS_BLOCK + FS_RPAD; c = c + 1) {
            if (c >= -apronX && !(lastRow && c >= lx)) {
                let src = fsFetchCell(blockOrigin + vec2<i32>(c, r), cellSize, texSize);
                let v = clamp(src + errRow[c + FS_APRON_MAX + 1] + rightErr + bias, vec3<f32>(0.0), vec3<f32>(1.0));
                let err = v - fsQuantize(v, paletteType, levels);
                rightErr = err * (7.0 / 16.0);
                errRow[c + FS_APRON_MAX] = errRow[c + FS_APRON_MAX] + err * (3.0 / 16.0);
                errRow[c + FS_APRON_MAX + 1] = diag + err * (5.0 / 16.0);
                diag = err * (1.0 / 16.0);
            }
        }
        if (lastRow) {
            // Incoming error for this fragment's own cell; keep the array
            // read on constant indices so it stays register-resident.
            var incoming = errRow[FS_APRON_MAX + 1];
            if (lx == 1) { incoming = errRow[FS_APRON_MAX + 2]; }
            if (lx == 2) { incoming = errRow[FS_APRON_MAX + 3]; }
            if (lx == 3) { incoming = errRow[FS_APRON_MAX + 4]; }
            carried = incoming + rightErr;
        }
    }

    // This fragment's own pixel, carrying the diffused error so per-pixel
    // detail survives when a cell spans multiple pixels
    let own = clamp(vec2<i32>(fragCoord), vec2<i32>(0), texSize - 1);
    let src = textureLoad(inputTex, own, 0).rgb;
    let v = clamp(src + carried + bias, vec3<f32>(0.0), vec3<f32>(1.0));
    return fsQuantize(v, paletteType, levels);
}

@fragment
fn main(@builtin(position) pos: vec4<f32>) -> @location(0) vec4<f32> {
    let texSize = vec2<f32>(textureDimensions(inputTex));
    let uv = pos.xy / texSize;

    var color = textureSample(inputTex, inputSampler, uv);

    // Use global pixel coordinate for dither pattern so it aligns across tiles
    let globalCoord = pos.xy + uniforms.tileOffset;

    var result: vec3<f32>;

    if (uniforms.ditherType == DITHER_ERROR_DIFFUSION) {
        result = errorDiffusion(globalCoord, pos.xy, uniforms.matrixScale * uniforms.renderScale, uniforms.palette, uniforms.levels, uniforms.threshold);
    } else {
        // Get dither threshold for current pixel
        let ditherValue = getDitherThreshold(globalCoord, uniforms.ditherType, uniforms.matrixScale * uniforms.renderScale, uniforms.time);

        if (uniforms.palette == PALETTE_INPUT) {
            // Per-channel quantization to the chosen number of levels
            result = quantizeWithDither(color.rgb, f32(uniforms.levels), ditherValue, uniforms.threshold);
        } else {
            // Use palette-based dithering
            result = ditherWithPalette(color.rgb, ditherValue, uniforms.threshold, uniforms.palette);
        }
    }

    // Blend between original input and dithered result
    result = mix(color.rgb, result, uniforms.mixAmount);

    return vec4<f32>(result, color.a);
}

/*
 * Edge detection with multiple kernels, sizes, and blend modes
 */

struct Uniforms {
    kernel: f32,
    size: f32,
    blend: f32,
    invert: f32,
    channel: f32,
    threshold: f32,
    amount: f32,
    mixAmt: f32,
    level: f32,
    contourSide: f32,
    renderScale: f32,
}

@group(0) @binding(0) var inputSampler: sampler;
@group(0) @binding(1) var inputTex: texture_2d<f32>;
@group(0) @binding(2) var<uniform> u: Uniforms;

const LUMA = vec3<f32>(0.2126, 0.7152, 0.0722);

fn getWeight(dx: i32, dy: i32, kernelType: i32) -> f32 {
    if (dx == 0 && dy == 0) { return 0.0; }

    if (kernelType == 0) {
        // fine: cardinal neighbors only (cross Laplacian)
        if (dx == 0 || dy == 0) { return -1.0; }
        return 0.0;
    } else {
        // bold: all neighbors equally
        return -1.0;
    }
}

fn applyBlend(edge: vec4<f32>, orig: vec4<f32>, mode: i32) -> vec4<f32> {
    if (mode == 0) { return min(orig + edge, vec4<f32>(1.0)); }                        // add
    if (mode == 1) { return min(orig, edge); }                                          // darken
    if (mode == 2) { return abs(orig - edge); }                                         // difference
    if (mode == 3) { return min(orig / max(1.0 - edge, vec4<f32>(0.001)), vec4<f32>(1.0)); } // dodge
    if (mode == 4) { return max(orig, edge); }                                          // lighten
    if (mode == 5) { return orig * edge; }                                              // multiply
    if (mode == 7) {                                                                     // overlay
        let r = select(1.0 - 2.0 * (1.0 - orig.r) * (1.0 - edge.r), 2.0 * orig.r * edge.r, orig.r < 0.5);
        let g = select(1.0 - 2.0 * (1.0 - orig.g) * (1.0 - edge.g), 2.0 * orig.g * edge.g, orig.g < 0.5);
        let b = select(1.0 - 2.0 * (1.0 - orig.b) * (1.0 - edge.b), 2.0 * orig.b * edge.b, orig.b < 0.5);
        return vec4<f32>(r, g, b, orig.a);
    }
    if (mode == 8) { return 1.0 - (1.0 - orig) * (1.0 - edge); }                      // screen
    return edge;                                                                         // normal (6)
}

// Contour: mark only the selected side of a level crossing against the 4
// cardinal neighbors (Trace Contour). Returns a binary vec3:
// 1.0 = background (white), 0.0 = contour line (dark).
fn contourConv(uv: vec2<f32>, texelSize: vec2<f32>, centerRGB: vec3<f32>, lvl: f32, useLuma: bool, upperSide: bool) -> vec3<f32> {
    let northRGB = textureSample(inputTex, inputSampler, uv + vec2<f32>(0.0,  1.0) * texelSize).rgb;
    let southRGB = textureSample(inputTex, inputSampler, uv + vec2<f32>(0.0, -1.0) * texelSize).rgb;
    let eastRGB  = textureSample(inputTex, inputSampler, uv + vec2<f32>( 1.0, 0.0) * texelSize).rgb;
    let westRGB  = textureSample(inputTex, inputSampler, uv + vec2<f32>(-1.0, 0.0) * texelSize).rgb;

    if (useLuma) {
        let centerL = dot(centerRGB, LUMA);
        var centerOnSide = centerL < lvl;
        if (upperSide) {
            centerOnSide = centerL >= lvl;
        }
        let crossing = centerOnSide && select(
            dot(northRGB, LUMA) >= lvl || dot(southRGB, LUMA) >= lvl ||
            dot(eastRGB, LUMA) >= lvl  || dot(westRGB, LUMA) >= lvl,
            dot(northRGB, LUMA) < lvl || dot(southRGB, LUMA) < lvl ||
            dot(eastRGB, LUMA) < lvl  || dot(westRGB, LUMA) < lvl,
            upperSide
        );
        return vec3<f32>(select(1.0, 0.0, crossing));
    }

    var centerOnSide = centerRGB < vec3<f32>(lvl);
    if (upperSide) {
        centerOnSide = centerRGB >= vec3<f32>(lvl);
    }

    let crossR = centerOnSide.r && select(
        northRGB.r >= lvl || southRGB.r >= lvl || eastRGB.r >= lvl || westRGB.r >= lvl,
        northRGB.r < lvl || southRGB.r < lvl || eastRGB.r < lvl || westRGB.r < lvl,
        upperSide);
    let crossG = centerOnSide.g && select(
        northRGB.g >= lvl || southRGB.g >= lvl || eastRGB.g >= lvl || westRGB.g >= lvl,
        northRGB.g < lvl || southRGB.g < lvl || eastRGB.g < lvl || westRGB.g < lvl,
        upperSide);
    let crossB = centerOnSide.b && select(
        northRGB.b >= lvl || southRGB.b >= lvl || eastRGB.b >= lvl || westRGB.b >= lvl,
        northRGB.b < lvl || southRGB.b < lvl || eastRGB.b < lvl || westRGB.b < lvl,
        upperSide);

    return vec3<f32>(
        select(1.0, 0.0, crossR),
        select(1.0, 0.0, crossG),
        select(1.0, 0.0, crossB)
    );
}

@fragment
fn main(@builtin(position) pos: vec4<f32>) -> @location(0) vec4<f32> {
    let texSize = vec2<f32>(textureDimensions(inputTex));
    let uv = pos.xy / texSize;
    let texelSize = 1.0 / texSize;

    let origColor = textureSample(inputTex, inputSampler, uv);

    let kernelType = i32(u.kernel);
    // Match edge.glsl: scale the kernel radius by renderScale so edge width
    // stays consistent under tiled / large-format (non-unit-scale) export.
    let radius = min(i32((u.size + 1.0) * u.renderScale), 256);
    let blendMode = i32(u.blend);
    let doInvert = u.invert > 0.5;
    let useLuma = u.channel > 0.5;

    // Convolution
    var conv = vec3<f32>(0.0);
    var centerWeight: f32 = 0.0;

    if (kernelType == 2) {
        // Contour: level-crossing trace, not a weighted convolution.
        conv = contourConv(uv, texelSize, origColor.rgb, u.level / 100.0, useLuma, u.contourSide > 0.5);
    } else {
        for (var dy = -3; dy <= 3; dy = dy + 1) {
            for (var dx = -3; dx <= 3; dx = dx + 1) {
                if (abs(dx) > radius || abs(dy) > radius) { continue; }
                if (dx == 0 && dy == 0) { continue; }

                let w = getWeight(dx, dy, kernelType);
                if (w == 0.0) { continue; }

                let offset = vec2<f32>(f32(dx), f32(dy)) * texelSize;
                let s = textureSample(inputTex, inputSampler, uv + offset).rgb;

                if (useLuma) {
                    conv = conv + vec3<f32>(dot(s, LUMA)) * w;
                } else {
                    conv = conv + s * w;
                }

                centerWeight = centerWeight - w;
            }
        }

        // Center sample
        var centerSample = origColor.rgb;
        if (useLuma) {
            centerSample = vec3<f32>(dot(centerSample, LUMA));
        }
        conv = conv + centerSample * centerWeight;
    }

    // Amount
    conv = conv * (u.amount / 50.0);
    conv = clamp(conv, vec3<f32>(0.0), vec3<f32>(1.0));

    // Threshold (before invert so it measures actual edge strength)
    if (u.threshold > 0.0) {
        let thresh = u.threshold / 100.0;
        var edge: f32;
        if (useLuma) {
            edge = conv.r;
        } else {
            edge = dot(conv, LUMA);
        }
        let mask = smoothstep(thresh - 0.01, thresh + 0.01, edge);
        conv = conv * mask;
    }

    // Invert
    if (doInvert) {
        conv = 1.0 - conv;
    }

    // Blend
    let edgeColor = vec4<f32>(conv, origColor.a);
    let blended = applyBlend(edgeColor, origColor, blendMode);

    // Mix
    let m = u.mixAmt / 100.0;
    return vec4<f32>(mix(origColor.rgb, blended.rgb, m), origColor.a);
}

/*
 * Emboss relief with two explicit visual contracts. This is the mathematical
 * match of emboss.glsl; see that file and help.md for the derivation.
 */

// STYLE is a runtime-injected module-scope const (injectDefines); Dawn/naga
// constant-fold the style dispatch so only the active path survives compilation.
struct Uniforms {
    amount: f32,
    angle: f32,
    height: f32,
    colorAmount: f32,
    tileOffset: vec2<f32>,
    fullResolution: vec2<f32>,
    renderScale: f32,
}

@group(0) @binding(0) var inputSampler: sampler;
@group(0) @binding(1) var inputTex: texture_2d<f32>;
@group(0) @binding(2) var<uniform> uniforms: Uniforms;

const LUMA = vec3<f32>(0.2126, 0.7152, 0.0722);

// Tile-space sample: globalUV is a UV against the full (possibly tiled)
// output canvas; map it back into this pass's local input texture using
// fullResolution/tileOffset, matching emboss.glsl's sampleGlobal().
fn sampleGlobal(globalUV: vec2<f32>) -> vec3<f32> {
    let texSize = vec2<f32>(textureDimensions(inputTex));
    var fullDims: vec2<f32> = texSize;
    if (uniforms.fullResolution.x > 0.0) { fullDims = uniforms.fullResolution; }
    let localUV = (globalUV * fullDims - uniforms.tileOffset) / texSize;
    return textureSample(inputTex, inputSampler, localUV).rgb;
}

fn colorDefaultEmboss(uv: vec2<f32>, texelSize: vec2<f32>) -> vec3<f32> {
    let kernel = array<f32, 9>(-2.0, -1.0, 0.0, -1.0, 1.0, 1.0, 0.0, 1.0, 2.0);

    // COLOR_DEFAULT_EXACT_BEGIN
    // Copied from the pre-angle/height shader: literal offsets and arithmetic
    // order intentionally stay intact so defaults never depend on trig folding.
    let offsets = array<vec2<f32>, 9>(
        vec2<f32>(-texelSize.x, -texelSize.y),
        vec2<f32>(0.0, -texelSize.y),
        vec2<f32>(texelSize.x, -texelSize.y),
        vec2<f32>(-texelSize.x, 0.0),
        vec2<f32>(0.0, 0.0),
        vec2<f32>(texelSize.x, 0.0),
        vec2<f32>(-texelSize.x, texelSize.y),
        vec2<f32>(0.0, texelSize.y),
        vec2<f32>(texelSize.x, texelSize.y)
    );
    let texSize = vec2<f32>(textureDimensions(inputTex));
    var fullDims: vec2<f32> = texSize;
    if (uniforms.fullResolution.x > 0.0) { fullDims = uniforms.fullResolution; }

    var conv = vec3<f32>(0.0);
    for (var i = 0; i < 9; i = i + 1) {
        let g = uv + offsets[i] * uniforms.amount * uniforms.renderScale;
        let sample = textureSample(inputTex, inputSampler, (g * fullDims - uniforms.tileOffset) / texSize).rgb;
        conv = conv + sample * kernel[i];
    }
    // COLOR_DEFAULT_EXACT_END
    return conv;
}

fn colorGeneralEmboss(uv: vec2<f32>, texelSize: vec2<f32>) -> vec3<f32> {
    let kernel = array<f32, 9>(-2.0, -1.0, 0.0, -1.0, 1.0, 1.0, 0.0, 1.0, 2.0);
    let baseOffsetsPx = array<vec2<f32>, 9>(
        vec2<f32>(-1.0, -1.0), vec2<f32>(0.0, -1.0), vec2<f32>(1.0, -1.0),
        vec2<f32>(-1.0,  0.0), vec2<f32>(0.0,  0.0), vec2<f32>(1.0,  0.0),
        vec2<f32>(-1.0,  1.0), vec2<f32>(0.0,  1.0), vec2<f32>(1.0,  1.0)
    );
    let theta = radians(uniforms.angle - 135.0);
    let ct = cos(theta);
    let st = sin(theta);

    let texSize = vec2<f32>(textureDimensions(inputTex));
    var fullDims: vec2<f32> = texSize;
    if (uniforms.fullResolution.x > 0.0) { fullDims = uniforms.fullResolution; }

    var conv = vec3<f32>(0.0);
    for (var i = 0; i < 9; i = i + 1) {
        let basePx = baseOffsetsPx[i];
        let rotatedPx = vec2<f32>(ct * basePx.x + st * basePx.y, -st * basePx.x + ct * basePx.y) * uniforms.height;
        let offsetUV = rotatedPx * texelSize * uniforms.amount * uniforms.renderScale;
        let g = uv + offsetUV;
        let sample = textureSample(inputTex, inputSampler, (g * fullDims - uniforms.tileOffset) / texSize).rgb;
        conv = conv + sample * kernel[i];
    }
    return conv;
}

fn grayEmboss(uv: vec2<f32>, centerRGB: vec3<f32>) -> vec3<f32> {
    let theta = radians(uniforms.angle);
    // This fixed sample delta matches GLSL because it is not position-derived.
    let direction = vec2<f32>(cos(theta), sin(theta));
    let offsetUV = direction * (uniforms.height * uniforms.renderScale) / uniforms.fullResolution;
    let positiveLuma = dot(sampleGlobal(uv + offsetUV), LUMA);
    let negativeLuma = dot(sampleGlobal(uv - offsetUV), LUMA);
    let signedEdge = positiveLuma - negativeLuma;
    let edgeMagnitude = abs(signedEdge);
    let relief = 0.5 + 0.5 * signedEdge;
    let centerLuma = dot(centerRGB, LUMA);
    let sourceChroma = centerRGB - vec3<f32>(centerLuma);
    let tracedColor = sourceChroma * edgeMagnitude * clamp(uniforms.colorAmount / 100.0, 0.0, 1.0);
    return vec3<f32>(relief) + tracedColor;
}

@fragment
fn main(@builtin(position) pos: vec4<f32>) -> @location(0) vec4<f32> {
    let texSize = vec2<f32>(textureDimensions(inputTex));
    let globalCoord = pos.xy + uniforms.tileOffset;
    let globalUV = globalCoord / uniforms.fullResolution;
    let texelSize = 1.0 / texSize;
    let uv = pos.xy / texSize;
    let origColor = textureSample(inputTex, inputSampler, uv);
    let fullFrame = all(uniforms.tileOffset == vec2<f32>(0.0)) && all(uniforms.fullResolution == texSize);
    var colorTexelSize = 1.0 / uniforms.fullResolution;
    if (fullFrame) { colorTexelSize = texelSize; }

    var result: vec3<f32>;
    if (STYLE == 0) {
        if (uniforms.angle == 135.0 && uniforms.height == 1.0) {
            result = colorDefaultEmboss(globalUV, colorTexelSize);
        } else {
            result = colorGeneralEmboss(globalUV, colorTexelSize);
        }
    } else {
        result = grayEmboss(globalUV, origColor.rgb);
    }
    return vec4<f32>(clamp(result, vec3<f32>(0.0), vec3<f32>(1.0)), origColor.a);
}

/*
 * Extrude - classic block/pyramid extrusion toward the viewer.
 * See extrude.glsl for the full algorithm, occlusion-ordering, and
 * shading derivation - this is a 1:1 port.
 *
 * Tile-aware, mirroring extrude.glsl: P = pos.xy + uniforms.tileOffset is
 * the GLOBAL fragment position (GLSL's gl_FragCoord.xy + tileOffset), and
 * imgCenter = fullResolution*0.5 is the GLOBAL image center (falling back
 * to the local textureDimensions(inputTex) size when fullResolution is
 * unset, i.e. uniforms.fullResolution.x <= 0.0 - matching filter/texture's
 * guard). Every downstream position in this file (cellC, faceCenter,
 * apex, the pyramid corners, localPos, ...) is derived from P and
 * imgCenter, so fixing just those two root values keeps the whole
 * grid/occlusion/apex geometry globally consistent across tile
 * boundaries. toSampleUV converts a GLOBAL position back to a tile-LOCAL
 * sample UV (subtract uniforms.tileOffset, divide by the local
 * textureDimensions(inputTex)) before ever touching inputTex, matching
 * GLSL's toSampleUV(globalPixelPos) = (globalPixelPos - tileOffset) /
 * resolution - inputTex only ever holds this tile's own crop, so every
 * texture read must land back in tile-local space even though the
 * geometry that produced it is computed globally. Default (non-tiled)
 * rendering has uniforms.tileOffset = (0,0) and uniforms.fullResolution
 * == textureDimensions(inputTex), so P and imgCenter reduce to their
 * pre-tiling values exactly (pos.xy and texSize*0.5) - byte-identical
 * output, zero regression by construction. No centerY-style flip is
 * needed for imgCenter itself (fullResolution*0.5 is symmetric
 * regardless of Y convention).
 *
 * TOP_SIGN = 1.0 here, SAME as GLSL: the two backends were verified
 * only as mutually consistent with each other - bit-exact
 * cross-backend parity, nothing more. This algorithm is
 * flip-symmetric (center-anchored grid; a global Y-mirror is a
 * self-consistent relabeling), so that parity CANNOT determine the
 * absolute orientation: which way is visually "up" for the side
 * shading was never independently verified, and it is cosmetically
 * irrelevant here - left/right facets are unaffected, and a global
 * flip would swap top/bottom facet shading only. Effects with
 * genuinely Y-asymmetric semantics must NOT inherit an orientation
 * claim from this file; they need their own discriminating test (see
 * spinBlur's centerY fix for the pattern).
 */

struct Uniforms {
    size: f32,
    depth: f32,
    solidFront: i32,
    tileOffset: vec2<f32>,
    fullResolution: vec2<f32>,
}

@group(0) @binding(0) var inputSampler: sampler;
@group(0) @binding(1) var inputTex: texture_2d<f32>;
@group(0) @binding(2) var<uniform> uniforms: Uniforms;

const TOP_SIGN: f32 = 1.0;

const SHADE_TOP: f32 = 0.8875;
const SHADE_BOTTOM: f32 = 0.6625;
const SHADE_LEFT: f32 = 0.969856;
const SHADE_RIGHT: f32 = 0.580144;

const EPS: f32 = 1e-4;

fn hash12(p: vec2<f32>) -> f32 {
    var p3 = fract(vec3<f32>(p.xyx) * 0.1031);
    p3 = p3 + dot(p3, p3.yzx + vec3<f32>(33.33));
    return fract((p3.x + p3.y) * p3.z);
}

fn lum(c: vec3<f32>) -> f32 {
    return dot(c, vec3<f32>(0.2126, 0.7152, 0.0722));
}

fn toSampleUV(globalPixelPos: vec2<f32>, texSize: vec2<f32>) -> vec2<f32> {
    return clamp((globalPixelPos - uniforms.tileOffset) / texSize, vec2<f32>(0.0), vec2<f32>(1.0));
}

// Small 3x3 average centered on a cell, spaced at size*0.25 so the full
// sample footprint (size*0.5 wide) stays inside the cell's own bounds.
//
// textureSampleLevel (explicit LOD 0), not textureSample: this function
// is called from the occlusion-walk loop in main(), whose iteration
// count is genuinely per-fragment data-dependent (it breaks at
// `t >= distToCenter`, and distToCenter varies with each fragment's own
// position) - non-uniform control flow, which disqualifies plain
// textureSample (it needs implicit derivatives / uniform control flow).
// inputTex is a non-mipmapped render-target-style texture, so LOD 0 is
// exactly GLSL's texture() here. Mirrors synth/remap's WGSL port.
fn cellAvgColor3x3(centerPx: vec2<f32>, texSize: vec2<f32>) -> vec4<f32> {
    let sp = uniforms.size * 0.25;
    var sum = vec4<f32>(0.0);
    for (var j = -1; j <= 1; j++) {
        for (var i = -1; i <= 1; i++) {
            let p = centerPx + vec2<f32>(f32(i), f32(j)) * sp;
            sum = sum + textureSampleLevel(inputTex, inputSampler, toSampleUV(p, texSize), 0.0);
        }
    }
    return sum * (1.0 / 9.0);
}

fn cellHeight(cellC: vec2<f32>, cellIdxF: vec2<f32>, texSize: vec2<f32>) -> f32 {
    if (DEPTH_SOURCE == 1) {
        // Hash the cell index directly - both backends' fragment
        // positions are content-Y-up in this runtime (see header), so
        // the center-anchored cell indices are already identical
        // cross-backend for the same visual cell.
        return hash12(cellIdxF);
    }
    return lum(cellAvgColor3x3(cellC, texSize).rgb);
}

// Barycentric coords of p in triangle (a,b,c); w (.z) corresponds to c.
// Returns a component < -1.0 (impossible for a real barycentric coord)
// when the triangle is degenerate, so callers can treat it as a miss
// with the same ">= -EPS" containment test used for real triangles.
fn baryWeights(p: vec2<f32>, a: vec2<f32>, b: vec2<f32>, c: vec2<f32>) -> vec3<f32> {
    let v0 = b - a;
    let v1 = c - a;
    let v2 = p - a;
    let d00 = dot(v0, v0);
    let d01 = dot(v0, v1);
    let d11 = dot(v1, v1);
    let d20 = dot(v2, v0);
    let d21 = dot(v2, v1);
    let denom = d00 * d11 - d01 * d01;
    if (abs(denom) < 1e-8) {
        return vec3<f32>(-2.0);
    }
    let v = (d11 * d20 - d01 * d21) / denom;
    let w = (d00 * d21 - d01 * d20) / denom;
    let u = 1.0 - v - w;
    return vec3<f32>(u, v, w);
}

// -1 if P misses all 4 faces; else 0=bottom,1=right,2=top,3=left (fixed
// per-triangle identity, independent of where apex actually projects to
// - see extrude.glsl's FACE COLOR / SHADING note).
fn pyramidTriHit(P: vec2<f32>, cellC: vec2<f32>, apex: vec2<f32>, halfCell: vec2<f32>) -> i32 {
    let topC = cellC + TOP_SIGN * vec2<f32>(0.0, halfCell.y);
    let botC = cellC - TOP_SIGN * vec2<f32>(0.0, halfCell.y);
    let leftX = cellC.x - halfCell.x;
    let rightX = cellC.x + halfCell.x;
    let Cbl = vec2<f32>(leftX, botC.y);
    let Cbr = vec2<f32>(rightX, botC.y);
    let Ctr = vec2<f32>(rightX, topC.y);
    let Ctl = vec2<f32>(leftX, topC.y);

    var bc = baryWeights(P, Cbl, Cbr, apex);
    if (bc.x >= -EPS && bc.y >= -EPS && bc.z >= -EPS) { return 0; }
    bc = baryWeights(P, Cbr, Ctr, apex);
    if (bc.x >= -EPS && bc.y >= -EPS && bc.z >= -EPS) { return 1; }
    bc = baryWeights(P, Ctr, Ctl, apex);
    if (bc.x >= -EPS && bc.y >= -EPS && bc.z >= -EPS) { return 2; }
    bc = baryWeights(P, Ctl, Cbl, apex);
    if (bc.x >= -EPS && bc.y >= -EPS && bc.z >= -EPS) { return 3; }
    return -1;
}

// Which side of the cell (relative to its center) a footprint pixel is
// nearest to - a simple X-pattern quadrant split.
fn sideShade(P: vec2<f32>, cellC: vec2<f32>) -> f32 {
    let d = P - cellC;
    let dyUp = d.y * TOP_SIGN;
    if (abs(d.x) > abs(dyUp)) {
        return select(SHADE_LEFT, SHADE_RIGHT, d.x > 0.0);
    }
    return select(SHADE_BOTTOM, SHADE_TOP, dyUp > 0.0);
}

@fragment
fn main(@builtin(position) pos: vec4<f32>) -> @location(0) vec4<f32> {
    let texSize = vec2<f32>(textureDimensions(inputTex));
    var globalRes: vec2<f32> = texSize;
    if (uniforms.fullResolution.x > 0.0) { globalRes = uniforms.fullResolution; }
    let P = pos.xy + uniforms.tileOffset;
    let imgCenter = globalRes * 0.5;
    let halfCell = vec2<f32>(uniforms.size * 0.5);

    let toCenter = imgCenter - P;
    let distToCenter = length(toCenter);
    var stepDir = vec2<f32>(0.0);
    if (distToCenter > 0.0) {
        stepDir = toCenter / distToCenter;
    }

    var bestPriority: f32 = -1.0e9;
    var bestCenterPx = vec2<f32>(0.0);
    var bestS: f32 = 1.0;
    var bestIsTop = false;
    var bestTri: i32 = -1;
    var found = false;

    for (var i = 0; i < 6; i++) {
        let t = min(f32(i) * uniforms.size, distToCenter);
        let samplePos = P + stepDir * t;
        // Center-anchored grid - see extrude.glsl's header for why
        // (cross-backend origin-anchoring mismatch).
        let cellIdxF = floor((samplePos - imgCenter) / uniforms.size);
        let cellC = imgCenter + (cellIdxF + 0.5) * uniforms.size;

        let h = cellHeight(cellC, cellIdxF, texSize);
        let s = 1.0 + h * (uniforms.depth / 100.0) * 0.4;

        if (EXTRUDE_TYPE == 1) {
            // pyramids: priority is s alone (no flat-top tier).
            let apex = imgCenter + (cellC - imgCenter) * s;
            let tri = pyramidTriHit(P, cellC, apex, halfCell);
            if (tri >= 0 && s > bestPriority) {
                bestPriority = s;
                bestCenterPx = cellC;
                bestS = s;
                bestTri = tri;
                found = true;
            }
        } else {
            // blocks: top face is the footprint scaled by s about the
            // image center; side band is the rest of the un-scaled
            // footprint (only ever true for i==0 - see header).
            let faceCenter = imgCenter + (cellC - imgCenter) * s;
            let faceHalf = halfCell * s;
            let topHit = all(abs(P - faceCenter) <= faceHalf);
            let sideHit = (!topHit) && all(abs(P - cellC) <= halfCell);
            if (topHit || sideHit) {
                let priority = s + select(0.0, 1000.0, topHit);
                if (priority > bestPriority) {
                    bestPriority = priority;
                    bestCenterPx = cellC;
                    bestS = s;
                    bestIsTop = topHit;
                    found = true;
                }
            }
        }

        if (t >= distToCenter) { break; }
    }

    var outColor: vec4<f32>;
    if (!found) {
        // Safety net: P's own cell should always produce a hit by
        // construction (see extrude.glsl header); this only guards
        // float-precision edge cases exactly on a cell boundary, so it
        // never shows up as a visible crack.
        let cellC = imgCenter + (floor((P - imgCenter) / uniforms.size) + 0.5) * uniforms.size;
        outColor = cellAvgColor3x3(cellC, texSize);
    } else if (EXTRUDE_TYPE == 1) {
        let apex = imgCenter + (bestCenterPx - imgCenter) * bestS;
        let topC = bestCenterPx + TOP_SIGN * vec2<f32>(0.0, halfCell.y);
        let botC = bestCenterPx - TOP_SIGN * vec2<f32>(0.0, halfCell.y);
        let leftX = bestCenterPx.x - halfCell.x;
        let rightX = bestCenterPx.x + halfCell.x;
        let Cbl = vec2<f32>(leftX, botC.y);
        let Cbr = vec2<f32>(rightX, botC.y);
        let Ctr = vec2<f32>(rightX, topC.y);
        let Ctl = vec2<f32>(leftX, topC.y);

        var Ci: vec2<f32>;
        var Ci1: vec2<f32>;
        var shadeConst: f32;
        if (bestTri == 0) { Ci = Cbl; Ci1 = Cbr; shadeConst = SHADE_BOTTOM; }
        else if (bestTri == 1) { Ci = Cbr; Ci1 = Ctr; shadeConst = SHADE_RIGHT; }
        else if (bestTri == 2) { Ci = Ctr; Ci1 = Ctl; shadeConst = SHADE_TOP; }
        else { Ci = Ctl; Ci1 = Cbl; shadeConst = SHADE_LEFT; }

        let bc = baryWeights(P, Ci, Ci1, apex);
        let apexW = clamp(bc.z, 0.0, 1.0);

        var baseColor: vec4<f32>;
        if (uniforms.solidFront != 0) {
            baseColor = cellAvgColor3x3(bestCenterPx, texSize);
        } else {
            let localPos = bc.x * Ci + bc.y * Ci1 + bc.z * bestCenterPx;
            // Explicit LOD - see cellAvgColor3x3's comment (same non-uniform-control-flow reasoning).
            baseColor = textureSampleLevel(inputTex, inputSampler, toSampleUV(localPos, texSize), 0.0);
        }
        let shade = mix(1.0, shadeConst, apexW);
        outColor = vec4<f32>(baseColor.rgb * shade, baseColor.a);
    } else if (bestIsTop) {
        if (uniforms.solidFront != 0) {
            outColor = cellAvgColor3x3(bestCenterPx, texSize);
        } else {
            let localPos = imgCenter + (P - imgCenter) / bestS;
            // Explicit LOD - see cellAvgColor3x3's comment (same non-uniform-control-flow reasoning).
            outColor = textureSampleLevel(inputTex, inputSampler, toSampleUV(localPos, texSize), 0.0);
        }
    } else {
        let shade = sideShade(P, bestCenterPx);
        let meanColor = cellAvgColor3x3(bestCenterPx, texSize);
        outColor = vec4<f32>(meanColor.rgb * shade, meanColor.a);
    }

    return outColor;
}

/*
 * Simple copy/blit shader - copies input to output unchanged.
 * Used for feedback texture updates.
 */

@group(0) @binding(0) var inputSampler: sampler;
@group(0) @binding(1) var inputTex: texture_2d<f32>;

@fragment
fn main(@builtin(position) pos: vec4<f32>) -> @location(0) vec4<f32> {
    let dims = vec2<f32>(textureDimensions(inputTex, 0));
    let uv = pos.xy / dims;
    return textureSample(inputTex, inputSampler, uv);
}

/*
 * Feedback post-processing shader (WGSL).
 * Offers blend modes alongside hue, distortion, and brightness controls for the accumulated feedback buffer.
 */

struct Uniforms {
    resolution: vec2<f32>,
    time: f32,
    seed: i32,
    scaleAmt: f32,
    rotation: f32,
    blendMode: i32,
    mixAmt: f32,
    hueRotation: f32,
    intensity: f32,
    distortion: f32,
    aberration: f32,
    refractAAmt: f32,
    refractBAmt: f32,
    refractADir: f32,
    refractBDir: f32,
    resetState: i32,
}

@group(0) @binding(0) var<uniform> uniforms: Uniforms;
@group(0) @binding(1) var texSampler: sampler;
@group(0) @binding(2) var inputTex: texture_2d<f32>;
@group(0) @binding(3) var selfTex: texture_2d<f32>;

const PI: f32 = 3.14159265359;

// Floored modulo (matches GLSL mod behavior for negative values)
fn floorMod(x: f32, y: f32) -> f32 {
    return x - y * floor(x / y);
}
const TAU: f32 = 6.28318530718;

fn map(value: f32, inMin: f32, inMax: f32, outMin: f32, outMax: f32) -> f32 {
    return outMin + (outMax - outMin) * (value - inMin) / (inMax - inMin);
}

fn blendOverlay(a: f32, b: f32) -> f32 {
    if (a < 0.5) {
        return 2.0 * a * b;
    } else {
        return 1.0 - 2.0 * (1.0 - a) * (1.0 - b);
    }
}

fn blendSoftLight(base: f32, blend: f32) -> f32 {
    if (blend < 0.5) {
        return 2.0 * base * blend + base * base * (1.0 - 2.0 * blend);
    } else {
        return sqrt(base) * (2.0 * blend - 1.0) + 2.0 * base * (1.0 - blend);
    }
}

fn blend(color1: vec4<f32>, color2: vec4<f32>, mode: i32, factor: f32) -> vec4<f32> {
    var middle: vec4<f32>;
    let amt = map(uniforms.mixAmt, 0.0, 100.0, 0.0, 1.0);

    switch (mode) {
        case 0: { // add
            middle = min(color1 + color2, vec4<f32>(1.0));
        }
        case 2: { // color burn
            if (all(color2 == vec4<f32>(0.0))) {
                middle = color2;
            } else {
                middle = max(1.0 - ((1.0 - color1) / color2), vec4<f32>(0.0));
            }
        }
        case 3: { // color dodge
            if (all(color2 == vec4<f32>(1.0))) {
                middle = color2;
            } else {
                middle = min(color1 / (1.0 - color2), vec4<f32>(1.0));
            }
        }
        case 4: { // darken
            middle = min(color1, color2);
        }
        case 5: { // difference
            middle = abs(color1 - color2);
            middle.a = max(color1.a, color2.a);
        }
        case 6: { // exclusion
            middle = color1 + color2 - 2.0 * color1 * color2;
            middle.a = max(color1.a, color2.a);
        }
        case 7: { // glow
            if (all(color2 == vec4<f32>(1.0))) {
                middle = color2;
            } else {
                middle = min(color1 * color1 / (1.0 - color2), vec4<f32>(1.0));
            }
        }
        case 8: { // hard light
            middle = vec4<f32>(
                blendOverlay(color2.r, color1.r),
                blendOverlay(color2.g, color1.g),
                blendOverlay(color2.b, color1.b),
                mix(color1.a, color2.a, 0.5)
            );
        }
        case 9: { // lighten
            middle = max(color1, color2);
        }
        case 10: { // mix
            middle = mix(color1, color2, 0.5);
        }
        case 11: { // multiply
            middle = color1 * color2;
        }
        case 12: { // negation
            middle = vec4<f32>(1.0) - abs(vec4<f32>(1.0) - color1 - color2);
            middle.a = max(color1.a, color2.a);
        }
        case 13: { // overlay
            middle = vec4<f32>(
                blendOverlay(color1.r, color2.r),
                blendOverlay(color1.g, color2.g),
                blendOverlay(color1.b, color2.b),
                mix(color1.a, color2.a, 0.5)
            );
        }
        case 14: { // phoenix
            middle = min(color1, color2) - max(color1, color2) + vec4<f32>(1.0);
        }
        case 15: { // reflect
            if (all(color1 == vec4<f32>(1.0))) {
                middle = color1;
            } else {
                middle = min(color2 * color2 / (1.0 - color1), vec4<f32>(1.0));
            }
        }
        case 16: { // screen
            middle = 1.0 - ((1.0 - color1) * (1.0 - color2));
        }
        case 17: { // soft light
            middle = vec4<f32>(
                blendSoftLight(color1.r, color2.r),
                blendSoftLight(color1.g, color2.g),
                blendSoftLight(color1.b, color2.b),
                mix(color1.a, color2.a, 0.5)
            );
        }
        case 18: { // subtract
            middle = max(color1 + color2 - 1.0, vec4<f32>(0.0));
        }
        default: {
            middle = mix(color1, color2, 0.5);
        }
    }

    var color: vec4<f32>;
    if (factor == 0.5) {
        color = middle;
    } else if (factor < 0.5) {
        let f = map(amt, 0.0, 0.5, 0.0, 1.0);
        color = mix(color1, middle, f);
    } else {
        let f = map(amt, 0.5, 1.0, 0.0, 1.0);
        color = mix(middle, color2, f);
    }

    return color;
}

fn brightnessContrast(color: vec3<f32>) -> vec3<f32> {
    let bright = map(uniforms.intensity * 0.1, -100.0, 100.0, -0.5, 0.5);
    let cont = map(uniforms.intensity * 0.1, -100.0, 100.0, 0.5, 1.5);
    return (color - 0.5) * cont + 0.5 + bright;
}

fn rotate2D(st_in: vec2<f32>, rot: f32) -> vec2<f32> {
    let aspectRatio = uniforms.resolution.x / uniforms.resolution.y;
    var st = st_in;
    st.x *= aspectRatio;
    let rotNorm = map(rot, 0.0, 360.0, 0.0, 2.0);
    let angle = rotNorm * PI;
    st -= vec2<f32>(0.5 * aspectRatio, 0.5);
    let c = cos(angle);
    let s = sin(angle);
    st = mat2x2<f32>(c, -s, s, c) * st;
    st += vec2<f32>(0.5 * aspectRatio, 0.5);
    st.x /= aspectRatio;
    return st;
}

fn hsv2rgb(hsv: vec3<f32>) -> vec3<f32> {
    let h = fract(hsv.x);
    let s = hsv.y;
    let v = hsv.z;

    let c = v * s;
    let x = c * (1.0 - abs((h * 6.0) % 2.0 - 1.0));
    let m = v - c;

    var rgb: vec3<f32>;
    if (h < 1.0/6.0) {
        rgb = vec3<f32>(c, x, 0.0);
    } else if (h < 2.0/6.0) {
        rgb = vec3<f32>(x, c, 0.0);
    } else if (h < 3.0/6.0) {
        rgb = vec3<f32>(0.0, c, x);
    } else if (h < 4.0/6.0) {
        rgb = vec3<f32>(0.0, x, c);
    } else if (h < 5.0/6.0) {
        rgb = vec3<f32>(x, 0.0, c);
    } else {
        rgb = vec3<f32>(c, 0.0, x);
    }

    return rgb + vec3<f32>(m);
}

fn rgb2hsv(rgb: vec3<f32>) -> vec3<f32> {
    let maxC = max(rgb.r, max(rgb.g, rgb.b));
    let minC = min(rgb.r, min(rgb.g, rgb.b));
    let delta = maxC - minC;

    var h = 0.0;
    if (delta != 0.0) {
        if (maxC == rgb.r) {
            h = floorMod((rgb.g - rgb.b) / delta, 6.0) / 6.0;
        } else if (maxC == rgb.g) {
            h = ((rgb.b - rgb.r) / delta + 2.0) / 6.0;
        } else {
            h = ((rgb.r - rgb.g) / delta + 4.0) / 6.0;
        }
    }

    let s = select(delta / maxC, 0.0, maxC == 0.0);
    let v = maxC;

    return vec3<f32>(h, s, v);
}

fn getImage(st_in: vec2<f32>) -> vec4<f32> {
    var st = rotate2D(st_in, uniforms.rotation);

    // aberration and lensing
    let diff = vec2<f32>(0.5) - st;
    let centerDist = length(diff);

    var distort = 0.0;
    var zoom = 0.0;
    if (uniforms.distortion < 0.0) {
        distort = map(uniforms.distortion, -100.0, 0.0, -2.0, 0.0);
        zoom = map(uniforms.distortion, -100.0, 0.0, 0.04, 0.0);
    } else {
        distort = map(uniforms.distortion, 0.0, 100.0, 0.0, 2.0);
        zoom = map(uniforms.distortion, 0.0, 100.0, 0.0, -1.0);
    }

    st = (st - diff * zoom) - diff * centerDist * centerDist * distort;

    // scale
    var scale = 100.0 / uniforms.scaleAmt;
    if (scale == 0.0) {
        scale = 1.0;
    }
    st *= scale;

    // center
    st.x -= (scale * 0.5) - (0.5 - (1.0 / uniforms.resolution.x * scale));
    st.y += (scale * 0.5) + (0.5 - (1.0 / uniforms.resolution.y * scale)) - (scale);

    // nudge
    st += 1.0 / uniforms.resolution;

    // tile
    st = fract(st);

    // chromatic aberration
    let aberrationOffset = map(uniforms.aberration, 0.0, 100.0, 0.0, 0.1) * centerDist * PI * 0.5;

    // Sample selfTex directly - no Y flip needed in WGSL since input.uv
    // coordinate space already matches texture storage orientation

    let redOffset = mix(clamp(st.x + aberrationOffset, 0.0, 1.0), st.x, st.x);
    let red = textureSample(selfTex, texSampler, vec2<f32>(redOffset, st.y));

    let green = textureSample(selfTex, texSampler, st);

    let blueOffset = mix(st.x, clamp(st.x - aberrationOffset, 0.0, 1.0), st.x);
    let blue = textureSample(selfTex, texSampler, vec2<f32>(blueOffset, st.y));

    var tex = vec4<f32>(red.r, green.g, blue.b, 1.0);
    tex = vec4<f32>(tex.rgb * tex.a, tex.a);

    return tex;
}

fn cloak(st: vec2<f32>) -> vec4<f32> {
    let m = map(uniforms.mixAmt, 0.0, 100.0, 0.0, 1.0);
    let ra = map(uniforms.refractAAmt, 0.0, 100.0, 0.0, 0.125);
    let rb = map(uniforms.refractBAmt, 0.0, 100.0, 0.0, 0.125);

    let leftColor = textureSample(inputTex, texSampler, st);
    let rightColor = textureSample(selfTex, texSampler, st);

    var leftUV = st;
    let rightLen = length(rightColor.rgb);
    leftUV.x += cos(rightLen * TAU) * ra;
    leftUV.y += sin(rightLen * TAU) * ra;
    let leftRefracted = textureSample(inputTex, texSampler, fract(leftUV));

    var rightUV = st;
    let leftLen = length(leftColor.rgb);
    rightUV.x += cos(leftLen * TAU) * rb;
    rightUV.y += sin(leftLen * TAU) * rb;
    let rightRefracted = textureSample(selfTex, texSampler, fract(rightUV));

    let leftReflected = min(rightRefracted * rightColor / (1.0 - leftRefracted * leftColor), vec4<f32>(1.0));
    let rightReflected = min(leftRefracted * leftColor / (1.0 - rightRefracted * rightColor), vec4<f32>(1.0));

    var left: vec4<f32>;
    var right: vec4<f32>;
    if (uniforms.mixAmt < 50.0) {
        left = mix(leftRefracted, leftReflected, map(uniforms.mixAmt, 0.0, 50.0, 0.0, 1.0));
        right = rightReflected;
    } else {
        left = leftReflected;
        right = mix(rightReflected, rightRefracted, map(uniforms.mixAmt, 50.0, 100.0, 0.0, 1.0));
    }

    return mix(left, right, m);
}

@fragment
fn main(@builtin(position) pos: vec4<f32>) -> @location(0) vec4<f32> {
    let uv = pos.xy / uniforms.resolution;

    // If resetState is true, bypass feedback and return input directly
    if (uniforms.resetState != 0) {
        return textureSample(inputTex, texSampler, uv);
    }

    var color: vec4<f32>;

    if (uniforms.blendMode == 100) {
        color = cloak(uv);
    } else {
        let ra = map(uniforms.refractAAmt, 0.0, 100.0, 0.0, 0.125);
        let rb = map(uniforms.refractBAmt, 0.0, 100.0, 0.0, 0.125);

        let leftColor = textureSample(inputTex, texSampler, uv);
        let rightColor = textureSample(selfTex, texSampler, uv);

        var leftUV = uv;
        let rightLen = length(rightColor.rgb) + uniforms.refractADir / 360.0;
        leftUV.x += cos(rightLen * TAU) * ra;
        leftUV.y += sin(rightLen * TAU) * ra;

        var rightUV = uv;
        let leftLen = length(leftColor.rgb) + uniforms.refractBDir / 360.0;
        rightUV.x += cos(leftLen * TAU) * rb;
        rightUV.y += sin(leftLen * TAU) * rb;

        color = blend(textureSample(inputTex, texSampler, leftUV), getImage(rightUV), uniforms.blendMode, uniforms.mixAmt * 0.01);
    }

    // hue rotation
    var hsv = rgb2hsv(color.rgb);
    hsv.x = fract(hsv.x + map(uniforms.hueRotation, -180.0, 180.0, -0.05, 0.05));
    color = vec4<f32>(hsv2rgb(hsv), color.a);

    // brightness/contrast
    color = vec4<f32>(brightnessContrast(color.rgb), color.a);

    return color;
}

// binding(0) deliberately unused — sampler declared previously was dead
// (only textureLoad is used below, which doesn't need a sampler).
@group(0) @binding(1) var inputTex : texture_2d<f32>;
@group(0) @binding(2) var overlayTex : texture_2d<f32>;
@group(0) @binding(3) var<uniform> alpha : f32;

@fragment
fn main(@builtin(position) pos : vec4<f32>) -> @location(0) vec4<f32> {
    let coord = vec2<i32>(i32(pos.x), i32(pos.y));
    let base = textureLoad(inputTex, coord, 0);
    let overlay = textureLoad(overlayTex, coord, 0);

    let a = overlay.a * alpha;
    let result = base.rgb * (1.0 - a) + overlay.rgb * a;
    return vec4<f32>(result, base.a);
}

/*
 * Flip/Mirror effect
 * Apply horizontal/vertical flipping and various mirroring modes
 */

struct Uniforms {
    flipMode: i32,
    _pad1: i32,
    _pad2: i32,
    _pad3: i32,
    tileOffset: vec2<f32>,
    fullResolution: vec2<f32>,
}

@group(0) @binding(0) var inputSampler: sampler;
@group(0) @binding(1) var inputTex: texture_2d<f32>;
@group(0) @binding(2) var<uniform> uniforms: Uniforms;

@fragment
fn main(@builtin(position) pos: vec4<f32>) -> @location(0) vec4<f32> {
    let texSize = vec2<f32>(textureDimensions(inputTex));
    let globalCoord = pos.xy + uniforms.tileOffset;
    let globalUV = globalCoord / uniforms.fullResolution;

    var uv = globalUV;

    if (uniforms.flipMode == 1) {
        // flip both
        uv.x = 1.0 - uv.x;
        uv.y = 1.0 - uv.y;
    } else if (uniforms.flipMode == 2) {
        // flip horizontal
        uv.x = 1.0 - uv.x;
    } else if (uniforms.flipMode == 3) {
        // flip vertical
        uv.y = 1.0 - uv.y;
    } else if (uniforms.flipMode == 11) {
        // mirror left to right
        if (uv.x > 0.5) {
            uv.x = 1.0 - uv.x;
        }
    } else if (uniforms.flipMode == 12) {
        // mirror right to left
        if (uv.x < 0.5) {
            uv.x = 1.0 - uv.x;
        }
    } else if (uniforms.flipMode == 13) {
        // mirror up to down
        if (uv.y > 0.5) {
            uv.y = 1.0 - uv.y;
        }
    } else if (uniforms.flipMode == 14) {
        // mirror down to up
        if (uv.y < 0.5) {
            uv.y = 1.0 - uv.y;
        }
    } else if (uniforms.flipMode == 15) {
        // mirror left to right, up to down
        if (uv.x > 0.5) {
            uv.x = 1.0 - uv.x;
        }
        if (uv.y > 0.5) {
            uv.y = 1.0 - uv.y;
        }
    } else if (uniforms.flipMode == 16) {
        // mirror left to right, down to up
        if (uv.x > 0.5) {
            uv.x = 1.0 - uv.x;
        }
        if (uv.y < 0.5) {
            uv.y = 1.0 - uv.y;
        }
    } else if (uniforms.flipMode == 17) {
        // mirror right to left, up to down
        if (uv.x < 0.5) {
            uv.x = 1.0 - uv.x;
        }
        if (uv.y > 0.5) {
            uv.y = 1.0 - uv.y;
        }
    } else if (uniforms.flipMode == 18) {
        // mirror right to left, down to up
        if (uv.x < 0.5) {
            uv.x = 1.0 - uv.x;
        }
        if (uv.y < 0.5) {
            uv.y = 1.0 - uv.y;
        }
    }

    let localUV = fract((uv * uniforms.fullResolution - uniforms.tileOffset) / texSize);
    return textureSampleLevel(inputTex, inputSampler, localUV, 0.0);
}

// FXAA antialiasing pass
// Applies an edge-aware blur weighted by luminance differences while preserving alpha.

struct Uniforms {
    data: array<vec4<f32>, 1>,
    // data[0].x = strength (fxaa)
    // data[0].y = sharpness (fxaa)
    // data[0].z = threshold (fxaa)
};

const EPSILON: f32 = 1e-10;
const LUMA_WEIGHTS: vec3<f32> = vec3<f32>(0.299, 0.587, 0.114);

// binding(0) deliberately unused — sampler declared previously was dead
// (only textureLoad is used below, which doesn't need a sampler).
@group(0) @binding(1) var inputTex: texture_2d<f32>;
@group(0) @binding(2) var<uniform> uniforms: Uniforms;

fn luminance_from_rgb(rgb: vec3<f32>) -> f32 {
    return dot(rgb, LUMA_WEIGHTS);
}

fn weight_from_luma(center_luma: f32, neighbor_luma: f32, sharpness: f32) -> f32 {
    return exp(-sharpness * abs(center_luma - neighbor_luma));
}

fn reflect_coord(coord: i32, limit: i32) -> i32 {
    if (limit <= 1) {
        return 0;
    }

    let period: i32 = 2 * limit - 2;
    var wrapped: i32 = coord % period;
    if (wrapped < 0) {
        wrapped = wrapped + period;
    }

    if (wrapped < limit) {
        return wrapped;
    }

    return period - wrapped;
}

fn load_texel(coord: vec2<i32>, size: vec2<i32>) -> vec4<f32> {
    let rx = reflect_coord(coord.x, size.x);
    let ry = reflect_coord(coord.y, size.y);
    return textureLoad(inputTex, vec2<i32>(rx, ry), 0);
}

@fragment
fn main(@builtin(position) position: vec4<f32>) -> @location(0) vec4<f32> {
    let strength = uniforms.data[0].x;
    let sharpness = uniforms.data[0].y;
    let threshold = uniforms.data[0].z;

    let size = vec2<i32>(textureDimensions(inputTex, 0));
    let pixel_coord = vec2<i32>(i32(position.x), i32(position.y));

    let center_texel = load_texel(pixel_coord, size);
    let north_texel = load_texel(pixel_coord + vec2<i32>(0, -1), size);
    let south_texel = load_texel(pixel_coord + vec2<i32>(0, 1), size);
    let west_texel = load_texel(pixel_coord + vec2<i32>(-1, 0), size);
    let east_texel = load_texel(pixel_coord + vec2<i32>(1, 0), size);

    let center_rgb = center_texel.xyz;
    let north_rgb = north_texel.xyz;
    let south_rgb = south_texel.xyz;
    let west_rgb = west_texel.xyz;
    let east_rgb = east_texel.xyz;

    let center_luma = luminance_from_rgb(center_rgb);
    let north_luma = luminance_from_rgb(north_rgb);
    let south_luma = luminance_from_rgb(south_rgb);
    let west_luma = luminance_from_rgb(west_rgb);
    let east_luma = luminance_from_rgb(east_rgb);

    // Threshold: skip AA when max luma contrast is below threshold
    let maxDiff = max(
        max(abs(center_luma - north_luma), abs(center_luma - south_luma)),
        max(abs(center_luma - west_luma), abs(center_luma - east_luma))
    );
    if (maxDiff < threshold) {
        return center_texel;
    }

    let weight_center: f32 = 1.0;
    let weight_north = weight_from_luma(center_luma, north_luma, sharpness);
    let weight_south = weight_from_luma(center_luma, south_luma, sharpness);
    let weight_west = weight_from_luma(center_luma, west_luma, sharpness);
    let weight_east = weight_from_luma(center_luma, east_luma, sharpness);
    let weight_sum = weight_center + weight_north + weight_south + weight_west + weight_east + EPSILON;

    let blended_rgb = (
        center_rgb * weight_center
        + north_rgb * weight_north
        + south_rgb * weight_south
        + west_rgb * weight_west
        + east_rgb * weight_east
    ) / weight_sum;

    let result_texel = vec4<f32>(blended_rgb, center_texel.w);

    // Strength: blend between original and AA result
    return mix(center_texel, result_texel, strength);
}

/*
 * Glowing Edge - single-pass Sobel edge detection with glow
 */

struct Uniforms {
    sobelMetric: f32,
    alpha: f32,
    width: f32,
    _pad3: f32,
    tileOffset: vec2<f32>,
    fullResolution: vec2<f32>,
}

@group(0) @binding(0) var inputSampler: sampler;
@group(0) @binding(1) var inputTex: texture_2d<f32>;
@group(0) @binding(2) var<uniform> uniforms: Uniforms;

fn luminance(rgb: vec3<f32>) -> f32 {
    return dot(rgb, vec3<f32>(0.299, 0.587, 0.114));
}

fn distance_metric(gx: f32, gy: f32, metric: i32) -> f32 {
    let abs_gx = abs(gx);
    let abs_gy = abs(gy);

    if (metric == 1) {
        return abs_gx + abs_gy;  // Manhattan
    } else if (metric == 2) {
        return max(abs_gx, abs_gy);  // Chebyshev
    } else if (metric == 3) {
        let cross_val = (abs_gx + abs_gy) / 1.414;
        return max(cross_val, max(abs_gx, abs_gy));  // Minkowski
    }
    return sqrt(gx * gx + gy * gy);  // Euclidean (0)
}

@fragment
fn main(@builtin(position) pos: vec4<f32>) -> @location(0) vec4<f32> {
    let texSize = vec2<f32>(textureDimensions(inputTex));
    let globalCoord = pos.xy + uniforms.tileOffset;
    let uv = globalCoord / uniforms.fullResolution;
    let texel = uniforms.width / texSize;

    // Use textureSampleLevel because noisemaker textures are rgba16float —
    // unfilterable on WebGPU without the float32-filterable feature, which
    // makes plain textureSample reject the auto-generated bind-group layout.
    // textureSampleLevel takes an explicit mip level so no derivatives or
    // filtering are needed.

    // Sample base color
    let base = textureSampleLevel(inputTex, inputSampler, pos.xy / texSize, 0.0);

    // Sample 3x3 neighborhood for Sobel
    let tl = luminance(textureSampleLevel(inputTex, inputSampler, ((uv + vec2<f32>(-texel.x, -texel.y)) * uniforms.fullResolution - uniforms.tileOffset) / texSize, 0.0).rgb);
    let tc = luminance(textureSampleLevel(inputTex, inputSampler, ((uv + vec2<f32>(0.0, -texel.y)) * uniforms.fullResolution - uniforms.tileOffset) / texSize, 0.0).rgb);
    let tr = luminance(textureSampleLevel(inputTex, inputSampler, ((uv + vec2<f32>(texel.x, -texel.y)) * uniforms.fullResolution - uniforms.tileOffset) / texSize, 0.0).rgb);
    let ml = luminance(textureSampleLevel(inputTex, inputSampler, ((uv + vec2<f32>(-texel.x, 0.0)) * uniforms.fullResolution - uniforms.tileOffset) / texSize, 0.0).rgb);
    let mr = luminance(textureSampleLevel(inputTex, inputSampler, ((uv + vec2<f32>(texel.x, 0.0)) * uniforms.fullResolution - uniforms.tileOffset) / texSize, 0.0).rgb);
    let bl = luminance(textureSampleLevel(inputTex, inputSampler, ((uv + vec2<f32>(-texel.x, texel.y)) * uniforms.fullResolution - uniforms.tileOffset) / texSize, 0.0).rgb);
    let bc = luminance(textureSampleLevel(inputTex, inputSampler, ((uv + vec2<f32>(0.0, texel.y)) * uniforms.fullResolution - uniforms.tileOffset) / texSize, 0.0).rgb);
    let br = luminance(textureSampleLevel(inputTex, inputSampler, ((uv + vec2<f32>(texel.x, texel.y)) * uniforms.fullResolution - uniforms.tileOffset) / texSize, 0.0).rgb);

    // Sobel kernels
    let gx = -tl - 2.0 * ml - bl + tr + 2.0 * mr + br;
    let gy = -tl - 2.0 * tc - tr + bl + 2.0 * bc + br;

    // Edge magnitude
    let metric = i32(uniforms.sobelMetric);
    let edge = clamp(distance_metric(gx, gy, metric) * 3.0, 0.0, 1.0);

    // Glow: edges emit the base color as additive light
    let glow = edge * base.rgb * 2.0;

    // Screen blend glow onto original
    let result = vec3<f32>(1.0) - (vec3<f32>(1.0) - base.rgb) * (vec3<f32>(1.0) - glow);

    // Mix based on alpha
    let mixed = mix(base.rgb, result, uniforms.alpha);

    return vec4<f32>(clamp(mixed, vec3<f32>(0.0), vec3<f32>(1.0)), base.a);
}

/*
 * Glyph Map effect
 * Converts image to ASCII/glyph art using hardcoded 5x7 glyph bitmaps
 * ordered by density. Each cell maps input brightness to a glyph.
 */

struct Uniforms {
    cellSize: i32,
    seed: i32,
    colorMode: i32,
    _pad: i32,
    renderScale: f32,
    tileOffset: vec2<f32>,
    fullResolution: vec2<f32>,
}

@group(0) @binding(0) var inputSampler: sampler;
@group(0) @binding(1) var inputTex: texture_2d<f32>;
@group(0) @binding(2) var<uniform> uniforms: Uniforms;

const GLYPH_COUNT: i32 = 16;

// PCG PRNG
fn pcg(seed: vec3<u32>) -> vec3<u32> {
    var v = seed * 1664525u + 1013904223u;
    v.x = v.x + v.y * v.z;
    v.y = v.y + v.z * v.x;
    v.z = v.z + v.x * v.y;
    v = v ^ (v >> vec3<u32>(16u));
    v.x = v.x + v.y * v.z;
    v.y = v.y + v.z * v.x;
    v.z = v.z + v.x * v.y;
    return v;
}

// Hash for glyph variant selection per cell
fn hash(p: vec2<f32>) -> f32 {
    let v = pcg(vec3<u32>(
        u32(select(-p.x * 2.0 + 1.0, p.x * 2.0, p.x >= 0.0)),
        u32(select(-p.y * 2.0 + 1.0, p.y * 2.0, p.y >= 0.0)),
        0u
    ));
    return f32(v.x) / f32(0xffffffffu);
}

// Get one row (5 bits) of a glyph bitmap
// g: glyph index (0-15), y: row (0-6)
// Returns the 5-bit row value
fn glyphRow(g: i32, y: i32) -> i32 {
    // Glyph 0: space
    if (g == 0) { return 0; }
    // Glyph 1: period
    if (g == 1) {
        if (y == 5) { return 4; }
        return 0;
    }
    // Glyph 2: colon
    if (g == 2) {
        if (y == 1 || y == 5) { return 4; }
        return 0;
    }
    // Glyph 3: dash
    if (g == 3) {
        if (y == 3) { return 14; }
        return 0;
    }
    // Glyph 4: plus
    if (g == 4) {
        if (y == 1 || y == 2 || y == 4 || y == 5) { return 4; }
        if (y == 3) { return 14; }
        return 0;
    }
    // Glyph 5: equals
    if (g == 5) {
        if (y == 2 || y == 4) { return 14; }
        return 0;
    }
    // Glyph 6: asterisk
    if (g == 6) {
        if (y == 1 || y == 5) { return 10; }
        if (y == 2 || y == 4) { return 4; }
        if (y == 3) { return 14; }
        return 0;
    }
    // Glyph 7: o
    if (g == 7) {
        if (y == 2 || y == 5) { return 14; }
        if (y == 3 || y == 4) { return 10; }
        return 0;
    }
    // Glyph 8: X
    if (g == 8) {
        if (y == 1 || y == 2 || y == 4 || y == 5) { return 10; }
        if (y == 3) { return 4; }
        return 0;
    }
    // Glyph 9: hash #
    if (g == 9) {
        if (y == 1 || y == 3 || y == 5) { return 10; }
        if (y == 2 || y == 4) { return 31; }
        return 0;
    }
    // Glyph 10: percent %
    if (g == 10) {
        if (y == 0) { return 25; }
        if (y == 1) { return 26; }
        if (y == 2) { return 4; }
        if (y == 3) { return 9; }
        if (y == 4) { return 11; }
        if (y == 5) { return 19; }
        return 0;
    }
    // Glyph 11: A
    if (g == 11) {
        if (y == 0) { return 4; }
        if (y == 1) { return 10; }
        if (y == 2) { return 17; }
        if (y == 3) { return 31; }
        if (y == 4 || y == 5) { return 17; }
        return 0;
    }
    // Glyph 12: W
    if (g == 12) {
        if (y == 0 || y == 1) { return 17; }
        if (y == 2 || y == 3) { return 21; }
        if (y == 4) { return 27; }
        if (y == 5) { return 10; }
        return 0;
    }
    // Glyph 13: M
    if (g == 13) {
        if (y == 0) { return 17; }
        if (y == 1) { return 27; }
        if (y == 2 || y == 3) { return 21; }
        if (y == 4 || y == 5) { return 17; }
        return 0;
    }
    // Glyph 14: @
    if (g == 14) {
        if (y == 0 || y == 6) { return 14; }
        if (y == 1) { return 17; }
        if (y == 2) { return 23; }
        if (y == 3) { return 21; }
        if (y == 4) { return 22; }
        if (y == 5) { return 16; }
        return 0;
    }
    // Glyph 15: full block
    return 31;
}

// Return 1.0 if pixel (x, y) is set in glyph g, else 0.0
fn glyphPixel(g: i32, x: i32, y: i32) -> f32 {
    let row = glyphRow(g, y);
    // WGSL requires the right-hand side of `>>` to be a u32 (or vecN<u32>)
    let bit = (row >> u32(4 - x)) & 1;
    return f32(bit);
}

@fragment
fn main(@builtin(position) pos: vec4<f32>) -> @location(0) vec4<f32> {
    let texSize = vec2<f32>(textureDimensions(inputTex));
    let tileOffset = uniforms.tileOffset;
    let isTile = length(tileOffset) > 0.0;
    // Non-tiling path is byte-identical to the previous shader. When tiling,
    // mirror glsl/glyphMap.glsl: global pixel grid + renderScale-scaled cell
    // (clamped to 512) so cells align across tiles.
    var pixelCoord = pos.xy;
    var cs = max(uniforms.cellSize, 1);
    if (isTile) {
        pixelCoord = pos.xy + tileOffset;
        cs = clamp(i32(f32(uniforms.cellSize) * uniforms.renderScale), 1, 512);
    }
    let csf = f32(cs);

    // Which cell are we in?
    let cellIndex = floor(pixelCoord / csf);

    // Local position within the cell, mapped to 5x7 glyph grid
    let localPos = fract(pixelCoord / csf);
    var gx = i32(floor(localPos.x * 5.0));
    var gy = i32(floor(localPos.y * 7.0));
    gx = clamp(gx, 0, 4);
    gy = clamp(gy, 0, 6);

    // Sample the center of the cell for brightness
    let cellCenter = (cellIndex + 0.5) * csf;
    var sampleUV = cellCenter / texSize;
    if (isTile) {
        sampleUV = clamp((cellCenter - tileOffset) / texSize, vec2<f32>(0.0), vec2<f32>(1.0));
    }
    let srcColor = textureSample(inputTex, inputSampler, sampleUV);

    // Compute luminance
    let luma = dot(srcColor.rgb, vec3<f32>(0.299, 0.587, 0.114));

    // Map luminance to glyph index (0 to GLYPH_COUNT-1)
    var glyphIdx = i32(floor(luma * f32(GLYPH_COUNT)));
    glyphIdx = clamp(glyphIdx, 0, GLYPH_COUNT - 1);

    // Use seed to rotate/shift glyph selection for variety
    let cellHash = hash(cellIndex + f32(uniforms.seed) * 0.37);
    let variant = i32(floor(cellHash * 3.0));

    if (variant == 2 && glyphIdx > 1) {
        glyphIdx = glyphIdx - 1;
    }

    // Get the glyph pixel value
    let glyphVal = glyphPixel(glyphIdx, gx, gy);

    if (uniforms.colorMode > 0) {
        return vec4<f32>(srcColor.rgb * glyphVal, 1.0);
    } else {
        return vec4<f32>(vec3<f32>(glyphVal), 1.0);
    }
}

/*
 * Grade - Creative Pass (WGSL)
 * Vibrance, faded film, shadow/highlight tinting (split tone)
 * All math in linear color space
 */

struct Uniforms {
    vibrance: f32,
    fadedFilm: f32,
    splitToneBalance: f32,
    _pad0: f32,
    shadowTint: vec3<f32>,
    _pad1: f32,
    highlightTint: vec3<f32>,
    _pad2: f32,
}

@group(0) @binding(0) var inputSampler: sampler;
@group(0) @binding(1) var inputTex: texture_2d<f32>;
@group(0) @binding(2) var<uniform> uniforms: Uniforms;

const LUMA_WEIGHTS = vec3<f32>(0.2126, 0.7152, 0.0722);

// sRGB to linear
fn srgbToLinear(srgb: vec3<f32>) -> vec3<f32> {
    var linear: vec3<f32>;
    for (var i = 0; i < 3; i++) {
        if (srgb[i] <= 0.04045) {
            linear[i] = srgb[i] / 12.92;
        } else {
            linear[i] = pow((srgb[i] + 0.055) / 1.055, 2.4);
        }
    }
    return linear;
}

// Linear to sRGB
fn linearToSrgb(linear: vec3<f32>) -> vec3<f32> {
    var srgb: vec3<f32>;
    for (var i = 0; i < 3; i++) {
        if (linear[i] <= 0.0031308) {
            srgb[i] = linear[i] * 12.92;
        } else {
            srgb[i] = 1.055 * pow(linear[i], 1.0 / 2.4) - 0.055;
        }
    }
    return srgb;
}

// Vibrance: boost low-saturation colors, protect already-saturated and skin tones
fn applyVibrance(rgb: vec3<f32>, vibrance: f32) -> vec3<f32> {
    if (abs(vibrance) < 0.001) { return rgb; }

    let luma = dot(rgb, LUMA_WEIGHTS);
    let chroma = rgb - luma;

    let maxC = max(max(rgb.r, rgb.g), rgb.b);
    let minC = min(min(rgb.r, rgb.g), rgb.b);
    var sat: f32;
    if (maxC > 0.001) {
        sat = (maxC - minC) / maxC;
    } else {
        sat = 0.0;
    }

    let vibranceGain = 1.0 + vibrance * (1.0 - sat);

    // Skin tone protection
    var skinFactor = 1.0;
    if (rgb.r > rgb.g && rgb.g > rgb.b) {
        skinFactor = smoothstep(0.3, 0.7, sat) * 0.5 + 0.5;
    }

    let finalGain = mix(1.0, vibranceGain, skinFactor);

    return luma + chroma * finalGain;
}

// Faded film: lift the blacks
fn applyFadedFilm(rgb: vec3<f32>, amount: f32) -> vec3<f32> {
    if (amount < 0.001) { return rgb; }

    let lifted = mix(rgb, vec3<f32>(0.2), amount * 0.5);

    let luma = dot(lifted, LUMA_WEIGHTS);
    let chroma = lifted - luma;

    let pivot = 0.5;
    let contrastFactor = 1.0 - amount * 0.3;
    let newLuma = (luma - pivot) * contrastFactor + pivot;

    return newLuma + chroma * (1.0 - amount * 0.2);
}

// Split toning
fn applySplitTone(rgb: vec3<f32>, shadowTint: vec3<f32>, highlightTint: vec3<f32>, balance: f32) -> vec3<f32> {
    let shadowShift = (shadowTint - 0.5) * 2.0;
    let highlightShift = (highlightTint - 0.5) * 2.0;

    if (length(shadowShift) < 0.01 && length(highlightShift) < 0.01) {
        return rgb;
    }

    let luma = dot(rgb, LUMA_WEIGHTS);
    let balancePoint = 0.5 + balance * 0.3;

    let shadowW = 1.0 - smoothstep(0.0, balancePoint, luma);
    let highlightW = smoothstep(balancePoint, 1.0, luma);

    var tintedRgb = rgb;
    tintedRgb += shadowShift * shadowW * 0.3;
    tintedRgb += highlightShift * highlightW * 0.3;

    return tintedRgb;
}

@fragment
fn main(@builtin(position) pos: vec4<f32>) -> @location(0) vec4<f32> {
    let texSize = vec2<f32>(textureDimensions(inputTex));
    let uv = pos.xy / texSize;
    let color = textureSample(inputTex, inputSampler, uv);

    var rgb = srgbToLinear(color.rgb);

    // 1. Vibrance
    rgb = applyVibrance(rgb, uniforms.vibrance);

    // 2. Faded Film
    rgb = applyFadedFilm(rgb, uniforms.fadedFilm);

    // 3. Split Toning
    rgb = applySplitTone(rgb, uniforms.shadowTint, uniforms.highlightTint, 
                         uniforms.splitToneBalance);

    rgb = linearToSrgb(max(rgb, vec3<f32>(0.0)));

    return vec4<f32>(rgb, color.a);
}

/*
 * Grade - HSL Secondary Pass (WGSL)
 * Isolate color range by Hue/Sat/Luma, apply targeted correction
 * Key with soft edges
 */

struct Uniforms {
    hslEnable: i32,
    hslHueCenter: f32,
    hslHueRange: f32,
    hslSatMin: f32,
    hslSatMax: f32,
    hslLumMin: f32,
    hslLumMax: f32,
    hslFeather: f32,
    hslHueShift: f32,
    hslSatAdjust: f32,
    hslLumAdjust: f32,
    _pad0: f32,
}

@group(0) @binding(0) var inputSampler: sampler;
@group(0) @binding(1) var inputTex: texture_2d<f32>;
@group(0) @binding(2) var<uniform> uniforms: Uniforms;

const LUMA_WEIGHTS = vec3<f32>(0.2126, 0.7152, 0.0722);

// sRGB to linear
fn srgbToLinear(srgb: vec3<f32>) -> vec3<f32> {
    var linear: vec3<f32>;
    for (var i = 0; i < 3; i++) {
        if (srgb[i] <= 0.04045) {
            linear[i] = srgb[i] / 12.92;
        } else {
            linear[i] = pow((srgb[i] + 0.055) / 1.055, 2.4);
        }
    }
    return linear;
}

// Linear to sRGB
fn linearToSrgb(linear: vec3<f32>) -> vec3<f32> {
    var srgb: vec3<f32>;
    for (var i = 0; i < 3; i++) {
        if (linear[i] <= 0.0031308) {
            srgb[i] = linear[i] * 12.92;
        } else {
            srgb[i] = 1.055 * pow(linear[i], 1.0 / 2.4) - 0.055;
        }
    }
    return srgb;
}

// RGB to HSL
fn rgbToHsl(rgb: vec3<f32>) -> vec3<f32> {
    let maxC = max(max(rgb.r, rgb.g), rgb.b);
    let minC = min(min(rgb.r, rgb.g), rgb.b);
    let delta = maxC - minC;

    let l = (maxC + minC) * 0.5;

    var h = 0.0;
    var s = 0.0;

    if (delta > 0.001) {
        if (l > 0.5) {
            s = delta / (2.0 - maxC - minC);
        } else {
            s = delta / (maxC + minC);
        }

        if (maxC == rgb.r) {
            h = (rgb.g - rgb.b) / delta;
            if (rgb.g < rgb.b) { h += 6.0; }
        } else if (maxC == rgb.g) {
            h = (rgb.b - rgb.r) / delta + 2.0;
        } else {
            h = (rgb.r - rgb.g) / delta + 4.0;
        }
        h /= 6.0;
    }

    return vec3<f32>(h, s, l);
}

// HSL to RGB
fn hslToRgb(hsl: vec3<f32>) -> vec3<f32> {
    let h = hsl.x;
    let s = hsl.y;
    let l = hsl.z;

    if (s < 0.001) {
        return vec3<f32>(l);
    }

    var q: f32;
    if (l < 0.5) {
        q = l * (1.0 + s);
    } else {
        q = l + s - l * s;
    }
    let p = 2.0 * l - q;

    var rgb: vec3<f32>;
    for (var i = 0; i < 3; i++) {
        var t = h + (1.0 - f32(i)) / 3.0;
        t = fract(t);

        if (t < 1.0 / 6.0) {
            rgb[i] = p + (q - p) * 6.0 * t;
        } else if (t < 0.5) {
            rgb[i] = q;
        } else if (t < 2.0 / 3.0) {
            rgb[i] = p + (q - p) * (2.0 / 3.0 - t) * 6.0;
        } else {
            rgb[i] = p;
        }
    }

    return rgb;
}

// Compute HSL key matte
fn computeHslKey(hsl: vec3<f32>, hueCenter: f32, hueRange: f32, 
                 satMin: f32, satMax: f32, lumMin: f32, lumMax: f32, feather: f32) -> f32 {
    var hueDist = abs(hsl.x - hueCenter);
    hueDist = min(hueDist, 1.0 - hueDist);

    let hueKey = 1.0 - smoothstep(hueRange - feather, hueRange + feather, hueDist);

    let satKey = smoothstep(satMin - feather, satMin + feather, hsl.y) *
                 (1.0 - smoothstep(satMax - feather, satMax + feather, hsl.y));

    let lumKey = smoothstep(lumMin - feather, lumMin + feather, hsl.z) *
                 (1.0 - smoothstep(lumMax - feather, lumMax + feather, hsl.z));

    return hueKey * satKey * lumKey;
}

// Apply correction
fn applyHslCorrection(hsl: vec3<f32>, hueShift: f32, satAdjust: f32, lumAdjust: f32) -> vec3<f32> {
    var corrected = hsl;
    corrected.x = fract(corrected.x + hueShift);
    corrected.y = clamp(corrected.y + satAdjust, 0.0, 1.0);
    corrected.z = clamp(corrected.z + lumAdjust * 0.5, 0.0, 1.0);
    return corrected;
}

@fragment
fn main(@builtin(position) pos: vec4<f32>) -> @location(0) vec4<f32> {
    let texSize = vec2<f32>(textureDimensions(inputTex));
    let uv = pos.xy / texSize;
    let color = textureSample(inputTex, inputSampler, uv);

    if (uniforms.hslEnable == 0) {
        return color;
    }

    var rgb = srgbToLinear(color.rgb);
    let hsl = rgbToHsl(rgb);

    let matte = computeHslKey(hsl, uniforms.hslHueCenter, uniforms.hslHueRange,
                              uniforms.hslSatMin, uniforms.hslSatMax,
                              uniforms.hslLumMin, uniforms.hslLumMax, 
                              uniforms.hslFeather);

    let correctedHsl = applyHslCorrection(hsl, uniforms.hslHueShift, 
                                           uniforms.hslSatAdjust, uniforms.hslLumAdjust);
    let correctedRgb = hslToRgb(correctedHsl);

    rgb = mix(rgb, correctedRgb, matte);

    rgb = linearToSrgb(max(rgb, vec3<f32>(0.0)));

    return vec4<f32>(rgb, color.a);
}

