// sRGB to linear
fn srgbToLinear(srgb: vec3f) -> vec3f {
    var linear: vec3f;
    for (var i = 0; i < 3; i++) {
        if (srgb[i] <= 0.04045) {
            linear[i] = srgb[i] / 12.92;
        } else {
            linear[i] = pow((srgb[i] + 0.055) / 1.055, 2.4);
