}

// Linear to sRGB
fn linearToSrgb(linear: vec3f) -> vec3f {
    var srgb: vec3f;
    for (var i = 0; i < 3; i++) {
        if (linear[i] <= 0.0031308) {
            srgb[i] = linear[i] * 12.92;
        } else {
            srgb[i] = 1.055 * pow(linear[i], 1.0 / 2.4) - 0.055;
        }
    }
