// RGB to HSL
fn rgbToHsl(rgb: vec3f) -> vec3f {
    let maxC = max(max(rgb.r, rgb.g), rgb.b);
    let minC = min(min(rgb.r, rgb.g), rgb.b);
    let delta = maxC - minC;
    let l = (maxC + minC) * 0.5;
    var h = 0.0;
    var s = 0.0;
    if (delta > 0.001) {
