    return vec3f(h, s, l);
}

// HSL to RGB
fn hue2rgb(p: f32, q: f32, t_in: f32) -> f32 {
    var t = t_in;
    if (t < 0.0) { t += 1.0; }
    if (t > 1.0) { t -= 1.0; }
    if (t < 1.0/6.0) { return p + (q - p) * 6.0 * t; }
    if (t < 1.0/2.0) { return q; }
    if (t < 2.0/3.0) { return p + (q - p) * (2.0/3.0 - t) * 6.0; }
    return p;
}

fn hslToRgb(hsl: vec3f) -> vec3f {
    if (hsl.y == 0.0) { return vec3f(hsl.z); }
    let q = select(hsl.z + hsl.y - hsl.z * hsl.y, hsl.z * (1.0 + hsl.y), hsl.z < 0.5);
    let p = 2.0 * hsl.z - q;
    return vec3f(
        hue2rgb(p, q, hsl.x + 1.0/3.0),
        hue2rgb(p, q, hsl.x),
        hue2rgb(p, q, hsl.x - 1.0/3.0)
    );
}

// Luminance
fn luma(rgb: vec3f) -> f32 {
    return dot(rgb, vec3f(0.2126, 0.7152, 0.0722));
}

// --- PROCEDURAL LUT PRESETS ---

fn lutTealOrange(rgb: vec3f) -> vec3f {
    let l = luma(rgb);
    let teal = vec3f(0.0, 0.5, 0.6);
    let orange = vec3f(1.0, 0.6, 0.3);
    let graded = mix(teal, orange, l);
    let hsl = rgbToHsl(rgb);
    var gradedHsl = rgbToHsl(graded);
    gradedHsl.y = mix(gradedHsl.y, hsl.y, 0.5);
    return hslToRgb(gradedHsl);
}

fn lutWarmFilm(rgb_in: vec3f) -> vec3f {
    var rgb = rgb_in * 0.95 + 0.05;
    rgb.r = pow(rgb.r, 0.95);
    rgb.b = pow(rgb.b, 1.05);
    let l = luma(rgb);
    rgb.g = mix(rgb.g * 0.95, rgb.g, l);
    rgb = rgb * rgb * (3.0 - 2.0 * rgb);
    return rgb;
}

fn lutCoolShadows(rgb_in: vec3f) -> vec3f {
    var rgb = rgb_in;
    let l = luma(rgb);
    let coolBlue = vec3f(0.4, 0.5, 0.7);
    let shadowMask = 1.0 - smoothstep(0.0, 0.5, l);
    rgb = mix(rgb, coolBlue * l * 2.0, shadowMask * 0.4);
    return rgb;
}

fn lutBleachBypass(rgb_in: vec3f) -> vec3f {
    var rgb = rgb_in;
    let l = luma(rgb);
    let desat = vec3f(l);
    rgb = mix(rgb, desat, 0.5);
    rgb = (rgb - 0.5) * 1.3 + 0.5;
    rgb.r *= 1.02;
    rgb.b *= 0.98;
    return clamp(rgb, vec3f(0.0), vec3f(1.0));
}

fn lutCrossProcess(rgb_in: vec3f) -> vec3f {
    var rgb = rgb_in;
    rgb.r = pow(rgb.r, 0.9);
    rgb.g = pow(rgb.g, 1.0);
    rgb.b = pow(rgb.b, 1.2);
    let l = luma(rgb);
    rgb.r += (1.0 - l) * -0.1 + l * 0.1;
    rgb.g += (1.0 - l) * 0.05;
    rgb.b += (1.0 - l) * 0.1 + l * -0.15;
    var hsl = rgbToHsl(rgb);
    hsl.y *= 1.2;
    rgb = hslToRgb(hsl);
    return clamp(rgb, vec3f(0.0), vec3f(1.0));
}

fn lutCinematic(rgb_in: vec3f) -> vec3f {
    var rgb = rgb_in;
    let l = luma(rgb);
    rgb = rgb * 0.9 + 0.03;
    let shadowTint = vec3f(0.95, 1.0, 1.05);
    let highlightTint = vec3f(1.05, 1.0, 0.95);
    rgb *= mix(shadowTint, highlightTint, l);
    rgb = pow(rgb, vec3f(1.1));
    return clamp(rgb, vec3f(0.0), vec3f(1.0));
}

fn lutDayForNight(rgb_in: vec3f) -> vec3f {
    var rgb = rgb_in;
    rgb.r *= 0.5;
    rgb.g *= 0.6;
    rgb.b *= 1.0;
    rgb *= 0.4;
    rgb = mix(vec3f(luma(rgb)), rgb, 0.7);
    return rgb;
}

fn lutVintage(rgb_in: vec3f) -> vec3f {
    var rgb = rgb_in * 0.85 + 0.08;
    rgb.r = pow(rgb.r, 0.95);
    rgb.b = pow(rgb.b, 1.1);
    var hsl = rgbToHsl(rgb);
    hsl.y *= 0.7;
    rgb = hslToRgb(hsl);
    return clamp(rgb, vec3f(0.0), vec3f(1.0));
}

// Noir - high contrast black and white with subtle blue shadows
fn lutNoir(rgb_in: vec3f) -> vec3f {
    let l = luma(rgb_in);
    let contrast = (l - 0.5) * 1.5 + 0.5;
    let blue = vec3f(0.9, 0.95, 1.0);
    var rgb = vec3f(contrast) * mix(blue, vec3f(1.0), contrast);
    return clamp(rgb, vec3f(0.0), vec3f(1.0));
}

// Sepia - warm brown vintage look
fn lutSepia(rgb_in: vec3f) -> vec3f {
    let l = luma(rgb_in);
    let sepia = vec3f(1.0, 0.89, 0.71);
    var rgb = l * sepia;
    rgb = rgb * 0.9 + 0.05;
    return clamp(rgb, vec3f(0.0), vec3f(1.0));
}

// Infrared - false color heat map style
fn lutInfrared(rgb_in: vec3f) -> vec3f {
    let l = luma(rgb_in);
    var rgb = rgb_in;
    rgb.r = pow(l, 0.7);
    rgb.g = rgb_in.g * 0.3;
    rgb.b = 1.0 - l;
    let foliage = smoothstep(0.2, 0.6, rgb_in.g) * (1.0 - abs(rgb_in.r - rgb_in.b));
    rgb.r = mix(rgb.r, 1.0, foliage * 0.7);
    return clamp(rgb, vec3f(0.0), vec3f(1.0));
}

// Technicolor - saturated three-strip film look
fn lutTechnicolor(rgb_in: vec3f) -> vec3f {
    var rgb = rgb_in;
    rgb.r = pow(rgb.r, 0.85) * 1.1;
    rgb.g = pow(rgb.g, 1.0) * 0.95;
    rgb.b = pow(rgb.b, 0.9) * 1.05;
    var hsl = rgbToHsl(rgb);
    hsl.y = min(hsl.y * 1.4, 1.0);
    rgb = hslToRgb(hsl);
    rgb = (rgb - 0.5) * 1.15 + 0.5;
    return clamp(rgb, vec3f(0.0), vec3f(1.0));
}

// Neon - cyberpunk high saturation with color shift
fn lutNeon(rgb_in: vec3f) -> vec3f {
    var rgb = rgb_in;
    var hsl = rgbToHsl(rgb);
    hsl.x = fract(hsl.x + 0.05);
    hsl.y = min(hsl.y * 1.8, 1.0);
    rgb = hslToRgb(hsl);
    rgb = (rgb - 0.5) * 1.4 + 0.5;
    rgb.r = pow(max(rgb.r, 0.0), 0.9);
    rgb.b = pow(max(rgb.b, 0.0), 0.85);
    return clamp(rgb, vec3f(0.0), vec3f(1.0));
}

// Matrix - green monochrome terminal look
fn lutMatrix(rgb_in: vec3f) -> vec3f {
    let l = luma(rgb_in);
    let boosted = pow(l, 0.8);
    var rgb = vec3f(boosted * 0.2, boosted, boosted * 0.15);
    rgb += vec3f(0.0, 0.02, 0.0);
    return clamp(rgb, vec3f(0.0), vec3f(1.0));
}

// Underwater - aquatic blue-green color shift
fn lutUnderwater(rgb_in: vec3f) -> vec3f {
    var rgb = rgb_in;
    rgb.r *= 0.5;
    rgb.g = pow(rgb.g, 0.9) * 0.9;
    rgb.b = pow(rgb.b, 0.85) * 1.1;
    let depth = 1.0 - luma(rgb_in) * 0.3;
    rgb = mix(rgb, rgb * vec3f(0.4, 0.7, 1.0), 0.3 * depth);
    return clamp(rgb, vec3f(0.0), vec3f(1.0));
}

// Sunset - warm orange/magenta gradient
fn lutSunset(rgb_in: vec3f) -> vec3f {
    var rgb = rgb_in;
    let l = luma(rgb_in);
    let warmth = smoothstep(0.3, 0.7, l);
    let sunset = mix(vec3f(1.0, 0.3, 0.5), vec3f(1.0, 0.8, 0.4), warmth);
    rgb = mix(rgb * sunset, rgb, 0.4);
    rgb.r = pow(rgb.r, 0.9);
    return clamp(rgb, vec3f(0.0), vec3f(1.0));
}

// Monochrome - pure black and white with enhanced contrast
fn lutMonochrome(rgb_in: vec3f) -> vec3f {
    let l = luma(rgb_in);
    let contrast = (l - 0.5) * 1.2 + 0.5;
    return clamp(vec3f(contrast), vec3f(0.0), vec3f(1.0));
}

// Psychedelic - extreme color rotation and saturation
fn lutPsychedelic(rgb_in: vec3f) -> vec3f {
    var hsl = rgbToHsl(rgb_in);
    hsl.x = fract(hsl.x * 3.0 + hsl.z * 0.5);
    hsl.y = min(hsl.y * 2.0, 1.0);
    hsl.z = (hsl.z - 0.5) * 1.3 + 0.5;
    var rgb = hslToRgb(hsl);
    return clamp(rgb, vec3f(0.0), vec3f(1.0));
}

// Hard Light - Extreme contrast for metallic/shiny appearance
fn lutHardLight(rgb_in: vec3f) -> vec3f {
    let l = luma(rgb_in);

    // Hard light blend mode simulation
    var result: vec3f;
    result.r = select(1.0 - 2.0 * (1.0 - rgb_in.r) * (1.0 - l), 2.0 * rgb_in.r * l, rgb_in.r < 0.5);
    result.g = select(1.0 - 2.0 * (1.0 - rgb_in.g) * (1.0 - l), 2.0 * rgb_in.g * l, rgb_in.g < 0.5);
    result.b = select(1.0 - 2.0 * (1.0 - rgb_in.b) * (1.0 - l), 2.0 * rgb_in.b * l, rgb_in.b < 0.5);

    // Boost overall contrast
    result = (result - 0.5) * 1.4 + 0.5;

    // Add slight cool metallic tint to highlights
    let highlightMask = smoothstep(0.5, 1.0, l);
    result.b += highlightMask * 0.05;

    return clamp(result, vec3f(0.0), vec3f(1.0));
}

// Posterize - Quantize luminance for banded noise effect
fn lutPosterize(rgb_in: vec3f) -> vec3f {
    let l = luma(rgb_in);

    // Quantize to discrete levels
    let levels = 6.0;
    let quantized = floor(l * levels + 0.5) / levels;

    // Map to a color ramp for visual interest
    var ramp: vec3f;
    if (quantized < 0.2) {
        ramp = vec3f(0.1, 0.05, 0.15);  // Deep purple-black
    } else if (quantized < 0.4) {
        ramp = vec3f(0.3, 0.2, 0.4);    // Dark purple
    } else if (quantized < 0.6) {
        ramp = vec3f(0.5, 0.4, 0.6);    // Medium purple
    } else if (quantized < 0.8) {
        ramp = vec3f(0.8, 0.6, 0.5);    // Warm highlight
    } else {
        ramp = vec3f(1.0, 0.9, 0.8);    // Bright cream
    }

    // Blend with original color for some hue preservation
    let hsl = rgbToHsl(rgb_in);
    var rampHsl = rgbToHsl(ramp);
    rampHsl.x = mix(rampHsl.x, hsl.x, 0.3);

    return hslToRgb(rampHsl);
}

// Solarize - Partial inversion creates wild band separation
fn lutSolarize(rgb_in: vec3f) -> vec3f {
    let l = luma(rgb_in);

    // Invert values above threshold, creating bands
    let threshold = 0.5;
    var result: vec3f;
    result.r = select(2.0 * (1.0 - rgb_in.r), 2.0 * rgb_in.r, rgb_in.r <= threshold);
    result.g = select(2.0 * (1.0 - rgb_in.g), 2.0 * rgb_in.g, rgb_in.g <= threshold);
    result.b = select(2.0 * (1.0 - rgb_in.b), 2.0 * rgb_in.b, rgb_in.b <= threshold);

    // Boost saturation for more dramatic effect
    var hsl = rgbToHsl(result);
    hsl.y = min(hsl.y * 1.5, 1.0);
    result = hslToRgb(hsl);

    // Add slight contrast
    result = (result - 0.5) * 1.1 + 0.5;

    return clamp(result, vec3f(0.0), vec3f(1.0));
}

@fragment
fn main(@builtin(position) fragCoord: vec4f) -> @location(0) vec4f {
    let coord = vec2i(fragCoord.xy);
    let color = textureLoad(inputTex, coord, 0);

    if (uniforms.preset == 0 || uniforms.alpha <= 0.0) {
        return color;
    }

    var rgb = srgbToLinear(color.rgb);
    var graded = rgb;

    if (uniforms.preset == 1) {
        graded = lutTealOrange(rgb);
    } else if (uniforms.preset == 2) {
        graded = lutWarmFilm(rgb);
    } else if (uniforms.preset == 3) {
        graded = lutCoolShadows(rgb);
    } else if (uniforms.preset == 4) {
        graded = lutBleachBypass(rgb);
    } else if (uniforms.preset == 5) {
        graded = lutCrossProcess(rgb);
    } else if (uniforms.preset == 6) {
        graded = lutCinematic(rgb);
    } else if (uniforms.preset == 7) {
        graded = lutDayForNight(rgb);
    } else if (uniforms.preset == 8) {
        graded = lutVintage(rgb);
    } else if (uniforms.preset == 9) {
        graded = lutNoir(rgb);
    } else if (uniforms.preset == 10) {
        graded = lutSepia(rgb);
    } else if (uniforms.preset == 11) {
        graded = lutInfrared(rgb);
    } else if (uniforms.preset == 12) {
        graded = lutTechnicolor(rgb);
    } else if (uniforms.preset == 13) {
        graded = lutNeon(rgb);
    } else if (uniforms.preset == 14) {
        graded = lutMatrix(rgb);
    } else if (uniforms.preset == 15) {
        graded = lutUnderwater(rgb);
    } else if (uniforms.preset == 16) {
        graded = lutSunset(rgb);
    } else if (uniforms.preset == 17) {
        graded = lutMonochrome(rgb);
    } else if (uniforms.preset == 18) {
        graded = lutPsychedelic(rgb);
    } else if (uniforms.preset == 20) {
        graded = lutHardLight(rgb);
    } else if (uniforms.preset == 21) {
        graded = lutPosterize(rgb);
    } else if (uniforms.preset == 22) {
        graded = lutSolarize(rgb);
    }

    rgb = mix(rgb, graded, uniforms.alpha);
    rgb = linearToSrgb(max(rgb, vec3f(0.0)));

    return vec4f(rgb, color.a);
}

/*
 * Grade - Primary Correction Pass (WGSL)
 * White balance, exposure, contrast, tonal range operators, saturation
 * All math in linear color space
 */

struct Uniforms {
    temperature: f32,
    tint: f32,
    exposure: f32,
    contrast: f32,
    highlights: f32,
    shadows: f32,
    whites: f32,
    blacks: f32,
    saturation: f32,
    curveShadows: f32,
    curveMidtones: f32,
    curveHighlights: f32,
}

@group(0) @binding(0) var inputSampler: sampler;
@group(0) @binding(1) var inputTex: texture_2d<f32>;
@group(0) @binding(2) var<uniform> uniforms: Uniforms;

const LUMA_WEIGHTS = vec3<f32>(0.2126, 0.7152, 0.0722);

// sRGB to linear
fn srgbToLinear(srgb: vec3<f32>) -> vec3<f32> {
    var linear: vec3<f32>;
    for (var i = 0; i < 3; i++) {
        if (srgb[i] <= 0.04045) {
            linear[i] = srgb[i] / 12.92;
        } else {
            linear[i] = pow((srgb[i] + 0.055) / 1.055, 2.4);
        }
    }
    return linear;
}

// Linear to sRGB
fn linearToSrgb(linear: vec3<f32>) -> vec3<f32> {
    var srgb: vec3<f32>;
    for (var i = 0; i < 3; i++) {
        if (linear[i] <= 0.0031308) {
            srgb[i] = linear[i] * 12.92;
        } else {
            srgb[i] = 1.055 * pow(linear[i], 1.0 / 2.4) - 0.055;
        }
    }
    return srgb;
}

// White balance using temperature/tint as chromatic adaptation
fn applyWhiteBalance(rgb: vec3<f32>, temp: f32, tint: f32) -> vec3<f32> {
    let shift = vec3<f32>(
        1.0 + temp * 0.5,
        1.0 - tint * 0.5,
        1.0 - temp * 0.5
    );
    return rgb * shift;
}

// Tonal weight functions
fn shadowWeight(luma: f32) -> f32 {
    return 1.0 - smoothstep(0.0, 0.5, luma);
}

fn highlightWeight(luma: f32) -> f32 {
    return smoothstep(0.5, 1.0, luma);
}

fn midtoneWeight(luma: f32) -> f32 {
    return 1.0 - abs(luma - 0.5) * 2.0;
}

fn whitesWeight(luma: f32) -> f32 {
    return smoothstep(0.7, 1.0, luma);
}

fn blacksWeight(luma: f32) -> f32 {
    return 1.0 - smoothstep(0.0, 0.3, luma);
}

// Apply tonal range adjustments
fn applyTonalRanges(rgb: vec3<f32>, highlights: f32, shadows: f32, whites: f32, blacks: f32) -> vec3<f32> {
    let luma = dot(rgb, LUMA_WEIGHTS);
    let chroma = rgb - luma;

    let hWeight = highlightWeight(luma);
    let sWeight = shadowWeight(luma);
    let wWeight = whitesWeight(luma);
    let bWeight = blacksWeight(luma);

    var lumaAdjust = 0.0;
    lumaAdjust += highlights * hWeight * 0.5;
    lumaAdjust += shadows * sWeight * 0.5;
    lumaAdjust += whites * wWeight * 0.3;
    lumaAdjust += blacks * bWeight * 0.3;

    let newLuma = max(luma + lumaAdjust, 0.0);

    return newLuma + chroma;
}

// S-curve contrast
fn applyContrast(rgb: vec3<f32>, contrast: f32) -> vec3<f32> {
    if (abs(contrast) < 0.001) { return rgb; }

    let luma = dot(rgb, LUMA_WEIGHTS);
    let chroma = rgb - luma;

    let pivot = 0.5;
    let factor = 1.0 + contrast;

    let newLuma = clamp((luma - pivot) * factor + pivot, 0.0, 1.5);

    return newLuma + chroma;
}

// Apply lift/gamma/gain style curve
fn applyCurve(rgb: vec3<f32>, shadowLift: f32, midGamma: f32, highGain: f32) -> vec3<f32> {
    let luma = dot(rgb, LUMA_WEIGHTS);
    let chroma = rgb - luma;

    let sW = shadowWeight(luma);
    let mW = midtoneWeight(luma);
    let hW = highlightWeight(luma);

    let lift = shadowLift * sW * 0.2;
    let gamma = 1.0 - midGamma * mW * 0.3;
    let gain = 1.0 + highGain * hW * 0.5;

    var newLuma = luma + lift;
    newLuma = pow(max(newLuma, 0.001), gamma);
    newLuma = newLuma * gain;

    return max(newLuma + chroma, vec3<f32>(0.0));
}

// Saturation adjustment
fn applySaturation(rgb: vec3<f32>, satAmount: f32) -> vec3<f32> {
    let luma = dot(rgb, LUMA_WEIGHTS);
    let chroma = rgb - luma;
    return luma + chroma * satAmount;
}

@fragment
fn main(@builtin(position) pos: vec4<f32>) -> @location(0) vec4<f32> {
    let texSize = vec2<f32>(textureDimensions(inputTex));
    let uv = pos.xy / texSize;
    let color = textureSample(inputTex, inputSampler, uv);

    // The public input is premultiplied. Private grade stages carry straight
    // sRGB until the final vignette pass restores premultiplied coverage.
    var straight = vec3<f32>(0.0);
    if (color.a > 0.0) {
        straight = color.rgb / color.a;
    }
    var rgb = srgbToLinear(straight);

    // 1. White Balance
    rgb = applyWhiteBalance(rgb, uniforms.temperature, uniforms.tint);

    // 2. Exposure
    rgb = rgb * pow(2.0, uniforms.exposure);

    // 3. Contrast
    rgb = applyContrast(rgb, uniforms.contrast);

    // 4. Tonal Range Operators
    rgb = applyTonalRanges(rgb, uniforms.highlights, uniforms.shadows, 
                           uniforms.whites, uniforms.blacks);

    // 5. Curves
    rgb = applyCurve(rgb, uniforms.curveShadows, uniforms.curveMidtones, 
                     uniforms.curveHighlights);

    // 6. Saturation
    rgb = applySaturation(rgb, uniforms.saturation);

    // Encode back to sRGB
    rgb = linearToSrgb(max(rgb, vec3<f32>(0.0)));

    return vec4<f32>(rgb, color.a);
}

/*
 * Grade - Vignette Pass (WGSL)
 * Elliptical vignette with highlight preservation
 * Applied as final spatial modifier
 */

struct Uniforms {
    vignetteAmount: f32,
    vignetteMidpoint: f32,
    vignetteRoundness: f32,
    vignetteFeather: f32,
    vigHiProtect: f32,
    _pad0: f32,
    _pad1: f32,
    _pad2: f32,
}

@group(0) @binding(0) var inputSampler: sampler;
@group(0) @binding(1) var inputTex: texture_2d<f32>;
@group(0) @binding(2) var<uniform> uniforms: Uniforms;

const LUMA_WEIGHTS = vec3<f32>(0.2126, 0.7152, 0.0722);

// sRGB to linear
fn srgbToLinear(srgb: vec3<f32>) -> vec3<f32> {
    var linear: vec3<f32>;
    for (var i = 0; i < 3; i++) {
        if (srgb[i] <= 0.04045) {
            linear[i] = srgb[i] / 12.92;
        } else {
            linear[i] = pow((srgb[i] + 0.055) / 1.055, 2.4);
        }
    }
    return linear;
}

// Linear to sRGB
fn linearToSrgb(linear: vec3<f32>) -> vec3<f32> {
    var srgb: vec3<f32>;
    for (var i = 0; i < 3; i++) {
        if (linear[i] <= 0.0031308) {
            srgb[i] = linear[i] * 12.92;
        } else {
            srgb[i] = 1.055 * pow(linear[i], 1.0 / 2.4) - 0.055;
        }
    }
    return srgb;
}

// Compute vignette mask
fn computeVignette(uv: vec2<f32>, aspectRatio: vec2<f32>, midpoint: f32, 
                   roundness: f32, feather: f32) -> f32 {
    var centered = uv - 0.5;

    var scale: vec2<f32>;
    if (roundness > 0.0) {
        scale = mix(aspectRatio, vec2<f32>(1.0), roundness);
    } else {
        scale = mix(aspectRatio, aspectRatio * vec2<f32>(1.0 + abs(roundness), 1.0 - abs(roundness) * 0.5), -roundness);
    }

    centered *= scale;

    let dist = length(centered) * 2.0;

    let inner = midpoint - feather * 0.5;
    let outer = midpoint + feather * 0.5;

    return 1.0 - smoothstep(inner, outer, dist);
}

// Apply vignette
fn applyVignette(rgb: vec3<f32>, vignetteMask: f32, amount: f32, highlightProtect: f32) -> vec3<f32> {
    if (abs(amount) < 0.001) { return rgb; }

    var darken = 1.0 - (1.0 - vignetteMask) * abs(amount);

    if (highlightProtect > 0.0) {
        let luma = dot(rgb, LUMA_WEIGHTS);
        let protection = smoothstep(0.5, 1.0, luma) * highlightProtect;
        darken = mix(darken, 1.0, protection);
    }

    if (amount > 0.0) {
        return rgb * darken;
    } else {
        return 1.0 - (1.0 - rgb) * darken;
    }
}

@fragment
fn main(@builtin(position) pos: vec4<f32>) -> @location(0) vec4<f32> {
    let texSize = vec2<f32>(textureDimensions(inputTex));
    let uv = pos.xy / texSize;
    let color = textureSample(inputTex, inputSampler, uv);

    if (abs(uniforms.vignetteAmount) < 0.001) {
        return vec4<f32>(color.rgb * color.a, color.a);
    }

    var rgb = srgbToLinear(color.rgb);

    var aspectRatio: vec2<f32>;
    if (texSize.x > texSize.y) {
        aspectRatio = vec2<f32>(texSize.x / texSize.y, 1.0);
    } else {
        aspectRatio = vec2<f32>(1.0, texSize.y / texSize.x);
    }

    let vignetteMask = computeVignette(uv, aspectRatio, uniforms.vignetteMidpoint, 
                                        uniforms.vignetteRoundness, uniforms.vignetteFeather);

    rgb = applyVignette(rgb, vignetteMask, uniforms.vignetteAmount, 
                        uniforms.vigHiProtect);

    rgb = linearToSrgb(max(rgb, vec3<f32>(0.0)));

    return vec4<f32>(rgb * color.a, color.a);
}

/*
 * Grade - Three-Way Color Wheels Pass (WGSL)
 * Shadows/Midtones/Highlights color balance
 * Classic 3-way corrector with separate chroma moves per tonal range
 */

struct Uniforms {
    wheelBalance: f32,
    _pad0: f32,
    _pad1: f32,
    _pad2: f32,
    wheelShadows: vec3<f32>,
    _pad3: f32,
    wheelMidtones: vec3<f32>,
    _pad4: f32,
    wheelHighlights: vec3<f32>,
    _pad5: f32,
}

@group(0) @binding(0) var inputSampler: sampler;
@group(0) @binding(1) var inputTex: texture_2d<f32>;
@group(0) @binding(2) var<uniform> uniforms: Uniforms;

const LUMA_WEIGHTS = vec3<f32>(0.2126, 0.7152, 0.0722);

// sRGB to linear
fn srgbToLinear(srgb: vec3<f32>) -> vec3<f32> {
    var linear: vec3<f32>;
    for (var i = 0; i < 3; i++) {
        if (srgb[i] <= 0.04045) {
            linear[i] = srgb[i] / 12.92;
        } else {
            linear[i] = pow((srgb[i] + 0.055) / 1.055, 2.4);
        }
    }
    return linear;
}

// Linear to sRGB
fn linearToSrgb(linear: vec3<f32>) -> vec3<f32> {
    var srgb: vec3<f32>;
    for (var i = 0; i < 3; i++) {
        if (linear[i] <= 0.0031308) {
            srgb[i] = linear[i] * 12.92;
        } else {
            srgb[i] = 1.055 * pow(linear[i], 1.0 / 2.4) - 0.055;
        }
    }
    return srgb;
}

// Tonal range weights
fn shadowWeight(luma: f32, balance: f32) -> f32 {
    let boundary = 0.33 - balance * 0.15;
    return 1.0 - smoothstep(0.0, boundary * 2.0, luma);
}

fn midtoneWeight(luma: f32, balance: f32) -> f32 {
    let center = 0.5;
    let spread = 0.4 - abs(balance) * 0.1;
    let dist = abs(luma - center) / spread;
    return max(0.0, 1.0 - dist);
}

fn highlightWeight(luma: f32, balance: f32) -> f32 {
    let boundary = 0.67 + balance * 0.15;
    return smoothstep(boundary - 0.33, 1.0, luma);
}

// Apply color wheel adjustment
fn applyWheels(rgb: vec3<f32>, shadowWheel: vec3<f32>, midWheel: vec3<f32>, 
               highWheel: vec3<f32>, balance: f32) -> vec3<f32> {
    let shadowOffset = (shadowWheel - 0.5) * 2.0;
    let midOffset = (midWheel - 0.5) * 2.0;
    let highOffset = (highWheel - 0.5) * 2.0;

    if (length(shadowOffset) < 0.01 && length(midOffset) < 0.01 && length(highOffset) < 0.01) {
        return rgb;
    }

    let luma = dot(rgb, LUMA_WEIGHTS);

    var sW = shadowWeight(luma, balance);
    var mW = midtoneWeight(luma, balance);
    var hW = highlightWeight(luma, balance);

    let totalWeight = sW + mW + hW + 0.001;
    sW /= totalWeight;
    mW /= totalWeight;
    hW /= totalWeight;

    var colorShift = vec3<f32>(0.0);
    colorShift += shadowOffset * sW * 0.5;
    colorShift += midOffset * mW * 0.5;
    colorShift += highOffset * hW * 0.5;

    var result = rgb + colorShift;

    let newLuma = dot(result, LUMA_WEIGHTS);
    let lumaDiff = luma - newLuma;
    result += lumaDiff * 0.3;

    return result;
}

@fragment
fn main(@builtin(position) pos: vec4<f32>) -> @location(0) vec4<f32> {
    let texSize = vec2<f32>(textureDimensions(inputTex));
    let uv = pos.xy / texSize;
    let color = textureSample(inputTex, inputSampler, uv);

    var rgb = srgbToLinear(color.rgb);

    rgb = applyWheels(rgb, uniforms.wheelShadows, uniforms.wheelMidtones, 
                      uniforms.wheelHighlights, uniforms.wheelBalance);

    rgb = linearToSrgb(max(rgb, vec3<f32>(0.0)));

    return vec4<f32>(rgb, color.a);
}

// Grain: blend the source image with animated value noise.
// Mirrors noisemaker.effects.grain, which calls value.values()
// using simplex-based value noise with bicubic interpolation.

const PI : f32 = 3.14159265358979323846;
const TAU : f32 = 6.28318530717958647692;
const UINT32_TO_FLOAT : f32 = 1.0 / 4294967296.0;
const CHANNEL_COUNT : u32 = 4u;
const INTERPOLATION_CONSTANT : u32 = 0u;
const INTERPOLATION_LINEAR : u32 = 1u;
const INTERPOLATION_COSINE : u32 = 2u;
const INTERPOLATION_BICUBIC : u32 = 3u;
const BASE_SEED : u32 = 0x1234u;

struct GrainParams {
    width : f32,
    height : f32,
    channels : f32,
    alpha : f32,
    time : f32,
    pause : f32,
    renderScale : f32,
    _pad0 : f32,
    tileOffset : vec2<f32>,
    fullResolution : vec2<f32>,
};

@group(0) @binding(0) var inputTex : texture_2d<f32>;
@group(0) @binding(1) var<storage, read_write> output_buffer : array<f32>;
@group(0) @binding(2) var<uniform> params : GrainParams;

fn as_u32(value : f32) -> u32 {
    return u32(max(round(value), 0.0));
}

fn clamp01(value : f32) -> f32 {
    return clamp(value, 0.0, 1.0);
}

fn pcg3d(v_in : vec3<u32>) -> vec3<u32> {
    var v : vec3<u32> = v_in * 1664525u + 1013904223u;
    v.x = v.x + v.y * v.z;
    v.y = v.y + v.z * v.x;
    v.z = v.z + v.x * v.y;
    v = v ^ (v >> vec3<u32>(16u));
    v.x = v.x + v.y * v.z;
    v.y = v.y + v.z * v.x;
    v.z = v.z + v.x * v.y;
    return v;
}

fn random_from_cell_3d(cell : vec3<i32>, seed : u32) -> f32 {
    let hashed : vec3<u32> = vec3<u32>(
        bitcast<u32>(cell.x) ^ seed,
        bitcast<u32>(cell.y) ^ (seed * 0x9e3779b9u + 0x7f4a7c15u),
        bitcast<u32>(cell.z) ^ (seed * 0x632be59bu + 0x5bf03635u),
    );
    let noise : vec3<u32> = pcg3d(hashed);
    return f32(noise.x) * UINT32_TO_FLOAT;
}

fn periodic_value(time_value : f32, sample : f32) -> f32 {
    return (sin((time_value - sample) * TAU) + 1.0) * 0.5;
}

fn interpolation_weight(value : f32, spline_order : u32) -> f32 {
    if (spline_order == INTERPOLATION_COSINE) {
        let clamped : f32 = clamp(value, 0.0, 1.0);
        let angle : f32 = clamped * PI;
        let cos_value : f32 = cos(angle);
        return (1.0 - cos_value) * 0.5;
    }
    return value;
}

fn blend_cubic(a : f32, b : f32, c : f32, d : f32, g : f32) -> f32 {
    let t : f32 = clamp(g, 0.0, 1.0);
    let t2 : f32 = t * t;
    let a0 : f32 = ((d - c) - a) + b;
    let a1 : f32 = (a - b) - a0;
    let a2 : f32 = c - a;
    let a3 : f32 = b;
    let term1 : f32 = (a0 * t) * t2;
    let term2 : f32 = a1 * t2;
    let term3 : f32 = (a2 * t) + a3;
    return (term1 + term2) + term3;
}

fn sample_bicubic_layer(
    cell : vec2<i32>,
    frac : vec2<f32>,
    z_cell : i32,
    base_seed : u32,
) -> f32 {
    let row0 : f32 = blend_cubic(
        random_from_cell_3d(vec3<i32>(cell.x - 1, cell.y - 1, z_cell), base_seed),
        random_from_cell_3d(vec3<i32>(cell.x + 0, cell.y - 1, z_cell), base_seed),
        random_from_cell_3d(vec3<i32>(cell.x + 1, cell.y - 1, z_cell), base_seed),
        random_from_cell_3d(vec3<i32>(cell.x + 2, cell.y - 1, z_cell), base_seed),
        frac.x,
    );
    let row1 : f32 = blend_cubic(
        random_from_cell_3d(vec3<i32>(cell.x - 1, cell.y + 0, z_cell), base_seed),
        random_from_cell_3d(vec3<i32>(cell.x + 0, cell.y + 0, z_cell), base_seed),
        random_from_cell_3d(vec3<i32>(cell.x + 1, cell.y + 0, z_cell), base_seed),
        random_from_cell_3d(vec3<i32>(cell.x + 2, cell.y + 0, z_cell), base_seed),
        frac.x,
    );
    let row2 : f32 = blend_cubic(
        random_from_cell_3d(vec3<i32>(cell.x - 1, cell.y + 1, z_cell), base_seed),
        random_from_cell_3d(vec3<i32>(cell.x + 0, cell.y + 1, z_cell), base_seed),
        random_from_cell_3d(vec3<i32>(cell.x + 1, cell.y + 1, z_cell), base_seed),
        random_from_cell_3d(vec3<i32>(cell.x + 2, cell.y + 1, z_cell), base_seed),
        frac.x,
    );
    let row3 : f32 = blend_cubic(
        random_from_cell_3d(vec3<i32>(cell.x - 1, cell.y + 2, z_cell), base_seed),
        random_from_cell_3d(vec3<i32>(cell.x + 0, cell.y + 2, z_cell), base_seed),
        random_from_cell_3d(vec3<i32>(cell.x + 1, cell.y + 2, z_cell), base_seed),
        random_from_cell_3d(vec3<i32>(cell.x + 2, cell.y + 2, z_cell), base_seed),
        frac.x,
    );
    return blend_cubic(row0, row1, row2, row3, frac.y);
}

fn sample_raw_value_noise(
    uv : vec2<f32>,
    freq : vec2<f32>,
    base_seed : u32,
    time_value : f32,
    speed_value : f32,
    spline_order : u32,
) -> f32 {
    let scaled_freq : vec2<f32> = max(freq, vec2<f32>(1.0, 1.0));
    let scaled_uv : vec2<f32> = uv * scaled_freq;
    let cell_f : vec2<f32> = floor(scaled_uv);
    let cell : vec2<i32> = vec2<i32>(i32(cell_f.x), i32(cell_f.y));
    let frac : vec2<f32> = fract(scaled_uv);
    let angle : f32 = time_value * TAU;
    let time_coord : f32 = cos(angle) * speed_value;
    let time_floor : f32 = floor(time_coord);
    let time_cell : i32 = i32(time_floor);
    let time_frac : f32 = fract(time_coord);

    if (spline_order == INTERPOLATION_CONSTANT) {
        return random_from_cell_3d(vec3<i32>(cell.x, cell.y, time_cell), base_seed);
    }

    if (spline_order == INTERPOLATION_LINEAR) {
        let tl : f32 = random_from_cell_3d(vec3<i32>(cell.x, cell.y, time_cell), base_seed);
        let tr : f32 = random_from_cell_3d(vec3<i32>(cell.x + 1, cell.y, time_cell), base_seed);
        let bl : f32 = random_from_cell_3d(vec3<i32>(cell.x, cell.y + 1, time_cell), base_seed);
        let br : f32 = random_from_cell_3d(vec3<i32>(cell.x + 1, cell.y + 1, time_cell), base_seed);
        let weight_x : f32 = interpolation_weight(frac.x, spline_order);
        let top : f32 = mix(tl, tr, weight_x);
        let bottom : f32 = mix(bl, br, weight_x);
        let weight_y : f32 = interpolation_weight(frac.y, spline_order);
        return mix(top, bottom, weight_y);
    }

    if (spline_order == INTERPOLATION_COSINE) {
        let weight_x : f32 = interpolation_weight(frac.x, spline_order);
        let weight_y : f32 = interpolation_weight(frac.y, spline_order);
        let tl : f32 = random_from_cell_3d(vec3<i32>(cell.x, cell.y, time_cell), base_seed);
        let tr : f32 = random_from_cell_3d(vec3<i32>(cell.x + 1, cell.y, time_cell), base_seed);
        let bl : f32 = random_from_cell_3d(vec3<i32>(cell.x, cell.y + 1, time_cell), base_seed);
        let br : f32 = random_from_cell_3d(vec3<i32>(cell.x + 1, cell.y + 1, time_cell), base_seed);
        let top : f32 = mix(tl, tr, weight_x);
        let bottom : f32 = mix(bl, br, weight_x);
        return mix(top, bottom, weight_y);
    }

    let slice0 : f32 = sample_bicubic_layer(cell, frac, time_cell - 1, base_seed);
    let slice1 : f32 = sample_bicubic_layer(cell, frac, time_cell + 0, base_seed);
    let slice2 : f32 = sample_bicubic_layer(cell, frac, time_cell + 1, base_seed);
    let slice3 : f32 = sample_bicubic_layer(cell, frac, time_cell + 2, base_seed);
    return blend_cubic(slice0, slice1, slice2, slice3, time_frac);
}

fn sample_value_noise(
    uv : vec2<f32>,
    freq : vec2<f32>,
    seed : u32,
    time_value : f32,
    speed_value : f32,
    spline_order : u32,
) -> f32 {
    let base_seed : u32 = seed;
    let base_value : f32 = sample_raw_value_noise(
        uv,
        freq,
        base_seed,
        time_value,
        speed_value,
        spline_order,
    );

    if (speed_value == 0.0 || time_value == 0.0) {
        return base_value;
    }

    let time_seed : u32 = base_seed + 0x9e3779b1u;
    let time_field : f32 = sample_raw_value_noise(
        uv,
        freq,
        time_seed,
        0.0,
        1.0,
        spline_order,
    );
    let scaled_time : f32 = periodic_value(time_value, time_field) * speed_value;
    return periodic_value(scaled_time, base_value);
}

fn sample_grain_noise(
    pixel_coords : vec2<u32>,
    dims : vec2<f32>,
    time_value : f32,
    speed_value : f32,
) -> f32 {
    let width : f32 = max(dims.x, 1.0);
    let height : f32 = max(dims.y, 1.0);
    let uv : vec2<f32> = vec2<f32>(f32(pixel_coords.x) / width, f32(pixel_coords.y) / height);
    let freq : vec2<f32> = vec2<f32>(width, height);
    return sample_value_noise(uv, freq, BASE_SEED, time_value, speed_value, INTERPOLATION_BICUBIC);
}

fn write_pixel(base_index : u32, rgba : vec4<f32>) {
    output_buffer[base_index + 0u] = rgba.x;
    output_buffer[base_index + 1u] = rgba.y;
    output_buffer[base_index + 2u] = rgba.z;
    output_buffer[base_index + 3u] = rgba.w;
}

@compute @workgroup_size(8, 8, 1)
fn main(@builtin(global_invocation_id) gid : vec3<u32>) {
    let width : u32 = max(as_u32(params.width), 1u);
    let height : u32 = max(as_u32(params.height), 1u);
    if (gid.x >= width || gid.y >= height) {
        return;
    }

    let full_width : u32 = select(width, max(as_u32(params.fullResolution.x), 1u), params.fullResolution.x > 0.0);
    let full_height : u32 = select(height, max(as_u32(params.fullResolution.y), 1u), params.fullResolution.y > 0.0);
    let tile_offset : vec2<i32> = vec2<i32>(
        i32(round(params.tileOffset.x)),
        i32(round(params.tileOffset.y)),
    );
    let global_pixel_signed : vec2<i32> = vec2<i32>(gid.xy) + tile_offset;
    if (global_pixel_signed.x < 0 || global_pixel_signed.y < 0 ||
        global_pixel_signed.x >= i32(full_width) || global_pixel_signed.y >= i32(full_height)) {
        return;
    }
    let global_pixel : vec2<u32> = vec2<u32>(global_pixel_signed);

    let coords : vec2<i32> = vec2<i32>(i32(gid.x), i32(gid.y));
    let texel : vec4<f32> = textureLoad(inputTex, coords, 0);
    let pixel_index : u32 = gid.y * width + gid.x;
    let base_index : u32 = pixel_index * CHANNEL_COUNT;

    let blend_alpha : f32 = clamp(params.alpha, 0.0, 1.0);
    if (blend_alpha <= 0.0) {
        write_pixel(base_index, texel);
        return;
    }

    // When paused, use time=0 for static noise; otherwise use actual time
    let effective_time : f32 = select(params.time, 0.0, params.pause > 0.5);

    let rs : f32 = max(params.renderScale, 1.0);
    let noise_value : f32 = sample_grain_noise(
        global_pixel,
        vec2<f32>(f32(full_width), f32(full_height)) / rs,
        effective_time,
        100.0,
    );
    let noise_rgb : vec3<f32> = vec3<f32>(noise_value);
    let mixed_rgb : vec3<f32> = mix(texel.rgb, noise_rgb, blend_alpha);
    write_pixel(base_index, vec4<f32>(
        clamp01(mixed_rgb.x),
        clamp01(mixed_rgb.y),
        clamp01(mixed_rgb.z),
        texel.a,
    ));
}

/*
 * Grime - dusty speckles and grime overlay
 *
 * Multi-octave noise with self-refraction, Chebyshev derivative,
 * dropout specks, and sparse noise blended to dirty the input.
 */

struct VertexOutput {
    @builtin(position) position: vec4<f32>,
    @location(0) uv: vec2<f32>,
}

@group(0) @binding(0) var u_sampler: sampler;
@group(0) @binding(1) var inputTex: texture_2d<f32>;
@group(0) @binding(2) var<uniform> strength: f32;
@group(0) @binding(3) var<uniform> seed: f32;
@group(0) @binding(4) var<uniform> resolution: vec2<f32>;
@group(0) @binding(5) var<uniform> tileOffset: vec2<f32>;
@group(0) @binding(6) var<uniform> fullResolution: vec2<f32>;

fn clamp01(v: f32) -> f32 {
    return clamp(v, 0.0, 1.0);
}

fn freq_for_shape(freq: f32, w: f32, h: f32) -> vec2<f32> {
    if (w <= 0.0 || h <= 0.0) { return vec2<f32>(freq, freq); }
    if (abs(w - h) < 0.5) { return vec2<f32>(freq, freq); }
    if (h < w) { return vec2<f32>(freq, freq * w / h); }
    return vec2<f32>(freq * h / w, freq);
}

// PCG PRNG
fn pcg(seed: vec3<u32>) -> vec3<u32> {
    var v = seed * 1664525u + 1013904223u;
    v.x = v.x + v.y * v.z;
    v.y = v.y + v.z * v.x;
    v.z = v.z + v.x * v.y;
    v = v ^ (v >> vec3<u32>(16u));
    v.x = v.x + v.y * v.z;
    v.y = v.y + v.z * v.x;
    v.z = v.z + v.x * v.y;
    return v;
}

fn hash21(p: vec2<f32>) -> f32 {
    let v = pcg(vec3<u32>(bitcast<u32>(p.x), bitcast<u32>(p.y), 0u));
    return f32(v.x) / f32(0xffffffffu);
}

fn hash31(p: vec3<f32>) -> f32 {
    let v = pcg(vec3<u32>(bitcast<u32>(p.x), bitcast<u32>(p.y), bitcast<u32>(p.z)));
    return f32(v.x) / f32(0xffffffffu);
}

fn fade(t: f32) -> f32 {
    return t * t * (3.0 - 2.0 * t);
}

fn value_noise(coord: vec2<f32>, s: f32) -> f32 {
    let cell = floor(coord);
    let f = fract(coord);
    let tl = hash31(vec3<f32>(cell, s));
    let tr = hash31(vec3<f32>(cell + vec2<f32>(1.0, 0.0), s));
    let bl = hash31(vec3<f32>(cell + vec2<f32>(0.0, 1.0), s));
    let br = hash31(vec3<f32>(cell + vec2<f32>(1.0, 1.0), s));
    let st = vec2<f32>(fade(f.x), fade(f.y));
    return mix(mix(tl, tr, st.x), mix(bl, br, st.x), st.y);
}

fn seed_offset(s: f32) -> vec2<f32> {
    let angle = s * 0.1375;
    let radius = 0.35 * (0.25 + 0.75 * sin(s * 1.37));
    return vec2<f32>(cos(angle), sin(angle)) * radius;
}

fn simple_multires(uv: vec2<f32>, base_freq: vec2<f32>, s: f32) -> f32 {
    var freq = base_freq;
    var amp: f32 = 0.5;
    var total: f32 = 0.0;
    var accum: f32 = 0.0;

    for (var i: u32 = 0u; i < 8u; i = i + 1u) {
        let os = s + f32(i) * 37.11;
        let off = seed_offset(os) / freq;
        accum = accum + value_noise(uv * freq + off, os) * amp;
        total = total + amp;
        freq = freq * 2.0;
        amp = amp * 0.5;
    }

    return clamp01(accum / max(total, 0.001));
}

fn refracted_field(uv: vec2<f32>, base_freq: vec2<f32>, px: vec2<f32>, disp: f32, s: f32) -> f32 {
    let base_mask = simple_multires(uv, base_freq, s);
    let off_mask = simple_multires(fract(uv + vec2<f32>(0.5, 0.5)), base_freq, s + 19.0);

    let off_vec = vec2<f32>(
        (base_mask * 2.0 - 1.0) * disp * px.x,
        (off_mask * 2.0 - 1.0) * disp * px.y,
    );
    return simple_multires(fract(uv + off_vec), base_freq, s + 41.0);
}

fn chebyshev_gradient(uv: vec2<f32>, base_freq: vec2<f32>, px: vec2<f32>, disp: f32, s: f32) -> f32 {
    let ox = vec2<f32>(px.x, 0.0);
    let oy = vec2<f32>(0.0, px.y);

    let r = refracted_field(fract(uv + ox), base_freq, px, disp, s);
    let l = refracted_field(fract(uv - ox), base_freq, px, disp, s);
    let u = refracted_field(fract(uv + oy), base_freq, px, disp, s);
    let d = refracted_field(fract(uv - oy), base_freq, px, disp, s);

    let dx = (r - l) * 0.5;
    let dy = (u - d) * 0.5;
    return clamp01(max(abs(dx), abs(dy)) * 4.0);
}

fn exponential_noise(uv: vec2<f32>, freq: vec2<f32>, s: f32) -> f32 {
    let off = seed_offset(s + 7.0);
    return pow(clamp01(value_noise(uv * freq + off, s + 13.0)), 4.0);
}

fn refracted_exponential(uv: vec2<f32>, freq: vec2<f32>, px: vec2<f32>, disp: f32, s: f32) -> f32 {
    let base = exponential_noise(uv, freq, s);
    let ox = exponential_noise(uv, freq, s + 23.0);
    let oy = exponential_noise(fract(uv + vec2<f32>(0.5, 0.5)), freq, s + 47.0);

    let off_vec = vec2<f32>(
        (ox * 2.0 - 1.0) * disp * px.x,
        (oy * 2.0 - 1.0) * disp * px.y,
    );
    let warped = exponential_noise(fract(uv + off_vec), freq, s + 59.0);
    return clamp01((base + warped) * 0.5);
}

@fragment
fn main(input: VertexOutput) -> @location(0) vec4<f32> {
    let dims = max(resolution, vec2<f32>(1.0, 1.0));
    // Frame coordinates as the GLSL's gl_FragCoord / resolution; the default
    // vertex uv has a bottom-left origin, which flipped the output.
    let uv = input.position.xy / dims;
    let tileSize = vec2<f32>(textureDimensions(inputTex, 0));
    let globalCoord = uv * tileSize + tileOffset;
    let globalUV = globalCoord / fullResolution;
    let px = 1.0 / fullResolution;
    let base_color = textureSample(inputTex, u_sampler, uv);

    let str = max(strength, 0.0);
    let s = seed;

    // Multi-octave noise mask, self-refracted
    let freq_mask = freq_for_shape(5.0, fullResolution.x, fullResolution.y);
    let mask_refracted = refracted_field(globalUV, freq_mask, px, 1.0, s + 11.0);
    let mask_gradient = chebyshev_gradient(globalUV, freq_mask, px, 1.0, s + 11.0);
    let mask_value = clamp01(mix(mask_refracted, mask_gradient, 0.125));

    // Blend input with dark dust using squared mask
    let mask_power = clamp01(mask_value * mask_value * 0.4);
    var dusty = mix(base_color.rgb, vec3<f32>(0.15), mask_power);

    // Speck overlay: dropout + exponential noise, refracted
    let freq_specks = fullResolution * 0.1;
    let dropout = select(0.0, 1.0, hash21(globalUV * fullResolution + vec2<f32>(s + 37.0, s * 1.37)) < 0.4);
    let specks_field = refracted_exponential(globalUV, freq_specks, px, 0.25, s + 71.0) * dropout;
    let trimmed = clamp01((specks_field - 0.3) / 0.7);
    let specks = 1.0 - sqrt(trimmed);

    // Sparse noise
    let sparse_mask = select(0.0, 1.0, hash21(globalUV * fullResolution + vec2<f32>(s + 113.0, s + 171.0)) < 0.25);
    let sparse_noise = exponential_noise(globalUV, fullResolution, s + 131.0) * sparse_mask;

    // Combine
    dusty = mix(dusty, vec3<f32>(sparse_noise), 0.15);
    dusty = dusty * specks;

    // Final blend: mix input toward dusty layer using mask * strength
    let blend_mask = clamp01(mask_value * str);
    let final_rgb = mix(base_color.rgb, dusty, blend_mask);

    return vec4<f32>(clamp(final_rgb, vec3<f32>(0.0), vec3<f32>(1.0)), base_color.a);
}

/*
 * Halftone - rotated-screen halftone reproduction. See halftone.glsl for
 * the full algorithm derivation; this is a 1:1 port.
 *
 * The explicit rotation expansion below matches GLSL's column-major
 * mat2(co, -si, si, co) multiplication exactly.
 *
 * MODE and PATTERN are compile-time consts injected by the runtime via
 * injectDefines (see definition.js `globals.mode.define` /
 * `globals.pattern.define`). Baking them lets Dawn constant-fold the
 * mode/pattern dispatch instead of carrying a runtime int dispatch through
 * every fragment. They are read bare (not through `uniforms`) and are no
 * longer struct fields.
 */

struct Uniforms {
    frequency: f32,
    cyanAngle: f32,
    magentaAngle: f32,
    yellowAngle: f32,
    blackAngle: f32,
    monoAngle: f32,
    sharpness: f32,
    inkColor: vec3<f32>,
    paperColor: vec3<f32>,
    tileOffset: vec2<f32>,
    fullResolution: vec2<f32>,
}

@group(0) @binding(0) var inputSampler: sampler;
@group(0) @binding(1) var inputTex: texture_2d<f32>;
@group(0) @binding(2) var<uniform> uniforms: Uniforms;

fn lum(c: vec3<f32>) -> f32 {
    return dot(c, vec3<f32>(0.2126, 0.7152, 0.0722));
}

fn tonemap2(t: f32, ink: vec3<f32>, paper: vec3<f32>) -> vec3<f32> {
    return mix(ink, paper, clamp(t, 0.0, 1.0));
}

// Standard CMYK separation with full under-color removal. The shared
// neutral component becomes K, leaving C/M/Y at zero for neutral RGB.
fn rgbToCmyk(rgb: vec3<f32>) -> vec4<f32> {
    let k = 1.0 - max(max(rgb.r, rgb.g), rgb.b);
    let scale = max(1.0 - k, 0.00001);
    let cmy = clamp((1.0 - rgb - vec3<f32>(k)) / scale, vec3<f32>(0.0), vec3<f32>(1.0));
    return vec4<f32>(cmy, k);
}

// See file header: raw-convention rotation for position-derived vectors.
// Calling this with -angleDeg gives the exact inverse rotation, which
// cellSampleFromRuv relies on below.
fn rotate2D(v: vec2<f32>, angleDeg: f32) -> vec2<f32> {
    let a = radians(angleDeg);
    let co = cos(a);
    let si = sin(a);
    return vec2<f32>(co * v.x + si * v.y, -si * v.x + co * v.y);
}

fn boxBlur3(uv: vec2<f32>, texel: vec2<f32>) -> vec3<f32> {
    var sum = vec3<f32>(0.0);
    for (var y = -1; y <= 1; y++) {
        for (var x = -1; x <= 1; x++) {
            let o = vec2<f32>(f32(x), f32(y)) * texel;
            sum += textureSample(inputTex, inputSampler, clamp(uv + o, vec2<f32>(0.0), vec2<f32>(1.0))).rgb;
        }
    }
    return sum / 9.0;
}

// Blurred RGB sampled at the center of the rotated screen cell whose
// already-rotated-and-scaled coordinate is `ruv` (= rotate2D(gc,
// angleDeg) / frequency).
fn cellSampleFromRuv(ruv: vec2<f32>, angleDeg: f32, texel: vec2<f32>) -> vec3<f32> {
    let texSize = vec2<f32>(textureDimensions(inputTex));
    let cellId = floor(ruv) + 0.5;
    let cellCenterGc = rotate2D(cellId * uniforms.frequency, -angleDeg);
    let cellUV = clamp((cellCenterGc - uniforms.tileOffset) / texSize, vec2<f32>(0.0), vec2<f32>(1.0));
    return boxBlur3(cellUV, texel);
}

fn halftoneCoverage(d: f32, value: f32, sharpnessPct: f32) -> f32 {
    let spot = sqrt(clamp(value, 0.0, 1.0)) * 0.7071;
    let softness = 1.0 - clamp(sharpnessPct / 100.0, 0.0, 1.0);
    let aa = max(mix(fwidth(d) * 1.5, 0.35, softness), 0.00001);
    return 1.0 - smoothstep(spot - aa, spot + aa, d);
}

const DOT_AREA_CAP: f32 = 0.50;
const PI: f32 = 3.141592653589793;
const MID_DOT_RADIUS: f32 = 0.39894228;
const MAX_DOT_RADIUS: f32 = 0.48;

fn roundDotCoverage(offset: vec2<f32>, value: f32, sharpnessPct: f32) -> f32 {
    let inkAmount = clamp(value, 0.0, 1.0);
    let centerDistance = length(offset);
    // Branchless form of the low/high dot-radius split. select(f, t, cond) is
    // a true select in WGSL (not an arithmetic blend), so this reproduces
    // both original arms bit-for-bit, including exactly at
    // inkAmount == DOT_AREA_CAP, where the low branch (sqrt formula) is
    // selected - matching the original strict `>` comparison.
    let inkRadius = select(
        sqrt(min(inkAmount, DOT_AREA_CAP) / PI),
        mix(MID_DOT_RADIUS, MAX_DOT_RADIUS,
            (inkAmount - DOT_AREA_CAP) / (1.0 - DOT_AREA_CAP)),
        inkAmount > DOT_AREA_CAP);
    let softness = 1.0 - clamp(sharpnessPct / 100.0, 0.0, 1.0);
    let centerAA = max(mix(fwidth(centerDistance) * 1.5, 0.35, softness), 0.00001);
    let resolvedInk = smoothstep(0.0, 1.0 / 255.0, value);
    return (1.0 - smoothstep(-centerAA, centerAA,
        centerDistance - inkRadius)) * resolvedInk;
}

@fragment
fn main(@builtin(position) pos: vec4<f32>) -> @location(0) vec4<f32> {
    let texSize = vec2<f32>(textureDimensions(inputTex));
    let fullSize = select(texSize, uniforms.fullResolution, uniforms.fullResolution.x > 0.0);
    let globalCoord = pos.xy + uniforms.tileOffset;
    let uv = pos.xy / texSize;
    let texel = 1.0 / texSize;
    let alpha = textureSample(inputTex, inputSampler, uv).a;

    if (MODE == 0) {
        // Subtractive color halftone.
        let ruvC = rotate2D(globalCoord, uniforms.cyanAngle) / uniforms.frequency;
        let ruvM = rotate2D(globalCoord, uniforms.magentaAngle) / uniforms.frequency;
        let ruvY = rotate2D(globalCoord, uniforms.yellowAngle) / uniforms.frequency;
        let ruvK = rotate2D(globalCoord, uniforms.blackAngle) / uniforms.frequency;
        let valC = rgbToCmyk(cellSampleFromRuv(ruvC, uniforms.cyanAngle, texel)).r;
        let valM = rgbToCmyk(cellSampleFromRuv(ruvM, uniforms.magentaAngle, texel)).g;
        let valY = rgbToCmyk(cellSampleFromRuv(ruvY, uniforms.yellowAngle, texel)).b;
        let valK = rgbToCmyk(cellSampleFromRuv(ruvK, uniforms.blackAngle, texel)).a;
        let inkC = roundDotCoverage(fract(ruvC) - 0.5, valC, uniforms.sharpness);
        let inkM = roundDotCoverage(fract(ruvM) - 0.5, valM, uniforms.sharpness);
        let inkY = roundDotCoverage(fract(ruvY) - 0.5, valY, uniforms.sharpness);
        let inkK = roundDotCoverage(fract(ruvK) - 0.5, valK, uniforms.sharpness);
        let screened = (vec3<f32>(1.0) - vec3<f32>(inkC, inkM, inkY)) * (1.0 - inkK);
        return vec4<f32>(screened, alpha);
    }

    // Monochrome screen pattern.
    var value: f32 = 0.0;
    var d: f32 = 0.0;
    var dotOffset = vec2<f32>(0.0);
    if (PATTERN == 2) {
        // circle: concentric rings from the fixed image center, unrotated.
        let center = fullSize * 0.5;
        value = 1.0 - lum(boxBlur3(uv, texel));
        let rd = length(globalCoord - center) / uniforms.frequency;
        d = abs(fract(rd) - 0.5);
    } else {
        let ruv = rotate2D(globalCoord, uniforms.monoAngle) / uniforms.frequency;
        value = 1.0 - lum(cellSampleFromRuv(ruv, uniforms.monoAngle, texel));
        let off = fract(ruv) - 0.5;
        dotOffset = off;
        d = select(length(off), abs(off.y), PATTERN == 1); // 1 = line, else dot
    }
    let ink = select(
        halftoneCoverage(d, value, uniforms.sharpness),
        roundDotCoverage(dotOffset, value, uniforms.sharpness),
        PATTERN == 0);
    return vec4<f32>(tonemap2(1.0 - ink, uniforms.inkColor, uniforms.paperColor), alpha);
}

/*
 * Hatch - single-pass six-mode sketch engine. See glsl/hatch.glsl for the
 * full per-mode algorithm derivation and mode mapping; this is a
 * 1:1 port. MODE is a compile-time const injected by the runtime (see
 * definition.js globals.mode.define), same mechanism as filter/oilPaint
 * and filter/texture.
 *
 * tileOffset converts tile-local positions into the global procedural
 * coordinate gc (floor(pos.xy) + tileOffset) so the hatch pattern is
 * seamless across CLI render tiles, matching glsl/hatch.glsl's gc and
 * filter/stipple's WGSL tileOffset handling. It is zero for ordinary
 * full-frame renders. textureDimensions(inputTex) still stands in for
 * GLSL's resolution elsewhere (uv, lumGradient's texel step).
 *
 * Every stroke-field rotation matches GLSL's column-major
 * mat2(c,-s,s,c) multiplication numerically: (c*x+s*y,-s*x+c*y).
 * Keeping the same transform is required for the selected stroke
 * direction to have the same screen-space slope on both backends.
 * Every noise/hash helper below is built from WGSL's
 * `floor`/`fract`, which - like GLSL's - are floor-based (not truncated)
 * for negative inputs, so the negative positions a rotation can produce
 * need no separate floored-mod wrap.
 */

struct Uniforms {
    strokeLength: f32,
    direction: i32,
    balance: f32,
    pressure: f32,
    inkColor: vec3<f32>,
    paperColor: vec3<f32>,
    tileOffset: vec2<f32>,
}

@group(0) @binding(0) var inputSampler: sampler;
@group(0) @binding(1) var inputTex: texture_2d<f32>;
@group(0) @binding(2) var<uniform> uniforms: Uniforms;

// hash - hash / jitter.
fn hash12(p: vec2<f32>) -> f32 {
    var p3 = fract(vec3<f32>(p.xyx) * 0.1031);
    p3 = p3 + dot(p3, p3.yzx + vec3<f32>(33.33));
    return fract((p3.x + p3.y) * p3.z);
}

// luminance - luminance.
fn lum(c: vec3<f32>) -> f32 {
    return dot(c, vec3<f32>(0.2126, 0.7152, 0.0722));
}

// value noise - value noise + fBm.
fn vnoise(p: vec2<f32>) -> f32 {
    let i = floor(p);
    let f = fract(p);
    let u = f * f * (3.0 - 2.0 * f);
    return mix(mix(hash12(i), hash12(i + vec2<f32>(1.0, 0.0)), u.x),
               mix(hash12(i + vec2<f32>(0.0, 1.0)), hash12(i + vec2<f32>(1.0, 1.0)), u.x), u.y);
}

fn fbm(p_in: vec2<f32>) -> f32 {
    var p = p_in;
    var v = 0.0;
    var a = 0.5;
    for (var i: i32 = 0; i < 5; i++) {
        v += a * vnoise(p);
        p *= 2.03;
        a *= 0.5;
    }
    return v;
}

// Sobel gradient - gradient (Sobel on luminance), used by coloredPencil to bend
// strokes along image contours.
fn lumGradient(uv: vec2<f32>) -> vec2<f32> {
    let texSize = vec2<f32>(textureDimensions(inputTex));
    let px = 1.0 / texSize;
    let tl = lum(textureSample(inputTex, inputSampler, uv + px * vec2<f32>(-1.0,  1.0)).rgb);
    let l  = lum(textureSample(inputTex, inputSampler, uv + px * vec2<f32>(-1.0,  0.0)).rgb);
    let bl = lum(textureSample(inputTex, inputSampler, uv + px * vec2<f32>(-1.0, -1.0)).rgb);
    let tr = lum(textureSample(inputTex, inputSampler, uv + px * vec2<f32>( 1.0,  1.0)).rgb);
    let r  = lum(textureSample(inputTex, inputSampler, uv + px * vec2<f32>( 1.0,  0.0)).rgb);
    let br = lum(textureSample(inputTex, inputSampler, uv + px * vec2<f32>( 1.0, -1.0)).rgb);
    let t  = lum(textureSample(inputTex, inputSampler, uv + px * vec2<f32>( 0.0,  1.0)).rgb);
    let b  = lum(textureSample(inputTex, inputSampler, uv + px * vec2<f32>( 0.0, -1.0)).rgb);
    return vec2<f32>(tr + 2.0 * r + br - tl - 2.0 * l - bl,
                      tl + 2.0 * t + tr - bl - 2.0 * b - br);
}

// ink/paper tonemapping - ink/paper tonemap.
fn tonemap2(t: f32, ink: vec3<f32>, paper: vec3<f32>) -> vec3<f32> {
    return mix(ink, paper, clamp(t, 0.0, 1.0));
}

// Numeric expansion of GLSL mat2(co,-si,si,co) * v.
fn rotate2D(v: vec2<f32>, angleDeg: f32) -> vec2<f32> {
    let a = radians(angleDeg);
    let co = cos(a);
    let si = sin(a);
    return vec2<f32>(co * v.x + si * v.y, -si * v.x + co * v.y);
}

// direction (0..3) -> stroke angle in degrees: rightDiag/horizontal/
// leftDiag/vertical.
fn dirAngle(d: i32) -> f32 {
    if (d == 1) { return 0.0; }
    if (d == 2) { return 135.0; }
    if (d == 3) { return 90.0; }
    return 45.0; // rightDiag (0, default)
}

// Shared stroke field: elongated value noise along angleDeg. See
// hatch.glsl's strokeField for the frequency rationale.
fn strokeField(gc: vec2<f32>, angleDeg: f32, stretchAmt: f32) -> f32 {
    let p = rotate2D(gc, angleDeg) * vec2<f32>(1.0 / stretchAmt, 0.9);
    return vnoise(p);
}

// Per-mode dispatch -- MODE is a compile-time const (Dawn constant-folds),
// mirroring filter/oilPaint's oilPost.wgsl modeColor structure: sequential
// `if (MODE == N) { return ...; }` checks with the last mode (coloredPencil,
// 5) as the unconditional fallback.
fn hatchColor(gc: vec2<f32>, uv: vec2<f32>, src: vec3<f32>, theta: f32, stretchAmt: f32, t: f32, pb: f32, s: f32) -> vec3<f32> {
    if (MODE == 0) {
        // Graphic Pen: see hatch.glsl MODE==0 for the pressure-nudge
        // rationale (zero at pressure=50, matching the core formula).
        let inkMask = step(s, clamp(1.0 - t + pb * 0.3, 0.0, 1.0));
        return tonemap2(1.0 - inkMask, uniforms.inkColor, uniforms.paperColor);
    }
    if (MODE == 1) {
        // Charcoal.
        let s2 = strokeField(gc * 2.0 + 91.7, theta, stretchAmt * 0.5);
        let rough = s * 0.6 + s2 * 0.4;
        let shadow = 1.0 - smoothstep(0.15, 0.55, t);
        let coverage = clamp(shadow + pb * 0.5, 0.0, 1.0);
        let inkMask = step(1.0 - coverage, rough);
        let darkness = mix(0.55, 1.0, uniforms.pressure / 100.0);
        let inkC = mix(uniforms.paperColor, uniforms.inkColor, darkness);
        return mix(uniforms.paperColor, inkC, inkMask);
    }
    if (MODE == 2) {
        // Chalk & Charcoal.
        let midGray = mix(uniforms.inkColor, uniforms.paperColor, 0.5);
        let sBg = strokeField(gc, theta + 90.0, stretchAmt);
        let aa = mix(0.4, 0.04, uniforms.pressure / 100.0);
        let fgGate = 1.0 - smoothstep(0.4 - aa, 0.4 + aa, t);
        let fgMask = step(1.0 - fgGate, s);
        let bgGate = smoothstep(0.6 - aa, 0.6 + aa, t);
        let bgMask = step(1.0 - bgGate, sBg);
        var outc = midGray;
        outc = mix(outc, uniforms.inkColor, fgMask);
        outc = mix(outc, uniforms.paperColor, bgMask);
        return outc;
    }
    if (MODE == 3) {
        // Conte Crayon.
        let toneGate = smoothstep(0.3, 0.7, t);
        let texture2 = mix(s, fbm(gc / (stretchAmt * 0.6) + 41.0), 0.5);
        var level = mix(texture2, toneGate, abs(toneGate * 2.0 - 1.0));
        level = clamp(level + pb * 0.15, 0.0, 1.0);
        return tonemap2(level, uniforms.inkColor, uniforms.paperColor);
    }
    if (MODE == 4) {
        // Crosshatch (color-preserving).
        let s45a = strokeField(gc, theta + 45.0, stretchAmt);
        let s45b = strokeField(gc, theta - 45.0, stretchAmt);
        let band1 = 1.0 - smoothstep(0.65, 0.85, t);
        let band2 = 1.0 - smoothstep(0.35, 0.55, t);
        let band3 = 1.0 - smoothstep(0.05, 0.25, t);
        let darkGain = mix(0.25, 1.0, uniforms.pressure / 100.0);
        let f0 = 1.0 - band1 * darkGain * (1.0 - s);
        let f1 = 1.0 - band2 * darkGain * (1.0 - s45a);
        let f2 = 1.0 - band3 * darkGain * (1.0 - s45b);
        return clamp(src * f0 * f1 * f2, vec3<f32>(0.0), vec3<f32>(1.0));
    }
    // coloredPencil (5) - fallback arm (MODE is always 0-5, injected by
    // the runtime, so the last value needs no explicit check).
    // Color-preserving.
    let grad = lumGradient(uv);
    let gradMag = length(grad);
    let edgeAngle = degrees(atan2(grad.y, grad.x)) + 90.0;
    let sEdge = strokeField(gc, edgeAngle, stretchAmt);
    let edgeBoost = clamp(gradMag * 3.0, 0.0, 1.0);
    let sCombined = mix(s, sEdge, edgeBoost);
    let coverage = clamp((1.0 - t) + pb * 0.4, 0.0, 1.0);
    let strokeMask = step(1.0 - coverage, sCombined);
    return mix(uniforms.paperColor, src, strokeMask);
}

@fragment
fn main(@builtin(position) pos: vec4<f32>) -> @location(0) vec4<f32> {
    let texSize = vec2<f32>(textureDimensions(inputTex));
    let uv = pos.xy / texSize;
    let src = textureSample(inputTex, inputSampler, uv);
    let gc = floor(pos.xy) + uniforms.tileOffset;

    let theta = dirAngle(uniforms.direction);
    let stretchAmt = mix(4.0, 40.0, uniforms.strokeLength / 100.0);
    let t = lum(src.rgb) + (uniforms.balance - 50.0) / 100.0;
    let pb = (uniforms.pressure - 50.0) / 100.0;
    let s = strokeField(gc, theta, stretchAmt);

    let outColor = hatchColor(gc, uv, src.rgb, theta, stretchAmt, t, pb, s);

    return vec4<f32>(clamp(outColor, vec3<f32>(0.0), vec3<f32>(1.0)), src.a);
}

/*
 * High pass - horizontal Gaussian pass
 */

struct Uniforms {
    radius: f32,
}

@group(0) @binding(0) var inputSampler: sampler;
@group(0) @binding(1) var inputTex: texture_2d<f32>;
@group(0) @binding(2) var<uniform> uniforms: Uniforms;

@fragment
fn main(@builtin(position) pos: vec4<f32>) -> @location(0) vec4<f32> {
    let texSize = vec2<f32>(textureDimensions(inputTex));
    let uv = pos.xy / texSize;
    let dirPx = vec2<f32>(1.0, 0.0);
    let sigma = max(uniforms.radius * 0.5, 0.001);
    let fTaps = min(uniforms.radius, 32.0);
    // Beyond 32 taps we can't add more samples (bounded loop), so widen the
    // spacing between them to keep the kernel reaching the full radius.
    let stride = select(1.0, uniforms.radius / 32.0, uniforms.radius > 32.0);
    var sum = textureSample(inputTex, inputSampler, uv);
    var wsum = 1.0;
    for (var i = 1; i <= 32; i++) {
        if (f32(i) > fTaps) { break; }
        let w = exp(-f32(i * i) / (2.0 * sigma * sigma));
        let o = dirPx * f32(i) * stride / texSize;
        sum += (textureSample(inputTex, inputSampler, uv + o)
              + textureSample(inputTex, inputSampler, uv - o)) * w;
        wsum += 2.0 * w;
    }
    return sum / wsum;
}

/*
 * High pass - vertical Gaussian pass
 */

struct Uniforms {
    radius: f32,
}

@group(0) @binding(0) var inputSampler: sampler;
@group(0) @binding(1) var inputTex: texture_2d<f32>;
@group(0) @binding(2) var<uniform> uniforms: Uniforms;

@fragment
fn main(@builtin(position) pos: vec4<f32>) -> @location(0) vec4<f32> {
    let texSize = vec2<f32>(textureDimensions(inputTex));
    let uv = pos.xy / texSize;
    let dirPx = vec2<f32>(0.0, 1.0);
    let sigma = max(uniforms.radius * 0.5, 0.001);
    let fTaps = min(uniforms.radius, 32.0);
    // Beyond 32 taps we can't add more samples (bounded loop), so widen the
    // spacing between them to keep the kernel reaching the full radius.
    let stride = select(1.0, uniforms.radius / 32.0, uniforms.radius > 32.0);
    var sum = textureSample(inputTex, inputSampler, uv);
    var wsum = 1.0;
    for (var i = 1; i <= 32; i++) {
        if (f32(i) > fTaps) { break; }
        let w = exp(-f32(i * i) / (2.0 * sigma * sigma));
        let o = dirPx * f32(i) * stride / texSize;
        sum += (textureSample(inputTex, inputSampler, uv + o)
              + textureSample(inputTex, inputSampler, uv - o)) * w;
        wsum += 2.0 * w;
    }
    return sum / wsum;
}

/*
 * High pass - combine pass
 */

struct Uniforms {
    mono: i32,
}

@group(0) @binding(0) var inputSampler: sampler;
@group(0) @binding(1) var inputTex: texture_2d<f32>;
@group(0) @binding(2) var blurTex: texture_2d<f32>;
@group(0) @binding(3) var<uniform> uniforms: Uniforms;

fn lum(c: vec3<f32>) -> f32 {
    return dot(c, vec3<f32>(0.2126, 0.7152, 0.0722));
}

@fragment
fn main(@builtin(position) pos: vec4<f32>) -> @location(0) vec4<f32> {
    let texSize = vec2<f32>(textureDimensions(inputTex));
    let uv = pos.xy / texSize;
    let src = textureSample(inputTex, inputSampler, uv);
    let blur = textureSample(blurTex, inputSampler, uv);
    let diff = src.rgb - blur.rgb;
    let hp = select(diff + 0.5, vec3<f32>(lum(diff) + 0.5), uniforms.mono != 0);
    return vec4<f32>(clamp(hp, vec3<f32>(0.0), vec3<f32>(1.0)), src.a);
}

