// HSV to RGB conversion
fn hsv_to_rgb(hsv: vec3f) -> vec3f {
    let h = hsv.x;
    let s = hsv.y;
    let v = hsv.z;

    let c = v * s;
    let hp = h * 6.0;
    let x = c * (1.0 - abs(floorMod(hp, 2.0) - 1.0));
    let m = v - c;

    var rgb: vec3f;
    if (hp < 1.0) {
        rgb = vec3f(c, x, 0.0);
    } else if (hp < 2.0) {
        rgb = vec3f(x, c, 0.0);
    } else if (hp < 3.0) {
        rgb = vec3f(0.0, c, x);
    } else if (hp < 4.0) {
        rgb = vec3f(0.0, x, c);
    } else if (hp < 5.0) {
        rgb = vec3f(x, 0.0, c);
    } else {
        rgb = vec3f(c, 0.0, x);
    }

    return rgb + vec3f(m, m, m);
}

// OkLab to linear RGB conversion
fn oklab_to_linear_rgb(lab: vec3f) -> vec3f {
    let L = lab.x;
    let a = lab.y;
    let b = lab.z;

    let l_ = L + 0.3963377774 * a + 0.2158037573 * b;
    let m_ = L - 0.1055613458 * a - 0.0638541728 * b;
    let s_ = L - 0.0894841775 * a - 1.2914855480 * b;

    let l = l_ * l_ * l_;
    let m = m_ * m_ * m_;
    let s = s_ * s_ * s_;

    return vec3f(
        4.0767416621 * l - 3.3077115913 * m + 0.2309699292 * s,
        -1.2684380046 * l + 2.6097574011 * m - 0.3413193965 * s,
        -0.0041960863 * l - 0.7034186147 * m + 1.7076147010 * s
    );
}

// Linear to sRGB conversion (gamma correction)
fn linear_to_srgb(linear: vec3f) -> vec3f {
    let low = linear * 12.92;
    let high = 1.055 * pow(linear, vec3f(1.0 / 2.4)) - 0.055;
    return select(high, low, linear <= vec3f(0.0031308));
}

// Combined OkLab to sRGB
fn oklab_to_rgb(lab: vec3f) -> vec3f {
    var labMod = lab;
    labMod.g = labMod.g * -0.509 + 0.276;
    labMod.b = labMod.b * -0.509 + 0.198;
    let linear_rgb = oklab_to_linear_rgb(labMod);
    return clamp(linear_to_srgb(linear_rgb), vec3f(0.0), vec3f(1.0));
}

// Cosine palette function - IQ formula
fn cosine_palette(t: f32, amp: vec3f, freq: vec3f, offset: vec3f, phase: vec3f) -> vec3f {
    let TAU = 6.283185307179586;
    return clamp(offset + amp * cos(TAU * (freq * t + phase)), vec3f(0.0), vec3f(1.0));
}

@fragment
fn main(@builtin(position) pos: vec4<f32>) -> @location(0) vec4<f32> {
    // Calculate UV from position
    let texSize = vec2<f32>(textureDimensions(inputTex));
    let uv = pos.xy / texSize;

    // Get input color
    let inputColor = textureSample(inputTex, inputSampler, uv);

    // Get uniforms
    let paletteIndex = i32(uniforms.data[0].x);
    let rotation = i32(uniforms.data[0].y);
    let offset = uniforms.data[0].z;
    let repeat = uniforms.data[0].w;
    let time = uniforms.data[1].y;

    // Index 0 is passthrough
    if (paletteIndex <= 0 || paletteIndex > 55) {
        return inputColor;
    }

    // Calculate luminance as the t value
    let lum = dot(inputColor.rgb, vec3f(0.299, 0.587, 0.114));

    // Apply palette modifiers: repeat, offset, and rotation (animation)
    var t = lum * repeat + offset * 0.01;
    if (rotation == -1) {
        t = t + time;
    } else if (rotation == 1) {
        t = t - time;
    }

    // Get palette entry (array is 0-indexed, palette indices are 1-indexed)
    let entry = palettes[paletteIndex - 1];

    // Extract mode from amp.w
    let mode = i32(entry.amp.w + 0.5);

    // Apply cosine palette in the appropriate colorspace
    let paletteColor = cosine_palette(t, entry.amp.xyz, entry.freq.xyz, entry.offset.xyz, entry.phase.xyz);

    // Convert to RGB based on mode
    var finalColor: vec3f;
    if (mode == 1) {
        // HSV mode - palette output is HSV, convert to RGB
        finalColor = hsv_to_rgb(paletteColor);
    } else if (mode == 2) {
        // OkLab mode - palette output is OkLab (L, a, b), convert to RGB
        finalColor = oklab_to_rgb(paletteColor);
    } else {
        // RGB mode (default) - no conversion needed
        finalColor = paletteColor;
    }

    // Blend between original and palette color based on alpha
    let alpha = uniforms.data[1].x;
    let blendedColor = mix(inputColor.rgb, finalColor, alpha);

    return vec4f(blendedColor, inputColor.a);
}

/*
 * Pseudo-3D perspective shift driven by a height map
 * Ray-marched parallax occlusion mapping with a configurable pivot height
 */

struct Uniforms {
    direction: vec3f,
    pivot: f32,
    // No renderScale: the GLSL sibling declares none (parallax has no
    // pixel-fixed-size elements), and the tails must stay matched.
    tileOffset: vec2f,
    fullResolution: vec2f,
}

@group(0) @binding(0) var inputSampler: sampler;
@group(0) @binding(1) var inputTex: texture_2d<f32>;
@group(0) @binding(2) var heightMap: texture_2d<f32>;
@group(0) @binding(3) var<uniform> uniforms: Uniforms;

const MARCH_STEPS: i32 = 32;
const SHIFT_SCALE: f32 = 0.15;

// Convert RGB to luminosity
fn getLuminosity(color: vec3f) -> f32 {
    return dot(color, vec3f(0.299, 0.587, 0.114));
}

fn getHeight(uv: vec2f) -> f32 {
    let mapSize = vec2<f32>(textureDimensions(heightMap));
    let localUV = (uv * uniforms.fullResolution - uniforms.tileOffset) / mapSize;
    return getLuminosity(textureSampleLevel(heightMap, inputSampler, localUV, 0.0).rgb);
}

fn getInput(uv: vec2f) -> vec4f {
    let texSize = vec2<f32>(textureDimensions(inputTex));
    let localUV = (uv * uniforms.fullResolution - uniforms.tileOffset) / texSize;
    return textureSampleLevel(inputTex, inputSampler, localUV, 0.0);
}

@fragment
fn main(@builtin(position) pos: vec4<f32>) -> @location(0) vec4<f32> {
    let globalCoord = pos.xy + uniforms.tileOffset;
    let uv = globalCoord / uniforms.fullResolution;

    var v = vec3f(0.0, 0.0, 1.0);
    if (length(uniforms.direction) > 0.0) {
        v = normalize(uniforms.direction);
    }
    var shift = v.xy * SHIFT_SCALE;

    // Tile rendering: clamp the ray-march shift to the tile overlap budget
    // (absolute pixels in fullResolution space) so displaced samples never
    // leave the tile's rendered region. No-op when tileOffset is zero.
    let isTileRendering = length(uniforms.tileOffset) > 0.0;
    if (isTileRendering) {
        let maxDispPixels: f32 = 256.0;
        let dispPixels = length(shift * uniforms.fullResolution);
        if (dispPixels > maxDispPixels) {
            shift = shift * (maxDispPixels / dispPixels);
        }
    }

    // View ray crosses this fragment's UV at height == pivot
    var t: f32 = 1.0;
    var rayUV = uv + shift * (1.0 - uniforms.pivot);
    var f = t - getHeight(rayUV);

    if (f > 0.0) {
        let stepSize = 1.0 / f32(MARCH_STEPS);
        for (var i: i32 = 1; i <= MARCH_STEPS; i = i + 1) {
            let prevF = f;
            let prevUV = rayUV;
            t = 1.0 - f32(i) * stepSize;
            rayUV = uv + shift * (t - uniforms.pivot);
            f = t - getHeight(rayUV);
            if (f <= 0.0) {
                // Refine: interpolate between the straddling samples
                let w = f / (f - prevF);
                rayUV = mix(rayUV, prevUV, vec2f(w));
                break;
            }
        }
    }

    return getInput(rayUV);
}

/*
 * Patchwork - needlepoint grid of solid-color squares raised by luminance
 * with lit bevel edges. See patchwork.glsl for the full algorithm
 * derivation (center-anchored grid, 3x3 mini-blur cell color, top-face
 * shading, the analytic per-side bevel construction, and the raised-vs-
 * carved polarity check against filter/craquelure); this is a 1:1 port.
 *
 * tileOffset converts the tile-local fragment position to global
 * procedural coordinates, matching GLSL's `gl_FragCoord.xy + tileOffset`:
 * globalCoord anchors the center-anchored grid (relPx/cellIdxF/
 * cellCenter) in full-image space, and toSampleUV subtracts tileOffset
 * back off before dividing by the tile-local texSize, so the 3x3
 * mini-blur and neighbor-cell samples land on the correct texel
 * regardless of which tile is being rendered - matching
 * filter/mosaicTiles' and filter/halftone's WGSL precedent. fullResolution
 * (guarded the same way as filter/texture's globalDims: falls back to
 * texSize when unset) gives imgCenter the TRUE full-image center rather
 * than this tile's own center, so the grid stays continuous across CLI
 * tiles. Both uniforms are zero/unset for ordinary full-frame renders,
 * where tileOffset=(0,0) and fullResolution=texSize reduce every
 * expression below to the previous non-tiling form exactly.
 *
 * cellIdxF/localPx/edgeNormal/imgCenter are all POSITION-DERIVED (built
 * from globalCoord = pos.xy + tileOffset) and ported with NO manual Y
 * compensation, exactly like filter/extrude's center-anchored imgCenter
 * (see extrude.wgsl's header:
 * "No centerY-style flip is needed for the image center itself... same
 * reasoning as pondRipples' fixed center") - the WebGPU present-time flip
 * cancels the raw Y-convention difference for position-derived geometry
 * automatically. lightDir is a plain function of the lightAngle uniform,
 * not fragment-coordinate-derived at all, so it is textually identical to
 * the GLSL, matching filter/relief's rlShade.wgsl
 * and filter/craquelure's WGSL light-vector precedent.
 *
 * cellAvgColor3x3 uses textureSampleLevel (explicit LOD 0), not
 * textureSample: it is called from inside main()'s `dMin < rimPx`
 * branch, whose condition is genuinely per-fragment data (non-uniform
 * control flow) - the same reasoning as filter/extrude's
 * cellAvgColor3x3.wgsl comment. inputTex is a non-mipmapped
 * render-target-style texture, so LOD 0 is exactly GLSL's texture() here.
 */

struct Uniforms {
    squareSize: f32,
    relief: f32,
    lightAngle: f32,
    tileOffset: vec2<f32>,
    fullResolution: vec2<f32>,
}

@group(0) @binding(0) var inputSampler: sampler;
@group(0) @binding(1) var inputTex: texture_2d<f32>;
@group(0) @binding(2) var<uniform> uniforms: Uniforms;

fn lum(c: vec3<f32>) -> f32 {
    return dot(c, vec3<f32>(0.2126, 0.7152, 0.0722));
}

fn toSampleUV(globalPixelPos: vec2<f32>, texSize: vec2<f32>) -> vec2<f32> {
    return clamp((globalPixelPos - uniforms.tileOffset) / texSize, vec2<f32>(0.0), vec2<f32>(1.0));
}

// 3x3 mini-blur centered on a cell - see patchwork.glsl's cellAvgColor3x3.
fn cellAvgColor3x3(centerPx: vec2<f32>, texSize: vec2<f32>) -> vec4<f32> {
    let sp = uniforms.squareSize * 0.25;
    var sum = vec4<f32>(0.0);
    for (var j = -1; j <= 1; j++) {
        for (var i = -1; i <= 1; i++) {
            let p = centerPx + vec2<f32>(f32(i), f32(j)) * sp;
            sum = sum + textureSampleLevel(inputTex, inputSampler, toSampleUV(p, texSize), 0.0);
        }
    }
    return sum * (1.0 / 9.0);
}

@fragment
fn main(@builtin(position) pos: vec4<f32>) -> @location(0) vec4<f32> {
    let texSize = vec2<f32>(textureDimensions(inputTex));
    var fullDims = texSize;
    if (uniforms.fullResolution.x > 0.0) { fullDims = uniforms.fullResolution; }
    let globalCoord = pos.xy + uniforms.tileOffset;
    let uv = pos.xy / texSize;
    let srcOwn = textureSample(inputTex, inputSampler, uv);

    // Center-anchored grid - see patchwork.glsl's header for why.
    let imgCenter = fullDims * 0.5;
    let relPx = globalCoord - imgCenter;
    let cellIdxF = floor(relPx / uniforms.squareSize);
    let localPx = relPx - cellIdxF * uniforms.squareSize;
    let cellCenter = imgCenter + (cellIdxF + 0.5) * uniforms.squareSize;

    let cellColor = cellAvgColor3x3(cellCenter, texSize).rgb;
    let h = lum(cellColor);
    let topFaceShade = 0.9 + 0.2 * (h - 0.5);

    // Distance (px) from this rim pixel to each of the cell's 4 edges.
    let rimPx = 0.15 * uniforms.squareSize;
    let dLeft = localPx.x;
    let dRight = uniforms.squareSize - localPx.x;
    let dBottom = localPx.y;
    let dTop = uniforms.squareSize - localPx.y;
    let dMin = min(min(dLeft, dRight), min(dBottom, dTop));

    var bevelMul = 1.0;
    if (dMin < rimPx) {
        var neighborIdx = cellIdxF;
        var edgeNormal: vec2<f32>;
        if (dMin == dLeft) {
            neighborIdx.x = neighborIdx.x - 1.0;
            edgeNormal = vec2<f32>(-1.0, 0.0);
        } else if (dMin == dRight) {
            neighborIdx.x = neighborIdx.x + 1.0;
            edgeNormal = vec2<f32>(1.0, 0.0);
        } else if (dMin == dBottom) {
            neighborIdx.y = neighborIdx.y - 1.0;
            edgeNormal = vec2<f32>(0.0, -1.0);
        } else {
            neighborIdx.y = neighborIdx.y + 1.0;
            edgeNormal = vec2<f32>(0.0, 1.0);
        }

        let neighborCenter = imgCenter + (neighborIdx + 0.5) * uniforms.squareSize;
        let hNeighbor = lum(cellAvgColor3x3(neighborCenter, texSize).rgb);
        let dh = h - hNeighbor;

        let a = radians(uniforms.lightAngle);
        let lightDir = vec2<f32>(cos(a), sin(a));
        let signTerm = dot(edgeNormal, lightDir);

        // See patchwork.glsl's POLARITY DERIVATION.
        bevelMul = 1.0 + 0.35 * (uniforms.relief / 100.0) * sign(dh) * signTerm;
    }

    let result = clamp(cellColor * topFaceShade * bevelMul, vec3<f32>(0.0), vec3<f32>(1.0));
    return vec4<f32>(result, srcOwn.a);
}

/*
 * Photocopy - horizontal Gaussian pass (see pcBlurH.glsl).
 */

struct Uniforms {
    detail: f32,
}

@group(0) @binding(0) var inputSampler: sampler;
@group(0) @binding(1) var inputTex: texture_2d<f32>;
@group(0) @binding(2) var<uniform> uniforms: Uniforms;

@fragment
fn main(@builtin(position) pos: vec4<f32>) -> @location(0) vec4<f32> {
    let texSize = vec2<f32>(textureDimensions(inputTex));
    let uv = pos.xy / texSize;
    let dirPx = vec2<f32>(1.0, 0.0);
    let radius = mix(1.0, 24.0, (uniforms.detail - 1.0) / 99.0);
    let sigma = max(radius * 0.5, 0.001);
    let fTaps = min(radius, 32.0);
    var sum = textureSample(inputTex, inputSampler, uv);
    var wsum = 1.0;
    for (var i = 1; i <= 32; i++) {
        if (f32(i) > fTaps) { break; }
        let w = exp(-f32(i * i) / (2.0 * sigma * sigma));
        let o = dirPx * f32(i) / texSize;
        sum += (textureSample(inputTex, inputSampler, uv + o)
              + textureSample(inputTex, inputSampler, uv - o)) * w;
        wsum += 2.0 * w;
    }
    return sum / wsum;
}

