struct Uniforms {
    strength: f32,
    aspectLens: i32,
    wrap: i32,
    rotation: f32,
    antialias: i32,
    resolution: vec2<f32>,
    tileOffset: vec2<f32>,
    fullResolution: vec2<f32>,
}

@group(0) @binding(0) var inputSampler: sampler;
@group(0) @binding(1) var inputTex: texture_2d<f32>;
