    // Estimate rank based on samples
    let estimatedRank : f32 = f32(brighterCount) / f32(NUM_SAMPLES);

    // Output: rank (normalized), luminance, original x (normalized)
    return vec4<f32>(estimatedRank, myLum, f32(x) / f32(width - 1), 1.0);
