    let pixelSize = uniforms.size;
    let isTile = length(uniforms.tileOffset) > 0.0;

    if (isTile) {
        let resolution = select(texSize, uniforms.fullResolution, uniforms.fullResolution.x > 0.0);
        let dx = pixelSize / resolution.x;
