    // Non-tiling path: byte-identical to the previous shader.
    let dx = pixelSize / texSize.x;
    let dy = pixelSize / texSize.y;
    var centered = uv - 0.5;
    var coord = vec2<f32>(dx * floor(centered.x / dx), dy * floor(centered.y / dy));
    coord = coord + 0.5;
