    let V = vec3<f32>(0.0, 0.0, 1.0);
    let halfVector = L + V;
    let halfLengthSq = dot(halfVector, halfVector);
    let defaultL = normalize(vec3<f32>(0.4, -0.6, 0.7));
    let defaultHalf = normalize(defaultL + V);
    var H = defaultHalf;
    if (halfLengthSq > 0.000001) {
        H = normalize(halfVector);
    }

    let gloss = mix(24.0, 6.0, uniforms.smoothness / 100.0);
    let flatSpec = pow(H.z, gloss);
    let rawSpec = pow(clamp(dot(n, H), 0.0, 1.0), gloss);
    var spec = clamp((rawSpec - flatSpec) / max(1.0 - flatSpec, 0.0001), 0.0, 1.0);

    let curv = 4.0 * hC - hL - hR - hB - hT;
    let ridge = clamp(curv * strength * 2.0, 0.0, 1.0);
    spec = clamp(spec * 1.35 + ridge * 0.75, 0.0, 1.0);

    let specColor = clamp(vec3<f32>(spec) * (uniforms.highlight / 100.0), vec3<f32>(0.0), vec3<f32>(1.0));
    let outc = vec3<f32>(1.0) - (vec3<f32>(1.0) - src.rgb) * (vec3<f32>(1.0) - specColor);

    return vec4<f32>(outc, src.a);
}

/*
 * Polar and vortex coordinate transforms
 */

struct Uniforms {
    time: f32,
    polarMode: i32,
    speed: f32,
    rotation: f32,
    scale: f32,
    aspectLens: i32,
    antialias: i32,
    _pad3: f32,
    tileOffset: vec2<f32>,
    fullResolution: vec2<f32>,
}

@group(0) @binding(0) var inputSampler: sampler;
@group(0) @binding(1) var inputTex: texture_2d<f32>;
@group(0) @binding(2) var<uniform> uniforms: Uniforms;

const TAU: f32 = 6.28318530718;

fn smod1(v: f32, m: f32) -> f32 {
    return m * (0.75 - abs(fract(v) - 0.5) - 0.25);
}

fn polarCoords(uvIn: vec2<f32>, aspect: f32, doAspect: bool) -> vec2<f32> {
    var uv = uvIn - 0.5;
    if (doAspect) { uv.x = uv.x * aspect; }
    var coord = vec2<f32>(atan2(uv.y, uv.x) / TAU + 0.5, length(uv) - uniforms.scale * 0.075);
    coord.x = smod1(coord.x + uniforms.time * -uniforms.rotation, 1.0);
    coord.y = smod1(coord.y + uniforms.time * uniforms.speed, 1.0);
    return coord;
}

fn vortexCoords(uvIn: vec2<f32>, aspect: f32, doAspect: bool) -> vec2<f32> {
    var uv = uvIn - 0.5;
    if (doAspect) { uv.x = uv.x * aspect; }
    let r2 = dot(uv, uv) - uniforms.scale * 0.01;
    uv = uv / r2;
    uv.x = smod1(uv.x + uniforms.time * -uniforms.rotation, 1.0);
    uv.y = smod1(uv.y + uniforms.time * uniforms.speed, 1.0);
    return uv;
}

@fragment
fn main(@builtin(position) pos: vec4<f32>) -> @location(0) vec4<f32> {
    let tileDims = vec2<f32>(textureDimensions(inputTex));
    let fullRes = select(tileDims, uniforms.fullResolution, uniforms.fullResolution.x > 0.0);
    let uv = (pos.xy + uniforms.tileOffset) / fullRes;
    let aspect = fullRes.x / fullRes.y;
    let doAspect = uniforms.aspectLens != 0;

    var coord: vec2<f32>;
    if (uniforms.polarMode == 0) {
        coord = polarCoords(uv, aspect, doAspect);
    } else {
        coord = vortexCoords(uv, aspect, doAspect);
    }

    if (uniforms.antialias != 0) {
        let dx = dpdx(coord);
        let dy = dpdy(coord);
        var col = vec4<f32>(0.0);
        col += textureSample(inputTex, inputSampler, coord + dx * -0.375 + dy * -0.125);
        col += textureSample(inputTex, inputSampler, coord + dx *  0.125 + dy * -0.375);
        col += textureSample(inputTex, inputSampler, coord + dx *  0.375 + dy *  0.125);
        col += textureSample(inputTex, inputSampler, coord + dx * -0.125 + dy *  0.375);
        return col * 0.25;
    } else {
        return textureSample(inputTex, inputSampler, coord);
    }
}

/*
 * Pond Ripples - concentric ring distortion around the fixed image center.
 * See pondRipples.glsl for the full algorithm derivation; this is a 1:1 port.
 *
 * Tile-aware, mirroring pondRipples.glsl: tileOffset/fullResolution
 * uniforms anchor the ripple center and phase to the full image via
 * globalCoord = pos.xy + tileOffset and a global-frame uv = globalCoord /
 * fullDims (fullDims falls back to texSize, from
 * textureDimensions(inputTex), when fullResolution is unset - guard
 * matches filter/texture's MODE>=5 globalDims pattern). The ripple and
 * rotation math runs entirely in that global frame, then the distorted
 * UV is converted back to tile-local space for the inputTex sample,
 * mirroring GLSL's sampleUV = (uv * fullResolution - tileOffset) /
 * resolution.
 *
 * That final tile-local conversion is additionally gated on
 * isTile = length(tileOffset) > 0.0, which GLSL doesn't need (GLSL has
 * separate resolution/fullResolution uniforms). The runtime sets
 * fullResolution to the canvas size even when not tiling (see
 * pipeline.js updateGlobalUniforms), so fullDims is bit-identical to
 * texSize in the non-tiling case - but an unconditional
 * (uv * fullDims) / texSize round-trip is not guaranteed bit-exact for
 * non-power-of-two sizes (e.g. the 96x96 pinned-hash fixture) under
 * IEEE-754 rounding. Gating on isTile keeps the non-tiling sampleUV
 * identically `uv`, guaranteeing a byte-identical non-tiling path,
 * matching filter/pixels and filter/lensWarp's WGSL precedent.
 *
 * Rotation matches GLSL's column-major mat2(co,-s,s,co)
 * multiplication numerically: (co*x+s*y,-s*x+co*y). This preserves
 * ripple chirality across the presented WebGL2 and WebGPU images.
 *
 * Wrap mode and antialiasing match filter/pinch's
 * WGSL port (already floored-mod safe for mirror/repeat).
 *
 * STYLE and WRAP are compile-time consts injected by the runtime (see
 * definition.js `globals.style.define` / `globals.wrap.define`,
 * injectDefines in webgpu.js). They are intentionally not declared here
 * (injection-only, matching filter/texture's MODE) and are no longer
 * fields of Uniforms below.
 */

struct Uniforms {
    amount: f32,
    ridges: i32,
    speed: i32,
    antialias: i32,
    tileOffset: vec2<f32>,
    fullResolution: vec2<f32>,
    time: f32,
}

@group(0) @binding(0) var inputSampler: sampler;
@group(0) @binding(1) var inputTex: texture_2d<f32>;
@group(0) @binding(2) var<uniform> uniforms: Uniforms;

const PI: f32 = 3.14159265359;

@fragment
fn main(@builtin(position) pos: vec4<f32>) -> @location(0) vec4<f32> {
    let texSize = vec2<f32>(textureDimensions(inputTex));
    var fullDims = texSize;
    if (uniforms.fullResolution.x > 0.0) { fullDims = uniforms.fullResolution; }
    let isTile = length(uniforms.tileOffset) > 0.0;
    let aspectRatio = fullDims.x / fullDims.y;
    let globalCoord = pos.xy + uniforms.tileOffset;
    var uv = globalCoord / fullDims;

    uv = uv - 0.5;
    uv.x = uv.x * aspectRatio;

    let r = length(uv);
    let phase = r * f32(uniforms.ridges) * 2.0 * PI - uniforms.time * 2.0 * PI * f32(uniforms.speed);
    // Clamp the damping term at 0 so corners beyond r=1 (aspect ratios
    // wider/taller than ~1.73:1) don't invert phase and amplify instead
    // of damping.
    let damping = max(0.0, 1.0 - r);
    var w: f32;
    if (uniforms.amount <= 30.0) {
        // Preserve the original 0..30 response, including the exact shipped
        // default expression at amount=30.
        w = sin(phase) * (uniforms.amount / 100.0) * 0.05 * damping;
    } else {
        // Continue smoothly from the original default slope, then accelerate
        // toward a 2.0 gain at amount=100 (twice the previous maximum).
        let x = (uniforms.amount - 30.0) / 70.0;
        let amountGain = 0.3 + 0.7 * x + x * x;
        w = sin(phase) * amountGain * 0.05 * damping;
    }

    var rotDelta: f32 = 0.0;
    var rDelta: f32 = 0.0;
    if (STYLE == 0) {
        // aroundCenter
        rotDelta = w;
    } else if (STYLE == 1) {
        // outFromCenter
        rDelta = w;
    } else {
        // pondRipples: both at half strength
        rotDelta = w * 0.5;
        rDelta = w * 0.5;
    }

    var dir = vec2<f32>(0.0);
    if (r > 0.0) {
        dir = uv / r;
    }

    let rot = rotDelta * 2.0 * PI * 0.25;
    let s = sin(rot);
    let co = cos(rot);
    let rotatedDir = vec2<f32>(co * dir.x + s * dir.y, -s * dir.x + co * dir.y);

    uv = rotatedDir * (r + rDelta);

    uv.x = uv.x / aspectRatio;
    uv = uv + 0.5;

    // Apply wrap mode (floored-mod so negative inputs wrap correctly)
    if (WRAP == 0) {
        // mirror
        uv = abs((uv + 1.0) - 2.0 * floor((uv + 1.0) / 2.0) - 1.0);
    } else if (WRAP == 1) {
        // repeat
        uv = (uv - 1.0 * floor(uv / 1.0));
    } else {
        // clamp
        uv = clamp(uv, vec2<f32>(0.0), vec2<f32>(1.0));
    }

    // Convert distorted global UV back to tile-local for texture sampling,
    // mirroring GLSL's sampleUV = (uv * fullResolution - tileOffset) / resolution.
    // Clamp to tile bounds so wrap modes don't sample past tile coverage.
    // Gated on isTile so the non-tiling path stays exactly `uv` (see header
    // comment for why the round-trip isn't safe to run unconditionally).
    var sampleUV = uv;
    if (isTile) {
        sampleUV = clamp((uv * fullDims - uniforms.tileOffset) / texSize, vec2<f32>(0.0), vec2<f32>(1.0));
    }

    if (uniforms.antialias != 0) {
        let dx = dpdx(sampleUV);
        let dy = dpdy(sampleUV);
        var col = vec4<f32>(0.0);
        col += textureSample(inputTex, inputSampler, sampleUV + dx * -0.375 + dy * -0.125);
        col += textureSample(inputTex, inputSampler, sampleUV + dx *  0.125 + dy * -0.375);
        col += textureSample(inputTex, inputSampler, sampleUV + dx *  0.375 + dy *  0.125);
        col += textureSample(inputTex, inputSampler, sampleUV + dx * -0.125 + dy *  0.375);
        return col * 0.25;
    } else {
        return textureSample(inputTex, inputSampler, sampleUV);
    }
}

/*
 * Posterize: sRGB-aware color quantization with adjustable gamma
 */

struct Uniforms {
    levels: f32,
    gamma: f32,
    antialias: i32,
}

@group(0) @binding(0) var inputSampler: sampler;
@group(0) @binding(1) var inputTex: texture_2d<f32>;
@group(0) @binding(2) var<uniform> uniforms: Uniforms;

const MIN_LEVELS: f32 = 1.0;
const MIN_GAMMA: f32 = 1e-3;

fn clamp_01(value: f32) -> f32 {
    return clamp(value, 0.0, 1.0);
}

fn srgb_to_linear_component(value: f32) -> f32 {
    if (value <= 0.04045) {
        return value / 12.92;
    }
    return pow((value + 0.055) / 1.055, 2.4);
}

fn linear_to_srgb_component(value: f32) -> f32 {
    if (value <= 0.0031308) {
        return value * 12.92;
    }
    return 1.055 * pow(value, 1.0 / 2.4) - 0.055;
}

fn srgb_to_linear_rgb(rgb: vec3<f32>) -> vec3<f32> {
    return vec3<f32>(
        srgb_to_linear_component(rgb.x),
        srgb_to_linear_component(rgb.y),
        srgb_to_linear_component(rgb.z),
    );
}

fn linear_to_srgb_rgb(rgb: vec3<f32>) -> vec3<f32> {
    return vec3<f32>(
        linear_to_srgb_component(rgb.x),
        linear_to_srgb_component(rgb.y),
        linear_to_srgb_component(rgb.z),
    );
}

fn pow_vec3(value: vec3<f32>, exponent: f32) -> vec3<f32> {
    return pow(value, vec3<f32>(exponent));
}

@fragment
fn main(@builtin(position) pos: vec4<f32>) -> @location(0) vec4<f32> {
    let texSize = vec2<f32>(textureDimensions(inputTex, 0));
    let uv = pos.xy / texSize;
    let texel = textureSample(inputTex, inputSampler, uv);

    let levels_raw = max(uniforms.levels, 0.0);
    let levels_quantized = max(round(levels_raw), MIN_LEVELS);
    if (levels_quantized <= 1.0) {
        return texel;
    }

    let level_factor = levels_quantized;
    let inv_factor = 1.0 / level_factor;
    let half_step = inv_factor * 0.5;
    let gamma_value = max(uniforms.gamma, MIN_GAMMA);
    let inv_gamma = 1.0 / gamma_value;

    var working_rgb = srgb_to_linear_rgb(texel.xyz);
    working_rgb = pow_vec3(clamp(working_rgb, vec3<f32>(0.0), vec3<f32>(1.0)), gamma_value);

    // Posterize with optional edge smoothing
    let scaled = working_rgb * level_factor + vec3<f32>(half_step);
    var quantized_rgb: vec3<f32>;
    if (uniforms.antialias != 0) {
        let f = fract(scaled);
        let fw = fwidth(scaled);
        let blend = smoothstep(0.5 - fw * 0.5, 0.5 + fw * 0.5, f);
        quantized_rgb = (floor(scaled) + blend) * inv_factor;
    } else {
        quantized_rgb = floor(scaled) * inv_factor;
    }
    quantized_rgb = pow_vec3(clamp(quantized_rgb, vec3<f32>(0.0), vec3<f32>(1.0)), inv_gamma);

    quantized_rgb = linear_to_srgb_rgb(quantized_rgb);

    return vec4<f32>(
        clamp_01(quantized_rgb.x),
        clamp_01(quantized_rgb.y),
        clamp_01(quantized_rgb.z),
        texel.w,
    );
}

/*
 * Prismatic aberration effect.
 * Ported from classicNoisedeck/lensDistortion.
 */

@group(0) @binding(0) var samp: sampler;
@group(0) @binding(1) var inputTex: texture_2d<f32>;

struct Uniforms {
    time: f32,
    deltaTime: f32,
    frame: i32,
    _pad0: f32,
    resolution: vec2f,
    aspect: f32,
    aberrationAmt: f32,
    modulate: i32,
    hueRotation: f32,
    hueRange: f32,
    saturation: f32,
    passthru: f32,
    tileOffset: vec2f,
    fullResolution: vec2f,
}

@group(0) @binding(2) var<uniform> u: Uniforms;

const PI: f32 = 3.14159265359;
const TAU: f32 = 6.28318530718;

// Floored modulo (matches GLSL mod behavior for negative values)
fn floorMod(x: f32, y: f32) -> f32 {
    return x - y * floor(x / y);
}

fn mapVal(value: f32, inMin: f32, inMax: f32, outMin: f32, outMax: f32) -> f32 {
    return outMin + (outMax - outMin) * (value - inMin) / (inMax - inMin);
}

fn hsv2rgb(hsv: vec3f) -> vec3f {
    let h = fract(hsv.x);
    let s = hsv.y;
    let v = hsv.z;

    let c = v * s;
    let x = c * (1.0 - abs((h * 6.0) % 2.0 - 1.0));
    let m = v - c;

    var rgb: vec3f;

    if (h < 1.0/6.0) {
        rgb = vec3f(c, x, 0.0);
    } else if (h < 2.0/6.0) {
        rgb = vec3f(x, c, 0.0);
    } else if (h < 3.0/6.0) {
        rgb = vec3f(0.0, c, x);
    } else if (h < 4.0/6.0) {
        rgb = vec3f(0.0, x, c);
    } else if (h < 5.0/6.0) {
        rgb = vec3f(x, 0.0, c);
    } else {
        rgb = vec3f(c, 0.0, x);
    }

    return rgb + vec3f(m, m, m);
}

fn rgb2hsv(rgb: vec3f) -> vec3f {
    let r = rgb.r;
    let g = rgb.g;
    let b = rgb.b;

    let maxC = max(r, max(g, b));
    let minC = min(r, min(g, b));
    let delta = maxC - minC;

    var h: f32 = 0.0;
    if (delta != 0.0) {
        if (maxC == r) {
            h = floorMod((g - b) / delta, 6.0) / 6.0;
        } else if (maxC == g) {
            h = ((b - r) / delta + 2.0) / 6.0;
        } else {
            h = ((r - g) / delta + 4.0) / 6.0;
        }
    }
    if (h < 0.0) { h = h + 1.0; }

    var s: f32 = 0.0;
    if (maxC != 0.0) {
        s = delta / maxC;
    }
    let v = maxC;

    return vec3f(h, s, v);
}

fn saturateColor(color: vec3f) -> vec3f {
    let sat = mapVal(u.saturation, -100.0, 100.0, -1.0, 1.0);
    let avg = (color.r + color.g + color.b) / 3.0;
    return color - (avg - color) * sat;
}

@fragment
fn main(@builtin(position) fragCoord: vec4f) -> @location(0) vec4f {
    let aspectRatio = u.fullResolution.x / u.fullResolution.y;
    var uv = (fragCoord.xy + u.tileOffset) / u.fullResolution;
    let texSize = vec2f(textureDimensions(inputTex, 0));

    var color = vec4f(0.0, 0.0, 0.0, 1.0);

    let diff = vec2f(0.5 * aspectRatio, 0.5) - vec2f(uv.x * aspectRatio, uv.y);
    let centerDist = length(diff);

    // No distortion/zoom
    let lensedCoords = uv;

    let aberrationOffset = mapVal(u.aberrationAmt, 0.0, 100.0, 0.0, 0.05) * centerDist * PI * 0.5;

    let redOffset = mix(clamp(lensedCoords.x + aberrationOffset, 0.0, 1.0), lensedCoords.x, lensedCoords.x);
    let red = textureSample(inputTex, samp, (vec2f(redOffset, lensedCoords.y) * u.fullResolution - u.tileOffset) / texSize);

    let green = textureSample(inputTex, samp, (lensedCoords * u.fullResolution - u.tileOffset) / texSize);

    let blueOffset = mix(lensedCoords.x, clamp(lensedCoords.x - aberrationOffset, 0.0, 1.0), lensedCoords.x);
    let blue = textureSample(inputTex, samp, (vec2f(blueOffset, lensedCoords.y) * u.fullResolution - u.tileOffset) / texSize);

    // from aberration
    var hsv = vec3f(1.0);

    var t: f32 = 0.0;
    if (u.modulate != 0) {
        t = u.time;
    }

    // prismatic - get edges
    color = vec4f(vec3f(length(vec4f(red.r, green.g, blue.b, color.a) - green)) * green.rgb, green.a);

    // boost hue range of edges
    hsv = rgb2hsv(color.rgb);
    hsv = vec3f(fract(((hsv.x + 0.125 + (1.0 - (u.hueRotation / 360.0))) * (2.0 + u.hueRange * 0.05)) + t), 1.0, hsv.z);

    // desaturate original
    var greenMod = saturateColor(green.rgb) * mapVal(u.passthru, 0.0, 100.0, 0.0, 2.0);

    // recombine (add)
    color = vec4f(min(greenMod + hsv2rgb(hsv), vec3f(1.0)), color.a);

    return color;
}

// Reindex Pass 3 (Apply): remap pixels using computed global statistics.
const F32_EPSILON : f32 = 0.0001;

@group(0) @binding(0) var inputTex : texture_2d<f32>;
@group(0) @binding(1) var statsTex : texture_2d<f32>;
@group(0) @binding(2) var<uniform> uDisplacement : f32;

fn clamp01(value : f32) -> f32 {
    return clamp(value, 0.0, 1.0);
}

fn srgb_to_linear(value : f32) -> f32 {
    if (value <= 0.04045) {
        return value / 12.92;
    }
    return pow((value + 0.055) / 1.055, 2.4);
}

fn cube_root(value : f32) -> f32 {
    if (value == 0.0) {
        return 0.0;
    }
    let sign_value : f32 = select(-1.0, 1.0, value >= 0.0);
    return sign_value * pow(abs(value), 1.0 / 3.0);
}

fn oklab_l_component(rgb : vec3<f32>) -> f32 {
    let r_lin : f32 = srgb_to_linear(clamp01(rgb.x));
    let g_lin : f32 = srgb_to_linear(clamp01(rgb.y));
    let b_lin : f32 = srgb_to_linear(clamp01(rgb.z));

    let l : f32 = 0.4121656120 * r_lin + 0.5362752080 * g_lin + 0.0514575653 * b_lin;
    let m : f32 = 0.2118591070 * r_lin + 0.6807189584 * g_lin + 0.1074065790 * b_lin;
    let s : f32 = 0.0883097947 * r_lin + 0.2818474174 * g_lin + 0.6302613616 * b_lin;

    let l_c : f32 = cube_root(l);
    let m_c : f32 = cube_root(m);
    let s_c : f32 = cube_root(s);

    let lightness : f32 = 0.2104542553 * l_c + 0.7936177850 * m_c - 0.0040720468 * s_c;
    return clamp01(lightness);
}

fn value_map_component(texel : vec4<f32>) -> f32 {
    return oklab_l_component(texel.xyz);
}

@fragment
fn main(@builtin(position) position : vec4<f32>) -> @location(0) vec4<f32> {
    let dims : vec2<u32> = textureDimensions(inputTex, 0);
    if (dims.x == 0u || dims.y == 0u) {
        return vec4<f32>(0.0);
    }

    let coord : vec2<i32> = vec2<i32>(i32(position.x), i32(position.y));
    if (coord.x < 0 || coord.y < 0 || coord.x >= i32(dims.x) || coord.y >= i32(dims.y)) {
        return vec4<f32>(0.0);
    }

    let texel : vec4<f32> = textureLoad(inputTex, coord, 0);
    let reference_value : f32 = value_map_component(texel);

    let min_max : vec2<f32> = textureLoad(statsTex, vec2<i32>(0, 0), 0).xy;
    let range : f32 = min_max.y - min_max.x;

    var normalized : f32 = reference_value;
    if (range > F32_EPSILON) {
        normalized = clamp01((reference_value - min_max.x) / range);
    }

    let mod_range : f32 = f32(min(dims.x, dims.y));
    let offset_value : f32 = normalized * uDisplacement * mod_range + normalized;
    // Use fract() for smooth wrapping to avoid seams at tile boundaries
    var sample_x : i32 = i32(fract(offset_value / f32(dims.x)) * f32(dims.x));
    var sample_y : i32 = i32(fract(offset_value / f32(dims.y)) * f32(dims.y));

    // Clamp to valid texture coordinates
    sample_x = min(sample_x, i32(dims.x) - 1);
    sample_y = min(sample_y, i32(dims.y) - 1);

    return textureLoad(inputTex, vec2<i32>(sample_x, sample_y), 0);
}

// Reindex Pass 2 (Reduce): collapse tile statistics to a global min/max pair.
const TILE_SIZE : i32 = 8;
const MAX_TILE_DIM : i32 = 512;
const F32_MAX : f32 = 3.402823466e38;
const F32_MIN : f32 = -3.402823466e38;

@group(0) @binding(0) var statsTex : texture_2d<f32>;

@fragment
fn main(@builtin(position) position : vec4<f32>) -> @location(0) vec4<f32> {
    if (i32(position.x) != 0 || i32(position.y) != 0) {
        return vec4<f32>(0.0);
    }

    let stats_tex_size : vec2<i32> = vec2<i32>(textureDimensions(statsTex, 0));
    let tile_count : vec2<i32> = vec2<i32>(
        (stats_tex_size.x + TILE_SIZE - 1) / TILE_SIZE,
        (stats_tex_size.y + TILE_SIZE - 1) / TILE_SIZE
    );

    var global_min : f32 = F32_MAX;
    var global_max : f32 = F32_MIN;

    for (var ty : i32 = 0; ty < MAX_TILE_DIM; ty = ty + 1) {
        if (ty >= tile_count.y) {
            break;
        }
        for (var tx : i32 = 0; tx < MAX_TILE_DIM; tx = tx + 1) {
            if (tx >= tile_count.x) {
                break;
            }
            let sample_coord : vec2<i32> = vec2<i32>(tx * TILE_SIZE, ty * TILE_SIZE);
            let tile_stats : vec2<f32> = textureLoad(statsTex, sample_coord, 0).xy;
            global_min = min(global_min, tile_stats.x);
            global_max = max(global_max, tile_stats.y);
        }
    }

    return vec4<f32>(global_min, global_max, 0.0, 1.0);
}

// Reindex Pass 1 (Stats): compute lightness range per TILE_SIZE tile.
const TILE_SIZE : i32 = 8;
const F32_MAX : f32 = 3.402823466e38;
const F32_MIN : f32 = -3.402823466e38;

@group(0) @binding(0) var inputTex : texture_2d<f32>;

fn clamp01(value : f32) -> f32 {
    return clamp(value, 0.0, 1.0);
}

fn srgb_to_linear(value : f32) -> f32 {
    if (value <= 0.04045) {
        return value / 12.92;
    }
    return pow((value + 0.055) / 1.055, 2.4);
}

fn cube_root(value : f32) -> f32 {
    if (value == 0.0) {
        return 0.0;
    }
    let sign_value : f32 = select(-1.0, 1.0, value >= 0.0);
    return sign_value * pow(abs(value), 1.0 / 3.0);
}

fn oklab_l_component(rgb : vec3<f32>) -> f32 {
    let r_lin : f32 = srgb_to_linear(clamp01(rgb.x));
    let g_lin : f32 = srgb_to_linear(clamp01(rgb.y));
    let b_lin : f32 = srgb_to_linear(clamp01(rgb.z));

    let l : f32 = 0.4121656120 * r_lin + 0.5362752080 * g_lin + 0.0514575653 * b_lin;
    let m : f32 = 0.2118591070 * r_lin + 0.6807189584 * g_lin + 0.1074065790 * b_lin;
    let s : f32 = 0.0883097947 * r_lin + 0.2818474174 * g_lin + 0.6302613616 * b_lin;

    let l_c : f32 = cube_root(l);
    let m_c : f32 = cube_root(m);
    let s_c : f32 = cube_root(s);

    let lightness : f32 = 0.2104542553 * l_c + 0.7936177850 * m_c - 0.0040720468 * s_c;
    return clamp01(lightness);
}

fn value_map_component(texel : vec4<f32>) -> f32 {
    return oklab_l_component(texel.xyz);
}

@fragment
fn main(@builtin(position) position : vec4<f32>) -> @location(0) vec4<f32> {
    let dims : vec2<u32> = textureDimensions(inputTex, 0);
    if (dims.x == 0u || dims.y == 0u) {
        return vec4<f32>(0.0);
    }

    let coord : vec2<i32> = vec2<i32>(i32(position.x), i32(position.y));
    if (coord.x < 0 || coord.y < 0) {
        return vec4<f32>(0.0);
    }

    let local_x : i32 = coord.x % TILE_SIZE;
    let local_y : i32 = coord.y % TILE_SIZE;
    if (local_x != 0 || local_y != 0) {
        return vec4<f32>(0.0);
    }

    var min_value : f32 = F32_MAX;
    var max_value : f32 = F32_MIN;
    let tile_origin : vec2<i32> = coord;
    let width : i32 = i32(dims.x);
    let height : i32 = i32(dims.y);

    for (var oy : i32 = 0; oy < TILE_SIZE; oy = oy + 1) {
        let py : i32 = tile_origin.y + oy;
        if (py >= height) {
            break;
        }
        for (var ox : i32 = 0; ox < TILE_SIZE; ox = ox + 1) {
            let px : i32 = tile_origin.x + ox;
            if (px >= width) {
                break;
            }
            let sample : vec4<f32> = textureLoad(inputTex, vec2<i32>(px, py), 0);
            let value : f32 = value_map_component(sample);
            min_value = min(min_value, value);
            max_value = max(max_value, value);
        }
    }

    return vec4<f32>(min_value, max_value, 0.0, 1.0);
}

/*
 * Relief - horizontal Gaussian pass (see rlBlurH.glsl).
 */

struct Uniforms {
    smoothness: f32,
}

@group(0) @binding(0) var inputSampler: sampler;
@group(0) @binding(1) var inputTex: texture_2d<f32>;
@group(0) @binding(2) var<uniform> uniforms: Uniforms;

@fragment
fn main(@builtin(position) pos: vec4<f32>) -> @location(0) vec4<f32> {
    let texSize = vec2<f32>(textureDimensions(inputTex));
    let uv = pos.xy / texSize;
    let dirPx = vec2<f32>(1.0, 0.0);
    let radius = mix(0.5, 15.0, uniforms.smoothness / 100.0);
    let sigma = max(radius * 0.5, 0.001);
    let fTaps = min(radius, 32.0);
    var sum = textureSample(inputTex, inputSampler, uv);
    var wsum = 1.0;
    for (var i = 1; i <= 32; i++) {
        if (f32(i) > fTaps) { break; }
        let w = exp(-f32(i * i) / (2.0 * sigma * sigma));
        let o = dirPx * f32(i) / texSize;
        sum += (textureSample(inputTex, inputSampler, uv + o)
              + textureSample(inputTex, inputSampler, uv - o)) * w;
        wsum += 2.0 * w;
    }
    return sum / wsum;
}

