        var n = vnoise(noiseP + f32(uniforms.seed) * 101.7);
        n = n + (uniforms.density - 50.0) / 100.0;
        let src = textureSample(inputTex, inputSampler, uv).rgb;
        result = vec3<f32>(step(n, src.r), step(n, src.g), step(n, src.b));
    } else {
