fn hash22(p: vec2<f32>) -> vec2<f32> {
    var p3 = fract(vec3<f32>(p.xyx) * vec3<f32>(0.1031, 0.1030, 0.0973));
    p3 = p3 + dot(p3, p3.yzx + vec3<f32>(33.33));
    return fract((p3.xx + p3.yz) * p3.zy);
}

fn lum(c: vec3<f32>) -> f32 {
    return dot(c, vec3<f32>(0.2126, 0.7152, 0.0722));
}

// Sobel gradient - gradient (Sobel on luminance); smudge (MODE 4) only. Backend-
// agnostic constant kernel offsets - textually identical to GLSL, no
// flip (see file header, filter/hatch's lumGradient). Called once per
// pixel outside smear()'s loop (uniform control flow either way), so
// textureSampleLevel isn't required here the way it is below - switched
// anyway for file-wide consistency with the loop-adjacent helpers (same
// non-mipmapped render-target texture, so LOD 0 is numerically identical
// to textureSample's implicit LOD).
fn lumGradient(uv: vec2<f32>) -> vec2<f32> {
    let texSize = vec2<f32>(textureDimensions(inputTex));
    let px = 1.0 / texSize;
    let tl = lum(textureSampleLevel(inputTex, inputSampler, uv + px * vec2<f32>(-1.0,  1.0), 0.0).rgb);
    let l  = lum(textureSampleLevel(inputTex, inputSampler, uv + px * vec2<f32>(-1.0,  0.0), 0.0).rgb);
    let bl = lum(textureSampleLevel(inputTex, inputSampler, uv + px * vec2<f32>(-1.0, -1.0), 0.0).rgb);
    let tr = lum(textureSampleLevel(inputTex, inputSampler, uv + px * vec2<f32>( 1.0,  1.0), 0.0).rgb);
    let r  = lum(textureSampleLevel(inputTex, inputSampler, uv + px * vec2<f32>( 1.0,  0.0), 0.0).rgb);
    let br = lum(textureSampleLevel(inputTex, inputSampler, uv + px * vec2<f32>( 1.0, -1.0), 0.0).rgb);
    let t  = lum(textureSampleLevel(inputTex, inputSampler, uv + px * vec2<f32>( 0.0,  1.0), 0.0).rgb);
    let b  = lum(textureSampleLevel(inputTex, inputSampler, uv + px * vec2<f32>( 0.0, -1.0), 0.0).rgb);
    return vec2<f32>(tr + 2.0 * r + br - tl - 2.0 * l - bl,
                      tl + 2.0 * t + tr - bl - 2.0 * b - br);
}

// Numeric expansion of GLSL mat2(co,-si,si,co) * v.
fn rotate2D(v: vec2<f32>, angleDeg: f32) -> vec2<f32> {
    let a = radians(angleDeg);
    let co = cos(a);
    let si = sin(a);
    return vec2<f32>(co * v.x + si * v.y, -si * v.x + co * v.y);
}

fn strokeVariation(gc: vec2<f32>, dirUnit: vec2<f32>, runBase: f32) -> f32 {
    let across = vec2<f32>(-dirUnit.y, dirUnit.x);
    let strokeSpace = vec2<f32>(
        dot(gc, dirUnit) / max(runBase, 3.0),
        dot(gc, across) / 3.5,
    );
    return 0.72 + 0.56 * valueNoise2(strokeSpace * 0.65);
}

fn brushStrokeField(uv: vec2<f32>, gc: vec2<f32>, dirUnit: vec2<f32>, runBase: f32) -> vec4<f32> {
    let across = vec2<f32>(-dirUnit.y, dirUnit.x);
    let oriented = vec2<f32>(dot(gc, dirUnit), dot(gc, across));
    let spacing = vec2<f32>(max(runBase * 0.70, 4.0), 4.5);
    let baseCell = floor(oriented / spacing);
    var field = 0.0;
    var pigmentSum = vec3<f32>(0.0);
    var pigmentWeight = 0.0;
    for (var cy: i32 = -1; cy <= 1; cy++) {
        for (var cx: i32 = -1; cx <= 1; cx++) {
            let cell = baseCell + vec2<f32>(f32(cx), f32(cy));
            let jitter = hash22(cell + vec2<f32>(17.3)) - vec2<f32>(0.5);
            let center = (cell + vec2<f32>(0.5) + jitter * vec2<f32>(0.56, 0.40)) * spacing;
            let delta = oriented - center;
            let angle = (hash12(cell + vec2<f32>(29.1)) - 0.5) * 0.34;
            let co = cos(angle);
            let si = sin(angle);
            let local = vec2<f32>(co * delta.x + si * delta.y,
                                  -si * delta.x + co * delta.y);
            let halfLength = runBase * (0.35 + 0.18 * hash12(cell + vec2<f32>(43.7)));
            let halfWidth = 1.4 + 1.2 * hash12(cell + vec2<f32>(71.9));
            let capsule = length(vec2<f32>(max(abs(local.x) - halfLength, 0.0), local.y)) - halfWidth;
            // Pixel-space analytic AA remains stable when baseCell changes.
            let aa = 1.35;
            let body = 1.0 - smoothstep(-aa, aa, capsule);
            let bristle = 0.78 + 0.22 * (0.5 + 0.5 *
                sin(local.y * 5.2 + hash12(cell + vec2<f32>(97.3)) * 6.2831853));
            let mark = body * bristle;
            let centerGlobal = dirUnit * center.x + across * center.y;
            let centerUV = uv + (centerGlobal - gc) / vec2<f32>(textureDimensions(inputTex));
            pigmentSum += srcSample(centerUV).rgb * mark;
            pigmentWeight += mark;
            field = max(field, mark);
        }
    }
    var pigment = srcSample(uv).rgb;
    if (pigmentWeight > 0.0001) {
        pigment = pigmentSum / pigmentWeight;
    }
    return vec4<f32>(pigment, clamp(field, 0.0, 1.0));
}

fn sprayJitter(gc: vec2<f32>, tap: f32) -> vec2<f32> {
    let p = gc / 7.0;
    return vec2<f32>(
        valueNoise2(p + vec2<f32>(tap * 0.73, 7.0)),
        valueNoise2(p + vec2<f32>(11.0, tap * 0.79) + vec2<f32>(37.1)),
    ) - vec2<f32>(0.5);
}

fn srcSample(sampleUV: vec2<f32>) -> vec4<f32> {
    if (MODE == 3) {
        // Sumi-e reads a locally ERODED source, so the directional smear spreads
        // expanded dark ink exactly like the two-pass original (which smeared a
        // precomputed 3x3 min). A 4-neighbour cross min approximates that erosion
        // inline. Matches glsl/stkSmear.glsl; MODE-gated so other variants pay
        // nothing.
        let px = 1.0 / vec2<f32>(textureDimensions(inputTex));
        let s = textureSampleLevel(inputTex, inputSampler, sampleUV, 0.0);
        var e = s.rgb;
        e = min(e, textureSampleLevel(inputTex, inputSampler, sampleUV + vec2<f32>(px.x, 0.0), 0.0).rgb);
        e = min(e, textureSampleLevel(inputTex, inputSampler, sampleUV - vec2<f32>(px.x, 0.0), 0.0).rgb);
        e = min(e, textureSampleLevel(inputTex, inputSampler, sampleUV + vec2<f32>(0.0, px.y), 0.0).rgb);
        e = min(e, textureSampleLevel(inputTex, inputSampler, sampleUV - vec2<f32>(0.0, px.y), 0.0).rgb);
        return vec4<f32>(e, s.a);
    }
    return textureSampleLevel(inputTex, inputSampler, sampleUV, 0.0);
}

// Bounded directional accumulation - see glsl/stkSmear.glsl's smear() for
// the full algorithm description.
//
// L varies across a coherent stroke field, so a data-dependent `if (fi > L) {
// break; }` makes every srcSample() call reached after the
// break non-uniform control flow. That's fine for textureSampleLevel
// (explicit LOD, no derivatives/uniformity requirement) but a hard
// rejection for plain textureSample ("must only be called from uniform
// control flow" -- caught by the real-browser harness; MCP's compile
// check does not enforce this). Fix: every srcSample()-routed fetch below
// uses textureSampleLevel, so the break is legal and taps past L are never
// sampled --
// restores the original early-exit cost profile instead of paying for
// MAX_TAPS iterations on every pixel regardless of L. Numerically a
// no-op vs. always running the full loop and multiplicatively zeroing
// out-of-range taps (w == 0 either contributes nothing or isn't computed
// at all -- same sum, same wsum, bit-for-bit), so this is a pure
// performance fix, not a behavior change. Applied identically in the
// GLSL file (which never needed the mask -- GLSL has no uniform-control-
// flow requirement on texture()).
fn smear(uv: vec2<f32>, gc: vec2<f32>, dirUnit: vec2<f32>, L: f32, jitterPx: f32) -> vec4<f32> {
    let texSize = vec2<f32>(textureDimensions(inputTex));
    let px = 1.0 / texSize;
    var sum = srcSample(uv);
    var wsum = 1.0;
    for (var i: i32 = 1; i <= MAX_TAPS; i++) {
        let fi = f32(i);
        if (fi > L) { break; }
        let w = exp(-2.0 * fi / L);
        var jp = vec2<f32>(0.0);
        var jn = vec2<f32>(0.0);
        if (jitterPx > 0.0) {
            jp = sprayJitter(gc, fi) * jitterPx;
            jn = sprayJitter(gc + vec2<f32>(31.7), -fi) * jitterPx;
        }
        let sampP = uv + (dirUnit * fi) * px + jp * px;
        let sampN = uv - (dirUnit * fi) * px + jn * px;
        sum += (srcSample(sampP) + srcSample(sampN)) * w;
        wsum += 2.0 * w;
    }
    return sum / wsum;
}

// Per-mode dispatch - mirrors filter/hatch's hatchColor / filter/oilPaint's
// modeColor structure (sequential if (MODE == N) checks, last mode as the
// unconditional fallback).
fn smearColor(uv: vec2<f32>, gc: vec2<f32>, src: vec4<f32>, runBase: f32) -> vec4<f32> {
    if (MODE == 0) {
        // Angled Strokes.
        let dir45 = rotate2D(vec2<f32>(1.0, 0.0), 45.0);
        let dir135 = rotate2D(vec2<f32>(1.0, 0.0), 135.0);
        let l45 = runBase * strokeVariation(gc, dir45, runBase);
        let l135 = runBase * strokeVariation(gc, dir135, runBase);
        let layer45 = brushStrokeField(uv, gc, dir45, runBase);
        let layer135 = brushStrokeField(uv, gc, dir135, runBase);
        let pigment45 = mix(smear(uv, gc, dir45, l45, 0.0), vec4<f32>(layer45.rgb, src.a), 0.72);
        let pigment135 = mix(smear(uv, gc, dir135, l135, 0.0), vec4<f32>(layer135.rgb, src.a), 0.72);
        let field45 = mix(src, pigment45, layer45.a);
        let field135 = mix(src, pigment135, layer135.a);
        let b = uniforms.balance / 100.0;
        let side = smoothstep(b - 0.1, b + 0.1, lum(src.rgb));
        return mix(field135, field45, side);
    }
    if (MODE == 1) {
        // Sprayed Strokes.
        let dir45 = rotate2D(vec2<f32>(1.0, 0.0), 45.0);
        let L = runBase * strokeVariation(gc, dir45, runBase);
        let jitterPx = uniforms.intensity / 100.0 * 6.0;
        let layer = brushStrokeField(uv, gc, dir45, runBase);
        let pigment = mix(smear(uv, gc, dir45, L, jitterPx), vec4<f32>(layer.rgb, src.a), 0.68);
        return mix(src, pigment, layer.a);
    }
    if (MODE == 2) {
        // Dark Strokes.
        let dir45 = rotate2D(vec2<f32>(1.0, 0.0), 45.0);
        let L = runBase * strokeVariation(gc, dir45, runBase);
        let layer = brushStrokeField(uv, gc, dir45, runBase);
        let pigment = mix(smear(uv, gc, dir45, L, 0.0), vec4<f32>(layer.rgb, src.a), 0.72);
        let c = mix(src, pigment, layer.a);
        let t = lum(c.rgb);
        let bAmt = uniforms.balance / 100.0;
        let exponent = select(1.0 / (1.0 + uniforms.intensity / 100.0), 1.0 + uniforms.intensity / 50.0, t < bAmt);
        return vec4<f32>(pow(max(c.rgb, vec3<f32>(0.0)), vec3<f32>(exponent)), c.a);
    }
    if (MODE == 3) {
        // Sumi-e: srcSample() returns a locally eroded source (see above), so
        // this 135deg directional smear spreads expanded dark ink along the
        // brush -- the wet-ink look of the two-pass original, in one pass.
        // Matches glsl/stkSmear.glsl. A contrast-only curve finishes it.
        let dir135 = rotate2D(vec2<f32>(1.0, 0.0), 135.0);
        let L = runBase * strokeVariation(gc, dir135, runBase);
        let layer = brushStrokeField(uv, gc, dir135, runBase);
        let pigment = mix(smear(uv, gc, dir135, L, 0.0), vec4<f32>(layer.rgb, src.a), 0.74);
        let c = mix(src, pigment, layer.a);
        return vec4<f32>(pow(max(c.rgb, vec3<f32>(0.0)), vec3<f32>(1.0 + uniforms.intensity / 50.0)), c.a);
    }
    // Smudge Stick (4) - fallback arm (MODE always 0-4, injected by the
    // runtime, so the last value needs no explicit check).
    let grad = lumGradient(uv);
    let gradMag = length(grad);
    let edgeAngle = select(45.0, degrees(atan2(grad.y, grad.x)) + 90.0, gradMag > 1e-5);
    let dir = rotate2D(vec2<f32>(1.0, 0.0), edgeAngle);
    let L = runBase * strokeVariation(gc, dir, runBase);
    let layer = brushStrokeField(uv, gc, dir, runBase);
    let pigment = mix(smear(uv, gc, dir, L, 0.0), vec4<f32>(layer.rgb, src.a), 0.64);
    let smeared = mix(src, pigment, layer.a);
    let shadowMask = 1.0 - smoothstep(0.55, 0.65, lum(src.rgb));
    return mix(src, smeared, shadowMask);
}

@fragment
fn main(@builtin(position) pos: vec4<f32>) -> @location(0) vec4<f32> {
    let texSize = vec2<f32>(textureDimensions(inputTex));
    let uv = pos.xy / texSize;
    let src = textureSample(inputTex, inputSampler, uv);
    let gc = pos.xy + uniforms.tileOffset;

    let runBase = mix(3.0, 50.0, uniforms.strokeLength / 100.0);
    let outc = smearColor(uv, gc, src, runBase);

    return vec4<f32>(clamp(outc.rgb, vec3<f32>(0.0), vec3<f32>(1.0)), src.a);
}

/*
 * Temporal Chromatic Aberration - shift pass (WGSL).
 * Mirrors glsl/delayShift.glsl: copies one stage of the bucket-brigade delay line into the
 * next, preserving alpha so the "filled" frontier advances one stage per frame.
 */

@group(0) @binding(0) var samp : sampler;
@group(0) @binding(1) var srcTex : texture_2d<f32>;

@fragment
fn main(@builtin(position) pos : vec4<f32>) -> @location(0) vec4<f32> {
    let texSize = vec2<f32>(textureDimensions(srcTex, 0));
    let uv = pos.xy / texSize;
    return textureSampleLevel(srcTex, samp, uv, 0.0);
}

/*
 * Temporal Chromatic Aberration - read pass (WGSL).
 * Mirrors glsl/temporalAberration.glsl: samples the live frame (delay 0) and the eight
 * history stages _h1.._h8 (delay 1..8), then builds each output channel from an
 * independently, fractionally delayed frame. Empty history slots (alpha 0) fall back to
 * the live frame for a clean ramp-in.
 */

struct Uniforms {
    // data[0] = (redDelay, greenDelay, blueDelay, unused)
    data : array<vec4<f32>, 1>,
};

@group(0) @binding(0) var<uniform> uniforms : Uniforms;
@group(0) @binding(1) var samp : sampler;
@group(0) @binding(2) var inputTex : texture_2d<f32>;
@group(0) @binding(3) var h1 : texture_2d<f32>;
@group(0) @binding(4) var h2 : texture_2d<f32>;
@group(0) @binding(5) var h3 : texture_2d<f32>;
@group(0) @binding(6) var h4 : texture_2d<f32>;
@group(0) @binding(7) var h5 : texture_2d<f32>;
@group(0) @binding(8) var h6 : texture_2d<f32>;
@group(0) @binding(9) var h7 : texture_2d<f32>;
@group(0) @binding(10) var h8 : texture_2d<f32>;

@fragment
fn main(@builtin(position) pos : vec4<f32>) -> @location(0) vec4<f32> {
    let redDelay = uniforms.data[0].x;
    let greenDelay = uniforms.data[0].y;
    let blueDelay = uniforms.data[0].z;

    let texSize = vec2<f32>(textureDimensions(inputTex, 0));
    let uv = pos.xy / texSize;

    let cur = textureSampleLevel(inputTex, samp, uv, 0.0);

    // slots[0] = live (delay 0); slots[1..8] = history (delay 1..8) with empty -> live.
    var slots : array<vec4<f32>, 9>;
    slots[0] = cur;
    var s : vec4<f32>;
    s = textureSampleLevel(h1, samp, uv, 0.0); slots[1] = select(s, cur, s.a < 0.5);
    s = textureSampleLevel(h2, samp, uv, 0.0); slots[2] = select(s, cur, s.a < 0.5);
    s = textureSampleLevel(h3, samp, uv, 0.0); slots[3] = select(s, cur, s.a < 0.5);
    s = textureSampleLevel(h4, samp, uv, 0.0); slots[4] = select(s, cur, s.a < 0.5);
    s = textureSampleLevel(h5, samp, uv, 0.0); slots[5] = select(s, cur, s.a < 0.5);
    s = textureSampleLevel(h6, samp, uv, 0.0); slots[6] = select(s, cur, s.a < 0.5);
    s = textureSampleLevel(h7, samp, uv, 0.0); slots[7] = select(s, cur, s.a < 0.5);
    s = textureSampleLevel(h8, samp, uv, 0.0); slots[8] = select(s, cur, s.a < 0.5);

    let dr = clamp(redDelay, 0.0, 8.0);
    let ir0 = i32(floor(dr));
    let ir1 = min(ir0 + 1, 8);
    let rOut = mix(slots[ir0], slots[ir1], dr - f32(ir0)).r;

    let dg = clamp(greenDelay, 0.0, 8.0);
    let ig0 = i32(floor(dg));
    let ig1 = min(ig0 + 1, 8);
    let gOut = mix(slots[ig0], slots[ig1], dg - f32(ig0)).g;

    let db = clamp(blueDelay, 0.0, 8.0);
    let ib0 = i32(floor(db));
    let ib1 = min(ib0 + 1, 8);
    let bOut = mix(slots[ib0], slots[ib1], db - f32(ib0)).b;

    return vec4<f32>(rOut, gOut, bOut, cur.a);
}

/**
 * Tetra Color Array Gradient - WGSL Fragment Shader
 *
 * Applies a discrete color array gradient to the input image based on luminance.
 * Supports up to 8 colors with manual or auto-positioned stops.
 * Supports RGB, HSV, OkLab, and OKLCH color modes.
 */

struct Uniforms {
    data: array<vec4<f32>, 12>,
    // data[0].x = colorMode, data[0].y = colorCount, data[0].z = positionMode, data[0].w = repeat
    // data[1].x = offset (mapping), data[1].y = alpha, data[1].z = smoothness, data[1].w = rotation
    // data[2].w = time (global, auto-provided)
    // data[2].xyz = color0 (rgb)
    // data[3].xyz = color1 (rgb)
    // data[4].xyz = color2 (rgb)
    // data[5].xyz = color3 (rgb)
    // data[6].xyz = color4 (rgb)
    // data[7].xyz = color5 (rgb)
    // data[8].xyz = color6 (rgb)
    // data[9].xyz = color7 (rgb)
    // data[10].xyzw = positions 0-3
    // data[11].xyzw = positions 4-7
}

@group(0) @binding(0) var samp: sampler;
@group(0) @binding(1) var inputTex: texture_2d<f32>;
@group(0) @binding(2) var<uniform> uniforms: Uniforms;

const TAU: f32 = 6.283185307179586;

// ============================================================================
// Color Space Conversions
// ============================================================================

// --- RGB <-> HSV ---

fn hsv2rgb(hsv: vec3<f32>) -> vec3<f32> {
    let h = hsv.x;
    let s = hsv.y;
    let v = hsv.z;

    let c = v * s;
    let hp = h * 6.0;
    let x = c * (1.0 - abs(hp % 2.0 - 1.0));
    let m = v - c;

    var rgb: vec3<f32>;
    if (hp < 1.0) {
        rgb = vec3<f32>(c, x, 0.0);
    } else if (hp < 2.0) {
        rgb = vec3<f32>(x, c, 0.0);
    } else if (hp < 3.0) {
        rgb = vec3<f32>(0.0, c, x);
    } else if (hp < 4.0) {
        rgb = vec3<f32>(0.0, x, c);
    } else if (hp < 5.0) {
        rgb = vec3<f32>(x, 0.0, c);
    } else {
        rgb = vec3<f32>(c, 0.0, x);
    }

    return rgb + vec3<f32>(m);
}

fn rgb2hsv(c: vec3<f32>) -> vec3<f32> {
    let cmax = max(c.r, max(c.g, c.b));
    let cmin = min(c.r, min(c.g, c.b));
    let delta = cmax - cmin;

    var h: f32 = 0.0;
    if (delta > 0.0) {
        if (cmax == c.r) {
            h = ((c.g - c.b) / delta % 6.0) / 6.0;
        } else if (cmax == c.g) {
            h = ((c.b - c.r) / delta + 2.0) / 6.0;
        } else {
            h = ((c.r - c.g) / delta + 4.0) / 6.0;
        }
        h = fract(h);
    }
    let s = select(0.0, delta / cmax, cmax > 0.0);
    return vec3<f32>(h, s, cmax);
}

// --- Gamma transfer ---

fn linear2srgb(lin: vec3<f32>) -> vec3<f32> {
    let low = lin * 12.92;
    let high = 1.055 * pow(max(lin, vec3<f32>(0.0)), vec3<f32>(1.0 / 2.4)) - 0.055;
    return select(high, low, lin < vec3<f32>(0.0031308));
}

fn srgb2linear(c: vec3<f32>) -> vec3<f32> {
    let low = c / 12.92;
    let high = pow((c + 0.055) / 1.055, vec3<f32>(2.4));
    return select(high, low, c < vec3<f32>(0.04045));
}

// --- OkLab core ---

fn oklab2linear(lab: vec3<f32>) -> vec3<f32> {
    let l_ = lab.x + 0.3963377774 * lab.y + 0.2158037573 * lab.z;
    let m_ = lab.x - 0.1055613458 * lab.y - 0.0638541728 * lab.z;
    let s_ = lab.x - 0.0894841775 * lab.y - 1.2914855480 * lab.z;

    let l = l_ * l_ * l_;
    let m = m_ * m_ * m_;
    let s = s_ * s_ * s_;

    return vec3<f32>(
        4.0767416621 * l - 3.3077115913 * m + 0.2309699292 * s,
        -1.2684380046 * l + 2.6097574011 * m - 0.3413193965 * s,
        -0.0041960863 * l - 0.7034186147 * m + 1.7076147010 * s
    );
}

fn linear2oklab(lin: vec3<f32>) -> vec3<f32> {
    let l = 0.4122214708 * lin.r + 0.5363325363 * lin.g + 0.0514459929 * lin.b;
    let m = 0.2119034982 * lin.r + 0.6806995451 * lin.g + 0.1073969566 * lin.b;
    let s = 0.0883024619 * lin.r + 0.2817188376 * lin.g + 0.6299787005 * lin.b;

    let l_ = pow(max(l, 0.0), 1.0 / 3.0);
    let m_ = pow(max(m, 0.0), 1.0 / 3.0);
    let s_ = pow(max(s, 0.0), 1.0 / 3.0);

    return vec3<f32>(
        0.2104542553 * l_ + 0.7936177850 * m_ - 0.0040720468 * s_,
        1.9779984951 * l_ - 2.4285922050 * m_ + 0.4505937099 * s_,
        0.0259040371 * l_ + 0.7827717662 * m_ - 0.8086757660 * s_
    );
}

// --- RGB <-> OkLab ---

fn oklab2rgb(lab: vec3<f32>) -> vec3<f32> {
    return clamp(linear2srgb(oklab2linear(lab)), vec3<f32>(0.0), vec3<f32>(1.0));
}

fn rgb2oklab(rgb: vec3<f32>) -> vec3<f32> {
    return linear2oklab(srgb2linear(rgb));
}

// --- RGB <-> OKLCH (L, C, H where H is 0-1 fractional turns) ---

fn oklch2rgb(lch: vec3<f32>) -> vec3<f32> {
    let a = lch.y * cos(lch.z * TAU);
    let b = lch.y * sin(lch.z * TAU);
    return clamp(linear2srgb(oklab2linear(vec3<f32>(lch.x, a, b))), vec3<f32>(0.0), vec3<f32>(1.0));
}

fn rgb2oklch(rgb: vec3<f32>) -> vec3<f32> {
    let lab = rgb2oklab(rgb);
    let C = length(lab.yz);
    let h = atan2(lab.z, lab.y);
    return vec3<f32>(lab.x, C, fract(h / TAU));
}

// --- Dispatch by mode ---

fn rgbToColorSpace(rgb: vec3<f32>, mode: i32) -> vec3<f32> {
    if (mode == 1) { return rgb2hsv(rgb); }
    if (mode == 2) { return rgb2oklab(rgb); }
    if (mode == 3) { return rgb2oklch(rgb); }
    return rgb;
}

fn colorSpaceToRgb(color: vec3<f32>, mode: i32) -> vec3<f32> {
    if (mode == 1) { return hsv2rgb(color); }
    if (mode == 2) { return oklab2rgb(color); }
    if (mode == 3) { return oklch2rgb(color); }
    return color;
}

// ============================================================================
// Color Array Helpers
// ============================================================================

fn getColor(index: i32) -> vec4<f32> {
    switch (index) {
        case 0: { return uniforms.data[2]; }
        case 1: { return uniforms.data[3]; }
        case 2: { return uniforms.data[4]; }
        case 3: { return uniforms.data[5]; }
        case 4: { return uniforms.data[6]; }
        case 5: { return uniforms.data[7]; }
        case 6: { return uniforms.data[8]; }
        case 7: { return uniforms.data[9]; }
        default: { return uniforms.data[2]; }
    }
}

fn getPosition(index: i32, colorCount: i32, positionMode: i32) -> f32 {
    // Auto mode: evenly distribute
    if (positionMode == 0) {
        if (colorCount <= 1) {
            return 0.0;
        }
        return f32(index) / f32(colorCount - 1);
    }

    // Manual mode: use stored positions
    switch (index) {
        case 0: { return uniforms.data[10].x; }
        case 1: { return uniforms.data[10].y; }
        case 2: { return uniforms.data[10].z; }
        case 3: { return uniforms.data[10].w; }
        case 4: { return uniforms.data[11].x; }
        case 5: { return uniforms.data[11].y; }
        case 6: { return uniforms.data[11].z; }
        case 7: { return uniforms.data[11].w; }
        default: { return 0.0; }
    }
}

// Interpolate in color space with shortest-path hue for HSV/OKLCH
fn mixInColorSpace(a: vec3<f32>, b: vec3<f32>, f: f32, mode: i32) -> vec3<f32> {
    if (mode == 1) {
        // HSV: hue is .x
        var dh = b.x - a.x;
        if (dh > 0.5) { dh -= 1.0; }
        if (dh < -0.5) { dh += 1.0; }
        return vec3<f32>(fract(a.x + dh * f), mix(a.y, b.y, f), mix(a.z, b.z, f));
    } else if (mode == 3) {
        // OKLCH: hue is .z
        var dh = b.z - a.z;
        if (dh > 0.5) { dh -= 1.0; }
        if (dh < -0.5) { dh += 1.0; }
        return vec3<f32>(mix(a.x, b.x, f), mix(a.y, b.y, f), fract(a.z + dh * f));
    }
    return mix(a, b, f);
}

fn sampleColorArray(t_in: f32, colorCount: i32, positionMode: i32, colorMode: i32, smoothAmount: f32) -> vec3<f32> {
    let t = clamp(t_in, 0.0, 1.0);

    // Handle edge cases
    if (colorCount <= 0) {
        return vec3<f32>(0.0);
    }
    if (colorCount == 1) {
        return getColor(0).rgb;
    }

    // Cascade blend: smoothstep at each transition boundary
    var result = rgbToColorSpace(getColor(0).rgb, colorMode);

    for (var i: i32 = 1; i < colorCount; i = i + 1) {
        var boundary: f32;
        var bw: f32;

        if (positionMode == 0) {
            // Auto: equal-width bands, transitions at i/count
            boundary = f32(i) / f32(colorCount);
            bw = smoothAmount * 0.5 / f32(colorCount);
        } else {
            // Manual: transition at midpoint between adjacent positions
            let pPrev = getPosition(i - 1, colorCount, positionMode);
            let pCurr = getPosition(i, colorCount, positionMode);
            boundary = (pPrev + pCurr) * 0.5;
            bw = smoothAmount * (pCurr - pPrev) * 0.25;
        }

        let blend = smoothstep(boundary - bw, boundary + bw, t);
        let nextColor = rgbToColorSpace(getColor(i).rgb, colorMode);
        result = mixInColorSpace(result, nextColor, blend, colorMode);
    }

    // Wrap-around blend: smooth the seam between last and first color
    // when the palette repeats (fract causes a hard edge at t=0/1)
    if (smoothAmount > 0.0) {
        var bw: f32;
        if (positionMode == 0) {
            bw = smoothAmount * 0.5 / f32(colorCount);
        } else {
            let pLast = getPosition(colorCount - 1, colorCount, positionMode);
            let pFirst = getPosition(0, colorCount, positionMode);
            let gap = 1.0 - pLast + pFirst;
            bw = smoothAmount * gap * 0.25;
        }

        if (bw > 0.0) {
            // Signed cyclic distance from the wrap boundary (t=0 ≡ t=1)
            let d = select(t, t - 1.0, t > 0.5);
            // Interpolation factor: 0 = last color, 1 = first color
            let wrapFactor = smoothstep(-bw, bw, d);
            let lastColor = rgbToColorSpace(getColor(colorCount - 1).rgb, colorMode);
            let firstColor = rgbToColorSpace(getColor(0).rgb, colorMode);
            let wrapColor = mixInColorSpace(lastColor, firstColor, wrapFactor, colorMode);

            // Mask: 1.0 at wrap point, fading to 0.0 at edge of zone
            let wrapMask = 1.0 - smoothstep(0.0, bw, abs(d));
            result = mixInColorSpace(result, wrapColor, wrapMask, colorMode);
        }
    }

    return colorSpaceToRgb(result, colorMode);
}

@fragment
fn main(@builtin(position) position: vec4<f32>) -> @location(0) vec4<f32> {
    // Extract uniforms
    let colorMode = i32(uniforms.data[0].x);
    let colorCount = i32(uniforms.data[0].y);
    let positionMode = i32(uniforms.data[0].z);
    let repeatVal = uniforms.data[0].w;
    let offsetVal = uniforms.data[1].x;
    let alpha = uniforms.data[1].y;
    let smoothness = uniforms.data[1].z;
    let rotation = i32(uniforms.data[1].w);
    let time = uniforms.data[2].w;

    // Calculate UV from position
    let size = vec2<f32>(textureDimensions(inputTex, 0));
    let uv = position.xy / size;

    // Get input color
    let inputColor = textureSampleLevel(inputTex, samp, uv, 0.0);

    // Calculate luminance as the t value
    let lum = dot(inputColor.rgb, vec3<f32>(0.299, 0.587, 0.114));

    // Apply mapping: repeat, offset, and rotation (animation)
    var t = lum * (1.0 - 1e-4) * repeatVal + offsetVal;

    if (rotation == -1) {
        t = t + time;
    } else if (rotation == 1) {
        t = t - time;
    }

    t = fract(t);

    // Sample the color array gradient
    let gradientColor = sampleColorArray(t, colorCount, positionMode, colorMode, smoothness);

    // Blend with original based on alpha
    let blendedColor = mix(inputColor.rgb, gradientColor, alpha);

    return vec4<f32>(blendedColor, inputColor.a);
}

/**
 * Tetra Cosine Gradient - WGSL Fragment Shader
 *
 * Applies a cosine palette to the input image based on luminance.
 * Uses the Inigo Quilez cosine palette formula:
 *   color(t) = offset + amp * cos(2π * (freq * t + phase))
 *
 * Supports RGB, HSV, OkLab, and OKLCH color modes.
 */

struct Uniforms {
    data: array<vec4<f32>, 6>,
    // data[0].x = offsetR, data[0].y = offsetG, data[0].z = offsetB, data[0].w = colorMode
    // data[1].x = ampR, data[1].y = ampG, data[1].z = ampB, data[1].w = repeat
    // data[2].x = freqR, data[2].y = freqG, data[2].z = freqB, data[2].w = offset (mapping)
    // data[3].x = phaseR, data[3].y = phaseG, data[3].z = phaseB, data[3].w = alpha
    // data[4].x = rotation, data[4].y = time
}

@group(0) @binding(0) var samp: sampler;
@group(0) @binding(1) var inputTex: texture_2d<f32>;
@group(0) @binding(2) var<uniform> uniforms: Uniforms;

const TAU: f32 = 6.283185307179586;

// ============================================================================
// Color Space Conversions
// ============================================================================

// HSV to RGB
fn hsv2rgb(hsv: vec3<f32>) -> vec3<f32> {
    let h = hsv.x;
    let s = hsv.y;
    let v = hsv.z;

    let c = v * s;
    let hp = h * 6.0;
    let x = c * (1.0 - abs((hp % 2.0 + 2.0) % 2.0 - 1.0));
    let m = v - c;

    var rgb: vec3<f32>;
    if (hp < 1.0) {
        rgb = vec3<f32>(c, x, 0.0);
    } else if (hp < 2.0) {
        rgb = vec3<f32>(x, c, 0.0);
    } else if (hp < 3.0) {
        rgb = vec3<f32>(0.0, c, x);
    } else if (hp < 4.0) {
        rgb = vec3<f32>(0.0, x, c);
    } else if (hp < 5.0) {
        rgb = vec3<f32>(x, 0.0, c);
    } else {
        rgb = vec3<f32>(c, 0.0, x);
    }

    return rgb + vec3<f32>(m);
}

// OkLab to linear RGB
fn oklab2linear(lab: vec3<f32>) -> vec3<f32> {
    let L = lab.x;
    let a = lab.y;
    let b = lab.z;

    let l_ = L + 0.3963377774 * a + 0.2158037573 * b;
    let m_ = L - 0.1055613458 * a - 0.0638541728 * b;
    let s_ = L - 0.0894841775 * a - 1.2914855480 * b;

    let l = l_ * l_ * l_;
    let m = m_ * m_ * m_;
    let s = s_ * s_ * s_;

    return vec3<f32>(
        4.0767416621 * l - 3.3077115913 * m + 0.2309699292 * s,
        -1.2684380046 * l + 2.6097574011 * m - 0.3413193965 * s,
        -0.0041960863 * l - 0.7034186147 * m + 1.7076147010 * s
    );
}

// Linear to sRGB gamma
fn linear2srgb(linear: vec3<f32>) -> vec3<f32> {
    let low = linear * 12.92;
    let high = 1.055 * pow(max(linear, vec3<f32>(0.0)), vec3<f32>(1.0 / 2.4)) - 0.055;
    return select(high, low, linear < vec3<f32>(0.0031308));
}

// OkLab to sRGB (cosine output is 0-1, a/b need remapping from 0-1 to -0.4..0.4)
fn oklab2rgb(lab: vec3<f32>) -> vec3<f32> {
    // Remap a, b from 0-1 storage format to actual -0.4 to 0.4 range
    let L = lab.x;
    let a = (lab.y - 0.5) * 0.8;  // 0-1 → -0.4 to 0.4
    let b = (lab.z - 0.5) * 0.8;  // 0-1 → -0.4 to 0.4

    let linear_rgb = oklab2linear(vec3<f32>(L, a, b));
    return clamp(linear2srgb(linear_rgb), vec3<f32>(0.0), vec3<f32>(1.0));
}

// OKLCH to sRGB (cosine output is L 0-1, C 0-1 representing 0-0.4, H 0-1)
fn oklch2rgb(lch: vec3<f32>) -> vec3<f32> {
    let L = lch.x;
    let C = lch.y * 0.4;  // 0-1 → 0 to 0.4
    let H = lch.z * TAU;  // 0-1 → 0 to 2π

    // Convert cylindrical to cartesian (OkLab)
    let a = C * cos(H);
    let b = C * sin(H);

    let linear_rgb = oklab2linear(vec3<f32>(L, a, b));
    return clamp(linear2srgb(linear_rgb), vec3<f32>(0.0), vec3<f32>(1.0));
}

// ============================================================================
// Cosine Palette
// ============================================================================

fn cosinePalette(t: f32, offset: vec3<f32>, amp: vec3<f32>, freq: vec3<f32>, phase: vec3<f32>) -> vec3<f32> {
    return clamp(offset + amp * cos(TAU * (freq * t + phase)), vec3<f32>(0.0), vec3<f32>(1.0));
}

@fragment
fn main(@builtin(position) position: vec4<f32>) -> @location(0) vec4<f32> {
    // Extract uniforms
    let offset = uniforms.data[0].xyz;
    let colorMode = i32(uniforms.data[0].w);
    let amp = uniforms.data[1].xyz;
    let repeatVal = uniforms.data[1].w;
    let freq = uniforms.data[2].xyz;
    let offsetVal = uniforms.data[2].w;
    let phase = uniforms.data[3].xyz;
    let alpha = uniforms.data[3].w;
    let rotation = i32(uniforms.data[4].x);
    let time = uniforms.data[4].y;

    // Calculate UV from position
    let size = vec2<f32>(textureDimensions(inputTex, 0));
    let uv = position.xy / size;

    // Get input color
    let inputColor = textureSample(inputTex, samp, uv);

    // Calculate luminance as the t value
    let lum = dot(inputColor.rgb, vec3<f32>(0.299, 0.587, 0.114));

    // Apply mapping: repeat, offset, and rotation (animation)
    var t = lum * repeatVal + offsetVal;

    if (rotation == -1) {
        t = t + time;
    } else if (rotation == 1) {
        t = t - time;
    }

    t = fract(t);

    // Evaluate cosine palette
    let paletteColor = cosinePalette(t, offset, amp, freq, phase);

    // Convert from color mode to RGB
    var finalColor: vec3<f32>;
    if (colorMode == 1) {
        // HSV mode
        finalColor = hsv2rgb(paletteColor);
    } else if (colorMode == 2) {
        // OkLab mode
        finalColor = oklab2rgb(paletteColor);
    } else if (colorMode == 3) {
        // OKLCH mode
        finalColor = oklch2rgb(paletteColor);
    } else {
        // RGB mode (default)
        finalColor = paletteColor;
    }

    // Blend with original based on alpha
    let blendedColor = mix(inputColor.rgb, finalColor, alpha);

    return vec4<f32>(blendedColor, inputColor.a);
}

/*
 * Text overlay shader
 * Blends pre-rendered text texture over input with matte background
 */

@group(0) @binding(0) var texSampler: sampler;
@group(0) @binding(1) var inputTex: texture_2d<f32>;
@group(0) @binding(2) var textTex: texture_2d<f32>;
@group(0) @binding(3) var<uniform> matteColor: vec3<f32>;
@group(0) @binding(4) var<uniform> matteOpacity: f32;
@group(0) @binding(5) var<uniform> tileOffset: vec2<f32>;
@group(0) @binding(6) var<uniform> fullResolution: vec2<f32>;

@fragment
fn main(@builtin(position) position: vec4<f32>) -> @location(0) vec4<f32> {
    let size = max(textureDimensions(inputTex, 0), vec2<u32>(1, 1));
    let localUV = position.xy / vec2<f32>(size);
    var fullSize = vec2<f32>(size);
    if (fullResolution.x > 0.0) { fullSize = fullResolution; }
    let globalUV = (position.xy + tileOffset) / fullSize;

    let inputColor = textureSample(inputTex, texSampler, localUV);
    let text = textureSample(textTex, texSampler, globalUV);

    // Text presence from canvas alpha (1.0 where text exists, 0.0 elsewhere)
    let textPresence = text.a;
    let matteAlpha = matteOpacity;

    // Premultiplied blend (matches pointsRender):
    // - Text contribution (not affected by matte)
    // - Input passes through where no text AND no matte
    // - Matte replaces input where matteOpacity > 0
    let rgb = text.rgb * textPresence
            + inputColor.rgb * (1.0 - textPresence) * (1.0 - matteAlpha)
            + matteColor * matteAlpha * (1.0 - textPresence);

    // Alpha: text=opaque, elsewhere blend input alpha toward opaque by matte
    let alpha = max(textPresence, mix(inputColor.a, 1.0, matteAlpha));

    return vec4<f32>(rgb, alpha);
}

// Texture effect: generate a height field from one of several texture modes,
// derive shading from the gradient, then blend back into the source pixels.
// Modes: 0=canvas, 1=crosshatch, 2=halftone, 3=paper, 4=stucco
//
// MODE is a compile-time const injected by the runtime via injectDefines
// (see definition.js `globals.mode.define`). Same fix as the GLSL backend —
// collapses the 5-way height_field dispatch so Dawn constant-folds it and
// emits only one variant body per compiled program. The old `mode` binding
// at @group(0) @binding(2) is removed; bindings 3/4/5 keep their original
// indices (WGSL binding numbers don't need to be contiguous).

struct VertexOutput {
    @builtin(position) position: vec4<f32>,
    @location(0) uv: vec2<f32>,
}

@group(0) @binding(0) var u_sampler: sampler;
@group(0) @binding(1) var inputTex: texture_2d<f32>;
@group(0) @binding(3) var<uniform> alpha: f32;
@group(0) @binding(4) var<uniform> scale: f32;
@group(0) @binding(5) var<uniform> time: f32;
@group(0) @binding(6) var<uniform> intensity: f32;
@group(0) @binding(7) var<uniform> contrast: f32;
@group(0) @binding(8) var<uniform> mono: i32;
@group(0) @binding(9) var<uniform> tileOffset: vec2<f32>;
@group(0) @binding(10) var<uniform> fullResolution: vec2<f32>;

const PI: f32 = 3.14159265359;
const INV_UINT32_MAX: f32 = 1.0 / 4294967295.0;
const Z_LOOP: i32 = 2;
const SHADE_GAIN: f32 = 4.4;

fn clamp01(value: f32) -> f32 {
    return clamp(value, 0.0, 1.0);
}

fn s_curve01(value: f32) -> f32 {
    let c: f32 = clamp01(value);
    return c * c * (3.0 - 2.0 * c);
}

fn fade(t: f32) -> f32 {
    return t * t * (3.0 - 2.0 * t);
}

fn freq_for_shape(base_freq: f32, dims: vec2<f32>) -> vec2<f32> {
    let w: f32 = max(dims.x, 1.0);
    let h: f32 = max(dims.y, 1.0);
    if (abs(w - h) < 0.5) {
        return vec2<f32>(base_freq, base_freq);
    }
    if (w > h) {
        return vec2<f32>(base_freq, base_freq * w / h);
    }
    return vec2<f32>(base_freq * h / w, base_freq);
}

fn hash_uint(x_in: u32) -> u32 {
    var x: u32 = x_in;
    x ^= x >> 16u;
    x *= 0x7feb352du;
    x ^= x >> 15u;
    x *= 0x846ca68bu;
    x ^= x >> 16u;
    return x;
}

fn fast_hash(p: vec3<i32>, salt: u32) -> f32 {
    var h: u32 = salt ^ 0x9e3779b9u;
    h ^= bitcast<u32>(p.x) * 0x27d4eb2du;
    h = hash_uint(h);
    h ^= bitcast<u32>(p.y) * 0xc2b2ae35u;
    h = hash_uint(h);
    h ^= bitcast<u32>(p.z) * 0x165667b1u;
    h = hash_uint(h);
    return f32(h) * INV_UINT32_MAX;
}

fn value_noise(uv: vec2<f32>, freq: vec2<f32>, motion: f32, salt: u32) -> f32 {
    let scaled_uv: vec2<f32> = uv * max(freq, vec2<f32>(1.0, 1.0));
    let cell_floor: vec2<f32> = floor(scaled_uv);
    let frac_part: vec2<f32> = fract(scaled_uv);
    let base_cell: vec2<i32> = vec2<i32>(i32(cell_floor.x), i32(cell_floor.y));

    let z_floor: f32 = floor(motion);
    let z_frac: f32 = fract(motion);
    let z0: i32 = i32(z_floor) % Z_LOOP;
    let z1: i32 = (z0 + 1) % Z_LOOP;

    let c000: f32 = fast_hash(vec3<i32>(base_cell.x + 0, base_cell.y + 0, z0), salt);
    let c100: f32 = fast_hash(vec3<i32>(base_cell.x + 1, base_cell.y + 0, z0), salt);
    let c010: f32 = fast_hash(vec3<i32>(base_cell.x + 0, base_cell.y + 1, z0), salt);
    let c110: f32 = fast_hash(vec3<i32>(base_cell.x + 1, base_cell.y + 1, z0), salt);
    let c001: f32 = fast_hash(vec3<i32>(base_cell.x + 0, base_cell.y + 0, z1), salt);
    let c101: f32 = fast_hash(vec3<i32>(base_cell.x + 1, base_cell.y + 0, z1), salt);
    let c011: f32 = fast_hash(vec3<i32>(base_cell.x + 0, base_cell.y + 1, z1), salt);
    let c111: f32 = fast_hash(vec3<i32>(base_cell.x + 1, base_cell.y + 1, z1), salt);

    let tx: f32 = fade(frac_part.x);
    let ty: f32 = fade(frac_part.y);
    let tz: f32 = fade(z_frac);

    let x00: f32 = mix(c000, c100, tx);
    let x10: f32 = mix(c010, c110, tx);
    let x01: f32 = mix(c001, c101, tx);
    let x11: f32 = mix(c011, c111, tx);

    let y0: f32 = mix(x00, x10, ty);
    let y1: f32 = mix(x01, x11, ty);

    return mix(y0, y1, tz);
}

// Paper: 3-octave ridged noise (original texture)
fn height_paper(uv: vec2<f32>, base_freq: vec2<f32>, motion: f32) -> f32 {
    var freq: vec2<f32> = max(base_freq, vec2<f32>(1.0, 1.0));
    var amplitude: f32 = 0.5;
    var accum: f32 = 0.0;
    var total: f32 = 0.0;

    for (var octave: u32 = 0u; octave < 3u; octave = octave + 1u) {
        let salt: u32 = 0x9e3779b9u * (octave + 1u);
        let sample_val: f32 = value_noise(uv, freq, motion + f32(octave) * 0.37, salt);
        let ridged: f32 = 1.0 - abs(sample_val * 2.0 - 1.0);
        accum = accum + ridged * amplitude;
        total = total + amplitude;
        freq = freq * 2.0;
        amplitude = amplitude * 0.55;
    }

    if (total <= 0.0) { return clamp01(accum); }
    return clamp01(accum / total);
}

// Stucco: 2-octave smooth noise, lower frequency, rounder bumps
fn height_stucco(uv: vec2<f32>, base_freq: vec2<f32>, motion: f32) -> f32 {
    var freq: vec2<f32> = max(base_freq, vec2<f32>(1.0, 1.0));
    var amplitude: f32 = 0.5;
    var accum: f32 = 0.0;
    var total: f32 = 0.0;

    for (var octave: u32 = 0u; octave < 2u; octave = octave + 1u) {
        let salt: u32 = 0x9e3779b9u * (octave + 1u);
        let sample_val: f32 = value_noise(uv, freq, motion + f32(octave) * 0.37, salt);
        accum = accum + sample_val * amplitude;
        total = total + amplitude;
        freq = freq * 2.0;
        amplitude = amplitude * 0.5;
    }

    if (total <= 0.0) { return clamp01(accum); }
    return clamp01(accum / total);
}

// Canvas: woven fabric pattern with slight noise perturbation
fn height_canvas(uv: vec2<f32>, base_freq: vec2<f32>, motion: f32) -> f32 {
    let st: vec2<f32> = uv * base_freq;
    let warpX: f32 = abs(sin(st.x * PI));
    let weftY: f32 = abs(sin(st.y * PI));
    let weave: f32 = warpX * weftY;

    let noise: f32 = value_noise(uv, base_freq * 0.5, motion, 0x12345678u);
    return clamp01(weave * 0.85 + noise * 0.15);
}

// Halftone: regular circular dot grid
fn height_halftone(uv: vec2<f32>, base_freq: vec2<f32>) -> f32 {
    let st: vec2<f32> = uv * base_freq;
    let cell: vec2<f32> = fract(st) - 0.5;
    let dot: f32 = 1.0 - clamp01(length(cell) * 3.0);
    return dot * dot;
}

// Crosshatch: two overlapping diagonal sine ridges
fn height_crosshatch(uv: vec2<f32>, base_freq: vec2<f32>) -> f32 {
    let st: vec2<f32> = uv * base_freq;
    let d1: f32 = abs(sin((st.x + st.y) * PI));
    let d2: f32 = abs(sin((st.x - st.y) * PI));
    return clamp01(d1 * d2);
}

// Dispatch to the active mode's height function — single variant selected
// at compile time by the MODE const (Dawn constant-folds).
fn height_field(uv: vec2<f32>, base_freq: vec2<f32>, motion: f32) -> f32 {
    if (MODE == 0) { return height_canvas(uv, base_freq, motion); }
    if (MODE == 1) { return height_crosshatch(uv, base_freq); }
    if (MODE == 2) { return height_halftone(uv, base_freq); }
    if (MODE == 4) { return height_stucco(uv, base_freq, motion); }
    return height_paper(uv, base_freq, motion);  // 3 = paper (default)
}

fn material_hash(p: vec2<i32>, salt: u32, layer: u32) -> u32 {
    var h: u32 = salt ^ (layer * 0x9e3779b9u);
    h ^= bitcast<u32>(p.x) * 0x27d4eb2du;
    h = hash_uint(h);
    h ^= bitcast<u32>(p.y) * 0xc2b2ae35u;
    return hash_uint(h);
}

fn material_gradient(p: vec2<i32>, salt: u32, layer: u32) -> vec2<f32> {
    let h: u32 = material_hash(p, salt, layer);
    var gradient = vec2<f32>(f32(h & 0xffffu), f32(h >> 16u)) * (2.0 / 65535.0) - 1.0;
    gradient *= inverseSqrt(max(dot(gradient, gradient), 0.000001));
    return gradient;
}

fn material_fade(t: vec2<f32>) -> vec2<f32> {
    return t * t * t * (t * (t * 6.0 - 15.0) + 10.0);
}

fn material_gradient_layer(p: vec2<f32>, salt: u32, layer: u32) -> f32 {
    let cellFloor = floor(p);
    let cell = vec2<i32>(i32(cellFloor.x), i32(cellFloor.y));
    let local = fract(p);
    let n00 = dot(material_gradient(cell, salt, layer), local);
    let n10 = dot(material_gradient(cell + vec2<i32>(1, 0), salt, layer), local - vec2<f32>(1.0, 0.0));
    let n01 = dot(material_gradient(cell + vec2<i32>(0, 1), salt, layer), local - vec2<f32>(0.0, 1.0));
    let n11 = dot(material_gradient(cell + vec2<i32>(1, 1), salt, layer), local - vec2<f32>(1.0, 1.0));
    let blend = material_fade(local);
    return mix(mix(n00, n10, blend.x), mix(n01, n11, blend.x), blend.y);
}

fn material_noise(globalPixel: vec2<f32>, cellSize: vec2<f32>, motion: f32, salt: u32) -> f32 {
    let p = globalPixel / max(cellSize, vec2<f32>(0.5));
    let zFloor = floor(motion);
    let z0 = i32(zFloor) % Z_LOOP;
    let z1 = (z0 + 1) % Z_LOOP;
    let n0 = material_gradient_layer(p, salt, u32(z0));
    let n1 = material_gradient_layer(p, salt, u32(z1));
    let n = mix(n0, n1, material_fade(vec2<f32>(fract(motion))).x);
    return clamp01(0.5 + n * 0.72);
}

fn material_soft(globalPixel: vec2<f32>, motion: f32, salt: u32, size: f32) -> f32 {
    // Two incommensurate gradient fields make a smooth isotropic surface.
    // Quintic interpolation keeps enlarged cells continuous without exposing
    // the square lattice that value noise reveals at high scale.
    let primaryCell = vec2<f32>(max(size * 3.25, 1.5));
    let primary = material_noise(globalPixel, primaryCell, motion, salt);
    let secondary = material_noise(globalPixel + vec2<f32>(17.31, 29.17), primaryCell * 1.87,
        motion + 0.41, salt ^ 0x68bc21ebu);
    return primary * 0.68 + secondary * 0.32;
}

fn material_directional(globalPixel: vec2<f32>, motion: f32, salt: u32, size: f32) -> f32 {
    // Strongly anisotropic gradient fields create continuous fibers directly,
    // avoiding both a stretched square lattice and a costly multi-tap blur.
    let primaryCell = vec2<f32>(max(size * 22.0, 8.0), max(size * 2.0, 1.25));
    let secondaryCell = vec2<f32>(max(size * 37.0, 13.0), max(size * 3.7, 2.3));
    let primary = material_noise(globalPixel, primaryCell, motion, salt);
    let secondary = material_noise(globalPixel + vec2<f32>(19.37, 11.83), secondaryCell,
        motion + 0.41, salt ^ 0x68bc21ebu);
    return primary * 0.72 + secondary * 0.28;
}

fn material_sprinkles(globalPixel: vec2<f32>, motion: f32, salt: u32, size: f32) -> f32 {
    let p: vec2<f32> = globalPixel / max(4.0 * size, 1.0) + vec2<f32>(motion * 0.31, motion * 0.19);
    let cellFloor = floor(p);
    let baseCell = vec2<i32>(i32(cellFloor.x), i32(cellFloor.y));
    let local = fract(p);
    var nearest = 10.0;
    for (var y = -1; y <= 1; y++) {
        for (var x = -1; x <= 1; x++) {
            let cell = baseCell + vec2<i32>(x, y);
            let jx = fast_hash(vec3<i32>(cell, 0), salt) - 0.5;
            let jy = fast_hash(vec3<i32>(cell, 1), salt ^ 0x68bc21ebu) - 0.5;
            let point = vec2<f32>(f32(x), f32(y)) + 0.5 + vec2<f32>(jx, jy) * 0.6;
            nearest = min(nearest, length(local - point));
        }
    }
    return mix(0.45, 1.0, 1.0 - smoothstep(0.10, 0.22, nearest));
}

fn material_edge_mask(uv: vec2<f32>, pixelStep: vec2<f32>) -> f32 {
    let weights: vec3<f32> = vec3<f32>(0.2126, 0.7152, 0.0722);
    let l: f32 = dot(textureSample(inputTex, u_sampler, uv - vec2<f32>(pixelStep.x, 0.0)).xyz, weights);
    let r: f32 = dot(textureSample(inputTex, u_sampler, uv + vec2<f32>(pixelStep.x, 0.0)).xyz, weights);
    let d: f32 = dot(textureSample(inputTex, u_sampler, uv - vec2<f32>(0.0, pixelStep.y)).xyz, weights);
    let u: f32 = dot(textureSample(inputTex, u_sampler, uv + vec2<f32>(0.0, pixelStep.y)).xyz, weights);
    return clamp(length(vec2<f32>(r - l, u - d)) * 6.0, 0.0, 1.0);
}

fn material_value(globalPixel: vec2<f32>, dims: vec2<f32>, uv: vec2<f32>, motion: f32, salt: u32) -> f32 {
    let size: f32 = max(scale, 0.1);
    if (MODE == 6) {
        return material_soft(globalPixel, motion, salt, size);
    }
    if (MODE == 7) {
        return material_sprinkles(globalPixel, motion, salt, size);
    }
    if (MODE == 8) {
        let a: f32 = material_noise(globalPixel, vec2<f32>(13.0 * size), motion, salt);
        let b: f32 = material_noise(globalPixel, vec2<f32>(6.0 * size), motion + 0.31, salt ^ 0x9e3779b9u);
        let c: f32 = material_noise(globalPixel, vec2<f32>(2.5 * size), motion + 0.67, salt ^ 0x85ebca6bu);
        return a * 0.58 + b * 0.28 + c * 0.14;
    }
    if (MODE == 9) {
        let n: f32 = material_noise(globalPixel, vec2<f32>(max(size * 1.5, 0.8)), motion, salt);
        return s_curve01(s_curve01(n));
    }
    if (MODE == 10) {
        return material_noise(globalPixel, vec2<f32>(4.5 * size), motion, salt);
    }
    if (MODE == 11) {
        return step(0.5, material_noise(globalPixel, vec2<f32>(max(size * 1.5, 0.8)), motion, salt));
    }
    if (MODE == 12) {
        return material_directional(globalPixel, motion, salt, size);
    }
    if (MODE == 13) {
        return material_directional(globalPixel.yx, motion, salt, size);
    }
    if (MODE == 14) {
        let n: f32 = material_noise(globalPixel, vec2<f32>(max(size * 1.5, 0.8)), motion, salt);
        return mix(0.5, n, material_edge_mask(uv, 1.0 / dims));
    }
    return material_noise(globalPixel, vec2<f32>(max(size * 1.5, 0.8)), motion, salt);
}

fn shape_material(raw: f32) -> f32 {
    let amount: f32 = intensity / 40.0;
    let shaped: f32 = raw * amount + 0.5 * (1.0 - amount);
    let c: f32 = clamp(contrast / 100.0, 0.0, 1.0);
    if (c < 0.5) { return mix(0.5, shaped, c * 2.0); }
    return mix(shaped, s_curve01(shaped), (c - 0.5) * 2.0);
}

@fragment
fn main(in: VertexOutput) -> @location(0) vec4<f32> {
    // The output-normalized coordinate, as the GLSL's v_texCoord against its
    // textures; the default vertex uv has a bottom-left origin, so it is
    // flipped vertically.
    let dims: vec2<f32> = vec2<f32>(textureDimensions(inputTex, 0));
    let uv: vec2<f32> = vec2<f32>(in.uv.x, 1.0 - in.uv.y);
    let base_color: vec4<f32> = textureSample(inputTex, u_sampler, uv);
    let pixel_step: vec2<f32> = 1.0 / dims;

    let a: f32 = clamp(alpha, 0.0, 1.0);
    if (a <= 0.0) {
        return base_color;
    }

    if (MODE >= 5) {
        var globalDims: vec2<f32> = dims;
        if (fullResolution.x > 0.0) { globalDims = fullResolution; }
        let globalPixel: vec2<f32> = in.position.xy + tileOffset;
        let materialMotion: f32 = time * f32(Z_LOOP);
        let r: f32 = shape_material(material_value(globalPixel, globalDims, uv, materialMotion, 0x1234abcdu));
        var material: vec3<f32> = vec3<f32>(r);
        if (mono == 0) {
            material.g = shape_material(material_value(globalPixel, globalDims, uv, materialMotion, 0x68bc21ebu));
            material.b = shape_material(material_value(globalPixel, globalDims, uv, materialMotion, 0x02e5be93u));
        }
        return vec4<f32>(clamp(mix(base_color.xyz, material, a), vec3<f32>(0.0), vec3<f32>(1.0)), base_color.w);
    }

    // Paper and stucco use different base frequencies
    var freq_scale: f32 = 24.0;
    if (MODE == 4) { freq_scale = 48.0; }
    let base_freq: vec2<f32> = freq_for_shape(freq_scale * (10.01 - scale), dims);
    let motion: f32 = time * f32(Z_LOOP);

    // Sample height field at center and 4 neighbors for gradient
    let h_center: f32 = height_field(uv, base_freq, motion);
    let h_right: f32 = height_field(uv + vec2<f32>(pixel_step.x, 0.0), base_freq, motion);
    let h_left: f32 = height_field(uv - vec2<f32>(pixel_step.x, 0.0), base_freq, motion);
    let h_up: f32 = height_field(uv + vec2<f32>(0.0, pixel_step.y), base_freq, motion);
    let h_down: f32 = height_field(uv - vec2<f32>(0.0, pixel_step.y), base_freq, motion);

    let gx: f32 = h_right - h_left;
    let gy: f32 = h_down - h_up;
    let gradient: f32 = sqrt(gx * gx + gy * gy);

    // Stucco uses stronger shading for more pronounced bumps
    var gain: f32 = SHADE_GAIN * 0.25;
    if (MODE == 4) { gain = SHADE_GAIN * 0.5; }
    let shade_base: f32 = clamp01(gradient * gain);

    let highlight_mix: f32 = clamp01((shade_base * shade_base) * 1.25);
    let base_factor: f32 = 0.9 + h_center * 0.35;
    let factor: f32 = clamp(base_factor + highlight_mix * 0.35, 0.85, 1.6);

    let scaled_rgb: vec3<f32> = clamp(base_color.xyz * factor, vec3<f32>(0.0), vec3<f32>(1.0));

    return vec4<f32>(mix(base_color.xyz, scaled_rgb, a), base_color.w);
}

