        centered.x = centered.x * aspectRatio; 
    }

    let a = atan2(centered.y, centered.x);
    var r: f32;

    if (uniforms.shape == 0) {
        // Circle
        r = length(centered);
    } else if (uniforms.shape == 1) {
        // Triangle
        r = polygonShape(centered * 2.0, 3);
    } else if (uniforms.shape == 2) {
        // Rounded square (superellipse)
        let p = centered * centered * centered * centered * centered * centered * centered * centered;
        r = pow(p.x + p.y, 1.0 / 8.0);
    } else if (uniforms.shape == 3) {
        // Square
        r = polygonShape(centered * 2.0, 4);
    } else if (uniforms.shape == 4) {
        // Hexagon
        r = polygonShape(centered * 2.0, 6);
    } else {
        // Octagon
        r = polygonShape(centered * 2.0, 8);
    }

    // Apply scale
    r -= uniforms.scale * 0.15;

    // Create tunnel coordinates
    let tunnelCoords = smod2(vec2<f32>(
        0.3 / r + uniforms.time * uniforms.speed,
        a / PI + uniforms.time * uniforms.rotation
    ), 1.0);

    var color: vec4<f32>;
    if (uniforms.antialias != 0) {
        let dx = dpdx(tunnelCoords);
        let dy = dpdy(tunnelCoords);
        color = vec4<f32>(0.0);
        color += textureSample(inputTex, inputSampler, tunnelCoords + dx * -0.375 + dy * -0.125);
        color += textureSample(inputTex, inputSampler, tunnelCoords + dx *  0.125 + dy * -0.375);
        color += textureSample(inputTex, inputSampler, tunnelCoords + dx *  0.375 + dy *  0.125);
        color += textureSample(inputTex, inputSampler, tunnelCoords + dx * -0.125 + dy *  0.375);
        color = color * 0.25;
    } else {
        color = textureSample(inputTex, inputSampler, tunnelCoords);
    }

    // Center vignette: smooth falloff to hide moiré at vanishing point
    if (uniforms.center != 0.0) {
        let centerMask = smoothstep(0.0, 0.5, r);
        let amt = uniforms.center / 100.0;
        if (amt < 0.0) {
            color = vec4<f32>(color.rgb * mix(1.0, centerMask, -amt), color.a);
        } else {
            color = vec4<f32>(mix(color.rgb, vec3<f32>(1.0), (1.0 - centerMask) * amt), color.a);
        }
    }

    return color;
}

/*
 * Unsharp mask - horizontal Gaussian pass
 */

struct Uniforms {
    radius: f32,
}

@group(0) @binding(0) var inputSampler: sampler;
@group(0) @binding(1) var inputTex: texture_2d<f32>;
@group(0) @binding(2) var<uniform> uniforms: Uniforms;

@fragment
fn main(@builtin(position) pos: vec4<f32>) -> @location(0) vec4<f32> {
    let texSize = vec2<f32>(textureDimensions(inputTex));
    let uv = pos.xy / texSize;
    let dirPx = vec2<f32>(1.0, 0.0);
    let sigma = max(uniforms.radius * 0.5, 0.001);
    let fTaps = min(uniforms.radius, 32.0);
    var sum = textureSample(inputTex, inputSampler, uv);
    var wsum = 1.0;
    for (var i = 1; i <= 32; i++) {
        if (f32(i) > fTaps) { break; }
        let w = exp(-f32(i * i) / (2.0 * sigma * sigma));
        let o = dirPx * f32(i) / texSize;
        sum += (textureSample(inputTex, inputSampler, uv + o)
              + textureSample(inputTex, inputSampler, uv - o)) * w;
        wsum += 2.0 * w;
    }
    return sum / wsum;
}

/*
 * Unsharp mask - vertical Gaussian pass
 */

struct Uniforms {
    radius: f32,
}

@group(0) @binding(0) var inputSampler: sampler;
@group(0) @binding(1) var inputTex: texture_2d<f32>;
@group(0) @binding(2) var<uniform> uniforms: Uniforms;

@fragment
fn main(@builtin(position) pos: vec4<f32>) -> @location(0) vec4<f32> {
    let texSize = vec2<f32>(textureDimensions(inputTex));
    let uv = pos.xy / texSize;
    let dirPx = vec2<f32>(0.0, 1.0);
    let sigma = max(uniforms.radius * 0.5, 0.001);
    let fTaps = min(uniforms.radius, 32.0);
    var sum = textureSample(inputTex, inputSampler, uv);
    var wsum = 1.0;
    for (var i = 1; i <= 32; i++) {
        if (f32(i) > fTaps) { break; }
        let w = exp(-f32(i * i) / (2.0 * sigma * sigma));
        let o = dirPx * f32(i) / texSize;
        sum += (textureSample(inputTex, inputSampler, uv + o)
              + textureSample(inputTex, inputSampler, uv - o)) * w;
        wsum += 2.0 * w;
    }
    return sum / wsum;
}

/*
 * Unsharp mask - combine pass
 */

struct Uniforms {
    amount: f32,
    threshold: f32,
}

@group(0) @binding(0) var inputSampler: sampler;
@group(0) @binding(1) var inputTex: texture_2d<f32>;
@group(0) @binding(2) var blurTex: texture_2d<f32>;
@group(0) @binding(3) var<uniform> uniforms: Uniforms;

@fragment
fn main(@builtin(position) pos: vec4<f32>) -> @location(0) vec4<f32> {
    let texSize = vec2<f32>(textureDimensions(inputTex));
    let uv = pos.xy / texSize;
    let src = textureSample(inputTex, inputSampler, uv);
    let blur = textureSample(blurTex, inputSampler, uv);
    let diff = src.rgb - blur.rgb;
    let t = uniforms.threshold / 100.0;
    let mag = max(max(abs(diff.r), abs(diff.g)), abs(diff.b));
    let gate = smoothstep(t, t + 0.02, mag);
    let outc = src.rgb + diff * (uniforms.amount / 100.0) * gate;
    return vec4<f32>(clamp(outc, vec3<f32>(0.0), vec3<f32>(1.0)), src.a);
}

// Vaseline - N-tap blur with edge-weighted blending
// Uses golden angle spiral kernel for smooth, non-blocky blur

struct Params {
    resolution: vec2f,
    alpha: f32,
    _pad0: f32,
    tileOffset: vec2f,
    fullResolution: vec2f,
    renderScale: f32,
}

@group(0) @binding(0) var inputTex: texture_2d<f32>;
@group(0) @binding(1) var inputSampler: sampler;
@group(0) @binding(2) var<uniform> params: Params;

const TAP_COUNT: i32 = 32;
const RADIUS: f32 = 48.0;
const GOLDEN_ANGLE: f32 = 2.39996323;
const BRIGHTNESS_ADJUST: f32 = 0.15;

fn clamp01v(v: vec3f) -> vec3f {
    return clamp(v, vec3f(0.0), vec3f(1.0));
}

fn chebyshev_mask(uv: vec2f) -> f32 {
    let centered = abs(uv - vec2f(0.5)) * 2.0;
    return max(centered.x, centered.y);
}

@fragment
fn main(@builtin(position) fragCoord: vec4f) -> @location(0) vec4f {
    let coord = vec2i(fragCoord.xy);
    let globalCoord = fragCoord.xy + params.tileOffset;
    let uv = globalCoord / params.fullResolution;
    let fullRes = select(params.resolution, params.fullResolution, params.fullResolution.x > 0.0);
    let globalUV = (fragCoord.xy + params.tileOffset) / fullRes;

    let original = textureLoad(inputTex, coord, 0);
    let a = clamp(params.alpha, 0.0, 1.0);

    if (a <= 0.0) {
        return vec4f(clamp01v(original.rgb), original.a);
    }

    let texelSize = 1.0 / params.fullResolution;
    let radiusUV = RADIUS * params.renderScale * texelSize;

    // N-tap gather using golden angle spiral
    var blurAccum = vec3f(0.0);
    var weightSum: f32 = 0.0;

    for (var i: i32 = 0; i < TAP_COUNT; i = i + 1) {
        let t = f32(i) / f32(TAP_COUNT);
        let r = sqrt(t);
        let theta = f32(i) * GOLDEN_ANGLE;
        let offset = vec2f(cos(theta), sin(theta)) * r;

        let sigma: f32 = 0.4;
        let weight = exp(-0.5 * (r * r) / (sigma * sigma));

        let sampleGlobalUV = clamp(uv + offset * radiusUV, vec2f(0.0), vec2f(1.0));
        let sampleLocalUV = (sampleGlobalUV * params.fullResolution - params.tileOffset) / vec2f(textureDimensions(inputTex, 0));
        blurAccum = blurAccum + textureSample(inputTex, inputSampler, sampleLocalUV).rgb * weight;
        weightSum = weightSum + weight;
    }

    let blurred = blurAccum / weightSum;
    let boosted = clamp01v(blurred + vec3f(BRIGHTNESS_ADJUST));

    // Edge mask - more effect at edges, using global UV so center is full-image center
    var edgeMask = chebyshev_mask(globalUV);
    edgeMask = smoothstep(0.0, 0.8, edgeMask);

    let sourceClamped = clamp01v(original.rgb);
    let bloomed = clamp01v((sourceClamped + boosted) * 0.5);
    let edgeBlended = mix(sourceClamped, bloomed, edgeMask);
    let finalRgb = clamp01v(mix(sourceClamped, edgeBlended, a));

    return vec4f(finalRgb, original.a);
}

/*
 * Radial vignette with brightness blend
 */

struct Uniforms {
    vignetteBrightness: f32,
    alpha: f32,
    _pad1: f32,
    _pad2: f32,
    tileOffset: vec2<f32>,
    fullResolution: vec2<f32>,
}

@group(0) @binding(0) var inputSampler: sampler;
@group(0) @binding(1) var inputTex: texture_2d<f32>;
@group(0) @binding(2) var<uniform> uniforms: Uniforms;

fn computeVignetteMask(uv: vec2<f32>, dims: vec2<f32>) -> f32 {
    if (dims.x <= 0.0 || dims.y <= 0.0) {
        return 0.0;
    }

    let delta = abs(uv - vec2<f32>(0.5));
    let aspect = dims.x / max(dims.y, 1.0);
    let scaled = vec2<f32>(delta.x * aspect, delta.y);
    let maxRadius = length(vec2<f32>(aspect * 0.5, 0.5));

    if (maxRadius <= 0.0) {
        return 0.0;
    }

    let normalizedDist = clamp(length(scaled) / maxRadius, 0.0, 1.0);
    return normalizedDist * normalizedDist;
}

@fragment
fn main(@builtin(position) pos: vec4<f32>) -> @location(0) vec4<f32> {
    let texSize = vec2<f32>(textureDimensions(inputTex));
    let tileDims = texSize;
    let dims = select(tileDims, uniforms.fullResolution, uniforms.fullResolution.x > 0.0);
    let uv = pos.xy / tileDims;
    let globalUV = (pos.xy + uniforms.tileOffset) / dims;

    let texel = textureSample(inputTex, inputSampler, uv);

    let mask = computeVignetteMask(globalUV, dims);

    // Apply brightness to RGB only, preserve alpha
    let brightnessRgb = vec3<f32>(uniforms.vignetteBrightness);
    let edgeBlend = mix(texel.rgb, brightnessRgb, mask);
    let finalRgb = mix(texel.rgb, edgeBlend, uniforms.alpha);

    return vec4<f32>(finalRgb, texel.a);
}

/*
 * Perlin noise-based warp distortion
 */

struct Uniforms {
    strength: f32,
    scale: f32,
    seed: i32,
    speed: i32,
    wrap: i32,
    antialias: i32,
    resolution: vec2<f32>,
    tileOffset: vec2<f32>,
    fullResolution: vec2<f32>,
}

@group(0) @binding(0) var inputSampler: sampler;
@group(0) @binding(1) var inputTex: texture_2d<f32>;
@group(0) @binding(2) var<uniform> uniforms: Uniforms;
@group(0) @binding(3) var<uniform> time: f32;

const TAU: f32 = 6.28318530718;

fn pcg(v_in: vec3<u32>) -> vec3<u32> {
    var v = v_in * 1664525u + 1013904223u;
    v.x = v.x + v.y * v.z;
    v.y = v.y + v.z * v.x;
    v.z = v.z + v.x * v.y;
    v = v ^ (v >> vec3<u32>(16u));
    v.x = v.x + v.y * v.z;
    v.y = v.y + v.z * v.x;
    v.z = v.z + v.x * v.y;
    return v;
}

fn prng(p_in: vec3<f32>) -> vec3<f32> {
    var p = p_in;
    p.x = select(-p.x * 2.0 + 1.0, p.x * 2.0, p.x >= 0.0);
    p.y = select(-p.y * 2.0 + 1.0, p.y * 2.0, p.y >= 0.0);
    p.z = select(-p.z * 2.0 + 1.0, p.z * 2.0, p.z >= 0.0);
    return vec3<f32>(pcg(vec3<u32>(p))) / f32(0xffffffff);
}

fn smootherstep(x: f32) -> f32 {
    return x * x * x * (x * (x * 6.0 - 15.0) + 10.0);
}

fn smoothlerp(x: f32, a: f32, b: f32) -> f32 {
    return a + smootherstep(x) * (b - a);
}

fn grid(st: vec2<f32>, cell: vec2<f32>, t: f32) -> f32 {
    var angle = prng(vec3<f32>(cell, 1.0)).r * TAU;
    angle = angle + t * TAU * f32(uniforms.speed);
    let gradient = vec2<f32>(cos(angle), sin(angle));
    let dist = st - cell;
    return dot(gradient, dist);
}

fn perlinNoise(st_in: vec2<f32>, noiseScale: vec2<f32>, t: f32) -> f32 {
    let st = st_in * noiseScale;
    let cell = floor(st);
    let tl = grid(st, cell, t);
    let tr = grid(st, vec2<f32>(cell.x + 1.0, cell.y), t);
    let bl = grid(st, vec2<f32>(cell.x, cell.y + 1.0), t);
    let br = grid(st, cell + 1.0, t);
    let upper = smoothlerp(st.x - cell.x, tl, tr);
    let lower = smoothlerp(st.x - cell.x, bl, br);
    let val = smoothlerp(st.y - cell.y, upper, lower);
    return val * 0.5 + 0.5;
}

@fragment
fn main(@builtin(position) pos: vec4<f32>) -> @location(0) vec4<f32> {
    let fullRes = select(uniforms.resolution, uniforms.fullResolution, uniforms.fullResolution.x > 0.0);
    let aspectRatio = fullRes.x / fullRes.y;
    var uv = (pos.xy + uniforms.tileOffset) / fullRes;

    let strength = uniforms.strength;
    let scale = uniforms.scale;
    let seed = uniforms.seed;
    let t = time;

    // Perlin warp — sample both axes before applying either
    let noiseCoord = uv * vec2<f32>(aspectRatio, 1.0);
    let noiseScale = vec2<f32>(abs(scale * 3.0));
    let dx = (perlinNoise(noiseCoord + f32(seed), noiseScale, t) - 0.5) * strength * 0.01;
    let dy = (perlinNoise(noiseCoord + f32(seed) + 10.0, noiseScale, t) - 0.5) * strength * 0.01;
    uv.x = uv.x + dx;
    uv.y = uv.y + dy;

    // Apply wrap mode
    if (uniforms.wrap == 0) {
        // mirror
        uv = abs((uv + 1.0) - 2.0 * floor((uv + 1.0) / 2.0) - 1.0);
    } else if (uniforms.wrap == 1) {
        // repeat
        uv = (uv - 1.0 * floor(uv / 1.0));
    } else {
        // clamp
        uv = clamp(uv, vec2<f32>(0.0), vec2<f32>(1.0));
    }

    if (uniforms.antialias != 0) {
        let dx = dpdx(uv);
        let dy = dpdy(uv);
        var col = vec4<f32>(0.0);
        col += textureSample(inputTex, inputSampler, uv + dx * -0.375 + dy * -0.125);
        col += textureSample(inputTex, inputSampler, uv + dx *  0.125 + dy * -0.375);
        col += textureSample(inputTex, inputSampler, uv + dx *  0.375 + dy *  0.125);
        col += textureSample(inputTex, inputSampler, uv + dx * -0.125 + dy *  0.375);
        return col * 0.25;
    } else {
        return textureSample(inputTex, inputSampler, uv);
    }
}

/*
 * Watercolor - composite pass: pigment pooling, paper granulation, warm
 * paper tint, and a flat-wash lift. See glsl/wcComposite.glsl for the full
 * algorithm description. The paper-granulation hash is seeded from the
 * tile-aware global pixel coordinate (floor(pos.xy) + uniforms.tileOffset),
 * matching GLSL's floor(gl_FragCoord.xy) + tileOffset exactly, so the grain
 * pattern stays seamless across CLI render tiles instead of restarting at
 * each tile's local origin.
 */

struct Uniforms {
    shadowIntensity: f32,
    paperTexture: f32,
    tileOffset: vec2<f32>,
}

@group(0) @binding(0) var inputSampler: sampler;
@group(0) @binding(1) var inputTex: texture_2d<f32>;
@group(0) @binding(2) var simplifiedTex: texture_2d<f32>;
@group(0) @binding(3) var<uniform> uniforms: Uniforms;

fn hash12(p: vec2<f32>) -> f32 {
    var p3 = fract(vec3<f32>(p.xyx) * 0.1031);
    p3 = p3 + dot(p3, p3.yzx + vec3<f32>(33.33));
    return fract((p3.x + p3.y) * p3.z);
}

fn vnoise(p: vec2<f32>) -> f32 {
    let i = floor(p);
    let f = fract(p);
    let u = f * f * (3.0 - 2.0 * f);
    return mix(mix(hash12(i), hash12(i + vec2<f32>(1.0, 0.0)), u.x),
               mix(hash12(i + vec2<f32>(0.0, 1.0)), hash12(i + vec2<f32>(1.0, 1.0)), u.x), u.y);
}

fn lum(c: vec3<f32>) -> f32 {
    return dot(c, vec3<f32>(0.2126, 0.7152, 0.0722));
}

// Sobel gradient gradient, applied to the SIMPLIFIED texture (pigment pooling edges).
fn lumGradientSimplified(uv: vec2<f32>) -> vec2<f32> {
    let texSize = vec2<f32>(textureDimensions(simplifiedTex));
    let px = 1.0 / texSize;
    let tl = lum(textureSample(simplifiedTex, inputSampler, uv + px * vec2<f32>(-1.0,  1.0)).rgb);
    let l  = lum(textureSample(simplifiedTex, inputSampler, uv + px * vec2<f32>(-1.0,  0.0)).rgb);
    let bl = lum(textureSample(simplifiedTex, inputSampler, uv + px * vec2<f32>(-1.0, -1.0)).rgb);
    let tr = lum(textureSample(simplifiedTex, inputSampler, uv + px * vec2<f32>( 1.0,  1.0)).rgb);
    let r  = lum(textureSample(simplifiedTex, inputSampler, uv + px * vec2<f32>( 1.0,  0.0)).rgb);
    let br = lum(textureSample(simplifiedTex, inputSampler, uv + px * vec2<f32>( 1.0, -1.0)).rgb);
    let t  = lum(textureSample(simplifiedTex, inputSampler, uv + px * vec2<f32>( 0.0,  1.0)).rgb);
    let b  = lum(textureSample(simplifiedTex, inputSampler, uv + px * vec2<f32>( 0.0, -1.0)).rgb);
    return vec2<f32>(tr + 2.0 * r + br - tl - 2.0 * l - bl,
                      tl + 2.0 * t + tr - bl - 2.0 * b - br);
}

@fragment
fn main(@builtin(position) pos: vec4<f32>) -> @location(0) vec4<f32> {
    let texSize = vec2<f32>(textureDimensions(inputTex));
    let uv = pos.xy / texSize;
    let src = textureSample(inputTex, inputSampler, uv);
    let simplified = textureSample(simplifiedTex, inputSampler, uv).rgb;

    let edge = length(lumGradientSimplified(uv));

    // Pigment pooling: darken along simplified-region boundaries, the way
    // watercolor pigment collects and dries darker at the edge of a wet wash.
    let pool = uniforms.shadowIntensity / 100.0 * 0.7 * smoothstep(0.05, 0.4, edge);
    var c = simplified * (1.0 - pool);

    // Paper granulation: hash/noise coordinate is the integer, tile-aware
    // global pixel index so the grain
    // aligns across GL/WGPU and across render tiles. Both the grain
    // strength and the warm paper tint are gated by paperTexture, so
    // paperTexture=0 yields a smooth, untinted wash and paperTexture=100
    // is full grain plus full tint.
    let gc = floor(pos.xy) + uniforms.tileOffset;
    c *= mix(1.0, 0.92 + 0.08 * vnoise(gc / 3.5), clamp(uniforms.paperTexture, 0.0, 100.0) / 100.0);
    c = mix(c, c * vec3<f32>(1.02, 1.0, 0.95), uniforms.paperTexture / 100.0);

    // Wash lift: on flat washes (edge near 0) lift the color very slightly
    // toward its own luminance (desaturate) and brighten a touch, as if the
    // pigment thinned out there and let the white paper glow through --
    // complement of the pooling darkening above, same `edge` field with an
    // inverted falloff.
    let flatness = 1.0 - smoothstep(0.0, 0.15, edge);
    c = mix(c, vec3<f32>(lum(c)), flatness * 0.12);
    c *= 1.0 + flatness * 0.05;

    return vec4<f32>(clamp(c, vec3<f32>(0.0), vec3<f32>(1.0)), src.a);
}

/*
 * Watercolor - seed pass: copies the source image into the ping-pong state
 * texture before the iterated stride-median simplify passes run.
 */

@group(0) @binding(0) var inputSampler: sampler;
@group(0) @binding(1) var inputTex: texture_2d<f32>;

@fragment
fn main(@builtin(position) pos: vec4<f32>) -> @location(0) vec4<f32> {
    let texSize = vec2<f32>(textureDimensions(inputTex));
    let uv = pos.xy / texSize;
    return textureSample(inputTex, inputSampler, uv);
}

/*
 * Watercolor - simplify pass: 3x3 median network (Devillard opt_med9, the
 * same 19-op compare-exchange sequence as filter/median's medianPass.wgsl)
 * sampled at a pixel stride that widens as `detail` decreases. See
 * glsl/wcSimplify.glsl for the full description. Executed twice per frame
 * (fixed `repeat: 2` in definition.js), ping-ponging global_wc_state.
 */

struct Uniforms {
    detail: f32,
}

@group(0) @binding(0) var inputSampler: sampler;
@group(0) @binding(1) var inputTex: texture_2d<f32>;
@group(0) @binding(2) var<uniform> uniforms: Uniforms;

fn sort2(a: ptr<function, vec3<f32>>, b: ptr<function, vec3<f32>>) {
    let lo = min(*a, *b);
    let hi = max(*a, *b);
    *a = lo;
    *b = hi;
}

@fragment
fn main(@builtin(position) pos: vec4<f32>) -> @location(0) vec4<f32> {
    let texSize = vec2<f32>(textureDimensions(inputTex));
    // detail=0 -> stride 3px (coarse); detail=100 -> stride 1px (fine).
    let stride = mix(3.0, 1.0, clamp(uniforms.detail, 0.0, 100.0) / 100.0);
    let texel = stride / texSize;
    let uv = pos.xy / texSize;

    let s0 = textureSample(inputTex, inputSampler, uv + vec2<f32>(-texel.x, -texel.y));
    let s1 = textureSample(inputTex, inputSampler, uv + vec2<f32>(0.0, -texel.y));
    let s2 = textureSample(inputTex, inputSampler, uv + vec2<f32>(texel.x, -texel.y));
    let s3 = textureSample(inputTex, inputSampler, uv + vec2<f32>(-texel.x, 0.0));
    let s4 = textureSample(inputTex, inputSampler, uv);
    let s5 = textureSample(inputTex, inputSampler, uv + vec2<f32>(texel.x, 0.0));
    let s6 = textureSample(inputTex, inputSampler, uv + vec2<f32>(-texel.x, texel.y));
    let s7 = textureSample(inputTex, inputSampler, uv + vec2<f32>(0.0, texel.y));
    let s8 = textureSample(inputTex, inputSampler, uv + vec2<f32>(texel.x, texel.y));

    var p0 = s0.rgb; var p1 = s1.rgb; var p2 = s2.rgb;
    var p3 = s3.rgb; var p4 = s4.rgb; var p5 = s5.rgb;
    var p6 = s6.rgb; var p7 = s7.rgb; var p8 = s8.rgb;

    sort2(&p1, &p2); sort2(&p4, &p5); sort2(&p7, &p8);
    sort2(&p0, &p1); sort2(&p3, &p4); sort2(&p6, &p7);
    sort2(&p1, &p2); sort2(&p4, &p5); sort2(&p7, &p8);
    sort2(&p0, &p3); sort2(&p5, &p8); sort2(&p4, &p7);
    sort2(&p3, &p6); sort2(&p1, &p4); sort2(&p2, &p5);
    sort2(&p4, &p7); sort2(&p4, &p2); sort2(&p6, &p4);
    sort2(&p4, &p2);

    return vec4<f32>(p4, s4.a);
}

/*
 * Sine wave distortion
 */

struct Uniforms {
    strength: f32,
    scale: f32,
    speed: i32,
    wrap: i32,
    rotation: f32,
    antialias: i32,
    tileOffset: vec2<f32>,
    fullResolution: vec2<f32>,
}

@group(0) @binding(0) var inputSampler: sampler;
@group(0) @binding(1) var inputTex: texture_2d<f32>;
@group(0) @binding(2) var<uniform> uniforms: Uniforms;
@group(0) @binding(3) var<uniform> time: f32;

const PI: f32 = 3.14159265359;
const TAU: f32 = 6.28318530718;

fn rotate2D(st_in: vec2<f32>, rot: f32, aspectRatio: f32) -> vec2<f32> {
    var st = st_in;
    st.x = st.x * aspectRatio;
    let angle = rot * PI;
    st = st - vec2<f32>(0.5 * aspectRatio, 0.5);
    let c = cos(angle);
    let s = sin(angle);
    st = mat2x2<f32>(c, -s, s, c) * st;
    st = st + vec2<f32>(0.5 * aspectRatio, 0.5);
    st.x = st.x / aspectRatio;
    return st;
}

@fragment
fn main(@builtin(position) pos: vec4<f32>) -> @location(0) vec4<f32> {
    let texSize = vec2<f32>(textureDimensions(inputTex));
    let aspectRatio = uniforms.fullResolution.x / uniforms.fullResolution.y;
    let globalCoord = pos.xy + uniforms.tileOffset;
    var uv = globalCoord / uniforms.fullResolution;

    let strength = uniforms.strength;
    let scale = uniforms.scale;
    let speed = uniforms.speed;
    let t = time;

    // Apply rotation before distortion
    uv = rotate2D(uv, uniforms.rotation / 180.0, aspectRatio);

    // Sine wave distortion
    var displacement = sin(uv.x * scale * 10.0 + t * TAU * f32(speed)) * (strength * 0.01);

    // Bound displacement to overlap in tile mode to prevent seams
    if (any(uniforms.tileOffset != vec2<f32>(0.0))) {
        let maxDisplacementUV = 256.0 / uniforms.fullResolution.y;
        displacement = clamp(displacement, -maxDisplacementUV, maxDisplacementUV);
    }

    uv.y = uv.y + displacement;

    // Apply wrap mode
    if (uniforms.wrap == 0) {
        // mirror
        uv = abs((uv + 1.0) - 2.0 * floor((uv + 1.0) / 2.0) - 1.0);
    } else if (uniforms.wrap == 1) {
        // repeat
        uv = (uv - 1.0 * floor(uv / 1.0));
    } else {
        // clamp
        uv = clamp(uv, vec2<f32>(0.0), vec2<f32>(1.0));
    }

    // Reverse rotation after distortion
    uv = rotate2D(uv, -uniforms.rotation / 180.0, aspectRatio);

    // Convert distorted global UV to tile-local UV.
    let localCoord = (uv * uniforms.fullResolution - uniforms.tileOffset) / texSize;

    // In tile mode, wrap to enable seamless tiling. In normal mode, clamp to preserve original behavior.
    let sampleUV = select(clamp(localCoord, vec2<f32>(0.0), vec2<f32>(1.0)), fract(localCoord), any(uniforms.tileOffset != vec2<f32>(0.0)));

    if (uniforms.antialias != 0) {
        let dx = dpdx(sampleUV);
        let dy = dpdy(sampleUV);
        var col = vec4<f32>(0.0);
        col += textureSample(inputTex, inputSampler, sampleUV + dx * -0.375 + dy * -0.125);
        col += textureSample(inputTex, inputSampler, sampleUV + dx *  0.125 + dy * -0.375);
        col += textureSample(inputTex, inputSampler, sampleUV + dx *  0.375 + dy *  0.125);
        col += textureSample(inputTex, inputSampler, sampleUV + dx * -0.125 + dy *  0.375);
        return col * 0.25;
    } else {
        return textureSample(inputTex, inputSampler, sampleUV);
    }
}

/* Wind — 1:1 port of the coherent scanline integration in wind.glsl. */

// METHOD is a runtime-injected module-scope const (injectDefines, see
// definition.js `globals.method.define`). Dawn/naga constant-fold the
// wind/blast/stagger dispatch so only the active decay/taper/density/gain
// arm survives compilation.
struct Uniforms {
    direction: i32,
    strength: f32,
    threshold: f32,
    tileOffset: vec2<f32>,
}

@group(0) @binding(0) var inputSampler: sampler;
@group(0) @binding(1) var inputTex: texture_2d<f32>;
@group(0) @binding(2) var<uniform> uniforms: Uniforms;

const MAX_STEPS: i32 = 128;
const STEP_PX: f32 = 1.0;
const MAX_REACH: f32 = 128.0;

fn lum(c: vec3<f32>) -> f32 {
    return dot(c, vec3<f32>(0.2126, 0.7152, 0.0722));
}

@fragment
fn main(@builtin(position) pos: vec4<f32>) -> @location(0) vec4<f32> {
    let texSize = vec2<f32>(textureDimensions(inputTex));
    let uv = pos.xy / texSize;
    let globalCoord = pos.xy + uniforms.tileOffset;
    let src = textureSample(inputTex, inputSampler, uv);

    let amount = clamp(uniforms.strength / 100.0, 0.0, 1.0);
    if (amount <= 0.0) {
        return src;
    }

    let reach = MAX_REACH * amount;
    let marchDir = select(1.0, -1.0, uniforms.direction == 0);
    var staggerPhase = 0.0;
    if (METHOD == 2) {
        staggerPhase = (0.5 + 0.5 * sin(globalCoord.y * 0.22))
            * min(12.0, reach * 0.18);
    }

    var accumColor = vec3<f32>(0.0);
    var accumWeight = 0.0;
    let baseLum = lum(src.rgb);
    let edge = uniforms.threshold / 100.0;

    for (var i: i32 = 1; i <= MAX_STEPS; i++) {
        let distancePx = f32(i) * STEP_PX;
        if (distancePx > reach) { break; }

        let sampleDistance = distancePx + staggerPhase;
        let sampleUV = clamp(
            (pos.xy + vec2<f32>(marchDir * sampleDistance, 0.0)) / texSize,
            vec2<f32>(0.0), vec2<f32>(1.0));
        let candidate = textureSample(inputTex, inputSampler, sampleUV).rgb;

        let contrast = lum(candidate) - baseLum - edge;
        let activation = smoothstep(0.0, 0.08, contrast);
        let alongRun = distancePx / max(reach, 1.0);
        var decayRate = 3.4;
        if (METHOD == 1) {
            decayRate = 0.8;
        } else if (METHOD == 2) {
            decayRate = 2.0;
        }
        var taperStart = 0.72;
        if (METHOD == 1) {
            taperStart = 0.82;
        }
        let endTaper = 1.0 - smoothstep(taperStart, 1.0, alongRun);
        let weight = activation * exp(-decayRate * alongRun) * endTaper;
        accumColor += candidate * weight;
        accumWeight += weight;
    }

    let integrated = accumColor / max(accumWeight, 0.00001);
    var densityRate = 0.16;
    if (METHOD == 1) {
        densityRate = 0.12;
    }
    let density = 1.0 - exp(-accumWeight * densityRate);
    var methodGain = 0.88;
    if (METHOD == 1) {
        methodGain = 1.0;
    }
    let blendAmount = clamp(density * amount * methodGain, 0.0, 1.0);
    let streak = mix(src.rgb, integrated, blendAmount);

    return vec4<f32>(max(src.rgb, streak), src.a);
}

// Wobble effect - offsets the entire frame using noise-driven jitter

struct VertexOutput {
    @builtin(position) position: vec4<f32>,
    @location(0) uv: vec2<f32>,
}

@group(0) @binding(0) var u_sampler: sampler;
@group(0) @binding(1) var inputTex: texture_2d<f32>;
@group(0) @binding(2) var<uniform> speed: f32;
@group(0) @binding(3) var<uniform> range: f32;
@group(0) @binding(4) var<uniform> time: f32;
@group(0) @binding(5) var<uniform> wrap: i32;

const TAU: f32 = 6.28318530717959;
const X_NOISE_SEED: vec3<f32> = vec3<f32>(17.0, 29.0, 11.0);
const Y_NOISE_SEED: vec3<f32> = vec3<f32>(41.0, 23.0, 7.0);

fn pcg(seed: vec3<u32>) -> vec3<u32> {
    var v = seed * 1664525u + 1013904223u;
    v.x = v.x + v.y * v.z;
    v.y = v.y + v.z * v.x;
    v.z = v.z + v.x * v.y;
    v = v ^ (v >> vec3<u32>(16u));
    v.x = v.x + v.y * v.z;
    v.y = v.y + v.z * v.x;
    v.z = v.z + v.x * v.y;
    return v;
}

fn hash31(p: vec3<f32>) -> f32 {
    let seed = vec3<u32>(
        u32(select(-p.x * 2.0 + 1.0, p.x * 2.0, p.x >= 0.0)),
        u32(select(-p.y * 2.0 + 1.0, p.y * 2.0, p.y >= 0.0)),
        u32(select(-p.z * 2.0 + 1.0, p.z * 2.0, p.z >= 0.0))
    );
    return f32(pcg(seed).x) / f32(0xffffffffu);
}

fn noise3d(p: vec3<f32>) -> f32 {
    let i = floor(p);
    var f = fract(p);
    f = f * f * (3.0 - 2.0 * f);

    let n000 = hash31(i);
    let n100 = hash31(i + vec3<f32>(1.0, 0.0, 0.0));
    let n010 = hash31(i + vec3<f32>(0.0, 1.0, 0.0));
    let n110 = hash31(i + vec3<f32>(1.0, 1.0, 0.0));
    let n001 = hash31(i + vec3<f32>(0.0, 0.0, 1.0));
    let n101 = hash31(i + vec3<f32>(1.0, 0.0, 1.0));
    let n011 = hash31(i + vec3<f32>(0.0, 1.0, 1.0));
    let n111 = hash31(i + vec3<f32>(1.0, 1.0, 1.0));

    let x0 = mix(n000, n100, f.x);
    let x1 = mix(n010, n110, f.x);
    let x2 = mix(n001, n101, f.x);
    let x3 = mix(n011, n111, f.x);

    let y0 = mix(x0, x1, f.y);
    let y1 = mix(x2, x3, f.y);

    return mix(y0, y1, f.z);
}

fn simplexRandom(t: f32, spd: f32, seed: vec3<f32>) -> f32 {
    let angle = t * TAU;
    // Include speed in the noise coordinates so output varies with speed even at time=0
    let z = cos(angle) * spd + seed.x + spd * 0.317;
    let w = sin(angle) * spd + seed.y + spd * 0.519;
    let n = noise3d(vec3<f32>(z, w, seed.z + spd * 0.1));
    return clamp(n, 0.0, 1.0);
}

fn applyWrap(uv: vec2<f32>) -> vec2<f32> {
    if (wrap == 0) {
        // Mirror: abs(mod(uv + 1, 2) - 1)
        let mx = abs((uv.x + 1.0) - floor((uv.x + 1.0) * 0.5) * 2.0 - 1.0);
        let my = abs((uv.y + 1.0) - floor((uv.y + 1.0) * 0.5) * 2.0 - 1.0);
        return vec2<f32>(mx, my);
    } else if (wrap == 1) {
        return fract(uv);  // repeat
    }
    return clamp(uv, vec2<f32>(0.0), vec2<f32>(1.0));  // clamp
}

@fragment
fn main(in: VertexOutput) -> @location(0) vec4<f32> {
    // Speed directly affects the noise sampling position
    // This ensures changing speed produces different noise values
    let spd = max(speed, 0.001);
    let r = max(range, 0.0);

    // Compute jitter offsets - speed affects both the noise input and output scale
    let xRandom = simplexRandom(time + speed * 0.1, spd, X_NOISE_SEED);
    let yRandom = simplexRandom(time + speed * 0.1, spd, Y_NOISE_SEED);

    // Scale offset by range - controls displacement amount
    let offsetScale = r * (0.01 + speed * 0.02);
    let offset = (vec2<f32>(xRandom, yRandom) - 0.5) * offsetScale;

    // Apply offset to texture coordinate
    // The output-normalized coordinate, as the GLSL's gl_FragCoord /
    // resolution; the default vertex uv has a bottom-left origin, so it is
    // flipped vertically.
    var sampleCoord = vec2<f32>(in.uv.x, 1.0 - in.uv.y) + offset;
    sampleCoord = applyWrap(sampleCoord);

    let sampled = textureSample(inputTex, u_sampler, sampleCoord);

    return sampled;
}

// Wormhole Blend
// Normalize accumulated scatter buffer, sqrt, blend with original.
// Uses mean-based normalization (robust to sparse sampling) instead of
// min/max (which flickered due to missing outlier hotspots in the grid).

@group(0) @binding(0) var u_sampler : sampler;
@group(0) @binding(1) var inputTex : texture_2d<f32>;
@group(0) @binding(2) var accumTex : texture_2d<f32>;
@group(0) @binding(3) var<uniform> resolution : vec2<f32>;
@group(0) @binding(4) var<uniform> alpha : f32;

@fragment
fn main(@builtin(position) position : vec4<f32>) -> @location(0) vec4<f32> {
    let uv = position.xy / resolution;

    let src = textureSampleLevel(inputTex, u_sampler, uv, 0.0);
    let accum = textureSampleLevel(accumTex, u_sampler, uv, 0.0);

    // Estimate mean of accum buffer from 32x32 grid (1024 samples).
    // Mean is robust to sparse sampling unlike min/max.
    var sum : f32 = 0.0;
    var count : f32 = 0.0;
    for (var gy : i32 = 0; gy < 32; gy = gy + 1) {
        for (var gx : i32 = 0; gx < 32; gx = gx + 1) {
            let sampleUV = (vec2<f32>(f32(gx), f32(gy)) + 0.5) / 32.0;
            let s = textureSampleLevel(accumTex, u_sampler, sampleUV, 0.0);
            let v = (s.r + s.g + s.b) / 3.0;
            sum = sum + v;
            count = count + 1.0;
        }
    }
    let mean = sum / count;

    // Normalize: scale so that mean maps to ~0.25 (after sqrt -> ~0.5)
    var normalized : vec3<f32>;
    if (mean > 0.0) {
        normalized = clamp(accum.rgb / (mean * 4.0), vec3<f32>(0.0), vec3<f32>(1.0));
    } else {
        normalized = accum.rgb;
    }

    let sqrtVal = sqrt(normalized);

    return vec4<f32>(mix(src.rgb, sqrtVal, alpha), src.a);
}

struct Uniforms {
    resolution: vec2<f32>,
}

@group(0) @binding(0) var<uniform> u: Uniforms;

@fragment
fn main() -> @location(0) vec4<f32> {
    return vec4<f32>(0.0);
}

// Wormhole Deposit - Scatter pixels to destination based on OKLab L channel

struct Uniforms {
    resolution: vec2<f32>,
    kink: f32,
    stride: f32,
    rotation: f32,
    wrap: i32,
};

struct VertexOutput {
    @builtin(position) position: vec4<f32>,
    @location(0) color: vec4<f32>,
};

@group(0) @binding(0) var<uniform> u: Uniforms;
@group(0) @binding(1) var inputTex: texture_2d<f32>;

const TAU: f32 = 6.28318530717959;

// OKLab L channel extraction (matches JS rgbToOklab -> L)
fn oklabL(rgb: vec3<f32>) -> f32 {
    let c = clamp(rgb, vec3<f32>(0.0), vec3<f32>(1.0));
    let l = 0.4122214708 * c.r + 0.5363325363 * c.g + 0.0514459929 * c.b;
    let m = 0.2119034982 * c.r + 0.6806995451 * c.g + 0.1073969566 * c.b;
    let s = 0.0883024619 * c.r + 0.2817188376 * c.g + 0.6299787005 * c.b;
    let l_ = pow(max(l, 0.0), 1.0 / 3.0);
    let m_ = pow(max(m, 0.0), 1.0 / 3.0);
    let s_ = pow(max(s, 0.0), 1.0 / 3.0);
    return 0.2104542553 * l_ + 0.7936177850 * m_ - 0.0040720468 * s_;
}

@vertex
fn vertexMain(@builtin(vertex_index) vertexIndex: u32) -> VertexOutput {
    var out: VertexOutput;

    let texSize = textureDimensions(inputTex, 0);
    let w = i32(texSize.x);
    let h = i32(texSize.y);

    if (i32(vertexIndex) >= w * h) {
        out.position = vec4<f32>(2.0, 2.0, 0.0, 1.0);
        out.color = vec4<f32>(0.0);
        return out;
    }

    let srcX = i32(vertexIndex) % w;
    let srcY = i32(vertexIndex) / w;

    let src = textureLoad(inputTex, vec2<i32>(srcX, srcY), 0);
    let lum = oklabL(src.rgb);

    let angle = lum * TAU * u.kink + radians(u.rotation);
    let pixelStride = 1024.0 * u.stride;

    let ox = (cos(angle) + 1.0) * pixelStride;
    let oy = (sin(angle) + 1.0) * pixelStride;

    var destX = i32(floor(f32(srcX) + ox));
    var destY = i32(floor(f32(srcY) + oy));

    // Branchless wrap modes (critical for vertex shader performance)
    if (u.wrap == 0) {
        // Mirror
        let mx = ((destX % (w * 2)) + w * 2) % (w * 2);
        let my = ((destY % (h * 2)) + h * 2) % (h * 2);
        destX = w - 1 - abs(mx - w + 1);
        destY = h - 1 - abs(my - h + 1);
    } else if (u.wrap == 2) {
        // Clamp
        destX = clamp(destX, 0, w - 1);
        destY = clamp(destY, 0, h - 1);
    } else {
        // Repeat (default)
        destX = ((destX % w) + w) % w;
        destY = ((destY % h) + h) % h;
    }

    let clipX = (f32(destX) + 0.5) / f32(w) * 2.0 - 1.0;
    // WebGPU Y is flipped vs WebGL2
    let clipY = 1.0 - (f32(destY) + 0.5) / f32(h) * 2.0;

    out.position = vec4<f32>(clipX, clipY, 0.0, 1.0);
    out.color = vec4<f32>(src.rgb * lum * lum, 0.0);
    return out;
}

@fragment
fn fragmentMain(in: VertexOutput) -> @location(0) vec4<f32> {
    return in.color;
}

/*
 * Zoom/radial blur effect
 * Creates a radial blur emanating from the center
 */

struct Uniforms {
    strength: f32,
    _pad1: f32,
    _pad2: f32,
    _pad3: f32,
    tileOffset: vec2<f32>,
    fullResolution: vec2<f32>,
}

@group(0) @binding(0) var inputSampler: sampler;
@group(0) @binding(1) var inputTex: texture_2d<f32>;
@group(0) @binding(2) var<uniform> uniforms: Uniforms;

// PCG PRNG
fn pcg(v_in: vec3<u32>) -> vec3<u32> {
    var v = v_in * 1664525u + 1013904223u;
    v.x += v.y * v.z;
    v.y += v.z * v.x;
    v.z += v.x * v.y;
    v = v ^ (v >> vec3<u32>(16u));
    v.x += v.y * v.z;
    v.y += v.z * v.x;
    v.z += v.x * v.y;
    return v;
}

fn prng(p: vec3<f32>) -> vec3<f32> {
    return vec3<f32>(pcg(vec3<u32>(p))) / f32(0xffffffffu);
}

@fragment
fn main(@builtin(position) pos: vec4<f32>) -> @location(0) vec4<f32> {
    let texSize = vec2<f32>(textureDimensions(inputTex));
    let tileDims = texSize;
    let fullRes = select(tileDims, uniforms.fullResolution, uniforms.fullResolution.x > 0.0);
    let uv = pos.xy / tileDims;
    let globalUV = (pos.xy + uniforms.tileOffset) / fullRes;

    var color = vec3<f32>(0.0);
    var total = 0.0;
    let toCenter = globalUV - 0.5;

    // Randomize the lookup values to hide the fixed number of samples
    let offset = prng(vec3<f32>(12.9898, 78.233, 151.7182)).x;

    for (var t = 0.0; t <= 40.0; t = t + 1.0) {
        let percent = (t + offset) / 40.0;
        let weight = 4.0 * (percent - percent * percent);
        let tex = textureSampleLevel(inputTex, inputSampler, uv + toCenter * percent * uniforms.strength, 0.0);
        color = color + tex.rgb * weight;
        total = total + weight;
    }

    color = color / total;

    return vec4<f32>(color, 1.0);
}

/*
 * Flow3D agent pass (WGSL) - 3D GPGPU agent simulation with MRT output
 * 
 * Agent format:
 * - state1: [x, y, z, rotRand]     - 3D position + rotation randomness
 * - state2: [r, g, b, seed]        - color + seed
 * - state3: [age, initialized, strideRand, 0] - age, init flag, per-agent stride random
 */

struct Outputs {
    @location(0) outState1: vec4<f32>,
    @location(1) outState2: vec4<f32>,
    @location(2) outState3: vec4<f32>,
}

// BEHAVIOR is a compile-time const injected by the runtime via injectDefines
// (see definition.js `globals.behavior.define`). Same fix as the GLSL
// backend — emits only one rotation-bias branch per compiled program. The
// old `behavior` binding at @group(0) @binding(9) is removed.

@group(0) @binding(0) var stateTex1: texture_2d<f32>;
@group(0) @binding(1) var stateTex2: texture_2d<f32>;
@group(0) @binding(2) var stateTex3: texture_2d<f32>;
@group(0) @binding(3) var mixerTex: texture_2d<f32>;
@group(0) @binding(4) var<uniform> stride: f32;
@group(0) @binding(5) var<uniform> strideDeviation: f32;
@group(0) @binding(6) var<uniform> kink: f32;
@group(0) @binding(7) var<uniform> time: f32;
@group(0) @binding(8) var<uniform> lifetime: f32;
@group(0) @binding(10) var<uniform> volumeSize: i32;

const TAU: f32 = 6.283185307179586;
const PI: f32 = 3.141592653589793;
const RIGHT_ANGLE: f32 = 1.5707963267948966;

fn hash_uint(seed: u32) -> u32 {
    var state = seed * 747796405u + 2891336453u;
    let word = ((state >> ((state >> 28u) + 4u)) ^ state) * 277803737u;
    return (word >> 22u) ^ word;
}

fn hash(seed: u32) -> f32 {
    return f32(hash_uint(seed)) / 4294967295.0;
}

fn hash3(seed: u32) -> vec3<f32> {
    return vec3<f32>(hash(seed), hash(seed + 1u), hash(seed + 2u));
}

fn wrap_float(value: f32, size: f32) -> f32 {
    if (size <= 0.0) { return 0.0; }
    let scaled = floor(value / size);
    var wrapped = value - scaled * size;
    if (wrapped < 0.0) { wrapped = wrapped + size; }
    return wrapped;
}

fn wrap_int(value: i32, size: i32) -> i32 {
    if (size <= 0) { return 0; }
    var result = value % size;
    if (result < 0) { result = result + size; }
    return result;
}

// Convert 3D voxel coord to 2D atlas texel coord
fn atlasTexel(p: vec3<i32>, volSize: i32) -> vec2<i32> {
    let clamped = clamp(p, vec3<i32>(0), vec3<i32>(volSize - 1));
    return vec2<i32>(clamped.x, clamped.y + clamped.z * volSize);
}

// Sample 3D volume at integer voxel position (matching 2D texelFetch pattern)
fn sampleVoxel(voxel: vec3<i32>, volSize: i32) -> vec4<f32> {
    let clamped = clamp(voxel, vec3<i32>(0), vec3<i32>(volSize - 1));
    return textureLoad(mixerTex, atlasTexel(clamped, volSize), 0);
}

fn srgb_to_linear(value: f32) -> f32 {
    if (value <= 0.04045) { return value / 12.92; }
    return pow((value + 0.055) / 1.055, 2.4);
}

fn cube_root(value: f32) -> f32 {
    if (value == 0.0) { return 0.0; }
    let sign_value = select(-1.0, 1.0, value >= 0.0);
    return sign_value * pow(abs(value), 1.0 / 3.0);
}

fn oklab_l(rgb: vec3<f32>) -> f32 {
    let r_lin = srgb_to_linear(clamp(rgb.x, 0.0, 1.0));
    let g_lin = srgb_to_linear(clamp(rgb.y, 0.0, 1.0));
    let b_lin = srgb_to_linear(clamp(rgb.z, 0.0, 1.0));
    let l = 0.4121656120 * r_lin + 0.5362752080 * g_lin + 0.0514575653 * b_lin;
    let m = 0.2118591070 * r_lin + 0.6807189584 * g_lin + 0.1074065790 * b_lin;
    let s = 0.0883097947 * r_lin + 0.2818474174 * g_lin + 0.6302613616 * b_lin;
    return 0.2104542553 * cube_root(l) + 0.7936177850 * cube_root(m) - 0.0040720468 * cube_root(s);
}

fn normalized_sine(value: f32) -> f32 {
    return (sin(value) + 1.0) * 0.5;
}

fn computeRotationBias(baseHeading: f32, baseRotRand: f32, time: f32, agentIndex: i32, totalAgents: i32) -> f32 {
    if (BEHAVIOR <= 0) {
        return 0.0;
    } else if (BEHAVIOR == 1) {
        return baseHeading;
    } else if (BEHAVIOR == 2) {
        // Crosshatch: 4 cardinal directions (PI/2 spacing) to match the 2D
        // reference in points/flow and the GLSL flow3d backend.
        return baseHeading + floor(baseRotRand * 4.0) * RIGHT_ANGLE;
    } else if (BEHAVIOR == 3) {
        return baseHeading + (baseRotRand - 0.5) * 0.25;
    } else if (BEHAVIOR == 4) {
        return baseRotRand * TAU;
    } else if (BEHAVIOR == 5) {
        let quarterSize = max(1, totalAgents / 4);
        let band = agentIndex / quarterSize;
        if (band <= 0) {
            return baseHeading;
        } else if (band == 1) {
            // Also 4 cardinal directions for parity with 2D reference.
            return baseHeading + floor(baseRotRand * 4.0) * RIGHT_ANGLE;
        } else if (band == 2) {
            return baseHeading + (baseRotRand - 0.5) * 0.25;
        } else {
            return baseRotRand * TAU;
        }
    } else if (BEHAVIOR == 10) {
        return normalized_sine((time - baseRotRand) * TAU);
    } else {
        return baseRotRand * TAU;
    }
}

@fragment
fn main(@builtin(position) position: vec4<f32>) -> Outputs {
    var output: Outputs;

    let coord = vec2<i32>(position.xy);
    // Use actual state texture size, not canvas resolution
    let stateTexSize = textureDimensions(stateTex1, 0);
    let width = i32(stateTexSize.x);
    let height = i32(stateTexSize.y);

    let volSize = volumeSize;
    let volSizeF = f32(volSize);

    let state1 = textureLoad(stateTex1, coord, 0);
    let state2 = textureLoad(stateTex2, coord, 0);
    let state3 = textureLoad(stateTex3, coord, 0);

    var flow_x = state1.x;
    var flow_y = state1.y;
    var flow_z = state1.z;
    var rotRand = state1.w;
    var cr = state2.x;
    var cg = state2.y;
    var cb = state2.z;
    var seed_f = state2.w;
    var age = state3.x;
    var initialized = state3.y;
    var strideRand = state3.z;  // Per-agent random [-0.5, 0.5] for stride variation

    let agentSeed = u32(coord.x + coord.y * width);
    let baseSeed = agentSeed + u32(time * 1000.0);

    let totalAgents = width * height;
    let agentIndex = coord.x + coord.y * width;

    // Initialize agent if needed
    if (initialized < 0.5) {
        let pos = hash3(agentSeed);
        flow_x = pos.x * volSizeF;
        flow_y = pos.y * volSizeF;
        flow_z = pos.z * volSizeF;

        rotRand = hash(agentSeed + 200u);
        strideRand = hash(agentSeed + 300u) - 0.5;

        let xi = wrap_int(i32(flow_x), volSize);
        let yi = wrap_int(i32(flow_y), volSize);
        let zi = wrap_int(i32(flow_z), volSize);
        let inputColor = sampleVoxel(vec3<i32>(xi, yi, zi), volSize);

        cr = inputColor.r;
        cg = inputColor.g;
        cb = inputColor.b;

        seed_f = f32(agentSeed);
        age = 0.0;
        initialized = 1.0;
    }

    // Check for respawn
    let agentPhase = f32(agentIndex) / f32(max(totalAgents, 1));
    let staggeredAge = age + agentPhase * lifetime;
    let shouldRespawn = lifetime > 0.0 && staggeredAge >= lifetime;

    if (shouldRespawn) {
        let pos = hash3(baseSeed);
        flow_x = pos.x * volSizeF;
        flow_y = pos.y * volSizeF;
        flow_z = pos.z * volSizeF;

        rotRand = hash(baseSeed + 200u);

        let xi = wrap_int(i32(flow_x), volSize);
        let yi = wrap_int(i32(flow_y), volSize);
        let zi = wrap_int(i32(flow_z), volSize);
        let inputColor = sampleVoxel(vec3<i32>(xi, yi, zi), volSize);

        cr = inputColor.r;
        cg = inputColor.g;
        cb = inputColor.b;

        age = 0.0;
    }

    // Sample input texture at current position for flow direction
    let xi = wrap_int(i32(flow_x), volSize);
    let yi = wrap_int(i32(flow_y), volSize);
    let zi = wrap_int(i32(flow_z), volSize);
    let texel = sampleVoxel(vec3<i32>(xi, yi, zi), volSize);

    let indexValue = oklab_l(texel.rgb);

    let baseHeading = hash(0u) * TAU;
    let rotationBias = computeRotationBias(baseHeading, rotRand, time, agentIndex, totalAgents);

    // For 3D: azimuth angle (XY plane) - direct extension of 2D angle
    let azimuth = indexValue * TAU * kink + rotationBias;

    // Elevation: use indexValue to modulate vertical movement
    let elevation = (indexValue - 0.5) * PI * kink * 0.5;

    let cosElev = cos(elevation);


    let scale = max(volSizeF / 64.0, 1.0);
    let devFactor = 1.0 + strideRand * 2.0 * strideDeviation;
    let actualStride = max(0.1, stride * scale * devFactor);

    var newX = flow_x + sin(azimuth) * cosElev * actualStride;
    var newY = flow_y + cos(azimuth) * cosElev * actualStride;
    var newZ = flow_z + sin(elevation) * actualStride;

    newX = wrap_float(newX, volSizeF);
    newY = wrap_float(newY, volSizeF);
    newZ = wrap_float(newZ, volSizeF);

    age = age + 0.016;

    output.outState1 = vec4<f32>(newX, newY, newZ, rotRand);
    output.outState2 = vec4<f32>(cr, cg, cb, seed_f);
    output.outState3 = vec4<f32>(age, initialized, strideRand, 0.0);

    return output;
}

/*
 * Flow3D blend pass (WGSL) - Combine input 3D volume with trail 3D volume
 * Direct port of nu/flow blend to 3D atlas format
 * 
 * Both mixerTex (inputTex3d) and trailTex are 2D atlas representations
 * of 3D volumes (width=volumeSize, height=volumeSize²)
 */

@group(0) @binding(0) var mixerTex: texture_2d<f32>;
@group(0) @binding(1) var trailTex: texture_2d<f32>;
@group(0) @binding(2) var<uniform> inputIntensity: f32;

@fragment
fn main(@builtin(position) position: vec4<f32>) -> @location(0) vec4<f32> {
    let coord = vec2<i32>(position.xy);

    // Both textures are 3D atlas format, sample directly with integer coords
    let inputIntensityValue = inputIntensity / 100.0;
    let baseSample = textureLoad(mixerTex, coord, 0);
    let baseColor = vec4<f32>(baseSample.rgb * inputIntensityValue, baseSample.a);

    let trailColor = textureLoad(trailTex, coord, 0);

    // Combine: add trail on top of input (same as 2D flow)
    let combinedRgb = clamp(baseColor.rgb + trailColor.rgb, vec3<f32>(0.0), vec3<f32>(1.0));
    let finalAlpha = clamp(max(baseColor.a, trailColor.a), 0.0, 1.0);

    return vec4<f32>(combinedRgb, finalAlpha);
}

/*
 * Flow3D copy pass (WGSL) - Blit source to destination (for ping-pong correction after diffuse)
 * This ensures the decayed trail is in the write buffer before deposit blends onto it
 */

@group(0) @binding(0) var sourceTex: texture_2d<f32>;

@fragment
fn main(@builtin(position) position: vec4<f32>) -> @location(0) vec4<f32> {
    let coord = vec2<i32>(position.xy);
    return textureLoad(sourceTex, coord, 0);
}

/*
 * Flow3D deposit pass (WGSL) - positions agents in 3D volume atlas
 */

@group(0) @binding(0) var stateTex1: texture_2d<f32>;
@group(0) @binding(1) var stateTex2: texture_2d<f32>;
@group(0) @binding(2) var<uniform> density: f32;
@group(0) @binding(3) var<uniform> volumeSize: i32;

struct VertexOutput {
    @builtin(position) position: vec4<f32>,
    @location(0) vColor: vec4<f32>,
}

@vertex
fn main(@builtin(vertex_index) vertexIndex: u32) -> VertexOutput {
    var output: VertexOutput;

    let agentIndex = i32(vertexIndex);
    // Use actual state texture size, not canvas resolution
    let stateTexSize = textureDimensions(stateTex1, 0);
    let texWidth = i32(stateTexSize.x);
    let texHeight = i32(stateTexSize.y);
    let volSize = volumeSize;
    let volSizeF = f32(volSize);

    // Calculate max agents based on density
    let maxDim = max(texWidth, texHeight);
    let maxAgents = i32(f32(maxDim) * density * 0.2);

    // Skip if beyond agent count
    if (agentIndex >= maxAgents) {
        output.position = vec4<f32>(2.0, 2.0, 0.0, 1.0);
        output.vColor = vec4<f32>(0.0);
        return output;
    }

    // Map agent index to state texture coordinate
    let stateTexWidth = texWidth;
    let stateX = agentIndex % stateTexWidth;
    let stateY = agentIndex / stateTexWidth;

    if (stateY >= texHeight) {
        output.position = vec4<f32>(2.0, 2.0, 0.0, 1.0);
        output.vColor = vec4<f32>(0.0);
        return output;
    }

    // Read agent state (3D position in state1.xyz)
    let state1 = textureLoad(stateTex1, vec2<i32>(stateX, stateY), 0);
    let state2 = textureLoad(stateTex2, vec2<i32>(stateX, stateY), 0);

    let x = state1.x;
    let y = state1.y;
    let z = state1.z;

    // Convert 3D position to 2D atlas position
    // Atlas layout: width = volSize, height = volSize * volSize
    let atlasX = x;
    let atlasY = y + floor(z) * volSizeF;

    // Convert to normalized device coordinates
    let atlasWidth = volSizeF;
    let atlasHeight = volSizeF * volSizeF;

    let ndc = vec2<f32>(
        (atlasX / atlasWidth) * 2.0 - 1.0,
        // WebGPU clip y runs opposite to GL's, so negate the GLSL's clip y
        1.0 - (atlasY / atlasHeight) * 2.0
    );

    output.position = vec4<f32>(ndc, 0.0, 1.0);
    output.vColor = vec4<f32>(state2.rgb, 1.0);

    return output;
}

@fragment
fn fragmentMain(input: VertexOutput) -> @location(0) vec4<f32> {
    return input.vColor;
}

/*
 * Flow3D diffuse pass (WGSL) - decay the 3D trail volume
 */

@group(0) @binding(0) var sourceTex: texture_2d<f32>;
@group(0) @binding(1) var<uniform> intensity: f32;

@fragment
fn main(@builtin(position) position: vec4<f32>) -> @location(0) vec4<f32> {
    let coord = vec2<i32>(position.xy);

    // Sample the trail texture directly (no blur)
    let trailColor = textureLoad(sourceTex, coord, 0);

    // Apply intensity decay (persistence)
    // intensity=100 means no decay, intensity=0 means instant fade
    let decay = clamp(intensity / 100.0, 0.0, 1.0);
    return trailColor * decay;
}

