    let colorB = textureSample(tex, samp, st);

    // Centered, aspect-correct coordinates using full image dimensions
    let fullRes = select(resolution, fullResolution, fullResolution.x > 0.0);
    let aspect = fullRes.x / fullRes.y;
    let globalUV = (position.xy + tileOffset) / fullRes;
    var p = (globalUV - vec2<f32>(0.5, 0.5)) * 2.0;
    p.x = p.x * aspect;

    // Apply position offset
    p = p - vec2<f32>(posX * aspect, -posY);

    // Apply rotation
    let rad = rotation * PI / 180.0;
    p = rotate2D(p, rad);

    // Animate radius: pulse in and out
    var r = radius;
    if (speed > 0) {
        r = radius * 0.5 + sin(time * TAU * f32(speed)) * radius * 0.5;
    }

    // Evaluate SDF
    var d: f32 = 0.0;
    if (shape == 0) {
        d = sdfCircle(p, r);
    } else if (shape == 1) {
        d = sdfTriangle(p, r);
    } else if (shape == 2) {
        d = sdfPolygon(p, r, 4.0);
    } else if (shape == 3) {
        d = sdfPolygon(p, r, 5.0);
    } else if (shape == 4) {
        d = sdfPolygon(p, r, 6.0);
    } else if (shape == 5) {
        d = sdfFlower(p, r);
    } else if (shape == 6) {
        d = sdfRing(p, r);
    } else if (shape == 7) {
        d = sdfStar5(p, r);
    }

    // Smoothstep mask: 0 inside, 1 outside
    var mask = smoothstep(-edgeSmooth, edgeSmooth, d);

    // Invert swaps inside/outside
    if (invert == 1) {
        mask = 1.0 - mask;
    }

    // A inside shape, B outside (before invert)
    var color = mix(colorA, colorB, mask);
    color.a = max(colorA.a, colorB.a);

    return color;
}

@group(0) @binding(0) var samp : sampler;
@group(0) @binding(1) var inputTex : texture_2d<f32>;
@group(0) @binding(2) var tex : texture_2d<f32>;
@group(0) @binding(3) var<uniform> position : f32;
@group(0) @binding(4) var<uniform> rotation : f32;
@group(0) @binding(5) var<uniform> softness : f32;
@group(0) @binding(6) var<uniform> invert : i32;
@group(0) @binding(7) var<uniform> speed : f32;
@group(0) @binding(8) var<uniform> time : f32;
@group(0) @binding(9) var<uniform> tileOffset : vec2<f32>;
@group(0) @binding(10) var<uniform> fullResolution : vec2<f32>;

const PI: f32 = 3.14159265359;

@fragment
fn main(@builtin(position) pos: vec4<f32>) -> @location(0) vec4<f32> {
    let dims = vec2<f32>(textureDimensions(inputTex, 0));
    let st = pos.xy / dims;

    let colorA = textureSample(inputTex, samp, st);
    let colorB = textureSample(tex, samp, st);

    let globalUV = (pos.xy + tileOffset) / fullResolution;
    let aspect = fullResolution.x / fullResolution.y;
    var centered = (globalUV - vec2<f32>(0.5, 0.5)) * 2.0;
    centered.x = centered.x * aspect;

    // Rotate the split line
    let rad = rotation * PI / 180.0;
    let c = cos(rad);
    let s = sin(rad);
    let rotated = vec2<f32>(centered.x * c - centered.y * s,
                            centered.x * s + centered.y * c);

    // Compute visible extent of rotated.y for seamless scrolling
    // The projected range depends on aspect ratio and rotation angle
    let extent = aspect * abs(s) + abs(c) + softness;

    // Animate: continuous scroll across full visible range
    // Alternates sweep direction each cycle so the wrap point is seamless
    var animPos = position;
    var flipCycle = false;
    if (speed > 0.0) {
        let cycle = time * speed * 2.0;
        let t = fract(cycle);
        flipCycle = i32(floor(cycle)) % 2 == 1;
        animPos = t * extent * 2.0 - extent;
    }

    // Signed distance from the split line
    let d = rotated.y - animPos;

    // Apply softness
    let halfSoft = max(softness * 0.5, 0.001);
    var mask = smoothstep(-halfSoft, halfSoft, d);

    if ((invert == 1) != flipCycle) {
        mask = 1.0 - mask;
    }

    var color = mix(colorA, colorB, mask);
    color.a = max(colorA.a, colorB.a);

    return color;
}

/*
 * ThresholdMix mixer shader (WGSL)
 * Combines two input textures using threshold masking with optional posterization
 * Supports luminance-based or per-channel RGB thresholding
 */

@group(0) @binding(0) var samp: sampler;
@group(0) @binding(1) var inputTex: texture_2d<f32>;
@group(0) @binding(2) var tex: texture_2d<f32>;
@group(0) @binding(3) var<uniform> mode: i32;
@group(0) @binding(4) var<uniform> quantize: i32;
@group(0) @binding(5) var<uniform> mapSource: i32;
@group(0) @binding(6) var<uniform> threshold: f32;
@group(0) @binding(7) var<uniform> range: f32;
@group(0) @binding(8) var<uniform> thresholdR: f32;
@group(0) @binding(9) var<uniform> rangeR: f32;
@group(0) @binding(10) var<uniform> thresholdG: f32;
@group(0) @binding(11) var<uniform> rangeG: f32;
@group(0) @binding(12) var<uniform> thresholdB: f32;
@group(0) @binding(13) var<uniform> rangeB: f32;

// Convert RGB to luminosity
fn getLuminosity(color: vec3f) -> f32 {
    return dot(color, vec3f(0.299, 0.587, 0.114));
}

// Quantize a value into discrete bands
fn quantizeValue(value: f32, bands: i32) -> f32 {
    if (bands <= 0) {
        return value;
    }
    let numBands = f32(bands);
    return floor(value * numBands) / numBands;
}

// Calculate blend factor with threshold and range
// Returns 0 for values below threshold, 1 for values above threshold+range
// Smooth transition in between
fn calculateBlendFactor(mapValue: f32, thresh: f32, rng: f32) -> f32 {
    if (rng <= 0.0) {
        // Hard threshold
        return step(thresh, mapValue);
    } else {
        // Soft threshold with range
        let lower = thresh;
        let upper = thresh + rng;
        return smoothstep(lower, upper, mapValue);
    }
}

@fragment
fn main(@builtin(position) position: vec4<f32>) -> @location(0) vec4<f32> {
    let dims = vec2f(textureDimensions(inputTex, 0));
    let uv = position.xy / dims;

    let colorA = textureSample(inputTex, samp, uv);
    let colorB = textureSample(tex, samp, uv);

    // Get map color based on mapSource
    var mapColor: vec3f;
    if (mapSource == 0) {
        mapColor = colorA.rgb;
    } else {
        mapColor = colorB.rgb;
    }

    // Apply quantization to map values if enabled
    if (quantize > 0) {
        mapColor.x = quantizeValue(mapColor.x, quantize);
        mapColor.y = quantizeValue(mapColor.y, quantize);
        mapColor.z = quantizeValue(mapColor.z, quantize);
    }

    var result: vec4f;

    if (mode == 0) {
        // Luminance mode - use single threshold for all channels
        let lum = getLuminosity(mapColor);
        let blendFactor = calculateBlendFactor(lum, threshold, range);
        result = mix(colorA, colorB, blendFactor);
    } else {
        // RGB mode - use separate threshold for each channel
        let blendR = calculateBlendFactor(mapColor.x, thresholdR, rangeR);
        let blendG = calculateBlendFactor(mapColor.y, thresholdG, rangeG);
        let blendB = calculateBlendFactor(mapColor.z, thresholdB, rangeB);

        result.x = mix(colorA.x, colorB.x, blendR);
        result.y = mix(colorA.y, colorB.y, blendG);
        result.z = mix(colorA.z, colorB.z, blendB);
        result.w = mix(colorA.w, colorB.w, (blendR + blendG + blendB) / 3.0);
    }

    return result;
}

@group(0) @binding(0) var samp : sampler;
@group(0) @binding(1) var inputTex : texture_2d<f32>;
@group(0) @binding(2) var tex : texture_2d<f32>;
@group(0) @binding(3) var<uniform> mapSource : i32;
@group(0) @binding(4) var<uniform> channel : i32;
@group(0) @binding(5) var<uniform> scale : f32;
@group(0) @binding(6) var<uniform> offset : f32;
@group(0) @binding(7) var<uniform> wrap : i32;
@group(0) @binding(8) var<uniform> resolution : vec2<f32>;
@group(0) @binding(9) var<uniform> tileOffset : vec2<f32>;
@group(0) @binding(10) var<uniform> fullResolution : vec2<f32>;


fn modulo(a: f32, b: f32) -> f32 {
    return a - b * floor(a / b);
}

fn mirrorWrap(t: f32) -> f32 {
    let m = modulo(t, 2.0);
    if (m > 1.0) {
        return 2.0 - m;
    }
    return m;
}

fn applyWrap(uv: vec2<f32>, wrapMode: i32) -> vec2<f32> {
    if (wrapMode == 0) {
        // Clamp
        return clamp(uv, vec2<f32>(0.0, 0.0), vec2<f32>(1.0, 1.0));
    } else if (wrapMode == 1) {
        // Mirror
        return vec2<f32>(mirrorWrap(uv.x), mirrorWrap(uv.y));
    } else {
        // Repeat
        return fract(uv);
    }
}

@fragment
fn main(@builtin(position) pos: vec4<f32>) -> @location(0) vec4<f32> {
    let localUV = pos.xy / resolution;
    let colorA = textureSample(inputTex, samp, localUV);
    let colorB = textureSample(tex, samp, localUV);

    // mapSource 0 reads the map from inputTex and samples tex
    let mapColor = select(colorB, colorA, mapSource == 0);
    let sampleFromB = select(0, 1, mapSource == 0);

    // Extract UV channels
    var rawUV: vec2<f32>;
    if (channel == 0) {
        rawUV = mapColor.rg;
    } else if (channel == 1) {
        rawUV = vec2<f32>(mapColor.r, mapColor.b);
    } else {
        rawUV = vec2<f32>(mapColor.g, mapColor.b);
    }

    // Apply scale (percentage: 100 = identity) and offset
    let s = scale / 100.0;
    var remappedUV = rawUV * s + offset;

    // Apply wrap mode
    remappedUV = applyWrap(remappedUV, wrap);

    var sampleUV = (remappedUV * fullResolution - tileOffset) / resolution;
    sampleUV = fract(sampleUV);

    // Sample the other texture at remapped UVs
    var result: vec4<f32>;
    if (sampleFromB == 1) {
        result = textureSample(tex, samp, sampleUV);
    } else {
        result = textureSample(inputTex, samp, sampleUV);
    }

    return result;
}

// Strange Attractors Agent Shader
// Updates particle positions based on attractor dynamics

struct Uniforms {
    time: f32,
    resolution: vec2<f32>,
    seed: i32,
    attractor: i32,
    speed: f32,
};

@group(0) @binding(0) var<uniform> u: Uniforms;
@group(0) @binding(1) var xyzTex: texture_2d<f32>;
@group(0) @binding(3) var velTex: texture_2d<f32>;
@group(0) @binding(5) var rgbaTex: texture_2d<f32>;

struct Outputs {
    @location(0) outXYZ: vec4<f32>,
    @location(1) outVel: vec4<f32>,
    @location(2) outRGBA: vec4<f32>,
};

// Integer-based hash for cross-platform determinism
fn hash_uint(seed: u32) -> u32 {
    var state = seed * 747796405u + 2891336453u;
    let word = ((state >> ((state >> 28u) + 4u)) ^ state) * 277803737u;
    return (word >> 22u) ^ word;
}

fn hash(seed: u32) -> f32 {
    return f32(hash_uint(seed)) / 4294967295.0;
}

// Lorenz attractor (classic butterfly)
fn lorenz(p: vec3<f32>) -> vec3<f32> {
    let sigma = 10.0;
    let rho = 28.0;
    let beta = 8.0 / 3.0;
    return vec3<f32>(
        sigma * (p.y - p.x),
        p.x * (rho - p.z) - p.y,
        p.x * p.y - beta * p.z
    );
}

// Rössler attractor (spiral)
fn rossler(p: vec3<f32>) -> vec3<f32> {
    let a = 0.2;
    let b = 0.2;
    let c = 5.7;
    return vec3<f32>(
        -p.y - p.z,
        p.x + a * p.y,
        b + p.z * (p.x - c)
    );
}

// Aizawa attractor (torus-like)
fn aizawa(p: vec3<f32>) -> vec3<f32> {
    let a = 0.95;
    let b = 0.7;
    let c = 0.6;
    let d = 3.5;
    let e = 0.25;
    let f = 0.1;
    return vec3<f32>(
        (p.z - b) * p.x - d * p.y,
        d * p.x + (p.z - b) * p.y,
        c + a * p.z - (p.z * p.z * p.z) / 3.0 - (p.x * p.x + p.y * p.y) * (1.0 + e * p.z) + f * p.z * p.x * p.x * p.x
    );
}

// Thomas attractor (cyclically symmetric)
fn thomas(p: vec3<f32>) -> vec3<f32> {
    let b = 0.208186;
    return vec3<f32>(
        sin(p.y) - b * p.x,
        sin(p.z) - b * p.y,
        sin(p.x) - b * p.z
    );
}

// Halvorsen attractor (3-fold symmetric)
fn halvorsen(p: vec3<f32>) -> vec3<f32> {
    let a = 1.89;
    return vec3<f32>(
        -a * p.x - 4.0 * p.y - 4.0 * p.z - p.y * p.y,
        -a * p.y - 4.0 * p.z - 4.0 * p.x - p.z * p.z,
        -a * p.z - 4.0 * p.x - 4.0 * p.y - p.x * p.x
    );
}

// Chen attractor (double scroll)
fn chen(p: vec3<f32>) -> vec3<f32> {
    let a = 40.0;
    let b = 3.0;
    let c = 28.0;
    return vec3<f32>(
        a * (p.y - p.x),
        (c - a) * p.x - p.x * p.z + c * p.y,
        p.x * p.y - b * p.z
    );
}

// Dadras attractor (4-wing)
fn dadras(p: vec3<f32>) -> vec3<f32> {
    let a = 3.0;
    let b = 2.7;
    let c = 1.7;
    let d = 2.0;
    let e = 9.0;
    return vec3<f32>(
        p.y - a * p.x + b * p.y * p.z,
        c * p.y - p.x * p.z + p.z,
        d * p.x * p.y - e * p.z
    );
}

fn stepAttractor(p: vec3<f32>, attractorType: i32, dt: f32) -> vec3<f32> {
    var dp: vec3<f32>;
    if (attractorType == 0) { dp = lorenz(p); }
    else if (attractorType == 1) { dp = rossler(p); }
    else if (attractorType == 2) { dp = aizawa(p); }
    else if (attractorType == 3) { dp = thomas(p); }
    else if (attractorType == 4) { dp = halvorsen(p); }
    else if (attractorType == 5) { dp = chen(p); }
    else { dp = dadras(p); }

    return p + dp * dt;
}

@fragment
fn main(@builtin(position) fragCoord: vec4<f32>) -> Outputs {
    let coord = vec2<i32>(fragCoord.xy);
    let texSize = textureDimensions(xyzTex, 0);
    let stateSize = i32(texSize.x);

    // Read current state
    let pos = textureLoad(xyzTex, coord, 0);
    let vel = textureLoad(velTex, coord, 0);
    let col = textureLoad(rgbaTex, coord, 0);

    let agentSeed = u32(coord.x + coord.y * stateSize) + u32(u.seed);

    // Check if needs 3D initialization
    // pointsEmit initializes agents in 2D normalized coords (0-1 range for x,y, z=0)
    // We detect this by checking if z is exactly 0.0 (never happens in attractor space)
    // and position is in the 0-1 range typical of pointsEmit output
    let needs3DInit = pos.w >= 0.5 && pos.z == 0.0 && pos.x >= 0.0 && pos.x <= 1.0 && pos.y >= 0.0 && pos.y <= 1.0;

    if (needs3DInit) {
        let initSeed = agentSeed + u32(u.time * 1000.0);
        let newX = (hash(initSeed) - 0.5) * 20.0;
        let newY = (hash(initSeed + 1u) - 0.5) * 20.0;
        let newZ = hash(initSeed + 2u) * 30.0 + 10.0;

        return Outputs(
            vec4<f32>(newX, newY, newZ, 1.0),
            vel,
            col
        );
    }

    // Skip dead agents
    if (pos.w < 0.5) {
        return Outputs(pos, vel, col);
    }

    // Step the attractor
    let dt = u.speed * 0.01;
    var newPos = stepAttractor(pos.xyz, u.attractor, dt);

    // Check for divergence (NaN or too far)
    // WGSL: check for NaN by comparing value to itself (NaN != NaN)
    let hasNaN = newPos.x != newPos.x || newPos.y != newPos.y || newPos.z != newPos.z;
    if (hasNaN || length(newPos) > 1000.0) {
        let respawnSeed = agentSeed + u32(u.time * 1000.0);
        newPos = vec3<f32>(
            (hash(respawnSeed) - 0.5) * 20.0,
            (hash(respawnSeed + 1u) - 0.5) * 20.0,
            hash(respawnSeed + 2u) * 30.0 + 10.0
        );
    }

    return Outputs(
        vec4<f32>(newPos, 1.0),
        vel,
        col
    );
}

@group(0) @binding(0) var inputTex: texture_2d<f32>;
@group(0) @binding(1) var texSampler: sampler;

struct VertexOutput {
    @builtin(position) position: vec4f,
    @location(0) uv: vec2f,
}

@fragment
fn main(in: VertexOutput) -> @location(0) vec4f {
    // Copy the input as the GLSL does, at gl_FragCoord / resolution: the
    // output-normalized coordinate with a top-left origin. The default vertex
    // uv has a bottom-left origin, so it is flipped vertically.
    return textureSample(inputTex, texSampler, vec2f(in.uv.x, 1.0 - in.uv.y));
}

// Buddhabrot Agent Shader
// 3 MRT outputs — matches pointsEmit layout

struct Uniforms {
    time: f32,
    resolution: vec2<f32>,
    seed: i32,
    maxIter: i32,
    minIter: i32,
    mode: i32,
    zoom: f32,
    centerX: f32,
    centerY: f32,
};

@group(0) @binding(0) var<uniform> u: Uniforms;
@group(0) @binding(1) var xyzTex: texture_2d<f32>;
@group(0) @binding(3) var velTex: texture_2d<f32>;
@group(0) @binding(5) var rgbaTex: texture_2d<f32>;

struct Outputs {
    @location(0) outXYZ: vec4<f32>,
    @location(1) outVel: vec4<f32>,
    @location(2) outRGBA: vec4<f32>,
};

fn hash_uint(seed: u32) -> u32 {
    var state = seed * 747796405u + 2891336453u;
    let word = ((state >> ((state >> 28u) + 4u)) ^ state) * 277803737u;
    return (word >> 22u) ^ word;
}

fn hash(seed: u32) -> f32 {
    return f32(hash_uint(seed)) / 4294967295.0;
}

fn complexToScreen(z: vec2<f32>) -> vec2<f32> {
    return vec2<f32>(
        (z.y - u.centerY) * u.zoom * u.zoom * 0.2 + 0.5,
        (u.centerX - z.x) * u.zoom * u.zoom * 0.2 + 0.5,
    );
}

fn inMandelbrotInterior(cRe: f32, cIm: f32) -> bool {
    let y2 = cIm * cIm;
    let q = (cRe - 0.25) * (cRe - 0.25) + y2;
    if (q * (q + (cRe - 0.25)) <= 0.25 * y2) { return true; }
    let xp1 = cRe + 1.0;
    return xp1 * xp1 + y2 <= 0.0625;
}

@fragment
fn main(@builtin(position) fragCoord: vec4<f32>) -> Outputs {
    let coord = vec2<i32>(fragCoord.xy);
    let texSize = textureDimensions(xyzTex, 0);
    let stateSize = i32(texSize.x);

    let pos = textureLoad(xyzTex, coord, 0);
    let vel = textureLoad(velTex, coord, 0);
    let col = textureLoad(rgbaTex, coord, 0);

    if (pos.w < 0.5) {
        return Outputs(pos, vel, col);
    }

    let agentSeed = hash_uint(u32(coord.x + coord.y * stateSize))
                  ^ u32(u.time * 65536.0)
                  ^ u32(vel.z * 137.0);

    let needsInit = pos.z < 0.25;

    if (needsInit) {
        let cRe = hash(agentSeed) * 3.5 - 2.5;
        let cIm = hash(agentSeed + 1u) * 3.0 - 1.5;

        if (u.mode == 0 && inMandelbrotInterior(cRe, cIm)) {
            return Outputs(
                vec4<f32>(pos.xy, 0.0, 0.0),
                vel,
                vec4<f32>(0.0, 0.0, 0.0, 0.0),
            );
        }

        var z = vec2<f32>(0.0, 0.0);
        var escapeAt: i32 = 0;
        let iterCap = min(u.maxIter, 2048);

        for (var i: i32 = 0; i < 2048; i = i + 1) {
            if (i >= iterCap) { break; }
            let zr = z.x * z.x - z.y * z.y + cRe;
            let zi = 2.0 * z.x * z.y + cIm;
            z = vec2<f32>(zr, zi);
            if (dot(z, z) > 4.0) {
                escapeAt = i + 1;
                break;
            }
        }

        let escaped = escapeAt > 0;
        var escapeStep: f32 = 0.0;
        var brightness: f32 = 0.0;

        if (u.mode == 0) {
            if (escaped && escapeAt >= u.minIter) {
                escapeStep = f32(escapeAt);
                brightness = 0.03;
            }
        } else {
            if (!escaped) {
                escapeStep = f32(iterCap);
                brightness = 0.03;
            }
        }

        if (brightness == 0.0) {
            return Outputs(
                vec4<f32>(pos.xy, 0.0, 0.0),
                vel,
                vec4<f32>(0.0, 0.0, 0.0, 0.0),
            );
        }

        // Start deposit at z₁ = c
        let screen = complexToScreen(vec2<f32>(cRe, cIm));

        return Outputs(
            vec4<f32>(screen, 0.5, 1.0),
            vec4<f32>(cRe, cIm, 1.0, escapeStep),
            vec4<f32>(brightness, brightness, brightness, 1.0),
        );
    }

    // ---- Active deposit phase ----
    // Recompute z from scratch using c and step count (no texture dependency)

    let cRe = vel.x;
    let cIm = vel.y;
    var step = vel.z;
    let escapeStep = vel.w;

    // Recompute z to current step from z₀ = 0
    var z = vec2<f32>(0.0, 0.0);
    let currentStep = i32(step);
    for (var i: i32 = 0; i < 2048; i = i + 1) {
        if (i >= currentStep) { break; }
        let zr = z.x * z.x - z.y * z.y + cRe;
        let zi = 2.0 * z.x * z.y + cIm;
        z = vec2<f32>(zr, zi);
    }

    // Advance 8 more steps
    for (var s: i32 = 0; s < 8; s = s + 1) {
        step = step + 1.0;

        if (step >= escapeStep) {
            return Outputs(
                vec4<f32>(pos.xy, 0.0, 0.0),
                vec4<f32>(0.0, 0.0, step, 0.0),
                vec4<f32>(0.0, 0.0, 0.0, 0.0),
            );
        }

        let zr = z.x * z.x - z.y * z.y + cRe;
        let zi = 2.0 * z.x * z.y + cIm;
        z = vec2<f32>(zr, zi);
    }

    let screen = complexToScreen(z);

    return Outputs(
        vec4<f32>(screen, 0.5, 1.0),
        vec4<f32>(cRe, cIm, step, escapeStep),
        col,
    );
}

@group(0) @binding(0) var inputTex: texture_2d<f32>;
@group(0) @binding(1) var texSampler: sampler;

struct VertexOutput {
    @builtin(position) position: vec4f,
    @location(0) uv: vec2f,
}

@fragment
fn main(in: VertexOutput) -> @location(0) vec4f {
    // Copy the input as the GLSL does, at gl_FragCoord / resolution: the
    // output-normalized coordinate with a top-left origin. The default vertex
    // uv has a bottom-left origin, so it is flipped vertically.
    return textureSample(inputTex, texSampler, vec2f(in.uv.x, 1.0 - in.uv.y));
}

// Buddhabrot z-state writer
// Recomputes z from scratch to current step for storage

@group(0) @binding(1) var xyzTex: texture_2d<f32>;
@group(0) @binding(3) var velTex: texture_2d<f32>;

@fragment
fn main(@builtin(position) fragCoord: vec4<f32>) -> @location(0) vec4<f32> {
    let coord = vec2<i32>(fragCoord.xy);
    let pos = textureLoad(xyzTex, coord, 0);
    let vel = textureLoad(velTex, coord, 0);

    // Dead agent
    if (pos.w < 0.5) {
        return vec4<f32>(0.0, 0.0, 0.0, 0.0);
    }

    let cRe = vel.x;
    let cIm = vel.y;
    let stepI = i32(vel.z);

    // Recompute z from scratch to current step
    var z = vec2<f32>(0.0, 0.0);

    for (var i: i32 = 0; i < 2048; i = i + 1) {
        if (i >= stepI) { break; }
        let zr = z.x * z.x - z.y * z.y + cRe;
        let zi = 2.0 * z.x * z.y + cIm;
        z = vec2<f32>(zr, zi);
    }

    return vec4<f32>(z.x, z.y, 0.0, 0.0);
}

// DLA - Agent Walk Pass (Common Agent Architecture)
// Reads agent state from pointsEmit, performs random walk, detects sticking

struct Uniforms {
    stride: f32,
    inputWeight: f32,
    attrition: f32,
    stateSize: i32,
}

struct VertexOutput {
    @builtin(position) position: vec4<f32>,
    @location(0) uv: vec2<f32>,
}

struct FragmentOutputs {
    @location(0) outXYZ: vec4<f32>,
    @location(1) outVel: vec4<f32>,
    @location(2) outRGBA: vec4<f32>,
}

@group(0) @binding(0) var<uniform> u: Uniforms;
@group(0) @binding(1) var xyzTex: texture_2d<f32>;
@group(0) @binding(2) var velTex: texture_2d<f32>;
@group(0) @binding(3) var rgbaTex: texture_2d<f32>;
@group(0) @binding(4) var gridTex: texture_2d<f32>;
@group(0) @binding(5) var inputTex: texture_2d<f32>;

// Integer-based hash for deterministic randomness
fn hash_uint(seed: u32) -> u32 {
    var state = seed * 747796405u + 2891336453u;
    let word = ((state >> ((state >> 28u) + 4u)) ^ state) * 277803737u;
    return (word >> 22u) ^ word;
}

fn hash(seed: u32) -> f32 {
    return f32(hash_uint(seed)) / 4294967295.0;
}

// PCG-style random using float seed (stored as bits)
fn rand(seed: ptr<function, f32>) -> f32 {
    var bits = bitcast<u32>(*seed);
    bits = hash_uint(bits);
    *seed = bitcast<f32>((bits & 0x007FFFFFu) | 0x3F800000u) - 1.0;
    bits = hash_uint(bits + 1u);
    *seed = bitcast<f32>((bits & 0x007FFFFFu) | 0x3F800000u) - 1.0;
    return *seed;
}

fn randomDirection(seed: ptr<function, f32>) -> vec2<f32> {
    let theta = rand(seed) * 6.28318530718;
    return vec2<f32>(cos(theta), sin(theta));
}

fn wrap01(v: vec2<f32>) -> vec2<f32> {
    return fract(max(v, vec2<f32>(0.0)));
}

fn sampleGrid(uv: vec2<f32>) -> f32 {
    let dims = vec2<f32>(textureDimensions(gridTex));
    let coord = vec2<i32>(wrap01(uv) * dims);
    return textureLoad(gridTex, coord, 0).a;
}

fn neighborhood(uv: vec2<f32>, radius: f32) -> f32 {
    let dims = vec2<f32>(textureDimensions(gridTex));
    let texel = radius / dims;
    var accum = 0.0;
    accum += sampleGrid(uv);
    accum += sampleGrid(uv + vec2<f32>(texel.x, 0.0));
    accum += sampleGrid(uv - vec2<f32>(texel.x, 0.0));
    accum += sampleGrid(uv + vec2<f32>(0.0, texel.y));
    accum += sampleGrid(uv - vec2<f32>(0.0, texel.y));
    return accum * 0.2;
}

@fragment
fn main(in: VertexOutput) -> FragmentOutputs {
    let coord = vec2<i32>(in.position.xy);
    let stateDims = textureDimensions(xyzTex);

    // Read input state from pipeline (from pointsEmit)
    let xyz = textureLoad(xyzTex, coord, 0);
    let vel = textureLoad(velTex, coord, 0);
    let rgba = textureLoad(rgbaTex, coord, 0);

    // Extract state
    var pos = xyz.xy;
    let alive = xyz.w;

    // vel.x = seed, vel.y = justStuck flag, vel.w = agentRand from emitter
    var seed = vel.x;
    let agentRand = vel.w;

    // Initialize or evolve seed using per-particle deterministic chain (matches GLSL)
    let agentId = u32(coord.x + coord.y * i32(stateDims.x));
    if (seed <= 0.0) {
        seed = hash(agentId) + 0.001;
    }
    let frameSeed = hash_uint(agentId * 31u + bitcast<u32>(seed));
    seed = bitcast<f32>((frameSeed & 0x007FFFFFu) | 0x3F800000u) - 1.0;

    // If not alive, pass through (waiting for respawn from pointsEmit)
    if (alive < 0.5) {
        return FragmentOutputs(
            xyz,
            vec4<f32>(seed, 0.0, 0.0, agentRand),
            rgba
        );
    }

    // Grid dimensions for step size
    let gridDims = vec2<f32>(textureDimensions(gridTex));
    let texel = 1.0 / max(gridDims.x, gridDims.y);

    // Check proximity to existing structure
    let local = neighborhood(pos, 2.0);
    let proximity = smoothstep(0.015, 0.12, local);

    // Random direction for walk
    let randomDir = randomDirection(&seed);

    // Input-weighted direction
    let inputW = u.inputWeight / 100.0;
    var stepDir = randomDir;
    if (inputW > 0.0) {
        let inputDims = textureDimensions(inputTex);
        let inputCoord = vec2<i32>(wrap01(pos) * vec2<f32>(inputDims));
        let inputVal = textureLoad(inputTex, inputCoord, 0);
        var inputDir = inputVal.xy * 2.0 - 1.0;
        if (length(inputDir) > 0.01) {
            inputDir = normalize(inputDir);
            stepDir = normalize(mix(randomDir, inputDir, inputW));
        }
    }

    // Step size: slow down near structure for finer aggregation
    let stepSize = (u.stride / 10.0) * texel * mix(3.0, 0.5, proximity);

    // Add wander jitter
    stepDir += randomDirection(&seed) * 0.3;
    stepDir = normalize(stepDir);

    // Move agent
    let candidate = wrap01(pos + stepDir * stepSize);

    // Check for sticking - require direct adjacency (radius 1.0)
    let here = sampleGrid(candidate);
    let nearby = neighborhood(candidate, 1.0);

    // Stick if adjacent to structure but local spot is empty
    let stuck = (nearby > 0.3 && here < 0.5);

    // Attrition: random respawn (0-10 scale → 0-0.1)
    var needsRespawn = false;
    if (u.attrition > 0.0) {
        let attritionRate = u.attrition * 0.01;
        if (rand(&seed) < attritionRate) {
            needsRespawn = true;
        }
    }

    if (stuck) {
        // Agent stuck: mark as dead for respawn, flag justStuck for deposit
        return FragmentOutputs(
            vec4<f32>(candidate, 0.0, 0.0),  // w=0 signals death to pointsEmit
            vec4<f32>(seed, 1.0, 0.0, agentRand),  // y=1 signals "just stuck" for depositGrid
            rgba
        );
    } else if (needsRespawn) {
        // Attrition death: mark for respawn
        return FragmentOutputs(
            vec4<f32>(candidate, 0.0, 0.0),  // w=0 signals death
            vec4<f32>(seed, 0.0, 0.0, agentRand),  // y=0, not stuck
            rgba
        );
    } else {
        // Continue walking
        return FragmentOutputs(
            vec4<f32>(candidate, 0.0, 1.0),  // w=1 alive
            vec4<f32>(seed, 0.0, 0.0, agentRand),
            rgba
        );
    }
}

// Copy Pass - Blit grid to write buffer for proper blending

@group(0) @binding(0) var uSampler: sampler;
@group(0) @binding(1) var gridTex: texture_2d<f32>;
@group(0) @binding(2) var<uniform> resolution: vec2<f32>;

@fragment
fn main(@builtin(position) position: vec4<f32>) -> @location(0) vec4<f32> {
    let uv = position.xy / resolution;
    return textureSample(gridTex, uSampler, uv);
}

// DLA - Deposit stuck agents to anchor grid (WGSL)
// Only deposits agents that just stuck (vel.y == 1.0)

struct VertexOutput {
    @builtin(position) position: vec4<f32>,
    @location(0) weight: f32,
    @location(1) color: vec3<f32>,
}

@group(0) @binding(0) var xyzTex: texture_2d<f32>;
@group(0) @binding(1) var velTex: texture_2d<f32>;
@group(0) @binding(2) var rgbaTex: texture_2d<f32>;
@group(0) @binding(3) var<uniform> deposit: f32;

fn decodeIndex(index: i32, dims: vec2<i32>) -> vec2<i32> {
    let x = index % dims.x;
    let y = index / dims.x;
    return vec2<i32>(x, y);
}

@vertex
fn vs_main(@builtin(vertex_index) vertexIndex: u32) -> VertexOutput {
    var output: VertexOutput;

    let dims = vec2<i32>(textureDimensions(xyzTex));
    let totalAgents = dims.x * dims.y;

    // Skip if vertex index exceeds agent count
    if (i32(vertexIndex) >= totalAgents) {
        output.position = vec4<f32>(-2.0, -2.0, 0.0, 1.0);
        output.weight = 0.0;
        output.color = vec3<f32>(0.0);
        return output;
    }

    let coord = decodeIndex(i32(vertexIndex), dims);

    let xyz = textureLoad(xyzTex, coord, 0);
    let vel = textureLoad(velTex, coord, 0);
    let rgba = textureLoad(rgbaTex, coord, 0);

    // vel.y == 1.0 means this agent just stuck
    let justStuck = vel.y;

    output.weight = justStuck;
    output.color = rgba.rgb;

    // Only render if just stuck
    if (justStuck < 0.5) {
        output.position = vec4<f32>(-2.0, -2.0, 0.0, 1.0);
        return output;
    }

    // Position from xyz (normalized [0,1])
    // WebGPU clip y runs opposite to GL's, so negate the GLSL's clip y
    let clip = vec2<f32>(xyz.x * 2.0 - 1.0, 1.0 - xyz.y * 2.0);
    output.position = vec4<f32>(clip, 0.0, 1.0);

    return output;
}

@fragment
fn fs_main(in: VertexOutput) -> @location(0) vec4<f32> {
    // Discard if not a stuck agent
    if (in.weight < 0.5) {
        discard;
    }

    // Deposit energy with agent color
    // deposit range [0.5, 20] maps to energy [0.05, 2.0]
    let energy = deposit * 0.1;
    return vec4<f32>(in.color * energy, energy);
}

// DLA - Initialize and decay anchor grid

struct Uniforms {
    resolution: vec2<f32>,
    decay: f32,
    anchorDensity: f32,
    resetState: i32,
}

struct VertexOutput {
    @builtin(position) position: vec4<f32>,
    @location(0) uv: vec2<f32>,
}

@group(0) @binding(0) var gridTex: texture_2d<f32>;
@group(0) @binding(1) var<uniform> u: Uniforms;

fn hash21(p: vec2<f32>) -> f32 {
    var p3 = fract(vec3<f32>(p.x, p.y, p.x) * 0.1031);
    p3 += dot(p3, vec3<f32>(p3.z, p3.y, p3.x) + 31.32);
    return fract((p3.x + p3.y) * p3.z);
}

@fragment
fn main(in: VertexOutput) -> @location(0) vec4<f32> {
    // If resetState is true, clear the grid
    if (u.resetState != 0) {
        return vec4<f32>(0.0);
    }

    let coord = vec2<i32>(in.position.xy);
    let uv = in.position.xy / u.resolution;

    // Sample previous grid value
    let prevSample = textureLoad(gridTex, coord, 0);
    let prev = prevSample.a;
    let prevColor = prevSample.rgb;

    // Apply decay (0 = full persistence, higher = faster fade)
    // decay range [0, 0.5] maps to persistence [1.0, 0.5]
    let persistence = 1.0 - u.decay;
    var energy = prev * persistence;
    var color = prevColor * persistence;

    // Cap energy to prevent runaway accumulation
    energy = min(energy, 3.0);

    // Seed initial structure - always try, but only where grid is empty
    let rng = hash21(in.position.xy);

    // Radial falloff from center - larger area for seeding
    let radial = smoothstep(0.25, 0.0, length(uv - 0.5));

    // Seed density controls threshold (higher = more seeds)
    // anchorDensity=1.0 → threshold=0.9 → 10% of radial pixels
    let seedThreshold = 1.0 - u.anchorDensity * 0.1;
    let seedWeight = step(seedThreshold, rng) * radial;

    // Only seed where there's no existing structure
    if (seedWeight > 0.0 && prev < 0.1) {
        let strength = mix(0.5, 1.0, rng);
        energy = max(energy, strength);
        color = vec3<f32>(strength);
    }

    return vec4<f32>(color, energy);
}

struct Uniforms {
    resolution: vec2f,
    matteOpacity: f32,
}

@group(0) @binding(0) var<uniform> u: Uniforms;
@group(0) @binding(1) var inputTex: texture_2d<f32>;
@group(0) @binding(2) var inputTexSampler: sampler;
@group(0) @binding(3) var gridTex: texture_2d<f32>;
@group(0) @binding(4) var gridTexSampler: sampler;

@fragment
fn main(@builtin(position) fragCoord: vec4f) -> @location(0) vec4f {
    let uv = fragCoord.xy / u.resolution;
    let input = textureSample(inputTex, inputTexSampler, uv);
    let grid = textureSample(gridTex, gridTexSampler, uv);

    // Blend grid structure over input
    // Grid alpha indicates structure presence
    let gridStrength = clamp(grid.a, 0.0, 1.0);
    let gridColor = grid.rgb;
    let matteAlpha = u.matteOpacity;

    // Mix: where grid exists, show grid color; otherwise show input (premultiplied by matte)
    let color = mix(input.rgb * matteAlpha, gridColor, gridStrength);

    // Alpha: where grid exists, full opacity; elsewhere, matte opacity
    let alpha = max(gridStrength, matteAlpha);

    return vec4f(color, alpha);
}

// Flock agent pass - Common Agent Architecture middleware
// Reads from global_xyz/vel/rgba, applies boids flocking, writes back
// State format: xyz=[x, y, z, alive] vel=[vx, vy, age, seed] rgba=[r, g, b, a]
// Positions in normalized coords [0,1]

struct Uniforms {
    resolution: vec2f,
    time: f32,
    separation: f32,
    alignment: f32,
    cohesion: f32,
    perceptionRadius: f32,
    separationRadius: f32,
    maxSpeed: f32,
    maxForce: f32,
    boundaryMode: i32,
    wallMargin: f32,
    noiseWeight: f32,
}

struct Outputs {
    @location(0) xyz: vec4f,
    @location(1) vel: vec4f,
    @location(2) rgba: vec4f,
}

@group(0) @binding(0) var<uniform> u: Uniforms;
@group(0) @binding(3) var xyzTex: texture_2d<f32>;
@group(0) @binding(4) var velTex: texture_2d<f32>;
@group(0) @binding(5) var rgbaTex: texture_2d<f32>;

// === ORIGINAL BOIDS HELPER FUNCTIONS (PRESERVED EXACTLY) ===

fn hash_uint(seed: u32) -> u32 {
    var state = seed * 747796405u + 2891336453u;
    let word = ((state >> ((state >> 28u) + 4u)) ^ state) * 277803737u;
    return (word >> 22u) ^ word;
}

fn hash(seed: u32) -> f32 {
    return f32(hash_uint(seed)) / 4294967295.0;
}

fn hash2(seed: u32) -> vec2f {
    return vec2f(hash(seed), hash(seed + 1u));
}

fn hashFloat(n: f32) -> f32 {
    return hash(bitcast<u32>(n));
}

fn noise2D(p: vec2f) -> f32 {
    let i = floor(p);
    let f = fract(p);
    let ff = f * f * (3.0 - 2.0 * f);
    let n = i.x + i.y * 57.0;
    return mix(
        mix(hashFloat(n), hashFloat(n + 1.0), ff.x),
        mix(hashFloat(n + 57.0), hashFloat(n + 58.0), ff.x),
        ff.y
    ) * 2.0 - 1.0;
}

fn wrapPosition(position: vec2f, bounds: vec2f) -> vec2f {
    return (position + bounds) - bounds * floor((position + bounds) / bounds);
}

fn limitVec(v: vec2f, maxLen: f32) -> vec2f {
    let len = length(v);
    if (len > maxLen && len > 0.0) {
        return v * (maxLen / len);
    }
    return v;
}

fn setMag(v: vec2f, mag: f32) -> vec2f {
    let len = length(v);
    if (len > 0.0) {
        return v * (mag / len);
    }
    return v;
}

const GRID_SIZE: i32 = 16;

fn getGridCell(pos: vec2f, res: vec2f) -> vec2i {
    let cellSize = res / f32(GRID_SIZE);
    return vec2i(clamp(pos / cellSize, vec2f(0.0), vec2f(f32(GRID_SIZE - 1))));
}

// === END ORIGINAL HELPER FUNCTIONS ===

@fragment
fn main(@builtin(position) fragCoord: vec4f) -> Outputs {
    let coord = vec2i(fragCoord.xy);
    let stateSize = textureDimensions(xyzTex, 0);

    // Read input state from pipeline
    let xyz = textureLoad(xyzTex, coord, 0);
    let vel = textureLoad(velTex, coord, 0);
    let rgba = textureLoad(rgbaTex, coord, 0);

    // Extract components
    let px = xyz.x;  // normalized x
    let py = xyz.y;  // normalized y
    let alive = xyz.w;

    // vel stores: [vx, vy, age, seed]
    var vx = vel.x;
    var vy = vel.y;
    var age = vel.z;
    var seed = vel.w;

    let boidId = u32(coord.x) + u32(coord.y) * u32(stateSize.x);

    // Convert normalized to pixel coords for the algorithm
    var pos = vec2f(px, py) * u.resolution;
    var velocity = vec2f(vx, vy);

    // If not alive, pass through unchanged
    if (alive < 0.5) {
        return Outputs(xyz, vel, rgba);
    }

    // Initialize velocity on first use (if zero from pointsEmit)
    if (length(velocity) == 0.0 && seed == 0.0) {
        seed = hash(boidId + 99999u);
        let angle = hash(boidId + 12345u) * 6.28318530718;
        let speed = hash(boidId + 23456u) * u.maxSpeed * 0.5 + u.maxSpeed * 0.25;
        velocity = vec2f(cos(angle), sin(angle)) * speed;
    }

    // Attrition is now handled by pointsEmit

    // === ORIGINAL BOIDS ALGORITHM (PRESERVED EXACTLY) ===

    var separationForce = vec2f(0.0);
    var alignmentSum = vec2f(0.0);
    var cohesionSum = vec2f(0.0);
    var separationCount = 0;
    var alignmentCount = 0;
    var cohesionCount = 0;

    let myCell = getGridCell(pos, u.resolution);
    let perceptionSq = u.perceptionRadius * u.perceptionRadius;
    let separationSq = u.separationRadius * u.separationRadius;

    let totalBoids = i32(stateSize.x * stateSize.y);

    // Sample neighbors
    for (var dy = -1; dy <= 1; dy++) {
        for (var dx = -1; dx <= 1; dx++) {
            var checkCell = myCell + vec2i(dx, dy);

            if (u.boundaryMode == 0) {
                checkCell = (checkCell + GRID_SIZE) % GRID_SIZE;
            } else {
                checkCell = clamp(checkCell, vec2i(0), vec2i(GRID_SIZE - 1));
            }

            let cellSeed = u32(checkCell.y * GRID_SIZE + checkCell.x);

            for (var s = 0; s < 8; s++) {
                let sampleSeed = cellSeed * 31u + u32(s) + u32(u.time * 10.0);
                let sampleIdx = i32(hash_uint(sampleSeed) % u32(totalBoids));

                let sx = sampleIdx % i32(stateSize.x);
                let sy = sampleIdx / i32(stateSize.x);

                // Skip self
                if (sx == coord.x && sy == coord.y) {
                    continue;
                }

                let otherXyz = textureLoad(xyzTex, vec2i(sx, sy), 0);
                let otherVel = textureLoad(velTex, vec2i(sx, sy), 0);

                // Skip dead agents
                if (otherXyz.w < 0.5) {
                    continue;
                }

                let otherPos = otherXyz.xy * u.resolution;
                let otherVelocity = otherVel.xy;

                // Calculate distance (with wrapping if needed)
                var diff = otherPos - pos;
                if (u.boundaryMode == 0) {
                    if (diff.x > u.resolution.x * 0.5) { diff.x -= u.resolution.x; }
                    if (diff.x < -u.resolution.x * 0.5) { diff.x += u.resolution.x; }
                    if (diff.y > u.resolution.y * 0.5) { diff.y -= u.resolution.y; }
                    if (diff.y < -u.resolution.y * 0.5) { diff.y += u.resolution.y; }
                }

                let distSq = dot(diff, diff);

                // Separation (close neighbors)
                if (distSq < separationSq && distSq > 0.0) {
                    let away = -diff;
                    let dist = sqrt(distSq);
                    separationForce += away / dist;
                    separationCount++;
                }

                // Alignment and Cohesion (perception radius)
                if (distSq < perceptionSq && distSq > 0.0) {
                    alignmentSum += otherVelocity;
                    alignmentCount++;
                    cohesionSum += otherPos;
                    cohesionCount++;
                }
            }
        }
    }

    // Calculate steering forces
    var steer = vec2f(0.0);

    // Separation
    if (separationCount > 0) {
        var sepForce = separationForce / f32(separationCount);
        if (length(sepForce) > 0.0) {
            sepForce = setMag(sepForce, u.maxSpeed);
            sepForce = sepForce - velocity;
            sepForce = limitVec(sepForce, u.maxForce);
            steer += sepForce * u.separation;
        }
    }

    // Alignment
    if (alignmentCount > 0) {
        var avgVel = alignmentSum / f32(alignmentCount);
        if (length(avgVel) > 0.0) {
            avgVel = setMag(avgVel, u.maxSpeed);
            var alignSteer = avgVel - velocity;
            alignSteer = limitVec(alignSteer, u.maxForce);
            steer += alignSteer * u.alignment;
        }
    }

    // Cohesion
    if (cohesionCount > 0) {
        let avgPos = cohesionSum / f32(cohesionCount);
        var desired = avgPos - pos;
        if (length(desired) > 0.0) {
            desired = setMag(desired, u.maxSpeed);
            var cohesionSteer = desired - velocity;
            cohesionSteer = limitVec(cohesionSteer, u.maxForce);
            steer += cohesionSteer * u.cohesion;
        }
    }

    // Noise/turbulence
    if (u.noiseWeight > 0.0) {
        let noiseScale = 0.01;
        let nx = noise2D(pos * noiseScale + u.time * 0.5);
        let ny = noise2D(pos * noiseScale + vec2f(100.0, 100.0) + u.time * 0.5);
        let noiseForce = vec2f(nx, ny) * u.maxForce * u.noiseWeight;
        steer += noiseForce;
    }

    // Boundary handling
    if (u.boundaryMode == 1) {
        var wallForce = vec2f(0.0);
        let turnStrength = u.maxForce * 2.0;

        if (pos.x < u.wallMargin) {
            wallForce.x = turnStrength * (1.0 - pos.x / u.wallMargin);
        } else if (pos.x > u.resolution.x - u.wallMargin) {
            wallForce.x = -turnStrength * (1.0 - (u.resolution.x - pos.x) / u.wallMargin);
        }

        if (pos.y < u.wallMargin) {
            wallForce.y = turnStrength * (1.0 - pos.y / u.wallMargin);
        } else if (pos.y > u.resolution.y - u.wallMargin) {
            wallForce.y = -turnStrength * (1.0 - (u.resolution.y - pos.y) / u.wallMargin);
        }

        steer += wallForce;
    }

    // Apply steering and update velocity
    velocity += steer;
    velocity = limitVec(velocity, u.maxSpeed);

    // Update position
    pos += velocity;

    // Boundary wrap
    if (u.boundaryMode == 0) {
        pos = wrapPosition(pos, u.resolution);
    } else {
        pos = clamp(pos, vec2f(1.0), u.resolution - vec2f(1.0));
    }

    // Update age
    age += 0.016;

    // === END ORIGINAL ALGORITHM ===

    // Convert back to normalized coords
    let newPx = pos.x / u.resolution.x;
    let newPy = pos.y / u.resolution.y;

    return Outputs(
        vec4f(newPx, newPy, xyz.z, 1.0),
        vec4f(velocity, age, seed),
        rgba
    );
