// Much faster than O(n²) as field is already computed
// Binding order: loaded textures (0-2), sampled texture pair (3-4), uniforms (5)

struct Uniforms {
    resolution: vec2f,
    muG: f32,
    sigmaG: f32,
    repulsion: f32,
    dt: f32,
}

