const EPSILON: f32 = 0.0001;
const PI: f32 = 3.14159265359;

// Gaussian shell kernel K(r) = exp(-((r - μ) / σ)²)
fn kernel(r: f32, mu: f32, sigma: f32) -> f32 {
    let x = (r - mu) / sigma;
    return exp(-x * x);
}

@fragment
fn main(@builtin(position) fragCoord: vec4f) -> @location(0) vec4f {
    // Use the actual density texture size, not output resolution
    let densityDims = textureDimensions(densityTex, 0);
    let densitySize = vec2f(f32(densityDims.x), f32(densityDims.y));
    let uv = fragCoord.xy / densitySize;
    let texelSize = 1.0 / densitySize;

    // Compute kernel weight for normalization
    var wK: f32 = 0.0;
    let numSamples: i32 = 64;
    let dr = uniforms.searchRadius / f32(numSamples);
    for (var i: i32 = 0; i < numSamples; i++) {
        let r = (f32(i) + 0.5) * dr;
        wK += kernel(r, uniforms.muK, uniforms.sigmaK) * r * dr;
    }
    wK = 1.0 / max(wK * 2.0 * PI, EPSILON);

    // Accumulate kernel-weighted density from neighbors
    var U: f32 = 0.0;
    let iRadius = i32(ceil(uniforms.searchRadius));

    for (var dy: i32 = -iRadius; dy <= iRadius; dy++) {
        for (var dx: i32 = -iRadius; dx <= iRadius; dx++) {
            let r = length(vec2f(f32(dx), f32(dy)));

            // Skip if outside search radius
            if (r > uniforms.searchRadius) {
                continue;
            }

            // Sample density at neighbor (wrap around edges)
            let sampleUV = fract(uv + vec2f(f32(dx), f32(dy)) * texelSize);
            let density = textureSampleLevel(densityTex, densitySampler, sampleUV, 0.0).r;

            // Apply kernel weight
            let kVal = kernel(r, uniforms.muK, uniforms.sigmaK) * wK;
            U += density * kVal;
        }
    }

    return vec4f(U, 0.0, 0.0, 1.0);
}

// Deposit Shader - Scatter particle deposits to density texture

struct Uniforms {
    resolution: vec2<f32>,
    depositAmount: f32,
}

struct VertexOutput {
    @builtin(position) position: vec4<f32>,
    @location(0) amount: f32,
}

@group(0) @binding(0) var<uniform> u: Uniforms;
@group(0) @binding(1) var xyzTex: texture_2d<f32>;

@vertex
fn vertexMain(@builtin(vertex_index) vertexIndex: u32) -> VertexOutput {
    var out: VertexOutput;

    // Get state size from xyz texture dimensions
    let texSize = textureDimensions(xyzTex, 0);
    let stateSize = i32(texSize.x);
    let totalAgents = stateSize * stateSize;

    // Cull vertices beyond texture size
    if (i32(vertexIndex) >= totalAgents) {
        out.position = vec4<f32>(2.0, 2.0, 0.0, 1.0);
        out.amount = 0.0;
        return out;
    }

    // Calculate UV for this agent
    let x = i32(vertexIndex) % stateSize;
    let y = i32(vertexIndex) / stateSize;

    // Read agent position
    let pos = textureLoad(xyzTex, vec2<i32>(x, y), 0);

    // Check if agent is alive
    if (pos.w < 0.5) {
        out.position = vec4<f32>(2.0, 2.0, 0.0, 1.0);
        out.amount = 0.0;
        return out;
    }

    // Convert position (0..1) to clip space (-1..1), matching WebGL point projection.
    let clipPos = vec2<f32>(pos.x * 2.0 - 1.0, 1.0 - pos.y * 2.0);

    out.position = vec4<f32>(clipPos, 0.0, 1.0);
    out.amount = u.depositAmount;
    return out;
}

@fragment
fn fragmentMain(in: VertexOutput) -> @location(0) vec4<f32> {
    // Each particle deposits a constant value
    return vec4<f32>(in.amount, 0.0, 0.0, 1.0);
}

// Passthrough shader - copy input to output for 2D chain continuity
// Standard binding order: sampler(0), texture(1) - no uniforms needed

@group(0) @binding(0) var inputSampler: sampler;
@group(0) @binding(1) var inputTex: texture_2d<f32>;

@fragment
fn main(@builtin(position) position: vec4f) -> @location(0) vec4f {
    let dims = textureDimensions(inputTex, 0);
    let uv = position.xy / vec2f(f32(dims.x), f32(dims.y));
    return textureSampleLevel(inputTex, inputSampler, vec2f(uv.x, 1.0 - uv.y), 0.0);
}

// Particle Life agent pass - Common Agent Architecture middleware
// Combined force evaluation + integration in single pass
// Reads from global_xyz/vel/rgba + internal data, writes back all 4
// Positions in normalized coords [0,1]

struct Uniforms {
    resolution: vec2f,
    time: f32,
    typeCount: i32,
    attractionScale: f32,
    repulsionScale: f32,
    minRadius: f32,
    maxRadius: f32,
    maxSpeed: f32,
    friction: f32,
    boundaryMode: i32,
    matrixSeed: f32,
    symmetricForces: i32,
    useTypeColor: i32,
}

struct Outputs {
    @location(0) xyz: vec4f,
    @location(1) vel: vec4f,
    @location(2) rgba: vec4f,
    @location(3) data: vec4f,
}

@group(0) @binding(0) var<uniform> u: Uniforms;
@group(0) @binding(3) var xyzTex: texture_2d<f32>;
@group(0) @binding(4) var velTex: texture_2d<f32>;
@group(0) @binding(5) var rgbaTex: texture_2d<f32>;
@group(0) @binding(6) var dataTex: texture_2d<f32>;
@group(0) @binding(7) var forceMatrix: texture_2d<f32>;
@group(0) @binding(8) var inputTex: texture_2d<f32>;
@group(0) @binding(9) var inputSampler: sampler;

// === HASH FUNCTIONS ===

fn hash_uint(seed: u32) -> u32 {
    var state = seed * 747796405u + 2891336453u;
    let word = ((state >> ((state >> 28u) + 4u)) ^ state) * 277803737u;
    return (word >> 22u) ^ word;
}

fn hash(seed: u32) -> f32 {
    return f32(hash_uint(seed)) / 4294967295.0;
}

fn hash2(seed: u32) -> vec2f {
    return vec2f(hash(seed), hash(seed + 1u));
}

// Type colors (rainbow palette)
fn typeColor(typeId: i32, totalTypes: i32) -> vec3f {
    let hue = f32(typeId) / f32(totalTypes);
    let h = hue * 6.0;
    let c = 1.0;
    let x = c * (1.0 - abs(h % 2.0 - 1.0));
    var rgb: vec3f;
    if (h < 1.0) { rgb = vec3f(c, x, 0.0); }
    else if (h < 2.0) { rgb = vec3f(x, c, 0.0); }
    else if (h < 3.0) { rgb = vec3f(0.0, c, x); }
    else if (h < 4.0) { rgb = vec3f(0.0, x, c); }
    else if (h < 5.0) { rgb = vec3f(x, 0.0, c); }
    else { rgb = vec3f(c, 0.0, x); }
    return rgb;
}

// === SPATIAL GRID ===

const GRID_SIZE: i32 = 16;

fn getGridCell(pos: vec2f) -> vec2i {
    let cellSize = vec2f(1.0) / f32(GRID_SIZE);
    return vec2i(clamp(pos / cellSize, vec2f(0.0), vec2f(f32(GRID_SIZE - 1))));
}

// === FORCE FUNCTIONS ===

fn radialForce(dist: f32, strength: f32, prefDist: f32, curveShape: f32) -> f32 {
    let normDist = (dist - u.minRadius) / (u.maxRadius - u.minRadius);

    // Scale forces to velocity space: force magnitude should be proportional to maxSpeed
    // A full-strength force should produce significant but not instant max velocity
    let forceScale = u.maxSpeed * 10.0;

    if (normDist < 0.0) {
        // Inside minRadius: hard repulsion
        return -u.repulsionScale * (1.0 - dist / u.minRadius) * forceScale;
    }

    if (normDist > 1.0) {
        // Outside maxRadius: no force
        return 0.0;
    }

    // In the interaction band: apply force curve
    var force: f32;
    if (normDist < prefDist) {
        force = strength * (normDist / prefDist);
    } else {
        force = strength * (1.0 - (normDist - prefDist) / (1.0 - prefDist));
    }

    // Apply curve shape
    let shaped = sign(force) * pow(abs(force), 1.0 - curveShape * 0.5);

    // Scale by attraction/repulsion multipliers and forceScale
    if (shaped > 0.0) {
        return shaped * u.attractionScale * forceScale;
    } else {
        return shaped * u.repulsionScale * forceScale;
    }
}

// === VECTOR HELPERS ===

fn wrapPosition(pos: vec2f) -> vec2f {
    return (pos + 1.0) - 1.0 * floor((pos + 1.0) / 1.0);
}

fn limitVec(v: vec2f, maxLen: f32) -> vec2f {
    let len = length(v);
    if (len > maxLen && len > 0.0) {
        return v * (maxLen / len);
    }
    return v;
}

@fragment
fn main(@builtin(position) position: vec4f) -> Outputs {
    let coord = vec2i(position.xy);
    let stateSize = vec2i(textureDimensions(xyzTex, 0));

    // Read input state from pipeline
    var xyz = textureLoad(xyzTex, coord, 0);
    var vel = textureLoad(velTex, coord, 0);
    var rgba = textureLoad(rgbaTex, coord, 0);
    var data = textureLoad(dataTex, coord, 0);

    // Extract components (normalized coords [0,1])
    let px = xyz.x;
    let py = xyz.y;
    let alive = xyz.w;

    var vx = vel.x;
    var vy = vel.y;
    var age = vel.z;
    let seed = vel.w;

    var typeId = data.x;
    var mass = data.y;

    let particleId = u32(coord.x + coord.y * stateSize.x);

    var pos = vec2f(px, py);
    var velocity = vec2f(vx, vy);

    // If not alive, pass through unchanged
    if (alive < 0.5) {
        return Outputs(xyz, vel, rgba, data);
    }

    // Initialize data on first use (typeId=0 and mass=0 means uninitialized)
    if (typeId == 0.0 && mass == 0.0) {
        let initSeed = particleId + u32(u.time * 1000.0);
        typeId = floor(hash(initSeed + 4u) * f32(u.typeCount));
        mass = 0.8 + hash(initSeed + 5u) * 0.4;

        // Initialize velocity if zero
        if (length(velocity) == 0.0) {
            let angle = hash(initSeed + 2u) * 6.28318530718;
            let speed = hash(initSeed + 3u) * u.maxSpeed * 0.3;
            velocity = vec2f(cos(angle), sin(angle)) * speed;
        }
    }

    // Ensure mass is valid
    mass = max(mass, 0.1);

    // Set color based on type
    rgba = vec4f(typeColor(i32(typeId), u.typeCount), 1.0);

    // Attrition is now handled by pointsEmit

    // === FORCE EVALUATION ===

    var totalForce = vec2f(0.0);
    var neighborCount = 0;
    let myType = i32(typeId);

    let myCell = getGridCell(pos);
    let totalParticles = stateSize.x * stateSize.y;

    // Sample neighbors using spatial grid
    for (var dy = -1; dy <= 1; dy++) {
        for (var dx = -1; dx <= 1; dx++) {
            var checkCell = myCell + vec2i(dx, dy);

            // Wrap cell coordinates
            checkCell = (checkCell + GRID_SIZE) % GRID_SIZE;

            let cellSeed = u32(checkCell.y * GRID_SIZE + checkCell.x);

            // Sample particles from this cell
            for (var s = 0; s < 12; s++) {
                let sampleSeed = cellSeed * 31u + u32(s) + u32(u.time * 7.0);
                let sampleIdx = i32(hash_uint(sampleSeed) % u32(totalParticles));

                let sx = sampleIdx % stateSize.x;
                let sy = sampleIdx / stateSize.x;

                // Skip self
                if (sx == coord.x && sy == coord.y) {
                    continue;
                }

                // Read neighbor state
                let otherXyz = textureLoad(xyzTex, vec2i(sx, sy), 0);
                let otherData = textureLoad(dataTex, vec2i(sx, sy), 0);

                let otherPos = otherXyz.xy;
                let otherAlive = otherXyz.w;
                let otherType = i32(otherData.x);

                // Skip dead or uninitialized
                if (otherAlive < 0.5) {
                    continue;
                }

                // Calculate distance with wrapping (toroidal)
                var diff = otherPos - pos;

                if (diff.x > 0.5) { diff.x -= 1.0; }
                if (diff.x < -0.5) { diff.x += 1.0; }
                if (diff.y > 0.5) { diff.y -= 1.0; }
                if (diff.y < -0.5) { diff.y += 1.0; }

                let dist = length(diff);

                // Skip if outside max interaction range
                if (dist < 0.0001 || dist > u.maxRadius) {
                    continue;
                }

                // Look up force parameters from ForceMatrix
                let forceParams = textureLoad(forceMatrix, vec2i(myType, otherType), 0);
                let strength = forceParams.x;
                let prefDist = forceParams.y;
                let curveShape = forceParams.z;

                // Calculate force magnitude
                let forceMag = radialForce(dist, strength, prefDist, curveShape);

                // Convert to force vector
                let forceDir = diff / dist;
                totalForce += forceDir * forceMag;
                neighborCount++;
            }
        }
    }

    // Normalize by mass
    totalForce /= mass;

    // === INTEGRATION ===

    // Apply forces
    velocity += totalForce;

    // Apply friction/damping
    velocity *= (1.0 - u.friction);

    // Limit speed
    velocity = limitVec(velocity, u.maxSpeed);

    // Update position
    pos += velocity;

    // Handle boundaries
    if (u.boundaryMode == 0) {
        // Wrap (toroidal)
        pos = wrapPosition(pos);
    } else {
        // Bounce
        if (pos.x < 0.0) { pos.x = -pos.x; velocity.x = -velocity.x; }
        if (pos.x > 1.0) { pos.x = 2.0 - pos.x; velocity.x = -velocity.x; }
        if (pos.y < 0.0) { pos.y = -pos.y; velocity.y = -velocity.y; }
        if (pos.y > 1.0) { pos.y = 2.0 - pos.y; velocity.y = -velocity.y; }
        pos = clamp(pos, vec2f(0.001), vec2f(0.999));
    }

    // Update age
    age += 0.016;

    var outColor = rgba;
    if (u.useTypeColor != 0) {
        outColor = vec4f(typeColor(i32(typeId), u.typeCount), 1.0);
    } else {
        // Sample from input texture based on position
        outColor = textureSampleLevel(inputTex, inputSampler, vec2f(pos.x, 1.0 - pos.y), 0.0);
    }

    // Output updated state
    return Outputs(
        vec4f(pos, 0.0, 1.0),
        vec4f(velocity, age, seed),
        outColor,
        vec4f(typeId, mass, 0.0, 1.0)
    );
}

// WGSL ForceMatrix Generator
// Encodes type-pair interaction parameters

struct Uniforms {
    resolution: vec2f,
    typeCount: i32,
    matrixSeed: f32,
    symmetricForces: i32,
}

@group(0) @binding(0) var<uniform> uniforms: Uniforms;

fn hash_uint(seed: u32) -> u32 {
    var state = seed * 747796405u + 2891336453u;
    let word = ((state >> ((state >> 28u) + 4u)) ^ state) * 277803737u;
    return (word >> 22u) ^ word;
}

fn hash(seed: u32) -> f32 {
    return f32(hash_uint(seed)) / 4294967295.0;
}

@fragment
fn main(@builtin(position) position: vec4f) -> @location(0) vec4f {
    let coord = vec2i(position.xy);
    let typeA = coord.x;
    let typeB = coord.y;

    // Skip if outside active types
    if (typeA >= uniforms.typeCount || typeB >= uniforms.typeCount) {
        return vec4f(0.0);
    }

    // Generate deterministic random based on seed and type pair
    var seed = u32(uniforms.matrixSeed * 1000.0) + u32(typeA * 31 + typeB * 17);

    // For symmetric forces, use canonical ordering
    if (uniforms.symmetricForces != 0 && typeB < typeA) {
        seed = u32(uniforms.matrixSeed * 1000.0) + u32(typeB * 31 + typeA * 17);
    }

    // Same type always has mild repulsion
    var strength: f32;
    if (typeA == typeB) {
        strength = -0.3 - hash(seed) * 0.4;
    } else {
        strength = hash(seed) * 2.0 - 1.0;
    }

    // Preferred distance (normalized)
    let prefDist = 0.3 + hash(seed + 1u) * 0.5;

    // Curve shape
    let curveShape = hash(seed + 2u);

    return vec4f(strength, prefDist, curveShape, 1.0);
}

// Passthrough shader - copy input to output for 2D chain continuity

struct Uniforms {
    resolution: vec2f,
    time: f32,
}

@group(0) @binding(0) var<uniform> u: Uniforms;
@group(0) @binding(1) var inputTex: texture_2d<f32>;
@group(0) @binding(2) var inputSampler: sampler;

@fragment
fn main(@builtin(position) position: vec4f) -> @location(0) vec4f {
    let uv = position.xy / u.resolution;
    return textureSampleLevel(inputTex, inputSampler, vec2f(uv.x, 1.0 - uv.y), 0.0);
}

// Physarum agent update shader - Common Agent Architecture
// Reads xyz/vel/rgba from pipeline, applies sensor-based steering

struct Uniforms {
    resolution: vec2f,
    time: f32,
    moveSpeed: f32,
    turnSpeed: f32,
    sensorAngle: f32,
    sensorDistance: f32,
    inputWeight: f32,
}

@group(0) @binding(0) var<uniform> u: Uniforms;
@group(0) @binding(1) var xyzTex: texture_2d<f32>;
@group(0) @binding(3) var velTex: texture_2d<f32>;
@group(0) @binding(5) var rgbaTex: texture_2d<f32>;
@group(0) @binding(7) var trailTex: texture_2d<f32>;
@group(0) @binding(8) var trailSampler: sampler;
@group(0) @binding(9) var inputTex: texture_2d<f32>;
@group(0) @binding(10) var inputSampler: sampler;

struct Outputs {
    @location(0) outXYZ: vec4f,
    @location(1) outVel: vec4f,
    @location(2) outRGBA: vec4f,
}

const TAU: f32 = 6.28318530718;

// Hash functions
fn hash_uint(seed: u32) -> u32 {
    var state = seed * 747796405u + 2891336453u;
    let word = ((state >> ((state >> 28u) + 4u)) ^ state) * 277803737u;
    return (word >> 22u) ^ word;
}

fn hash(seed: u32) -> f32 {
    return f32(hash_uint(seed)) / 4294967295.0;
}

fn hash_f(n: f32) -> f32 {
    return hash(bitcast<u32>(n));
}

// Wrap position to [0,1]
fn wrapPosition(pos: vec2f) -> vec2f {
    return fract(pos + vec2f(1.0));
}

fn luminance(color: vec3f) -> f32 {
    return dot(color, vec3f(0.2126, 0.7152, 0.0722));
}

// Sample trail at normalized UV
fn sampleTrail(uv: vec2f) -> f32 {
    return luminance(textureSampleLevel(trailTex, trailSampler, uv, 0.0).rgb);
}

// Sample input texture for external field attraction
fn sampleExternalField(uv: vec2f, weight: f32) -> f32 {
    if (weight <= 0.0) { return 0.0; }
    let blend = clamp(weight * 0.01, 0.0, 1.0);
    return luminance(textureSampleLevel(inputTex, inputSampler, uv, 0.0).rgb) * blend * 0.05;
}

@fragment
fn main(@builtin(position) fragCoord: vec4f) -> Outputs {
    let stateSize = vec2i(textureDimensions(xyzTex, 0));
    let coord = vec2i(i32(fragCoord.x), i32(fragCoord.y));

    // Read current state
    let xyz = textureLoad(xyzTex, coord, 0);
    let vel = textureLoad(velTex, coord, 0);
    let rgba = textureLoad(rgbaTex, coord, 0);

    var pos = xyz.xy;           // Normalized [0,1]
    var heading = xyz.z;        // Radians
    let alive = xyz.w;
    let age = vel.z;
    let seed = vel.w;

    // Check if agent is dead (needs respawn by pointsEmit)
    if (alive < 0.5) {
        // Pass through - pointsEmit will handle respawn
        // Initialize heading from seed
        return Outputs(
            vec4f(pos, hash(u32(seed * 1000.0)) * TAU, 0.0),
            vel,
            rgba
        );
    }

    // Attrition is now handled by pointsEmit

    // Compute sensor positions in normalized coords
    let forwardDir = vec2f(cos(heading), sin(heading));
    let leftDir = vec2f(cos(heading - u.sensorAngle), sin(heading - u.sensorAngle));
    let rightDir = vec2f(cos(heading + u.sensorAngle), sin(heading + u.sensorAngle));

    let sensorPosF = wrapPosition(pos + forwardDir * u.sensorDistance);
    let sensorPosL = wrapPosition(pos + leftDir * u.sensorDistance);
    let sensorPosR = wrapPosition(pos + rightDir * u.sensorDistance);

    // Sample trail + external field at sensor positions
    let valF = sampleTrail(sensorPosF) + sampleExternalField(sensorPosF, u.inputWeight);
    let valL = sampleTrail(sensorPosL) + sampleExternalField(sensorPosL, u.inputWeight);
    let valR = sampleTrail(sensorPosR) + sampleExternalField(sensorPosR, u.inputWeight);

    // Steering logic
    var newHeading = heading;
    if (valF > valL && valF > valR) {
        // Forward is best, keep going
    } else if (valF < valL && valF < valR) {
        // Forward is worst, turn randomly
        newHeading += (hash_f(u.time + pos.x) - 0.5) * 2.0 * u.turnSpeed * u.moveSpeed;
    } else if (valL > valR) {
        // Turn left
        newHeading -= u.turnSpeed * u.moveSpeed;
    } else if (valR > valL) {
        // Turn right
        newHeading += u.turnSpeed * u.moveSpeed;
    }

    // Move forward
    let moveDir = vec2f(cos(newHeading), sin(newHeading));

    // Speed modulation from input texture
    var speedScale = 1.0;
    let blend = clamp(u.inputWeight * 0.01, 0.0, 1.0);
    if (blend > 0.0) {
        let localInput = luminance(textureSampleLevel(inputTex, inputSampler, pos, 0.0).rgb);
        // Invert: slow in bright, fast in dark
        speedScale = mix(1.0, mix(1.8, 0.35, localInput), blend);
    }

    // Scale moveSpeed to normalized coords
    let normalizedSpeed = u.moveSpeed * 0.001 * speedScale;
    let newPos = wrapPosition(pos + moveDir * normalizedSpeed);

    // Update age
    let newAge = age + 0.016;

    // Output
    return Outputs(
        vec4f(newPos, newHeading, 1.0),  // alive = 1
        vec4f(0.0, 0.0, newAge, seed),
        rgba  // Color unchanged
    );
}

// Deposit Shader - Scatter agents to trail texture

struct Uniforms {
    resolution: vec2<f32>,
    deposit: f32,
};

struct VertexOutput {
    @builtin(position) position: vec4<f32>,
    @location(0) color: vec4<f32>,
};

@group(0) @binding(0) var<uniform> u: Uniforms;
@group(0) @binding(1) var xyzTex: texture_2d<f32>;
@group(0) @binding(2) var rgbaTex: texture_2d<f32>;

@vertex
fn vertexMain(@builtin(vertex_index) vertexIndex: u32) -> VertexOutput {
    var out: VertexOutput;

    // Get state size from xyz texture dimensions (inherited from pointsEmit)
    let texSize = textureDimensions(xyzTex, 0);
    let stateSize = i32(texSize.x);
    let totalAgents = stateSize * stateSize;

    // Cull vertices beyond texture size
    if (i32(vertexIndex) >= totalAgents) {
        out.position = vec4<f32>(2.0, 2.0, 0.0, 1.0);
        out.color = vec4<f32>(0.0);
        return out;
    }

    // Calculate UV for this agent
    let x = i32(vertexIndex) % stateSize;
    let y = i32(vertexIndex) / stateSize;

    // Read agent position and color
    let pos = textureLoad(xyzTex, vec2<i32>(x, y), 0);
    let col = textureLoad(rgbaTex, vec2<i32>(x, y), 0);

    // Check if agent is alive (pos.w >= 0.5 means alive)
    if (pos.w < 0.5) {
        out.position = vec4<f32>(2.0, 2.0, 0.0, 1.0);
        out.color = vec4<f32>(0.0);
        return out;
    }

    // Convert display-space position (0..1, top-left Y) to WebGPU clip space.
    let clipPos = vec2<f32>(pos.x * 2.0 - 1.0, 1.0 - pos.y * 2.0);

    out.position = vec4<f32>(clipPos, 0.0, 1.0);

    // Apply deposit amount
