struct Uniforms {
    resolution: vec2f,
    time: f32,
    gravity: f32,
    wind: f32,
    energy: f32,
    drag: f32,
    deviation: f32,
    wander: f32,
}

struct Outputs {
    @location(0) xyz: vec4f,
    @location(1) vel: vec4f,
    @location(2) rgba: vec4f,
}

// Bindings: uniforms at 0, then state textures consecutively (textureLoad, no samplers)
