fn hash_uint_bb(seed: u32) -> u32 {
    var state = seed * 747796405u + 2891336453u;
    let word = ((state >> ((state >> 28u) + 4u)) ^ state) * 277803737u;
    return (word >> 22u) ^ word;
}

fn hash(n: f32) -> f32 {
    return f32(hash_uint_bb(bitcast<u32>(n + f32(u.seed)))) / 4294967295.0;
