@vertex
fn vertexMain(@builtin(vertex_index) vertexIndex: u32) -> VertexOutput {
    var out: VertexOutput;

    if (BLUR_LAYER == 1 && (VIEW_MODE == 0 || u.aperture <= 0.0 || BLEND_MODE != 0)) {
        out.position = vec4f(2.0, 2.0, 0.0, 1.0);
        return out;
    }
