fn shadeSprite(uv: vec2f, color: vec4f) -> vec4f {
    let opacity = u.depositOpacity / 100.0;

    if (u.shapeMode == 0) {
        // Texture mode: sample sprite texture
        let spriteColor = textureSampleLevel(spriteTex, spriteSampler, uv, 0.0);
