@group(0) @binding(5) var<uniform> matteOpacity : f32;

@fragment
fn main(@builtin(position) position : vec4<f32>) -> @location(0) vec4<f32> {
    let size = max(resolution, vec2<f32>(1.0));
    var uv = position.xy / size;

    let inputColor = textureSample(inputTex, u_sampler, uv);
    let trailColor = textureSample(trailTex, u_sampler, uv);

    // Additive blend: trail + scaled input
    // inputIntensity 0 = black, 100 = trail + full input
    let t = inputIntensity / 100.0;
    let matteAlpha = matteOpacity;

    // Trail presence based on max RGB channel
    let trailPresence = max(max(trailColor.r, trailColor.g), trailColor.b);

    // Background contribution is scaled by matte opacity (premultiplied)
    // Trail contribution is NOT affected by matte opacity
    let rgb = trailColor.rgb + inputColor.rgb * t * matteAlpha;

    // Alpha: where trail exists, full opacity; elsewhere, matte opacity
    let alpha = max(trailPresence, matteAlpha);

    return clamp(vec4<f32>(rgb, alpha), vec4<f32>(0.0), vec4<f32>(1.0));
}

// Copy Pass - Blit source to destination (for ping-pong correction)
// Pass provides: sourceTex (binding 0), sampler (binding 1)
// No uniforms - use texture dimensions for resolution

@group(0) @binding(0) var sourceTex: texture_2d<f32>;
@group(0) @binding(1) var u_sampler: sampler;

@fragment
fn main(@builtin(position) position: vec4<f32>) -> @location(0) vec4<f32> {
    let dims = textureDimensions(sourceTex, 0);
    let uv = position.xy / vec2<f32>(f32(dims.x), f32(dims.y));
    return textureSample(sourceTex, u_sampler, uv);
}

// Deposit Shader - Scatter agents to trail texture

struct Uniforms {
    resolution: vec2<f32>,
    density: f32,
    rotateX: f32,
    rotateY: f32,
    rotateZ: f32,
    viewScale: f32,
    posX: f32,
    posY: f32,
    posZ: f32,
    fieldOfView: f32,
};

struct VertexOutput {
    @builtin(position) position: vec4<f32>,
    @location(0) color: vec4<f32>,
};

@group(0) @binding(0) var<uniform> u: Uniforms;
@group(0) @binding(1) var xyzTex: texture_2d<f32>;
@group(0) @binding(2) var rgbaTex: texture_2d<f32>;

@vertex
fn vertexMain(@builtin(vertex_index) vertexIndex: u32) -> VertexOutput {
    var out: VertexOutput;

    // Get state size from xyz texture dimensions (inherited from pointsEmit)
    let texSize = textureDimensions(xyzTex, 0);
    let stateSize = i32(texSize.x);
    let totalAgents = stateSize * stateSize;

    // Cull vertices beyond texture size
    if (i32(vertexIndex) >= totalAgents) {
        out.position = vec4<f32>(2.0, 2.0, 0.0, 1.0);
        out.color = vec4<f32>(0.0);
        return out;
    }

    // Density-based culling
    let cullThreshold = u.density / 100.0;
    let particleRandom = fract(f32(vertexIndex) * 0.618033988749895);
    if (particleRandom > cullThreshold) {
        out.position = vec4<f32>(2.0, 2.0, 0.0, 1.0);
        out.color = vec4<f32>(0.0);
        return out;
    }

    // Calculate UV for this agent
    let x = i32(vertexIndex) % stateSize;
    let y = i32(vertexIndex) / stateSize;

    // Read agent position and color
    let pos = textureLoad(xyzTex, vec2<i32>(x, y), 0);
    let col = textureLoad(rgbaTex, vec2<i32>(x, y), 0);

    // Check if agent is alive (pos.w >= 0.5 means alive)
    if (pos.w < 0.5) {
        out.position = vec4<f32>(2.0, 2.0, 0.0, 1.0);
        out.color = vec4<f32>(0.0);
        return out;
    }

    var clipPos: vec2<f32>;

    if (VIEW_MODE == 0) {
        // 2D mode: positions are normalized 0..1
        clipPos = vec2<f32>(pos.x * 2.0 - 1.0, 1.0 - pos.y * 2.0);
    } else {
        // 3D mode: rotate world coordinates before camera projection
        var p = pos.xyz;

        // Detect if this is a 2D system (coords in 0-1) or 3D attractor (coords ±40)
        // 2D systems have Z near 0 and XY in 0-1 range
        let is2DSystem = VIEW_MODE == 1 && abs(p.z) < 1.0 && p.x >= 0.0 && p.x <= 1.0 && p.y >= 0.0 && p.y <= 1.0;

        if (is2DSystem) {
            // Center 2D coords around origin: 0-1 -> -0.5 to 0.5
            p = vec3<f32>(p.x - 0.5, p.y - 0.5, 0.0);
        }

        // Apply rotation around X axis
        let cosX = cos(u.rotateX);
        let sinX = sin(u.rotateX);
        p = vec3<f32>(p.x, p.y * cosX - p.z * sinX, p.y * sinX + p.z * cosX);

        // Apply rotation around Y axis
        let cosY = cos(u.rotateY);
        let sinY = sin(u.rotateY);
        p = vec3<f32>(p.x * cosY + p.z * sinY, p.y, -p.x * sinY + p.z * cosY);

        // Apply rotation around Z axis
        let cosZ = cos(u.rotateZ);
        let sinZ = sin(u.rotateZ);
        p = vec3<f32>(p.x * cosZ - p.y * sinZ, p.x * sinZ + p.y * cosZ, p.z);

        // Apply X/Y offset after rotation (pan in screen space)
        p.x = p.x + u.posX;
        p.y = p.y + u.posY;

        if (VIEW_MODE == 2) {
            // Match the billboard camera at Z=80, looking down negative Z.
            let cameraDepth = 80.0 - (p.z + u.posZ);
            if (cameraDepth <= 0.1) {
                out.position = vec4<f32>(2.0, 2.0, 0.0, 1.0);
                out.color = vec4<f32>(0.0);
                return out;
            }
            let focalLength = 1.0 / tan(clamp(u.fieldOfView, 10.0, 150.0) * 0.00872664626);
            clipPos = p.xy * focalLength * u.viewScale / cameraDepth;
            clipPos.x = clipPos.x * u.resolution.y / u.resolution.x;
        } else if (is2DSystem) {
            // 2D systems: coords are now ±0.5, scale to fill viewport
            // Use 3.5x multiplier for close-up view that's nice to pan around
            clipPos = p.xy * 3.5 * u.viewScale;
        } else {
            // 3D attractors: coords range roughly ±40, normalize then scale
            clipPos = p.xy / 40.0 * u.viewScale;
        }
        clipPos.y = -clipPos.y;
    }

    out.position = vec4<f32>(clipPos, 0.0, 1.0);
    out.color = vec4<f32>(col.rgb, col.a);
    return out;
}

@fragment
fn fragmentMain(in: VertexOutput) -> @location(0) vec4<f32> {
    return in.color;
}

// Diffuse Pass - Decay existing trail (matches flow)

struct Uniforms {
    resolution: vec2<f32>,
    intensity: f32,
};

@group(0) @binding(0) var<uniform> u: Uniforms;
@group(0) @binding(1) var trailTex: texture_2d<f32>;
@group(0) @binding(2) var trailSampler: sampler;

@fragment
fn main(@builtin(position) fragCoord: vec4<f32>) -> @location(0) vec4<f32> {
    let uv = fragCoord.xy / u.resolution;

    // Sample the trail texture directly (no blur)
    let trailColor = textureSample(trailTex, trailSampler, uv);

    // Apply intensity decay (persistence) - faithfully matches flow implementation
    // intensity=100 means no decay, intensity=0 means instant fade
    let decay = clamp(u.intensity / 100.0, 0.0, 1.0);
    return clamp(trailColor * decay, vec4<f32>(0.0), vec4<f32>(1.0));
}

/*
 * Universal 3D volume renderer (WGSL)
 * 
 * This shader provides common raymarching logic extracted from all 3D effects.
 * It supports both isosurface (smooth) and voxel (blocky) rendering modes.
 * 
 * The volume is sampled from the red channel (.r) for the density/SDF field.
 * RGB channels are used for coloring.
 */

// FILTERING and INVERT are compile-time defines injected by the expander
// (see definition.js). They eliminate the unused raymarching path and the
// per-sample invert branch respectively, dramatically reducing the work the
// SPIR-V optimizer has to do on a 14kB shader.
@group(0) @binding(0) var<uniform> resolution: vec2<f32>;
@group(0) @binding(1) var<uniform> time: f32;
@group(0) @binding(2) var<uniform> threshold: f32;
@group(0) @binding(3) var<uniform> volumeSize: i32;
@group(0) @binding(4) var<uniform> orbitSpeed: i32;
@group(0) @binding(5) var<uniform> bgColor: vec3<f32>;
@group(0) @binding(6) var<uniform> bgAlpha: f32;
@group(0) @binding(7) var volumeCache: texture_2d<f32>;
@group(0) @binding(8) var<uniform> tileOffset: vec2<f32>;
@group(0) @binding(9) var<uniform> fullResolution: vec2<f32>;

const TAU: f32 = 6.283185307179586;
const PI: f32 = 3.141592653589793;
const MAX_STEPS: i32 = 256;
const MAX_DIST: f32 = 10.0;

// MRT output structure for color and geometry buffer
struct FragmentOutput {
    @location(0) color: vec4<f32>,
    @location(1) geoOut: vec4<f32>,
}

// Convert 3D volume coordinates to 2D atlas texel coordinates
fn volumeToAtlas(x: i32, y: i32, z: i32, volSize: i32) -> vec2<i32> {
    return vec2<i32>(x, y + z * volSize);
}

// Sample volume at integer voxel coordinates (for voxel mode)
fn sampleVoxel(voxel: vec3<i32>) -> vec4<f32> {
    let volSize = volumeSize;
    let clamped = clamp(voxel, vec3<i32>(0), vec3<i32>(volSize - 1));
    return textureLoad(volumeCache, volumeToAtlas(clamped.x, clamped.y, clamped.z, volSize), 0);
}

// Sample the cached 3D volume with trilinear interpolation
// World position p is in [-1, 1]^3 (bounding box coordinates)
fn sampleVolume(worldPos: vec3<f32>) -> vec4<f32> {
    let volSize = volumeSize;
    let volSizeF = f32(volSize);

    // Convert world position [-1, 1] to normalized volume coords [0, 1]
    var uvw = worldPos * 0.5 + 0.5;
    uvw = clamp(uvw, vec3<f32>(0.0), vec3<f32>(1.0));

    // Convert to texel coordinates
    let texelPos = uvw * (volSizeF - 1.0);
    let texelFloor = floor(texelPos);
    let frac = texelPos - texelFloor;

    let i0 = vec3<i32>(texelFloor);
    let i1 = min(i0 + 1, vec3<i32>(volSize - 1));

    // Trilinear filtering - load 8 corners
    let c000 = textureLoad(volumeCache, volumeToAtlas(i0.x, i0.y, i0.z, volSize), 0);
    let c100 = textureLoad(volumeCache, volumeToAtlas(i1.x, i0.y, i0.z, volSize), 0);
    let c010 = textureLoad(volumeCache, volumeToAtlas(i0.x, i1.y, i0.z, volSize), 0);
    let c110 = textureLoad(volumeCache, volumeToAtlas(i1.x, i1.y, i0.z, volSize), 0);
    let c001 = textureLoad(volumeCache, volumeToAtlas(i0.x, i0.y, i1.z, volSize), 0);
    let c101 = textureLoad(volumeCache, volumeToAtlas(i1.x, i0.y, i1.z, volSize), 0);
    let c011 = textureLoad(volumeCache, volumeToAtlas(i0.x, i1.y, i1.z, volSize), 0);
    let c111 = textureLoad(volumeCache, volumeToAtlas(i1.x, i1.y, i1.z, volSize), 0);

    // Trilinear interpolation
    let c00 = mix(c000, c100, frac.x);
    let c10 = mix(c010, c110, frac.x);
    let c01 = mix(c001, c101, frac.x);
    let c11 = mix(c011, c111, frac.x);

    let c0 = mix(c00, c10, frac.y);
    let c1 = mix(c01, c11, frac.y);

    return mix(c0, c1, frac.z);
}

// Get the scalar field value at a point (what we're finding the isosurface of)
// Convention: HIGH values = SOLID, field < 0 = inside solid
fn getField(p: vec3<f32>) -> f32 {
    var val = sampleVolume(p).r;
    // INVERT is a compile-time const; the optimizer drops the dead branch.
    if (INVERT) {
        val = 1.0 - val;
    }
    return threshold - val;
}

// Check if a voxel is solid (above threshold - high values = solid)
fn isVoxelSolid(voxel: vec3<i32>) -> bool {
    var val = sampleVoxel(voxel).r;
    if (INVERT) {
        val = 1.0 - val;
    }
    return val > threshold;
}

// Convert world position to voxel coordinates
fn worldToVoxel(worldPos: vec3<f32>) -> vec3<i32> {
    let volSize = volumeSize;
    let uvw = worldPos * 0.5 + 0.5;  // [-1,1] -> [0,1]
    return vec3<i32>(floor(uvw * f32(volSize)));
}

// Convert voxel coordinates to world position (center of voxel)
fn voxelToWorld(voxel: vec3<i32>) -> vec3<f32> {
    let volSize = volumeSize;
    let uvw = (vec3<f32>(voxel) + 0.5) / f32(volSize);  // center of voxel in [0,1]
    return uvw * 2.0 - 1.0;  // [0,1] -> [-1,1]
}

// Voxel hit result
struct VoxelHit {
    dist: f32,
    normal: vec3<f32>,
    voxel: vec3<i32>,
}

// DDA voxel traversal - returns hit distance and face normal
fn voxelTrace(ro: vec3<f32>, rd: vec3<f32>) -> VoxelHit {
    var result: VoxelHit;
    result.dist = -1.0;
    result.normal = vec3<f32>(0.0);
    result.voxel = vec3<i32>(0);

    let volSize = volumeSize;
    let voxelSize = 2.0 / f32(volSize);  // world-space size of one voxel

    // Ray-box intersection with the volume bounds [-1, 1]
    let invRd = 1.0 / rd;
    let t0 = (-1.0 - ro) * invRd;
    let t1 = (1.0 - ro) * invRd;
    let tminV = min(t0, t1);
    let tmaxV = max(t0, t1);
    let tEnter = max(max(tminV.x, tminV.y), tminV.z);
    let tExit = min(min(tmaxV.x, tmaxV.y), tmaxV.z);

    if (tEnter > tExit || tExit < 0.0) {
        return result;  // No intersection with volume
    }

    // Start position (slightly inside the volume)
    var tStart = max(tEnter + 0.001, 0.0);
    let pos = ro + rd * tStart;

    // Current voxel
    var voxel = worldToVoxel(pos);
    voxel = clamp(voxel, vec3<i32>(0), vec3<i32>(volSize - 1));

    // Step direction
    let step = vec3<i32>(sign(rd));

    // Distance to next voxel boundary in each axis
    let voxelBounds = voxelToWorld(voxel + max(step, vec3<i32>(0)));
    var tMaxVec = (voxelBounds - ro) * invRd;

    // Distance to cross one voxel in each axis
    let tDelta = abs(vec3<f32>(voxelSize) * invRd);

    // Traverse voxels
    var lastNormal = vec3<f32>(0.0);
    for (var i: i32 = 0; i < MAX_STEPS * 2; i = i + 1) {
        // Check if current voxel is solid
        if (voxel.x >= 0 && voxel.x < volSize &&
            voxel.y >= 0 && voxel.y < volSize &&
            voxel.z >= 0 && voxel.z < volSize) {

            if (isVoxelSolid(voxel)) {
                // Hit! 
                result.dist = tStart;
                result.normal = lastNormal;
                result.voxel = voxel;

                // If this is the first voxel, compute entry normal
                if (lastNormal.x == 0.0 && lastNormal.y == 0.0 && lastNormal.z == 0.0) {
                    if (tminV.x > tminV.y && tminV.x > tminV.z) {
                        result.normal = vec3<f32>(-sign(rd.x), 0.0, 0.0);
                    } else if (tminV.y > tminV.z) {
                        result.normal = vec3<f32>(0.0, -sign(rd.y), 0.0);
                    } else {
                        result.normal = vec3<f32>(0.0, 0.0, -sign(rd.z));
                    }
                }
                return result;
            }
        }

        // Step to next voxel (DDA)
        if (tMaxVec.x < tMaxVec.y) {
            if (tMaxVec.x < tMaxVec.z) {
                tStart = tMaxVec.x;
                tMaxVec.x = tMaxVec.x + tDelta.x;
                voxel.x = voxel.x + step.x;
                lastNormal = vec3<f32>(-f32(step.x), 0.0, 0.0);
            } else {
                tStart = tMaxVec.z;
                tMaxVec.z = tMaxVec.z + tDelta.z;
                voxel.z = voxel.z + step.z;
                lastNormal = vec3<f32>(0.0, 0.0, -f32(step.z));
            }
        } else {
            if (tMaxVec.y < tMaxVec.z) {
                tStart = tMaxVec.y;
                tMaxVec.y = tMaxVec.y + tDelta.y;
                voxel.y = voxel.y + step.y;
                lastNormal = vec3<f32>(0.0, -f32(step.y), 0.0);
            } else {
                tStart = tMaxVec.z;
                tMaxVec.z = tMaxVec.z + tDelta.z;
                voxel.z = voxel.z + step.z;
                lastNormal = vec3<f32>(0.0, 0.0, -f32(step.z));
            }
        }

        // Check if we've exited the volume
        if (tStart > tExit) { break; }
    }

    return result;
}

// Compute smooth normal using central differences on the SDF field
fn calcNormal(p: vec3<f32>) -> vec3<f32> {
    let eps = 2.0 / f32(volumeSize);

    let dx = getField(p + vec3<f32>(eps, 0.0, 0.0)) - getField(p - vec3<f32>(eps, 0.0, 0.0));
    let dy = getField(p + vec3<f32>(0.0, eps, 0.0)) - getField(p - vec3<f32>(0.0, eps, 0.0));
    let dz = getField(p + vec3<f32>(0.0, 0.0, eps)) - getField(p - vec3<f32>(0.0, 0.0, eps));

    var n = vec3<f32>(dx, dy, dz);

    let len = length(n);
    if (len < 0.0001) { return vec3<f32>(0.0, 1.0, 0.0); }

    return n / len;
}

// Isosurface hit result
struct IsoHit {
    dist: f32,
    pos: vec3<f32>,
    hit: bool,
}

// Analytic isosurface raymarching with bisection refinement
fn isosurfaceTrace(ro: vec3<f32>, rd: vec3<f32>) -> IsoHit {
    var result: IsoHit;
    result.hit = false;
    result.dist = -1.0;
    result.pos = vec3<f32>(0.0);

    let invRd = 1.0 / rd;
    let t0 = (-1.0 - ro) * invRd;
    let t1 = (1.0 - ro) * invRd;
    let tminV = min(t0, t1);
    let tmaxV = max(t0, t1);
    let tEnter = max(max(tminV.x, tminV.y), tminV.z);
    let tExit = min(min(tmaxV.x, tmaxV.y), tmaxV.z);

    if (tEnter > tExit || tExit < 0.0) { return result; }

    let tStart = max(tEnter, 0.0);
    let stepSize = 1.5 / f32(volumeSize);

    var t = tStart;
    var prevField = getField(ro + rd * t);

    // If we start inside solid (e.g., inverted volume), hit the bounding box surface
    if (prevField < 0.0) {
        result.hit = true;
        result.dist = tStart;
        result.pos = ro + rd * tStart;
        return result;
    }

    for (var i: i32 = 0; i < MAX_STEPS; i = i + 1) {
        t = t + stepSize;
        if (t > tExit) { break; }

        let p = ro + rd * t;
        let field = getField(p);

        if (prevField * field < 0.0) {
            var tLo = t - stepSize;
            var tHi = t;
            var pf = prevField;

            for (var j: i32 = 0; j < 8; j = j + 1) {
                let tMid = (tLo + tHi) * 0.5;
                let fMid = getField(ro + rd * tMid);

                if (pf * fMid < 0.0) {
                    tHi = tMid;
                } else {
                    tLo = tMid;
                    pf = fMid;
                }
            }

            result.hit = true;
            result.dist = (tLo + tHi) * 0.5;
            result.pos = ro + rd * result.dist;
            return result;
        }

        prevField = field;
    }

    return result;
}

// Shading for smooth isosurface
fn shade(p: vec3<f32>, rd: vec3<f32>) -> vec3<f32> {
    let n = calcNormal(p);
    let lightDir = normalize(vec3<f32>(1.0, 1.0, -1.0));

    let diff = max(dot(n, lightDir), 0.0);
    let amb: f32 = 0.15;

    let halfVec = normalize(lightDir - rd);
    let spec = pow(max(dot(n, halfVec), 0.0), 32.0);

    let rim = pow(1.0 - max(dot(n, -rd), 0.0), 3.0);

    // Use RGB from volume for coloring
    let volColor = sampleVolume(p);
    var baseColor = volColor.rgb;

    // If volume appears grayscale (R≈G≈B), use a neutral gray
    let colorVariance = length(volColor.rgb - vec3<f32>(volColor.r));
    if (colorVariance < 0.01) {
        baseColor = vec3<f32>(0.75);
    }

    return baseColor * (amb + diff * 0.7) + spec * 0.2 + rim * 0.15;
}

// Voxel shading with flat face normals
fn shadeVoxel(p: vec3<f32>, rd: vec3<f32>, n: vec3<f32>, voxel: vec3<i32>) -> vec3<f32> {
    let lightDir = normalize(vec3<f32>(1.0, 1.0, -1.0));

    let diff = max(dot(n, lightDir), 0.0);
    let amb: f32 = 0.3;

    // Use RGB from volume for coloring
    let volColor = sampleVoxel(voxel);
    var baseColor = volColor.rgb;

    // If volume appears grayscale, apply face-based shading variation
    let colorVariance = length(volColor.rgb - vec3<f32>(volColor.r));
    if (colorVariance < 0.01) {
        let faceShade = abs(n.x) * 0.9 + abs(n.y) * 1.0 + abs(n.z) * 0.85;
        baseColor = vec3<f32>(0.7 * faceShade);
    }

    return baseColor * (amb + diff * 0.7);
}

@fragment
fn main(@builtin(position) position: vec4<f32>) -> FragmentOutput {
    var fullRes = select(resolution, fullResolution, fullResolution.x > 0.0);
    if (fullRes.x < 1.0) { fullRes = vec2<f32>(1024.0, 1024.0); }

    let uv = ((position.xy + tileOffset) - 0.5 * fullRes) / fullRes.y;

    let camAngle = time * TAU * f32(orbitSpeed);
    let camDist: f32 = 3.5;
    let ro = vec3<f32>(sin(camAngle) * camDist, 0.5, cos(camAngle) * camDist);
    let lookAt = vec3<f32>(0.0);

    let forward = normalize(lookAt - ro);
    let right = normalize(cross(vec3<f32>(0.0, 1.0, 0.0), forward));
    let up = cross(forward, right);

    let rd = normalize(forward + uv.x * right + uv.y * up);

    var color: vec3<f32>;
    var normal = vec3<f32>(0.0, 0.0, 1.0);
    var depth: f32 = 1.0;
    var alpha: f32 = 1.0;

    // FILTERING is a compile-time const; the optimizer eliminates the
    // unused raymarching path entirely.
    if (FILTERING == 1) {
        let hit = voxelTrace(ro, rd);
        if (hit.dist > 0.0) {
            let p = ro + rd * hit.dist;
            color = shadeVoxel(p, rd, hit.normal, hit.voxel);
            normal = hit.normal;
            depth = hit.dist / MAX_DIST;
        } else {
            color = bgColor;
            alpha = bgAlpha;
        }
    } else {
        let hit = isosurfaceTrace(ro, rd);
        if (hit.hit) {
            color = shade(hit.pos, rd);
            normal = calcNormal(hit.pos);
            depth = hit.dist / MAX_DIST;
        } else {
            color = bgColor;
            alpha = bgAlpha;
        }
    }

    color = pow(color, vec3<f32>(1.0 / 2.2));

    var output: FragmentOutput;
    output.color = vec4<f32>(color, alpha);
    output.geoOut = vec4<f32>(normal * 0.5 + 0.5, depth);
    return output;
}

/*
 * Cubemap 3D volume renderer (WGSL) — renderCubemap3d
 *
 * A multi-face clone of render3d: the lit "blob in space" projected onto cube
 * faces. Same isosurface/voxel raymarching and shading as render3d (including
 * gamma) — only the orbit camera is replaced by the per-face cube camera
 * (cubeBasis, 90-degree frustum from the volume center).
 *
 * The volume is sampled from the red channel (.r) for the density/SDF field.
 * RGB channels are used for coloring.
 */

// FILTERING and INVERT are compile-time defines injected by the expander
// (see definition.js). They eliminate the unused raymarching path and the
// per-sample invert branch respectively, dramatically reducing the work the
// SPIR-V optimizer has to do on a 14kB shader.
@group(0) @binding(0) var<uniform> resolution: vec2<f32>;
@group(0) @binding(1) var<uniform> threshold: f32;
@group(0) @binding(2) var<uniform> volumeSize: i32;
@group(0) @binding(3) var<uniform> cubeBasis: mat3x3<f32>;
@group(0) @binding(4) var<uniform> bgColor: vec3<f32>;
@group(0) @binding(5) var<uniform> bgAlpha: f32;
@group(0) @binding(6) var volumeCache: texture_2d<f32>;
@group(0) @binding(7) var<uniform> tileOffset: vec2<f32>;
@group(0) @binding(8) var<uniform> fullResolution: vec2<f32>;

const TAU: f32 = 6.283185307179586;
const PI: f32 = 3.141592653589793;
const MAX_STEPS: i32 = 256;
const MAX_DIST: f32 = 10.0;

// MRT output structure for color and geometry buffer
struct FragmentOutput {
    @location(0) color: vec4<f32>,
    @location(1) geoOut: vec4<f32>,
}

// Convert 3D volume coordinates to 2D atlas texel coordinates
fn volumeToAtlas(x: i32, y: i32, z: i32, volSize: i32) -> vec2<i32> {
    return vec2<i32>(x, y + z * volSize);
}

// Sample volume at integer voxel coordinates (for voxel mode)
fn sampleVoxel(voxel: vec3<i32>) -> vec4<f32> {
    let volSize = volumeSize;
    let clamped = clamp(voxel, vec3<i32>(0), vec3<i32>(volSize - 1));
    return textureLoad(volumeCache, volumeToAtlas(clamped.x, clamped.y, clamped.z, volSize), 0);
}

// Sample the cached 3D volume with trilinear interpolation
// World position p is in [-1, 1]^3 (bounding box coordinates)
fn sampleVolume(worldPos: vec3<f32>) -> vec4<f32> {
    let volSize = volumeSize;
    let volSizeF = f32(volSize);

    // Convert world position [-1, 1] to normalized volume coords [0, 1]
    var uvw = worldPos * 0.5 + 0.5;
    uvw = clamp(uvw, vec3<f32>(0.0), vec3<f32>(1.0));

    // Convert to texel coordinates
    let texelPos = uvw * (volSizeF - 1.0);
    let texelFloor = floor(texelPos);
    let frac = texelPos - texelFloor;

    let i0 = vec3<i32>(texelFloor);
    let i1 = min(i0 + 1, vec3<i32>(volSize - 1));

    // Trilinear filtering - load 8 corners
    let c000 = textureLoad(volumeCache, volumeToAtlas(i0.x, i0.y, i0.z, volSize), 0);
    let c100 = textureLoad(volumeCache, volumeToAtlas(i1.x, i0.y, i0.z, volSize), 0);
    let c010 = textureLoad(volumeCache, volumeToAtlas(i0.x, i1.y, i0.z, volSize), 0);
    let c110 = textureLoad(volumeCache, volumeToAtlas(i1.x, i1.y, i0.z, volSize), 0);
    let c001 = textureLoad(volumeCache, volumeToAtlas(i0.x, i0.y, i1.z, volSize), 0);
    let c101 = textureLoad(volumeCache, volumeToAtlas(i1.x, i0.y, i1.z, volSize), 0);
    let c011 = textureLoad(volumeCache, volumeToAtlas(i0.x, i1.y, i1.z, volSize), 0);
    let c111 = textureLoad(volumeCache, volumeToAtlas(i1.x, i1.y, i1.z, volSize), 0);

    // Trilinear interpolation
    let c00 = mix(c000, c100, frac.x);
    let c10 = mix(c010, c110, frac.x);
    let c01 = mix(c001, c101, frac.x);
    let c11 = mix(c011, c111, frac.x);

    let c0 = mix(c00, c10, frac.y);
    let c1 = mix(c01, c11, frac.y);

    return mix(c0, c1, frac.z);
}

// Get the scalar field value at a point (what we're finding the isosurface of)
// Convention: HIGH values = SOLID, field < 0 = inside solid
fn getField(p: vec3<f32>) -> f32 {
    var val = sampleVolume(p).r;
    // INVERT is a compile-time const; the optimizer drops the dead branch.
    if (INVERT) {
        val = 1.0 - val;
    }
    return threshold - val;
}

// Check if a voxel is solid (above threshold - high values = solid)
fn isVoxelSolid(voxel: vec3<i32>) -> bool {
    var val = sampleVoxel(voxel).r;
    if (INVERT) {
        val = 1.0 - val;
    }
    return val > threshold;
}

// Convert world position to voxel coordinates
fn worldToVoxel(worldPos: vec3<f32>) -> vec3<i32> {
    let volSize = volumeSize;
    let uvw = worldPos * 0.5 + 0.5;  // [-1,1] -> [0,1]
    return vec3<i32>(floor(uvw * f32(volSize)));
}

// Convert voxel coordinates to world position (center of voxel)
fn voxelToWorld(voxel: vec3<i32>) -> vec3<f32> {
    let volSize = volumeSize;
    let uvw = (vec3<f32>(voxel) + 0.5) / f32(volSize);  // center of voxel in [0,1]
    return uvw * 2.0 - 1.0;  // [0,1] -> [-1,1]
}

// Voxel hit result
struct VoxelHit {
    dist: f32,
    normal: vec3<f32>,
    voxel: vec3<i32>,
}

// DDA voxel traversal - returns hit distance and face normal
fn voxelTrace(ro: vec3<f32>, rd: vec3<f32>) -> VoxelHit {
    var result: VoxelHit;
    result.dist = -1.0;
    result.normal = vec3<f32>(0.0);
    result.voxel = vec3<i32>(0);

    let volSize = volumeSize;
    let voxelSize = 2.0 / f32(volSize);  // world-space size of one voxel

    // Ray-box intersection with the volume bounds [-1, 1]
    let invRd = 1.0 / rd;
    let t0 = (-1.0 - ro) * invRd;
    let t1 = (1.0 - ro) * invRd;
    let tminV = min(t0, t1);
    let tmaxV = max(t0, t1);
    let tEnter = max(max(tminV.x, tminV.y), tminV.z);
    let tExit = min(min(tmaxV.x, tmaxV.y), tmaxV.z);

    if (tEnter > tExit || tExit < 0.0) {
        return result;  // No intersection with volume
    }

    // Start position (slightly inside the volume)
    var tStart = max(tEnter + 0.001, 0.0);
    let pos = ro + rd * tStart;

    // Current voxel
    var voxel = worldToVoxel(pos);
    voxel = clamp(voxel, vec3<i32>(0), vec3<i32>(volSize - 1));

    // Step direction
    let step = vec3<i32>(sign(rd));

    // Distance to next voxel boundary in each axis
    let voxelBounds = voxelToWorld(voxel + max(step, vec3<i32>(0)));
    var tMaxVec = (voxelBounds - ro) * invRd;

    // Distance to cross one voxel in each axis
    let tDelta = abs(vec3<f32>(voxelSize) * invRd);

    // Traverse voxels
    var lastNormal = vec3<f32>(0.0);
    for (var i: i32 = 0; i < MAX_STEPS * 2; i = i + 1) {
        // Check if current voxel is solid
        if (voxel.x >= 0 && voxel.x < volSize &&
            voxel.y >= 0 && voxel.y < volSize &&
            voxel.z >= 0 && voxel.z < volSize) {

            if (isVoxelSolid(voxel)) {
                // Hit! 
                result.dist = tStart;
                result.normal = lastNormal;
                result.voxel = voxel;

                // If this is the first voxel, compute entry normal
                if (lastNormal.x == 0.0 && lastNormal.y == 0.0 && lastNormal.z == 0.0) {
                    if (tminV.x > tminV.y && tminV.x > tminV.z) {
                        result.normal = vec3<f32>(-sign(rd.x), 0.0, 0.0);
                    } else if (tminV.y > tminV.z) {
                        result.normal = vec3<f32>(0.0, -sign(rd.y), 0.0);
                    } else {
                        result.normal = vec3<f32>(0.0, 0.0, -sign(rd.z));
                    }
                }
                return result;
            }
        }

        // Step to next voxel (DDA)
        if (tMaxVec.x < tMaxVec.y) {
            if (tMaxVec.x < tMaxVec.z) {
                tStart = tMaxVec.x;
                tMaxVec.x = tMaxVec.x + tDelta.x;
                voxel.x = voxel.x + step.x;
                lastNormal = vec3<f32>(-f32(step.x), 0.0, 0.0);
            } else {
                tStart = tMaxVec.z;
                tMaxVec.z = tMaxVec.z + tDelta.z;
                voxel.z = voxel.z + step.z;
                lastNormal = vec3<f32>(0.0, 0.0, -f32(step.z));
            }
        } else {
            if (tMaxVec.y < tMaxVec.z) {
                tStart = tMaxVec.y;
                tMaxVec.y = tMaxVec.y + tDelta.y;
                voxel.y = voxel.y + step.y;
                lastNormal = vec3<f32>(0.0, -f32(step.y), 0.0);
            } else {
                tStart = tMaxVec.z;
                tMaxVec.z = tMaxVec.z + tDelta.z;
                voxel.z = voxel.z + step.z;
                lastNormal = vec3<f32>(0.0, 0.0, -f32(step.z));
            }
        }

        // Check if we've exited the volume
        if (tStart > tExit) { break; }
    }

    return result;
}

// Compute smooth normal using central differences on the SDF field
fn calcNormal(p: vec3<f32>) -> vec3<f32> {
    let eps = 2.0 / f32(volumeSize);

    let dx = getField(p + vec3<f32>(eps, 0.0, 0.0)) - getField(p - vec3<f32>(eps, 0.0, 0.0));
    let dy = getField(p + vec3<f32>(0.0, eps, 0.0)) - getField(p - vec3<f32>(0.0, eps, 0.0));
    let dz = getField(p + vec3<f32>(0.0, 0.0, eps)) - getField(p - vec3<f32>(0.0, 0.0, eps));

    var n = vec3<f32>(dx, dy, dz);

    let len = length(n);
    if (len < 0.0001) { return vec3<f32>(0.0, 1.0, 0.0); }

    return n / len;
}

// Isosurface hit result
struct IsoHit {
    dist: f32,
    pos: vec3<f32>,
    hit: bool,
}

// Analytic isosurface raymarching with bisection refinement
fn isosurfaceTrace(ro: vec3<f32>, rd: vec3<f32>) -> IsoHit {
    var result: IsoHit;
    result.hit = false;
    result.dist = -1.0;
    result.pos = vec3<f32>(0.0);

    let invRd = 1.0 / rd;
    let t0 = (-1.0 - ro) * invRd;
    let t1 = (1.0 - ro) * invRd;
    let tminV = min(t0, t1);
    let tmaxV = max(t0, t1);
    let tEnter = max(max(tminV.x, tminV.y), tminV.z);
    let tExit = min(min(tmaxV.x, tmaxV.y), tmaxV.z);

    if (tEnter > tExit || tExit < 0.0) { return result; }

    let tStart = max(tEnter, 0.0);
    let stepSize = 1.5 / f32(volumeSize);

    var t = tStart;
    var prevField = getField(ro + rd * t);

    // If we start inside solid (e.g., inverted volume), hit the bounding box surface
    if (prevField < 0.0) {
        result.hit = true;
        result.dist = tStart;
        result.pos = ro + rd * tStart;
        return result;
    }

    for (var i: i32 = 0; i < MAX_STEPS; i = i + 1) {
        t = t + stepSize;
        if (t > tExit) { break; }

        let p = ro + rd * t;
        let field = getField(p);

        if (prevField * field < 0.0) {
            var tLo = t - stepSize;
            var tHi = t;
            var pf = prevField;

            for (var j: i32 = 0; j < 8; j = j + 1) {
                let tMid = (tLo + tHi) * 0.5;
                let fMid = getField(ro + rd * tMid);

                if (pf * fMid < 0.0) {
                    tHi = tMid;
                } else {
                    tLo = tMid;
                    pf = fMid;
                }
            }

            result.hit = true;
            result.dist = (tLo + tHi) * 0.5;
            result.pos = ro + rd * result.dist;
            return result;
        }

        prevField = field;
    }

    return result;
}

// Shading for smooth isosurface
fn shade(p: vec3<f32>, rd: vec3<f32>) -> vec3<f32> {
    let n = calcNormal(p);
    let lightDir = normalize(vec3<f32>(1.0, 1.0, -1.0));

    let diff = max(dot(n, lightDir), 0.0);
    let amb: f32 = 0.15;

    let halfVec = normalize(lightDir - rd);
    let spec = pow(max(dot(n, halfVec), 0.0), 32.0);

    let rim = pow(1.0 - max(dot(n, -rd), 0.0), 3.0);

    // Use RGB from volume for coloring
    let volColor = sampleVolume(p);
    var baseColor = volColor.rgb;

    // If volume appears grayscale (R≈G≈B), use a neutral gray
    let colorVariance = length(volColor.rgb - vec3<f32>(volColor.r));
    if (colorVariance < 0.01) {
        baseColor = vec3<f32>(0.75);
    }

    return baseColor * (amb + diff * 0.7) + spec * 0.2 + rim * 0.15;
}

// Voxel shading with flat face normals
fn shadeVoxel(p: vec3<f32>, rd: vec3<f32>, n: vec3<f32>, voxel: vec3<i32>) -> vec3<f32> {
    let lightDir = normalize(vec3<f32>(1.0, 1.0, -1.0));

    let diff = max(dot(n, lightDir), 0.0);
    let amb: f32 = 0.3;

    // Use RGB from volume for coloring
    let volColor = sampleVoxel(voxel);
    var baseColor = volColor.rgb;

    // If volume appears grayscale, apply face-based shading variation
    let colorVariance = length(volColor.rgb - vec3<f32>(volColor.r));
    if (colorVariance < 0.01) {
        let faceShade = abs(n.x) * 0.9 + abs(n.y) * 1.0 + abs(n.z) * 0.85;
        baseColor = vec3<f32>(0.7 * faceShade);
    }

    return baseColor * (amb + diff * 0.7);
}

@fragment
fn main(@builtin(position) position: vec4<f32>) -> FragmentOutput {
    // Square face: uv in [-1,1], 90-degree frustum. Camera at the volume center,
    // looking out along the per-face basis (cubeBasis). Replaces render3d's orbit.
    var fullRes = select(resolution, fullResolution, fullResolution.x > 0.0);
    if (fullRes.x < 1.0) { fullRes = vec2<f32>(1024.0, 1024.0); }

    let uv = ((position.xy + tileOffset) - 0.5 * fullRes) / (0.5 * fullRes.y);
    let ro = vec3<f32>(0.0);
    let rd = normalize(cubeBasis * vec3<f32>(uv.x, -uv.y, 1.0));

    var color: vec3<f32>;
    var normal = vec3<f32>(0.0, 0.0, 1.0);
    var depth: f32 = 1.0;
    var alpha: f32 = 1.0;

    // FILTERING is a compile-time const; the optimizer eliminates the
    // unused raymarching path entirely.
    if (FILTERING == 1) {
        let hit = voxelTrace(ro, rd);
        if (hit.dist > 0.0) {
            let p = ro + rd * hit.dist;
            color = shadeVoxel(p, rd, hit.normal, hit.voxel);
            normal = hit.normal;
            depth = hit.dist / MAX_DIST;
        } else {
            color = bgColor;
            alpha = bgAlpha;
        }
    } else {
        let hit = isosurfaceTrace(ro, rd);
        if (hit.hit) {
            color = shade(hit.pos, rd);
            normal = calcNormal(hit.pos);
            depth = hit.dist / MAX_DIST;
        } else {
            color = bgColor;
            alpha = bgAlpha;
        }
    }

    color = pow(color, vec3<f32>(1.0 / 2.2));

    var output: FragmentOutput;
    output.color = vec4<f32>(color, alpha);
    output.geoOut = vec4<f32>(normal * 0.5 + 0.5, depth);
    return output;
}

/*
 * Cubemap surface sampler (WGSL) — renderCubemapSurface
 *
 * Samples a 3D volume (inputTex3d) along the per-face cube camera rays and shows
 * the RAW, TRUE color of the field exactly as sampled — front-to-back
 * emission/absorption, with NO lighting and NO gamma. (The lit isosurface/voxel
 * "blob in space" view lives in the sibling renderCubemap3d.)
 *
 * The volume's red channel drives per-step opacity; RGB is the emitted color.
 */

@group(0) @binding(0) var<uniform> resolution: vec2<f32>;
@group(0) @binding(1) var<uniform> volumeSize: i32;
@group(0) @binding(2) var<uniform> cubeBasis: mat3x3<f32>;
@group(0) @binding(3) var<uniform> bgColor: vec3<f32>;
@group(0) @binding(4) var<uniform> bgAlpha: f32;
@group(0) @binding(5) var volumeCache: texture_2d<f32>;
@group(0) @binding(6) var<uniform> tileOffset: vec2<f32>;
@group(0) @binding(7) var<uniform> fullResolution: vec2<f32>;
@group(0) @binding(8) var<uniform> density: f32;
@group(0) @binding(9) var<uniform> absorption: f32;
@group(0) @binding(10) var<uniform> emission: f32;

const MAX_STEPS: i32 = 256;

// MRT output structure for color and geometry buffer
struct FragmentOutput {
    @location(0) color: vec4<f32>,
    @location(1) geoOut: vec4<f32>,
}

// Convert 3D volume coordinates to 2D atlas texel coordinates
fn volumeToAtlas(x: i32, y: i32, z: i32, volSize: i32) -> vec2<i32> {
    return vec2<i32>(x, y + z * volSize);
}

// Sample the cached 3D volume with trilinear interpolation
// World position p is in [-1, 1]^3 (bounding box coordinates)
fn sampleVolume(worldPos: vec3<f32>) -> vec4<f32> {
    let volSize = volumeSize;
    let volSizeF = f32(volSize);

    // Convert world position [-1, 1] to normalized volume coords [0, 1]
    var uvw = worldPos * 0.5 + 0.5;
    uvw = clamp(uvw, vec3<f32>(0.0), vec3<f32>(1.0));

    // Convert to texel coordinates
    let texelPos = uvw * (volSizeF - 1.0);
    let texelFloor = floor(texelPos);
    let frac = texelPos - texelFloor;

    let i0 = vec3<i32>(texelFloor);
    let i1 = min(i0 + 1, vec3<i32>(volSize - 1));

    // Trilinear filtering - load 8 corners
    let c000 = textureLoad(volumeCache, volumeToAtlas(i0.x, i0.y, i0.z, volSize), 0);
    let c100 = textureLoad(volumeCache, volumeToAtlas(i1.x, i0.y, i0.z, volSize), 0);
    let c010 = textureLoad(volumeCache, volumeToAtlas(i0.x, i1.y, i0.z, volSize), 0);
    let c110 = textureLoad(volumeCache, volumeToAtlas(i1.x, i1.y, i0.z, volSize), 0);
    let c001 = textureLoad(volumeCache, volumeToAtlas(i0.x, i0.y, i1.z, volSize), 0);
    let c101 = textureLoad(volumeCache, volumeToAtlas(i1.x, i0.y, i1.z, volSize), 0);
    let c011 = textureLoad(volumeCache, volumeToAtlas(i0.x, i1.y, i1.z, volSize), 0);
    let c111 = textureLoad(volumeCache, volumeToAtlas(i1.x, i1.y, i1.z, volSize), 0);

    // Trilinear interpolation
    let c00 = mix(c000, c100, frac.x);
    let c10 = mix(c010, c110, frac.x);
    let c01 = mix(c001, c101, frac.x);
    let c11 = mix(c011, c111, frac.x);

    let c0 = mix(c00, c10, frac.y);
    let c1 = mix(c01, c11, frac.y);

    return mix(c0, c1, frac.z);
}

// Ray-box intersection against [-1,1]^3. Returns vec2(tEnter, tExit).
// tb.y < 0 or tb.x > tb.y means no intersection.
fn intersectBox(ro: vec3<f32>, rd: vec3<f32>) -> vec2<f32> {
    let invRd = 1.0 / rd;
    let t0 = (-1.0 - ro) * invRd;
    let t1 = (1.0 - ro) * invRd;
    let tmin = min(t0, t1);
    let tmax = max(t0, t1);
    let tEnter = max(max(tmin.x, tmin.y), tmin.z);
    let tExit = min(min(tmax.x, tmax.y), tmax.z);
    if (tEnter > tExit || tExit < 0.0) {
        return vec2<f32>(-1.0);
    }
    return vec2<f32>(tEnter, tExit);
}

@fragment
fn main(@builtin(position) position: vec4<f32>) -> FragmentOutput {
    // Square face: uv in [-1, 1], 90-degree frustum. Camera at the volume center.
    let res = select(resolution, fullResolution, fullResolution.x > 0.0);
    let uv = ((position.xy + tileOffset) - 0.5 * res) / (0.5 * res.y);
    let ro = vec3<f32>(0.0, 0.0, 0.0);
    let rd = normalize(cubeBasis * vec3<f32>(uv.x, -uv.y, 1.0));

    // Front-to-back emission/absorption. NO gamma, NO lighting: the raw field
    // color shows through exactly as sampled.
    var col = vec3<f32>(0.0);
    var trans = 1.0;
    let tb = intersectBox(ro, rd);
    if (tb.y > 0.0) {
        let t0 = max(tb.x, 0.0);
        let dt = (tb.y - t0) / f32(MAX_STEPS);
        var t = t0;
        for (var i = 0; i < MAX_STEPS; i = i + 1) {
            let s = sampleVolume(ro + rd * t);
            let a = 1.0 - exp(-s.r * density * absorption * dt);
            col = col + trans * a * s.rgb * emission;
            trans = trans * (1.0 - a);
            if (trans < 0.01) { break; }
            t = t + dt;
        }
    }
    let outc = col + bgColor * trans;
    var output: FragmentOutput;
    output.color = vec4<f32>(outc, 1.0 - trans + bgAlpha * trans);
    output.geoOut = vec4<f32>(0.5, 0.5, 0.5, 1.0);
    return output;
}

struct Uniforms {
    resolution: vec2f,
    tileOffset: vec2f,
    fullResolution: vec2f,
    volumeSize: i32,
    threshold: f32,
    zoom: f32,
    panX: f32,
    panY: f32,
    ambient: f32,
    lightDirection: vec3f,
    diffuseIntensity: f32,
    bgColor: vec3f,
    specularIntensity: f32,
    bgAlpha: f32,
    rotateX: f32,
    rotateY: f32,
    rotateZ: f32,
    viewScale: f32,
    posX: f32,
    posY: f32,
    posZ: f32,
    fieldOfView: f32,
}
@group(0) @binding(0) var<uniform> u: Uniforms;
@group(0) @binding(1) var volumeCache: texture_2d<f32>;
@group(0) @binding(2) var analyticalGeo: texture_2d<f32>;

struct FragmentOutput {
    @location(0) fragColor: vec4f,
    @location(1) geoOut: vec4f,
}

fn lighting(color: vec3f, normal: vec3f, viewDirection: vec3f) -> vec3f {
    var light = vec3f(0.0, 1.0, 0.0);
    if (dot(u.lightDirection, u.lightDirection) > 0.000001) { light = normalize(u.lightDirection); }
    let halfVector = light + viewDirection;
    var specular = 0.0;
    if (dot(halfVector, halfVector) > 0.000001) {
        specular = pow(max(dot(normal, normalize(halfVector)), 0.0), 32.0) * u.specularIntensity;
    }
    return color * (u.ambient + max(dot(normal, light), 0.0) * u.diffuseIntensity) + specular;
}

// Filter voxel-center coordinates explicitly, avoiding unrelated atlas rows.
fn sampleAtlasTexel(atlas: texture_2d<f32>, p: vec3i, material: bool) -> vec4f {
    let coord = vec2i(p.x, p.y + p.z * u.volumeSize);
    let value = textureLoad(atlas, coord, 0);
    if (material) {
        // Geometry defines empty samples. Volume alpha can hold unrelated data.
        let present = select(0.0, 1.0, textureLoad(analyticalGeo, coord, 0).a > 0.0);
        return vec4f(value.rgb * present, present);
    }
    return value;
}

// Preserve constant fields exactly so flat surfaces have zero tangential gradient.
fn interpolateAtlas(a: vec4f, b: vec4f, weight: f32) -> vec4f {
    return a + (b - a) * weight;
}

struct AtlasCoords {
    lo: vec3i,
    fraction: vec3f,
}

fn atlasCoords(p: vec3f) -> AtlasCoords {
    let texel = clamp(p - 0.5, vec3f(0.0), vec3f(f32(u.volumeSize - 1)));
    return AtlasCoords(vec3i(floor(texel)), fract(texel));
}

fn sampleAtlasCoords(atlas: texture_2d<f32>, coords: AtlasCoords, material: bool) -> vec4f {
    let lo = coords.lo;
    let hi = min(lo + 1, vec3i(u.volumeSize - 1));
    let f = coords.fraction;
    let c00 = interpolateAtlas(sampleAtlasTexel(atlas, vec3i(lo.x, lo.y, lo.z), material),
                  sampleAtlasTexel(atlas, vec3i(hi.x, lo.y, lo.z), material), f.x);
    let c10 = interpolateAtlas(sampleAtlasTexel(atlas, vec3i(lo.x, hi.y, lo.z), material),
                  sampleAtlasTexel(atlas, vec3i(hi.x, hi.y, lo.z), material), f.x);
    let c01 = interpolateAtlas(sampleAtlasTexel(atlas, vec3i(lo.x, lo.y, hi.z), material),
                  sampleAtlasTexel(atlas, vec3i(hi.x, lo.y, hi.z), material), f.x);
    let c11 = interpolateAtlas(sampleAtlasTexel(atlas, vec3i(lo.x, hi.y, hi.z), material),
                  sampleAtlasTexel(atlas, vec3i(hi.x, hi.y, hi.z), material), f.x);
    let value = interpolateAtlas(interpolateAtlas(c00, c10, f.y), interpolateAtlas(c01, c11, f.y), f.z);
    if (material && value.a > 0.0) { return vec4f(value.rgb / value.a, value.a); }
    return value;
}

fn sampleAtlas(atlas: texture_2d<f32>, p: vec3f, material: bool) -> vec4f {
    return sampleAtlasCoords(atlas, atlasCoords(p), material);
}

fn isSolid(coords: AtlasCoords) -> bool {
    let density = sampleAtlasCoords(analyticalGeo, coords, false).a;
    return density > 0.0 && density >= u.threshold;
}

struct IsoHit {
    distance: f32,
    position: vec3f,
    coords: AtlasCoords,
}

fn traceIsosurface(origin: vec3f, direction: vec3f, start: f32, leave: f32) -> IsoHit {
    var position = origin + direction * start;
    var coords = atlasCoords(position);
    if (isSolid(coords)) { return IsoHit(start, position, coords); }
    // Half-voxel steps cover the entire box, including long diagonal rays.
    let stepSize = 0.5 / length(direction);
    var previous = start;
    for (var step = 0; step < u.volumeSize * 4; step++) {
        let distance = min(previous + stepSize, leave);
        position = origin + direction * distance;
        coords = atlasCoords(position);
        if (isSolid(coords)) {
            var lo = previous;
            var hi = distance;
            for (var refine = 0; refine < 8; refine++) {
                let mid = (lo + hi) * 0.5;
                let candidate = origin + direction * mid;
                let candidateCoords = atlasCoords(candidate);
                if (isSolid(candidateCoords)) {
                    hi = mid;
                    position = candidate;
                    coords = candidateCoords;
                } else { lo = mid; }
            }
            // Reuse the tested interpolation coordinates for material sampling.
            // Recomputing them from position can round onto the empty boundary.
            return IsoHit(hi, position, coords);
        }
        if (distance >= leave) { break; }
        previous = distance;
    }
    return IsoHit(-1.0, vec3f(0.0), AtlasCoords(vec3i(0), vec3f(0.0)));
}

fn isosurfaceNormal(p: vec3f, fallback: vec3f) -> vec3f {
    let gradient = vec3f(
        sampleAtlas(analyticalGeo, p - vec3f(0.5, 0.0, 0.0), false).a - sampleAtlas(analyticalGeo, p + vec3f(0.5, 0.0, 0.0), false).a,
        sampleAtlas(analyticalGeo, p - vec3f(0.0, 0.5, 0.0), false).a - sampleAtlas(analyticalGeo, p + vec3f(0.0, 0.5, 0.0), false).a,
        sampleAtlas(analyticalGeo, p - vec3f(0.0, 0.0, 0.5), false).a - sampleAtlas(analyticalGeo, p + vec3f(0.0, 0.0, 0.5), false).a);
    if (dot(gradient, gradient) > 1e-12) { return normalize(gradient); }
    return fallback;
}

// Inverse of the billboard renderer's X -> Y -> Z rotation.
fn inverseRotation(input: vec3f) -> vec3f {
    let c = cos(vec3f(u.rotateX, u.rotateY, u.rotateZ));
    let s = sin(vec3f(u.rotateX, u.rotateY, u.rotateZ));
    var p = vec3f(input.x * c.z + input.y * s.z, -input.x * s.z + input.y * c.z, input.z);
    p = vec3f(p.x * c.y - p.z * s.y, p.y, p.x * s.y + p.z * c.y);
    return vec3f(p.x, p.y * c.x + p.z * s.x, -p.y * s.x + p.z * c.x);
}

fn forwardRotation(input: vec3f) -> vec3f {
    let c = cos(vec3f(u.rotateX, u.rotateY, u.rotateZ));
    let s = sin(vec3f(u.rotateX, u.rotateY, u.rotateZ));
    var p = vec3f(input.x, input.y * c.x - input.z * s.x, input.y * s.x + input.z * c.x);
    p = vec3f(p.x * c.y + p.z * s.y, p.y, -p.x * s.y + p.z * c.y);
    return vec3f(p.x * c.z - p.y * s.z, p.x * s.z + p.y * c.z, p.z);
}

fn renderPerspective(uv: vec2f) -> FragmentOutput {
    var out: FragmentOutput;
    out.fragColor = vec4f(u.bgColor * u.bgAlpha, u.bgAlpha);
    out.geoOut = vec4f(0.5, 0.5, 1.0, 1.0);
    let size = f32(u.volumeSize);
    let focalLength = 1.0 / tan(clamp(u.fieldOfView, 10.0, 150.0) * 0.00872664626);
    // The volume spans [-40,40]. Position follows rotation; camera Z is 80.
    let origin = (inverseRotation(vec3f(-u.posX, -u.posY, 80.0 - u.posZ)) / 80.0 + 0.5) * size;
    let framedUv = (uv + vec2f(u.panX, u.panY)) / max(u.zoom, 0.001);
    let cameraRay = vec3f(framedUv * 2.0 / (focalLength * max(u.viewScale, 0.001)), -1.0);
    let direction = inverseRotation(cameraRay) * (size / 80.0);
    var nearT = vec3f(-1e30);
    var farT = vec3f(1e30);
    var delta = vec3f(1e30);
    var stepDir = vec3i(0);
    for (var axis = 0; axis < 3; axis++) {
        if (abs(direction[axis]) < 1e-8) {
            if (origin[axis] < 0.0 || origin[axis] >= size) { return out; }
        } else {
            let a = -origin[axis] / direction[axis];
            let b = (size - origin[axis]) / direction[axis];
            nearT[axis] = min(a, b);
            farT[axis] = max(a, b);
            delta[axis] = 1.0 / abs(direction[axis]);
            stepDir[axis] = select(-1, 1, direction[axis] > 0.0);
        }
    }
    let enter = max(max(nearT.x, nearT.y), nearT.z);
    let leave = min(min(farT.x, farT.y), farT.z);
    var distance = max(enter, 0.1);
    if (distance >= leave) { return out; }
    var cell = clamp(vec3i(floor(origin + direction * distance + vec3f(stepDir) * 0.0001)), vec3i(0), vec3i(u.volumeSize - 1));
    var nextT = vec3f(1e30);
    for (var axis = 0; axis < 3; axis++) {
        if (stepDir[axis] != 0) {
            let boundary = f32(cell[axis]) + select(0.0, 1.0, stepDir[axis] > 0);
            nextT[axis] = (boundary - origin[axis]) / direction[axis];
        }
    }
    let viewDirection = normalize(-cameraRay);
    var normal = normalize(-direction);
    if (enter >= 0.1) {
        normal = vec3f(0.0);
        if (nearT.y >= nearT.x && nearT.y >= nearT.z) { normal.y = -f32(stepDir.y); }
        else if (nearT.x >= nearT.z) { normal.x = -f32(stepDir.x); }
        else { normal.z = -f32(stepDir.z); }
    }
    // FILTERING is a module constant; the compiler removes the inactive path.
    if (FILTERING == 0) {
        let hit = traceIsosurface(origin, direction, distance, leave);
        if (hit.distance < 0.0) { return out; }
        let p = hit.position;
        if (hit.distance > distance) { normal = isosurfaceNormal(p, normal); }
        let worldNormal = forwardRotation(normal);
        out.fragColor = vec4f(lighting(sampleAtlasCoords(volumeCache, hit.coords, true).rgb, worldNormal, viewDirection), 1.0);
        out.geoOut = vec4f(worldNormal * 0.5 + 0.5, clamp(hit.distance / 320.0, 0.0, 1.0));
        return out;
    }
    for (var step = 0; step < u.volumeSize * 3; step++) {
        if (any(cell < vec3i(0)) || any(cell >= vec3i(u.volumeSize)) || distance >= leave) { break; }
        let atlas = vec2i(cell.x, cell.y + cell.z * u.volumeSize);
        let density = textureLoad(analyticalGeo, atlas, 0).a;
        if (density > 0.0 && density >= u.threshold) {
            let worldNormal = forwardRotation(normal);
            out.fragColor = vec4f(lighting(textureLoad(volumeCache, atlas, 0).rgb, worldNormal, viewDirection), 1.0);
            out.geoOut = vec4f(worldNormal * 0.5 + 0.5, clamp(distance / 320.0, 0.0, 1.0));
            return out;
        }
        distance = min(min(nextT.x, nextT.y), nextT.z);
        let crossed = nextT <= vec3f(distance);
        normal = vec3f(0.0);
        if (crossed.y) { normal.y = -f32(stepDir.y); }
        else if (crossed.x) { normal.x = -f32(stepDir.x); }
        else { normal.z = -f32(stepDir.z); }
        cell += select(vec3i(0), vec3i(1), crossed) * stepDir;
        nextT += select(vec3f(0.0), vec3f(1.0), crossed) * delta;
    }
    return out;
}

@fragment
fn main(@builtin(position) position: vec4f) -> FragmentOutput {
    var out: FragmentOutput;
    out.fragColor = vec4f(u.bgColor * u.bgAlpha, u.bgAlpha);
    out.geoOut = vec4f(0.5, 0.5, 1.0, 1.0);
    let fullRes = select(u.resolution, u.fullResolution, u.fullResolution.x > 0.0);
    let uv = (position.xy + u.tileOffset - fullRes * 0.5) / fullRes.y;
    // VIEW_MODE is a module constant; the compiler removes the inactive path.
    if (VIEW_MODE == 2) { return renderPerspective(uv); }
    let size = f32(u.volumeSize);
    let aspect = fullRes.x / fullRes.y;
    let span = max(1.6329931619, 1.4142135624 / aspect) * size * 1.08 / max(u.zoom, 0.001);
    let right = vec3f(0.7071067812, 0.0, -0.7071067812);
    let up = vec3f(-0.4082482905, 0.8164965809, -0.4082482905);
    let origin = vec3f(size * 2.5) + right * (uv.x + u.panX) * span + up * (uv.y + u.panY) * span;

    let nearT = origin - size;
    let enter = max(max(nearT.x, nearT.y), nearT.z);
    let leave = min(min(origin.x, origin.y), origin.z);
    if (enter >= leave) { return out; }
    var distance = max(enter, 0.0);
    var cell = clamp(vec3i(floor(origin - (distance + 0.0001))), vec3i(0), vec3i(u.volumeSize - 1));
    var nextT = origin - vec3f(cell);
    var normal = vec3f(0.0, 0.0, 1.0);
    if (nearT.y >= nearT.x && nearT.y >= nearT.z) { normal = vec3f(0.0, 1.0, 0.0); }
    else if (nearT.x >= nearT.z) { normal = vec3f(1.0, 0.0, 0.0); }

    if (FILTERING == 0) {
        let hit = traceIsosurface(origin, vec3f(-1.0), distance, leave);
        if (hit.distance < 0.0) { return out; }
        let p = hit.position;
        if (hit.distance > distance) { normal = isosurfaceNormal(p, normal); }
        out.fragColor = vec4f(lighting(sampleAtlasCoords(volumeCache, hit.coords, true).rgb, normal, vec3f(0.5773502692)), 1.0);
        out.geoOut = vec4f(normal * 0.5 + 0.5, clamp(hit.distance / (size * 4.0), 0.0, 1.0));
        return out;
    }
    for (var step = 0; step < u.volumeSize * 3; step++) {
        if (any(cell < vec3i(0)) || distance >= leave) { break; }
        let atlas = vec2i(cell.x, cell.y + cell.z * u.volumeSize);
        let density = textureLoad(analyticalGeo, atlas, 0).a;
        if (density > 0.0 && density >= u.threshold) {
            let color = textureLoad(volumeCache, atlas, 0).rgb;
            out.fragColor = vec4f(lighting(color, normal, vec3f(0.5773502692)), 1.0);
            out.geoOut = vec4f(normal * 0.5 + 0.5, clamp(distance / (size * 4.0), 0.0, 1.0));
            return out;
        }
        distance = min(min(nextT.x, nextT.y), nextT.z);
        let crossed = nextT <= vec3f(distance);
        if (crossed.y) { normal = vec3f(0.0, 1.0, 0.0); }
        else if (crossed.x) { normal = vec3f(1.0, 0.0, 0.0); }
        else { normal = vec3f(0.0, 0.0, 1.0); }
        cell -= select(vec3i(0), vec3i(1), crossed);
        nextT += select(vec3f(0.0), vec3f(1.0), crossed);
    }
    return out;
}

/*
 * Universal 3D volume renderer with advanced lighting (WGSL)
 * 
 * Raymarches through a 3D volume texture to find isosurfaces,
 * with configurable bounding shapes and Blinn-Phong lighting.
 * 
 * Bounding shapes: cube, sphere
 * Lighting: diffuse, specular, ambient, rim
 */

// Uniforms struct with explicit padding to match std140 layout
// Field names MUST match definition.js uniform names exactly
struct Uniforms {
    // Built-in globals - vec2f has 8-byte align
    resolution: vec2f,    // offset 0, size 8
    time: f32,            // offset 8, size 4
    threshold: f32,       // offset 12, size 4
    // i32 scalars can be packed sequentially (4-byte align each)
    volumeSize: i32,      // offset 16, size 4
    invert: i32,          // offset 20, size 4  
    shape: i32,           // offset 24, size 4
    orbitSpeed: i32,      // offset 28, size 4
    // vec3f has 16-byte align, so cameraPosition starts at offset 32
    cameraPosition: vec3f,   // offset 32, size 12
    // bgAlpha can fit after cameraPosition
    bgAlpha: f32,         // offset 44, size 4
    // Next vec3f must align to 16 bytes -> offset 48
    bgColor: vec3f,       // offset 48, size 12
    diffuseIntensity: f32,   // offset 60, size 4
    // Next vec3f must align to 16 bytes -> offset 64
    lightDirection: vec3f,   // offset 64, size 12
    specularIntensity: f32,  // offset 76, size 4
    // Next vec3f must align to 16 bytes -> offset 80
    diffuseColor: vec3f,     // offset 80, size 12
    shininess: f32,          // offset 92, size 4
    // Next vec3f must align to 16 bytes -> offset 96
    specularColor: vec3f,    // offset 96, size 12
    rimIntensity: f32,       // offset 108, size 4
    // Next vec3f must align to 16 bytes -> offset 112
    ambientColor: vec3f,     // offset 112, size 12
    rimPower: f32,           // offset 124, size 4
    // Next vec2f aligns to 8 bytes -> offset 128
    tileOffset: vec2f,       // offset 128, size 8
    fullResolution: vec2f,   // offset 136, size 8
    // Struct size: 144 bytes (16-byte aligned)
}

@group(0) @binding(0) var<uniform> u: Uniforms;
@group(0) @binding(1) var volumeCache: texture_2d<f32>;

struct VertexOutput {
    @builtin(position) position: vec4f,
    @location(0) uv: vec2f,
}

@vertex
fn vertexMain(@builtin(vertex_index) vertexIndex: u32) -> VertexOutput {
    // Fullscreen triangle - 3 vertices that cover the entire screen when clipped
    let positions = array<vec2f, 3>(
        vec2f(-1.0, -1.0),
        vec2f(3.0, -1.0),
        vec2f(-1.0, 3.0)
    );
    let pos = positions[vertexIndex];
    var output: VertexOutput;
    output.position = vec4f(pos, 0.0, 1.0);
    output.uv = pos * 0.5 + 0.5;
    return output;
}

struct FragmentOutput {
    @location(0) color: vec4f,
    @location(1) geo: vec4f,
}

const TAU: f32 = 6.283185307179586;
const PI: f32 = 3.141592653589793;
const MAX_STEPS: i32 = 256;
const MAX_DIST: f32 = 10.0;
const NEAR_CLIP: f32 = 0.01;

// Helper to convert 3D texel coords to 2D atlas texel coords
fn atlasTexel(p: vec3i, volSize: i32) -> vec2i {
    return vec2i(p.x, p.y + p.z * volSize);
}

// Sample the cached 3D volume with trilinear interpolation
fn sampleVolume(worldPos: vec3f) -> vec4f {
    let volSize = u.volumeSize;
    let volSizeF = f32(volSize);

    // Convert world position [-1, 1] to normalized volume coords [0, 1]
    var uvw = worldPos * 0.5 + 0.5;
    uvw = clamp(uvw, vec3f(0.0), vec3f(1.0));

    // Convert to texel coordinates
    let texelPos = uvw * (volSizeF - 1.0);
    let texelFloor = floor(texelPos);
    let frac = texelPos - texelFloor;

    let i0 = vec3i(texelFloor);
    let i1 = min(i0 + 1, vec3i(volSize - 1));

    // Trilinear filtering - sample all 8 corners
    let c000 = textureLoad(volumeCache, atlasTexel(vec3i(i0.x, i0.y, i0.z), volSize), 0);
    let c100 = textureLoad(volumeCache, atlasTexel(vec3i(i1.x, i0.y, i0.z), volSize), 0);
    let c010 = textureLoad(volumeCache, atlasTexel(vec3i(i0.x, i1.y, i0.z), volSize), 0);
    let c110 = textureLoad(volumeCache, atlasTexel(vec3i(i1.x, i1.y, i0.z), volSize), 0);
    let c001 = textureLoad(volumeCache, atlasTexel(vec3i(i0.x, i0.y, i1.z), volSize), 0);
    let c101 = textureLoad(volumeCache, atlasTexel(vec3i(i1.x, i0.y, i1.z), volSize), 0);
    let c011 = textureLoad(volumeCache, atlasTexel(vec3i(i0.x, i1.y, i1.z), volSize), 0);
    let c111 = textureLoad(volumeCache, atlasTexel(vec3i(i1.x, i1.y, i1.z), volSize), 0);

    // Trilinear interpolation
    let c00 = mix(c000, c100, frac.x);
    let c10 = mix(c010, c110, frac.x);
    let c01 = mix(c001, c101, frac.x);
    let c11 = mix(c011, c111, frac.x);

    let c0 = mix(c00, c10, frac.y);
    let c1 = mix(c01, c11, frac.y);

    return mix(c0, c1, frac.z);
}

// Get the scalar field value at a point
fn getField(p: vec3f) -> f32 {
    var val = sampleVolume(p).r;
    if (u.invert == 1) {
        val = 1.0 - val;
    }
    return u.threshold - val;
}

// Compute smooth normal using central differences
fn calcNormal(p: vec3f) -> vec3f {
    let eps = 2.0 / f32(u.volumeSize);

    let dx = getField(p + vec3f(eps, 0.0, 0.0)) - getField(p - vec3f(eps, 0.0, 0.0));
    let dy = getField(p + vec3f(0.0, eps, 0.0)) - getField(p - vec3f(0.0, eps, 0.0));
    let dz = getField(p + vec3f(0.0, 0.0, eps)) - getField(p - vec3f(0.0, 0.0, eps));

    let n = vec3f(dx, dy, dz);
    let len = length(n);
    if (len < 0.0001) {
        return vec3f(0.0, 1.0, 0.0);
    }

    return n / len;
}

// Compute outward normal for bounding shape at position p
fn calcBoundaryNormal(p: vec3f) -> vec3f {
    if (u.shape == 0) {
        // Cube: normal points outward from nearest face
        let absP = abs(p);
        if (absP.x > absP.y && absP.x > absP.z) {
            return vec3f(sign(p.x), 0.0, 0.0);
        } else if (absP.y > absP.z) {
            return vec3f(0.0, sign(p.y), 0.0);
        } else {
            return vec3f(0.0, 0.0, sign(p.z));
        }
    } else {
        // Sphere: normal is just the normalized position
        return normalize(p);
    }
}

// Ray-box intersection (cube shape)
fn intersectBox(ro: vec3f, rd: vec3f) -> vec2f {
    let invRd = 1.0 / rd;
    let t0 = (-1.0 - ro) * invRd;
    let t1 = (1.0 - ro) * invRd;
    let tmin = min(t0, t1);
    let tmax = max(t0, t1);
    let tEnter = max(max(tmin.x, tmin.y), tmin.z);
    let tExit = min(min(tmax.x, tmax.y), tmax.z);

    if (tEnter > tExit || tExit < 0.0) {
        return vec2f(-1.0);
    }
    return vec2f(tEnter, tExit);
}

// Ray-sphere intersection (radius 1 centered at origin)
fn intersectSphere(ro: vec3f, rd: vec3f) -> vec2f {
    let b = dot(ro, rd);
    let c = dot(ro, ro) - 1.0;
    let disc = b * b - c;

    if (disc < 0.0) {
        return vec2f(-1.0);
    }

    let sqrtDisc = sqrt(disc);
    let tEnter = -b - sqrtDisc;
    let tExit = -b + sqrtDisc;

    if (tExit < 0.0) {
        return vec2f(-1.0);
    }
    return vec2f(tEnter, tExit);
}

// Get ray bounds based on selected shape
fn getRayBounds(ro: vec3f, rd: vec3f) -> vec2f {
    var t: vec2f;

    if (u.shape == 0) {
        t = intersectBox(ro, rd);
    } else {
        t = intersectSphere(ro, rd);
    }

    if (t.x < 0.0 && t.y < 0.0) {
        return vec2f(-1.0);
    }

    // Apply near clip (handles camera inside volume)
    t.x = max(t.x, NEAR_CLIP);

    return t;
}

// Isosurface hit result
struct IsoHit {
    dist: f32,
    pos: vec3f,
    hit: bool,
    atBoundary: bool,  // true if hit at bounding shape edge, not isosurface
}

// Raymarching with bisection refinement
fn raymarch(ro: vec3f, rd: vec3f) -> IsoHit {
    var result: IsoHit;
    result.hit = false;
    result.dist = -1.0;
    result.pos = vec3f(0.0);
    result.atBoundary = false;

    let bounds = getRayBounds(ro, rd);
    if (bounds.x < 0.0) {
        return result;
    }

    let tStart = bounds.x;
    let tEnd = bounds.y;

    // Step size based on volume resolution
    let stepSize = 1.5 / f32(u.volumeSize);

    // March through volume
    var t = tStart;
    var prevField = getField(ro + rd * t);

    // If we start inside solid, hit immediately at boundary
    if (prevField < 0.0) {
        result.hit = true;
        result.dist = tStart;
        result.pos = ro + rd * tStart;
        result.atBoundary = true;
        return result;
    }

    for (var i = 0; i < MAX_STEPS; i++) {
        t += stepSize;
        if (t > tEnd) {
            break;
        }

        let p = ro + rd * t;

        // For bounded shapes, check if still in bounds
        if (u.shape == 0) {
            // Cube bounds check
            if (any(p < vec3f(-1.0)) || any(p > vec3f(1.0))) {
                break;
            }
        } else if (u.shape == 1) {
            // Sphere bounds check
            if (dot(p, p) > 1.0) {
                break;
            }
        }

        let field = getField(p);

        // Check for sign change (threshold crossing)
        if (prevField * field < 0.0) {
            // Found crossing - refine with bisection
            var tLo = t - stepSize;
            var tHi = t;
            var bisectPrevField = prevField;

            for (var j = 0; j < 8; j++) {
                let tMid = (tLo + tHi) * 0.5;
                let fMid = getField(ro + rd * tMid);

                if (bisectPrevField * fMid < 0.0) {
                    tHi = tMid;
                } else {
                    tLo = tMid;
                    bisectPrevField = fMid;
                }
            }

            result.hit = true;
            result.dist = (tLo + tHi) * 0.5;
            result.pos = ro + rd * result.dist;
            return result;
        }

        prevField = field;
    }

    return result;
}

// Advanced lighting calculation
fn applyLighting(baseColor: vec3f, n_in: vec3f, rd: vec3f, worldLightDir: vec3f) -> vec3f {
    let lightDir = normalize(worldLightDir);
    let viewDir = -rd;

    // Ensure normal faces the camera
    var n = n_in;
    if (dot(n, viewDir) < 0.0) {
        n = -n;
    }

    // Ambient lighting
    let ambient = u.ambientColor * baseColor;

    // Diffuse lighting (Lambertian)
    let diffuseFactor = max(dot(n, lightDir), 0.0);
    let diffuse = u.diffuseColor * diffuseFactor * baseColor * u.diffuseIntensity;

    // Specular lighting (Blinn-Phong)
    let halfDir = normalize(lightDir + viewDir);
    let specAngle = max(dot(halfDir, n), 0.0);
    let specularFactor = pow(specAngle, u.shininess);
    let specular = u.specularColor * specularFactor * u.specularIntensity;

    // Fresnel rim lighting
    let rim = pow(1.0 - max(dot(n, viewDir), 0.0), u.rimPower);
    let rimLight = vec3f(rim) * u.rimIntensity;

    return ambient + diffuse + specular + rimLight;
}

// Shading - uses RGB from volume for coloring
fn shade(p: vec3f, n: vec3f, rd: vec3f, worldLightDir: vec3f) -> vec3f {
    let volColor = sampleVolume(p);
    var baseColor = volColor.rgb;

    // If volume appears grayscale, use neutral gray
    let colorVariance = length(volColor.rgb - vec3f(volColor.r));
    if (colorVariance < 0.01) {
        baseColor = vec3f(0.75);
    }

    return applyLighting(baseColor, n, rd, worldLightDir);
}

@fragment
fn fragmentMain(input: VertexOutput) -> FragmentOutput {
    var fullRes = select(u.resolution, u.fullResolution, u.fullResolution.x > 0.0);
    if (fullRes.x < 1.0) {
        fullRes = vec2f(1024.0, 1024.0);
    }

    let fragCoord = input.position.xy;
    let uv = ((fragCoord + u.tileOffset) - 0.5 * fullRes) / fullRes.y;

    // Camera setup - fixed position, volume rotates
    // Scale camera position from 0-1 UI range to world coords
    let ro = u.cameraPosition * vec3f(-1.0, 1.0, 1.0) * 3.5;

    // Camera looks at origin; handle case when at origin
    var forward: vec3f;
    if (length(ro) < 0.001) {
        forward = vec3f(0.0, 0.0, -1.0);  // Default: look into volume
    } else {
        forward = normalize(-ro);  // Look toward origin
    }
    var worldUp = vec3f(0.0, 1.0, 0.0);
    // Handle looking straight up/down
    if (abs(dot(forward, worldUp)) > 0.999) {
        worldUp = vec3f(0.0, 0.0, 1.0);
    }
    let right = normalize(cross(worldUp, forward));
    let up = cross(forward, right);

    let rd = normalize(forward + uv.x * right + uv.y * up);

    // Light direction is fixed in world space (not view space)
    let worldLightDir = normalize(u.lightDirection * vec3f(-1.0, 1.0, 1.0));

    // Rotate ray into volume space
    let angle = u.time * TAU * f32(u.orbitSpeed);
    let c = cos(angle);
    let s = sin(angle);
    // Rotation around Y axis
    let roVol = vec3f(ro.x * c + ro.z * s, ro.y, -ro.x * s + ro.z * c);
    let rdVol = vec3f(rd.x * c + rd.z * s, rd.y, -rd.x * s + rd.z * c);

    var color: vec3f;
    var normal = vec3f(0.0, 0.0, 1.0);
    var depth = 1.0;
    var alpha = 1.0;

    let hit = raymarch(roVol, rdVol);
    if (hit.hit) {
        if (hit.atBoundary) {
            normal = calcBoundaryNormal(hit.pos);
        } else {
            normal = calcNormal(hit.pos);
        }
        // Rotate normal back to world space
        normal = vec3f(normal.x * c - normal.z * s, normal.y, normal.x * s + normal.z * c);
        // Use world-space rd for consistent lighting (normal is in world space)
        color = shade(hit.pos, normal, rd, worldLightDir);
        depth = hit.dist / MAX_DIST;
    } else {
        color = u.bgColor;
        alpha = u.bgAlpha;
    }

    // Gamma correction
    color = pow(color, vec3f(1.0 / 2.2));

    var output: FragmentOutput;
    output.color = vec4f(color, alpha);
    output.geo = vec4f(normal * 0.5 + 0.5, depth);
    return output;
}

// WGSL version – WebGPU
// Pack uniforms into a struct to stay within WebGPU's 12 uniform buffer limit
struct Uniforms {
    // Slot 0: resolution.xy, time, operation
    // Slot 1: scale, offsetX, offsetY, mask
    // Slot 2: seed, colorMode, speed, rotation
    // Slot 3: colorOffset
    data: array<vec4<f32>, 6>,
};

const PI: f32 = 3.14159265358979;

// Branchless HSV to RGB conversion
fn hsv2rgb(c: vec3<f32>) -> vec3<f32> {
    let p = abs(fract(c.xxx + vec3<f32>(1.0, 2.0/3.0, 1.0/3.0)) * 6.0 - 3.0);
    return c.z * mix(vec3<f32>(1.0), clamp(p - 1.0, vec3<f32>(0.0), vec3<f32>(1.0)), vec3<f32>(c.y));
}

@group(0) @binding(0) var<uniform> uniforms: Uniforms;

// Perform the selected bitwise/arithmetic operation on two integers,
// mask the result, then normalize to 0..1
fn bitOp(a: i32, b: i32, op: i32, m: i32) -> f32 {
    var r: i32 = 0;
    if (op == 0)      { r = a ^ b; }        // xor
    else if (op == 1) { r = a & b; }        // and
    else if (op == 2) { r = a | b; }        // or
    else if (op == 3) { r = ~(a & b); }     // nand
    else if (op == 4) { r = ~(a ^ b); }     // xnor
    else if (op == 5) { r = a * b; }        // mul
    else if (op == 6) { r = a + b; }        // add
    else              { r = a - b; }        // sub
    r = r & m;
    return f32(r) / f32(m);
}

@fragment
fn main(@builtin(position) position: vec4<f32>) -> @location(0) vec4<f32> {
    // Unpack uniforms
    let resolution = uniforms.data[0].xy;
    let time = uniforms.data[0].z;
    let operation = i32(uniforms.data[0].w);
    let scale = uniforms.data[1].x;
    let offsetX = i32(uniforms.data[1].y);
    let offsetY = i32(uniforms.data[1].z);
    let mask = i32(uniforms.data[1].w);
    let seed = i32(uniforms.data[2].x);
    let colorMode = i32(uniforms.data[2].y);
    let speed = i32(uniforms.data[2].z);
    let rotation = uniforms.data[2].w;
    let colorOffset = i32(uniforms.data[3].x);
    let tileOffset = uniforms.data[4].xy;
    let fullResolution = uniforms.data[4].zw;
    let renderScale = uniforms.data[5].x;

    // Map scale so higher value = bigger cells (lower frequency)
    let pixelScale = scale * 0.1 * renderScale;

    // Apply rotation around screen center
    let angle = rotation * PI / 180.0;
    let c = cos(angle);
    let s = sin(angle);
    let centered = (position.xy + tileOffset) - fullResolution * 0.5;
    let rotated = vec2<f32>(centered.x * c - centered.y * s, centered.x * s + centered.y * c);
    let coord = rotated + fullResolution * 0.5;

    // Time offset — uses 256 (pattern period) so it loops seamlessly at any speed
    let animOffset = i32(floor(time * f32(-speed) * 256.0));

    // Compute integer coordinates
    var x = i32(floor(coord.x / pixelScale)) + offsetX + animOffset;
    var y = i32(floor(coord.y / pixelScale)) + offsetY;

    // Seed XORs into coordinates (dramatic pattern shifts)
    x = x ^ seed;
    y = y ^ (seed * 3);

    if (colorMode == 0) {
        // Mono: same operation across all channels
        let v = bitOp(x, y, operation, mask);
        return vec4<f32>(v, v, v, 1.0);
    } else if (colorMode == 1) {
        // RGB: channel-shifted patterns (chromatic aberration)
        let r = bitOp(x, y, operation, mask);
        let g = bitOp(x + colorOffset, y, operation, mask);
        let b = bitOp(x, y + colorOffset, operation, mask);
        return vec4<f32>(r, g, b, 1.0);
    } else {
        // HSV: bitwise value drives hue, full saturation and value
        // Scale hue to avoid wrapping both ends to red
        let v = bitOp(x, y, operation, mask);
        let hueScale = f32(mask) / f32(mask + 1);
        return vec4<f32>(hsv2rgb(vec3<f32>(v * hueScale, 1.0, 1.0)), 1.0);
    }
}

/*
 * WGSL cell noise shader (simplified - mono only).
 * Implements Worley distance evaluation with deterministic jitter identical to the GLSL path.
 * Metric selection maps to safe ranges so seeds produce seamless tiles.
 */

struct Uniforms {
    data : array<vec4<f32>, 4>,
};

@group(0) @binding(0) var<uniform> uniforms : Uniforms;

const PI : f32 = 3.14159265359;
const TAU : f32 = 6.28318530718;

fn modulo(a: f32, b: f32) -> f32 {
    return a - b * floor(a / b);
}

fn map(value: f32, inMin: f32, inMax: f32, outMin: f32, outMax: f32) -> f32 {
    return outMin + (outMax - outMin) * (value - inMin) / (inMax - inMin);
}

// PCG PRNG - MIT License
fn pcg(seed: vec3<u32>) -> vec3<u32> {
    var v = seed * 1664525u + 1013904223u;

    v.x = v.x + v.y * v.z;
    v.y = v.y + v.z * v.x;
    v.z = v.z + v.x * v.y;

    v = v ^ (v >> vec3<u32>(16u));

    v.x = v.x + v.y * v.z;
    v.y = v.y + v.z * v.x;
    v.z = v.z + v.x * v.y;

    return v;
}

fn prng(p0: vec3<f32>) -> vec3<f32> {
    var p = p0;
    if (p.x >= 0.0) { p.x = p.x * 2.0; } else { p.x = -p.x * 2.0 + 1.0; }
    if (p.y >= 0.0) { p.y = p.y * 2.0; } else { p.y = -p.y * 2.0 + 1.0; }
    if (p.z >= 0.0) { p.z = p.z * 2.0; } else { p.z = -p.z * 2.0 + 1.0; }
    let u = pcg(vec3<u32>(p));
    return vec3<f32>(u) / f32(0xffffffffu);
}

fn polarShape(st: vec2<f32>, sides: i32) -> f32 {
    let a = atan2(st.x, st.y) + PI;
    let r = TAU / f32(sides);
    return cos(floor(0.5 + a / r) * r - a) * length(st);
}

fn shape(st0: vec2<f32>, offset: vec2<f32>, kind: i32, scale: f32) -> f32 {
    var st = st0 + offset;
    var d = 1.0;
    if (kind == 0) {
        d = length(st * 1.2);
    } else if (kind == 2) {
        d = polarShape(st * 1.2, 6);
    } else if (kind == 3) {
        d = polarShape(st * 1.2, 8);
    } else if (kind == 4) {
        d = polarShape(st * 1.5, 4);
    } else if (kind == 6) {
        var st2 = st;
        st2.y = st2.y + 0.05;
        d = polarShape(st2 * 1.5, 3);
    }
    return d * scale;
}

fn smin(a: f32, b: f32, k: f32) -> f32 {
    if (k == 0.0) { return min(a, b); }
    let h = max(k - abs(a - b), 0.0) / k;
    return min(a, b) - h * h * k * 0.25;
}

fn cells(st0: vec2<f32>, freq: f32, cellSize: f32, metric: i32, seed: i32, speed: f32, variation: f32, cellSmooth: f32, time: f32, aspect: f32) -> f32 {
    var st = st0;
    st = st - vec2<f32>(0.5 * aspect, 0.5);
    st = st * freq;
    st = st + vec2<f32>(0.5 * aspect, 0.5);
    st = st + prng(vec3<f32>(f32(seed))).xy;

    var i = floor(st);
    var f = fract(st);

    var d = 1.0;
    for (var y: i32 = -2; y <= 2; y = y + 1) {
        for (var x: i32 = -2; x <= 2; x = x + 1) {
            let n = vec2<f32>(f32(x), f32(y));
            var wrap = i + n;
            var point = prng(vec3<f32>(wrap, f32(seed))).xy;

            let r1 = prng(vec3<f32>(f32(seed), wrap)) * 0.5 - vec3<f32>(0.25);
            let r2 = prng(vec3<f32>(wrap, f32(seed))) * 2.0 - vec3<f32>(1.0);
            let spd = floor(speed);
            point = point + vec2<f32>(
                sin(time * TAU * spd + r2.x) * r1.x,
                cos(time * TAU * spd + r2.y) * r1.y
            );

            let diff = n + point - f;
            var dist = shape(vec2<f32>(diff.x, -diff.y), vec2<f32>(0.0), metric, cellSize);
            if (metric == 1) {
                dist = abs(n.x + point.x - f.x) + abs(n.y + point.y - f.y);
                dist = dist * cellSize;
            }

            dist = dist + r1.z * (variation * 0.01);
            d = smin(d, dist, cellSmooth * 0.01);
        }
    }
    return d;
}

@fragment
fn main(@builtin(position) pos : vec4<f32>) -> @location(0) vec4<f32> {
    let resolution = uniforms.data[0].xy;
    let time = uniforms.data[0].z;
    let seed = i32(uniforms.data[0].w);

    let metric = i32(uniforms.data[1].x);
    var scale = uniforms.data[1].y;
    var cellScale = uniforms.data[1].z;
    let cellSmooth = uniforms.data[1].w;

    let variation = uniforms.data[2].x;
    let speed = uniforms.data[2].y;

    let tileOffset = uniforms.data[3].xy;
    let fullResolution = uniforms.data[3].zw;
    let aspect = fullResolution.x / fullResolution.y;

    var color = vec4<f32>(0.0, 0.0, 1.0, 1.0);
    var st = (pos.xy + tileOffset) / fullResolution.y;

    let freq = map(scale, 1.0, 100.0, 20.0, 1.0);
    let cellSize = map(cellScale, 1.0, 100.0, 3.0, 0.75);

    let d = cells(st, freq, cellSize, metric, seed, speed, variation, cellSmooth, time, aspect);

    // Mono output only
    color = vec4<f32>(vec3<f32>(d, d, d), color.a);

    return color;
}

// Cellular automata display pass (WGSL).
// Mono-only version (no palette support).

struct Uniforms {
    data : array<vec4<f32>, 3>,
};

@group(0) @binding(0) var<uniform> uniforms : Uniforms;
@group(0) @binding(1) var fbTex: texture_2d<f32>;
@group(0) @binding(2) var mySampler: sampler;

fn quadratic3(p0: vec4<f32>, p1: vec4<f32>, p2: vec4<f32>, t: f32) -> vec4<f32> {
    let t2 = t * t;

    return p0 * 0.5 * (1.0 - t) * (1.0 - t) +
           p1 * 0.5 * (-2.0 * t2 + 2.0 * t + 1.0) +
           p2 * 0.5 * t2;
}

fn bicubic4(p0: vec4<f32>, p1: vec4<f32>, p2: vec4<f32>, p3: vec4<f32>, t: f32) -> vec4<f32> {
    let t2 = t * t;
    let t3 = t2 * t;

    let b0 = (1.0 - t) * (1.0 - t) * (1.0 - t) / 6.0;
    let b1 = (3.0 * t3 - 6.0 * t2 + 4.0) / 6.0;
    let b2 = (-3.0 * t3 + 3.0 * t2 + 3.0 * t + 1.0) / 6.0;
    let b3 = t3 / 6.0;

    return p0 * b0 + p1 * b1 + p2 * b2 + p3 * b3;
}

fn catmullRom3(p0: vec4<f32>, p1: vec4<f32>, p2: vec4<f32>, t: f32) -> vec4<f32> {
    // Catmull-Rom-esque cubic through 3 points
    // Interpolating (passes through control points)
    let t2 = t * t;
    let t3 = t2 * t;

    return p1 + 0.5 * t * (p2 - p0) +
           0.5 * t2 * (2.0*p0 - 5.0*p1 + 4.0*p2 - p0) +
           0.5 * t3 * (-p0 + 3.0*p1 - 3.0*p2 + p0);
}

fn catmullRom4(p0: vec4<f32>, p1: vec4<f32>, p2: vec4<f32>, p3: vec4<f32>, t: f32) -> vec4<f32> {
    return p1 + 0.5 * t * (p2 - p0 + t * (2.0 * p0 - 5.0 * p1 + 4.0 * p2 - p3 + t * (3.0 * (p1 - p2) + p3 - p0)));
}

fn quadraticSample(tex: texture_2d<f32>, samp: sampler, uv: vec2<f32>, texelSize: vec2<f32>) -> vec4<f32> {
    // Match GLSL: offset uv by one texel to accommodate texel centering
    let uv2 = uv + texelSize;
    let texCoord = uv2 / texelSize;
    let baseCoord = floor(texCoord - 0.5);
    let f = fract(texCoord - 0.5);

    // Sample 3x3 grid centered on the interpolation point
    let v00 = textureSampleLevel(tex, samp, (baseCoord + vec2<f32>(-0.5, -0.5)) * texelSize, 0.0);
    let v10 = textureSampleLevel(tex, samp, (baseCoord + vec2<f32>( 0.5, -0.5)) * texelSize, 0.0);
    let v20 = textureSampleLevel(tex, samp, (baseCoord + vec2<f32>( 1.5, -0.5)) * texelSize, 0.0);

    let v01 = textureSampleLevel(tex, samp, (baseCoord + vec2<f32>(-0.5,  0.5)) * texelSize, 0.0);
    let v11 = textureSampleLevel(tex, samp, (baseCoord + vec2<f32>( 0.5,  0.5)) * texelSize, 0.0);
    let v21 = textureSampleLevel(tex, samp, (baseCoord + vec2<f32>( 1.5,  0.5)) * texelSize, 0.0);

    let v02 = textureSampleLevel(tex, samp, (baseCoord + vec2<f32>(-0.5,  1.5)) * texelSize, 0.0);
    let v12 = textureSampleLevel(tex, samp, (baseCoord + vec2<f32>( 0.5,  1.5)) * texelSize, 0.0);
    let v22 = textureSampleLevel(tex, samp, (baseCoord + vec2<f32>( 1.5,  1.5)) * texelSize, 0.0);

    // Interpolate rows using quadratic B-spline
    let y0 = quadratic3(v00, v10, v20, f.x);
    let y1 = quadratic3(v01, v11, v21, f.x);
    let y2 = quadratic3(v02, v12, v22, f.x);

    // Interpolate columns
    return quadratic3(y0, y1, y2, f.y);
}

fn catmullRom3x3Sample(tex: texture_2d<f32>, samp: sampler, uv: vec2<f32>, texelSize: vec2<f32>) -> vec4<f32> {
    // Match GLSL: offset uv by one texel to accommodate texel centering
    let uv2 = uv + texelSize;
    let texCoord = uv2 / texelSize;
    let baseCoord = floor(texCoord - 1.0);
    let f = fract(texCoord - 1.0);

    // Sample 3x3 grid
    let v00 = textureSampleLevel(tex, samp, (baseCoord + vec2<f32>(-0.5, -0.5)) * texelSize, 0.0);
    let v10 = textureSampleLevel(tex, samp, (baseCoord + vec2<f32>( 0.5, -0.5)) * texelSize, 0.0);
    let v20 = textureSampleLevel(tex, samp, (baseCoord + vec2<f32>( 1.5, -0.5)) * texelSize, 0.0);

    let v01 = textureSampleLevel(tex, samp, (baseCoord + vec2<f32>(-0.5,  0.5)) * texelSize, 0.0);
    let v11 = textureSampleLevel(tex, samp, (baseCoord + vec2<f32>( 0.5,  0.5)) * texelSize, 0.0);
    let v21 = textureSampleLevel(tex, samp, (baseCoord + vec2<f32>( 1.5,  0.5)) * texelSize, 0.0);

    let v02 = textureSampleLevel(tex, samp, (baseCoord + vec2<f32>(-0.5,  1.5)) * texelSize, 0.0);
    let v12 = textureSampleLevel(tex, samp, (baseCoord + vec2<f32>( 0.5,  1.5)) * texelSize, 0.0);
    let v22 = textureSampleLevel(tex, samp, (baseCoord + vec2<f32>( 1.5,  1.5)) * texelSize, 0.0);

    // Interpolate rows using Catmull-Rom
    let y0 = catmullRom3(v00, v10, v20, f.x);
    let y1 = catmullRom3(v01, v11, v21, f.x);
    let y2 = catmullRom3(v02, v12, v22, f.x);

    // Interpolate columns
    return catmullRom3(y0, y1, y2, f.y);
}

fn bicubicSample(tex: texture_2d<f32>, samp: sampler, uv: vec2<f32>, texelSize: vec2<f32>) -> vec4<f32> {
    let uv2 = uv + texelSize;
    let texCoord = uv2 / texelSize;
    let baseCoord = floor(texCoord - 1.0);
    let f = fract(texCoord - 1.0);

    let row0 = bicubic4(
        textureSampleLevel(tex, samp, (baseCoord + vec2<f32>(-0.5, -0.5)) * texelSize, 0.0),
        textureSampleLevel(tex, samp, (baseCoord + vec2<f32>( 0.5, -0.5)) * texelSize, 0.0),
        textureSampleLevel(tex, samp, (baseCoord + vec2<f32>( 1.5, -0.5)) * texelSize, 0.0),
        textureSampleLevel(tex, samp, (baseCoord + vec2<f32>( 2.5, -0.5)) * texelSize, 0.0),
        f.x
    );

    let row1 = bicubic4(
        textureSampleLevel(tex, samp, (baseCoord + vec2<f32>(-0.5,  0.5)) * texelSize, 0.0),
        textureSampleLevel(tex, samp, (baseCoord + vec2<f32>( 0.5,  0.5)) * texelSize, 0.0),
        textureSampleLevel(tex, samp, (baseCoord + vec2<f32>( 1.5,  0.5)) * texelSize, 0.0),
        textureSampleLevel(tex, samp, (baseCoord + vec2<f32>( 2.5,  0.5)) * texelSize, 0.0),
        f.x
    );

    let row2 = bicubic4(
        textureSampleLevel(tex, samp, (baseCoord + vec2<f32>(-0.5,  1.5)) * texelSize, 0.0),
        textureSampleLevel(tex, samp, (baseCoord + vec2<f32>( 0.5,  1.5)) * texelSize, 0.0),
        textureSampleLevel(tex, samp, (baseCoord + vec2<f32>( 1.5,  1.5)) * texelSize, 0.0),
        textureSampleLevel(tex, samp, (baseCoord + vec2<f32>( 2.5,  1.5)) * texelSize, 0.0),
        f.x
    );

    let row3 = bicubic4(
        textureSampleLevel(tex, samp, (baseCoord + vec2<f32>(-0.5,  2.5)) * texelSize, 0.0),
        textureSampleLevel(tex, samp, (baseCoord + vec2<f32>( 0.5,  2.5)) * texelSize, 0.0),
        textureSampleLevel(tex, samp, (baseCoord + vec2<f32>( 1.5,  2.5)) * texelSize, 0.0),
        textureSampleLevel(tex, samp, (baseCoord + vec2<f32>( 2.5,  2.5)) * texelSize, 0.0),
        f.x
    );

    return bicubic4(row0, row1, row2, row3, f.y);
}

fn catmullRom4x4Sample(tex: texture_2d<f32>, samp: sampler, uv: vec2<f32>, texelSize: vec2<f32>) -> vec4<f32> {
    let uv2 = uv + texelSize;
    let texCoord = uv2 / texelSize;
    let baseCoord = floor(texCoord - 1.0);
    let f = fract(texCoord - 1.0);

    let row0 = catmullRom4(
        textureSampleLevel(tex, samp, (baseCoord + vec2<f32>(-0.5, -0.5)) * texelSize, 0.0),
        textureSampleLevel(tex, samp, (baseCoord + vec2<f32>( 0.5, -0.5)) * texelSize, 0.0),
        textureSampleLevel(tex, samp, (baseCoord + vec2<f32>( 1.5, -0.5)) * texelSize, 0.0),
        textureSampleLevel(tex, samp, (baseCoord + vec2<f32>( 2.5, -0.5)) * texelSize, 0.0),
        f.x
    );

    let row1 = catmullRom4(
        textureSampleLevel(tex, samp, (baseCoord + vec2<f32>(-0.5,  0.5)) * texelSize, 0.0),
        textureSampleLevel(tex, samp, (baseCoord + vec2<f32>( 0.5,  0.5)) * texelSize, 0.0),
        textureSampleLevel(tex, samp, (baseCoord + vec2<f32>( 1.5,  0.5)) * texelSize, 0.0),
        textureSampleLevel(tex, samp, (baseCoord + vec2<f32>( 2.5,  0.5)) * texelSize, 0.0),
        f.x
    );

    let row2 = catmullRom4(
        textureSampleLevel(tex, samp, (baseCoord + vec2<f32>(-0.5,  1.5)) * texelSize, 0.0),
        textureSampleLevel(tex, samp, (baseCoord + vec2<f32>( 0.5,  1.5)) * texelSize, 0.0),
        textureSampleLevel(tex, samp, (baseCoord + vec2<f32>( 1.5,  1.5)) * texelSize, 0.0),
        textureSampleLevel(tex, samp, (baseCoord + vec2<f32>( 2.5,  1.5)) * texelSize, 0.0),
        f.x
    );

    let row3 = catmullRom4(
        textureSampleLevel(tex, samp, (baseCoord + vec2<f32>(-0.5,  2.5)) * texelSize, 0.0),
        textureSampleLevel(tex, samp, (baseCoord + vec2<f32>( 0.5,  2.5)) * texelSize, 0.0),
        textureSampleLevel(tex, samp, (baseCoord + vec2<f32>( 1.5,  2.5)) * texelSize, 0.0),
        textureSampleLevel(tex, samp, (baseCoord + vec2<f32>( 2.5,  2.5)) * texelSize, 0.0),
        f.x
    );

    return catmullRom4(row0, row1, row2, row3, f.y);
}

fn cosineMix(a: f32, b: f32, t: f32) -> f32 {
    let amount = (1.0 - cos(t * 3.141592653589793)) * 0.5;
    return mix(a, b, amount);
}

@fragment fn main(@builtin(position) fragCoord: vec4<f32>) -> @location(0) vec4<f32> {
    let resolution = uniforms.data[0].xy;
    let smoothing = i32(uniforms.data[1].y);
    let tileOffset = uniforms.data[2].xy;
    let fullResolution = uniforms.data[2].zw;
    let globalCoord = fragCoord.xy + tileOffset;

    var state: f32 = 0.0;
    if (smoothing == 0) {
        // constant - use textureLoad for exact nearest-neighbor sampling
        let texSizeI = vec2<i32>(textureDimensions(fbTex, 0));
        let texSizeF = vec2<f32>(f32(texSizeI.x), f32(texSizeI.y));
        let pixelCoord = vec2<i32>(floor(globalCoord * texSizeF / fullResolution));
        state = textureLoad(fbTex, clamp(pixelCoord, vec2<i32>(0), texSizeI - vec2<i32>(1)), 0).g;
    } else if (smoothing == 3) {
        // catmull-rom 3x3 (9 taps)
        let texSize = vec2<f32>(textureDimensions(fbTex, 0));
        let texelSize = 1.0 / texSize;
        let scaling = fullResolution / texSize;
        let uv = (globalCoord - scaling * 0.5) / fullResolution;
        state = catmullRom3x3Sample(fbTex, mySampler, uv, texelSize).g;
    } else if (smoothing == 4) {
        // catmull-rom 4x4 (16 taps)
        let texSize = vec2<f32>(textureDimensions(fbTex, 0));
        let texelSize = 1.0 / texSize;
        let scaling = fullResolution / texSize;
        let uv = (globalCoord - scaling * 0.5) / fullResolution;
        state = catmullRom4x4Sample(fbTex, mySampler, uv, texelSize).g;
    } else if (smoothing == 5) {
        // b-spline 3x3 (9 taps)
        let texSize = vec2<f32>(textureDimensions(fbTex, 0));
        let texelSize = 1.0 / texSize;
        let scaling = fullResolution / texSize;
        let uv = (globalCoord - scaling * 0.5) / fullResolution;
        state = quadraticSample(fbTex, mySampler, uv, texelSize).g;
    } else if (smoothing == 6) {
        // b-spline 4x4 (16 taps)
        let texSize = vec2<f32>(textureDimensions(fbTex, 0));
        let texelSize = 1.0 / texSize;
        let scaling = fullResolution / texSize;
        let uv = (globalCoord - scaling * 0.5) / fullResolution;
        state = bicubicSample(fbTex, mySampler, uv, texelSize).g;
    } else {
        // linear-style smoothing — sample texel centres explicitly to avoid seams.
        let texSize = vec2<f32>(textureDimensions(fbTex, 0));
        let texelPos = (globalCoord * texSize / fullResolution) - vec2<f32>(0.5, 0.5);
        let base = floor(texelPos);
        let weights = fract(texelPos);
        let next = base + vec2<f32>(1.0, 1.0);

        let texSizeI = vec2<i32>(textureDimensions(fbTex, 0));
        let minIdx = vec2<i32>(0, 0);
        let maxIdx = texSizeI - vec2<i32>(1, 1);
        let baseI = clamp(vec2<i32>(base), minIdx, maxIdx);
        let nextI = clamp(vec2<i32>(next), minIdx, maxIdx);

        let v00 = textureLoad(fbTex, baseI, 0).g;
        let v10 = textureLoad(fbTex, vec2<i32>(nextI.x, baseI.y), 0).g;
        let v01 = textureLoad(fbTex, vec2<i32>(baseI.x, nextI.y), 0).g;
        let v11 = textureLoad(fbTex, nextI, 0).g;

        if (smoothing == 1) {
            let v0 = mix(v00, v10, weights.x);
            let v1 = mix(v01, v11, weights.x);
            state = mix(v0, v1, weights.y);
        } else {
            let v0 = cosineMix(v00, v10, weights.x);
            let v1 = cosineMix(v01, v11, weights.x);
            state = cosineMix(v0, v1, weights.y);
        }
    }

    // Mono output only
    let intensity = clamp(state, 0.0, 1.0);
    return vec4<f32>(intensity, intensity, intensity, 1.0);
}

/*
 * Cellular automata feedback pass.
 *
 * This shader advances the ping-pong buffer by evaluating a neighbourhood
 * count against a curated ruleset or custom birth/survival tables provided
 * by the UI.  When `source` is set, the previous compositing stage is sampled
 * and luminance blended into the automata to support audio/video driven
 * perturbations without breaking the automata's binary storage format.
 */

struct Uniforms {
    data : array<vec4<f32>, 7>,
};

@group(0) @binding(0) var<uniform> uniforms : Uniforms;
@group(0) @binding(1) var samp: sampler;
@group(0) @binding(2) var bufTex: texture_2d<f32>;
@group(0) @binding(3) var tex: texture_2d<f32>;

fn map(value: f32, inMin: f32, inMax: f32, outMin: f32, outMax: f32) -> f32 {
    return outMin + (outMax - outMin) * (value - inMin) / (inMax - inMin);
}

fn lum(color: vec3<f32>) -> f32 {
    return 0.2126 * color.r + 0.7152 * color.g + 0.0722 * color.b;
}

fn random(st: vec2<f32>) -> f32 {
    return fract(sin(dot(st, vec2<f32>(12.9898, 78.233))) * 43758.5453123);
}

/*
Rulesets

Name                    Born                Survive
-----------------------------------------------------
Classic Life            3                   23
Highlife                36                  23
Seeds                   2                   -
Coral                   38                  23
Day & Night             3678                34678
Life Without Death      3                   012345678
Replicator              1357                1357
Amoeba                  357                 1358
Maze                    3                   12345
Glider Walk             25                  4
Diamoeba                35678               5678
2x2                     36                  125
Morley                  368                 245
Anneal                  4678                35678
34 Life                 34                  34

Simple Replicator       368                 12578       
Waffles                 36                  245
Pond Life               37                  23
*/

// Determine if cell should be born based on state of neighbors (n)
fn shouldBeBorn(n: i32, ruleIndex: i32) -> bool {
    var should: bool = false;

    if (ruleIndex == 0 || ruleIndex == 5 || ruleIndex == 8) {
        should = n == 3;                                        // Classic Life, Life w/o Death, Maze: B3
    } else if (ruleIndex == 1 || ruleIndex == 11 || ruleIndex == 16) {
        should = n == 3 || n == 6;                              // Highlife, 2x2, Waffles: B36
    } else if (ruleIndex == 2) {
        should = n == 2;                                        // Seeds: B2
    } else if (ruleIndex == 3) {
        should = n == 3 || n == 8;                              // Coral: B38 
    } else if (ruleIndex == 4) {
        should = n == 3 || n == 6 || n == 7 || n == 8;          // Day & Night: B3678  
    } else if (ruleIndex == 6) {
        should = n == 1 || n == 3 || n == 5 || n == 7;          // Replicator: B1357
    } else if (ruleIndex == 7) {
        should = n == 3 || n == 5 || n == 7;                    // Amoeba: B357
    } else if (ruleIndex == 9) {
        should = n == 2 || n == 5;                              // Glider Walk: B25 
    } else if (ruleIndex == 10) {
        should = n == 3 || n >= 5;                              // Diamoeba: B35678
    } else if (ruleIndex == 12) {
        should = n == 3 || n == 6 || n == 8;                    // Morley: B368 
    } else if (ruleIndex == 13) {
        should = n == 4 || n == 6 || n == 7 || n == 8;          // Anneal: B4678 
    } else if (ruleIndex == 14) {
        should = n == 3 || n == 4;                              // 34 Life: B34
    } else if (ruleIndex == 15) {
        should = n == 3 || n == 6 || n == 8;                    // Simple Replicator: B368
    } else if (ruleIndex == 17) {
        should = n == 3 || n == 7;                              // Pond Life: B37
    }

    return should;
}

// Determine if cell should survive based on state of neighbors (n)
fn shouldSurvive(n: i32, current: f32, ruleIndex: i32) -> bool {
    var should: bool = false;

    if (ruleIndex == 0 || ruleIndex == 1 || ruleIndex == 3 || ruleIndex == 17) {
        should = n == 2 || n == 3;                              // Classic Life, Highlife, Coral, Pond Life: S23
    } else if (ruleIndex == 2) {
        should = false;                                         // Seeds: no survival
    } else if (ruleIndex == 4) {
        should = n == 3 || n == 4 || n == 6 || n == 7 || n == 8;  // Day & Night: S34678
    } else if (ruleIndex == 5) {
        should = true;                                          // Life w/o Death: S012345678
    } else if (ruleIndex == 6) {
        should = n == 1 || n == 3 || n == 5 || n == 7;          // Replicator: S1357
    } else if (ruleIndex == 7) {
        should = n == 1 || n == 3 || n == 5 || n == 8;          // Amoeba: S1358
    } else if (ruleIndex == 8) {
        should = n >= 1 && n <= 5;                              // Maze: S12345
    } else if (ruleIndex == 9) {
        should = n == 4;                                        // Glider Walk: S4
    } else if (ruleIndex == 10) {
        should = n >= 5;                                        // Diamoeba: S5678
    } else if (ruleIndex == 11) {
        should = n == 1 || n == 2 || n == 5;                    // 2x2: S125
    } else if (ruleIndex == 12 || ruleIndex == 16) {
        should = n == 2 || n == 4 || n == 5;                    // Morley, Waffles: S245
    } else if (ruleIndex == 13) {
        should = n == 3 || n >= 5;                              // Anneal: S35678
    } else if (ruleIndex == 14) {
        should = n == 3 || n == 4;                              // 34 Life: S34
    } else if (ruleIndex == 15) {
        should = n == 1 || n == 2 || n == 5 || n >= 7;          // Simple Replicator: S12578
    }

    if (current < 0.5) { should = false; }

    return should;
}

fn shouldBeBornCustom(n: i32, bornMask0: vec4<f32>, bornMask1: vec4<f32>, bornMask2: f32) -> bool {
    if (n == 0) { return bornMask0.x > 0.5; }
    else if (n == 1) { return bornMask0.y > 0.5; }
    else if (n == 2) { return bornMask0.z > 0.5; }
    else if (n == 3) { return bornMask0.w > 0.5; }
    else if (n == 4) { return bornMask1.x > 0.5; }
    else if (n == 5) { return bornMask1.y > 0.5; }
    else if (n == 6) { return bornMask1.z > 0.5; }
    else if (n == 7) { return bornMask1.w > 0.5; }
    else if (n == 8) { return bornMask2 > 0.5; }
    return false;
}

fn shouldSurviveCustom(n: i32, current: f32, surviveMask0: vec3<f32>, surviveMask1: vec4<f32>, surviveMask2: vec2<f32>) -> bool {
    var should: bool = false;
    if (n == 0) { should = surviveMask0.x > 0.5; }
    else if (n == 1) { should = surviveMask0.y > 0.5; }
    else if (n == 2) { should = surviveMask0.z > 0.5; }
    else if (n == 3) { should = surviveMask1.x > 0.5; }
    else if (n == 4) { should = surviveMask1.y > 0.5; }
    else if (n == 5) { should = surviveMask1.z > 0.5; }
    else if (n == 6) { should = surviveMask1.w > 0.5; }
    else if (n == 7) { should = surviveMask2.x > 0.5; }
    else if (n == 8) { should = surviveMask2.y > 0.5; }

    if (current < 0.5) { should = false; }
    return should;
}

// Clamp a texel coordinate to the valid texture bounds
fn clampCoord(p: vec2<i32>, size: vec2<i32>) -> vec2<i32> {
    let cx = clamp(p.x, 0, size.x - 1);
    let cy = clamp(p.y, 0, size.y - 1);
    return vec2<i32>(cx, cy);
}

// Fetch a single cell value using integer coordinates to avoid filtering
fn cellAt(p: vec2<i32>, size: vec2<i32>) -> f32 {
    let pc = clampCoord(p, size);
    return textureLoad(bufTex, pc, 0).r;
}

// Count Moore-neighbourhood alive cells around base pixel
fn countNeighbors(base: vec2<i32>, size: vec2<i32>) -> i32 {
    var count: i32 = 0;
    for (var dy: i32 = -1; dy <= 1; dy++) {
        for (var dx: i32 = -1; dx <= 1; dx++) {
            if (dx == 0 && dy == 0) { continue; }
            let n: f32 = cellAt(base + vec2<i32>(dx, dy), size);
            count += i32(n > 0.5);
        }
    }
    return count;
}

@fragment
fn main(@builtin(position) fragCoord: vec4<f32>) -> @location(0) vec4<f32> {
    let texSize: vec2<f32> = vec2<f32>(textureDimensions(bufTex, 0));
    let texSizeI: vec2<i32> = vec2<i32>(textureDimensions(bufTex, 0));
    let uv: vec2<f32> = fragCoord.xy / texSize;

    // Extract parameters from uniforms - precise mapping from hooks.js and
    // the framebuffer layout in uniforms.json. Slots 0-2 mirror the runtime's
    // timing metadata, slot 1 stores the primary CA controls, and slots 2-6
    // pack the custom rule masks alongside the input source selector.
    let deltaTime: f32 = uniforms.data[0].y;
    let seed: i32 = i32(uniforms.data[0].z);
    let resetState: bool = uniforms.data[0].w > 0.5;
    let ruleIndex: i32 = i32(uniforms.data[1].x);
    let speed: f32 = uniforms.data[1].y;
    let weight: f32 = uniforms.data[1].z;
    let useCustom: bool = uniforms.data[1].w > 0.5;

    let bornMask0: vec4<f32> = uniforms.data[2];
    let bornMask1: vec4<f32> = uniforms.data[3];
    let bornMask2: f32 = uniforms.data[4].x;
    let surviveMask0: vec3<f32> = uniforms.data[4].yzw;
    let surviveMask1: vec4<f32> = uniforms.data[5];
    let surviveMask2: vec2<f32> = uniforms.data[6].xy;
    let source: i32 = i32(uniforms.data[6].z);

    // Sample all 4 channels to check if buffer is truly empty
    let base: vec2<i32> = vec2<i32>(i32(fragCoord.x), i32(fragCoord.y));
    let bufState: vec4<f32> = textureLoad(bufTex, clampCoord(base, texSizeI), 0);
    let state: f32 = bufState.r;
    let bufferIsEmpty: bool = (bufState.r == 0.0 && bufState.g == 0.0 && bufState.b == 0.0 && bufState.a == 0.0);

    // Sample previous frame for luminance-based perturbation (must be before early return for uniform control flow)
    let prevFrame: vec3<f32> = textureSample(tex, samp, uv).rgb;
    let prevLum: f32 = lum(prevFrame);

    // Initialize when reset button pressed or when buffer is completely empty (first load)
    if (resetState || bufferIsEmpty) {
        let r: f32 = random(uv + vec2<f32>(f32(seed), f32(seed)));
        let alive: f32 = step(0.5, r);
        return vec4<f32>(alive, alive, alive, 1.0);
    }

    let prevFrameCoord: vec2<f32> = vec2<f32>(fragCoord.x / texSize.x, 1.0 - fragCoord.y / texSize.y);

    let neighbors: i32 = countNeighbors(base, texSizeI);

    var newState: f32 = state;

    if (useCustom) {
        if (shouldBeBornCustom(neighbors, bornMask0, bornMask1, bornMask2)) {
            newState = 1.0;
        } else if (shouldSurviveCustom(neighbors, state, surviveMask0, surviveMask1, surviveMask2)) {
            newState = 1.0;
        } else {
            newState = 0.0;
        }
    } else {
        if (shouldBeBorn(neighbors, ruleIndex)) {
            newState = 1.0;
        } else if (shouldSurvive(neighbors, state, ruleIndex)) {
            newState = 1.0;
        } else {
            newState = 0.0;
        }
    }

    if (weight > 0.0) {
        newState = mix(newState, prevLum, weight * 0.01);
    }

    // The speed knob expresses human-friendly BPM-style values; remapping keeps
    // the integration step numerically stable across refresh rates.
    let animSpeed: f32 = map(speed, 1.0, 100.0, 0.1, 100.0);
    let currentState: vec4<f32> = vec4<f32>(state, state, state, 1.0);
    let nextState: vec4<f32> = vec4<f32>(newState, newState, newState, 1.0);
    return mix(currentState, nextState, min(1.0, deltaTime * animSpeed));
}

// OCTAVES, RIDGES, OUTPUT_MODE are compile-time consts injected by the
// runtime via injectDefines (see definition.js `globals.{octaves,ridges,
// outputMode}.define`). Same fix as the GLSL backend — collapsing the
// fbmSimplex3D loop bound from runtime to compile-time drops the default
// case from 36 simplex3D inlines/pixel to 12.

struct Uniforms {
    resolution: vec2f,
    time: f32,
    aspectRatio: f32,
    scale: f32,
    // f32, not i32: definition uniformLayout slots are packed with setFloat32
    // (packUniformsWithLayout) — an i32 field here reads the float's bit pattern.
    seed: f32,
    speed: f32,
    // Slots kept as padding so field offsets still match the definition.js
    // vec4 uniformLayout — the JS-side packer targets the vec4 component
    // offsets explicitly and needs the WGSL struct to line up.
    _pad_octaves: f32,     // was octaves — now compile-time OCTAVES
    _pad_ridges: f32,      // was ridges — now compile-time RIDGES
    _pad_outputMode: f32,  // was outputMode — now compile-time OUTPUT_MODE
    intensity: f32,
    _pad_intensity_w: f32, // slot 2.w padding so tile fields land on slot 3
    tileOffset: vec2f,     // slot 3.xy
    fullResolution: vec2f, // slot 3.zw
}

@group(0) @binding(0) var<uniform> u: Uniforms;

// ============================================================================
// 3D Simplex Noise Implementation
// Based on Stefan Gustavson's implementation
// ============================================================================

// Permutation polynomial: (34x^2 + 10x) mod 289
fn permute3(x: vec3f) -> vec3f {
    return (((x * 34.0) + 10.0) * x) % 289.0;
}

fn permute4(x: vec4f) -> vec4f {
    return (((x * 34.0) + 10.0) * x) % 289.0;
}

fn taylorInvSqrt(r: vec4f) -> vec4f {
    return 1.79284291400159 - 0.85373472095314 * r;
}

// 3D Simplex noise with seed support
fn simplex3D(v: vec3f) -> f32 {
    let C = vec2f(1.0 / 6.0, 1.0 / 3.0);
    let D = vec4f(0.0, 0.5, 1.0, 2.0);

    // Apply seed offset to input
    let vSeeded = v + u.seed * 0.1271;

    // First corner
    let i = floor(vSeeded + dot(vSeeded, C.yyy));
    let x0 = vSeeded - i + dot(i, C.xxx);

    // Other corners
    let g = step(x0.yzx, x0.xyz);
    let l = 1.0 - g;
    let i1 = min(g.xyz, l.zxy);
    let i2 = max(g.xyz, l.zxy);

    let x1 = x0 - i1 + C.xxx;
    let x2 = x0 - i2 + C.yyy;
    let x3 = x0 - D.yyy;

    // Permutations
    let iMod = (i - 289.0 * floor(i / 289.0));
    let p = permute4(permute4(permute4(
        iMod.z + vec4f(0.0, i1.z, i2.z, 1.0))
        + iMod.y + vec4f(0.0, i1.y, i2.y, 1.0))
        + iMod.x + vec4f(0.0, i1.x, i2.x, 1.0));

    // Gradients: 7x7 points over a square, mapped onto an octahedron
    let n_ = 0.142857142857; // 1/7
    let ns = n_ * D.wyz - D.xzx;

    let j = p - 49.0 * floor(p * ns.z * ns.z);

    let x_ = floor(j * ns.z);
    let y_ = floor(j - 7.0 * x_);

    let x = x_ * ns.x + ns.yyyy;
    let y = y_ * ns.x + ns.yyyy;
    let h = 1.0 - abs(x) - abs(y);

    let b0 = vec4f(x.xy, y.xy);
    let b1 = vec4f(x.zw, y.zw);

    let s0 = floor(b0) * 2.0 + 1.0;
    let s1 = floor(b1) * 2.0 + 1.0;
    let sh = -step(h, vec4f(0.0));

    let a0 = b0.xzyw + s0.xzyw * sh.xxyy;
    let a1 = b1.xzyw + s1.xzyw * sh.zzww;

    let p0 = vec3f(a0.xy, h.x);
    let p1 = vec3f(a0.zw, h.y);
    let p2 = vec3f(a1.xy, h.z);
    let p3 = vec3f(a1.zw, h.w);

    // Normalise gradients
    let norm = taylorInvSqrt(vec4f(dot(p0, p0), dot(p1, p1), dot(p2, p2), dot(p3, p3)));
    let p0n = p0 * norm.x;
    let p1n = p1 * norm.y;
    let p2n = p2 * norm.z;
    let p3n = p3 * norm.w;

    // Mix final noise value
    var m = max(0.6 - vec4f(dot(x0, x0), dot(x1, x1), dot(x2, x2), dot(x3, x3)), vec4f(0.0));
    m = m * m;
    return 42.0 * dot(m * m, vec4f(dot(p0n, x0), dot(p1n, x1), dot(p2n, x2), dot(p3n, x3)));
}

// FBM — loop bound is the compile-time OCTAVES const so Dawn fully unrolls
// and DCE's the unused iterations.
fn fbmSimplex3D(p: vec3f) -> f32 {
    var sum: f32 = 0.0;
    var amp: f32 = 1.0;
    var freq: f32 = 1.0;
    var maxAmp: f32 = 0.0;

    for (var i: i32 = 0; i < OCTAVES; i = i + 1) {
        var n = simplex3D(p * freq);

        sum = sum + n * amp;
        maxAmp = maxAmp + amp;
        freq = freq * 2.0;
        amp = amp * 0.5;
    }

    return sum / maxAmp;
}

// ============================================================================
// 3D Curl Noise
// curl(F) = (dFz/dy - dFy/dz, dFx/dz - dFz/dx, dFy/dx - dFx/dy)
// ============================================================================

fn curlNoise3D(p: vec3f) -> vec3f {
    let eps: f32 = 1.0;

    // We need 3 independent scalar fields to compute curl of a vector field
    // Use offset positions to create decorrelated fields
    let a = (sin(u.time * 6.28318) * (u.speed) + 1.0) / f32(OCTAVES) * 0.2;
    let b = (cos(u.time * 6.28318) * (u.speed) + 1.0) / f32(OCTAVES) * 0.2;

    let offset1 = vec3f(a, b, 0.0);
    let offset2 = vec3f(31.416 - a, 47.853 - b, 12.793);
    let offset3 = vec3f(93.719 - b, 61.248 - a, 73.561);

    // Sample Fx derivatives
    let Fx_py = fbmSimplex3D(p + vec3f(0.0, eps, 0.0) - offset1);
    let Fx_ny = fbmSimplex3D(p - vec3f(0.0, eps, 0.0) + offset1);
    let Fx_pz = fbmSimplex3D(p + vec3f(0.0, 0.0, eps) - offset1);
    let Fx_nz = fbmSimplex3D(p - vec3f(0.0, 0.0, eps) + offset1);

    // Sample Fy derivatives
    let Fy_px = fbmSimplex3D(p + vec3f(eps, 0.0, 0.0) - offset2);
    let Fy_nx = fbmSimplex3D(p - vec3f(eps, 0.0, 0.0) + offset2);
    let Fy_pz = fbmSimplex3D(p + vec3f(0.0, 0.0, eps) - offset2);
    let Fy_nz = fbmSimplex3D(p - vec3f(0.0, 0.0, eps) + offset2);

    // Sample Fz derivatives
    let Fz_px = fbmSimplex3D(p + vec3f(eps, 0.0, 0.0) - offset3);
    let Fz_nx = fbmSimplex3D(p - vec3f(eps, 0.0, 0.0) + offset3);
    let Fz_py = fbmSimplex3D(p + vec3f(0.0, eps, 0.0) - offset3);
    let Fz_ny = fbmSimplex3D(p - vec3f(0.0, eps, 0.0) + offset3);

    // Compute partial derivatives
    let dFx_dy = (Fx_py - Fx_ny) / (2.0 * eps);
    let dFx_dz = (Fx_pz - Fx_nz) / (2.0 * eps);
    let dFy_dx = (Fy_px - Fy_nx) / (2.0 * eps);
    let dFy_dz = (Fy_pz - Fy_nz) / (2.0 * eps);
    let dFz_dx = (Fz_px - Fz_nx) / (2.0 * eps);
    let dFz_dy = (Fz_py - Fz_ny) / (2.0 * eps);

    // curl = (dFz/dy - dFy/dz, dFx/dz - dFz/dx, dFy/dx - dFx/dy)
    return vec3f(
        dFz_dy - dFy_dz,
        dFx_dz - dFz_dx,
        dFy_dx - dFx_dy
    );
}

@fragment
fn main(@builtin(position) fragCoord: vec4f) -> @location(0) vec4f {
    let uv = (fragCoord.xy + u.tileOffset) / u.fullResolution;
    let aspect = u.fullResolution.x / u.fullResolution.y;

    // Center and scale coordinates
    let centered = (uv - 0.5) * vec2f(aspect, 1.0);
    let p = vec3f(centered * (21.0 - u.scale), 0.5);

    // Compute 3D curl noise
    var curl = curlNoise3D(p);

    // Smooth compression to [0, 1] — tanh saturates gracefully, intensity controls curve
    let curlNorm = tanh(curl * u.intensity) * 0.5 + 0.5;

    var color: vec3f;

    if (OUTPUT_MODE == 0) {
        // flowX: curl.x component
        color = vec3f(curlNorm.x);
    } else if (OUTPUT_MODE == 1) {
        // flowY: curl.y component
        color = vec3f(curlNorm.y);
    } else if (OUTPUT_MODE == 2) {
        // flowZ: curl.z component
        color = vec3f(curlNorm.z);
    } else if (OUTPUT_MODE == 3) {
        // full: all three components as RGB
        color = curlNorm;
    } else {
        // magnitude: length of curl vector
        let curlCentered = curlNorm * 2.0 - 1.0; // Back to [-1, 1]
        let mag = length(curlCentered);
        color = vec3f(mag);
    }

    if (RIDGES) {
        color = 1.0 - abs(color * 2.0 - 1.0);
    }

    return vec4f(color, 1.0);
}

/*
 * Gabor noise — sparse convolution of anisotropic Gabor kernels.
 * Each grid cell scatters random impulse points; the final value is the sum
 * of Gabor kernel contributions from the 3×3 cell neighborhood.
 */

struct Uniforms {
    data: array<vec4<f32>, 4>,
}

@group(0) @binding(0) var<uniform> uniforms: Uniforms;

const PI: f32 = 3.14159265359;
const TAU: f32 = 6.28318530718;

// PCG PRNG - MIT License
fn pcg(seed: vec3<u32>) -> vec3<u32> {
    var v = seed * 1664525u + 1013904223u;
    v.x = v.x + v.y * v.z;
    v.y = v.y + v.z * v.x;
    v.z = v.z + v.x * v.y;
    v = v ^ (v >> vec3<u32>(16u));
    v.x = v.x + v.y * v.z;
    v.y = v.y + v.z * v.x;
    v.z = v.z + v.x * v.y;
    return v;
}

fn prng(p0: vec3<f32>) -> vec3<f32> {
    var p = p0;
    if (p.x >= 0.0) { p.x = p.x * 2.0; } else { p.x = -p.x * 2.0 + 1.0; }
    if (p.y >= 0.0) { p.y = p.y * 2.0; } else { p.y = -p.y * 2.0 + 1.0; }
    if (p.z >= 0.0) { p.z = p.z * 2.0; } else { p.z = -p.z * 2.0 + 1.0; }
    let u = pcg(vec3<u32>(p));
    return vec3<f32>(u) / f32(0xffffffffu);
}

fn map(value: f32, inMin: f32, inMax: f32, outMin: f32, outMax: f32) -> f32 {
    return outMin + (outMax - outMin) * (value - inMin) / (inMax - inMin);
}

fn gaborNoise(st: vec2<f32>, freq: f32, sigma: f32, baseAngle: f32, iso: f32, impulses: i32, t: f32, sd: f32) -> f32 {
    let cell = floor(st);
    let fr = fract(st);
    var sum = 0.0;

    for (var dy: i32 = -1; dy <= 1; dy = dy + 1) {
        for (var dx: i32 = -1; dx <= 1; dx = dx + 1) {
            let neighbor = vec2<f32>(f32(dx), f32(dy));
            let cellId = cell + neighbor;

            for (var k: i32 = 0; k < 8; k = k + 1) {
                if (k >= impulses) { break; }

                let r1 = prng(vec3<f32>(cellId, sd + f32(k) * 7.0));
                let r2 = prng(vec3<f32>(sd + f32(k) * 13.0, cellId));

                var impulsePos = r1.xy;
                impulsePos = impulsePos + vec2<f32>(sin(t + r2.x * TAU), cos(t + r2.y * TAU)) * 0.15;

                let delta = neighbor + impulsePos - fr;

                let angle = mix(baseAngle, r2.z * TAU, iso);
                let dir = vec2<f32>(cos(angle), sin(angle));

                var weight = 1.0;
                if (r1.z < 0.5) { weight = -1.0; }

                let envelope = exp(-dot(delta, delta) / (2.0 * sigma * sigma));
                let phase = TAU * freq * dot(dir, delta);
                sum = sum + weight * envelope * cos(phase);
            }
        }
    }
    return sum;
}

@fragment
fn main(@builtin(position) pos: vec4<f32>) -> @location(0) vec4<f32> {
    let resolution = uniforms.data[0].xy;
    let time = uniforms.data[0].z;
    let seed = uniforms.data[0].w;

    let scale = uniforms.data[1].x;
    let orientation = uniforms.data[1].y;
    let bandwidth = uniforms.data[1].z;
    let isotropy = uniforms.data[1].w;

    let density = uniforms.data[2].x;
    let octaves = uniforms.data[2].y;
    let speed = uniforms.data[2].z;
    let tileOffset = uniforms.data[3].xy;
    let fullResolution = uniforms.data[3].zw;
    var st = (pos.xy + tileOffset) / fullResolution.y;

    let freq = map(scale, 1.0, 100.0, 20.0, 1.0);
    let sigma = map(bandwidth, 1.0, 100.0, 0.05, 0.35);
    let baseAngle = orientation * PI / 180.0;
    let iso = isotropy / 100.0;
    let impulses = i32(density);
    let oct = i32(octaves);
    let spd = floor(speed);
    let t = time * TAU * spd;

    var p = st * freq;

    // Fractal octave summation
    var value = 0.0;
    var amplitude = 1.0;
    var totalAmp = 0.0;
    var pOct = p;

    for (var i: i32 = 0; i < 5; i = i + 1) {
        if (i >= oct) { break; }
        let octFreq = 1.0 + f32(i) * 0.5;
        let octSigma = sigma / (1.0 + f32(i) * 0.5);
        let fi = f32(i);
        value = value + amplitude * gaborNoise(pOct, octFreq, octSigma, baseAngle, iso, impulses, t + fi * 3.7, seed + fi * 17.0);
        totalAmp = totalAmp + amplitude;
        amplitude = amplitude * 0.5;
        pOct = pOct * 2.0;
    }
    value = value / totalAmp;

    let n = 1.0 / (1.0 + exp(-value * 3.0));
    return vec4<f32>(vec3<f32>(n), 1.0);
}

// WGSL version – WebGPU

/*
 * Gradient generator shader.
 * Renders linear, radial, conic, and four corners gradients with rotation and repeat.
 *
 * Uniforms are packed into a single struct (one uniform buffer) rather than
 * 12+ individual @binding uniforms: gradient otherwise hits the WebGPU
 * maxUniformBuffersPerShaderStage limit (12) once the universal tile globals
 * (tileOffset, fullResolution) are added, producing an invalid pipeline.
 * Packing layout is declared in this effect's own definition.js uniformLayout.
 */

struct Uniforms {
    data : array<vec4<f32>, 8>,
};

@group(0) @binding(0) var<uniform> uniforms : Uniforms;

// Values referenced by helper functions (set from `uniforms` in main).
var<private> resolution : vec2<f32>;
var<private> fullResolution : vec2<f32>;
var<private> seed : i32;
var<private> colorCount : i32;
var<private> color1 : vec3<f32>;
var<private> color2 : vec3<f32>;
var<private> color3 : vec3<f32>;
var<private> color4 : vec3<f32>;

const PI: f32 = 3.14159265359;
const TAU: f32 = 6.28318530718;

fn rotate2D(st: vec2<f32>, angle: f32) -> vec2<f32> {
    let fullRes = select(resolution, fullResolution, fullResolution.x > 0.0);
    let aspectRatio = fullRes.x / fullRes.y;
    var coord = st;
    coord.x = coord.x * aspectRatio;
    coord = coord - vec2<f32>(aspectRatio * 0.5, 0.5);
    let c = cos(angle);
    let s = sin(angle);
    coord = mat2x2<f32>(c, -s, s, c) * coord;
    coord = coord + vec2<f32>(aspectRatio * 0.5, 0.5);
    coord.x = coord.x / aspectRatio;
    return coord;
}

fn getColor(idx: i32) -> vec3<f32> {
    switch idx {
        case 0: { return color1; }
        case 1: { return color2; }
        case 2: { return color3; }
        default: { return color4; }
    }
}

// Blend colors based on a 0-1 parameter t, cycling through colorCount colors
fn blendColors(t_in: f32) -> vec3<f32> {
    let t = fract(t_in);
    let segment = t * f32(colorCount);
    let idx = i32(floor(segment));
    let localT = fract(segment);
    var next = idx + 1;
    if (next >= colorCount) { next = 0; }
    return mix(getColor(idx), getColor(next), localT);
}

// PCG PRNG for noise gradient
fn pcg(seed_in: vec3<u32>) -> vec3<u32> {
    var v = seed_in * 1664525u + 1013904223u;
    v.x = v.x + v.y * v.z;
    v.y = v.y + v.z * v.x;
    v.z = v.z + v.x * v.y;
    v = v ^ (v >> vec3<u32>(16u));
    v.x = v.x + v.y * v.z;
    v.y = v.y + v.z * v.x;
    v.z = v.z + v.x * v.y;
    return v;
}

fn prng(p0: vec3<f32>) -> vec3<f32> {
    var p = p0;
    if (p.x >= 0.0) { p.x = p.x * 2.0; } else { p.x = -p.x * 2.0 + 1.0; }
    if (p.y >= 0.0) { p.y = p.y * 2.0; } else { p.y = -p.y * 2.0 + 1.0; }
    if (p.z >= 0.0) { p.z = p.z * 2.0; } else { p.z = -p.z * 2.0 + 1.0; }
    let u = pcg(vec3<u32>(p));
    return vec3<f32>(u) / f32(0xffffffffu);
}

fn hash2D(p: vec2<f32>) -> f32 {
    return prng(vec3<f32>(p, f32(seed))).x;
}

fn valueNoise(p: vec2<f32>) -> f32 {
    let i = floor(p);
    let f = fract(p);
    let u = f * f * (3.0 - 2.0 * f);

    let a = hash2D(i);
    let b = hash2D(i + vec2<f32>(1.0, 0.0));
    let c = hash2D(i + vec2<f32>(0.0, 1.0));
    let d = hash2D(i + vec2<f32>(1.0, 1.0));

    return mix(mix(a, b, u.x), mix(c, d, u.x), u.y);
}

fn fbmNoise(p: vec2<f32>) -> f32 {
    var sum: f32 = 0.0;
    var amp: f32 = 0.5;
    var freq: f32 = 1.0;
    var maxVal: f32 = 0.0;
    for (var i: i32 = 0; i < 4; i = i + 1) {
        sum = sum + valueNoise(p * freq) * amp;
        maxVal = maxVal + amp;
        freq = freq * 2.0;
        amp = amp * 0.5;
    }
    return sum / maxVal;
}

@fragment
fn main(@builtin(position) pos: vec4<f32>) -> @location(0) vec4<f32> {
    resolution = uniforms.data[0].xy;
    let time = uniforms.data[0].z;
    let speed = uniforms.data[0].w;
    let rotation = uniforms.data[1].x;
    let gradientType = i32(uniforms.data[1].y);
    let repeat = i32(uniforms.data[1].z);
    colorCount = i32(uniforms.data[1].w);
    seed = i32(uniforms.data[2].x);
    color1 = uniforms.data[3].xyz;
    color2 = uniforms.data[4].xyz;
    color3 = uniforms.data[5].xyz;
    color4 = uniforms.data[6].xyz;
    let tileOffset = uniforms.data[7].xy;
    fullResolution = uniforms.data[7].zw;

    let fullRes = select(resolution, fullResolution, fullResolution.x > 0.0);
    let st = (pos.xy + tileOffset) / fullRes;
    let aspectRatio = fullRes.x / fullRes.y;

    // Convert rotation from degrees to radians
    let angle = -rotation * PI / 180.0;

    // Apply rotation for linear and conic gradients
    let rotatedSt = rotate2D(st, angle);

    // Centered coordinates for radial and conic
    var centered = st - 0.5;
    centered.x = centered.x * aspectRatio;

    // Rotated centered for conic
    let c = cos(angle);
    let s = sin(angle);
    let rotatedCentered = mat2x2<f32>(c, -s, s, c) * centered;

    var color: vec3<f32>;
    var t: f32;
    let timeOffset = time * speed;

    switch gradientType {
        case 0: {
            // Conic/angular gradient
            let a = atan2(rotatedCentered.y, rotatedCentered.x);
            t = (a + PI) / TAU;
            t = fract(t * f32(repeat) + timeOffset);
            color = blendColors(t);
        }
        case 1: {
            // Diamond gradient - L1 distance with rotation
            t = abs(rotatedCentered.x) + abs(rotatedCentered.y);
            t = fract(t * f32(repeat) + timeOffset);
            color = blendColors(t);
        }
        case 2: {
            // Four corners - bilinear interpolation
            // 4: TL=c1 TR=c2 BL=c3 BR=c4
            // 3: TL=c1 TR=c2 BL=c3 BR=c3
            // 2: TL=c1 TR=c1 BL=c2 BR=c2
            let cornerSt = rotate2D(st, angle);
            var cTL = color1;
            var cTR = color1;
            var cBL = color2;
            var cBR = color2;
            if (colorCount >= 3) {
                cTR = color2;
                cBL = color3;
                cBR = color3;
            }
            if (colorCount >= 4) {
                cBR = color4;
            }
            let top = mix(cTL, cTR, cornerSt.x);
            let bottom = mix(cBL, cBR, cornerSt.x);
            color = mix(bottom, top, cornerSt.y);
        }
        case 3: {
            // Linear gradient along rotated y-axis
            t = rotatedSt.y;
            t = fract(t * f32(repeat) + timeOffset);
            color = blendColors(t);
        }
        case 4: {
            // Noise gradient with rotation
            let noiseSt = rotatedCentered * 4.0;
            t = fbmNoise(noiseSt);
            t = fract(t * f32(repeat) + timeOffset);
            color = blendColors(t);
        }
        case 5: {
            // Radial gradient from center
            let rotatedPoint = mat2x2<f32>(c, -s, s, c) * centered;
            let dist = length(rotatedPoint) * 2.0;
            t = dist;
            t = fract(t * f32(repeat) + timeOffset);
            color = blendColors(t);
        }
        case 6: {
            // Spiral gradient - angle + distance
            let a = atan2(rotatedCentered.y, rotatedCentered.x);
            let dist = length(centered);
            t = fract(a / TAU + dist * 2.0);
            t = fract(t * f32(repeat) + timeOffset);
            color = blendColors(t);
        }
        default: {
            color = color1;
        }
    }

    return vec4<f32>(color, 1.0);
}

/*
 * Julia set explorer — state-of-the-art (WGSL backend)
 *
 * Grayscale value output [0,1]. Alpha = 1.0 (synth effect).
 * Iteration: z = z² + c, z₀ = pixel, c = Julia constant.
 * Derivative: dz/dz₀ for distance estimation (no +1 term — c is constant).
 *
 * All coordinate and iteration math uses df64 (double-float emulation).
 * Single iteration loop computes all output values simultaneously.
 * Output mode selects which value to emit.
 */

struct Uniforms {
    // Slot 0: resolution.xy, time, (unused)
    // Slot 1: cReal, cImag, poi, outputMode
    // Slot 2: centerX, centerY, rotation, (unused)
    // Slot 3: iterations, stripeFreq, trapShape, lightAngle
    // Slot 4: cPath, cSpeed, cRadius, invert
    // Slot 5: zoomSpeed, zoomDepth, (unused), (unused)
    data: array<vec4<f32>, 7>,
};

@group(0) @binding(0) var<uniform> uniforms: Uniforms;

const PI: f32 = 3.14159265359;
const TAU: f32 = 6.28318530718;
const BAILOUT: f32 = 256.0;
const LOG2: f32 = 0.6931471805599453;

// ============================================================================
// POI c-values (famous Julia sets)
// ============================================================================

fn getPOI(idx: i32) -> vec2<f32> {
    if (idx == 1) { return vec2<f32>(-0.123, 0.745); }         // Douady's rabbit
    if (idx == 2) { return vec2<f32>(-0.3905, 0.5868); }       // Siegel disk
    if (idx == 3) { return vec2<f32>(0.0, 1.0); }              // Dendrite
    if (idx == 4) { return vec2<f32>(-1.0, 0.0); }             // Basilica
    if (idx == 5) { return vec2<f32>(-0.7455, 0.1130); }       // Spiral galaxy
    if (idx == 6) { return vec2<f32>(-0.0986, 0.6534); }       // Lightning
    if (idx == 7) { return vec2<f32>(-0.8, 0.156); }           // Dragon curve
    if (idx == 8) { return vec2<f32>(-0.75, 0.0); }            // San Marco
    if (idx == 9) { return vec2<f32>(-0.5792, 0.5385); }       // Starfish
    if (idx == 10) { return vec2<f32>(0.28, 0.008); }          // Double spiral
    return vec2<f32>(-0.123, 0.745);
}

// ============================================================================
// Animated c-paths
// ============================================================================

fn getAnimatedC(pathType: i32, t: f32, radius: f32) -> vec2<f32> {
    let theta = t * TAU;
    if (pathType == 1) {
        return vec2<f32>(
            cos(theta) * 0.5 - cos(2.0 * theta) * 0.25,
            sin(theta) * 0.5 - sin(2.0 * theta) * 0.25
        );
    }
    if (pathType == 2) {
        return vec2<f32>(cos(theta), sin(theta)) * radius;
    }
    if (pathType == 3) {
        return vec2<f32>(-1.0 + cos(theta) * 0.25, sin(theta) * 0.25);
    }
    return vec2<f32>(0.0, 0.0);
}

// ============================================================================
// Complex multiply
// ============================================================================

fn cmul(a: vec2<f32>, b: vec2<f32>) -> vec2<f32> {
    return vec2<f32>(a.x * b.x - a.y * b.y, a.x * b.y + a.y * b.x);
}

// ============================================================================
// Double-float emulation (df64) — two f32s = ~15 decimal digits
// ============================================================================

fn df64_from(a: f32) -> vec2<f32> {
    return vec2<f32>(a, 0.0);
}

fn df64_add(a: vec2<f32>, b: vec2<f32>) -> vec2<f32> {
    let s = a.x + b.x;
    let v = s - a.x;
    let e = (a.x - (s - v)) + (b.x - v);
    return vec2<f32>(s, e + a.y + b.y);
}

fn df64_sub(a: vec2<f32>, b: vec2<f32>) -> vec2<f32> {
    return df64_add(a, vec2<f32>(-b.x, -b.y));
}

fn df64_split(a: f32) -> vec2<f32> {
    let t = 4097.0 * a; // 2^12 + 1
    let hi = t - (t - a);
    return vec2<f32>(hi, a - hi);
}

fn df64_mul(a: vec2<f32>, b: vec2<f32>) -> vec2<f32> {
    let p = a.x * b.x;
    let as_ = df64_split(a.x);
    let bs = df64_split(b.x);
    var e = ((as_.x * bs.x - p) + as_.x * bs.y + as_.y * bs.x) + as_.y * bs.y;
    e = e + a.x * b.y + a.y * b.x;
    return vec2<f32>(p, e);
}

fn df64_mul_f(a: vec2<f32>, b: f32) -> vec2<f32> {
    let p = a.x * b;
    let as_ = df64_split(a.x);
    let bs = df64_split(b);
    var e = ((as_.x * bs.x - p) + as_.x * bs.y + as_.y * bs.x) + as_.y * bs.y;
    e = e + a.y * b;
    return vec2<f32>(p, e);
}

// ============================================================================
// Resolve c-value from POI/path/manual
// ============================================================================

fn resolveC(poi: i32, cPath: i32, time: f32, cSpeed: f32, cRadius: f32, cReal: f32, cImag: f32) -> vec2<f32> {
    if (poi > 0) { return getPOI(poi); }
    if (cPath > 0) { return getAnimatedC(cPath, time * cSpeed, cRadius); }
    return vec2<f32>(cReal, cImag);
}

// ============================================================================
// df64 coordinate transform
// ============================================================================

fn transformCoords(fragCoord: vec2<f32>, resolution: vec2<f32>,
                   cx: f32, cy: f32, zm: f32, rot: f32)
                   -> array<vec2<f32>, 2> {
    var uv = (fragCoord - 0.5 * resolution) / min(resolution.x, resolution.y);
    let angle = -rot * TAU / 360.0;
    let cs = cos(angle);
    let sn = sin(angle);
    uv = mat2x2<f32>(cs, -sn, sn, cs) * uv;

    let scale = 2.5 / zm;
    let reDF = df64_add(df64_mul_f(df64_from(uv.x), scale), df64_from(cx));
    let imDF = df64_add(df64_mul_f(df64_from(uv.y), scale), df64_from(cy));
    return array<vec2<f32>, 2>(reDF, imDF);
}

// ============================================================================
// Unified Julia iteration — df64 z-iteration, all output values in one loop
// ============================================================================

struct JuliaResult {
    iter: f32,
    zMag2: f32,
    dzMag2: f32,
    stripeSum: f32,
    stripeCount: f32,
    stripeLast: f32,
    trapMin: f32,
};

fn juliaIterate(z0Re: vec2<f32>, z0Im: vec2<f32>, c: vec2<f32>,
                maxIter: i32, freq: f32, trap: i32) -> JuliaResult {
    var zRe = z0Re;
    var zIm = z0Im;
    var dz = vec2<f32>(1.0, 0.0);
    var i: f32 = 0.0;
    var stripeSum: f32 = 0.0;
    var stripeLast: f32 = 0.0;
    var stripeCount: f32 = 0.0;
    var trapMin: f32 = 1e10;
    let bail2 = BAILOUT * BAILOUT;

    var zSlow = vec2<f32>(z0Re.x, z0Im.x);
    var period: i32 = 0;

    for (var n: i32 = 0; n < 1000; n = n + 1) {
        if (n >= maxIter) { break; }

        // Derivative: dz = 2*z*dz (float32 using hi parts)
        let zF = vec2<f32>(zRe.x, zIm.x);
        dz = 2.0 * cmul(zF, dz);

        // Iteration: z = z² + c in df64
        let zRe2 = df64_mul(zRe, zRe);
        let zIm2 = df64_mul(zIm, zIm);
        let zReIm = df64_mul(zRe, zIm);

        zRe = df64_add(df64_sub(zRe2, zIm2), df64_from(c.x));
        zIm = df64_add(df64_mul_f(zReIm, 2.0), df64_from(c.y));

        // Bailout check (float32 hi parts)
        let zMag2 = zRe.x * zRe.x + zIm.x * zIm.x;
        if (zMag2 > bail2) { break; }

        i = i + 1.0;

        // Stripe average accumulation (float32 from hi parts)
        let zHi = vec2<f32>(zRe.x, zIm.x);
        if (freq > 0.0) {
            stripeLast = 0.5 * sin(freq * atan2(zHi.y, zHi.x)) + 0.5;
            stripeSum = stripeSum + stripeLast;
            stripeCount = stripeCount + 1.0;
        }

        // Orbit trap accumulation
        var td: f32;
        if (trap == 0) {
            td = length(zHi);
        } else if (trap == 1) {
            td = min(abs(zHi.x), abs(zHi.y));
        } else {
            td = abs(length(zHi) - 1.0);
        }
        trapMin = min(trapMin, td);

        // Period detection
        period = period + 1;
        if (period == 20) {
            period = 0;
            zSlow = zHi;
        } else if (distance(zHi, zSlow) < 1e-10) {
            i = f32(maxIter);
            break;
        }
    }

    var r: JuliaResult;
    r.iter = i;
    r.zMag2 = zRe.x * zRe.x + zIm.x * zIm.x;
    r.dzMag2 = dot(dz, dz);
    r.stripeSum = stripeSum;
    r.stripeCount = stripeCount;
    r.stripeLast = stripeLast;
    r.trapMin = trapMin;
    return r;
}

// ============================================================================
// Output extraction from unified result
// ============================================================================

fn outputSmoothIteration(r: JuliaResult, maxIter: f32) -> f32 {
    if (r.iter >= maxIter) { return 0.0; }
    let log_zn = log(r.zMag2) * 0.5;
    let nu = log(log_zn / LOG2) / LOG2;
    return clamp((r.iter + 1.0 - nu) / maxIter, 0.0, 1.0);
}

fn outputDistanceEstimation(r: JuliaResult, maxIter: f32) -> f32 {
    if (r.iter >= maxIter) { return 0.0; }
    let zMag = sqrt(r.zMag2);
    let dzMag = sqrt(r.dzMag2);
    if (dzMag < 1e-10) { return 0.0; }
    let dist = 2.0 * zMag * log(zMag) / dzMag;
    return clamp(log(dist + 1.0) * 2.0, 0.0, 1.0);
}

fn outputStripeAverage(r: JuliaResult, maxIter: f32) -> f32 {
    if (r.iter >= maxIter) { return 0.0; }
    if (r.stripeCount < 1.0) { return 0.0; }
    let avg = r.stripeSum / r.stripeCount;
    var prevAvg = avg;
    if (r.stripeCount > 1.0) { prevAvg = (r.stripeSum - r.stripeLast) / (r.stripeCount - 1.0); }
    let log_zn = log(r.zMag2) * 0.5;
    let nu = log(log_zn / LOG2) / LOG2;
    let frac = clamp(1.0 - nu + floor(nu), 0.0, 1.0);
    return clamp(mix(prevAvg, avg, frac), 0.0, 1.0);
}

fn outputOrbitTrap(r: JuliaResult, maxIter: f32) -> f32 {
    if (r.iter >= maxIter) { return 0.0; }
    return clamp(1.0 - r.trapMin, 0.0, 1.0);
}

// ============================================================================
// Normal map — runs iteration 3 times for finite differences
// ============================================================================

fn iterateSmooth(fragCoord: vec2<f32>, c: vec2<f32>, maxIter: i32,
                 resolution: vec2<f32>, cx: f32, cy: f32, zm: f32, rot: f32) -> f32 {
    let coords = transformCoords(fragCoord, resolution, cx, cy, zm, rot);
    var zRe = coords[0];
    var zIm = coords[1];
    var i: f32 = 0.0;
    let bail2 = BAILOUT * BAILOUT;

    for (var n: i32 = 0; n < 1000; n = n + 1) {
        if (n >= maxIter) { break; }

        let zRe2 = df64_mul(zRe, zRe);
        let zIm2 = df64_mul(zIm, zIm);
        let zReIm = df64_mul(zRe, zIm);

        zRe = df64_add(df64_sub(zRe2, zIm2), df64_from(c.x));
        zIm = df64_add(df64_mul_f(zReIm, 2.0), df64_from(c.y));

        let zMag2 = zRe.x * zRe.x + zIm.x * zIm.x;
        if (zMag2 > bail2) { break; }
        i = i + 1.0;
    }

    if (i >= f32(maxIter)) { return 0.0; }
    let zMag2 = zRe.x * zRe.x + zIm.x * zIm.x;
    let log_zn = log(zMag2) * 0.5;
    let nu = log(log_zn / LOG2) / LOG2;
    return clamp((i + 1.0 - nu) / f32(maxIter), 0.0, 1.0);
}

fn outputNormalMap(fragCoord: vec2<f32>, c: vec2<f32>, maxIter: i32, angle: f32,
                   resolution: vec2<f32>, cx: f32, cy: f32, zm: f32, rot: f32) -> f32 {
    let d0 = iterateSmooth(fragCoord, c, maxIter, resolution, cx, cy, zm, rot);
    let d1 = iterateSmooth(fragCoord + vec2<f32>(1.0, 0.0), c, maxIter, resolution, cx, cy, zm, rot);
    let d2 = iterateSmooth(fragCoord + vec2<f32>(0.0, 1.0), c, maxIter, resolution, cx, cy, zm, rot);

    let normal = normalize(vec3<f32>(d1 - d0, d2 - d0, 0.05));
    let rad = angle * TAU / 360.0;
    let lightDir = normalize(vec3<f32>(cos(rad), sin(rad), 0.7));
    return clamp(max(dot(normal, lightDir), 0.0), 0.0, 1.0);
}

// ============================================================================
// Main
// ============================================================================

@fragment
fn main(@builtin(position) pos: vec4<f32>) -> @location(0) vec4<f32> {
    // Unpack uniforms
    let resolution = uniforms.data[0].xy;
    let time = uniforms.data[0].z;

    let cReal = uniforms.data[1].x;
    let cImag = uniforms.data[1].y;
    let poi = i32(uniforms.data[1].z);
    let outputMode = i32(uniforms.data[1].w);

    let centerX = uniforms.data[2].x;
    let centerY = uniforms.data[2].y;
    let rotation = uniforms.data[2].z;

    let iterations = i32(uniforms.data[3].x);
    let stripeFreq = uniforms.data[3].y;
    let trapShape = i32(uniforms.data[3].z);
    let lightAngle = uniforms.data[3].w;

    let cPath = i32(uniforms.data[4].x);
    let cSpeed = uniforms.data[4].y;
    let cRadius = uniforms.data[4].z;
    let invertFlag = uniforms.data[4].w;

    let zoomSpeed = uniforms.data[5].x;
    let zoomDepth = uniforms.data[5].y;

    let tileOffset = uniforms.data[6].xy;
    let fullResolution = uniforms.data[6].zw;

    // Resolve c-value
    let c = resolveC(poi, cPath, time, cSpeed, cRadius, cReal, cImag);

    // Zoom: sinusoidal when animated, static pow(10, depth) when not
    var effectiveZoom: f32;
    if (zoomSpeed > 0.0) {
        let phase = 0.5 * (1.0 - cos(time * zoomSpeed * TAU));
        effectiveZoom = pow(10.0, zoomDepth * phase);
    } else {
        effectiveZoom = pow(10.0, zoomDepth);
    }

    // Compute output
    var value: f32;

    if (outputMode == 4) {
        value = outputNormalMap(pos.xy + tileOffset, c, iterations, lightAngle, fullResolution, centerX, centerY, effectiveZoom, rotation);
    } else {
        let coords = transformCoords(pos.xy + tileOffset, fullResolution, centerX, centerY, effectiveZoom, rotation);
        let r = juliaIterate(coords[0], coords[1], c, iterations, stripeFreq, trapShape);

        if (outputMode == 0) {
            value = outputSmoothIteration(r, f32(iterations));
        } else if (outputMode == 1) {
            value = outputDistanceEstimation(r, f32(iterations));
        } else if (outputMode == 2) {
            value = outputStripeAverage(r, f32(iterations));
        } else if (outputMode == 3) {
            value = outputOrbitTrap(r, f32(iterations));
        } else {
            value = outputSmoothIteration(r, f32(iterations));
        }
    }

    // Invert
    if (invertFlag > 0.5) {
        value = 1.0 - value;
    }

    return vec4<f32>(vec3<f32>(value), 1.0);
}

// WGSL version – WebGPU
struct Uniforms {
    resolution: vec2<f32>,
    aspect: f32,
    time: f32,
    scale: f32,
    rotation: f32,
    thickness: f32,
    smoothness: f32,
    speed: f32,
    pulseDepth: f32,
    layerSpacing: f32,
    twist: f32,
    shapeGrowth: f32,
    symmetry: i32,
    layers: i32,
    shape: i32,
    bindu: i32,
    animation: i32,
    fgColor: vec3<f32>,
    bgColor: vec3<f32>,
    tileOffset: vec2<f32>,
    fullResolution: vec2<f32>,
    renderScale: f32,
}
@group(0) @binding(0) var<uniform> u: Uniforms;

const PI: f32 = 3.14159265359;
const TAU: f32 = 6.28318530718;
const SQRT3: f32 = 1.7320508075688772;

const SHAPE_PETAL: i32 = 0;
const SHAPE_TRIANGLE: i32 = 1;
const SHAPE_DOT: i32 = 2;

const ANIM_ROTATE: i32 = 1;
const ANIM_PULSE: i32 = 2;
const ANIM_DIFFERENTIAL: i32 = 3;
const ANIM_COUNTERROTATE: i32 = 4;
const ANIM_SPIRALWAVE: i32 = 5;
const ANIM_RIPPLE: i32 = 6;

// GLSL-style mod() — always non-negative when b > 0.
fn floorMod(a: f32, b: f32) -> f32 {
    return a - b * floor(a / b);
}

fn rotate2D(p: vec2<f32>, angle: f32) -> vec2<f32> {
    let c = cos(angle);
    let s = sin(angle);
    return vec2<f32>(p.x * c - p.y * s, p.x * s + p.y * c);
}

fn sdEquilateralTriangle(p_in: vec2<f32>, r: f32) -> f32 {
    let k = SQRT3;
    var p = vec2<f32>(abs(p_in.x) - r, p_in.y + r / k);
    if (p.x + k * p.y > 0.0) {
        p = vec2<f32>(p.x - k * p.y, -k * p.x - p.y) / 2.0;
    }
    p.x = p.x - clamp(p.x, -2.0 * r, 0.0);
    return -length(p) * sign(p.y);
}

fn fillEdge(d: f32) -> f32 {
    return smoothstep(u.smoothness, -u.smoothness, d);
}

fn mandalaMask(p: vec2<f32>) -> f32 {
    let r = length(p);
    let theta = atan2(p.y, p.x) - PI * 0.5;
    let wedge = TAU / f32(u.symmetry);
    let twistRad = u.twist * PI / 180.0;
    let baseSize = 0.25 + u.thickness * 0.65;

    // spiralWave: twist oscillates over the cycle using `twist` as amplitude.
    var dynTwistRad = twistRad;
    if (u.animation == ANIM_SPIRALWAVE) {
        dynTwistRad = twistRad * sin(u.time * TAU * floor(u.speed));
    }

    var m: f32 = 0.0;

    if (u.bindu != 0) {
        let dBindu = length(p) - (0.15 + u.thickness * 0.15);
        m = max(m, fillEdge(dBindu));
    }

    for (var i: i32 = 0; i < 12; i = i + 1) {
        if (i >= u.layers) { break; }
        let Rlayer = f32(i + 1) * u.layerSpacing;

        // Per-layer animation rotation.
        var layerAnimRot: f32 = 0.0;
        if (u.animation == ANIM_DIFFERENTIAL) {
            layerAnimRot = u.time * TAU * (floor(u.speed) + f32(i));
        } else if (u.animation == ANIM_COUNTERROTATE) {
            var dir: f32 = 1.0;
            if (floorMod(f32(i), 2.0) >= 0.5) {
                dir = -1.0;
            }
            layerAnimRot = u.time * TAU * floor(u.speed) * dir;
        }

        let layerTheta = theta - f32(i) * dynTwistRad - layerAnimRot;
        let folded = abs(floorMod(layerTheta + wedge * 0.5, wedge) - wedge * 0.5);
        let radial = r - Rlayer;
        let tangent = folded * Rlayer;

        var lt: f32 = 0.0;
        if (u.layers > 1) {
            lt = f32(i) / f32(u.layers - 1) - 0.5;
        }
        var shapeSize = baseSize * (1.0 + u.shapeGrowth * lt);

        // ripple: per-layer pulse with phase offset.
        if (u.animation == ANIM_RIPPLE) {
            shapeSize = shapeSize * (1.0 + u.pulseDepth * sin(u.time * TAU * floor(u.speed) - f32(i) * 0.6));
        }

        if (u.shape == SHAPE_PETAL) {
            let d = length(vec2<f32>(radial * 0.55, tangent)) - shapeSize;
            m = max(m, fillEdge(d));
        } else if (u.shape == SHAPE_TRIANGLE) {
            let q = vec2<f32>(tangent, -radial);
            let d = sdEquilateralTriangle(q, shapeSize);
            m = max(m, fillEdge(d));
        } else {
            let d = length(vec2<f32>(radial, tangent)) - shapeSize * 0.7;
            m = max(m, fillEdge(d));
        }
    }
    return m;
}

@fragment
fn main(@builtin(position) position: vec4<f32>) -> @location(0) vec4<f32> {
    let globalCoord = position.xy + u.tileOffset;
    var st = globalCoord / u.fullResolution;
    st = (st - vec2<f32>(0.5, 0.5)) * 2.0;
    st.x = st.x * u.aspect;

    let rad = u.rotation * PI / 180.0;
    st = rotate2D(st, rad);

    if (u.animation == ANIM_ROTATE) {
        st = rotate2D(st, u.time * TAU * floor(u.speed));
    }

    var scaleFactor = 21.0 - u.scale;
    if (u.animation == ANIM_PULSE) {
        scaleFactor = scaleFactor * (1.0 + u.pulseDepth * sin(u.time * TAU * floor(u.speed)));
    }

    let p = st * scaleFactor;

    let m = clamp(mandalaMask(p), 0.0, 1.0);
    let color = mix(u.bgColor, u.fgColor, m);
    return vec4<f32>(color, 1.0);
}

/*
 * synth/mandelbrot — State-of-the-art Mandelbrot explorer (WGSL)
 *
 * WGSL port of the GLSL implementation. Same algorithms:
 * df64 deep zoom, 5 output modes, POI animated zoom.
 */

struct Uniforms {
    // Slot 0: resolution.xy, time, (unused)
    // Slot 1: poi, outputMode, iterations, (unused)
    // Slot 2: centerHiX, centerHiY, centerLoX, centerLoY
    // Slot 3: zoom, zoomSpeed, zoomDepth, invert
    // Slot 4: stripeFreq, trapShape, lightAngle, rotation
    // Slot 5: tileOffset.xy, fullResolution.xy
    data: array<vec4<f32>, 6>,
}

@group(0) @binding(0) var<uniform> uniforms: Uniforms;

const PI: f32 = 3.14159265359;
const TAU: f32 = 6.28318530718;
const BAILOUT: f32 = 256.0;
const LOG2: f32 = 0.6931471805599453;
const MAX_ITER: i32 = 2048;

// ============================================================================
// df64 arithmetic
// ============================================================================

fn df64_quick_two_sum(a: f32, b: f32) -> vec2<f32> {
    let s = a + b;
    let e = b - (s - a);
    return vec2<f32>(s, e);
}

fn df64_two_sum(a: f32, b: f32) -> vec2<f32> {
    let s = a + b;
    let v = s - a;
    let e = (a - (s - v)) + (b - v);
    return vec2<f32>(s, e);
}

// Dekker's split method for error-free product
fn df64_two_prod(a: f32, b: f32) -> vec2<f32> {
    let p = a * b;
    let ca = 4097.0 * a;
    let ah = ca - (ca - a);
    let al = a - ah;
    let cb = 4097.0 * b;
    let bh = cb - (cb - b);
    let bl = b - bh;
    let e = ((ah * bh - p) + ah * bl + al * bh) + al * bl;
    return vec2<f32>(p, e);
}

fn df64_add(a: vec2<f32>, b: vec2<f32>) -> vec2<f32> {
    var s = df64_two_sum(a.x, b.x);
    s.y = s.y + a.y + b.y;
    return df64_quick_two_sum(s.x, s.y);
}

fn df64_sub(a: vec2<f32>, b: vec2<f32>) -> vec2<f32> {
    return df64_add(a, vec2<f32>(-b.x, -b.y));
}

fn df64_mul(a: vec2<f32>, b: vec2<f32>) -> vec2<f32> {
    var p = df64_two_prod(a.x, b.x);
    p.y = p.y + a.x * b.y + a.y * b.x;
    return df64_quick_two_sum(p.x, p.y);
}

fn df64_mul_f(a: vec2<f32>, b: f32) -> vec2<f32> {
    var p = df64_two_prod(a.x, b);
    p.y = p.y + a.y * b;
    return df64_quick_two_sum(p.x, p.y);
}

fn df64_from(a: f32) -> vec2<f32> {
    return vec2<f32>(a, 0.0);
}

fn df64_to_float(a: vec2<f32>) -> f32 {
    return a.x + a.y;
}

// ============================================================================
// Points of Interest
// ============================================================================

struct PoiCoords {
    cX: vec2<f32>,
    cY: vec2<f32>,
}

fn getPoiMaxZoom(index: i32) -> f32 {
    if (index == 2 || index == 7) { return 7.0; }   // 5-8 digit coords
    if (index == 8) { return 10.0; }                  // 10 digit coords
    return 14.0;                                       // full df64 precision
}

fn getPOI(index: i32, centerHiX: f32, centerLoX: f32, centerHiY: f32, centerLoY: f32) -> PoiCoords {
    // Verified from authoritative sources (MROB, superliminal, fractaljourney)
    if (index == 1) { // seahorseValley — MROB embedded Julia nucleus
        return PoiCoords(vec2<f32>(-0.7445398569107056, -3.4452027897e-9),
                         vec2<f32>( 0.12172377109527588, 2.7991489404e-9));
    } else if (index == 2) { // elephantValley — MROB
        return PoiCoords(vec2<f32>( 0.29833000898361206, -8.9836120765e-9),
                         vec2<f32>( 0.0011099999537691474, 4.6230852696e-11));
    } else if (index == 3) { // scepterValley — period-3 nucleus
        return PoiCoords(vec2<f32>(-1.7548776865005493, 2.0253856592e-8),
                         vec2<f32>( 0.0, 0.0));
    } else if (index == 4) { // miniBrot — fractaljourney verified
        return PoiCoords(vec2<f32>(-1.7400623559951782, -2.6584161761e-8),
                         vec2<f32>( 0.028175339102745056, 6.7646594229e-10));
    } else if (index == 5) { // feigenbaum — Myrberg-Feigenbaum constant
        return PoiCoords(vec2<f32>(-1.4011552333831787, 4.4291128098e-8),
                         vec2<f32>( 0.0, 0.0));
    } else if (index == 6) { // birdOfParadise — superliminal verified
        return PoiCoords(vec2<f32>( 0.37500011920928955, 8.5257595428e-10),
                         vec2<f32>(-0.21663938462734222, -3.8103704636e-9));
    } else if (index == 7) { // spiralGalaxy — MROB seahorse double hook
        return PoiCoords(vec2<f32>(-0.7445389032363892, -1.6763610833e-8),
                         vec2<f32>( 0.12172418087720871, -8.7720870845e-10));
    } else if (index == 8) { // doubleSpiral — MROB seahorse medallion
        return PoiCoords(vec2<f32>(-1.2553445100784302, -1.4721569741e-8),
                         vec2<f32>(-0.3822004497051239, -1.3294876089e-8));
    }
    return PoiCoords(vec2<f32>(centerHiX, centerLoX), vec2<f32>(centerHiY, centerLoY));
}

// ============================================================================
// Coordinate transform
// ============================================================================

struct Df64Pair {
    re: vec2<f32>,
    im: vec2<f32>,
}

fn transformCoords_df64(fragCoord: vec2<f32>, resolution: vec2<f32>,
                        cX_df: vec2<f32>, cY_df: vec2<f32>,
                        z: f32, rot: f32) -> Df64Pair {
    var uv = (fragCoord - 0.5 * resolution) / min(resolution.x, resolution.y);
    let angle = -rot * TAU / 360.0;
    let c = cos(angle);
    let s = sin(angle);
    // Match GLSL mat2(c, -s, s, c) column-major rotation
    uv = vec2<f32>(c * uv.x + s * uv.y, -s * uv.x + c * uv.y);

    let scale = 2.5 / z;
    let re = df64_add(df64_from(uv.x * scale), cX_df);
    let im = df64_add(df64_from(uv.y * scale), cY_df);
    return Df64Pair(re, im);
}

// ============================================================================
// Early-out tests
// ============================================================================

fn inCardioid(x: f32, y: f32) -> bool {
    let y2 = y * y;
    let q = (x - 0.25) * (x - 0.25) + y2;
    return q * (q + (x - 0.25)) <= 0.25 * y2;
}

fn inPeriod2Bulb(x: f32, y: f32) -> bool {
    let xp1 = x + 1.0;
    return xp1 * xp1 + y * y <= 0.0625;
}

// ============================================================================
// Orbit trap
// ============================================================================

fn trapDistance(z: vec2<f32>, shape: i32) -> f32 {
    if (shape == 0) {
        return length(z);
    } else if (shape == 1) {
        return min(abs(z.x), abs(z.y));
    } else {
        return abs(length(z) - 1.0);
    }
}

// ============================================================================
// Iteration result
// ============================================================================

struct IterResult {
    smoothIter: f32,
    rawIter: f32,
    z_final: vec2<f32>,
    dz_final: vec2<f32>,
    stripeAcc: f32,
    trapMin: f32,
}

// ============================================================================
// df64 iteration — deep precision
// ============================================================================

fn mandelbrot_df64(c_re: vec2<f32>, c_im: vec2<f32>, maxIter: i32,
                   sFreq: f32, tShape: i32) -> IterResult {
    let cx = df64_to_float(c_re);
    let cy = df64_to_float(c_im);
    if (inCardioid(cx, cy) || inPeriod2Bulb(cx, cy)) {
        return IterResult(f32(maxIter), f32(maxIter), vec2<f32>(0.0), vec2<f32>(0.0), 0.0, 1e20);
    }

    var zr = vec2<f32>(0.0, 0.0);
    var zi = vec2<f32>(0.0, 0.0);
    var dz = vec2<f32>(1.0, 0.0);
    var stripe: f32 = 0.0;
    var trap: f32 = 1e20;
    var i: f32 = 0.0;

    for (var n: i32 = 0; n < MAX_ITER; n = n + 1) {
        if (n >= maxIter) { break; }

        let zx = df64_to_float(zr);
        let zy = df64_to_float(zi);

        dz = vec2<f32>(
            2.0 * (zx * dz.x - zy * dz.y) + 1.0,
            2.0 * (zx * dz.y + zy * dz.x)
        );

        let zr2 = df64_mul(zr, zr);
        let zi2 = df64_mul(zi, zi);
        let zri = df64_mul(zr, zi);
        let new_zr = df64_add(df64_sub(zr2, zi2), c_re);
        let new_zi = df64_add(df64_mul_f(zri, 2.0), c_im);
        zr = new_zr;
        zi = new_zi;

        let post_zx = df64_to_float(zr);
        let post_zy = df64_to_float(zi);
        let post_mag2 = post_zx * post_zx + post_zy * post_zy;

        if (sFreq > 0.0) {
            stripe = stripe + sin(sFreq * atan2(post_zy, post_zx));
        }
        trap = min(trap, trapDistance(vec2<f32>(post_zx, post_zy), tShape));

        if (post_mag2 > BAILOUT * BAILOUT) { break; }
        i = i + 1.0;
    }

    let fx = df64_to_float(zr);
    let fy = df64_to_float(zi);
    let z_final = vec2<f32>(fx, fy);

    var smoothI = i;
    let mag2 = dot(z_final, z_final);
    if (i < f32(maxIter) && mag2 > 1.0) {
        let log_zn = log(mag2) * 0.5;
        let nu = log(log_zn / LOG2) / LOG2;
        smoothI = i + 1.0 - nu;
    }

    return IterResult(smoothI, i, z_final, dz, stripe, trap);
}

// ============================================================================
// Output algorithms
// ============================================================================

fn outputSmoothIteration(smoothI: f32, rawI: f32, maxIter: i32) -> f32 {
    if (rawI >= f32(maxIter)) { return 0.0; }
    return smoothI / f32(maxIter);
}

fn outputDistance(z: vec2<f32>, dz: vec2<f32>, rawI: f32, maxIter: i32) -> f32 {
    if (rawI >= f32(maxIter)) { return 0.0; }
    let mag = length(z);
    let dmag = length(dz);
    if (dmag == 0.0) { return 0.0; }
    let dist = 2.0 * mag * log(mag) / dmag;
    return clamp(sqrt(dist * f32(maxIter)) * 0.5, 0.0, 1.0);
}

fn outputStripeAverage(smoothI: f32, rawI: f32, stripeAcc: f32, maxIter: i32) -> f32 {
    if (rawI >= f32(maxIter)) { return 0.0; }
    let count = max(rawI, 1.0);
    let avg = stripeAcc / count;
    let frac = smoothI - floor(smoothI);
    return clamp(0.5 + 0.5 * avg * (1.0 - frac), 0.0, 1.0);
}

fn outputOrbitTrap(trapMin: f32, rawI: f32, maxIter: i32) -> f32 {
    if (rawI >= f32(maxIter)) { return 0.0; }
    return clamp(1.0 - trapMin * 0.5, 0.0, 1.0);
}

// ============================================================================
// Normal map helpers
// ============================================================================

fn computeDistAt_df64(fragCoord: vec2<f32>, resolution: vec2<f32>,
                      cX_df: vec2<f32>, cY_df: vec2<f32>, z_zoom: f32, rot: f32,
                      maxIter: i32, sFreq: f32, tShape: i32) -> f32 {
    let coords = transformCoords_df64(fragCoord, resolution, cX_df, cY_df, z_zoom, rot);
    let r = mandelbrot_df64(coords.re, coords.im, maxIter, sFreq, tShape);
    return outputDistance(r.z_final, r.dz_final, r.rawIter, maxIter);
}

fn outputNormalMap(fragCoord: vec2<f32>, resolution: vec2<f32>,
                   cX_df: vec2<f32>, cY_df: vec2<f32>,
                   z_zoom: f32, rot: f32, maxIter: i32, angle: f32,
                   sFreq: f32, tShape: i32) -> f32 {
    let eps = 1.0 / min(resolution.x, resolution.y);
    let h0 = computeDistAt_df64(fragCoord, resolution, cX_df, cY_df, z_zoom, rot, maxIter, sFreq, tShape);
    let hx = computeDistAt_df64(fragCoord + vec2<f32>(1.0, 0.0), resolution, cX_df, cY_df, z_zoom, rot, maxIter, sFreq, tShape);
    let hy = computeDistAt_df64(fragCoord + vec2<f32>(0.0, 1.0), resolution, cX_df, cY_df, z_zoom, rot, maxIter, sFreq, tShape);

    let normal = normalize(vec3<f32>(h0 - hx, h0 - hy, eps));
    let rad = angle * TAU / 360.0;
    let lightDir = normalize(vec3<f32>(cos(rad), sin(rad), 0.7));
    return clamp(dot(normal, lightDir), 0.0, 1.0);
}

// ============================================================================
// Main
// ============================================================================

@fragment
fn main(@builtin(position) pos: vec4<f32>) -> @location(0) vec4<f32> {
    let resolution = uniforms.data[0].xy;
    let time = uniforms.data[0].z;

    let poi = i32(uniforms.data[1].x);
    let outputMode = i32(uniforms.data[1].y);
    let iterations = i32(uniforms.data[1].z);

    let centerHiX = uniforms.data[2].x;
    let centerHiY = uniforms.data[2].y;
    let centerLoX = uniforms.data[2].z;
    let centerLoY = uniforms.data[2].w;

    let zoomSpeed = uniforms.data[3].x;
    let zoomDepth = uniforms.data[3].y;
    let invertVal = uniforms.data[3].z;
    let stripeFreq = uniforms.data[3].w;

    let trapShape = i32(uniforms.data[4].x);
    let lightAngle = uniforms.data[4].y;
    let rotation = uniforms.data[4].z;

    let tileOffset = uniforms.data[5].xy;
    let fullResolution = uniforms.data[5].zw;
    let globalCoord = pos.xy + tileOffset;

    let maxIter = min(iterations, MAX_ITER);

    // Clamp zoom depth to POI coordinate precision
    let maxDepth = select(14.0, getPoiMaxZoom(poi), poi > 0);
    let effDepth = min(zoomDepth, maxDepth);
    var effZoom: f32;
    if (zoomSpeed > 0.0) {
        // Sinusoidal zoom: t=0 zoomed out, t=0.5/speed max depth, t=1/speed zoomed out
        let zoomPhase = 0.5 * (1.0 - cos(time * zoomSpeed * TAU));
        effZoom = pow(10.0, effDepth * zoomPhase);
    } else {
        effZoom = pow(10.0, effDepth);
    }

    let rot = select(rotation, 0.0, poi > 0);

    // Resolve POI coordinates
    let poiCoords = getPOI(poi, centerHiX, centerLoX, centerHiY, centerLoY);
    let cX_df = poiCoords.cX;
    let cY_df = poiCoords.cY;

    var value: f32;

    if (outputMode == 4) {
        value = outputNormalMap(globalCoord, fullResolution, cX_df, cY_df,
                               effZoom, rot, maxIter, lightAngle,
                               stripeFreq, trapShape);
    } else {
        let coords = transformCoords_df64(globalCoord, fullResolution, cX_df, cY_df, effZoom, rot);
        let r = mandelbrot_df64(coords.re, coords.im, maxIter, stripeFreq, trapShape);

        if (outputMode == 0) {
            value = outputSmoothIteration(r.smoothIter, r.rawIter, maxIter);
        } else if (outputMode == 1) {
            value = outputDistance(r.z_final, r.dz_final, r.rawIter, maxIter);
        } else if (outputMode == 2) {
            value = outputStripeAverage(r.smoothIter, r.rawIter, r.stripeAcc, maxIter);
        } else if (outputMode == 3) {
            value = outputOrbitTrap(r.trapMin, r.rawIter, maxIter);
        } else {
            value = outputSmoothIteration(r.smoothIter, r.rawIter, maxIter);
        }
    }

    if (invertVal > 0.5) {
        value = 1.0 - value;
    }

    return vec4<f32>(vec3<f32>(value), 1.0);
}

/*
 * WGSL media input shader.
 * Mirrors the GLSL normalization and crop logic for camera feeds.
 */

struct Uniforms {
    data : array<vec4<f32>, 5>,
};
@group(0) @binding(0) var<uniform> uniforms : Uniforms;
@group(0) @binding(1) var samp : sampler;
@group(0) @binding(2) var imageTex : texture_2d<f32>;

var<private> resolution : vec2<f32>;
var<private> time : f32;
var<private> posIndex : i32;
var<private> rotation : f32;
var<private> scaleAmt : f32;
var<private> offsetX : f32;
var<private> offsetY : f32;
var<private> tiling : i32;
var<private> flip : i32;
var<private> bgColor : vec3<f32>;
var<private> bgAlpha : f32;
var<private> imageSize : vec2<f32>;

const PI : f32 = 3.14159265359;
const TAU : f32 = 6.28318530718;

fn map(value: f32, inMin: f32, inMax: f32, outMin: f32, outMax: f32) -> f32 {
    return outMin + (outMax - outMin) * (value - inMin) / (inMax - inMin);
}

fn rotate2D(st: vec2<f32>) -> vec2<f32> {
    var st2 = st;
    let rot = map(rotation, -180.0, 180.0, 0.5, -0.5);
    let angle = rot * TAU * -1.0;

    let aspect = imageSize.x / imageSize.y;
    st2 = st2 - vec2<f32>(0.5 * aspect, 0.5);
    let c = cos(angle);
    let s = sin(angle);
    st2 = mat2x2<f32>(c, -s, s, c) * st2;
    st2 = st2 + vec2<f32>(0.5 * aspect, 0.5);
    return st2;
}

fn tile(st: vec2<f32>) -> vec2<f32> {
    if (tiling == 0) {
        return st;
    } else if (tiling == 1) {
        return fract(st);
    } else if (tiling == 2) {
        return vec2<f32>(fract(st.x), st.y);
    } else if (tiling == 3) {
        return vec2<f32>(st.x, fract(st.y));
    }
    return st;
}

// External uploads use straight alpha; filter premultiplied texels.
fn mediaTexel(p: vec2<i32>, size: vec2<i32>) -> vec4<f32> {
    let c = textureLoad(imageTex, clamp(p, vec2<i32>(0), size - vec2<i32>(1)), 0);
    return vec4<f32>(c.rgb * c.a, c.a);
}

fn sampleMedia(uv: vec2<f32>) -> vec4<f32> {
    let size = vec2<i32>(textureDimensions(imageTex));
    let p = uv * vec2<f32>(size) - vec2<f32>(0.5);
    let lo = vec2<i32>(floor(p));
    let f = fract(p);
    return mix(mix(mediaTexel(lo, size), mediaTexel(lo + vec2<i32>(1, 0), size), f.x),
               mix(mediaTexel(lo + vec2<i32>(0, 1), size), mediaTexel(lo + vec2<i32>(1, 1), size), f.x), f.y);
}

fn getImage(pos: vec2<f32>) -> vec4<f32> {
    var st = pos / imageSize;
    st.y = 1.0 - st.y;

    var scale = 100.0 / scaleAmt;
    if (scale == 0.0) { scale = 1.0; }
    st = st * scale;

    if (posIndex == 0) {
        st.y = st.y + (resolution.y / imageSize.y * scale) - (scale - (1.0 / imageSize.y * scale));
    } else if (posIndex == 1) {
        st.x = st.x - (resolution.x / imageSize.x * scale * 0.5) + (0.5 - (1.0 / imageSize.x * scale));
        st.y = st.y + (resolution.y / imageSize.y * scale) - (scale - (1.0 / imageSize.y * scale));
    } else if (posIndex == 2) {
        st.x = st.x - (resolution.x / imageSize.x * scale) + (1.0 - (1.0 / imageSize.x * scale));
        st.y = st.y + (resolution.y / imageSize.y * scale) - (scale - (1.0 / imageSize.y * scale));
    } else if (posIndex == 3) {
        st.y = st.y + (resolution.y / imageSize.y * scale * 0.5) + (0.5 - (1.0 / imageSize.y * scale)) - scale;
    } else if (posIndex == 4) {
        st.x = st.x - (resolution.x / imageSize.x * scale * 0.5) + (0.5 - (1.0 / imageSize.x * scale));
        st.y = st.y + (resolution.y / imageSize.y * scale * 0.5) + (0.5 - (1.0 / imageSize.y * scale)) - scale;
    } else if (posIndex == 5) {
        st.x = st.x - (resolution.x / imageSize.x * scale) + (1.0 - (1.0 / imageSize.x * scale));
        st.y = st.y + (resolution.y / imageSize.y * scale * 0.5) + (0.5 - (1.0 / imageSize.y * scale)) - scale;
    } else if (posIndex == 6) {
        st.y = st.y + 1.0 - (scale - (1.0 / imageSize.y * scale));
    } else if (posIndex == 7) {
        st.x = st.x - (resolution.x / imageSize.x * scale * 0.5) + (0.5 - (1.0 / imageSize.x * scale));
        st.y = st.y + 1.0 - (scale - (1.0 / imageSize.y * scale));
    } else if (posIndex == 8) {
        st.x = st.x - (resolution.x / imageSize.x * scale) + (1.0 - (1.0 / imageSize.x * scale));
        st.y = st.y + 1.0 - (scale - (1.0 / imageSize.y * scale));
    }

    st.x = st.x - map(offsetX, -100.0, 100.0, -resolution.x / imageSize.x * scale, resolution.x / imageSize.x * scale) * 1.5;
    st.y = st.y - map(offsetY, -100.0, 100.0, -resolution.y / imageSize.y * scale, resolution.y / imageSize.y * scale) * 1.5;

    st.x = st.x * (imageSize.x / imageSize.y);
    // Preserve exact texture coordinates for the identity transform.
    if (rotation != 0.0) { st = rotate2D(st); }
    st.x = st.x / (imageSize.x / imageSize.y);

    st = tile(st);

    st = st + 1.0 / imageSize;

    if (flip == 1) {
        st.x = 1.0 - st.x;
        st.y = 1.0 - st.y;
    } else if (flip == 2) {
        st.x = 1.0 - st.x;
    } else if (flip == 3) {
        st.y = 1.0 - st.y;
    } else if (flip == 11) {
        if (st.x > 0.5) { st.x = 1.0 - st.x; }
    } else if (flip == 12) {
        if (st.x < 0.5) { st.x = 1.0 - st.x; }
    } else if (flip == 13) {
        if (st.y > 0.5) { st.y = 1.0 - st.y; }
    } else if (flip == 14) {
        if (st.y < 0.5) { st.y = 1.0 - st.y; }
    } else if (flip == 15) {
        if (st.x > 0.5) { st.x = 1.0 - st.x; }
        if (st.y > 0.5) { st.y = 1.0 - st.y; }
    } else if (flip == 16) {
        if (st.x > 0.5) { st.x = 1.0 - st.x; }
        if (st.y < 0.5) { st.y = 1.0 - st.y; }
    } else if (flip == 17) {
        if (st.x < 0.5) { st.x = 1.0 - st.x; }
        if (st.y > 0.5) { st.y = 1.0 - st.y; }
    } else if (flip == 18) {
        if (st.x < 0.5) { st.x = 1.0 - st.x; }
        if (st.y < 0.5) { st.y = 1.0 - st.y; }
    }

    let text = sampleMedia(st);

    if (st.x < 0.0 || st.x > 1.0 || st.y < 0.0 || st.y > 1.0) {
        return vec4<f32>(bgColor * bgAlpha, bgAlpha);
    }

    return text;
}

@fragment
fn main(@builtin(position) pos : vec4<f32>) -> @location(0) vec4<f32> {
    resolution = uniforms.data[0].xy;
    time = uniforms.data[0].z;
    posIndex = i32(uniforms.data[1].x);
    rotation = uniforms.data[1].y;
    scaleAmt = uniforms.data[1].z;
    offsetX = uniforms.data[1].w;

    offsetY = uniforms.data[2].x;
    tiling = i32(uniforms.data[2].y);
    flip = i32(uniforms.data[2].z);
    bgAlpha = uniforms.data[2].w;

    bgColor = uniforms.data[3].xyz;

    imageSize = uniforms.data[4].xy;

    // Internal rows match GLSL texture rows; presentation applies the final
    // Y conversion. Keep anchor, offset and rotation in that same space.
    return getImage(pos.xy);
}

// Cellular automata display pass (WGSL).

struct Uniforms {
    data : array<vec4<f32>, 7>,
};

@group(0) @binding(0) var<uniform> uniforms : Uniforms;
@group(0) @binding(1) var fbTex: texture_2d<f32>;
@group(0) @binding(2) var mySampler: sampler;

fn quadratic3(p0: vec4<f32>, p1: vec4<f32>, p2: vec4<f32>, t: f32) -> vec4<f32> {
    let t2 = t * t;

    return p0 * 0.5 * (1.0 - t) * (1.0 - t) +
           p1 * 0.5 * (-2.0 * t2 + 2.0 * t + 1.0) +
           p2 * 0.5 * t2;
}

fn bicubic4(p0: vec4<f32>, p1: vec4<f32>, p2: vec4<f32>, p3: vec4<f32>, t: f32) -> vec4<f32> {
    let t2 = t * t;
    let t3 = t2 * t;

    let b0 = (1.0 - t) * (1.0 - t) * (1.0 - t) / 6.0;
    let b1 = (3.0 * t3 - 6.0 * t2 + 4.0) / 6.0;
    let b2 = (-3.0 * t3 + 3.0 * t2 + 3.0 * t + 1.0) / 6.0;
    let b3 = t3 / 6.0;

    return p0 * b0 + p1 * b1 + p2 * b2 + p3 * b3;
}

fn catmullRom3(p0: vec4<f32>, p1: vec4<f32>, p2: vec4<f32>, t: f32) -> vec4<f32> {
    // Catmull-Rom-esque cubic through 3 points
    // Interpolating (passes through control points)
    let t2 = t * t;
    let t3 = t2 * t;

    return p1 + 0.5 * t * (p2 - p0) +
           0.5 * t2 * (2.0*p0 - 5.0*p1 + 4.0*p2 - p0) +
           0.5 * t3 * (-p0 + 3.0*p1 - 3.0*p2 + p0);
}

fn catmullRom4(p0: vec4<f32>, p1: vec4<f32>, p2: vec4<f32>, p3: vec4<f32>, t: f32) -> vec4<f32> {
    return p1 + 0.5 * t * (p2 - p0 + t * (2.0 * p0 - 5.0 * p1 + 4.0 * p2 - p3 + t * (3.0 * (p1 - p2) + p3 - p0)));
}

fn quadraticSample(tex: texture_2d<f32>, samp: sampler, uv: vec2<f32>, texelSize: vec2<f32>) -> vec4<f32> {
    // Match GLSL: offset uv by one texel to accommodate texel centering
    let uv2 = uv + texelSize;
    let texCoord = uv2 / texelSize;
    let baseCoord = floor(texCoord - 0.5);
    let f = fract(texCoord - 0.5);

    // Sample 3x3 grid centered on the interpolation point
    let v00 = textureSampleLevel(tex, samp, (baseCoord + vec2<f32>(-0.5, -0.5)) * texelSize, 0.0);
    let v10 = textureSampleLevel(tex, samp, (baseCoord + vec2<f32>( 0.5, -0.5)) * texelSize, 0.0);
    let v20 = textureSampleLevel(tex, samp, (baseCoord + vec2<f32>( 1.5, -0.5)) * texelSize, 0.0);

    let v01 = textureSampleLevel(tex, samp, (baseCoord + vec2<f32>(-0.5,  0.5)) * texelSize, 0.0);
    let v11 = textureSampleLevel(tex, samp, (baseCoord + vec2<f32>( 0.5,  0.5)) * texelSize, 0.0);
    let v21 = textureSampleLevel(tex, samp, (baseCoord + vec2<f32>( 1.5,  0.5)) * texelSize, 0.0);

    let v02 = textureSampleLevel(tex, samp, (baseCoord + vec2<f32>(-0.5,  1.5)) * texelSize, 0.0);
    let v12 = textureSampleLevel(tex, samp, (baseCoord + vec2<f32>( 0.5,  1.5)) * texelSize, 0.0);
    let v22 = textureSampleLevel(tex, samp, (baseCoord + vec2<f32>( 1.5,  1.5)) * texelSize, 0.0);

    // Interpolate rows using quadratic B-spline
    let y0 = quadratic3(v00, v10, v20, f.x);
    let y1 = quadratic3(v01, v11, v21, f.x);
    let y2 = quadratic3(v02, v12, v22, f.x);

    // Interpolate columns
    return quadratic3(y0, y1, y2, f.y);
}

fn catmullRom3x3Sample(tex: texture_2d<f32>, samp: sampler, uv: vec2<f32>, texelSize: vec2<f32>) -> vec4<f32> {
    // Match GLSL: offset uv by one texel to accommodate texel centering
    let uv2 = uv + texelSize;
    let texCoord = uv2 / texelSize;
    let baseCoord = floor(texCoord - 1.0);
    let f = fract(texCoord - 1.0);

    // Sample 3x3 grid
    let v00 = textureSampleLevel(tex, samp, (baseCoord + vec2<f32>(-0.5, -0.5)) * texelSize, 0.0);
    let v10 = textureSampleLevel(tex, samp, (baseCoord + vec2<f32>( 0.5, -0.5)) * texelSize, 0.0);
    let v20 = textureSampleLevel(tex, samp, (baseCoord + vec2<f32>( 1.5, -0.5)) * texelSize, 0.0);

    let v01 = textureSampleLevel(tex, samp, (baseCoord + vec2<f32>(-0.5,  0.5)) * texelSize, 0.0);
    let v11 = textureSampleLevel(tex, samp, (baseCoord + vec2<f32>( 0.5,  0.5)) * texelSize, 0.0);
    let v21 = textureSampleLevel(tex, samp, (baseCoord + vec2<f32>( 1.5,  0.5)) * texelSize, 0.0);

    let v02 = textureSampleLevel(tex, samp, (baseCoord + vec2<f32>(-0.5,  1.5)) * texelSize, 0.0);
    let v12 = textureSampleLevel(tex, samp, (baseCoord + vec2<f32>( 0.5,  1.5)) * texelSize, 0.0);
    let v22 = textureSampleLevel(tex, samp, (baseCoord + vec2<f32>( 1.5,  1.5)) * texelSize, 0.0);

    // Interpolate rows using Catmull-Rom
    let y0 = catmullRom3(v00, v10, v20, f.x);
    let y1 = catmullRom3(v01, v11, v21, f.x);
    let y2 = catmullRom3(v02, v12, v22, f.x);

    // Interpolate columns
    return catmullRom3(y0, y1, y2, f.y);
}

fn bicubicSample(tex: texture_2d<f32>, samp: sampler, uv: vec2<f32>, texelSize: vec2<f32>) -> vec4<f32> {
    let uv2 = uv + texelSize;
    let texCoord = uv2 / texelSize;
    let baseCoord = floor(texCoord - 1.0);
    let f = fract(texCoord - 1.0);

    let row0 = bicubic4(
        textureSampleLevel(tex, samp, (baseCoord + vec2<f32>(-0.5, -0.5)) * texelSize, 0.0),
        textureSampleLevel(tex, samp, (baseCoord + vec2<f32>( 0.5, -0.5)) * texelSize, 0.0),
        textureSampleLevel(tex, samp, (baseCoord + vec2<f32>( 1.5, -0.5)) * texelSize, 0.0),
        textureSampleLevel(tex, samp, (baseCoord + vec2<f32>( 2.5, -0.5)) * texelSize, 0.0),
        f.x
    );

    let row1 = bicubic4(
        textureSampleLevel(tex, samp, (baseCoord + vec2<f32>(-0.5,  0.5)) * texelSize, 0.0),
        textureSampleLevel(tex, samp, (baseCoord + vec2<f32>( 0.5,  0.5)) * texelSize, 0.0),
        textureSampleLevel(tex, samp, (baseCoord + vec2<f32>( 1.5,  0.5)) * texelSize, 0.0),
        textureSampleLevel(tex, samp, (baseCoord + vec2<f32>( 2.5,  0.5)) * texelSize, 0.0),
        f.x
    );

    let row2 = bicubic4(
        textureSampleLevel(tex, samp, (baseCoord + vec2<f32>(-0.5,  1.5)) * texelSize, 0.0),
        textureSampleLevel(tex, samp, (baseCoord + vec2<f32>( 0.5,  1.5)) * texelSize, 0.0),
        textureSampleLevel(tex, samp, (baseCoord + vec2<f32>( 1.5,  1.5)) * texelSize, 0.0),
        textureSampleLevel(tex, samp, (baseCoord + vec2<f32>( 2.5,  1.5)) * texelSize, 0.0),
        f.x
    );

    let row3 = bicubic4(
        textureSampleLevel(tex, samp, (baseCoord + vec2<f32>(-0.5,  2.5)) * texelSize, 0.0),
        textureSampleLevel(tex, samp, (baseCoord + vec2<f32>( 0.5,  2.5)) * texelSize, 0.0),
        textureSampleLevel(tex, samp, (baseCoord + vec2<f32>( 1.5,  2.5)) * texelSize, 0.0),
        textureSampleLevel(tex, samp, (baseCoord + vec2<f32>( 2.5,  2.5)) * texelSize, 0.0),
        f.x
    );

    return bicubic4(row0, row1, row2, row3, f.y);
}

fn catmullRom4x4Sample(tex: texture_2d<f32>, samp: sampler, uv: vec2<f32>, texelSize: vec2<f32>) -> vec4<f32> {
    let uv2 = uv + texelSize;
    let texCoord = uv2 / texelSize;
    let baseCoord = floor(texCoord - 1.0);
    let f = fract(texCoord - 1.0);

    let row0 = catmullRom4(
        textureSampleLevel(tex, samp, (baseCoord + vec2<f32>(-0.5, -0.5)) * texelSize, 0.0),
        textureSampleLevel(tex, samp, (baseCoord + vec2<f32>( 0.5, -0.5)) * texelSize, 0.0),
        textureSampleLevel(tex, samp, (baseCoord + vec2<f32>( 1.5, -0.5)) * texelSize, 0.0),
        textureSampleLevel(tex, samp, (baseCoord + vec2<f32>( 2.5, -0.5)) * texelSize, 0.0),
        f.x
    );

    let row1 = catmullRom4(
        textureSampleLevel(tex, samp, (baseCoord + vec2<f32>(-0.5,  0.5)) * texelSize, 0.0),
        textureSampleLevel(tex, samp, (baseCoord + vec2<f32>( 0.5,  0.5)) * texelSize, 0.0),
        textureSampleLevel(tex, samp, (baseCoord + vec2<f32>( 1.5,  0.5)) * texelSize, 0.0),
        textureSampleLevel(tex, samp, (baseCoord + vec2<f32>( 2.5,  0.5)) * texelSize, 0.0),
        f.x
    );

    let row2 = catmullRom4(
        textureSampleLevel(tex, samp, (baseCoord + vec2<f32>(-0.5,  1.5)) * texelSize, 0.0),
        textureSampleLevel(tex, samp, (baseCoord + vec2<f32>( 0.5,  1.5)) * texelSize, 0.0),
        textureSampleLevel(tex, samp, (baseCoord + vec2<f32>( 1.5,  1.5)) * texelSize, 0.0),
        textureSampleLevel(tex, samp, (baseCoord + vec2<f32>( 2.5,  1.5)) * texelSize, 0.0),
        f.x
    );

    let row3 = catmullRom4(
        textureSampleLevel(tex, samp, (baseCoord + vec2<f32>(-0.5,  2.5)) * texelSize, 0.0),
        textureSampleLevel(tex, samp, (baseCoord + vec2<f32>( 0.5,  2.5)) * texelSize, 0.0),
        textureSampleLevel(tex, samp, (baseCoord + vec2<f32>( 1.5,  2.5)) * texelSize, 0.0),
        textureSampleLevel(tex, samp, (baseCoord + vec2<f32>( 2.5,  2.5)) * texelSize, 0.0),
        f.x
    );

    return catmullRom4(row0, row1, row2, row3, f.y);
}

fn cosineMix(a: f32, b: f32, t: f32) -> f32 {
    let amount = (1.0 - cos(t * 3.141592653589793)) * 0.5;
    return mix(a, b, amount);
}

@fragment fn main(@builtin(position) fragCoord: vec4<f32>) -> @location(0) vec4<f32> {
    let resolution = uniforms.data[0].xy;
    let smoothing = i32(uniforms.data[1].y);
    let tileOffset = uniforms.data[6].xy;
    let fullResolution = uniforms.data[6].zw;
    let globalCoord = fragCoord.xy + tileOffset;

    var state: f32 = 0.0;
    if (smoothing == 0) {
        // constant - use textureLoad for exact nearest-neighbor sampling
        let texSizeI = vec2<i32>(textureDimensions(fbTex, 0));
        let texSizeF = vec2<f32>(f32(texSizeI.x), f32(texSizeI.y));
        let pixelCoord = vec2<i32>(floor(globalCoord * texSizeF / fullResolution));
        state = textureLoad(fbTex, clamp(pixelCoord, vec2<i32>(0), texSizeI - vec2<i32>(1)), 0).g;
    } else if (smoothing == 3) {
        // catmull-rom 3x3 (9 taps)
        let texSize = vec2<f32>(textureDimensions(fbTex, 0));
        let texelSize = 1.0 / texSize;
        let scaling = fullResolution / texSize;
        let uv = (globalCoord - scaling * 0.5) / fullResolution;
        state = catmullRom3x3Sample(fbTex, mySampler, uv, texelSize).g;
    } else if (smoothing == 4) {
        // catmull-rom 4x4 (16 taps)
        let texSize = vec2<f32>(textureDimensions(fbTex, 0));
        let texelSize = 1.0 / texSize;
        let scaling = fullResolution / texSize;
        let uv = (globalCoord - scaling * 0.5) / fullResolution;
        state = catmullRom4x4Sample(fbTex, mySampler, uv, texelSize).g;
    } else if (smoothing == 5) {
        // b-spline 3x3 (9 taps)
        let texSize = vec2<f32>(textureDimensions(fbTex, 0));
        let texelSize = 1.0 / texSize;
        let scaling = fullResolution / texSize;
        let uv = (globalCoord - scaling * 0.5) / fullResolution;
        state = quadraticSample(fbTex, mySampler, uv, texelSize).g;
    } else if (smoothing == 6) {
        // b-spline 4x4 (16 taps)
        let texSize = vec2<f32>(textureDimensions(fbTex, 0));
        let texelSize = 1.0 / texSize;
        let scaling = fullResolution / texSize;
        let uv = (globalCoord - scaling * 0.5) / fullResolution;
        state = bicubicSample(fbTex, mySampler, uv, texelSize).g;
    } else {
        // linear-style smoothing — sample texel centres explicitly to avoid seams.
        let texSize = vec2<f32>(textureDimensions(fbTex, 0));
        let texelPos = (globalCoord * texSize / fullResolution) - vec2<f32>(0.5, 0.5);
        let base = floor(texelPos);
        let weights = fract(texelPos);
        let next = base + vec2<f32>(1.0, 1.0);

        let texSizeI = vec2<i32>(textureDimensions(fbTex, 0));
        let minIdx = vec2<i32>(0, 0);
        let maxIdx = texSizeI - vec2<i32>(1, 1);
        let baseI = clamp(vec2<i32>(base), minIdx, maxIdx);
        let nextI = clamp(vec2<i32>(next), minIdx, maxIdx);

        let v00 = textureLoad(fbTex, baseI, 0).g;
        let v10 = textureLoad(fbTex, vec2<i32>(nextI.x, baseI.y), 0).g;
        let v01 = textureLoad(fbTex, vec2<i32>(baseI.x, nextI.y), 0).g;
        let v11 = textureLoad(fbTex, nextI, 0).g;

        if (smoothing == 1) {
            let v0 = mix(v00, v10, weights.x);
            let v1 = mix(v01, v11, weights.x);
            state = mix(v0, v1, weights.y);
        } else {
            let v0 = cosineMix(v00, v10, weights.x);
            let v1 = cosineMix(v01, v11, weights.x);
            state = cosineMix(v0, v1, weights.y);
        }
    }

    return vec4<f32>(state, state, state, 1.0);
}

/*
 * Multi-neighbourhood cellular automata feedback pass.
 *
 * Evolves the automaton by sampling two concentric neighbourhoods and mapping
 * their averages through UI-configurable threshold windows. The luminance
 * blend mirrors the single-neighbourhood shader so modulation rules stay
 * consistent across module variants.
 */

struct Uniforms {
    data : array<vec4<f32>, 6>,
};

@group(0) @binding(0) var<uniform> uniforms : Uniforms;
@group(0) @binding(1) var samp: sampler;
@group(0) @binding(2) var bufTex: texture_2d<f32>;
@group(0) @binding(3) var seedTex: texture_2d<f32>;

fn map(value: f32, inMin: f32, inMax: f32, outMin: f32, outMax: f32) -> f32 {
    return outMin + (outMax - outMin) * (value - inMin) / (inMax - inMin);
}

fn lum(color: vec3<f32>) -> f32 {
    return 0.2126 * color.r + 0.7152 * color.g + 0.0722 * color.b;
}

fn random(st: vec2<f32>) -> f32 {
    return fract(sin(dot(st, vec2<f32>(12.9898, 78.233))) * 43758.5453123);
}

// Clamp a texel coordinate to the valid texture bounds
fn clampCoord(p: vec2<i32>, size: vec2<i32>) -> vec2<i32> {
    let cx = clamp(p.x, 0, size.x - 1);
    let cy = clamp(p.y, 0, size.y - 1);
    return vec2<i32>(cx, cy);
}

// Fetch a single cell value using integer coordinates to avoid filtering
fn cellAt(base: vec2<i32>, offset: vec2<i32>, size: vec2<i32>) -> f32 {
    let pc = clampCoord(base + offset, size);
    return textureLoad(bufTex, pc, 0).r;
}

// Neighbourhood 1 = circle with r = 3.
fn neighborsAvgCircle(base: vec2<i32>, size: vec2<i32>) -> f32 {
    var total: f32 = 0.0;
    for (var y: i32 = -3; y <= 3; y++) {
        for (var x: i32 = -3; x <= 3; x++) {
            if (x == 0 && y == 0) { continue; }
            if (abs(x) == 3 && abs(y) > 1) { continue; }
            if (abs(y) == 3 && abs(x) > 1) { continue; }
            total += cellAt(base, vec2<i32>(x, y), size);
        }
    }
    return total / 36.0;
}

// Neighbourhood 2 = ring with inner r = 4 and outer r = 7.
fn neighborsAvgRing(base: vec2<i32>, size: vec2<i32>) -> f32 {
    var total: f32 = 0.0;
    for (var y: i32 = -7; y <= 7; y++) {
        for (var x: i32 = -7; x <= 7; x++) {
            // ignore inner area
            if (abs(x) <= 3 && abs(y) <= 3) { continue; }
            if (abs(x) == 4 && abs(y) <= 2) { continue; }
            if (abs(y) == 4 && abs(x) <= 2) { continue; }
            // ignore outer corners 
            if (abs(x) == 7 && abs(y) > 2) { continue; }
            if (abs(x) == 6 && abs(y) > 4) { continue; }
            if (abs(x) == 5 && abs(y) > 5) { continue; }
            if (abs(x) > 2 && abs(y) > 6) { continue; }
            total += cellAt(base, vec2<i32>(x, y), size);
        }
    }
    return total / 108.0;
}

fn getState(avg1: f32, avg2: f32, state: f32,
            n1v1: f32, n1r1: f32, n1v2: f32, n1r2: f32,
            n1v3: f32, n1r3: f32, n1v4: f32, n1r4: f32,
            n2v1: f32, n2r1: f32, n2v2: f32, n2r2: f32) -> f32 {
    var newState: f32 = state;
    if (avg1 >= n1v1 * 0.01 && avg1 <= n1v1 * 0.01 + n1r1 * 0.01) { newState = 1.0; }
    if (avg1 >= n1v2 * 0.01 && avg1 <= n1v2 * 0.01 + n1r2 * 0.01) { newState = 0.0; }
    if (avg1 >= n1v3 * 0.01 && avg1 <= n1v3 * 0.01 + n1r3 * 0.01) { newState = 0.0; }
    if (avg2 >= n2v1 * 0.01 && avg2 <= n2v1 * 0.01 + n2r1 * 0.01) { newState = 0.0; }
    if (avg2 >= n2v2 * 0.01 && avg2 <= n2v2 * 0.01 + n2r2 * 0.01) { newState = 1.0; }
    if (avg1 >= n1v4 * 0.01 && avg1 <= n1v4 * 0.01 + n1r4 * 0.01) { newState = 0.0; }
    return newState;
}

@fragment
fn main(@builtin(position) fragCoord: vec4<f32>) -> @location(0) vec4<f32> {
    let texSizeI: vec2<i32> = vec2<i32>(textureDimensions(bufTex, 0));
    let texSize: vec2<f32> = vec2<f32>(f32(texSizeI.x), f32(texSizeI.y));
    let uv: vec2<f32> = fragCoord.xy / texSize;

    // Extract parameters from uniforms
    // Slot 0: resolution, time, deltaTime
    let deltaTime: f32 = uniforms.data[0].w;

    // Slot 1: speed, smoothing, weight, seed
    let speed: f32 = uniforms.data[1].x;
    let weight: f32 = uniforms.data[1].z;
    let seed: i32 = i32(uniforms.data[1].w);

    // Slot 2: resetState, n1v1, n1r1, n1v2
    let resetState: bool = uniforms.data[2].x > 0.5;
    let n1v1: f32 = uniforms.data[2].y;
    let n1r1: f32 = uniforms.data[2].z;
    let n1v2: f32 = uniforms.data[2].w;

    // Slot 3: n1r2, n1v3, n1r3, n1v4
    let n1r2: f32 = uniforms.data[3].x;
    let n1v3: f32 = uniforms.data[3].y;
    let n1r3: f32 = uniforms.data[3].z;
    let n1v4: f32 = uniforms.data[3].w;

    // Slot 4: n1r4, n2v1, n2r1, n2v2
    let n1r4: f32 = uniforms.data[4].x;
    let n2v1: f32 = uniforms.data[4].y;
    let n2r1: f32 = uniforms.data[4].z;
    let n2v2: f32 = uniforms.data[4].w;

    // Slot 5: n2r2
    let n2r2: f32 = uniforms.data[5].x;

    // Sample textures unconditionally to satisfy uniform control flow requirement
    let prevFrame: vec3<f32> = textureSample(seedTex, samp, uv).rgb;
    let prevLum: f32 = lum(prevFrame);

    // Use UV-derived coordinates (not fragCoord) to handle resolution mismatch between output and feedback texture
    let base: vec2<i32> = vec2<i32>(i32(uv.x * texSize.x), i32(uv.y * texSize.y));
    let bufState: vec4<f32> = textureLoad(bufTex, clampCoord(base, texSizeI), 0);
    let state: f32 = bufState.r;
    let bufferIsEmpty: bool = (bufState.r == 0.0 && bufState.g == 0.0 && bufState.b == 0.0 && bufState.a == 0.0);

    // Initialize when reset button pressed or when buffer is completely empty (first load)
    if (resetState || bufferIsEmpty) {
        let r: f32 = random(uv + vec2<f32>(f32(seed), f32(seed)));
        let alive: f32 = step(0.5, r);
        return vec4<f32>(alive, alive, alive, 1.0);
    }

    let n1: f32 = neighborsAvgCircle(base, texSizeI);
    let n2: f32 = neighborsAvgRing(base, texSizeI);
    var newState: f32 = getState(n1, n2, state, n1v1, n1r1, n1v2, n1r2, n1v3, n1r3, n1v4, n1r4, n2v1, n2r1, n2v2, n2r2);

    if (weight > 0.0) {
        newState = mix(newState, prevLum, weight * 0.01);
    }

    // The speed knob expresses human-friendly BPM-style values; remapping keeps
    // the integration step numerically stable across refresh rates.
    let animSpeed: f32 = map(speed, 1.0, 100.0, 0.1, 100.0);
    let currentState: vec4<f32> = vec4<f32>(state, state, state, 1.0);
    let nextState: vec4<f32> = vec4<f32>(newState, newState, newState, 1.0);
    return mix(currentState, nextState, min(1.0, deltaTime * animSpeed));
}

// WGSL version – WebGPU
// Pack uniforms into a struct to stay within WebGPU's 12 uniform buffer limit
struct Uniforms {
    // Slot 0: resolution.xy, time, aspect
    // Slot 1: shape1, scale1, repeat1, shape2
    // Slot 2: scale2, repeat2, shape3, scale3
    // Slot 3: repeat3, blend, speed, smoothing
    // Slot 4: animMode
    // Slot 5: tileOffset.xy, fullResolution.xy
    data: array<vec4<f32>, 6>,
};

@group(0) @binding(0) var<uniform> uniforms: Uniforms;

// GLSL-compatible mod function: mod(x, y) = x - y * floor(x/y)
// WGSL % operator behaves like C's fmod, which gives different results for negative numbers
fn glsl_mod(x: f32, y: f32) -> f32 {
    return x - y * floor(x / y);
}

fn glsl_mod2(x: vec2<f32>, y: vec2<f32>) -> vec2<f32> {
    return x - y * floor(x / y);
}

// Generate a geometric shape from the given coordinates
fn shape(shapeIndex: i32, p: vec2<f32>) -> f32 {
	var v: f32;
	if (shapeIndex < 1) {
		// plus
		v = max(p.x, p.y);
	} else if (shapeIndex < 2) {
		// square
		v = min(p.x, p.y);
	} else {
		// diamond
		v = abs(p.x - p.y);
	}
	return v;
}

fn smoothFract(x: f32) -> f32 {
	let smoothing = i32(uniforms.data[3].w);
	let f = fract(x);
	let edgeWidth = f32(smoothing) * 0.01;
	if (f > 1.0 - edgeWidth) {
		return smoothstep(0.0, edgeWidth, 1.0 - f);
	}
	return f;
}

fn smoothFract2(v: vec2<f32>) -> vec2<f32>  {
	return vec2<f32>(smoothFract(v.x), smoothFract(v.y));
}

fn smoothFract3(v: vec3<f32>) -> vec3<f32> {
	return vec3<f32>(smoothFract(v.x), smoothFract(v.y), smoothFract(v.z));
}

@fragment
fn main(@builtin(position) position: vec4<f32>) -> @location(0) vec4<f32> {
	// Unpack uniforms
	let resolution = uniforms.data[0].xy;
	let time = uniforms.data[0].z;

	let shape1 = i32(uniforms.data[1].x);
	let scale1 = uniforms.data[1].y;
	let repeat1 = uniforms.data[1].z;
	let shape2 = i32(uniforms.data[1].w);

	let scale2 = uniforms.data[2].x;
	let repeat2 = uniforms.data[2].y;
	let shape3 = i32(uniforms.data[2].z);
	let scale3 = uniforms.data[2].w;

	let repeat3 = uniforms.data[3].x;
	let blend = i32(uniforms.data[3].y);
	let speed = i32(uniforms.data[3].z);
	let smoothing = i32(uniforms.data[3].w);
	let animMode = i32(uniforms.data[4].x);
	let tileOffset = uniforms.data[5].xy;
	let fullResolution = uniforms.data[5].zw;

	var res = fullResolution;
	if (res.x < 1.0) { res = vec2<f32>(1024.0, 1024.0); }

	// Normalized coordinates
	let globalCoord = position.xy + tileOffset;
	var uv = (globalCoord - res * 0.5) / min(res.x, res.y);

	let spd = floor(f32(speed));
	let anim = time * spd;
	let TAU = 6.28318530718;

	// Create repeating cells with hard edges
	// mod(uv * scale, 2.0) creates repeating cells from 0 to 2
	// Subtracting 1.0 centers them from -1 to 1
	// abs() folds them, so you get a pattern that goes 0->1->0->1 with sharp peaks
	let s1 = 20.1 - scale1; // Map scale so larger number = lower frequency
	var p = abs(glsl_mod2(uv * s1, vec2<f32>(2.0)) - vec2<f32>(1.0));

	// Pan mode: per-layer directional oscillation, scaled to layer frequency
	if (animMode == 1) {
		let osc1 = sin(time * TAU * spd) * 0.03;
		p += vec2<f32>(osc1, 0.0);
	}

	// Generate a shape/pattern for the repeated coordinates
	let n1 = shape(shape1, p);

	// Phase mode: offset each layer independently
	let phase1 = select(0.0, anim, animMode == 2);
	let phase2 = select(0.0, anim, animMode == 2);
	let phase3 = select(0.0, anim, animMode == 2);

	// Repeat the same fold operation but at a different frequency, and generate another shape
	let s2 = 10.1 - scale2; // Map scale so larger number = lower frequency
	p = abs(glsl_mod2(p * s2, vec2<f32>(2.0)) - vec2<f32>(1.0));

	// Pan mode: layer 2 pans up
	if (animMode == 1) {
		let osc2 = sin(time * TAU * spd) * 0.07;
		p += vec2<f32>(0.0, osc2);
	}

	let n2 = shape(shape2, p);

	// Multiply each pattern by different amounts (like 3 and 5) and add them together.
	// The fract() wraps values back to 0-1, creating interference patterns
	var val = 0.0;
	if (blend < 1) {
		val = fract(n1 * repeat1 + phase1 + n2 * repeat2 + phase2);
	} else {
		val = smoothFract(n1 * repeat1 + phase1 + n2 * repeat2 + phase2);
	}

	// Repeat again with scale3 frequency, modifying the coordinates and creating another
	// shape/pattern
	let s3 = 6.1 - scale3; // Map scale so larger number = lower frequency
	p = abs(glsl_mod2(p * s3, vec2<f32>(2.0)) - vec2<f32>(1.0));

	// Pan mode: layer 3 pans left
	if (animMode == 1) {
		let osc3 = sin(time * TAU * spd) * 0.15;
		p += vec2<f32>(-osc3, 0.0);
	}

	let n3 = shape(shape3, p);

	// Shift mode: add time offset at the final blend stage
	let shift = select(0.0, anim, animMode == 0);

	// Combine layers with selected blend mode
	var color: vec3<f32>;
	if (blend < 1) {
		// add
		color = smoothFract3(vec3<f32>(fract(val + n3 * repeat3 + phase3 + shift)));
	} else if (blend < 2) {
		// max
		color = vec3<f32>(max(val, smoothFract(n3 * repeat3 + phase3 + shift)));
	} else if (blend < 3) {
		// mix
		color = vec3<f32>(mix(val, smoothFract(n3 * repeat3 + phase3 + shift), 0.5));
	} else {
		// rgb
		color = smoothFract3(vec3<f32>(n1 * repeat1 + phase1, n2 * repeat2 + phase2, n3 * repeat3 + phase3 + shift));
	}

	return vec4<f32>(color, 1.0);
}

/*
 * WGSL Navier-Stokes display pass.
 * Plain bilinear blit of the intermediate smoothed canvas. No smoothing math here.
 */

struct Uniforms {
    // data[0] = (resolution.x, resolution.y, _, _)
    // data[1] = (inputIntensity, _, _, _)
    // data[2] = (tileOffset.x, tileOffset.y, fullResolution.x, fullResolution.y)
    data : array<vec4<f32>, 3>,
};

@group(0) @binding(0) var<uniform> uniforms : Uniforms;
@group(0) @binding(1) var samp : sampler;
@group(0) @binding(2) var fbTex : texture_2d<f32>;
@group(0) @binding(3) var inputTex : texture_2d<f32>;

@fragment
fn main(@builtin(position) pos : vec4<f32>) -> @location(0) vec4<f32> {
    let resolution = uniforms.data[0].xy;
    let inputIntensity = uniforms.data[1].x;
    let tileOffset = uniforms.data[2].xy;
    let fullResolution = uniforms.data[2].zw;
    let globalCoord = pos.xy + tileOffset;

    let texSize = vec2<i32>(textureDimensions(fbTex, 0));
    let texSizeF = vec2<f32>(texSize);
    let minIdx = vec2<i32>(0);
    let maxIdx = texSize - vec2<i32>(1);

    let texelPos = (globalCoord * texSizeF / fullResolution) - vec2<f32>(0.5);
    let baseI = vec2<i32>(floor(texelPos));
    let f = fract(texelPos);

    let v00 = textureLoad(fbTex, clamp(baseI,                           minIdx, maxIdx), 0).b;
    let v10 = textureLoad(fbTex, clamp(baseI + vec2<i32>(1, 0),         minIdx, maxIdx), 0).b;
    let v01 = textureLoad(fbTex, clamp(baseI + vec2<i32>(0, 1),         minIdx, maxIdx), 0).b;
    let v11 = textureLoad(fbTex, clamp(baseI + vec2<i32>(1, 1),         minIdx, maxIdx), 0).b;

    let v0 = mix(v00, v10, f.x);
    let v1 = mix(v01, v11, f.x);
    let state = mix(v0, v1, f.y);

    let intensity = clamp(state, 0.0, 1.0);
    var outCol = vec3<f32>(intensity);

    let blend = clamp(inputIntensity, 0.0, 100.0) * 0.01;
    if (blend > 0.0) {
        let inputUv = globalCoord / fullResolution;
        let inputColor = textureSampleLevel(inputTex, samp, inputUv, 0.0).rgb;
        outCol = mix(outCol, inputColor, vec3<f32>(blend));
    }

    return vec4<f32>(outCol, 1.0);
}

/*
 * WGSL Navier-Stokes advection pass (semi-Lagrangian).
 * Mirrors glsl/nsAdvect.glsl: canonical bilinear backtrace sample, decay applied. No kernel
 * choice here — smoothing lives in the dedicated nsSmooth pass between sim and display so the
 * compute canvas never receives blended pixels.
 */

struct Uniforms {
    // data[0] = (resolution.x, resolution.y, _, speed)
    // data[1] = (dyeDecay, velocityDecay, _, _)
    data : array<vec4<f32>, 2>,
};

@group(0) @binding(0) var<uniform> uniforms : Uniforms;
@group(0) @binding(1) var samp : sampler;
@group(0) @binding(2) var bufTex : texture_2d<f32>;

fn fetchTex(idx: vec2<i32>, minIdx: vec2<i32>, maxIdx: vec2<i32>) -> vec4<f32> {
    return textureLoad(bufTex, clamp(idx, minIdx, maxIdx), 0);
}

fn sampleBilinear(uv: vec2<f32>, texSize: vec2<i32>) -> vec4<f32> {
    let minIdx = vec2<i32>(0);
    let maxIdx = texSize - vec2<i32>(1);
    let texSizeF = vec2<f32>(texSize);
    let texelPos = uv * texSizeF - vec2<f32>(0.5);
    let baseI = vec2<i32>(floor(texelPos));
    let f = fract(texelPos);

    let v00 = fetchTex(baseI,                            minIdx, maxIdx);
    let v10 = fetchTex(baseI + vec2<i32>(1, 0),          minIdx, maxIdx);
    let v01 = fetchTex(baseI + vec2<i32>(0, 1),          minIdx, maxIdx);
    let v11 = fetchTex(baseI + vec2<i32>(1, 1),          minIdx, maxIdx);
    let v0 = mix(v00, v10, vec4<f32>(f.x));
    let v1 = mix(v01, v11, vec4<f32>(f.x));
    return mix(v0, v1, vec4<f32>(f.y));
}

@fragment
fn main(@builtin(position) pos : vec4<f32>) -> @location(0) vec4<f32> {
    let speed = uniforms.data[0].w;
    let dyeDecay = uniforms.data[1].x;
    let velocityDecay = uniforms.data[1].y;

    let texSize = vec2<i32>(textureDimensions(bufTex, 0));
    let texSizeF = vec2<f32>(texSize);
    let fragCoord = pos.xy;
    let uv = fragCoord / texSizeF;

    let here = textureLoad(bufTex, clamp(vec2<i32>(fragCoord), vec2<i32>(0), texSize - vec2<i32>(1)), 0);
    let u = here.rg;

    let dt = clamp(speed, 0.0, 200.0) * 0.0001;
    let backUv = clamp(uv - u * dt, vec2<f32>(0.0), vec2<f32>(1.0));

    let advected = sampleBilinear(backUv, texSize);
    var newVel = advected.rg;
    var newDye = advected.b;

    let vDecay = pow(clamp(velocityDecay, 0.0, 100.0) * 0.01, dt * 60.0);
    let dDecay = pow(clamp(dyeDecay, 0.0, 100.0) * 0.01, dt * 60.0);

    newVel = newVel * vDecay;
    newDye = newDye * dDecay;

    return vec4<f32>(newVel, newDye, 1.0);
}

/*
 * WGSL Navier-Stokes divergence pass.
 * Mirrors glsl/nsDivergence.glsl. Uses textureLoad on integer texel coords — the velocity
 * texture is rgba16f which is not guaranteed to be sampler-filterable in WebGPU.
 */

struct Uniforms {
    // data[0] = (resolution.x, resolution.y, _, _)
    data : array<vec4<f32>, 2>,
};

@group(0) @binding(0) var<uniform> uniforms : Uniforms;
@group(0) @binding(1) var samp : sampler;
@group(0) @binding(2) var velTex : texture_2d<f32>;

fn fetchVel(idx: vec2<i32>, minIdx: vec2<i32>, maxIdx: vec2<i32>) -> vec2<f32> {
    return textureLoad(velTex, clamp(idx, minIdx, maxIdx), 0).rg;
}

@fragment
fn main(@builtin(position) pos : vec4<f32>) -> @location(0) vec4<f32> {
    let texSize = vec2<i32>(textureDimensions(velTex, 0));
    let texSizeF = vec2<f32>(texSize);
    let minIdx = vec2<i32>(0);
    let maxIdx = texSize - vec2<i32>(1);
    let fragCoord = pos.xy;
    let centerI = vec2<i32>(floor(fragCoord));

    var uR = fetchVel(centerI + vec2<i32>(1, 0),  minIdx, maxIdx);
    var uL = fetchVel(centerI + vec2<i32>(-1, 0), minIdx, maxIdx);
    var uT = fetchVel(centerI + vec2<i32>(0, 1),  minIdx, maxIdx);
    var uB = fetchVel(centerI + vec2<i32>(0, -1), minIdx, maxIdx);

    if (fragCoord.x < 1.0) { uL.x = -uR.x; }
    if (fragCoord.x > texSizeF.x - 1.0) { uR.x = -uL.x; }
    if (fragCoord.y < 1.0) { uB.y = -uT.y; }
    if (fragCoord.y > texSizeF.y - 1.0) { uT.y = -uB.y; }

    let div = 0.5 * ((uR.x - uL.x) + (uT.y - uB.y));

    return vec4<f32>(0.0, div, 0.0, 1.0);
}

/*
 * WGSL Navier-Stokes gradient subtraction (projection) pass.
 * Mirrors glsl/nsGradient.glsl. textureLoad on integer texel coords (rgba16f, no sampler).
 */

struct Uniforms {
    // data[0] = (resolution.x, resolution.y, _, _)
    data : array<vec4<f32>, 2>,
};

@group(0) @binding(0) var<uniform> uniforms : Uniforms;
@group(0) @binding(1) var samp : sampler;
@group(0) @binding(2) var velTex : texture_2d<f32>;
@group(0) @binding(3) var pressureTex : texture_2d<f32>;

@fragment
fn main(@builtin(position) pos : vec4<f32>) -> @location(0) vec4<f32> {
    let texSize = vec2<i32>(textureDimensions(velTex, 0));
    let minIdx = vec2<i32>(0);
    let maxIdx = texSize - vec2<i32>(1);
    let centerI = vec2<i32>(floor(pos.xy));

    let pR = textureLoad(pressureTex, clamp(centerI + vec2<i32>(1, 0),  minIdx, maxIdx), 0).r;
    let pL = textureLoad(pressureTex, clamp(centerI + vec2<i32>(-1, 0), minIdx, maxIdx), 0).r;
    let pT = textureLoad(pressureTex, clamp(centerI + vec2<i32>(0, 1),  minIdx, maxIdx), 0).r;
    let pB = textureLoad(pressureTex, clamp(centerI + vec2<i32>(0, -1), minIdx, maxIdx), 0).r;

    let grad = 0.5 * vec2<f32>(pR - pL, pT - pB);

    let here = textureLoad(velTex, clamp(centerI, minIdx, maxIdx), 0);
    let u = here.rg - grad;

    return vec4<f32>(u, here.b, 1.0);
}

/*
 * WGSL Navier-Stokes pressure pass (Jacobi iteration).
 * Mirrors glsl/nsPressure.glsl. textureLoad on integer texel coords (rgba16f, no sampler).
 */

struct Uniforms {
    // data[0] = (resolution.x, resolution.y, _, _)
    data : array<vec4<f32>, 2>,
};

@group(0) @binding(0) var<uniform> uniforms : Uniforms;
@group(0) @binding(1) var samp : sampler;
@group(0) @binding(2) var bufTex : texture_2d<f32>;

@fragment
fn main(@builtin(position) pos : vec4<f32>) -> @location(0) vec4<f32> {
    let texSize = vec2<i32>(textureDimensions(bufTex, 0));
    let minIdx = vec2<i32>(0);
    let maxIdx = texSize - vec2<i32>(1);
    let centerI = vec2<i32>(floor(pos.xy));

    let pR = textureLoad(bufTex, clamp(centerI + vec2<i32>(1, 0),  minIdx, maxIdx), 0).r;
    let pL = textureLoad(bufTex, clamp(centerI + vec2<i32>(-1, 0), minIdx, maxIdx), 0).r;
    let pT = textureLoad(bufTex, clamp(centerI + vec2<i32>(0, 1),  minIdx, maxIdx), 0).r;
    let pB = textureLoad(bufTex, clamp(centerI + vec2<i32>(0, -1), minIdx, maxIdx), 0).r;

    let div = textureLoad(bufTex, clamp(centerI, minIdx, maxIdx), 0).g;

    let p = (pR + pL + pT + pB - div) * 0.25;

    return vec4<f32>(p, div, 0.0, 1.0);
}

/*
 * WGSL Navier-Stokes smoothing pass.
 * Mirrors glsl/nsSmooth.glsl: applies the selected kernel during upsample from compute canvas
 * to intermediate smoothed canvas. All 7 sim-tag modes (constant, linear, hermite,
 * catmullRom3x3, catmullRom4x4, bSpline3x3, bSpline4x4).
 */

struct Uniforms {
    // data[0] = (resolution.x, resolution.y, smoothing, _)
    // data[1] reserved for layout padding
    data : array<vec4<f32>, 2>,
};

@group(0) @binding(0) var<uniform> uniforms : Uniforms;
@group(0) @binding(1) var samp : sampler;
@group(0) @binding(2) var canvasTex : texture_2d<f32>;

fn fetchTex(idx: vec2<i32>, minIdx: vec2<i32>, maxIdx: vec2<i32>) -> vec4<f32> {
    return textureLoad(canvasTex, clamp(idx, minIdx, maxIdx), 0);
}

fn quad3v(p0: vec4<f32>, p1: vec4<f32>, p2: vec4<f32>, t: f32) -> vec4<f32> {
    let t2 = t * t;
    return p0 * 0.5 * (1.0 - t) * (1.0 - t) +
           p1 * 0.5 * (-2.0 * t2 + 2.0 * t + 1.0) +
           p2 * 0.5 * t2;
}

fn bicubic4v(p0: vec4<f32>, p1: vec4<f32>, p2: vec4<f32>, p3: vec4<f32>, t: f32) -> vec4<f32> {
    let t2 = t * t;
    let t3 = t2 * t;
    let b0 = (1.0 - t) * (1.0 - t) * (1.0 - t) / 6.0;
    let b1 = (3.0 * t3 - 6.0 * t2 + 4.0) / 6.0;
    let b2 = (-3.0 * t3 + 3.0 * t2 + 3.0 * t + 1.0) / 6.0;
    let b3 = t3 / 6.0;
    return p0 * b0 + p1 * b1 + p2 * b2 + p3 * b3;
}

fn catmull3v(p0: vec4<f32>, p1: vec4<f32>, p2: vec4<f32>, t: f32) -> vec4<f32> {
    let t2 = t * t;
    let t3 = t2 * t;
    let m = 0.5 * (p2 - p0);
    return (2.0*t3 - 3.0*t2 + 1.0) * p1 +
           (t3 - 2.0*t2 + t) * m +
           (-2.0*t3 + 3.0*t2) * p2 +
           (t3 - t2) * m;
}

fn catmull4v(p0: vec4<f32>, p1: vec4<f32>, p2: vec4<f32>, p3: vec4<f32>, t: f32) -> vec4<f32> {
    return p1 + 0.5 * t * (p2 - p0 + t * (2.0 * p0 - 5.0 * p1 + 4.0 * p2 - p3 + t * (3.0 * (p1 - p2) + p3 - p0)));
}

@fragment
fn main(@builtin(position) pos : vec4<f32>) -> @location(0) vec4<f32> {
    let resolution = uniforms.data[0].xy;
    let smoothing = i32(uniforms.data[0].z);

    let texSize = vec2<i32>(textureDimensions(canvasTex, 0));
    let texSizeF = vec2<f32>(texSize);
    let minIdx = vec2<i32>(0);
    let maxIdx = texSize - vec2<i32>(1);

    let uv = pos.xy / resolution;
    let texelPos = uv * texSizeF - vec2<f32>(0.5);
    let baseI = vec2<i32>(floor(texelPos));
    let f = fract(texelPos);

    var sampled : vec4<f32>;

    if (smoothing == 0) {
        let idx = clamp(vec2<i32>(floor(texelPos + 0.5)), minIdx, maxIdx);
        sampled = textureLoad(canvasTex, idx, 0);
    } else if (smoothing == 2) {
        let v00 = fetchTex(baseI,                            minIdx, maxIdx);
        let v10 = fetchTex(baseI + vec2<i32>(1, 0),          minIdx, maxIdx);
        let v01 = fetchTex(baseI + vec2<i32>(0, 1),          minIdx, maxIdx);
        let v11 = fetchTex(baseI + vec2<i32>(1, 1),          minIdx, maxIdx);
        let w = smoothstep(vec2<f32>(0.0), vec2<f32>(1.0), f);
        let v0 = mix(v00, v10, vec4<f32>(w.x));
        let v1 = mix(v01, v11, vec4<f32>(w.x));
        sampled = mix(v0, v1, vec4<f32>(w.y));
    } else if (smoothing == 3) {
        var p : array<vec4<f32>, 9>;
        for (var j: i32 = 0; j < 3; j = j + 1) {
            for (var i: i32 = 0; i < 3; i = i + 1) {
                p[j * 3 + i] = fetchTex(baseI + vec2<i32>(i - 1, j - 1), minIdx, maxIdx);
            }
        }
        let r0 = catmull3v(p[0], p[1], p[2], f.x);
        let r1 = catmull3v(p[3], p[4], p[5], f.x);
        let r2 = catmull3v(p[6], p[7], p[8], f.x);
        sampled = catmull3v(r0, r1, r2, f.y);
    } else if (smoothing == 4) {
        var p : array<vec4<f32>, 16>;
        for (var j: i32 = 0; j < 4; j = j + 1) {
            for (var i: i32 = 0; i < 4; i = i + 1) {
                p[j * 4 + i] = fetchTex(baseI + vec2<i32>(i - 1, j - 1), minIdx, maxIdx);
            }
        }
        let r0 = catmull4v(p[0], p[1], p[2], p[3], f.x);
        let r1 = catmull4v(p[4], p[5], p[6], p[7], f.x);
        let r2 = catmull4v(p[8], p[9], p[10], p[11], f.x);
        let r3 = catmull4v(p[12], p[13], p[14], p[15], f.x);
        sampled = catmull4v(r0, r1, r2, r3, f.y);
    } else if (smoothing == 5) {
        var p : array<vec4<f32>, 9>;
        for (var j: i32 = 0; j < 3; j = j + 1) {
            for (var i: i32 = 0; i < 3; i = i + 1) {
                p[j * 3 + i] = fetchTex(baseI + vec2<i32>(i - 1, j - 1), minIdx, maxIdx);
            }
        }
        let r0 = quad3v(p[0], p[1], p[2], f.x);
        let r1 = quad3v(p[3], p[4], p[5], f.x);
        let r2 = quad3v(p[6], p[7], p[8], f.x);
        sampled = quad3v(r0, r1, r2, f.y);
    } else if (smoothing == 6) {
        var p : array<vec4<f32>, 16>;
        for (var j: i32 = 0; j < 4; j = j + 1) {
            for (var i: i32 = 0; i < 4; i = i + 1) {
                p[j * 4 + i] = fetchTex(baseI + vec2<i32>(i - 1, j - 1), minIdx, maxIdx);
            }
        }
        let r0 = bicubic4v(p[0], p[1], p[2], p[3], f.x);
        let r1 = bicubic4v(p[4], p[5], p[6], p[7], f.x);
        let r2 = bicubic4v(p[8], p[9], p[10], p[11], f.x);
        let r3 = bicubic4v(p[12], p[13], p[14], p[15], f.x);
        sampled = bicubic4v(r0, r1, r2, r3, f.y);
    } else {
        let v00 = fetchTex(baseI,                            minIdx, maxIdx);
        let v10 = fetchTex(baseI + vec2<i32>(1, 0),          minIdx, maxIdx);
        let v01 = fetchTex(baseI + vec2<i32>(0, 1),          minIdx, maxIdx);
        let v11 = fetchTex(baseI + vec2<i32>(1, 1),          minIdx, maxIdx);
        let v0 = mix(v00, v10, vec4<f32>(f.x));
        let v1 = mix(v01, v11, vec4<f32>(f.x));
        sampled = mix(v0, v1, vec4<f32>(f.y));
    }

    return sampled;
}

/*
 * WGSL Navier-Stokes external-force / source pass.
 * Mirrors glsl/nsSplat.glsl: seeds initial vortices on reset/first frame, applies input-driven
 * force and dye on subsequent frames. State is rgba16f so velocity is stored unencoded.
 */

struct Uniforms {
    // data[0] = (resolution.x, resolution.y, _, seed)
    // data[1] = (speed, inputForce, inputDye, resetState)
    data : array<vec4<f32>, 2>,
};

@group(0) @binding(0) var<uniform> uniforms : Uniforms;
@group(0) @binding(1) var samp : sampler;
@group(0) @binding(2) var bufTex : texture_2d<f32>;
@group(0) @binding(3) var inputTex : texture_2d<f32>;

const NUM_INIT_VORTICES : i32 = 9;

fn hash11(x: f32) -> f32 {
    return fract(sin(x * 12.9898) * 43758.5453);
}

fn hash22(p: vec2<f32>) -> vec2<f32> {
    let q = vec2<f32>(dot(p, vec2<f32>(127.1, 311.7)), dot(p, vec2<f32>(269.5, 183.3)));
    return fract(sin(q) * 43758.5453);
}

fn lum(c: vec3<f32>) -> f32 {
    return 0.2126 * c.r + 0.7152 * c.g + 0.0722 * c.b;
}

@fragment
fn main(@builtin(position) pos : vec4<f32>) -> @location(0) vec4<f32> {
    let seedF = uniforms.data[0].w;
    let speed = uniforms.data[1].x;
    let inputForce = uniforms.data[1].y;
    let inputDye = uniforms.data[1].z;
    let resetState = uniforms.data[1].w > 0.5;

    let texSizeI = vec2<i32>(textureDimensions(bufTex, 0));
    let texSize = vec2<f32>(texSizeI);
    let fragCoord = pos.xy;
    let uv = fragCoord / texSize;

    // State is rgba16f — read with textureLoad on integer texel coords (sampler-filterable
    // float textures aren't guaranteed in WebGPU).
    let prev = textureLoad(bufTex, clamp(vec2<i32>(fragCoord), vec2<i32>(0), texSizeI - vec2<i32>(1)), 0);

    let bufferEmpty = (prev.a == 0.0);
    if (resetState || bufferEmpty) {
        var vel = vec2<f32>(0.0);
        var dye = 0.0;
        for (var i: i32 = 0; i < NUM_INIT_VORTICES; i = i + 1) {
            let idf = f32(i);
            let c = hash22(vec2<f32>(idf * 7.31 + 1.0, seedF * 13.7 + idf));
            var sign = -1.0;
            if (hash11(idf * 4.17 + seedF * 5.9) > 0.5) { sign = 1.0; }
            let radius = 0.10 + 0.06 * hash11(idf * 2.11 + seedF);

            let d = uv - c;
            let r2 = dot(d, d);
            let falloff = exp(-r2 / (2.0 * radius * radius));
            let tangent = vec2<f32>(-d.y, d.x);
            vel = vel + tangent * sign * falloff * 12.0;
            dye = dye + falloff;
        }
        return vec4<f32>(vel, clamp(dye, 0.0, 1.0), 1.0);
    }

    var vel = prev.rg;
    var dye = prev.b;

    let dt = clamp(speed, 0.0, 200.0) * 0.0001;

    let iForce = clamp(inputForce, 0.0, 100.0) * 0.01;
    let iDye = clamp(inputDye, 0.0, 100.0) * 0.01;
    if (iForce > 0.0 || iDye > 0.0) {
        let texel = vec2<f32>(1.0, 1.0) / texSize;
        let lc = lum(textureSampleLevel(inputTex, samp, uv, 0.0).rgb);
        let lr = lum(textureSampleLevel(inputTex, samp, uv + vec2<f32>(texel.x, 0.0), 0.0).rgb);
        let lu = lum(textureSampleLevel(inputTex, samp, uv + vec2<f32>(0.0, texel.y), 0.0).rgb);
        let grad = vec2<f32>(lr - lc, lu - lc);
        vel = vel + grad * iForce * 50.0;
        dye = dye + lc * iDye * dt * 60.0;
    }

    dye = clamp(dye, 0.0, 2.0);

    return vec4<f32>(vel, dye, 1.0);
}

/*
 * Newton fractal explorer (WGSL)
 *
 * Newton-Raphson root finding for z^n - 1 with:
 * - Continuous fractional degree (3.0-8.0)
 * - Real-valued relaxation (Nova generalization)
 * - df64 emulated double-precision for deep zoom (~10^14)
 * - Time-driven animation with golden ratio phase decoherence
 * - Pre-baked points of interest
 * - Three grayscale output modes
 *
 * All iteration runs in df64 complex arithmetic.
 * z^n computed via repeated df64 complex multiplication.
 * Fractional degrees are floored to nearest integer for root finding.
 */

struct Uniforms {
    data: array<vec4<f32>, 7>,
}

@group(0) @binding(0) var<uniform> uniforms: Uniforms;

const PI: f32 = 3.14159265359;
const TAU: f32 = 6.28318530718;
const PHI: f32 = 1.6180339887;

// ============================================================================
// df64 emulated double-precision
// ============================================================================

fn df64_quick_two_sum(a: f32, b: f32) -> vec2<f32> {
    let s = a + b;
    let e = b - (s - a);
    return vec2<f32>(s, e);
}

fn df64_two_sum(a: f32, b: f32) -> vec2<f32> {
    let s = a + b;
    let v = s - a;
    let e = (a - (s - v)) + (b - v);
    return vec2<f32>(s, e);
}

fn df64_two_prod(a: f32, b: f32) -> vec2<f32> {
    let p = a * b;
    let ca = 4097.0 * a;
    let ah = ca - (ca - a);
    let al = a - ah;
    let cb = 4097.0 * b;
    let bh = cb - (cb - b);
    let bl = b - bh;
    let e = ((ah * bh - p) + ah * bl + al * bh) + al * bl;
    return vec2<f32>(p, e);
}

fn df64_add(a: vec2<f32>, b: vec2<f32>) -> vec2<f32> {
    var s = df64_two_sum(a.x, b.x);
    s.y = s.y + a.y + b.y;
    return df64_quick_two_sum(s.x, s.y);
}

fn df64_sub(a: vec2<f32>, b: vec2<f32>) -> vec2<f32> {
    return df64_add(a, vec2<f32>(-b.x, -b.y));
}

fn df64_mul(a: vec2<f32>, b: vec2<f32>) -> vec2<f32> {
    var p = df64_two_prod(a.x, b.x);
    p.y = p.y + a.x * b.y + a.y * b.x;
    return df64_quick_two_sum(p.x, p.y);
}

fn df64_mul_f(a: vec2<f32>, b: f32) -> vec2<f32> {
    var p = df64_two_prod(a.x, b);
    p.y = p.y + a.y * b;
    return df64_quick_two_sum(p.x, p.y);
}

fn df64_from(a: f32) -> vec2<f32> {
    return vec2<f32>(a, 0.0);
}

fn df64_to_float(a: vec2<f32>) -> f32 {
    return a.x + a.y;
}

// ============================================================================
// df64 complex multiply
// ============================================================================

struct Df64Complex {
    re: vec2<f32>,
    im: vec2<f32>,
}

fn df64_cmul(a: Df64Complex, b: Df64Complex) -> Df64Complex {
    let rr = df64_sub(df64_mul(a.re, b.re), df64_mul(a.im, b.im));
    let ri = df64_add(df64_mul(a.re, b.im), df64_mul(a.im, b.re));
    return Df64Complex(rr, ri);
}

// ============================================================================
// df64 coordinate transform
// ============================================================================

struct CoordResult {
    re: vec2<f32>,
    im: vec2<f32>,
}

fn transformCoords_df64(fragCoord: vec2<f32>, cX_df: vec2<f32>, cY_df: vec2<f32>,
                        res: vec2<f32>, z_zoom: f32, rot: f32) -> CoordResult {
    var uv = (fragCoord - 0.5 * res) / min(res.x, res.y);
    let angle = -rot * TAU / 360.0;
    let c = cos(angle);
    let s = sin(angle);
    uv = vec2<f32>(c * uv.x + s * uv.y, -s * uv.x + c * uv.y);
    let scale = 2.5 / z_zoom;
    let uv_re_df = df64_mul_f(df64_from(uv.x), scale);
    let uv_im_df = df64_mul_f(df64_from(uv.y), scale);
    let re = df64_add(uv_re_df, cX_df);
    let im = df64_add(uv_im_df, cY_df);
    return CoordResult(re, im);
}

// ============================================================================
// Points of interest
// ============================================================================

struct POIData {
    center: vec4<f32>,
    deg: f32,
    maxZoom: f32,
}

fn getPOI(idx: i32) -> POIData {
    // center = vec4(hiX, hiY, loX, loY), deg, maxZoom
    // Origin POIs: maxZoom=7 (pixel coord precision limit)
    // Non-origin POIs: df64 split provides ~14 digits
    if (idx == 1) { return POIData(vec4<f32>(0.0, 0.0, 0.0, 0.0), 3.0, 7.0); }           // triplePoint3
    if (idx == 2) { return POIData(vec4<f32>(0.25, 0.4330126941204071, 0.0, 7.7718e-9), 3.0, 14.0); } // spiralJunction3
    if (idx == 3) { return POIData(vec4<f32>(0.0, 0.0, 0.0, 0.0), 5.0, 7.0); }           // starCenter5
    if (idx == 4) { return POIData(vec4<f32>(0.6545084714889526, 0.4755282700061798, 2.5699e-8, -1.1859e-8), 5.0, 14.0); } // pentaSpiral5
    if (idx == 5) { return POIData(vec4<f32>(0.0, 0.0, 0.0, 0.0), 6.0, 7.0); }           // hexWeb6
    if (idx == 6) { return POIData(vec4<f32>(0.0, 0.0, 0.0, 0.0), 8.0, 7.0); }           // octoFlower8
    return POIData(vec4<f32>(0.0, 0.0, 0.0, 0.0), 3.0, 7.0);
}

// ============================================================================
// Main
// ============================================================================

@fragment
fn main(@builtin(position) pos: vec4<f32>) -> @location(0) vec4<f32> {
    // Unpack uniforms
    let resolution = uniforms.data[0].xy;
    let time = uniforms.data[0].z;
    let degree = uniforms.data[0].w;

    let relaxation = uniforms.data[1].x;
    let iterations = uniforms.data[1].y;
    let toleranceU = uniforms.data[1].z;
    let poiU = uniforms.data[1].w;

    let centerHiX = uniforms.data[2].x;
    let centerHiY = uniforms.data[2].y;
    let centerLoX = uniforms.data[2].z;
    let centerLoY = uniforms.data[2].w;

    let zoomSpeed = uniforms.data[3].x;
    let zoomDepthU = uniforms.data[3].y;
    let degreeSpeed = uniforms.data[3].z;
    let degreeRangeU = uniforms.data[3].w;

    let relaxSpeed = uniforms.data[4].x;
    let relaxRangeU = uniforms.data[4].y;
    let rotationU = uniforms.data[4].z;
    let outputMode = uniforms.data[5].x;
    let invertU = uniforms.data[5].y;

    // Tile-aware global coords (mirror glsl/newton.glsl). When not tiling the
    // engine supplies tileOffset=(0,0) and fullResolution=resolution, so the
    // transform below is byte-identical to the previous shader.
    let tileOffset = uniforms.data[6].xy;
    let fullResolution = uniforms.data[6].zw;
    let frRes = select(resolution, fullResolution, fullResolution.x > 0.0);

    let maxIter = i32(iterations);
    let poiIdx = i32(poiU);
    let outMode = i32(outputMode);
    let doInvert = invertU > 0.5;

    // --- Effective parameters with animation ---

    var effDegree = degree;
    if (degreeSpeed > 0.0 && degreeRangeU > 0.0) {
        effDegree = effDegree + degreeRangeU * sin(time * degreeSpeed * TAU);
        effDegree = clamp(effDegree, 3.0, 8.0);
    }

    var effRelax = relaxation;
    if (relaxSpeed > 0.0 && relaxRangeU > 0.0) {
        effRelax = effRelax + relaxRangeU * sin(time * relaxSpeed * TAU * PHI);
        effRelax = clamp(effRelax, 0.5, 2.0);
    }

    // --- Center and zoom ---

    var cHi = vec2<f32>(centerHiX, centerHiY);
    var cLo = vec2<f32>(centerLoX, centerLoY);
    var effZoomDepth = zoomDepthU;

    if (poiIdx > 0) {
        let p = getPOI(poiIdx);
        cHi = p.center.xy + cHi;
        cLo = p.center.zw + cLo;
        effDegree = p.deg;
        effZoomDepth = min(zoomDepthU, p.maxZoom);
    }

    // Sinusoidal zoom: time 0 = zoomed out, time 0.5/speed = max depth, time 1/speed = zoomed out
    var zoom: f32;
    if (zoomSpeed > 0.0) {
        let zoomPhase = 0.5 * (1.0 - cos(time * zoomSpeed * TAU));
        zoom = pow(10.0, effZoomDepth * zoomPhase);
    } else {
        zoom = pow(10.0, effZoomDepth);
    }

    // --- df64 coordinate transform ---

    let coords = transformCoords_df64(pos.xy + tileOffset,
        vec2<f32>(cHi.x, cLo.x), vec2<f32>(cHi.y, cLo.y),
        frRes, zoom, rotationU);

    // --- Compute roots of z^n - 1 ---

    let intDeg = i32(floor(effDegree));
    let numRoots = intDeg;
    var roots: array<vec2<f32>, 8>;
    for (var k: i32 = 0; k < 8; k = k + 1) {
        if (k >= numRoots) { break; }
        let angle = TAU * f32(k) / f32(intDeg);
        roots[k] = vec2<f32>(cos(angle), sin(angle));
    }

    // --- df64 Newton iteration ---

    var iter: f32 = 0.0;
    var convergedRoot: i32 = -1;
    var convergeDist: f32 = 1.0;
    let bailout = 1e10 * effRelax;

    var zr_df = coords.re;
    var zi_df = coords.im;

    for (var n: i32 = 0; n < 500; n = n + 1) {
        if (n >= maxIter) { break; }

        // Compute z^(intDeg-1) via repeated df64 complex multiplication
        var pw = Df64Complex(df64_from(1.0), df64_from(0.0));
        for (var j: i32 = 0; j < 7; j = j + 1) {
            if (j >= intDeg - 1) { break; }
            pw = df64_cmul(pw, Df64Complex(zr_df, zi_df));
        }

        // z^intDeg = z^(intDeg-1) * z
        let zn = df64_cmul(pw, Df64Complex(zr_df, zi_df));

        // f(z) = z^n - 1
        let fzr = df64_sub(zn.re, df64_from(1.0));
        let fzi = zn.im;

        // f'(z) = n * z^(n-1)
        let fpzr = df64_mul_f(pw.re, f32(intDeg));
        let fpzi = df64_mul_f(pw.im, f32(intDeg));

        // Degenerate derivative guard
        let fpzr_f = df64_to_float(fpzr);
        let fpzi_f = df64_to_float(fpzi);
        if (fpzr_f * fpzr_f + fpzi_f * fpzi_f < 1e-20) { break; }

        // delta = f(z) / f'(z) via df64 complex division
        let denom = fpzr_f * fpzr_f + fpzi_f * fpzi_f;
        let inv_denom = 1.0 / denom;
        let nr = df64_add(df64_mul(fzr, fpzr), df64_mul(fzi, fpzi));
        let ni = df64_sub(df64_mul(fzi, fpzr), df64_mul(fzr, fpzi));
        let dr = df64_mul_f(nr, inv_denom);
        let di = df64_mul_f(ni, inv_denom);

        // z = z - relaxation * delta
        zr_df = df64_sub(zr_df, df64_mul_f(dr, effRelax));
        zi_df = df64_sub(zi_df, df64_mul_f(di, effRelax));

        // Divergence check
        let zx = df64_to_float(zr_df);
        let zy = df64_to_float(zi_df);
        if (zx * zx + zy * zy > bailout) { break; }

        // Convergence check
        for (var ck: i32 = 0; ck < 8; ck = ck + 1) {
            if (ck >= numRoots) { break; }
            let dx = zx - roots[ck].x;
            let dy = zy - roots[ck].y;
            let d = sqrt(dx * dx + dy * dy);
            if (d < toleranceU) {
                convergedRoot = ck;
                convergeDist = d;
                break;
            }
        }
        if (convergedRoot >= 0) { break; }

        iter = iter + 1.0;
    }

    // --- Smooth iteration count ---

    var smoothIter = iter;
    if (convergedRoot >= 0 && convergeDist > 0.0 && convergeDist < toleranceU) {
        smoothIter = iter - log2(log(convergeDist) / log(toleranceU));
    }

    // --- Output mapping ---

    var value: f32 = 0.0;
    let maxIterF = f32(maxIter);
    let numRootsF = f32(numRoots);

    if (outMode == 0) {
        value = smoothIter / maxIterF;
    } else if (outMode == 1) {
        if (convergedRoot >= 0) {
            value = f32(convergedRoot) / numRootsF;
        }
    } else {
        if (convergedRoot >= 0) {
            value = (f32(convergedRoot) + smoothIter / maxIterF) / numRootsF;
        }
    }

    if (doInvert) { value = 1.0 - value; }

    return vec4<f32>(vec3<f32>(value), 1.0);
}

/*
 * VNoise - WGSL port of simplified value noise synthesizer.
 * From nd/noise with colorization simplified to mono and rgb only.
 */

struct Uniforms {
    data : array<vec4<f32>, 5>,
};

@group(0) @binding(0) var<uniform> uniforms : Uniforms;

// NOISE_TYPE is a compile-time const injected by the runtime via injectDefines
// (see synth/noise/definition.js `globals.type.define`). Replacing the runtime
// dispatch with a compile-time constant lets the WGSL compiler dead-code-eliminate
// the unused noise variants — same fix as the GLSL backend (see noise.glsl header
// comment). The expander always provides this define for synth/noise programs.

var<private> resolution : vec2<f32>;
var<private> time : f32;
var<private> aspectRatio : f32;
var<private> scaleX : f32;
var<private> scaleY : f32;
var<private> seed : f32;
var<private> loopScale : f32;
var<private> speed : f32;
var<private> octaves : i32;
var<private> ridges : bool;
var<private> wrap : bool;
var<private> colorMode : i32;

const PI : f32 = 3.14159265359;
const TAU : f32 = 6.28318530718;

fn modulo(a: f32, b: f32) -> f32 {
    return a - b * floor(a / b);
}

fn map(value: f32, inMin: f32, inMax: f32, outMin: f32, outMax: f32) -> f32 {
    return outMin + (outMax - outMin) * (value - inMin) / (inMax - inMin);
}

fn pcg(v_in: vec3<u32>) -> vec3<u32> {
    var v = v_in * 1664525u + 1013904223u;
    v.x += v.y * v.z;
    v.y += v.z * v.x;
    v.z += v.x * v.y;
    v = v ^ (v >> vec3<u32>(16u));
    v.x += v.y * v.z;
    v.y += v.z * v.x;
    v.z += v.x * v.y;
    return v;
}

fn prng(p0: vec3<f32>) -> vec3<f32> {
    var p = p0;
    p.x = select(-p.x * 2.0 + 1.0, p.x * 2.0, p.x >= 0.0);
    p.y = select(-p.y * 2.0 + 1.0, p.y * 2.0, p.y >= 0.0);
    p.z = select(-p.z * 2.0 + 1.0, p.z * 2.0, p.z >= 0.0);
    let u = pcg(vec3<u32>(p));
    return vec3<f32>(u) / f32(0xffffffffu);
}

fn random(st: vec2<f32>) -> f32 {
    return prng(vec3<f32>(st, 0.0)).x;
}

fn periodicFunction(p: f32) -> f32 {
    return map(cos(p * TAU), -1.0, 1.0, 0.0, 1.0);
}

fn blendBicubic(p0: f32, p1: f32, p2: f32, p3: f32, t: f32) -> f32 {
    let t2 = t * t;
    let t3 = t2 * t;
    let b0 = (1.0 - t) * (1.0 - t) * (1.0 - t) / 6.0;
    let b1 = (3.0 * t3 - 6.0 * t2 + 4.0) / 6.0;
    let b2 = (-3.0 * t3 + 3.0 * t2 + 3.0 * t + 1.0) / 6.0;
    let b3 = t3 / 6.0;
    return p0 * b0 + p1 * b1 + p2 * b2 + p3 * b3;
}

fn catmullRom3(p0: f32, p1: f32, p2: f32, t: f32) -> f32 {
    let t2 = t * t;
    let t3 = t2 * t;
    return p1 + 0.5 * t * (p2 - p0) + 
           0.5 * t2 * (2.0*p0 - 5.0*p1 + 4.0*p2 - p0) +
           0.5 * t3 * (-p0 + 3.0*p1 - 3.0*p2 + p0);
}

fn catmullRom4(p0: f32, p1: f32, p2: f32, p3: f32, t: f32) -> f32 {
    return p1 + 0.5 * t * (p2 - p0 + t * (2.0 * p0 - 5.0 * p1 + 4.0 * p2 - p3 + t * (3.0 * (p1 - p2) + p3 - p0)));
}

fn quadratic3(p0: f32, p1: f32, p2: f32, t: f32) -> f32 {
    let t2 = t * t;
    return p0 * 0.5 * (1.0 - t) * (1.0 - t) +
           p1 * 0.5 * (-2.0 * t2 + 2.0 * t + 1.0) +
           p2 * 0.5 * t2;
}

fn blendLinearOrCosine(a: f32, b: f32, amount: f32, nType: i32) -> f32 {
    if (nType == 1) { return mix(a, b, amount); }
    return mix(a, b, smoothstep(0.0, 1.0, amount));
}

fn positiveModulo(value: i32, modulus: i32) -> i32 {
    if (modulus == 0) { return 0; }
    var r = value % modulus;
    if (r < 0) { r = r + modulus; }
    return r;
}

fn constantFromLatticeWithOffset(lattice: vec2<f32>, freq: vec2<f32>, s: f32, blend: f32, offset: vec2<i32>) -> f32 {
    let baseFloor = floor(lattice);
    let base = vec2<i32>(baseFloor) + offset;
    let fr = lattice - baseFloor;
    let seedInt = i32(floor(s));
    let sFrac = fract(s);
    let xCombined = fr.x + sFrac;
    var xi = base.x + i32(floor(xCombined));
    var yi = base.y;

    if (wrap) {
        let freqX = i32(freq.x + 0.5);
        let freqY = i32(freq.y + 0.5);
        if (freqX > 0) { xi = positiveModulo(xi, freqX); }
        if (freqY > 0) { yi = positiveModulo(yi, freqY); }
    }

    let xBits = u32(xi);
    let yBits = u32(yi);
    let seedBits = u32(seedInt);
    let fracBits = bitcast<u32>(sFrac);

    let jitter = vec3<u32>(
        (fracBits * 374761393u) ^ 0x9E3779B9u,
        (fracBits * 668265263u) ^ 0x7F4A7C15u,
        (fracBits * 2246822519u) ^ 0x94D049B4u
    );

    let state = vec3<u32>(xBits, yBits, seedBits) ^ jitter;
    let prngState = pcg(state);
    let noiseValue = f32(prngState.x) / f32(0xffffffffu);
    return periodicFunction(noiseValue - blend);
}

fn constantFromLattice(lattice: vec2<f32>, freq: vec2<f32>, s: f32, blend: f32) -> f32 {
    return constantFromLatticeWithOffset(lattice, freq, s, blend, vec2<i32>(0, 0));
}

fn constant(st: vec2<f32>, freq: vec2<f32>, s: f32, blend: f32) -> f32 {
    let lattice = st * freq;
    return constantFromLattice(lattice, freq, s, blend);
}

fn constantOffset(lattice: vec2<f32>, freq: vec2<f32>, s: f32, blend: f32, offset: vec2<i32>) -> f32 {
    return constantFromLatticeWithOffset(lattice, freq, s, blend, offset);
}

fn cubic3x3ValueNoise(st: vec2<f32>, freq: vec2<f32>, s: f32, blend: f32) -> f32 {
    let lattice = st * freq;
    let f = fract(lattice);
    let v00 = constantFromLatticeWithOffset(lattice, freq, s, blend, vec2<i32>(-1, -1));
    let v10 = constantFromLatticeWithOffset(lattice, freq, s, blend, vec2<i32>( 0, -1));
    let v20 = constantFromLatticeWithOffset(lattice, freq, s, blend, vec2<i32>( 1, -1));
    let v01 = constantFromLatticeWithOffset(lattice, freq, s, blend, vec2<i32>(-1,  0));
    let v11 = constantFromLattice(lattice, freq, s, blend);
    let v21 = constantFromLatticeWithOffset(lattice, freq, s, blend, vec2<i32>( 1,  0));
    let v02 = constantFromLatticeWithOffset(lattice, freq, s, blend, vec2<i32>(-1,  1));
    let v12 = constantFromLatticeWithOffset(lattice, freq, s, blend, vec2<i32>( 0,  1));
    let v22 = constantFromLatticeWithOffset(lattice, freq, s, blend, vec2<i32>( 1,  1));
    let y0 = quadratic3(v00, v10, v20, f.x);
    let y1 = quadratic3(v01, v11, v21, f.x);
    let y2 = quadratic3(v02, v12, v22, f.x);
    return quadratic3(y0, y1, y2, f.y);
}

fn bicubicValue(st: vec2<f32>, freq: vec2<f32>, s: f32, blend: f32) -> f32 {
    let lattice = st * freq;
    let x0y0 = constantOffset(lattice, freq, s, blend, vec2<i32>(-1, -1));
    let x0y1 = constantOffset(lattice, freq, s, blend, vec2<i32>(-1, 0));
    let x0y2 = constantOffset(lattice, freq, s, blend, vec2<i32>(-1, 1));
    let x0y3 = constantOffset(lattice, freq, s, blend, vec2<i32>(-1, 2));
    let x1y0 = constantOffset(lattice, freq, s, blend, vec2<i32>(0, -1));
    let x1y1 = constantFromLattice(lattice, freq, s, blend);
    let x1y2 = constantOffset(lattice, freq, s, blend, vec2<i32>(0, 1));
    let x1y3 = constantOffset(lattice, freq, s, blend, vec2<i32>(0, 2));
    let x2y0 = constantOffset(lattice, freq, s, blend, vec2<i32>(1, -1));
    let x2y1 = constantOffset(lattice, freq, s, blend, vec2<i32>(1, 0));
    let x2y2 = constantOffset(lattice, freq, s, blend, vec2<i32>(1, 1));
    let x2y3 = constantOffset(lattice, freq, s, blend, vec2<i32>(1, 2));
    let x3y0 = constantOffset(lattice, freq, s, blend, vec2<i32>(2, -1));
    let x3y1 = constantOffset(lattice, freq, s, blend, vec2<i32>(2, 0));
    let x3y2 = constantOffset(lattice, freq, s, blend, vec2<i32>(2, 1));
    let x3y3 = constantOffset(lattice, freq, s, blend, vec2<i32>(2, 2));
    let fr = fract(lattice);
    let y0 = blendBicubic(x0y0, x1y0, x2y0, x3y0, fr.x);
    let y1 = blendBicubic(x0y1, x1y1, x2y1, x3y1, fr.x);
    let y2 = blendBicubic(x0y2, x1y2, x2y2, x3y2, fr.x);
    let y3 = blendBicubic(x0y3, x1y3, x2y3, x3y3, fr.x);
    return blendBicubic(y0, y1, y2, y3, fr.y);
}

fn catmullRom3x3ValueNoise(st: vec2<f32>, freq: vec2<f32>, s: f32, blend: f32) -> f32 {
    let lattice = st * freq;
    let f = fract(lattice);
    let v00 = constantFromLatticeWithOffset(lattice, freq, s, blend, vec2<i32>(-1, -1));
    let v10 = constantFromLatticeWithOffset(lattice, freq, s, blend, vec2<i32>( 0, -1));
    let v20 = constantFromLatticeWithOffset(lattice, freq, s, blend, vec2<i32>( 1, -1));
    let v01 = constantFromLatticeWithOffset(lattice, freq, s, blend, vec2<i32>(-1,  0));
    let v11 = constantFromLattice(lattice, freq, s, blend);
    let v21 = constantFromLatticeWithOffset(lattice, freq, s, blend, vec2<i32>( 1,  0));
    let v02 = constantFromLatticeWithOffset(lattice, freq, s, blend, vec2<i32>(-1,  1));
    let v12 = constantFromLatticeWithOffset(lattice, freq, s, blend, vec2<i32>( 0,  1));
    let v22 = constantFromLatticeWithOffset(lattice, freq, s, blend, vec2<i32>( 1,  1));
    let y0 = catmullRom3(v00, v10, v20, f.x);
    let y1 = catmullRom3(v01, v11, v21, f.x);
    let y2 = catmullRom3(v02, v12, v22, f.x);
    return catmullRom3(y0, y1, y2, f.y);
}

fn catmullRom4x4ValueNoise(st: vec2<f32>, freq: vec2<f32>, s: f32, blend: f32) -> f32 {
    let lattice = st * freq;
    let x0y0 = constantOffset(lattice, freq, s, blend, vec2<i32>(-1, -1));
    let x0y1 = constantOffset(lattice, freq, s, blend, vec2<i32>(-1, 0));
    let x0y2 = constantOffset(lattice, freq, s, blend, vec2<i32>(-1, 1));
    let x0y3 = constantOffset(lattice, freq, s, blend, vec2<i32>(-1, 2));
    let x1y0 = constantOffset(lattice, freq, s, blend, vec2<i32>(0, -1));
    let x1y1 = constantFromLattice(lattice, freq, s, blend);
    let x1y2 = constantOffset(lattice, freq, s, blend, vec2<i32>(0, 1));
    let x1y3 = constantOffset(lattice, freq, s, blend, vec2<i32>(0, 2));
    let x2y0 = constantOffset(lattice, freq, s, blend, vec2<i32>(1, -1));
    let x2y1 = constantOffset(lattice, freq, s, blend, vec2<i32>(1, 0));
    let x2y2 = constantOffset(lattice, freq, s, blend, vec2<i32>(1, 1));
    let x2y3 = constantOffset(lattice, freq, s, blend, vec2<i32>(1, 2));
    let x3y0 = constantOffset(lattice, freq, s, blend, vec2<i32>(2, -1));
    let x3y1 = constantOffset(lattice, freq, s, blend, vec2<i32>(2, 0));
    let x3y2 = constantOffset(lattice, freq, s, blend, vec2<i32>(2, 1));
    let x3y3 = constantOffset(lattice, freq, s, blend, vec2<i32>(2, 2));
    let fr = fract(lattice);
    let y0 = catmullRom4(x0y0, x1y0, x2y0, x3y0, fr.x);
    let y1 = catmullRom4(x0y1, x1y1, x2y1, x3y1, fr.x);
    let y2 = catmullRom4(x0y2, x1y2, x2y2, x3y2, fr.x);
    let y3 = catmullRom4(x0y3, x1y3, x2y3, x3y3, fr.x);
    return catmullRom4(y0, y1, y2, y3, fr.y);
}

fn mod289v3(x: vec3<f32>) -> vec3<f32> { return x - floor(x * (1.0 / 289.0)) * 289.0; }
fn mod289v2(x: vec2<f32>) -> vec2<f32> { return x - floor(x * (1.0 / 289.0)) * 289.0; }
fn permute(x: vec3<f32>) -> vec3<f32> { return mod289v3(((x*34.0)+1.0)*x); }

fn simplexValue(st: vec2<f32>, freq: vec2<f32>, s: f32, blend: f32) -> f32 {
    let C = vec4<f32>(0.211324865405187, 0.366025403784439, -0.577350269189626, 0.024390243902439);
    var uv = st * freq;
    uv.x += s;
    let i = floor(uv + dot(uv, C.yy));
    let x0 = uv - i + dot(i, C.xx);
    let i1 = select(vec2<f32>(0.0, 1.0), vec2<f32>(1.0, 0.0), x0.x > x0.y);
    var x12 = x0.xyxy + C.xxzz;
    x12 = vec4<f32>(x12.xy - i1, x12.zw);
    let ii = mod289v2(i);
    let p = permute(permute(ii.y + vec3<f32>(0.0, i1.y, 1.0)) + ii.x + vec3<f32>(0.0, i1.x, 1.0));
    var m = max(vec3<f32>(0.5) - vec3<f32>(dot(x0,x0), dot(x12.xy,x12.xy), dot(x12.zw,x12.zw)), vec3<f32>(0.0));
    m = m*m;
    m = m*m;
    let x = 2.0 * fract(p * C.www) - 1.0;
    let h = abs(x) - 0.5;
    let ox = floor(x + 0.5);
    let a0 = x - ox;
    m *= 1.79284291400159 - 0.85373472095314 * (a0*a0 + h*h);
    var g: vec3<f32>;
    g.x = a0.x * x0.x + h.x * x0.y;
    g.y = a0.y * x12.x + h.y * x12.y;
    g.z = a0.z * x12.z + h.z * x12.w;
    let v = 130.0 * dot(m, g);
    return periodicFunction(map(v, -1.0, 1.0, 0.0, 1.0) - blend);
}

fn sineNoise(st: vec2<f32>, freq: vec2<f32>, s: f32, blend: f32) -> f32 {
    var stt = st * freq;
    stt.x += s;
    let a = blend;
    let b = blend;
    let c = 1.0 - blend;
    let r1 = prng(vec3<f32>(s, s, s)) * 0.75 + 0.125;
    let r2 = prng(vec3<f32>(s + 10.0, s + 10.0, s + 10.0)) * 0.75 + 0.125;
    let x = sin(r1.x * stt.y + sin(r1.y * stt.x + a) + sin(r1.z * stt.x + b) + c);
    let y = sin(r2.x * stt.x + sin(r2.y * stt.y + b) + sin(r2.z * stt.y + c) + a);
    return (x + y) * 0.5 + 0.5;
}

fn value(st: vec2<f32>, freq: vec2<f32>, s: f32, blend: f32) -> f32 {
    if (NOISE_TYPE == 3) { return catmullRom3x3ValueNoise(st, freq, s, blend); }
    if (NOISE_TYPE == 4) { return catmullRom4x4ValueNoise(st, freq, s, blend); }
    if (NOISE_TYPE == 5) { return cubic3x3ValueNoise(st, freq, s, blend); }
    if (NOISE_TYPE == 6) { return bicubicValue(st, freq, s, blend); }
    if (NOISE_TYPE == 10) { return simplexValue(st, freq, s, blend); }
    if (NOISE_TYPE == 11) { return sineNoise(st, freq, s, blend); }

    let lattice = st * freq;
    let x1y1 = constantFromLattice(lattice, freq, s, blend);
    if (NOISE_TYPE == 0) { return x1y1; }

    let x2y1 = constantOffset(lattice, freq, s, blend, vec2<i32>(1, 0));
    let x1y2 = constantOffset(lattice, freq, s, blend, vec2<i32>(0, 1));
    let x2y2 = constantOffset(lattice, freq, s, blend, vec2<i32>(1, 1));
    let fr = fract(lattice);
    let aa = blendLinearOrCosine(x1y1, x2y1, fr.x, NOISE_TYPE);
    let bb = blendLinearOrCosine(x1y2, x2y2, fr.x, NOISE_TYPE);
    return blendLinearOrCosine(aa, bb, fr.y, NOISE_TYPE);
}

fn circles(st: vec2<f32>, freq: f32) -> f32 {
    let dist = length(st - vec2<f32>(0.5 * aspectRatio, 0.5));
    return dist * freq;
}

fn rings(st: vec2<f32>, freq: f32) -> f32 {
    let dist = length(st - vec2<f32>(0.5 * aspectRatio, 0.5));
    return cos(dist * PI * freq);
}

fn diamonds(st: vec2<f32>, freq: f32, pos: vec2<f32>) -> f32 {
    var stt = pos / resolution.y;
    stt -= vec2<f32>(0.5 * aspectRatio, 0.5);
    stt *= freq;
    return (cos(stt.x * PI) + cos(stt.y * PI));
}

fn shape(st: vec2<f32>, sides: i32, blend: f32) -> f32 {
    let stt = st * 2.0 - vec2<f32>(aspectRatio, 1.0);
    let a = atan2(stt.x, stt.y) + PI;
    let r = TAU / f32(sides);
    return cos(floor(0.5 + a / r) * r - a) * length(stt) * blend;
}

fn offset(st: vec2<f32>, freq: vec2<f32>, pos: vec2<f32>) -> f32 {
    if (LOOP_OFFSET == 10) { return circles(st, freq.x); }
    if (LOOP_OFFSET == 20) { return shape(st, 3, freq.x * 0.5); }
    if (LOOP_OFFSET == 30) { return (abs(st.x - 0.5 * aspectRatio) + abs(st.y - 0.5)) * freq.x * 0.5; }
    if (LOOP_OFFSET == 40) { return shape(st, 4, freq.x * 0.5); }
    if (LOOP_OFFSET == 50) { return shape(st, 5, freq.x * 0.5); }
    if (LOOP_OFFSET == 60) { return shape(st, 6, freq.x * 0.5); }
    if (LOOP_OFFSET == 70) { return shape(st, 7, freq.x * 0.5); }
    if (LOOP_OFFSET == 80) { return shape(st, 8, freq.x * 0.5); }
    if (LOOP_OFFSET == 90) { return shape(st, 9, freq.x * 0.5); }
    if (LOOP_OFFSET == 100) { return shape(st, 10, freq.x * 0.5); }
    if (LOOP_OFFSET == 110) { return shape(st, 11, freq.x * 0.5); }
    if (LOOP_OFFSET == 120) { return shape(st, 12, freq.x * 0.5); }
    if (LOOP_OFFSET == 200) { return st.x * freq.x * 0.5; }
    if (LOOP_OFFSET == 210) { return st.y * freq.x * 0.5; }
    if (LOOP_OFFSET == 300) {
        let stt = st - vec2<f32>(aspectRatio * 0.5, 0.5);
        return value(stt, freq, seed + 50.0, 0.0);
    }
    if (LOOP_OFFSET == 400) { return 1.0 - rings(st, freq.x); }
    if (LOOP_OFFSET == 410) { return 1.0 - diamonds(st, freq.x, pos); }
    return 0.0;
}

fn generate_octave(st: vec2<f32>, freq: vec2<f32>, s: f32, blend: f32, layer: f32) -> vec3<f32> {
    var color = vec3<f32>(0.0);
    color.r = value(st, freq, s, blend);
    color.g = value(st, freq, s + 10.0, blend);
    color.b = value(st, freq, s + 20.0, blend);
    return color;
}

fn multires(st_in: vec2<f32>, freq: vec2<f32>, oct: i32, s: f32, blend: f32) -> vec3<f32> {
    let st = st_in;
    var color = vec3<f32>(0.0);
    var multiplicand = 0.0;

    for (var i = 1; i <= oct; i++) {
        let multiplier = pow(2.0, f32(i));
        let baseFreq = freq * 0.5 * multiplier;
        multiplicand += 1.0 / multiplier;

        let layer = generate_octave(st, baseFreq, s + 10.0 * f32(i), blend, f32(i));

        color = color + layer / multiplier;
    }

    color = color / multiplicand;

    // Simplified colorization: mono (0) or rgb (1) only
    if (colorMode == 0) {
        // mono - use blue channel
        var b = color.b;
        if (ridges) { b = 1.0 - abs(b * 2.0 - 1.0); }
        return vec3<f32>(b);
    } else {
        // rgb
        if (ridges) {
            color.r = 1.0 - abs(color.r * 2.0 - 1.0);
            color.g = 1.0 - abs(color.g * 2.0 - 1.0);
            color.b = 1.0 - abs(color.b * 2.0 - 1.0);
        }
        return color;
    }
}

@fragment
fn main(@builtin(position) position: vec4<f32>) -> @location(0) vec4<f32> {
    // Unpack uniforms
    resolution = uniforms.data[0].xy;
    time = uniforms.data[0].z;
    aspectRatio = uniforms.data[0].w;
    scaleX = uniforms.data[1].x;
    scaleY = uniforms.data[1].y;
    seed = uniforms.data[1].z;
    loopScale = uniforms.data[1].w;
    speed = uniforms.data[2].x;
    // uniforms.data[2].y was loopOffset (now compile-time LOOP_OFFSET)
    octaves = i32(uniforms.data[2].w);
    ridges = uniforms.data[3].x > 0.5;
    wrap = uniforms.data[3].y > 0.5;
    colorMode = i32(uniforms.data[3].z);

    var color = vec4<f32>(0.0, 0.0, 0.0, 1.0);
    let tileOffset = uniforms.data[4].xy;
    let fullResolution = uniforms.data[4].zw;
    var st = (position.xy + tileOffset) / fullResolution.y;
    let centered = st - vec2<f32>(aspectRatio * 0.5, 0.5);

    var freq = vec2<f32>(1.0);
    var lf = vec2<f32>(1.0);

    if (NOISE_TYPE == 11) {
        freq.x = map(scaleX, 1.0, 100.0, 40.0, 1.0);
        freq.y = map(scaleY, 1.0, 100.0, 40.0, 1.0);
        lf = vec2<f32>(map(loopScale, 1.0, 100.0, 10.0, 1.0));
    } else if (NOISE_TYPE == 10) {
        freq.x = map(scaleX, 1.0, 100.0, 6.0, 0.5);
        freq.y = map(scaleY, 1.0, 100.0, 6.0, 0.5);
        lf = vec2<f32>(map(loopScale, 1.0, 100.0, 6.0, 0.5));
    } else {
        freq.x = map(scaleX, 1.0, 100.0, 20.0, 3.0);
        freq.y = map(scaleY, 1.0, 100.0, 20.0, 3.0);
        lf = vec2<f32>(map(loopScale, 1.0, 100.0, 12.0, 3.0));
    }

    if (LOOP_OFFSET == 300) {
        var nominalFreq = vec2<f32>(1.0);
        if (NOISE_TYPE == 11) {
            let base = map(75.0, 1.0, 100.0, 40.0, 1.0);
            nominalFreq = vec2<f32>(base);
        } else if (NOISE_TYPE == 10) {
            let base = map(75.0, 1.0, 100.0, 6.0, 0.5);
            nominalFreq = vec2<f32>(base);
        } else {
            let base = map(75.0, 1.0, 100.0, 20.0, 3.0);
            nominalFreq = vec2<f32>(base);
        }
        lf *= freq / nominalFreq;
    }

    if (NOISE_TYPE != 4 && NOISE_TYPE != 10 && wrap) {
        freq = floor(freq);
        if (LOOP_OFFSET == 300) {
            lf = floor(lf);
        }
    }

    var t = 1.0;
    if (speed < 0.0) {
        t = time + offset(st, lf, position.xy);
    } else {
        t = time - offset(st, lf, position.xy);
    }
    let blend = periodicFunction(t) * abs(speed) * 0.01;

    color = vec4<f32>(multires(centered, freq, octaves, seed, blend), 1.0);
    return color;
}

// WGSL version – WebGPU
@group(0) @binding(0) var<uniform> resolution: vec2<f32>;
@group(0) @binding(1) var<uniform> aspect: f32;
@group(0) @binding(2) var<uniform> time: f32;
@group(0) @binding(3) var<uniform> oscType: i32;
@group(0) @binding(4) var<uniform> frequency: i32;
@group(0) @binding(5) var<uniform> speed: f32;
@group(0) @binding(6) var<uniform> rotation: f32;
@group(0) @binding(7) var<uniform> seed: i32;
@group(0) @binding(8) var<uniform> tileOffset: vec2<f32>;
@group(0) @binding(9) var<uniform> fullResolution: vec2<f32>;

const PI: f32 = 3.141592653589793;
const TAU: f32 = 6.283185307179586;

// Simple 1D hash for noise
fn hash11(p: f32, s: f32) -> f32 {
    var pv = fract(p * 234.34 + s * 0.7183);
    pv = pv + pv * (pv + 34.23);
    return fract(pv * pv);
}

// Value noise 1D - tiles at integer frequency boundaries
fn tilingNoise1D(x: f32, freq: f32, s: f32) -> f32 {
    // x is in [0, 1] range, scale by frequency
    let p = x * freq;
    let i = floor(p);
    var f = fract(p);
    f = f * f * (3.0 - 2.0 * f);  // smoothstep

    // Wrap indices for seamless tiling
    let i0 = i - freq * floor(i / freq);
    let i1 = (i + 1.0) - freq * floor((i + 1.0) / freq);

    let a = hash11(i0, s);
    let b = hash11(i1, s);

    return mix(a, b, f);
}

// Periodic value function: h/t Etienne Jacob
// https://bleuje.github.io/tutorial2/
// Python: periodic_value(time, value) = normalized_sine((time - value) * tau)
fn periodicValue(t: f32, v: f32) -> f32 {
    return (sin((t - v) * TAU) + 1.0) * 0.5;
}

// Rotate 2D coordinates
fn rotate2D(p: vec2<f32>, angle: f32) -> vec2<f32> {
    let s = sin(angle);
    let c = cos(angle);
    return vec2<f32>(p.x * c - p.y * s, p.x * s + p.y * c);
}

// All oscillator functions return 0->1->0 over t=0..1
fn oscSine(t: f32) -> f32 {
    // Use half-cycle sine: 0->1->0 over t=0..1
    return sin(fract(t) * PI);
}

fn oscLinear(t: f32) -> f32 {
    // Triangle wave: 0->1->0 over t=0..1
    let tf = fract(t);
    return 1.0 - abs(tf * 2.0 - 1.0);
}

fn oscSawtooth(t: f32) -> f32 {
    // Sawtooth: 0->1 over t=0..1
    return fract(t);
}

fn oscSawtoothInv(t: f32) -> f32 {
    // Inverted sawtooth: 1->0 over t=0..1
    return 1.0 - fract(t);
}

fn oscSquare(t: f32) -> f32 {
    // Square wave: 0 or 1
    return step(0.5, fract(t));
}

@fragment
fn main(@builtin(position) position: vec4<f32>) -> @location(0) vec4<f32> {
    var res = fullResolution;
    if (res.x < 1.0) { res = vec2<f32>(1024.0, 1024.0); }

    // Normalized coordinates
    var st = (position.xy + tileOffset) / res;

    // Center for rotation
    st = st - 0.5;
    st.x = st.x * aspect;

    // Apply rotation
    let rotRad = rotation * PI / 180.0;
    st = rotate2D(st, rotRad);

    // Spatial position in [0, 1] for noise sampling
    let spatialPos = st.y + 0.5;
    let freq = f32(frequency);

    // The oscillator value is based on position along y-axis
    // frequency controls how many bands appear across the image
    // speed controls how fast the animation runs
    let spatialPhase = st.y * freq;
    let timePhase = time * speed;
    let t = spatialPhase + timePhase;

    var val: f32;
    if (oscType == 0) {
        // Sine
        val = oscSine(t);
    } else if (oscType == 1) {
        // Linear (triangle)
        val = oscLinear(t);
    } else if (oscType == 2) {
        // Sawtooth
        val = oscSawtooth(t);
    } else if (oscType == 3) {
        // Sawtooth inverted
        val = oscSawtoothInv(t);
    } else if (oscType == 4) {
        // Square
        val = oscSquare(t);
    } else if (oscType == 5) {
        // noise1d - scrolling version of noise2d
        // At t=0, must match noise2d exactly
        // Then scrolls the pattern over time
        let scrollOffset = fract(time * speed);
        let scrolledPos = fract(spatialPos + scrollOffset);

        // Same computation as noise2d at t=0
        let timeNoise = tilingNoise1D(scrolledPos, freq, f32(seed) + 12345.0);
        let valueNoise = tilingNoise1D(scrolledPos, freq, f32(seed));
        let scaledTime = periodicValue(0.0, timeNoise) * speed;
        val = periodicValue(scaledTime, valueNoise);
    } else {
        // noise2d (oscType == 6) - two-stage periodic
        // Python: scaled_time = periodic_value(time, time_noise) * speed
        //         result = periodic_value(scaled_time, value_noise)

        // Get noise values at this spatial position (same sampling as noise1d)
        let timeNoise = tilingNoise1D(spatialPos, freq, f32(seed) + 12345.0);
        let valueNoise = tilingNoise1D(spatialPos, freq, f32(seed));

        // Two-stage periodic: time -> periodic -> scale -> periodic
        let scaledTime = periodicValue(time, timeNoise) * speed;
        val = periodicValue(scaledTime, valueNoise);
    }

    return vec4<f32>(vec3<f32>(val), 1.0);
}

// WGSL version – WebGPU
// Consolidated into a single Uniforms struct so the fragment stage holds
// 1 uniform buffer instead of 13 (the WebGPU per-stage limit is 12).
struct Uniforms {
    resolution: vec2<f32>,
    aspect: f32,
    patternType: i32,
    scale: f32,
    thickness: f32,
    smoothness: f32,
    rotation: f32,
    animation: i32,
    speed: f32,
    time: f32,
    skew: f32,
    fgColor: vec3<f32>,
    bgColor: vec3<f32>,
    tileOffset: vec2<f32>,
    fullResolution: vec2<f32>,
}
@group(0) @binding(0) var<uniform> u: Uniforms;

const PI: f32 = 3.14159265359;
const SQRT3: f32 = 1.7320508075688772;

// Pattern type constants
const CHECKERBOARD: i32 = 0;
const CONCENTRIC_RINGS: i32 = 1;
const DOTS: i32 = 2;
const GRID: i32 = 3;
const HEXAGONS: i32 = 4;
const RADIAL_LINES: i32 = 5;
const SPIRAL_PATTERN: i32 = 6;
const STRIPES: i32 = 7;
const TRIANGULAR_GRID: i32 = 8;
const HEARTS: i32 = 9;
const WAVES: i32 = 10;
const ZIGZAG: i32 = 11;
const TAU: f32 = 6.28318530718;

// Rotate a 2D point
fn rotate2D(p: vec2<f32>, angle: f32) -> vec2<f32> {
    let c = cos(angle);
    let s = sin(angle);
    return vec2<f32>(p.x * c - p.y * s, p.x * s + p.y * c);
}

// Stripes pattern
fn stripes(p: vec2<f32>, t: f32, sm: f32) -> f32 {
    let stripe = fract(p.x);
    // Apply smoothness to both edges of the stripe
    let edge1 = smoothstep(0.5 - t * 0.5 - sm, 0.5 - t * 0.5 + sm, stripe);
    let edge2 = smoothstep(0.5 + t * 0.5 - sm, 0.5 + t * 0.5 + sm, stripe);
    return edge1 - edge2;
}

// Checkerboard pattern
fn checkerboard(p: vec2<f32>, sm: f32) -> f32 {
    let f = fract(p);
    // Distance to nearest cell edge
    let d = min(min(f.x, 1.0 - f.x), min(f.y, 1.0 - f.y));
    // Determine which cell we're in
    let cell = floor(p);
    let check = (cell.x + cell.y) - 2.0 * floor((cell.x + cell.y) / 2.0);
    // Apply smoothness at edges
    let edge = smoothstep(0.0, sm * 0.5, d);
    return mix(1.0 - check, check, edge);
}

// Grid pattern (lines forming a grid)
fn grid(p: vec2<f32>, t: f32, sm: f32) -> f32 {
    let f = fract(p);
    let lineX = smoothstep(t * 0.5 - sm, t * 0.5 + sm, abs(f.x - 0.5));
    let lineY = smoothstep(t * 0.5 - sm, t * 0.5 + sm, abs(f.y - 0.5));
    return 1.0 - min(lineX, lineY);
}

// Dots pattern (circles on a grid)
fn dots(p: vec2<f32>, t: f32, sm: f32) -> f32 {
    let f = fract(p) - vec2<f32>(0.5, 0.5);
    let d = length(f);
    let radius = t * 0.5;
    return 1.0 - smoothstep(radius - sm, radius + sm, d);
}

// Hexagon distance function
fn hexDist(p: vec2<f32>) -> f32 {
    let ap = abs(p);
    return max(ap.x * 0.5 + ap.y * (SQRT3 / 2.0), ap.x);
}

// Hexagons pattern
fn hexagons(p: vec2<f32>, t: f32, sm: f32) -> f32 {
    // Scale for hexagonal grid
    let s = vec2<f32>(1.0, SQRT3);
    let h = s * 0.5;

    // Two offset grids
    let a = ((p % s) + s) % s - h;
    let b = (((p + h) % s) + s) % s - h;

    // Choose closest hexagon center
    var g: vec2<f32>;
    if (length(a) < length(b)) {
        g = a;
    } else {
        g = b;
    }

    let d = hexDist(g);
    let edge = 0.5 * t;
    return smoothstep(edge + sm, edge - sm, d);
}

// Concentric rings pattern (timeOffset expands/contracts from center)
fn concentricRings(p: vec2<f32>, t: f32, sm: f32, timeOffset: f32) -> f32 {
    let d = fract(length(p) + timeOffset);
    let edge1 = smoothstep(0.5 - t * 0.5 - sm, 0.5 - t * 0.5 + sm, d);
    let edge2 = smoothstep(0.5 + t * 0.5 - sm, 0.5 + t * 0.5 + sm, d);
    return edge1 - edge2;
}

// Radial lines pattern (timeOffset rotates around center)
fn radialLines(p: vec2<f32>, t: f32, sm: f32, timeOffset: f32) -> f32 {
    let lineCount = floor(u.scale);
    let angle = atan2(p.y, p.x) + timeOffset * TAU;
    let d = fract(angle / TAU * lineCount);
    let edge1 = smoothstep(0.5 - t * 0.5 - sm, 0.5 - t * 0.5 + sm, d);
    let edge2 = smoothstep(0.5 + t * 0.5 - sm, 0.5 + t * 0.5 + sm, d);
    return edge1 - edge2;
}

// Triangular grid pattern
fn triangularGrid(p: vec2<f32>, t: f32, sm: f32) -> f32 {
    let skewed = vec2<f32>(p.x - p.y / SQRT3, p.y * 2.0 / SQRT3);
    let cell = floor(skewed);
    let f = fract(skewed);

    var d: f32;
    if (f.x + f.y < 1.0) {
        d = min(min(f.x, f.y), 1.0 - f.x - f.y);
    } else {
        d = min(min(1.0 - f.x, 1.0 - f.y), f.x + f.y - 1.0);
    }

    let edge = (1.0 - t) * 0.4;
    return smoothstep(edge - sm, edge + sm, d);
}

// Spiral pattern (timeOffset rotates arms)
fn spiralPattern(p: vec2<f32>, t: f32, sm: f32, timeOffset: f32) -> f32 {
    let dist = length(p);
    let angle = atan2(p.y, p.x) + timeOffset * TAU;
    let d = fract(angle / TAU + dist);
    let edge1 = smoothstep(0.5 - t * 0.5 - sm, 0.5 - t * 0.5 + sm, d);
    let edge2 = smoothstep(0.5 + t * 0.5 - sm, 0.5 + t * 0.5 + sm, d);
    return edge1 - edge2;
}

// Heart SDF (based on Inigo Quilez)
fn heartSDF(p_in: vec2<f32>) -> f32 {
    var p = vec2<f32>(abs(p_in.x), p_in.y);
    if (p.y + p.x > 1.0) {
        let d = p - vec2<f32>(0.25, 0.75);
        return sqrt(dot(d, d)) - sqrt(2.0) / 4.0;
    }
    let d1 = p - vec2<f32>(0.0, 1.0);
    let proj = 0.5 * max(p.x + p.y, 0.0);
    let d2 = p - proj;
    return sqrt(min(dot(d1, d1), dot(d2, d2))) * sign(p.x - p.y);
}

// Hearts pattern (tiled heart shapes)
fn hearts(p: vec2<f32>, t: f32, sm: f32) -> f32 {
    var cell = fract(p) - 0.5;
    cell.y += 0.25;
    let d = heartSDF(cell * 2.4);
    let radius = 0.15 - (t * 0.15);
    let s = min(sm, radius + 0.15);
    return 1.0 - smoothstep(-radius - s, -radius + s, d);
}

// Waves pattern (sine-displaced horizontal lines)
fn waves(p: vec2<f32>, t: f32, sm: f32) -> f32 {
    var y = fract(p.y) - 0.5;
    y -= cos(p.x * TAU) * 0.15;
    let dist = abs(y);
    let halfW = t * 0.2;
    let s = min(sm, halfW + 0.01);
    return 1.0 - smoothstep(halfW - s, halfW + s, dist);
}

// Zigzag pattern (V-shaped line per cell)
fn zigzag(p: vec2<f32>, t: f32, sm: f32) -> f32 {
    let f = fract(p);
    // Zigzag line: y = 1 - 2*abs(x - 0.5), scaled to 0.25–0.75 range
    let lineY = 1.0 - 2.0 * abs(f.x - 0.5);
    let dist = abs(f.y - lineY * 0.5 - 0.25);
    // Max vertical distance to cell edge is 0.25; cap halfW + sm to stay within
    let halfW = t * 0.12;
    let s = min(sm, max(0.24 - halfW, 0.005));
    return 1.0 - smoothstep(halfW - s, halfW + s, dist);
}

@fragment
fn main(@builtin(position) position: vec4<f32>) -> @location(0) vec4<f32> {
    // Normalize coordinates
    let globalCoord = position.xy + u.tileOffset;
    var st = globalCoord / u.fullResolution;
    st = (st - vec2<f32>(0.5, 0.5)) * 2.0;
    st.x = st.x * u.aspect;

    // Apply rotation
    let rad = u.rotation * PI / 180.0;
    st = rotate2D(st, rad);

    // Apply animation rotation/pan (only for non-centered patterns)
    let centered = u.patternType == CONCENTRIC_RINGS || u.patternType == RADIAL_LINES || u.patternType == SPIRAL_PATTERN;
    if (!centered && u.animation == 2) {
        st = rotate2D(st, u.time * TAU * floor(u.speed));
    }

    // Horizontal shear (screen-vertical axis), applied as the final transform
    st.x = st.x + st.y * u.skew;

    // Apply scale, mapping so lower scale = higher frequency
    var p = st * (21.0 - u.scale);

    if (!centered && u.animation == 1) {
        // Checkerboard's spatial period along p.x is 2 (cell parity flips every unit),
        // so double the shift to keep the time=1 wrap landing on an even cell boundary.
        let panPeriod = select(1.0, 2.0, u.patternType == CHECKERBOARD);
        p.x += u.time * -floor(u.speed) * panPeriod;
    }

    // Compute pattern value
    var m: f32 = 0.0;

    if (u.patternType == CHECKERBOARD) {
        m = checkerboard(p, u.smoothness);
    } else if (u.patternType == CONCENTRIC_RINGS) {
        m = concentricRings(p, u.thickness, u.smoothness, -u.time * floor(u.speed));
    } else if (u.patternType == DOTS) {
        m = dots(p, u.thickness, u.smoothness);
    } else if (u.patternType == GRID) {
        m = grid(p, u.thickness, u.smoothness);
    } else if (u.patternType == HEXAGONS) {
        m = hexagons(p, u.thickness, u.smoothness);
    } else if (u.patternType == RADIAL_LINES) {
        m = radialLines(p, u.thickness, u.smoothness, u.time * floor(u.speed));
    } else if (u.patternType == SPIRAL_PATTERN) {
        m = spiralPattern(p, u.thickness, u.smoothness, -u.time * floor(u.speed));
    } else if (u.patternType == STRIPES) {
        m = stripes(p, u.thickness, u.smoothness);
    } else if (u.patternType == TRIANGULAR_GRID) {
        m = triangularGrid(p, u.thickness, u.smoothness);
    } else if (u.patternType == HEARTS) {
        m = hearts(p, u.thickness, u.smoothness);
    } else if (u.patternType == WAVES) {
        m = waves(p, u.thickness, u.smoothness);
    } else if (u.patternType == ZIGZAG) {
        m = zigzag(p, u.thickness, u.smoothness);
    }

    // Mix colors
    let color = mix(u.bgColor, u.fgColor, m);

    return vec4<f32>(color, 1.0);
}

// WGSL version – WebGPU
//
// DIMENSIONS is a compile-time const injected by the runtime via injectDefines.
// See synth/perlin/definition.js `globals.dimensions.define`. Picking 2D vs 3D
// at compile time lets the WGSL compiler dead-code-eliminate the unused
// implementation. The Params.dimensions field is left in place to preserve the
// uniform layout but is no longer read by the shader.

struct Params {
    resolution: vec2<f32>,
    aspect: f32,
    time: f32,
    scale: f32,
    seed: i32,
    octaves: i32,
    colorMode: i32,
    dimensions: i32,
    ridges: i32,
    speed: f32,
    warpIterations: i32,
    warpScale: f32,
    warpIntensity: f32,
    tileOffset: vec2<f32>,
    fullResolution: vec2<f32>,
    renderScale: f32,
}

@group(0) @binding(0) var<uniform> params: Params;

/* 3D gradient noise with quintic interpolation
   Animated using periodic z-axis for seamless looping
   2D output is a cross-section through 3D noise volume

   Also supports 2D periodic noise using time-animated gradients */

const TAU: f32 = 6.283185307179586;
const Z_PERIOD: f32 = 4.0;  // Period length in z-axis lattice units

// PCG PRNG for 2D mode
fn pcg(v_in: vec3<u32>) -> vec3<u32> {
    var v = v_in * 1664525u + 1013904223u;
    v.x = v.x + v.y * v.z;
    v.y = v.y + v.z * v.x;
    v.z = v.z + v.x * v.y;
    v = v ^ (v >> vec3<u32>(16u));
    v.x = v.x + v.y * v.z;
    v.y = v.y + v.z * v.x;
    v.z = v.z + v.x * v.y;
    return v;
}

fn prng(p_in: vec3<f32>) -> vec3<f32> {
    var p = p_in;
    p.x = select(-p.x * 2.0 + 1.0, p.x * 2.0, p.x >= 0.0);
    p.y = select(-p.y * 2.0 + 1.0, p.y * 2.0, p.y >= 0.0);
    p.z = select(-p.z * 2.0 + 1.0, p.z * 2.0, p.z >= 0.0);
    return vec3<f32>(pcg(vec3<u32>(p))) / f32(0xffffffff);
}

// 3D hash using multiple rounds of mixing
// Based on techniques from "Hash Functions for GPU Rendering" (Jarzynski & Olano, 2020)
fn hash3(p: vec3<f32>) -> f32 {
    // Add seed to input to vary the noise pattern
    let ps = p + f32(params.seed) * 0.1;

    // Convert to unsigned integer values via large multipliers
    var q = vec3<u32>(vec3<i32>(ps * 1000.0) + 65536);

    // Multiple rounds of mixing for thorough decorrelation
    q = q * 1664525u + 1013904223u;  // LCG constants
    q.x = q.x + q.y * q.z;
    q.y = q.y + q.z * q.x;
    q.z = q.z + q.x * q.y;

    q = q ^ (q >> vec3<u32>(16u));

    q.x = q.x + q.y * q.z;
    q.y = q.y + q.z * q.x;
    q.z = q.z + q.x * q.y;

    return f32(q.x ^ q.y ^ q.z) / 4294967295.0;
}

// Gradient from hash - returns normalized 3D vector
fn grad3(p: vec3<f32>) -> vec3<f32> {
    let h1 = hash3(p);
    let h2 = hash3(p + 127.1);
    let h3 = hash3(p + 269.5);

    // Generate independent gradient components - each component is [-1, 1]
    let g = vec3<f32>(
        h1 * 2.0 - 1.0,
        h2 * 2.0 - 1.0,
        h3 * 2.0 - 1.0
    );

    return normalize(g);
}

// Quintic interpolation for smooth transitions
fn quintic(t: f32) -> f32 {
    return t * t * t * (t * (t * 6.0 - 15.0) + 10.0);
}

fn smoothlerp(x: f32, a: f32, b: f32) -> f32 {
    return a + quintic(x) * (b - a);
}

// Wrap z index for periodicity at lattice level
fn wrapZ(z: f32) -> f32 {
    return (z % Z_PERIOD + Z_PERIOD) % Z_PERIOD;
}

// 2D periodic grid function - gradient angle animates with time
fn grid2D(st: vec2<f32>, cell: vec2<f32>, timeAngle: f32, channelOffset: f32) -> f32 {
    var angle = prng(vec3<f32>(cell + f32(params.seed), 1.0)).r * TAU;
    angle = angle + timeAngle + channelOffset * TAU;  // Animate gradient rotation
    let gradient = vec2<f32>(cos(angle), sin(angle));
    let dist = st - cell;
    return dot(gradient, dist);
}

// 2D periodic Perlin noise - time animates gradient angles for seamless loop
fn noise2D(st: vec2<f32>, timeAngle: f32, channelOffset: f32) -> f32 {
    let cell = floor(st);
    let f = fract(st);

    let tl = grid2D(st, cell, timeAngle, channelOffset);
    let tr = grid2D(st, vec2<f32>(cell.x + 1.0, cell.y), timeAngle, channelOffset);
    let bl = grid2D(st, vec2<f32>(cell.x, cell.y + 1.0), timeAngle, channelOffset);
    let br = grid2D(st, cell + 1.0, timeAngle, channelOffset);

    let upper = smoothlerp(f.x, tl, tr);
    let lower = smoothlerp(f.x, bl, br);
    let val = smoothlerp(f.y, upper, lower);

    return val;  // Returns -1..1
}

// 3D gradient noise - Perlin-style with quintic interpolation
// z-axis is periodic with period Z_PERIOD
fn noise3D(p: vec3<f32>) -> f32 {
    let i = floor(p);
    let f = fract(p);

    let u = vec3<f32>(quintic(f.x), quintic(f.y), quintic(f.z));

    // Wrap z indices for periodicity - gradients at z=0 and z=Z_PERIOD will match
    let iz0 = wrapZ(i.z);
    let iz1 = wrapZ(i.z + 1.0);

    // 8 corners of 3D cube with wrapped z
    let n000 = dot(grad3(vec3<f32>(i.xy, iz0) + vec3<f32>(0.0, 0.0, 0.0)), f - vec3<f32>(0.0, 0.0, 0.0));
    let n100 = dot(grad3(vec3<f32>(i.xy, iz0) + vec3<f32>(1.0, 0.0, 0.0)), f - vec3<f32>(1.0, 0.0, 0.0));
    let n010 = dot(grad3(vec3<f32>(i.xy, iz0) + vec3<f32>(0.0, 1.0, 0.0)), f - vec3<f32>(0.0, 1.0, 0.0));
    let n110 = dot(grad3(vec3<f32>(i.xy, iz0) + vec3<f32>(1.0, 1.0, 0.0)), f - vec3<f32>(1.0, 1.0, 0.0));
    let n001 = dot(grad3(vec3<f32>(i.xy, iz1) + vec3<f32>(0.0, 0.0, 0.0)), f - vec3<f32>(0.0, 0.0, 1.0));
    let n101 = dot(grad3(vec3<f32>(i.xy, iz1) + vec3<f32>(1.0, 0.0, 0.0)), f - vec3<f32>(1.0, 0.0, 1.0));
    let n011 = dot(grad3(vec3<f32>(i.xy, iz1) + vec3<f32>(0.0, 1.0, 0.0)), f - vec3<f32>(0.0, 1.0, 1.0));
    let n111 = dot(grad3(vec3<f32>(i.xy, iz1) + vec3<f32>(1.0, 1.0, 0.0)), f - vec3<f32>(1.0, 1.0, 1.0));

    let nx00 = mix(n000, n100, u.x);
    let nx10 = mix(n010, n110, u.x);
    let nx01 = mix(n001, n101, u.x);
    let nx11 = mix(n011, n111, u.x);

    let nxy0 = mix(nx00, nx10, u.y);
    let nxy1 = mix(nx01, nx11, u.y);

    return mix(nxy0, nxy1, u.z);
}

// FBM for 2D periodic noise
fn fbm2D(st: vec2<f32>, timeAngle: f32, channelOffset: f32, ridgedMode: i32) -> f32 {
    let MAX_OCT: i32 = 8;
    var amplitude: f32 = 0.5;
    var frequency: f32 = 1.0;
    var sum: f32 = 0.0;
    var maxVal: f32 = 0.0;
    var oct = params.octaves;
    if (oct < 1) { oct = 1; }

    for (var i: i32 = 0; i < MAX_OCT; i = i + 1) {
        if (i >= oct) { break; }
        var n = noise2D(st * frequency, timeAngle, channelOffset);  // -1..1
        n = clamp(n * 1.5, -1.0, 1.0);
        if (ridgedMode == 1) {
            n = 1.0 - abs(n);
        } else {
            n = (n + 1.0) * 0.5;
        }
        sum = sum + n * amplitude;
        maxVal = maxVal + amplitude;
        frequency = frequency * 2.0;
        amplitude = amplitude * 0.5;
    }
    return sum / maxVal;
}

// FBM using 3D noise with circular time for seamless looping
// 2D cross-section moves through 3D noise as time varies
fn fbm3D(st: vec2<f32>, timeAngle: f32, channelOffset: f32, ridgedMode: i32) -> f32 {
    let MAX_OCT: i32 = 8;
    var amplitude: f32 = 0.5;
    var frequency: f32 = 1.0;
    var sum: f32 = 0.0;
    var maxVal: f32 = 0.0;
    var oct = params.octaves;
    if (oct < 1) { oct = 1; }

    // Linear time traversal with periodic z-axis
    // time goes 0->1, map to 0->Z_PERIOD for one complete loop
    let z = timeAngle / TAU * Z_PERIOD + channelOffset;

    for (var i: i32 = 0; i < MAX_OCT; i = i + 1) {
        if (i >= oct) { break; }
        let p = vec3<f32>(st * frequency, z);
        var n = noise3D(p);  // -1..1
        // Scale up by ~1.5 to spread the gaussian-ish distribution
        // Perlin noise rarely hits +-1, so this expands the usable range
        n = clamp(n * 1.5, -1.0, 1.0);
        if (ridgedMode == 1) {
            n = 1.0 - abs(n);  // fold at zero, gives 0..1 with ridges at zero-crossings
        } else {
            n = (n + 1.0) * 0.5;  // normalize to 0..1
        }
        sum = sum + n * amplitude;
        maxVal = maxVal + amplitude;
        frequency = frequency * 2.0;
        amplitude = amplitude * 0.5;
    }
    return sum / maxVal;
}

// Single-octave warp noise helpers (cheap, no fbm)
fn warpNoise2D(p: vec2<f32>, timeAngle: f32) -> f32 {
    return noise2D(p, timeAngle, 0.0);
}

fn warpNoise3D(p: vec2<f32>, z: f32) -> f32 {
    return noise3D(vec3<f32>(p, z));
}

// Domain warp: iteratively displace coordinates using noise
fn domainWarp2D(st: vec2<f32>, timeAngle: f32, iterations: i32, wScale: f32, wIntensity: f32) -> vec2<f32> {
    let wFreq = max(0.1, 100.0 / max(wScale, 0.01));
    let disp = wIntensity * 0.02;
    var p = st;
    for (var i: i32 = 0; i < 4; i = i + 1) {
        if (i >= iterations) { break; }
        let fi = f32(i);
        let nx = warpNoise2D(p * wFreq + vec2<f32>(fi * 5.2 + 1.7, fi * 1.3 + 13.7), timeAngle);
        let ny = warpNoise2D(p * wFreq + vec2<f32>(fi * 2.8 + 7.3, fi * 4.1 + 3.9), timeAngle);
        p = p + vec2<f32>(nx, ny) * disp;
    }
    return p;
}

fn domainWarp3D(st: vec2<f32>, z: f32, iterations: i32, wScale: f32, wIntensity: f32) -> vec2<f32> {
    let wFreq = max(0.1, 100.0 / max(wScale, 0.01));
    let disp = wIntensity * 0.02;
    var p = st;
    for (var i: i32 = 0; i < 4; i = i + 1) {
        if (i >= iterations) { break; }
        let fi = f32(i);
        let nx = warpNoise3D(p * wFreq + vec2<f32>(fi * 5.2 + 1.7, fi * 1.3 + 13.7), z);
        let ny = warpNoise3D(p * wFreq + vec2<f32>(fi * 2.8 + 7.3, fi * 4.1 + 3.9), z);
        p = p + vec2<f32>(nx, ny) * disp;
    }
    return p;
}

@fragment
fn main(@builtin(position) position: vec4<f32>) -> @location(0) vec4<f32> {
    var res = params.resolution;
    if (res.x < 1.0) { res = vec2<f32>(1024.0, 1024.0); }
    var st = (position.xy + params.tileOffset) / params.fullResolution;
    // Center UVs so zoom scales from center, not corner
    st = st - 0.5;
    st.x = st.x * params.aspect;
    // Invert scale to match vnoise convention: higher scale = fewer cells (zoomed in)
    let freq = max(0.1, 100.0 / max(params.scale, 0.01));
    st = st * freq;
    // Offset to keep noise coords positive (avoids hash artifacts at boundaries)
    st = st + 1000.0;

    // time is 0-1 representing position around circle for seamless looping
    // speed multiplies the time to control animation speed
    let timeAngle = params.time * params.speed * TAU;

    // Apply domain warp if enabled
    if (params.warpIterations > 0) {
        if (DIMENSIONS == 2) {
            st = domainWarp2D(st, timeAngle, params.warpIterations, params.warpScale, params.warpIntensity);
        } else {
            let z = timeAngle / TAU * Z_PERIOD;
            st = domainWarp3D(st, z, params.warpIterations, params.warpScale, params.warpIntensity);
        }
    }

    var r: f32;
    var g: f32;
    var b: f32;

    if (DIMENSIONS == 2) {
        // 2D periodic noise (faster)
        r = fbm2D(st, timeAngle, 0.0, params.ridges);
        g = fbm2D(st, timeAngle, 0.333, params.ridges);
        b = fbm2D(st, timeAngle, 0.667, params.ridges);
    } else {
        // 3D cross-section noise (original)
        r = fbm3D(st, timeAngle, 0.0, params.ridges);
        g = fbm3D(st, timeAngle, 1.33, params.ridges);
        b = fbm3D(st, timeAngle, 2.67, params.ridges);
    }

    var col: vec3<f32>;
    if (params.colorMode == 0) {
        // Mono mode
        col = vec3<f32>(r);
    } else {
        // RGB mode
        col = vec3<f32>(r, g, b);
    }

    return vec4<f32>(col, 1.0);
}

// WGSL version – WebGPU
@group(0) @binding(0) var<uniform> resolution: vec2<f32>;
@group(0) @binding(1) var<uniform> aspect: f32;
@group(0) @binding(2) var<uniform> sides: i32;
@group(0) @binding(3) var<uniform> radius: f32;
@group(0) @binding(4) var<uniform> smoothing: f32;
@group(0) @binding(5) var<uniform> rotation: f32;
@group(0) @binding(6) var<uniform> fgColor: vec3<f32>;
@group(0) @binding(7) var<uniform> fgAlpha: f32;
@group(0) @binding(8) var<uniform> bgColor: vec3<f32>;
@group(0) @binding(9) var<uniform> bgAlpha: f32;
@group(0) @binding(10) var<uniform> tileOffset: vec2<f32>;
@group(0) @binding(11) var<uniform> fullResolution: vec2<f32>;

const PI: f32 = 3.14159265359;

/* Regular polygon distance field built from polar math; draws a soft-edged shape. */
fn polygon(st: vec2<f32>, sides: f32) -> f32 {
  let a = atan2(st.y, st.x) + 3.14159265;
  let r = 6.2831853 / sides;
  return cos(floor(0.5 + a / r) * r - a) * length(st);
}

@fragment
fn main(@builtin(position) position: vec4<f32>) -> @location(0) vec4<f32> {
  let globalCoord = position.xy + tileOffset;
  var st = globalCoord / fullResolution;
  st = (st - vec2<f32>(0.5, 0.5)) * 2.0;
  st.x *= aspect;
  // Apply rotation
  let c = cos(rotation * PI / 180.0);
  let s = sin(rotation * PI / 180.0);
  st = vec2<f32>(st.x * c - st.y * s, st.x * s + st.y * c);
  let sidesF = f32(max(sides, 3));
  // Rotate triangle so vertex points up
  if (sides == 3) {
      st = vec2<f32>(st.y, -st.x);
  }
  // Normalize by inradius so all shapes have consistent size
  let d = polygon(st, sidesF) / cos(PI / sidesF);
  let m = smoothstep(radius, radius - smoothing, d);

  // fgAlpha scales foreground visibility, bgAlpha scales background visibility
  let fgMask = m * fgAlpha;
  let bgMask = (1.0 - m) * bgAlpha;
  let totalAlpha = fgMask + bgMask;

  // Compute color as weighted blend (for non-zero alpha)
  var outColor: vec3<f32>;
  if (totalAlpha > 0.0) {
      outColor = (fgColor * fgMask + bgColor * bgMask) / totalAlpha;
  } else {
      outColor = vec3<f32>(0.0);
  }

  // Output premultiplied alpha for correct compositing
  return vec4<f32>(outColor * totalAlpha, totalAlpha);
}

/*
 * WGSL reaction-diffusion display shader (mono only).
 * Formats the simulation state into grayscale output.
 */

struct Uniforms {
    // data[0] = (resolution.x, resolution.y, time, unused)
    // data[1] = (inputIntensity, unused, unused, unused)
    // data[2] = (tileOffset.x, tileOffset.y, fullResolution.x, fullResolution.y)
    // data[3] = (unused, unused, unused, smoothing)
    data : array<vec4<f32>, 4>,
};
@group(0) @binding(0) var<uniform> uniforms : Uniforms;
@group(0) @binding(1) var samp : sampler;
@group(0) @binding(2) var fbTex : texture_2d<f32>;
@group(0) @binding(3) var inputTex : texture_2d<f32>;

const PI : f32 = 3.14159265359;

fn modulo(a: f32, b: f32) -> f32 {
    return a - b * floor(a / b);
}

fn quadratic3(p0: vec4<f32>, p1: vec4<f32>, p2: vec4<f32>, t: f32) -> vec4<f32> {
    let t2 = t * t;

    return p0 * 0.5 * (1.0 - t) * (1.0 - t) +
           p1 * 0.5 * (-2.0 * t2 + 2.0 * t + 1.0) +
           p2 * 0.5 * t2;
}

fn bicubic4(p0: vec4<f32>, p1: vec4<f32>, p2: vec4<f32>, p3: vec4<f32>, t: f32) -> vec4<f32> {
    let t2 = t * t;
    let t3 = t2 * t;

    let b0 = (1.0 - t) * (1.0 - t) * (1.0 - t) / 6.0;
    let b1 = (3.0 * t3 - 6.0 * t2 + 4.0) / 6.0;
    let b2 = (-3.0 * t3 + 3.0 * t2 + 3.0 * t + 1.0) / 6.0;
    let b3 = t3 / 6.0;

    return p0 * b0 + p1 * b1 + p2 * b2 + p3 * b3;
}

fn catmullRom3(p0: vec4<f32>, p1: vec4<f32>, p2: vec4<f32>, t: f32) -> vec4<f32> {
    let t2 = t * t;
    let t3 = t2 * t;

    let m = 0.5 * (p2 - p0);

    return (2.0*t3 - 3.0*t2 + 1.0) * p1 +
           (t3 - 2.0*t2 + t) * m +
           (-2.0*t3 + 3.0*t2) * p2 +
           (t3 - t2) * m;
}

fn catmullRom4(p0: vec4<f32>, p1: vec4<f32>, p2: vec4<f32>, p3: vec4<f32>, t: f32) -> vec4<f32> {
    return p1 + 0.5 * t * (p2 - p0 + t * (2.0 * p0 - 5.0 * p1 + 4.0 * p2 - p3 + t * (3.0 * (p1 - p2) + p3 - p0)));
}

fn quadratic(tex: texture_2d<f32>, uv: vec2<f32>, texelSize: vec2<f32>) -> vec4<f32> {
    let uv2 = uv + texelSize;
    let texCoord = uv2 / texelSize;
    let baseCoord = floor(texCoord - 0.5);
    let f = fract(texCoord - 0.5);

    // Sample 3x3 grid centered on the interpolation point
    let v00 = textureSampleLevel(tex, samp, (baseCoord + vec2<f32>(-0.5, -0.5)) * texelSize, 0.0);
    let v10 = textureSampleLevel(tex, samp, (baseCoord + vec2<f32>( 0.5, -0.5)) * texelSize, 0.0);
    let v20 = textureSampleLevel(tex, samp, (baseCoord + vec2<f32>( 1.5, -0.5)) * texelSize, 0.0);

    let v01 = textureSampleLevel(tex, samp, (baseCoord + vec2<f32>(-0.5,  0.5)) * texelSize, 0.0);
    let v11 = textureSampleLevel(tex, samp, (baseCoord + vec2<f32>( 0.5,  0.5)) * texelSize, 0.0);
    let v21 = textureSampleLevel(tex, samp, (baseCoord + vec2<f32>( 1.5,  0.5)) * texelSize, 0.0);

    let v02 = textureSampleLevel(tex, samp, (baseCoord + vec2<f32>(-0.5,  1.5)) * texelSize, 0.0);
    let v12 = textureSampleLevel(tex, samp, (baseCoord + vec2<f32>( 0.5,  1.5)) * texelSize, 0.0);
    let v22 = textureSampleLevel(tex, samp, (baseCoord + vec2<f32>( 1.5,  1.5)) * texelSize, 0.0);

    // Interpolate rows using quadratic B-spline
    let y0 = quadratic3(v00, v10, v20, f.x);
    let y1 = quadratic3(v01, v11, v21, f.x);
    let y2 = quadratic3(v02, v12, v22, f.x);

    // Interpolate columns
    return quadratic3(y0, y1, y2, f.y);
}

fn catmullRom3x3(tex: texture_2d<f32>, uv: vec2<f32>, texelSize: vec2<f32>) -> vec4<f32> {
    let uv2 = uv + texelSize;
    let texCoord = uv2 / texelSize;
    let baseCoord = floor(texCoord - 1.0);
    let f = fract(texCoord - 1.0);

    // Sample 3x3 grid
    let v00 = textureSampleLevel(tex, samp, (baseCoord + vec2<f32>(-0.5, -0.5)) * texelSize, 0.0);
    let v10 = textureSampleLevel(tex, samp, (baseCoord + vec2<f32>( 0.5, -0.5)) * texelSize, 0.0);
    let v20 = textureSampleLevel(tex, samp, (baseCoord + vec2<f32>( 1.5, -0.5)) * texelSize, 0.0);

    let v01 = textureSampleLevel(tex, samp, (baseCoord + vec2<f32>(-0.5,  0.5)) * texelSize, 0.0);
    let v11 = textureSampleLevel(tex, samp, (baseCoord + vec2<f32>( 0.5,  0.5)) * texelSize, 0.0);
    let v21 = textureSampleLevel(tex, samp, (baseCoord + vec2<f32>( 1.5,  0.5)) * texelSize, 0.0);

    let v02 = textureSampleLevel(tex, samp, (baseCoord + vec2<f32>(-0.5,  1.5)) * texelSize, 0.0);
    let v12 = textureSampleLevel(tex, samp, (baseCoord + vec2<f32>( 0.5,  1.5)) * texelSize, 0.0);
    let v22 = textureSampleLevel(tex, samp, (baseCoord + vec2<f32>( 1.5,  1.5)) * texelSize, 0.0);

    // Interpolate rows using Catmull-Rom
    let y0 = catmullRom3(v00, v10, v20, f.x);
    let y1 = catmullRom3(v01, v11, v21, f.x);
    let y2 = catmullRom3(v02, v12, v22, f.x);

    // Interpolate columns
    return catmullRom3(y0, y1, y2, f.y);
}

fn bicubic(tex: texture_2d<f32>, uv: vec2<f32>, texelSize: vec2<f32>) -> vec4<f32> {
    let uv2 = uv + texelSize;
    let texCoord = uv2 / texelSize;
    let baseCoord = floor(texCoord - 1.0);
    let f = fract(texCoord - 1.0);

    let row0 = bicubic4(
        textureSampleLevel(tex, samp, (baseCoord + vec2<f32>(-0.5, -0.5)) * texelSize, 0.0),
        textureSampleLevel(tex, samp, (baseCoord + vec2<f32>( 0.5, -0.5)) * texelSize, 0.0),
        textureSampleLevel(tex, samp, (baseCoord + vec2<f32>( 1.5, -0.5)) * texelSize, 0.0),
        textureSampleLevel(tex, samp, (baseCoord + vec2<f32>( 2.5, -0.5)) * texelSize, 0.0),
        f.x
    );

    let row1 = bicubic4(
        textureSampleLevel(tex, samp, (baseCoord + vec2<f32>(-0.5,  0.5)) * texelSize, 0.0),
        textureSampleLevel(tex, samp, (baseCoord + vec2<f32>( 0.5,  0.5)) * texelSize, 0.0),
        textureSampleLevel(tex, samp, (baseCoord + vec2<f32>( 1.5,  0.5)) * texelSize, 0.0),
        textureSampleLevel(tex, samp, (baseCoord + vec2<f32>( 2.5,  0.5)) * texelSize, 0.0),
        f.x
    );

    let row2 = bicubic4(
        textureSampleLevel(tex, samp, (baseCoord + vec2<f32>(-0.5,  1.5)) * texelSize, 0.0),
        textureSampleLevel(tex, samp, (baseCoord + vec2<f32>( 0.5,  1.5)) * texelSize, 0.0),
        textureSampleLevel(tex, samp, (baseCoord + vec2<f32>( 1.5,  1.5)) * texelSize, 0.0),
        textureSampleLevel(tex, samp, (baseCoord + vec2<f32>( 2.5,  1.5)) * texelSize, 0.0),
        f.x
    );

    let row3 = bicubic4(
        textureSampleLevel(tex, samp, (baseCoord + vec2<f32>(-0.5,  2.5)) * texelSize, 0.0),
        textureSampleLevel(tex, samp, (baseCoord + vec2<f32>( 0.5,  2.5)) * texelSize, 0.0),
        textureSampleLevel(tex, samp, (baseCoord + vec2<f32>( 1.5,  2.5)) * texelSize, 0.0),
        textureSampleLevel(tex, samp, (baseCoord + vec2<f32>( 2.5,  2.5)) * texelSize, 0.0),
        f.x
    );

    return bicubic4(row0, row1, row2, row3, f.y);
}

fn catmullRom4x4(tex: texture_2d<f32>, uv: vec2<f32>, texelSize: vec2<f32>) -> vec4<f32> {
    let uv2 = uv + texelSize;
    let texCoord = uv2 / texelSize;
    let baseCoord = floor(texCoord - 1.0);
    let f = fract(texCoord - 1.0);

    let row0 = catmullRom4(
        textureSampleLevel(tex, samp, (baseCoord + vec2<f32>(-0.5, -0.5)) * texelSize, 0.0),
        textureSampleLevel(tex, samp, (baseCoord + vec2<f32>( 0.5, -0.5)) * texelSize, 0.0),
        textureSampleLevel(tex, samp, (baseCoord + vec2<f32>( 1.5, -0.5)) * texelSize, 0.0),
        textureSampleLevel(tex, samp, (baseCoord + vec2<f32>( 2.5, -0.5)) * texelSize, 0.0),
        f.x
    );

    let row1 = catmullRom4(
        textureSampleLevel(tex, samp, (baseCoord + vec2<f32>(-0.5,  0.5)) * texelSize, 0.0),
        textureSampleLevel(tex, samp, (baseCoord + vec2<f32>( 0.5,  0.5)) * texelSize, 0.0),
        textureSampleLevel(tex, samp, (baseCoord + vec2<f32>( 1.5,  0.5)) * texelSize, 0.0),
        textureSampleLevel(tex, samp, (baseCoord + vec2<f32>( 2.5,  0.5)) * texelSize, 0.0),
        f.x
    );

    let row2 = catmullRom4(
        textureSampleLevel(tex, samp, (baseCoord + vec2<f32>(-0.5,  1.5)) * texelSize, 0.0),
        textureSampleLevel(tex, samp, (baseCoord + vec2<f32>( 0.5,  1.5)) * texelSize, 0.0),
        textureSampleLevel(tex, samp, (baseCoord + vec2<f32>( 1.5,  1.5)) * texelSize, 0.0),
        textureSampleLevel(tex, samp, (baseCoord + vec2<f32>( 2.5,  1.5)) * texelSize, 0.0),
        f.x
    );

    let row3 = catmullRom4(
        textureSampleLevel(tex, samp, (baseCoord + vec2<f32>(-0.5,  2.5)) * texelSize, 0.0),
        textureSampleLevel(tex, samp, (baseCoord + vec2<f32>( 0.5,  2.5)) * texelSize, 0.0),
        textureSampleLevel(tex, samp, (baseCoord + vec2<f32>( 1.5,  2.5)) * texelSize, 0.0),
        textureSampleLevel(tex, samp, (baseCoord + vec2<f32>( 2.5,  2.5)) * texelSize, 0.0),
        f.x
    );

    return catmullRom4(row0, row1, row2, row3, f.y);
}

fn cosineMix(a: f32, b: f32, t: f32) -> f32 {
    let amount = (1.0 - cos(t * 3.141592653589793)) * 0.5;
    return mix(a, b, amount);
}

@fragment
fn main(@builtin(position) pos : vec4<f32>) -> @location(0) vec4<f32> {
    let resolution = uniforms.data[0].xy;
    let smoothing = i32(uniforms.data[3].w);
    let inputIntensity = uniforms.data[1].x * 0.01;
    let tileOffset = uniforms.data[2].xy;
    let fullResolution = uniforms.data[2].zw;
    let globalCoord = pos.xy + tileOffset;

    var intensity = 1.0;

    if (smoothing == 0) {
        let texSizeI = vec2<i32>(textureDimensions(fbTex, 0));
        let texSizeF = vec2<f32>(f32(texSizeI.x), f32(texSizeI.y));
        let coord = vec2<i32>(floor(globalCoord * texSizeF / fullResolution));
        let clamped = clamp(coord, vec2<i32>(0), texSizeI - vec2<i32>(1));
        intensity = clamp(textureLoad(fbTex, clamped, 0).g, 0.0, 1.0);
    } else if (smoothing == 2) {
        // hermite (smoothstep)
        let texSize = vec2<f32>(textureDimensions(fbTex, 0));
        let texelPos = (globalCoord * texSize / fullResolution) - vec2<f32>(0.5);
        let base = floor(texelPos);
        let weights = fract(texelPos);
        let next = base + vec2<f32>(1.0);

        let texSizeI = vec2<i32>(textureDimensions(fbTex, 0));
        let minIdx = vec2<i32>(0);
        let maxIdx = texSizeI - vec2<i32>(1);

        let baseIdx = clamp(vec2<i32>(base), minIdx, maxIdx);
        let nextIdx = clamp(vec2<i32>(next), minIdx, maxIdx);

        let v00 = textureLoad(fbTex, baseIdx, 0).g;
        let v10 = textureLoad(fbTex, vec2<i32>(nextIdx.x, baseIdx.y), 0).g;
        let v01 = textureLoad(fbTex, vec2<i32>(baseIdx.x, nextIdx.y), 0).g;
        let v11 = textureLoad(fbTex, nextIdx, 0).g;

        let smoothWeights = smoothstep(vec2<f32>(0.0), vec2<f32>(1.0), weights);
        let v0 = mix(v00, v10, smoothWeights.x);
        let v1 = mix(v01, v11, smoothWeights.x);
        intensity = clamp(mix(v0, v1, smoothWeights.y), 0.0, 1.0);
    } else if (smoothing == 3) {
        // catmull-rom 3x3 (9 taps)
        let texSize = vec2<f32>(textureDimensions(fbTex, 0));
        let texelSize = 1.0 / texSize;
        let scaling = fullResolution / texSize;
        let uv = (globalCoord - scaling * 0.5) / fullResolution;
        let sample = catmullRom3x3(fbTex, uv, texelSize);
        intensity = clamp(sample.g, 0.0, 1.0);
    } else if (smoothing == 4) {
        // catmull-rom 4x4 (16 taps)
        let texSize = vec2<f32>(textureDimensions(fbTex, 0));
        let texelSize = 1.0 / texSize;
        let scaling = fullResolution / texSize;
        let uv = (globalCoord - scaling * 0.5) / fullResolution;
        let sample = catmullRom4x4(fbTex, uv, texelSize);
        intensity = clamp(sample.g, 0.0, 1.0);
    } else if (smoothing == 5) {
        // b-spline 3x3 (9 taps)
        let texSize = vec2<f32>(textureDimensions(fbTex, 0));
        let texelSize = 1.0 / texSize;
        let scaling = fullResolution / texSize;
        let uv = (globalCoord - scaling * 0.5) / fullResolution;
        let sample = quadratic(fbTex, uv, texelSize);
        intensity = clamp(sample.g, 0.0, 1.0);
    } else if (smoothing == 6) {
        // b-spline 4x4 (16 taps)
        let texSize = vec2<f32>(textureDimensions(fbTex, 0));
        let texelSize = 1.0 / texSize;
        let scaling = fullResolution / texSize;
        let uv = (globalCoord - scaling * 0.5) / fullResolution;
        let sample = bicubic(fbTex, uv, texelSize);
        intensity = clamp(sample.g, 0.0, 1.0);
    } else {
        let texSize = vec2<f32>(textureDimensions(fbTex, 0));
        let texelPos = (globalCoord * texSize / fullResolution) - vec2<f32>(0.5, 0.5);
        let base = floor(texelPos);
        let weights = fract(texelPos);
        let next = base + vec2<f32>(1.0, 1.0);

        let texSizeI = vec2<i32>(textureDimensions(fbTex, 0));
        let minIdx = vec2<i32>(0, 0);
        let maxIdx = texSizeI - vec2<i32>(1, 1);
        let baseI = clamp(vec2<i32>(base), minIdx, maxIdx);
        let nextI = clamp(vec2<i32>(next), minIdx, maxIdx);

        let v00 = textureLoad(fbTex, baseI, 0).g;
        let v10 = textureLoad(fbTex, vec2<i32>(nextI.x, baseI.y), 0).g;
        let v01 = textureLoad(fbTex, vec2<i32>(baseI.x, nextI.y), 0).g;
        let v11 = textureLoad(fbTex, nextI, 0).g;

        if (smoothing == 1) {
            let v0 = mix(v00, v10, weights.x);
            let v1 = mix(v01, v11, weights.x);
            intensity = clamp(mix(v0, v1, weights.y), 0.0, 1.0);
        } else {
            let v0 = cosineMix(v00, v10, weights.x);
            let v1 = cosineMix(v01, v11, weights.x);
            intensity = clamp(cosineMix(v0, v1, weights.y), 0.0, 1.0);
        }
    }

    var rdColor = vec3<f32>(intensity, intensity, intensity);

    // Blend with input texture
    if (inputIntensity > 0.0) {
        var inputUv = globalCoord / fullResolution;
        let inputColor = textureSampleLevel(inputTex, samp, inputUv, 0.0).rgb;
        rdColor = mix(rdColor, inputColor, inputIntensity);
    }

    return vec4<f32>(rdColor, 1.0);
}

/*
 * WGSL reaction-diffusion feedback shader.
 * Implements the Gray-Scott solver in WGSL to match the GLSL pass for deterministic evolution.
 * Feed and kill coefficients are clamped to stability thresholds before integration.
 */

struct Uniforms {
    // data[0] = (resolution.x, resolution.y, time, zoom)
    // data[1] = (feed, kill, rate1, rate2)
    // data[2] = (speed, weight, sourceF, sourceK)
    // data[3] = (sourceR1, sourceR2, resetState, seed)
    data : array<vec4<f32>, 4>,
};
@group(0) @binding(0) var<uniform> uniforms : Uniforms;
@group(0) @binding(1) var samp : sampler;
@group(0) @binding(2) var bufTex : texture_2d<f32>;
@group(0) @binding(3) var inputTex : texture_2d<f32>;

fn lp(tex: texture_2d<f32>, uv: vec2<f32>, size: vec2<f32>) -> vec3<f32> {
    // Fixed 1px neighbourhood sampling (matches GLSL behavior)
    let pixelStep = 1.0;

    var val = vec3<f32>(0.0);
    val = val + textureSampleLevel(tex, samp, (uv + vec2<f32>(-pixelStep, -pixelStep)) / size, 0.0).rgb * 0.05;
    val = val + textureSampleLevel(tex, samp, (uv + vec2<f32>(0.0, -pixelStep)) / size, 0.0).rgb * 0.2;
    val = val + textureSampleLevel(tex, samp, (uv + vec2<f32>(pixelStep, -pixelStep)) / size, 0.0).rgb * 0.05;
    val = val + textureSampleLevel(tex, samp, (uv + vec2<f32>(-pixelStep, 0.0)) / size, 0.0).rgb * 0.2;
    val = val + textureSampleLevel(tex, samp, (uv + vec2<f32>(0.0, 0.0)) / size, 0.0).rgb * -1.0;
    val = val + textureSampleLevel(tex, samp, (uv + vec2<f32>(pixelStep, 0.0)) / size, 0.0).rgb * 0.2;
    val = val + textureSampleLevel(tex, samp, (uv + vec2<f32>(-pixelStep, pixelStep)) / size, 0.0).rgb * 0.05;
    val = val + textureSampleLevel(tex, samp, (uv + vec2<f32>(0.0, pixelStep)) / size, 0.0).rgb * 0.2;
    val = val + textureSampleLevel(tex, samp, (uv + vec2<f32>(pixelStep, pixelStep)) / size, 0.0).rgb * 0.05;
    return val;
}

fn map(value: f32, inMin: f32, inMax: f32, outMin: f32, outMax: f32) -> f32 {
    return outMin + (outMax - outMin) * (value - inMin) / (inMax - inMin);
}

fn lum(color: vec3<f32>) -> f32 {
    return 0.2126 * color.r + 0.7152 * color.g + 0.0722 * color.b;
}

fn hash(p: vec2<f32>) -> f32 {
    var p2 = fract(p * vec2<f32>(0.1031, 0.1030));
    p2 = p2 + dot(p2, p2.yx + 33.33);
    return fract((p2.x + p2.y) * p2.x);
}

@fragment
fn main(@builtin(position) pos : vec4<f32>) -> @location(0) vec4<f32> {
    let resolution = uniforms.data[0].xy;
    let time = uniforms.data[0].z; // unused
    let zoom = uniforms.data[0].w;
    let seed = uniforms.data[3].w;

    let texSize = vec2<f32>(textureDimensions(bufTex, 0));
    let tex = textureSampleLevel(bufTex, samp, pos.xy / texSize, 0.0);
    var a = tex.r;
    var b = tex.g;

    // Check if buffer is empty (first frame initialization) or reset requested
    let bufferIsEmpty = (tex.r == 0.0 && tex.g == 0.0 && tex.b == 0.0 && tex.a == 0.0);
    let resetState = uniforms.data[3].z > 0.5;

    if (bufferIsEmpty || resetState) {
        // Initialize: A=1 everywhere, B=1 at sparse random locations
        a = 1.0;
        b = 0.0;
        if (hash(pos.xy + vec2<f32>(seed, seed)) > 0.99) {
            b = 1.0;
        }
        // Return initial state without running update step
        return vec4<f32>(a, b, 0.0, 1.0);
    }

    var color = lp(bufTex, pos.xy, texSize);

    var prevFrameCoord = pos.xy / texSize;

    let prevFrame = textureSampleLevel(inputTex, samp, prevFrameCoord, 0.0).rgb;

    let prevLum = lum(prevFrame);

    var f = uniforms.data[1].x * 0.001;
    var k = uniforms.data[1].y * 0.001;
    var r1 = uniforms.data[1].z * 0.01;
    var r2 = uniforms.data[1].w * 0.01;
    let s = uniforms.data[2].x * 0.01;
    let weight = uniforms.data[2].y * 0.01;
    let sourceF = i32(uniforms.data[2].z);
    let sourceK = i32(uniforms.data[2].w);
    let sourceR1 = i32(uniforms.data[3].x);
    let sourceR2 = i32(uniforms.data[3].y);

    if (sourceF > 0) {
        var val = prevLum;
        if (sourceF == 2) {
            val = 1.0 - prevLum;
        } else if (sourceF == 3) {
            val = prevFrame.r;
        } else if (sourceF == 4) {
            val = prevFrame.g;
        } else if (sourceF == 5) {
            val = prevFrame.b;
        } else if (sourceF == 6) {
            // sliderInput: blend slider value with brightness-modulated value
            val = map(prevLum, 0.0, 1.0, 0.01, 0.11);
            f = mix(f, val, weight);
        }
        if (sourceF != 6) {
            val = map(val, 0.0, 1.0, 0.01, 0.11);
            f = val;
        }
    }

    if (sourceK > 0) {
        var val = prevLum;
        if (sourceK == 2) {
            val = 1.0 - prevLum;
        } else if (sourceK == 3) {
            val = prevFrame.r;
        } else if (sourceK == 4) {
            val = prevFrame.g;
        } else if (sourceK == 5) {
            val = prevFrame.b;
        } else if (sourceK == 6) {
            // sliderInput: blend slider value with brightness-modulated value
            val = map(prevLum, 0.0, 1.0, 0.045, 0.07);
            k = mix(k, val, weight);
        }
        if (sourceK != 6) {
            val = map(val, 0.0, 1.0, 0.045, 0.07);
            k = val;
        }
    }

    if (sourceR1 > 0) {
        var val = prevLum;
        if (sourceR1 == 2) {
            val = 1.0 - prevLum;
        } else if (sourceR1 == 3) {
            val = prevFrame.r;
        } else if (sourceR1 == 4) {
            val = prevFrame.g;
        } else if (sourceR1 == 5) {
            val = prevFrame.b;
        } else if (sourceR1 == 6) {
            // sliderInput: blend slider value with brightness-modulated value
            val = map(prevLum, 0.0, 1.0, 0.5, 1.2);
            r1 = mix(r1, val, weight);
        }
        if (sourceR1 != 6) {
            val = map(val, 0.0, 1.0, 0.5, 1.2);
            r1 = val;
        }
    }

    if (sourceR2 > 0) {
        var val = prevLum;
        if (sourceR2 == 2) {
            val = 1.0 - prevLum;
        } else if (sourceR2 == 3) {
            val = prevFrame.r;
        } else if (sourceR2 == 4) {
            val = prevFrame.g;
        } else if (sourceR2 == 5) {
            val = prevFrame.b;
        } else if (sourceR2 == 6) {
            // sliderInput: blend slider value with brightness-modulated value
            val = map(prevLum, 0.0, 1.0, 0.2, 0.5);
            r2 = mix(r2, val, weight);
        }
        if (sourceR2 != 6) {
            val = map(val, 0.0, 1.0, 0.2, 0.5);
            r2 = val;
        }
    }

    let a2 = clamp(a + (r1 * color.r - a * b * b + f * (1.0 - a)) * s, 0.0, 1.0);
    let b2 = clamp(b + (r2 * color.g + a * b * b - (k + f) * b) * s, 0.0, 1.0);

    return vec4<f32>(a2, b2, 0.0, 1.0);
}

/**
 * Remap — WGSL fragment shader
 *
 * Polygon-zone router. Zones are composited TOP-DOWN: the last active zone
 * (highest index) that contains a pixel is on top. A zone's coverage is 1
 * everywhere inside its polygon and feathers OUTWARD over
 * `smoothEdge * 0.05 * min(fullResolution)` pixels, so the interior is
 * never eroded: adjacent zones meet without a seam and canvas borders
 * stay clean. Sources are premultiplied and stacked with the premultiplied
 * "under" operator, so a transparent source shows the zone below it, or
 * the background.
 *
 * Per zone, ONE pass over the packed vertex pairs (one uniform fetch per
 * two vertices) evaluates the even-odd inside test and the squared pixel
 * distance to the boundary together. With smoothEdge 0 the walk carries no
 * distance math at all, a host-supplied bounding box (zoneN_bounds) skips
 * zones the pixel cannot touch, and the zone loop stops as soon as the
 * pixel is opaque. Uniforms are packed into a single vec4 array to match
 * the JS uniformLayout.
 */

struct Uniforms {
    data: array<vec4<f32>, 275>,
    // slot 0:      bgR, bgG, bgB, bgAlpha
    // slot 1:      zoneCount, smoothEdge, _, time
    // slot 2..9:   per-zone meta (vertexCount, active, _, alpha)
    //              `active` is 1 when zoneN_tex is wired, 0 when "none".
    // slot 10..265: per-zone polygons; 32 vec4s per zone (64 verts packed two
    //              per vec4 as v_2k.xy + v_2k+1.xy)
    // slot 266.xy: resolution (auto-filled by the runtime)
    // slot 267..274: per-zone bounds [minX, minY, maxX, maxY], normalized;
    //              default [0, 0, 1, 1] never rejects a pixel
}

@group(0) @binding(0) var samp: sampler;
@group(0) @binding(1) var<uniform> uniforms: Uniforms;
@group(0) @binding(2) var zone0_tex: texture_2d<f32>;
@group(0) @binding(3) var zone1_tex: texture_2d<f32>;
@group(0) @binding(4) var zone2_tex: texture_2d<f32>;
@group(0) @binding(5) var zone3_tex: texture_2d<f32>;
@group(0) @binding(6) var zone4_tex: texture_2d<f32>;
@group(0) @binding(7) var zone5_tex: texture_2d<f32>;
@group(0) @binding(8) var zone6_tex: texture_2d<f32>;
@group(0) @binding(9) var zone7_tex: texture_2d<f32>;
// Auto-filled when noisedeck is doing a tiled large-resolution export.
// When not tiling: tileOffset = (0, 0), fullResolution = resolution.
@group(0) @binding(10) var<uniform> tileOffset: vec2<f32>;
@group(0) @binding(11) var<uniform> fullResolution: vec2<f32>;

const MAX_ZONES: i32 = 8;
const MAX_PAIRS: i32 = 32;  // MAX_VERTS_PER_ZONE / 2
const HEADER_SLOT: i32 = 0;
const CONTROLS_SLOT: i32 = 1;
const ZONE_META_SLOT: i32 = 2;
const ZONE_VERTS_SLOT: i32 = 10;
const RESOLUTION_SLOT: i32 = 266;
const ZONE_BOUNDS_SLOT: i32 = 267;

fn sampleZone(z: i32, uv: vec2<f32>) -> vec4<f32> {
    // textureSampleLevel (explicit LOD 0) — sampleZone is called from the
    // per-pixel, data-dependent zone loop (non-uniform control flow), which
    // disqualifies plain textureSample (it needs implicit derivatives /
    // uniform control flow). Zone surfaces are non-mipmapped render targets,
    // so LOD 0 is exactly GLSL's texture() here. Mirrors the mixer/shadow port.
    if (z == 0) { return textureSampleLevel(zone0_tex, samp, uv, 0.0); }
    if (z == 1) { return textureSampleLevel(zone1_tex, samp, uv, 0.0); }
    if (z == 2) { return textureSampleLevel(zone2_tex, samp, uv, 0.0); }
    if (z == 3) { return textureSampleLevel(zone3_tex, samp, uv, 0.0); }
    if (z == 4) { return textureSampleLevel(zone4_tex, samp, uv, 0.0); }
    if (z == 5) { return textureSampleLevel(zone5_tex, samp, uv, 0.0); }
    if (z == 6) { return textureSampleLevel(zone6_tex, samp, uv, 0.0); }
    return textureSampleLevel(zone7_tex, samp, uv, 0.0);
}

// Polygon state accumulated over one zone's edges for the current pixel.
struct ZoneTest {
    inside: bool,   // even-odd crossing parity
    d2: f32,        // squared pixel distance to the nearest boundary point
}

// Folds the edge between vertex `a` and its predecessor `b` into `t0`.
// All positions are global pixel coordinates (top-left origin).
fn testEdge(t0: ZoneTest, a: vec2<f32>, b: vec2<f32>, q: vec2<f32>, needDist: bool) -> ZoneTest {
    var t = t0;
    let e = b - a;
    let w = q - a;
    // Even-odd crossing count along the +x ray from q, branch-free. The
    // half-open scanline rule keeps an edge shared by two zones unambiguous.
    let c = vec3<bool>((q.y >= a.y), (q.y < b.y), (e.x * w.y > e.y * w.x));
    if (all(c) || !any(c)) { t.inside = !t.inside; }
    if (needDist) {
        let s = clamp(dot(w, e) / max(dot(e, e), 1e-6), 0.0, 1.0);
        let r = w - e * s;
        t.d2 = min(t.d2, dot(r, r));
    }
    return t;
}

// Walks one zone's packed vertex pairs (one uniform fetch per two vertices)
// and returns the inside parity plus the squared pixel distance to the
// boundary. `needDist` is a constant at each call site in fragmentMain(),
// so the smoothEdge-0 walk is compiled without any distance math.
fn walkZone(base: i32, n: i32, q: vec2<f32>, needDist: bool) -> ZoneTest {
    var t = ZoneTest(false, 1e30);
    let last: i32 = n - 1;
    let lastPack = uniforms.data[base + last / 2];
    var prev = select(lastPack.zw, lastPack.xy, last % 2 == 0) * fullResolution;
    let pairs: i32 = (n + 1) / 2;
    for (var pair: i32 = 0; pair < MAX_PAIRS; pair = pair + 1) {
        if (pair >= pairs) { break; }
        let pack = uniforms.data[base + pair];
        let v0 = pack.xy * fullResolution;
        t = testEdge(t, v0, prev, q, needDist);
        prev = v0;
        if (pair * 2 + 1 < n) {
            let v1 = pack.zw * fullResolution;
            t = testEdge(t, v1, prev, q, needDist);
            prev = v1;
        }
    }
    return t;
}

@fragment
fn fragmentMain(@builtin(position) fragCoord: vec4<f32>) -> @location(0) vec4<f32> {
    // Polygon tests use the GLOBAL pixel position so zones land in the same
    // image position regardless of which tile is rendering. The y flip below
    // is not a claim about the origin @builtin(position) uses — the WGSL spec
    // does not settle that here. It is the flip that makes this backend agree
    // with the GLSL one, which the orientation case in
    // shaders/tests/test_remap_render.mjs and byte parity with GLSL
    // (parity-attestation.json, maxDiff 0) both hold to.
    let globalPx = fragCoord.xy + tileOffset;
    let q = vec2<f32>(globalPx.x, fullResolution.y - globalPx.y);
    let p = q / fullResolution;   // normalized, for the zone bounds test
    // Texture sampling stays TILE-LOCAL: each zoneN_tex is the current
    // tile's slice of its source surface, so sample at the tile-local
    // pixel position, not the global one.
    let sampleUv = fragCoord.xy / uniforms.data[RESOLUTION_SLOT].xy;

    let header = uniforms.data[HEADER_SLOT];
    let controls = uniforms.data[CONTROLS_SLOT];
    let activeCount: i32 = min(i32(controls.x), MAX_ZONES);
    // Feather width in pixels, proportional to the shorter canvas side, so
    // it is the same width on both axes whatever the aspect ratio. smoothEdge
    // is clamped at 0: an automated negative value would otherwise make the
    // bounds dilation negative and SHRINK every zone's reject box.
    let featherPx: f32 = max(controls.y, 0.0) * 0.05 * min(fullResolution.x, fullResolution.y);
    let needDist: bool = featherPx > 0.0;
    let dilate = vec2<f32>(featherPx) / fullResolution;   // feather in normalized units per axis

    var result = vec4<f32>(0.0);
    for (var k: i32 = 0; k < MAX_ZONES; k = k + 1) {
        let z: i32 = activeCount - 1 - k;   // top-down: highest index first
        if (z < 0) { break; }
        let zoneMeta = uniforms.data[ZONE_META_SLOT + z];
        // Clamped: a host-supplied count above the per-zone capacity would
        // otherwise walk past this zone's slots into the next zone's.
        let n: i32 = min(i32(zoneMeta.x), MAX_PAIRS * 2);
        if (n < 3 || zoneMeta.y < 0.5) { continue; }   // degenerate, or source not wired
        // Host-supplied bounding box [minX, minY, maxX, maxY], dilated by the
        // feather. The default [0, 0, 1, 1] never rejects a canvas pixel.
        let bounds = uniforms.data[ZONE_BOUNDS_SLOT + z];
        if (any(p < bounds.xy - dilate) || any(p > bounds.zw + dilate)) { continue; }
        let base: i32 = ZONE_VERTS_SLOT + z * MAX_PAIRS;

        var t: ZoneTest;
        if (needDist) {
            t = walkZone(base, n, q, true);
        } else {
            t = walkZone(base, n, q, false);
        }

        var coverage: f32 = 1.0;
        if (!t.inside) {
            if (!needDist) { continue; }
            coverage = 1.0 - smoothstep(0.0, featherPx, sqrt(t.d2));
            if (coverage <= 0.0) { continue; }
        }
        // Premultiplied "under": this zone is above everything still to come.
        let src = sampleZone(z, sampleUv) * (coverage * zoneMeta.w);
        result = result + src * (1.0 - result.a);
        if (result.a >= 0.999) { break; }
    }
    // Background goes under whatever the zones left uncovered.
    result = result + vec4<f32>(header.xyz * header.w, header.w) * (1.0 - result.a);

    return result;
}

/*
 * Simple copy/blit shader - copies input to output unchanged.
 * Used for feedback texture updates.
 */

@group(0) @binding(0) var inputSampler: sampler;
@group(0) @binding(1) var inputTex: texture_2d<f32>;

@fragment
fn main(@builtin(position) pos: vec4<f32>) -> @location(0) vec4<f32> {
    let dims = vec2<f32>(textureDimensions(inputTex, 0));
    let uv = pos.xy / dims;
    return textureSample(inputTex, inputSampler, uv);
}

@group(0) @binding(0) var<uniform> resolution: vec2<f32>;
@group(0) @binding(1) var<uniform> deltaTime: f32;
@group(0) @binding(2) var<uniform> lineColor: vec3<f32>;
@group(0) @binding(3) var<uniform> gain: f32;
@group(0) @binding(4) var<uniform> speed: f32;
@group(0) @binding(5) var feedbackSampler: sampler;
@group(0) @binding(6) var feedbackTex: texture_2d<f32>;
@group(0) @binding(7) var noteGridSampler: sampler;
@group(0) @binding(8) var noteGridTex: texture_2d<f32>;

@fragment
fn main(@builtin(position) pos: vec4<f32>) -> @location(0) vec4<f32> {
    let uv = pos.xy / resolution;

    // Scroll feedback right (notes enter at left)
    let scrollAmount = speed * deltaTime * 0.5;
    let scrollUv = vec2<f32>(max(uv.x - scrollAmount, 0.0), uv.y);
    var prev = textureSample(feedbackTex, feedbackSampler, scrollUv) * 0.997;
    prev *= step(0.0, uv.x - scrollAmount);

    // 16 MIDI channels as horizontal swim lanes
    let laneF = uv.y * 16.0;
    let channel = i32(floor(laneF));
    let laneLocal = fract(laneF);

    // Each lane maps to MIDI keys 36-84 (C2-C6, 4 octaves)
    let keyLow = 36;
    let keyRange = 48;
    let keyExact = f32(keyLow) + laneLocal * f32(keyRange);
    let key = i32(floor(keyExact));

    // Sample note grid with fixed spread for visibility
    var maxVel = 0.0;
    for (var dk = -2; dk <= 2; dk++) {
        let k = clamp(key + dk, 0, 127);
        let gridUv = vec2<f32>((f32(k) + 0.5) / 128.0, (f32(channel) + 0.5) / 16.0);
        let noteData = textureSample(noteGridTex, noteGridSampler, gridUv);
        if (noteData.g > 0.5) {
            maxVel = max(maxVel, noteData.r);
        }
    }

    // Write new note data at the left edge
    let edgeWidth = 4.0 / resolution.x;
    var noteVal = 0.0;
    if (uv.x < edgeWidth && maxVel > 0.0) {
        noteVal = maxVel * gain;
    }

    // Lane separator lines
    var laneSep = 0.0;
    let laneEdge = fract(uv.y * 16.0);
    if (laneEdge < 0.02 || laneEdge > 0.98) {
        laneSep = 0.2;
    }

    let prevBright = max(prev.r, max(prev.g, prev.b));
    let brightness = max(prevBright, max(noteVal, laneSep));
    let col = lineColor * brightness;

    return vec4<f32>(col, 1.0);
}

// WGSL version – WebGPU
struct Uniforms {
    resolution: vec2<f32>,
    aspect: f32,
    time: f32,
    scale: f32,
    rotation: f32,
    thickness: f32,
    smoothness: f32,
    speed: f32,
    pulseDepth: f32,
    geometry: i32,
    rings: i32,
    starPoints: i32,
    animation: i32,
    fgColor: vec3<f32>,
    bgColor: vec3<f32>,
    tileOffset: vec2<f32>,
    fullResolution: vec2<f32>,
    renderScale: f32,
}
@group(0) @binding(0) var<uniform> u: Uniforms;

const PI: f32 = 3.14159265359;
const TAU: f32 = 6.28318530718;
const SQRT3: f32 = 1.7320508075688772;

const ANIM_ROTATE: i32 = 1;
const ANIM_PULSE: i32 = 2;
const ANIM_RIPPLE: i32 = 4;
const ANIM_UNFOLD: i32 = 5;

const GEOM_FLOWER: i32 = 0;
const GEOM_FRUIT: i32 = 1;
const GEOM_METATRON: i32 = 3;
const GEOM_SEED: i32 = 4;
const GEOM_VESICA: i32 = 5;
const GEOM_BORROMEAN: i32 = 6;
const GEOM_STARPOLYGON: i32 = 7;
const GEOM_TRIQUETRA: i32 = 8;

fn rotate2D(p: vec2<f32>, angle: f32) -> vec2<f32> {
    let c = cos(angle);
    let s = sin(angle);
    return vec2<f32>(p.x * c - p.y * s, p.x * s + p.y * c);
}

fn lineSegmentSDF(p: vec2<f32>, a: vec2<f32>, b: vec2<f32>) -> f32 {
    let pa = p - a;
    let ba = b - a;
    let h = clamp(dot(pa, ba) / dot(ba, ba), 0.0, 1.0);
    return length(pa - ba * h);
}

fn outlineEdge(d: f32, w: f32) -> f32 {
    return smoothstep(w + u.smoothness, w - u.smoothness, abs(d));
}

fn ripplePulse(phase: f32) -> f32 {
    return 1.0 + u.pulseDepth * sin(u.time * TAU * floor(u.speed) - phase);
}

fn unfoldVis(t_e: f32) -> f32 {
    return max(0.0, sin((u.time - t_e * 0.5) * TAU * floor(u.speed)));
}

fn flowerMask(p_in: vec2<f32>, ringsN: i32, figureScale: f32) -> f32 {
    let lineWidth = 0.04 + u.thickness * 0.12;
    let circleRadius = 1.0;
    let p = p_in * figureScale;

    var m: f32 = 0.0;
    for (var q: i32 = -6; q <= 6; q = q + 1) {
        if (q < -ringsN || q > ringsN) { continue; }
        for (var r: i32 = -6; r <= 6; r = r + 1) {
            if (r < -ringsN || r > ringsN) { continue; }
            if (q + r < -ringsN || q + r > ringsN) { continue; }

            let center = vec2<f32>(f32(q) + f32(r) * 0.5, f32(r) * SQRT3 * 0.5);
            let hexDist = max(max(abs(f32(q)), abs(f32(r))), abs(f32(q + r)));

            var circleR = circleRadius;
            if (u.animation == ANIM_RIPPLE) {
                circleR = circleR * ripplePulse(hexDist * 1.4);
            }
            let d = length(p - center) - circleR;

            var vis: f32 = 1.0;
            if (u.animation == ANIM_UNFOLD) {
                let t_e = hexDist / max(f32(ringsN), 1.0);
                vis = unfoldVis(t_e);
            }

            m = max(m, outlineEdge(d, lineWidth) * vis);
        }
    }
    return m;
}

fn fruitMask(p_in: vec2<f32>, drawLines: bool) -> f32 {
    let lineWidth = 0.04 + u.thickness * 0.12;
    let p = p_in * 0.5;

    var centers: array<vec2<f32>, 13>;
    centers[0] = vec2<f32>(0.0, 0.0);
    for (var k: i32 = 0; k < 6; k = k + 1) {
        let angle = f32(k) * PI / 3.0;
        centers[1 + k] = 2.0 * vec2<f32>(cos(angle), sin(angle));
    }
    for (var k: i32 = 0; k < 6; k = k + 1) {
        let angle = f32(k) * PI / 3.0 + PI / 6.0;
        centers[7 + k] = 2.0 * SQRT3 * vec2<f32>(cos(angle), sin(angle));
    }

    let maxCircleDist = 2.0 * SQRT3;
    var circleUnfoldRange: f32 = 1.0;
    if (drawLines) {
        circleUnfoldRange = 0.6;
    }

    var m: f32 = 0.0;

    for (var i: i32 = 0; i < 13; i = i + 1) {
        let distFromOrigin = length(centers[i]);

        var circleR: f32 = 1.0;
        if (u.animation == ANIM_RIPPLE) {
            circleR = circleR * ripplePulse(distFromOrigin * 0.8);
        }
        let d = length(p - centers[i]) - circleR;

        var vis: f32 = 1.0;
        if (u.animation == ANIM_UNFOLD) {
            let t_e = distFromOrigin / maxCircleDist * circleUnfoldRange;
            vis = unfoldVis(t_e);
        }

        m = max(m, outlineEdge(d, lineWidth) * vis);
    }

    if (drawLines) {
        var lineVis: f32 = 1.0;
        if (u.animation == ANIM_UNFOLD) {
            lineVis = unfoldVis(0.65);
        }
        for (var i: i32 = 0; i < 13; i = i + 1) {
            for (var j: i32 = 0; j < 13; j = j + 1) {
                if (j <= i) { continue; }
                let dL = lineSegmentSDF(p, centers[i], centers[j]);
                m = max(m, outlineEdge(dL, lineWidth * 0.5) * lineVis);
            }
        }
    }

    return m;
}

fn vesicaMask(p_in: vec2<f32>) -> f32 {
    let lineWidth = 0.04 + u.thickness * 0.12;
    let p = p_in * 0.25;
    let r = 1.5;
    let sep = r * 0.5;

    var rA: f32 = r;
    var rB: f32 = r;
    if (u.animation == ANIM_RIPPLE) {
        rA = rA * ripplePulse(0.0);
        rB = rB * ripplePulse(PI);
    }

    var visA: f32 = 1.0;
    var visB: f32 = 1.0;
    if (u.animation == ANIM_UNFOLD) {
        visA = unfoldVis(0.0);
        visB = unfoldVis(0.5);
    }

    let dA = length(p - vec2<f32>(-sep, 0.0)) - rA;
    let dB = length(p - vec2<f32>( sep, 0.0)) - rB;

    var m: f32 = 0.0;
    m = max(m, outlineEdge(dA, lineWidth) * visA);
    m = max(m, outlineEdge(dB, lineWidth) * visB);
    return m;
}

fn triquetraMask(p_in: vec2<f32>) -> f32 {
    let lineWidth = 0.04 + u.thickness * 0.12;
    let p = p_in * 0.30;
    let r = 2.25;
    let dist = r / SQRT3;

    let C0 = dist * vec2<f32>(cos(PI * 0.5),                       sin(PI * 0.5));
    let C1 = dist * vec2<f32>(cos(PI * 0.5 + TAU / 3.0),           sin(PI * 0.5 + TAU / 3.0));
    let C2 = dist * vec2<f32>(cos(PI * 0.5 + 2.0 * TAU / 3.0),     sin(PI * 0.5 + 2.0 * TAU / 3.0));

    var r0: f32 = r;
    var r1: f32 = r;
    var r2: f32 = r;
    if (u.animation == ANIM_RIPPLE) {
        r0 = r0 * ripplePulse(0.0);
        r1 = r1 * ripplePulse(TAU / 3.0);
        r2 = r2 * ripplePulse(2.0 * TAU / 3.0);
    }

    let d0 = length(p - C0) - r0;
    let d1 = length(p - C1) - r1;
    let d2 = length(p - C2) - r2;

    var v01: f32 = 1.0;
    var v02: f32 = 1.0;
    var v12: f32 = 1.0;
    if (u.animation == ANIM_UNFOLD) {
        v01 = unfoldVis(0.0);
        v02 = unfoldVis(0.33);
        v12 = unfoldVis(0.66);
    }

    var m: f32 = 0.0;
    m = max(m, outlineEdge(max(d0, d1), lineWidth) * v01);
    m = max(m, outlineEdge(max(d0, d2), lineWidth) * v02);
    m = max(m, outlineEdge(max(d1, d2), lineWidth) * v12);
    return m;
}

fn borromeanMask(p_in: vec2<f32>) -> f32 {
    let lineWidth = 0.04 + u.thickness * 0.12;
    let p = p_in * 0.32;
    let r = 1.5;
    let dist = 1.4;

    var m: f32 = 0.0;
    for (var i: i32 = 0; i < 3; i = i + 1) {
        let angle = f32(i) * TAU / 3.0 + PI * 0.5;
        let c = dist * vec2<f32>(cos(angle), sin(angle));

        var circleR = r;
        if (u.animation == ANIM_RIPPLE) {
            circleR = circleR * ripplePulse(f32(i) * TAU / 3.0);
        }
        let d = length(p - c) - circleR;

        var vis: f32 = 1.0;
        if (u.animation == ANIM_UNFOLD) {
            vis = unfoldVis(f32(i) / 3.0);
        }

        m = max(m, outlineEdge(d, lineWidth) * vis);
    }
    return m;
}

fn starPolygonMask(p_in: vec2<f32>, n: i32) -> f32 {
    let lineWidth = 0.04 + u.thickness * 0.12;
    let p = p_in * 0.32;
    var radius = 2.8;

    if (u.animation == ANIM_RIPPLE) {
        radius = radius * ripplePulse(0.0);
    }

    var m: f32 = 0.0;
    for (var i: i32 = 0; i < 12; i = i + 1) {
        if (i >= n) { break; }
        let j = (i + 2) - ((i + 2) / n) * n;
        let angle1 = f32(i) * TAU / f32(n) + PI * 0.5;
        let angle2 = f32(j) * TAU / f32(n) + PI * 0.5;
        let a = radius * vec2<f32>(cos(angle1), sin(angle1));
        let b = radius * vec2<f32>(cos(angle2), sin(angle2));
        let dL = lineSegmentSDF(p, a, b);

        var vis: f32 = 1.0;
        if (u.animation == ANIM_UNFOLD) {
            vis = unfoldVis(f32(i) / f32(n));
        }

        m = max(m, outlineEdge(dL, lineWidth) * vis);
    }
    return m;
}

@fragment
fn main(@builtin(position) position: vec4<f32>) -> @location(0) vec4<f32> {
    var st = (position.xy + u.tileOffset) / u.fullResolution;
    st = (st - vec2<f32>(0.5, 0.5)) * 2.0;
    st.x = st.x * u.aspect;

    let rad = u.rotation * PI / 180.0;
    st = rotate2D(st, rad);

    if (u.animation == ANIM_ROTATE) {
        st = rotate2D(st, u.time * TAU * floor(u.speed));
    }

    var scaleFactor = 21.0 - u.scale;
    if (u.animation == ANIM_PULSE) {
        scaleFactor = scaleFactor * (1.0 + u.pulseDepth * sin(u.time * TAU * floor(u.speed)));
    }

    let p = st * scaleFactor;

    var m: f32 = 0.0;
    if (u.geometry == GEOM_FLOWER) {
        m = flowerMask(p, u.rings, 0.45);
    } else if (u.geometry == GEOM_SEED) {
        m = flowerMask(p, 1, 0.23);
    } else if (u.geometry == GEOM_FRUIT) {
        m = fruitMask(p, false);
    } else if (u.geometry == GEOM_METATRON) {
        m = fruitMask(p, true);
    } else if (u.geometry == GEOM_VESICA) {
        m = vesicaMask(p);
    } else if (u.geometry == GEOM_BORROMEAN) {
        m = borromeanMask(p);
    } else if (u.geometry == GEOM_TRIQUETRA) {
        m = triquetraMask(p);
    } else if (u.geometry == GEOM_STARPOLYGON) {
        m = starPolygonMask(p, u.starPoints);
    }

    m = clamp(m, 0.0, 1.0);
    let color = mix(u.bgColor, u.fgColor, m);
    return vec4<f32>(color, 1.0);
}

// WGSL version – WebGPU
@group(0) @binding(0) var<uniform> resolution: vec2<f32>;
@group(0) @binding(1) var<uniform> audioWaveform: array<vec4<f32>, 32>;
@group(0) @binding(2) var<uniform> lineColor: vec3<f32>;
@group(0) @binding(3) var<uniform> lineThickness: f32;
@group(0) @binding(4) var<uniform> gain: f32;
@group(0) @binding(5) var<uniform> tileOffset: vec2<f32>;
@group(0) @binding(6) var<uniform> fullResolution: vec2<f32>;

fn sampleWaveform(index: u32) -> f32 {
    return audioWaveform[index / 4u][index % 4u];
}

@fragment
fn main(@builtin(position) position: vec4<f32>) -> @location(0) vec4<f32> {
    let globalCoord = position.xy + tileOffset;
    let uv = globalCoord / fullResolution;

    // Sample the waveform at this x position
    // Map uv.x [0,1] to array index [0,127]
    let fIndex = uv.x * 127.0;
    let i0 = u32(floor(fIndex));
    let i1 = min(i0 + 1u, 127u);
    let fract_i = fract(fIndex);

    // Linearly interpolate between adjacent samples
    let s0 = sampleWaveform(i0);
    let s1 = sampleWaveform(i1);
    let wval = mix(s0, s1, fract_i);

    // Apply gain around center (0.5 = silence)
    let gained = 0.5 + (wval - 0.5) * gain;

    // Distance from fragment to waveform line, in pixels
    let dist = abs(uv.y - gained) * fullResolution.y;

    // Anti-aliased line
    let line = smoothstep(lineThickness + 1.0, lineThickness, dist);

    // Premultiplied alpha output
    return vec4<f32>(lineColor * line, line);
}

/*
 * WGSL shape generator shader (mono-only variant).
 * Removed: palette colorization, hsv/oklab conversion
 * Output: grayscale intensity based on offset pattern
 */

struct Uniforms {
    data : array<vec4<f32>, 4>,
};

@group(0) @binding(0) var<uniform> uniforms : Uniforms;

var<private> resolution : vec2<f32>;
// LOOP_A_OFFSET and LOOP_B_OFFSET are compile-time consts injected by the
// runtime via injectDefines(). See synth/shape/definition.js
// `globals.LOOP_A_OFFSET.define` / `globals.LOOP_B_OFFSET.define`.

var<private> time : f32;
var<private> seed : f32;
var<private> wrap : bool;
var<private> loopAScale : f32;
var<private> loopBScale : f32;
var<private> speedA : f32;
var<private> speedB : f32;
var<private> aspectRatio : f32;
var<private> tileOffset : vec2<f32>;
var<private> fullResolution : vec2<f32>;
var<private> globalCoord : vec2<f32>;

const PI : f32 = 3.14159265359;
const TAU : f32 = 6.28318530718;

fn modulo(a: f32, b: f32) -> f32 {
    return a - b * floor(a / b);
}

fn map(value: f32, inMin: f32, inMax: f32, outMin: f32, outMax: f32) -> f32 {
    return outMin + (outMax - outMin) * (value - inMin) / (inMax - inMin);
}

fn pcg(v_in: vec3<u32>) -> vec3<u32> {
    var v = v_in * 1664525u + 1013904223u;
    v.x = v.x + v.y * v.z;
    v.y = v.y + v.z * v.x;
    v.z = v.z + v.x * v.y;
    v = v ^ (v >> vec3<u32>(16u));
    v.x = v.x + v.y * v.z;
    v.y = v.y + v.z * v.x;
    v.z = v.z + v.x * v.y;
    return v;
}

fn prng(p0: vec3<f32>) -> vec3<f32> {
    var p = p0;
    if (p.x >= 0.0) { p.x = p.x * 2.0; } else { p.x = -p.x * 2.0 + 1.0; }
    if (p.y >= 0.0) { p.y = p.y * 2.0; } else { p.y = -p.y * 2.0 + 1.0; }
    if (p.z >= 0.0) { p.z = p.z * 2.0; } else { p.z = -p.z * 2.0 + 1.0; }
    let u = pcg(vec3<u32>(p));
    return vec3<f32>(u) / f32(0xffffffffu);
}

fn periodicFunction(p: f32) -> f32 {
    let x = TAU * p;
    return map(sin(x), -1.0, 1.0, 0.0, 1.0);
}

// Positive modulo for lattice wrapping
fn positiveModulo(a: i32, b: i32) -> i32 {
    var result = a - (a / b) * b;
    if (result < 0) { result = result + b; }
    return result;
}

// The GLSL lattice hash: pcg over the integer lattice cell (offset by xyOffset),
// the seed and fixed jitter words, wrapped on an integer period.
fn randomFromLatticeWithOffset(st: vec2<f32>, freq: f32, xyOffset: vec2<i32>) -> vec3<f32> {
    let scaled = st * freq;
    let base = vec2<i32>(floor(scaled)) + xyOffset;
    let frac = fract(scaled);

    let seedInt = i32(seed);
    let seedFrac = 0.0;

    let xCombined = frac.x + seedFrac;
    var xi = base.x + seedInt + i32(floor(xCombined));
    var yi = base.y;

    if (wrap) {
        let freqInt = i32(freq + 0.5);
        if (freqInt > 0) {
            xi = positiveModulo(xi, freqInt);
            yi = positiveModulo(yi, freqInt);
        }
    }

    let xBits = bitcast<u32>(xi);
    let yBits = bitcast<u32>(yi);
    let seedBits = bitcast<u32>(seedInt);
    let fracBits = 0u;

    let jitter = vec3<u32>(
        (fracBits * 374761393u) ^ 0x9E3779B9u,
        (fracBits * 668265263u) ^ 0x7F4A7C15u,
        (fracBits * 2246822519u) ^ 0x94D049B4u
    );

    let state = vec3<u32>(xBits, yBits, seedBits) ^ jitter;
    let prngState = pcg(state);
    let denom = f32(0xffffffffu);
    return vec3<f32>(
        f32(prngState.x) / denom,
        f32(prngState.y) / denom,
        f32(prngState.z) / denom
    );
}

fn constant(st: vec2<f32>, freq: f32, speed: f32) -> f32 {
    let randTime = randomFromLatticeWithOffset(st, freq, vec2<i32>(40, 0));
    let scaledTime = periodicFunction(randTime.x - time) * map(abs(speed), 0.0, 100.0, 0.0, 0.33);

    let rand = randomFromLatticeWithOffset(st, freq, vec2<i32>(0, 0));
    return periodicFunction(rand.y - scaledTime);
}

// ---- 3×3 quadratic interpolation ----
fn quadratic3(p0: f32, p1: f32, p2: f32, t: f32) -> f32 {
    let t2 = t * t;
    return p0 * 0.5 * (1.0 - t) * (1.0 - t) +
           p1 * 0.5 * (-2.0 * t2 + 2.0 * t + 1.0) +
           p2 * 0.5 * t2;
}

fn catmullRom3(p0: f32, p1: f32, p2: f32, t: f32) -> f32 {
    let t2 = t * t;
    let t3 = t2 * t;
    return p1 + 0.5 * t * (p2 - p0) + 
           0.5 * t2 * (2.0*p0 - 5.0*p1 + 4.0*p2 - p0) +
           0.5 * t3 * (-p0 + 3.0*p1 - 3.0*p2 + p0);
}

fn quadratic3x3Value(st: vec2<f32>, freq: f32, speed: f32) -> f32 {
    let lattice = st * freq;
    let f = fract(lattice);
    let nd = 1.0 / freq;

    let v00 = constant(st + vec2<f32>(-nd, -nd), freq, speed);
    let v10 = constant(st + vec2<f32>(0.0, -nd), freq, speed);
    let v20 = constant(st + vec2<f32>(nd, -nd), freq, speed);

    let v01 = constant(st + vec2<f32>(-nd, 0.0), freq, speed);
    let v11 = constant(st, freq, speed);
    let v21 = constant(st + vec2<f32>(nd, 0.0), freq, speed);

    let v02 = constant(st + vec2<f32>(-nd, nd), freq, speed);
    let v12 = constant(st + vec2<f32>(0.0, nd), freq, speed);
    let v22 = constant(st + vec2<f32>(nd, nd), freq, speed);

    let y0 = quadratic3(v00, v10, v20, f.x);
    let y1 = quadratic3(v01, v11, v21, f.x);
    let y2 = quadratic3(v02, v12, v22, f.x);

    return quadratic3(y0, y1, y2, f.y);
}

fn catmullRom3x3Value(st: vec2<f32>, freq: f32, speed: f32) -> f32 {
    let lattice = st * freq;
    let f = fract(lattice);
    let nd = 1.0 / freq;

    let v00 = constant(st + vec2<f32>(-nd, -nd), freq, speed);
    let v10 = constant(st + vec2<f32>(0.0, -nd), freq, speed);
    let v20 = constant(st + vec2<f32>(nd, -nd), freq, speed);

    let v01 = constant(st + vec2<f32>(-nd, 0.0), freq, speed);
    let v11 = constant(st, freq, speed);
    let v21 = constant(st + vec2<f32>(nd, 0.0), freq, speed);

    let v02 = constant(st + vec2<f32>(-nd, nd), freq, speed);
    let v12 = constant(st + vec2<f32>(0.0, nd), freq, speed);
    let v22 = constant(st + vec2<f32>(nd, nd), freq, speed);

    let y0 = catmullRom3(v00, v10, v20, f.x);
    let y1 = catmullRom3(v01, v11, v21, f.x);
    let y2 = catmullRom3(v02, v12, v22, f.x);

    return catmullRom3(y0, y1, y2, f.y);
}

// ---- 4×4 interpolation ----
fn blendBicubic(p0: f32, p1: f32, p2: f32, p3: f32, t: f32) -> f32 {
    let t2 = t * t;
    let t3 = t2 * t;

    let b0 = (1.0 - t) * (1.0 - t) * (1.0 - t) / 6.0;
    let b1 = (3.0 * t3 - 6.0 * t2 + 4.0) / 6.0;
    let b2 = (-3.0 * t3 + 3.0 * t2 + 3.0 * t + 1.0) / 6.0;
    let b3 = t3 / 6.0;

    return p0 * b0 + p1 * b1 + p2 * b2 + p3 * b3;
}

fn catmullRom4(p0: f32, p1: f32, p2: f32, p3: f32, t: f32) -> f32 {
    return p1 + 0.5 * t * (p2 - p0 + t * (2.0 * p0 - 5.0 * p1 + 4.0 * p2 - p3 + 
           t * (3.0 * (p1 - p2) + p3 - p0)));
}

fn blendLinearOrCosine(a: f32, b: f32, amount: f32, interp: i32) -> f32 {
    if (interp == 1) {
        return mix(a, b, amount);
    }
    return mix(a, b, smoothstep(0.0, 1.0, amount));
}

// Simplex 2D noise helpers
fn mod289_v3(x: vec3<f32>) -> vec3<f32> {
    return x - floor(x * (1.0 / 289.0)) * 289.0;
}

fn mod289_v2(x: vec2<f32>) -> vec2<f32> {
    return x - floor(x * (1.0 / 289.0)) * 289.0;
}

fn permute(x: vec3<f32>) -> vec3<f32> {
    return mod289_v3(((x * 34.0) + 1.0) * x);
}

fn simplexValue(st: vec2<f32>, freq: f32, s: f32, blend: f32) -> f32 {
    let C = vec4<f32>(0.211324865405187,
                      0.366025403784439,
                     -0.577350269189626,
                      0.024390243902439);

    var uv = st * freq;
    uv.x = uv.x + s;

    let i = floor(uv + dot(uv, C.yy));
    let x0 = uv - i + dot(i, C.xx);

    var i1: vec2<f32>;
    if (x0.x > x0.y) {
        i1 = vec2<f32>(1.0, 0.0);
    } else {
        i1 = vec2<f32>(0.0, 1.0);
    }
    var x12 = x0.xyxy + C.xxzz;
    x12 = vec4<f32>(x12.xy - i1, x12.zw);

    let i_mod = mod289_v2(i);
    let p = permute(permute(i_mod.y + vec3<f32>(0.0, i1.y, 1.0))
          + i_mod.x + vec3<f32>(0.0, i1.x, 1.0));

    var m = max(0.5 - vec3<f32>(dot(x0, x0), dot(x12.xy, x12.xy), dot(x12.zw, x12.zw)), vec3<f32>(0.0));
    m = m * m;
    m = m * m;

    let x = 2.0 * fract(p * C.www) - 1.0;
    let h = abs(x) - 0.5;
    let ox = floor(x + 0.5);
    let a0 = x - ox;

    m = m * (1.79284291400159 - 0.85373472095314 * (a0 * a0 + h * h));

    var g: vec3<f32>;
    g.x = a0.x * x0.x + h.x * x0.y;
    g.y = a0.y * x12.x + h.y * x12.y;
    g.z = a0.z * x12.z + h.z * x12.w;

    let v = 130.0 * dot(m, g);

    return periodicFunction(map(v, -1.0, 1.0, 0.0, 1.0) - blend);
}

fn sineNoise(st_in: vec2<f32>, freq: f32, s: f32, blend: f32) -> f32 {
    var st = st_in * freq;
    st.x = st.x + s;

    let a = blend;
    let b = blend;
    let c = 1.0 - blend;

    let r1 = prng(vec3<f32>(s)) * 0.75 + 0.125;
    let r2 = prng(vec3<f32>(s + 10.0)) * 0.75 + 0.125;
    let x = sin(r1.x * st.y + sin(r1.y * st.x + a) + sin(r1.z * st.x + b) + c);
    let y = sin(r2.x * st.x + sin(r2.y * st.y + b) + sin(r2.z * st.y + c) + a);

    return (x + y) * 0.5 + 0.5;
}

fn bicubicValue(st: vec2<f32>, freq: f32, speed: f32) -> f32 {
    let ndX = 1.0 / freq;
    let ndY = 1.0 / freq;

    let u0 = st.x - ndX;
    let u1 = st.x;
    let u2 = st.x + ndX;
    let u3 = st.x + ndX + ndX;

    let v0 = st.y - ndY;
    let v1 = st.y;
    let v2 = st.y + ndY;
    let v3 = st.y + ndY + ndY;

    let x0y0 = constant(vec2<f32>(u0, v0), freq, speed);
    let x0y1 = constant(vec2<f32>(u0, v1), freq, speed);
    let x0y2 = constant(vec2<f32>(u0, v2), freq, speed);
    let x0y3 = constant(vec2<f32>(u0, v3), freq, speed);

    let x1y0 = constant(vec2<f32>(u1, v0), freq, speed);
    let x1y1 = constant(st, freq, speed);
    let x1y2 = constant(vec2<f32>(u1, v2), freq, speed);
    let x1y3 = constant(vec2<f32>(u1, v3), freq, speed);

    let x2y0 = constant(vec2<f32>(u2, v0), freq, speed);
    let x2y1 = constant(vec2<f32>(u2, v1), freq, speed);
    let x2y2 = constant(vec2<f32>(u2, v2), freq, speed);
    let x2y3 = constant(vec2<f32>(u2, v3), freq, speed);

    let x3y0 = constant(vec2<f32>(u3, v0), freq, speed);
    let x3y1 = constant(vec2<f32>(u3, v1), freq, speed);
    let x3y2 = constant(vec2<f32>(u3, v2), freq, speed);
    let x3y3 = constant(vec2<f32>(u3, v3), freq, speed);

    let uv = st * freq;

    let y0 = blendBicubic(x0y0, x1y0, x2y0, x3y0, fract(uv.x));
    let y1 = blendBicubic(x0y1, x1y1, x2y1, x3y1, fract(uv.x));
    let y2 = blendBicubic(x0y2, x1y2, x2y2, x3y2, fract(uv.x));
    let y3 = blendBicubic(x0y3, x1y3, x2y3, x3y3, fract(uv.x));

    return blendBicubic(y0, y1, y2, y3, fract(uv.y));
}

fn catmullRom4x4Value(st: vec2<f32>, freq: f32, speed: f32) -> f32 {
    let ndX = 1.0 / freq;
    let ndY = 1.0 / freq;

    let u0 = st.x - ndX;
    let u1 = st.x;
    let u2 = st.x + ndX;
    let u3 = st.x + ndX + ndX;

    let v0 = st.y - ndY;
    let v1 = st.y;
    let v2 = st.y + ndY;
    let v3 = st.y + ndY + ndY;

    let x0y0 = constant(vec2<f32>(u0, v0), freq, speed);
    let x0y1 = constant(vec2<f32>(u0, v1), freq, speed);
    let x0y2 = constant(vec2<f32>(u0, v2), freq, speed);
    let x0y3 = constant(vec2<f32>(u0, v3), freq, speed);

    let x1y0 = constant(vec2<f32>(u1, v0), freq, speed);
    let x1y1 = constant(st, freq, speed);
    let x1y2 = constant(vec2<f32>(u1, v2), freq, speed);
    let x1y3 = constant(vec2<f32>(u1, v3), freq, speed);

    let x2y0 = constant(vec2<f32>(u2, v0), freq, speed);
    let x2y1 = constant(vec2<f32>(u2, v1), freq, speed);
    let x2y2 = constant(vec2<f32>(u2, v2), freq, speed);
    let x2y3 = constant(vec2<f32>(u2, v3), freq, speed);

    let x3y0 = constant(vec2<f32>(u3, v0), freq, speed);
    let x3y1 = constant(vec2<f32>(u3, v1), freq, speed);
    let x3y2 = constant(vec2<f32>(u3, v2), freq, speed);
    let x3y3 = constant(vec2<f32>(u3, v3), freq, speed);

    let uv = st * freq;

    let y0 = catmullRom4(x0y0, x1y0, x2y0, x3y0, fract(uv.x));
    let y1 = catmullRom4(x0y1, x1y1, x2y1, x3y1, fract(uv.x));
    let y2 = catmullRom4(x0y2, x1y2, x2y2, x3y2, fract(uv.x));
    let y3 = catmullRom4(x0y3, x1y3, x2y3, x3y3, fract(uv.x));

    return catmullRom4(y0, y1, y2, y3, fract(uv.y));
}

fn value(st: vec2<f32>, freq: f32, interp: i32, speed: f32) -> f32 {
    if (interp == 3) {
        return catmullRom3x3Value(st, freq, speed);
    } else if (interp == 4) {
        return catmullRom4x4Value(st, freq, speed);
    } else if (interp == 5) {
        return quadratic3x3Value(st, freq, speed);
    } else if (interp == 6) {
        return bicubicValue(st, freq, speed);
    } else if (interp == 10) {
        let scaledTime = periodicFunction(time) * map(abs(speed), 0.0, 100.0, 0.0, 0.333);
        return simplexValue(st, freq, seed, scaledTime);
    } else if (interp == 11) {
        let scaledTime = periodicFunction(time) * map(abs(speed), 0.0, 100.0, 0.0, 0.333);
        return sineNoise(st, freq, seed, scaledTime);
    }

    let x1y1 = constant(st, freq, speed);

    if (interp == 0) {
        return x1y1;
    }

    let ndX = 1.0 / freq;
    let ndY = 1.0 / freq;

    let x1y2 = constant(vec2<f32>(st.x, st.y + ndY), freq, speed);
    let x2y1 = constant(vec2<f32>(st.x + ndX, st.y), freq, speed);
    let x2y2 = constant(vec2<f32>(st.x + ndX, st.y + ndY), freq, speed);

    let uv = st * freq;

    let a = blendLinearOrCosine(x1y1, x2y1, fract(uv.x), interp);
    let b = blendLinearOrCosine(x1y2, x2y2, fract(uv.x), interp);

    return blendLinearOrCosine(a, b, fract(uv.y), interp);
}

// Shape functions
fn circles(st: vec2<f32>, freq: f32) -> f32 {
    let dist = length(st - vec2<f32>(0.5 * aspectRatio, 0.5));
    return dist * freq;
}

fn rings(st: vec2<f32>, freq: f32) -> f32 {
    let dist = length(st - vec2<f32>(0.5 * aspectRatio, 0.5));
    return cos(dist * PI * freq);
}

fn diamonds(pos: vec4<f32>, freq: f32) -> f32 {
    var stLocal = globalCoord / fullResolution.y;
    stLocal = stLocal - vec2<f32>(0.5 * aspectRatio, 0.5);
    stLocal = stLocal * freq;
    return (cos(stLocal.x * PI) + cos(stLocal.y * PI));
}

fn shape(st: vec2<f32>, sides: i32, blend: f32) -> f32 {
    let stLocal = st * 2.0 - vec2<f32>(aspectRatio, 1.0);
    let a = atan2(stLocal.x, stLocal.y) + PI;
    let r = TAU / f32(sides);
    return cos(floor(0.5 + a / r) * r - a) * length(stLocal) * blend;
}

fn offset(st: vec2<f32>, freq: f32, loopOffset: i32, speed: f32, seedVal: f32, pos: vec4<f32>) -> f32 {
    if (loopOffset == 10) {
        return circles(st, freq);
    } else if (loopOffset == 20) {
        return shape(st, 3, freq * 0.5);
    } else if (loopOffset == 30) {
        return (abs(st.x - 0.5 * aspectRatio) + abs(st.y - 0.5)) * freq * 0.5;
    } else if (loopOffset >= 40 && loopOffset <= 120) {
        let sides = loopOffset / 10;
        return shape(st, sides, freq * 0.5);
    } else if (loopOffset == 200) {
        return st.x * freq * 0.5;
    } else if (loopOffset == 210) {
        return st.y * freq * 0.5;
    } else if (loopOffset >= 300 && loopOffset <= 380) {
        let idx = (loopOffset - 300) / 10;
        let interp = select(idx + 3, idx, idx <= 6);
        let f = select(freq, map(freq, 1.0, 6.0, 1.0, 20.0), loopOffset == 300);
        return 1.0 - value(st + seedVal, f, interp, speed);
    } else if (loopOffset == 400) {
        return 1.0 - rings(st, freq);
    } else if (loopOffset == 410) {
        return 1.0 - diamonds(pos, freq);
    }
    return 0.0;
}

@fragment
fn main(@builtin(position) pos: vec4<f32>) -> @location(0) vec4<f32> {
    resolution = uniforms.data[0].xy;
    time = uniforms.data[0].z;
    seed = uniforms.data[0].w;

    wrap = uniforms.data[1].x > 0.5;
    loopAScale = uniforms.data[1].w;

    loopBScale = uniforms.data[2].x;
    speedA = uniforms.data[2].y;
    speedB = uniforms.data[2].z;
    // Slot [2].w unused (was paletteMode)

    // Slot [3] = (tileOffset.x, tileOffset.y, fullResolution.x, fullResolution.y)
    tileOffset = uniforms.data[3].xy;
    fullResolution = uniforms.data[3].zw;

    var color = vec4<f32>(0.0, 0.0, 0.0, 1.0);
    globalCoord = pos.xy + tileOffset;
    var st = globalCoord / fullResolution.y;
    aspectRatio = fullResolution.x / fullResolution.y;

    var lf1 = map(loopAScale, 1.0, 100.0, 6.0, 1.0);
    if (wrap) {
        lf1 = floor(lf1);
        if (LOOP_A_OFFSET >= 200 && LOOP_A_OFFSET < 300) {
            lf1 = lf1 * 2.0;
        }
    }
    let amp1 = map(abs(speedA), 0.0, 100.0, 0.0, 1.0);
    var t1 = 1.0;
    if (speedA < 0.0) {
        t1 = time + offset(st, lf1, LOOP_A_OFFSET, amp1, seed, pos);
    } else if (speedA > 0.0) {
        t1 = time - offset(st, lf1, LOOP_A_OFFSET, amp1, seed, pos);
    }

    var lf2 = map(loopBScale, 1.0, 100.0, 6.0, 1.0);
    if (wrap) {
        lf2 = floor(lf2);
        if (LOOP_B_OFFSET >= 200 && LOOP_B_OFFSET < 300) {
            lf2 = lf2 * 2.0;
        }
    }
    let amp2 = map(abs(speedB), 0.0, 100.0, 0.0, 1.0);
    var t2 = 1.0;
    if (speedB < 0.0) {
        t2 = time + offset(st, lf2, LOOP_B_OFFSET, amp2, seed + 10.0, pos);
    } else if (speedB > 0.0) {
        t2 = time - offset(st, lf2, LOOP_B_OFFSET, amp2, seed + 10.0, pos);
    }

    let a = periodicFunction(t1) * amp1;
    let b = periodicFunction(t2) * amp2;

    let d = abs((a + b) - 1.0);

    // Mono output: grayscale intensity
    color = vec4<f32>(vec3<f32>(d), 1.0);

    return color;
}

// WGSL version – WebGPU
@group(0) @binding(0) var<uniform> color: vec3<f32>;
@group(0) @binding(1) var<uniform> alpha: f32;

/* Produces a constant color with premultiplied alpha. */
@fragment
fn main(@builtin(position) position: vec4<f32>) -> @location(0) vec4<f32> {
  // Premultiply RGB by alpha for correct compositing
  return vec4<f32>(color * alpha, alpha);
}

// WGSL version – WebGPU
@group(0) @binding(0) var<uniform> resolution: vec2<f32>;
@group(0) @binding(1) var<uniform> audioSpectrum: array<vec4<f32>, 32>;
@group(0) @binding(2) var<uniform> lineColor: vec3<f32>;
@group(0) @binding(3) var<uniform> lineThickness: f32;
@group(0) @binding(4) var<uniform> gain: f32;
@group(0) @binding(5) var<uniform> tileOffset: vec2<f32>;
@group(0) @binding(6) var<uniform> fullResolution: vec2<f32>;

fn sampleSpectrum(index: u32) -> f32 {
    return audioSpectrum[index / 4u][index % 4u];
}

@fragment
fn main(@builtin(position) position: vec4<f32>) -> @location(0) vec4<f32> {
    let globalCoord = position.xy + tileOffset;
    let uv = globalCoord / fullResolution;

    // Sample the spectrum at this x position
    let fIndex = uv.x * 127.0;
    let i0 = u32(floor(fIndex));
    let i1 = min(i0 + 1u, 127u);
    let fract_i = fract(fIndex);

    // Linearly interpolate between adjacent bins
    let s0 = sampleSpectrum(i0);
    let s1 = sampleSpectrum(i1);
    let mag = mix(s0, s1, fract_i) * gain;

    // Distance from fragment to spectrum curve, in pixels
    let dist = abs(uv.y - mag) * fullResolution.y;

    // Anti-aliased line
    let line = smoothstep(lineThickness + 1.0, lineThickness, dist);

    // Fill below the curve
    let fill = smoothstep(mag + 1.0 / fullResolution.y, mag, uv.y) * 0.15;

    let alpha = max(line, fill);
    return vec4<f32>(lineColor * alpha, alpha);
}

/*
 * Recursive grid subdivision with shapes
 */

struct Uniforms {
    // data[0] = (resolution.x, resolution.y, mode, depth)
    // data[1] = (density, seed, fill, outline)
    // data[2] = (inputMix, wrap, time, speed)
    // data[3] = (tileOffset.x, tileOffset.y, fullResolution.x, fullResolution.y)
    // data[4] = (renderScale, _, _, _)
    data: array<vec4<f32>, 5>,
}

@group(0) @binding(0) var<uniform> u: Uniforms;
@group(0) @binding(1) var samp: sampler;
@group(0) @binding(2) var inputTex: texture_2d<f32>;

// PCG PRNG - deterministic across platforms
fn pcg(v_in: vec3<u32>) -> vec3<u32> {
    var v = v_in * 1664525u + 1013904223u;
    v.x = v.x + v.y * v.z;
    v.y = v.y + v.z * v.x;
    v.z = v.z + v.x * v.y;
    v = v ^ (v >> vec3<u32>(16u));
    v.x = v.x + v.y * v.z;
    v.y = v.y + v.z * v.x;
    v.z = v.z + v.x * v.y;
    return v;
}

fn prng(p: vec3<f32>) -> vec3<f32> {
    return vec3<f32>(pcg(vec3<u32>(u32(p.x), u32(p.y), u32(p.z)))) / f32(0xffffffffu);
}

// Get a random float for a cell at a given level and channel
// Golden ratio for staggering level transitions
const PHI: f32 = 1.618033988749895;

fn cellRand(cellMin: vec2<f32>, level: f32, channel: f32, animSeed: f32) -> f32 {
    let cx = floor(cellMin.x * 1000.0);
    let cy = floor(cellMin.y * 1000.0);
    let seed = u.data[1].y;
    return prng(vec3<f32>(cx + level * 7.0, cy + level * 13.0, seed + channel + animSeed * 100.0)).x;
}

// Shape functions (1.0 inside, 0.0 outside)
// All work in 1:1 aspect-corrected centered coords
fn circleShape(centered: vec2<f32>) -> f32 {
    return step(length(centered), 0.32);
}

fn diamondShape(centered: vec2<f32>) -> f32 {
    return step(abs(centered.x) + abs(centered.y), 0.32);
}

fn squareShape(centered: vec2<f32>) -> f32 {
    return step(max(abs(centered.x), abs(centered.y)), 0.28);
}

fn arcShape(centered: vec2<f32>, halfW: f32, halfH: f32, h: f32) -> f32 {
    let corner = i32(h * 4.0);
    var origin: vec2<f32>;
    if (corner == 0) { origin = vec2<f32>(-halfW, -halfH); }
    else if (corner == 1) { origin = vec2<f32>(halfW, -halfH); }
    else if (corner == 2) { origin = vec2<f32>(-halfW, halfH); }
    else { origin = vec2<f32>(halfW, halfH); }
    let dist = length(centered - origin);
    return step(dist, 0.7) * (1.0 - step(dist, 0.5));
}

fn drawShape(shapeType: i32, centered: vec2<f32>, halfW: f32, halfH: f32, h: f32) -> f32 {
    if (shapeType == 0) { return 1.0; }  // solid
    if (shapeType == 1) { return circleShape(centered); }
    if (shapeType == 2) { return diamondShape(centered); }
    if (shapeType == 3) { return squareShape(centered); }
    if (shapeType == 4) { return arcShape(centered, halfW, halfH, h); }
    return 1.0;
}

fn shadeFromHash(h: f32) -> f32 {
    let idx = i32(h * 5.0);
    if (idx == 0) { return 0.15; }
    if (idx == 1) { return 0.35; }
    if (idx == 2) { return 0.55; }
    if (idx == 3) { return 0.75; }
    return 1.0;
}

@fragment
fn main(@builtin(position) pos: vec4<f32>) -> @location(0) vec4<f32> {
    let resolution = u.data[0].xy;
    let tileOffset = u.data[3].xy;
    let fullResolution = u.data[3].zw;
    let renderScale = u.data[4].x;
    let globalCoord = pos.xy + tileOffset;
    let modeType = i32(u.data[0].z);
    let maxDepth = i32(u.data[0].w);
    let dens = u.data[1].x / 100.0;
    let fillType = i32(u.data[1].z);
    let outlineWidthX = u.data[1].w * renderScale / fullResolution.x;
    let outlineWidthY = u.data[1].w * renderScale / fullResolution.y;

    let time = u.data[2].z;
    let spd = floor(u.data[2].w) * 2.0;

    let st = globalCoord / fullResolution;

    // Subdivision loop
    var cellMin = vec2<f32>(0.0);
    var cellMax = vec2<f32>(1.0);
    var isOutline = false;

    for (var level = 0; level < 6; level = level + 1) {
        if (level >= maxDepth) { break; }

        // Stagger each level's transition using golden ratio
        let levelTime = floor(time * spd + f32(level) * PHI);
        let h = cellRand(cellMin, f32(level), 0.0, levelTime);

        if (h < dens) {
            // Skip splits that would create too-narrow cells (max 5:1 aspect)
            let cellW = (cellMax.x - cellMin.x) * fullResolution.x;
            let cellH = (cellMax.y - cellMin.y) * fullResolution.y;
            let canSplitH = min(cellW, cellH * 0.5) / max(cellW, cellH * 0.5) >= 0.2;
            let canSplitV = min(cellW * 0.5, cellH) / max(cellW * 0.5, cellH) >= 0.2;

            if (modeType == 0) {
                let dir = cellRand(cellMin, f32(level), 1.0, levelTime);
                var splitDir = -1;
                if (dir < 0.5) {
                    if (canSplitH) { splitDir = 0; }
                    else if (canSplitV) { splitDir = 1; }
                } else {
                    if (canSplitV) { splitDir = 1; }
                    else if (canSplitH) { splitDir = 0; }
                }
                if (splitDir == 0) {
                    let mid = (cellMin.y + cellMax.y) * 0.5;
                    if (abs(st.y - mid) < outlineWidthY) { isOutline = true; }
                    if (st.y < mid) { cellMax.y = mid; }
                    else { cellMin.y = mid; }
                } else if (splitDir == 1) {
                    let mid = (cellMin.x + cellMax.x) * 0.5;
                    if (abs(st.x - mid) < outlineWidthX) { isOutline = true; }
                    if (st.x < mid) { cellMax.x = mid; }
                    else { cellMin.x = mid; }
                }
            } else {
                if (canSplitH && canSplitV) {
                    let mid = (cellMin + cellMax) * 0.5;
                    if (abs(st.x - mid.x) < outlineWidthX || abs(st.y - mid.y) < outlineWidthY) {
                        isOutline = true;
                    }
                    if (st.x < mid.x) { cellMax.x = mid.x; }
                    else { cellMin.x = mid.x; }
                    if (st.y < mid.y) { cellMax.y = mid.y; }
                    else { cellMin.y = mid.y; }
                }
            }
        }
    }

    // Cell properties
    let cellSize = cellMax - cellMin;
    let cellUv = (st - cellMin) / cellSize;

    // 1:1 aspect-corrected coords, scaled to fit shorter side
    let cellPixelW = cellSize.x * fullResolution.x;
    let cellPixelH = cellSize.y * fullResolution.y;
    let minDim = min(cellPixelW, cellPixelH);
    var centered = cellUv - 0.5;
    centered.x = centered.x * (cellPixelW / minDim);
    centered.y = centered.y * (cellPixelH / minDim);
    let halfW = cellPixelW / minDim * 0.5;
    let halfH = cellPixelH / minDim * 0.5;

    // Visual properties crossfade between current and next state
    let visualT = time * spd + PHI * 7.0;
    let curVisualTime = floor(visualT);
    let nextVisualTime = curVisualTime + 1.0;
    let visualBlend = smoothstep(0.0, 1.0, fract(visualT));

    // Crossfade shades
    let shade = mix(
        shadeFromHash(cellRand(cellMin, 0.0, 2.0, curVisualTime)),
        shadeFromHash(cellRand(cellMin, 0.0, 2.0, nextVisualTime)),
        visualBlend);
    let bgShade = mix(
        shadeFromHash(cellRand(cellMin, 0.0, 8.0, curVisualTime)),
        shadeFromHash(cellRand(cellMin, 0.0, 8.0, nextVisualTime)),
        visualBlend);

    // Crossfade shapes (dissolve between current and next)
    var curShapeType = fillType;
    var nextShapeType = fillType;
    if (modeType == 0) {
        curShapeType = 0;
        nextShapeType = 0;
    } else if (fillType == 5) {
        curShapeType = i32(cellRand(cellMin, 0.0, 3.0, curVisualTime) * 5.0);
        nextShapeType = i32(cellRand(cellMin, 0.0, 3.0, nextVisualTime) * 5.0);
    }
    let curCorner = cellRand(cellMin, 0.0, 4.0, curVisualTime);
    let nextCorner = cellRand(cellMin, 0.0, 4.0, nextVisualTime);
    let curMask = drawShape(curShapeType, centered, halfW, halfH, curCorner);
    let nextMask = drawShape(nextShapeType, centered, halfW, halfH, nextCorner);
    let shapeMask = mix(curMask, nextMask, visualBlend);

    let color = mix(bgShade, shade, shapeMask);
    var result = vec3<f32>(color);

    // Input texture blend (random scale, offset, aspect-preserving)
    let blend = u.data[2].x / 100.0;
    if (blend > 0.0) {
        let curTexScale = 0.3 + cellRand(cellMin, 0.0, 5.0, curVisualTime) * 0.7;
        let nextTexScale = 0.3 + cellRand(cellMin, 0.0, 5.0, nextVisualTime) * 0.7;
        let texScale = mix(curTexScale, nextTexScale, visualBlend);

        var texUv = cellUv;
        // Correct for aspect ratio difference between cell and texture
        let cellAspect = (cellSize.x * fullResolution.x) / (cellSize.y * fullResolution.y);
        let texAspect = fullResolution.x / fullResolution.y;
        let ratio = cellAspect / texAspect;
        if (ratio > 1.0) {
            texUv.x = 0.5 + (texUv.x - 0.5) * ratio;
        } else {
            texUv.y = 0.5 + (texUv.y - 0.5) / ratio;
        }
        texUv = texUv * texScale;
        texUv.x = texUv.x + mix(
            cellRand(cellMin, 0.0, 6.0, curVisualTime),
            cellRand(cellMin, 0.0, 6.0, nextVisualTime),
            visualBlend) * (1.0 - texScale);
        texUv.y = texUv.y + mix(
            cellRand(cellMin, 0.0, 7.0, curVisualTime),
            cellRand(cellMin, 0.0, 7.0, nextVisualTime),
            visualBlend) * (1.0 - texScale);
        // Apply wrap mode
        let wrapMode = i32(u.data[2].y);
        if (wrapMode == 0) {
            texUv = abs((texUv + 1.0) - 2.0 * floor((texUv + 1.0) / 2.0) - 1.0);
        } else if (wrapMode == 1) {
            texUv = (texUv - 1.0 * floor(texUv / 1.0));
        } else {
            texUv = clamp(texUv, vec2<f32>(0.0), vec2<f32>(1.0));
        }
        let inputColor = textureSample(inputTex, samp, texUv).rgb;
        result = mix(result, inputColor, blend);
    }

    // Outline (black, drawn after texture so it stays visible)
    if (isOutline && u.data[1].w > 0.0) {
        result = vec3<f32>(0.0);
    }

    return vec4<f32>(result, 1.0);
}

// WGSL version – WebGPU

struct Uniforms {
    resolution: vec2f,
    gridSize: i32,
    pattern: i32,
    tileOffset: vec2f,
    fullResolution: vec2f,
}

@group(0) @binding(0) var<uniform> uniforms: Uniforms;

// 3x5 pixel font for digits 0-9
// Each digit is encoded as 15 bits (3 columns x 5 rows, row-major)
const GLYPH = array<i32, 10>(
    0x7B6F,  // 0: 111 101 101 101 111
    0x2492,  // 1: 010 010 010 010 010
    0x73E7,  // 2: 111 001 111 100 111
    0x72CF,  // 3: 111 001 011 001 111
    0x5BC9,  // 4: 101 101 111 001 001
    0x79CF,  // 5: 111 100 111 001 111
    0x79EF,  // 6: 111 100 111 101 111
    0x7249,  // 7: 111 001 001 001 001
    0x7BEF,  // 8: 111 101 111 101 111
    0x7BCF   // 9: 111 101 111 001 111
);

// Sample a glyph at local coordinates (0-2, 0-4)
fn sampleGlyph(digit: i32, x: i32, y: i32) -> bool {
    if (digit < 0 || digit > 9 || x < 0 || x > 2 || y < 0 || y > 4) {
        return false;
    }
    let bitIndex = y * 3 + (2 - x);  // row-major, top-left origin
    return ((GLYPH[digit] >> u32(bitIndex)) & 1) == 1;
}

// Render a number at a position within a cell
fn renderNumber(number: i32, cellUV: vec2f) -> bool {
    // Determine how many digits we need
    var numDigits = 1;
    if (number >= 10) { numDigits = 2; }
    if (number >= 100) { numDigits = 3; }

    // Glyph dimensions in UV space (centered, scaled to fit nicely)
    let glyphWidth = 0.15;
    let glyphHeight = 0.35;
    let spacing = 0.05;

    let totalWidth = f32(numDigits) * glyphWidth + f32(numDigits - 1) * spacing;
    let startX = 0.5 - totalWidth * 0.5;
    let startY = 0.5 - glyphHeight * 0.5;

    // Check if we're in the vertical range for glyphs
    if (cellUV.y < startY || cellUV.y >= startY + glyphHeight) {
        return false;
    }

    // Extract digits (right to left)
    var digits = array<i32, 3>(0, 0, 0);
    var temp = number;
    for (var i = 0; i < 3; i++) {
        digits[i] = temp % 10;
        temp = temp / 10;
    }

    // Check each digit position (left to right)
    for (var d = 0; d < numDigits; d++) {
        let digitX = startX + f32(d) * (glyphWidth + spacing);

        if (cellUV.x >= digitX && cellUV.x < digitX + glyphWidth) {
            // We're in this digit's horizontal range
            let localX = (cellUV.x - digitX) / glyphWidth;
            let localY = (cellUV.y - startY) / glyphHeight;

            // Map to 3x5 grid
            let gx = i32(localX * 3.0);
            let gy = i32(localY * 5.0);

            // Get the correct digit (numDigits-1-d because digits[] is reversed)
            let digit = digits[numDigits - 1 - d];

            return sampleGlyph(digit, gx, gy);
        }
    }

    return false;
}

// Pattern 0: Numbered checkerboard
fn checkerboard(uv: vec2f) -> vec4f {
    let n = max(uniforms.gridSize, 1);
    let cellX = i32(uv.x * f32(n)) % n;
    let cellY = i32(uv.y * f32(n)) % n;

    let cellNum = (n - 1 - cellY) * n + cellX;

    let isWhiteCell = ((cellX + cellY) % 2) == 0;

    let cellUV = fract(uv * f32(n));

    let isGlyph = renderNumber(cellNum, cellUV);

    let cellColor = select(0.0, 1.0, isWhiteCell);
    let glyphColor = select(1.0, 0.0, isWhiteCell);
    let finalColor = select(cellColor, glyphColor, isGlyph);

    return vec4f(vec3f(finalColor), 1.0);
}

// Pattern 1: 8 vertical SMPTE-style color bars
fn colorBars(uv: vec2f) -> vec4f {
    var bar = i32(uv.x * 8.0);
    bar = clamp(bar, 0, 7);

    // white, yellow, cyan, green, magenta, red, blue, black
    let colors = array<vec3f, 8>(
        vec3f(1.0, 1.0, 1.0),
        vec3f(1.0, 1.0, 0.0),
        vec3f(0.0, 1.0, 1.0),
        vec3f(0.0, 1.0, 0.0),
        vec3f(1.0, 0.0, 1.0),
        vec3f(1.0, 0.0, 0.0),
        vec3f(0.0, 0.0, 1.0),
        vec3f(0.0, 0.0, 0.0)
    );

    return vec4f(colors[bar], 1.0);
}

// Pattern 2: Horizontal black-to-white gradient ramp
fn gradientRamp(uv: vec2f) -> vec4f {
    return vec4f(vec3f(uv.x), 1.0);
}

// Pattern 3: UV map (R=u, G=v, B=0)
fn uvMapPattern(uv: vec2f) -> vec4f {
    return vec4f(uv.x, uv.y, 0.0, 1.0);
}

// Pattern 4: Thin white grid lines on black
fn gridLines(uv: vec2f) -> vec4f {
    let n = max(uniforms.gridSize, 1);
    let cellUV = fract(uv * f32(n));
    let edge = min(cellUV, 1.0 - cellUV);

    // Use direct calculation instead of fwidth() for tile-aware rendering.
    // This maintains the same line thickness in normal rendering while ensuring
    // continuity across tile boundaries during large-format print export.
    let fr = select(uniforms.resolution, uniforms.fullResolution, uniforms.fullResolution.x > 0.0);
    let fw = vec2f(1.0) / fr * f32(n);

    let line = 1.0 - smoothstep(0.0, 2.0 * fw.x, edge.x) * smoothstep(0.0, 2.0 * fw.y, edge.y);
    return vec4f(vec3f(line), 1.0);
}

// HSV to RGB (hue only, full saturation & value)
fn hue2rgb(h: f32) -> vec3f {
    let r = abs(h * 6.0 - 3.0) - 1.0;
    let g = 2.0 - abs(h * 6.0 - 2.0);
    let b = 2.0 - abs(h * 6.0 - 4.0);
    return clamp(vec3f(r, g, b), vec3f(0.0), vec3f(1.0));
}

// Pattern 5: Each cell gets a unique hue
fn colorGrid(uv: vec2f) -> vec4f {
    let n = max(uniforms.gridSize, 1);
    let cellX = i32(uv.x * f32(n)) % n;
    let cellY = i32(uv.y * f32(n)) % n;
    let cellIndex = cellY * n + cellX;
    let hue = fract(f32(cellIndex) * 0.618033988749895);
    return vec4f(hue2rgb(hue), 1.0);
}

// Pattern 6: Filled circle at each grid intersection
fn dotGrid(uv: vec2f) -> vec4f {
    let n = max(uniforms.gridSize, 1);
    let scaled = uv * f32(n);
    let nearest = round(scaled);
    let dist = length(scaled - nearest);
    let d = 1.0 - smoothstep(0.12, 0.15, dist);
    return vec4f(vec3f(d), 1.0);
}

@fragment
fn main(@builtin(position) position: vec4f) -> @location(0) vec4f {
    // Tile-aware global UV (mirror glsl/testPattern.glsl). Non-tiling
    // (tileOffset=(0,0), fullResolution=resolution) is byte-identical.
    let fr = select(uniforms.resolution, uniforms.fullResolution, uniforms.fullResolution.x > 0.0);
    let uv = (position.xy + uniforms.tileOffset) / fr;

    if (uniforms.pattern == 1) {
        return colorBars(uv);
    } else if (uniforms.pattern == 2) {
        return gradientRamp(uv);
    } else if (uniforms.pattern == 3) {
        return uvMapPattern(uv);
    } else if (uniforms.pattern == 4) {
        return gridLines(uv);
    } else if (uniforms.pattern == 5) {
        return colorGrid(uv);
    } else if (uniforms.pattern == 6) {
        return dotGrid(uv);
    } else {
        return checkerboard(uv);
    }
}

// WGSL version – WebGPU
@group(0) @binding(0) var<uniform> scale: f32;
@group(0) @binding(1) var<uniform> seed: i32;
@group(0) @binding(2) var<uniform> metric: i32;
@group(0) @binding(3) var<uniform> cellVariation: f32;
@group(0) @binding(4) var<uniform> volumeSize: i32;
@group(0) @binding(5) var<uniform> colorMode: i32;

// Volume dimensions - stored as 2D atlas
// Atlas layout: volumeSize x (volumeSize * volumeSize)

// PCG-based 3D hash for reproducible randomness
fn pcg3d(v_in: vec3<u32>) -> vec3<u32> {
    var v = v_in * 1664525u + 1013904223u;
    v.x = v.x + v.y * v.z;
    v.y = v.y + v.z * v.x;
    v.z = v.z + v.x * v.y;
    v = v ^ (v >> vec3<u32>(16u));
    v.x = v.x + v.y * v.z;
    v.y = v.y + v.z * v.x;
    v.z = v.z + v.x * v.y;
    return v;
}

fn hash3(p: vec3<f32>) -> vec3<f32> {
    let ps = p + f32(seed) * 0.1;
    let q = pcg3d(vec3<u32>(vec3<i32>(ps * 1000.0) + 65536));
    return vec3<f32>(q) / 4294967295.0;
}

// 3D Worley/Cell noise - returns distance to nearest cell and cell ID
fn cellNoise3D(p: vec3<f32>) -> vec2<f32> {
    let i = floor(p);
    let f = fract(p);

    var minDist: f32 = 10.0;
    var cellId: f32 = 0.0;

    // Search 3x3x3 neighborhood
    for (var z: i32 = -1; z <= 1; z = z + 1) {
        for (var y: i32 = -1; y <= 1; y = y + 1) {
            for (var x: i32 = -1; x <= 1; x = x + 1) {
                let neighbor = vec3<f32>(f32(x), f32(y), f32(z));
                let cellPos = i + neighbor;

                let randomOffset = hash3(cellPos);
                let jitter = cellVariation * 0.01;
                let cellPoint = neighbor + mix(vec3<f32>(0.5), randomOffset, jitter);

                let diff = cellPoint - f;

                var dist: f32;
                if (metric == 0) {
                    dist = length(diff);
                } else if (metric == 1) {
                    dist = abs(diff.x) + abs(diff.y) + abs(diff.z);
                } else {
                    dist = max(max(abs(diff.x), abs(diff.y)), abs(diff.z));
                }

                if (dist < minDist) {
                    minDist = dist;
                    cellId = cellPos.x * 73.0 + cellPos.y * 157.0 + cellPos.z * 311.0;
                }
            }
        }
    }

    return vec2<f32>(minDist, cellId);
}

// MRT output structure for volume cache and geometry buffer
struct FragOutput {
    @location(0) color: vec4<f32>,
    @location(1) geoOut: vec4<f32>,
}

@fragment
fn main(@builtin(position) position: vec4<f32>) -> FragOutput {
    // Use uniform for volume size
    let volSize = volumeSize;
    let volSizeF = f32(volSize);

    // Atlas is volSize x (volSize * volSize)
    // Pixel (x, y) maps to 3D coordinate (x, y % volSize, y / volSize)

    let pixelCoord = vec2<i32>(position.xy);

    let x = pixelCoord.x;
    let y = pixelCoord.y % volSize;
    let z = pixelCoord.y / volSize;

    // Bounds check
    if (x >= volSize || y >= volSize || z >= volSize) {
        return FragOutput(vec4<f32>(0.0), vec4<f32>(0.5, 0.5, 0.5, 0.0));
    }

    // Convert to normalized 3D coordinates in [-1, 1] world space (bounding box)
    // Use (volSizeF - 1.0) so texel 0 → -1.0 and texel N-1 → 1.0 exactly
    // This matches the sampling in the main shader which uses the same denominator
    var p = vec3<f32>(f32(x), f32(y), f32(z)) / (volSizeF - 1.0) * 2.0 - 1.0;

    // Scale for cell noise density
    let scaledP = p * (16.0 - scale);

    // Compute cell noise at this point
    let result = cellNoise3D(scaledP);
    let dist = result.x;
    let cellId = result.y;

    // Normalize distance based on metric
    var normalizer: f32;
    if (metric == 0) {
        normalizer = 0.866;  // Euclidean
    } else if (metric == 1) {
        normalizer = 1.5;    // Manhattan
    } else {
        normalizer = 0.6;    // Chebyshev
    }
    let normalizedDist = 1.0 - clamp(dist / normalizer, 0.0, 1.0);

    // Generate color from cell ID (for RGB mode)
    let h1 = fract(cellId * 0.0127);
    let h2 = fract(cellId * 0.0231);
    let h3 = fract(cellId * 0.0347);

    // Compute analytical gradient using finite differences
    let eps = 1.0 / volSizeF;
    let dx = cellNoise3D(scaledP + vec3<f32>(eps, 0.0, 0.0)).x;
    let dy = cellNoise3D(scaledP + vec3<f32>(0.0, eps, 0.0)).x;
    let dz = cellNoise3D(scaledP + vec3<f32>(0.0, 0.0, eps)).x;

    let gradient = vec3<f32>(dx - dist, dy - dist, dz - dist) / eps;
    let normal = normalize(-gradient + vec3<f32>(0.000001));

    // Pack output based on colorMode
    // colorMode 0 = mono (grayscale), 1 = rgb (cell colors)
    var color: vec4<f32>;
    if (colorMode == 0) {
        color = vec4<f32>(normalizedDist, normalizedDist, normalizedDist, 1.0);
    } else {
        color = vec4<f32>(normalizedDist, h1, h2, h3);
    }
    let geoOut = vec4<f32>(normal * 0.5 + 0.5, normalizedDist);

    return FragOutput(color, geoOut);
}

/*
 * 3D Cellular Automata simulation shader (WGSL)
 * Implements various 3D CA rules with Moore (26) or Von Neumann (6) neighborhoods
 * Self-initializing: detects empty buffer and seeds on first frame
 */

@group(0) @binding(0) var<uniform> volumeSize: i32;
@group(0) @binding(1) var<uniform> seed: i32;
@group(0) @binding(2) var<uniform> ruleIndex: i32;
@group(0) @binding(3) var<uniform> neighborMode: i32;
@group(0) @binding(4) var<uniform> speed: f32;
@group(0) @binding(5) var<uniform> density: f32;
@group(0) @binding(6) var<uniform> weight: f32;
@group(0) @binding(7) var<uniform> resetState: i32;
@group(0) @binding(8) var stateTex: texture_2d<f32>;
@group(0) @binding(9) var seedTex: texture_2d<f32>;  // 3D input volume atlas (inputTex3d)

// Hash for initialization
fn hash3(p: vec3<f32>, s: f32) -> f32 {
    var pp = p + s * 0.1;
    pp = fract(pp * vec3<f32>(0.1031, 0.1030, 0.0973));
    pp = pp + dot(pp, pp.yxz + 33.33);
    return fract((pp.x + pp.y) * pp.z);
}

// Helper to convert 3D voxel coords to 2D atlas texel coords with wrapping
fn atlasTexel(p: vec3<i32>, volSize: i32) -> vec2<i32> {
    // Wrap coordinates for periodic boundary
    let wrapped = vec3<i32>(
        (p.x + volSize) % volSize,
        (p.y + volSize) % volSize,
        (p.z + volSize) % volSize
    );
    return vec2<i32>(wrapped.x, wrapped.y + wrapped.z * volSize);
}

// Sample state at voxel coordinate with wrapping
fn sampleState(voxel: vec3<i32>, volSize: i32) -> vec4<f32> {
    return textureLoad(stateTex, atlasTexel(voxel, volSize), 0);
}

// Sample seed texture at voxel coordinate (for inputTex3d seeding)
fn sampleSeed(voxel: vec3<i32>, volSize: i32) -> vec4<f32> {
    return textureLoad(seedTex, atlasTexel(voxel, volSize), 0);
}

// Count alive neighbors using Moore neighborhood (26 neighbors)
fn countMooreNeighbors(voxel: vec3<i32>, volSize: i32) -> i32 {
    var count: i32 = 0;
    for (var dz: i32 = -1; dz <= 1; dz = dz + 1) {
        for (var dy: i32 = -1; dy <= 1; dy = dy + 1) {
            for (var dx: i32 = -1; dx <= 1; dx = dx + 1) {
                if (dx == 0 && dy == 0 && dz == 0) { continue; }
                let neighbor = sampleState(voxel + vec3<i32>(dx, dy, dz), volSize);
                if (neighbor.r > 0.5) { count = count + 1; }
            }
        }
    }
    return count;
}

// Count alive neighbors using Von Neumann neighborhood (6 neighbors)
fn countVonNeumannNeighbors(voxel: vec3<i32>, volSize: i32) -> i32 {
    var count: i32 = 0;
    let xp = sampleState(voxel + vec3<i32>(1, 0, 0), volSize);
    let xn = sampleState(voxel + vec3<i32>(-1, 0, 0), volSize);
    let yp = sampleState(voxel + vec3<i32>(0, 1, 0), volSize);
    let yn = sampleState(voxel + vec3<i32>(0, -1, 0), volSize);
    let zp = sampleState(voxel + vec3<i32>(0, 0, 1), volSize);
    let zn = sampleState(voxel + vec3<i32>(0, 0, -1), volSize);

    if (xp.r > 0.5) { count = count + 1; }
    if (xn.r > 0.5) { count = count + 1; }
    if (yp.r > 0.5) { count = count + 1; }
    if (yn.r > 0.5) { count = count + 1; }
    if (zp.r > 0.5) { count = count + 1; }
    if (zn.r > 0.5) { count = count + 1; }

    return count;
}

// Check if cell should be born
fn shouldBeBorn(n: i32, rule: i32) -> bool {
    if (rule == 0) { return n == 4; }                                   // 445M
    if (rule == 1) { return n >= 6 && n <= 8; }                         // 678 678
    if (rule == 2) { return n >= 9; }                                   // Amoeba
    if (rule == 3) { return n == 4 || n == 6 || n == 8 || n == 9; }     // Builder1
    if (rule == 4) { return n == 3; }                                   // Builder2 (3D Life)
    if (rule == 5) { return n >= 13; }                                  // Clouds
    if (rule == 6) { return n == 1 || n == 3; }                         // Crystal
    if (rule == 7) { return (n >= 5 && n <= 7) || n == 12; }            // Diamoeba
    if (rule == 8) { return n >= 4 && n <= 7; }                         // Pyroclastic
    if (rule == 9) { return n == 4; }                                   // Slow Decay
    if (rule == 10) { return n >= 5 && n <= 8; }                        // Spikey
    return false;
}

// Check if cell should survive
fn shouldSurvive(n: i32, rule: i32) -> bool {
    if (rule == 0) { return n == 4; }                                    // 445M
    if (rule == 1) { return n >= 6 && n <= 8; }                          // 678 678
    if (rule == 2) { return (n >= 5 && n <= 7) || n == 12 || n == 13 || n == 15; }  // Amoeba
    if (rule == 3) { return (n >= 3 && n <= 6) || n == 9; }              // Builder1
    if (rule == 4) { return n == 2 || n == 3; }                          // Builder2 (3D Life)
    if (rule == 5) { return n >= 13; }                                   // Clouds
    if (rule == 6) { return n == 1 || n == 2 || n == 4; }                // Crystal
    if (rule == 7) { return n >= 5 && n <= 8; }                          // Diamoeba
    if (rule == 8) { return n >= 6 && n <= 8; }                          // Pyroclastic
    if (rule == 9) { return n == 3 || n == 4; }                          // Slow Decay
    if (rule == 10) { return n == 5 || n == 6 || n == 9; }               // Spikey
    return false;
}

@fragment
fn main(@builtin(position) position: vec4<f32>) -> @location(0) vec4<f32> {
    let volSize = volumeSize;
    let volSizeF = f32(volSize);

    // Decode voxel position from atlas
    let pixelCoord = vec2<i32>(position.xy);
    let x = pixelCoord.x;
    let y = pixelCoord.y % volSize;
    let z = pixelCoord.y / volSize;
    let voxel = vec3<i32>(x, y, z);

    // Bounds check
    if (x >= volSize || y >= volSize || z >= volSize) {
        return vec4<f32>(0.0);
    }

    // Current state
    let state = sampleState(voxel, volSize);
    var alive = state.r;
    var age = state.g;

    // Self-initialization or reset: detect empty buffer (first frame) or reset button
    let bufferIsEmpty = (state.r == 0.0 && state.g == 0.0 && state.b == 0.0 && state.a == 0.0);

    if (bufferIsEmpty || resetState != 0) {
        // Check if we have input from seedTex (inputTex3d)
        let seedVal = sampleSeed(voxel, volSize);
        let hasSeedInput = (seedVal.r > 0.0 || seedVal.g > 0.0 || seedVal.b > 0.0);

        if (hasSeedInput) {
            // Use seed texture luminance to determine initial alive state
            let lum = 0.299 * seedVal.r + 0.587 * seedVal.g + 0.114 * seedVal.b;
            if (lum > 0.5) {
                alive = 1.0;
            } else {
                alive = 0.0;
            }
            age = 0.0;
        } else {
            // Initialize with random sparse distribution
            let p = vec3<f32>(f32(x), f32(y), f32(z));
            let h = hash3(p, f32(seed));
            let thresh = density * 0.01;

            // Seed a sphere in the center plus random cells
            let center = vec3<f32>(volSizeF * 0.5);
            let dist = length(p - center);
            let radius = volSizeF * 0.15;

            if (h < thresh || dist < radius) {
                alive = 1.0;
                age = 0.0;
            } else {
                alive = 0.0;
                age = 0.0;
            }
        }

        return vec4<f32>(alive, alive, alive, 1.0);
    }

    // Count neighbors based on neighborhood mode
    var neighbors: i32;
    if (neighborMode == 0) {
        neighbors = countMooreNeighbors(voxel, volSize);
    } else {
        neighbors = countVonNeumannNeighbors(voxel, volSize);
    }

    // Apply CA rules
    var newAlive: f32 = 0.0;
    var newAge: f32 = age;

    if (alive > 0.5) {
        // Cell is alive - check survival
        if (shouldSurvive(neighbors, ruleIndex)) {
            newAlive = 1.0;
            newAge = min(age + 0.01, 1.0);  // Age increases while alive
        } else {
            newAlive = 0.0;
            newAge = 0.0;
        }
    } else {
        // Cell is dead - check birth
        if (shouldBeBorn(neighbors, ruleIndex)) {
            newAlive = 1.0;
            newAge = 0.0;
        } else {
            newAlive = 0.0;
            newAge = 0.0;
        }
    }

    // Speed control - interpolate between states
    let animSpeed = speed * 0.01;
    var finalAlive = mix(alive, newAlive, animSpeed);
    let finalAge = mix(age, newAge, animSpeed);

    // Apply input weight blending from seedTex (inputTex3d)
    if (weight > 0.0) {
        let seedVal = sampleSeed(voxel, volSize);
        let seedLum = 0.299 * seedVal.r + 0.587 * seedVal.g + 0.114 * seedVal.b;
        finalAlive = mix(finalAlive, seedLum, weight * 0.01);
    }

    return vec4<f32>(finalAlive, finalAlive, finalAlive, 1.0);
}

// Flythrough3D Precompute - WGSL
// Orbital path through fractal interior

@group(0) @binding(0) var<uniform> time: f32;
@group(0) @binding(1) var<uniform> volumeSize: i32;
@group(0) @binding(2) var<uniform> noiseType: i32;
@group(0) @binding(3) var<uniform> power: f32;
@group(0) @binding(4) var<uniform> iterations: i32;
@group(0) @binding(5) var<uniform> bailout: f32;
@group(0) @binding(6) var<uniform> speed: f32;
@group(0) @binding(7) var<uniform> voiSize: f32;
@group(0) @binding(8) var<uniform> seed: f32;

const SAFETY_RADIUS: f32 = 0.08;
const PI: f32 = 3.141592653589793;
const TAU: f32 = 6.283185307179586;

// ============================================================================
// FLYTHROUGH ENGINE - Orbital path through fractal interior
// ============================================================================

fn hash(n: f32) -> f32 {
    return fract(sin(n + seed) * 43758.5453123);
}

// ============================================================================
// ORBIT PATH GENERATION
// ============================================================================

fn trefoilKnot(t: f32, scale: f32) -> vec3f {
    let p = 2.0;
    let q = 3.0;
    let r = 0.5 + 0.2 * cos(q * t);
    return scale * vec3f(
        r * cos(p * t),
        r * sin(p * t),
        0.3 * sin(q * t)
    );
}

fn tiltedOrbit(t: f32, scale: f32) -> vec3f {
    let tilt = 0.4;

    let a = 1.0;
    let b = 0.7;
    var pos = vec3f(
        a * cos(t),
        b * sin(t),
        0.0
    );

    let c = cos(tilt);
    let s = sin(tilt);
    pos = vec3f(pos.x, pos.y * c - pos.z * s, pos.y * s + pos.z * c);

    return scale * pos;
}

fn lissajousOrbit(t: f32, scale: f32) -> vec3f {
    let fx = 1.0;
    let fy = 1.618;
    let fz = 2.0;
    let px = 0.0;
    let py = PI * 0.5;
    let pz = PI * 0.25;

    return scale * vec3f(
        sin(fx * t + px),
        sin(fy * t + py) * 0.6,
        sin(fz * t + pz) * 0.4
    );
}

fn getOrbitPosition(t: f32) -> vec3f {
    let orbitScale = 0.7;
    let orbitType = i32(seed * 3.0) % 3;

    if (orbitType == 0) {
        return trefoilKnot(t, orbitScale);
    } else if (orbitType == 1) {
        return tiltedOrbit(t, orbitScale);
    } else {
        return lissajousOrbit(t, orbitScale);
    }
}

fn getOrbitTangent(t: f32) -> vec3f {
    let dt = 0.01;
    let p0 = getOrbitPosition(t);
    let p1 = getOrbitPosition(t + dt);
    return normalize(p1 - p0);
}

fn getWobbleOffset(t: f32, tangent: vec3f) -> vec3f {
    var up = vec3f(0.0, 1.0, 0.0);
    if (abs(dot(tangent, up)) > 0.99) {
        up = vec3f(1.0, 0.0, 0.0);
    }
    let right = normalize(cross(tangent, up));
    let realUp = normalize(cross(right, tangent));

    let wobbleAmp = 0.15;
    let wx = sin(t * 2.7 + seed * PI) * wobbleAmp;
    let wy = sin(t * 1.9 + seed * TAU) * wobbleAmp * 0.7;

    return right * wx + realUp * wy;
}

// ============================================================================
// CAMERA STATE
// ============================================================================

struct CameraState {
    pos: vec3f,
    dir: vec3f,
    up: vec3f,
}

fn getCameraState(t: f32) -> CameraState {
    let orbitTime = t * speed * 0.3;

    let orbitPos = getOrbitPosition(orbitTime);
    let tangent = getOrbitTangent(orbitTime);
    let wobble = getWobbleOffset(orbitTime, tangent);
    let pos = orbitPos + wobble;

    let dir = tangent;

    let worldUp = vec3f(0.0, 1.0, 0.0);
    var right = normalize(cross(worldUp, dir));
    var up = normalize(cross(dir, right));

    let roll = sin(orbitTime * 0.5) * 0.1;
    let rollRight = right * cos(roll) + up * sin(roll);
    up = normalize(cross(rollRight, dir));

    return CameraState(pos, dir, up);
}

// ============================================================================
// FRACTAL DISTANCE ESTIMATORS
// ============================================================================

struct FractalResult {
    dist: f32,
    trap: f32,
    iterRatio: f32,
}

fn mandelbulb(pos: vec3f, n: f32, maxIter: i32, bail: f32) -> FractalResult {
    var z = pos;
    var dr = 1.0;
    var r = 0.0;
    var trap = 1e10;
    var iter = 0.0;

    for (var i = 0; i < maxIter; i++) {
        r = length(z);
        if (r > bail) { break; }

        trap = min(trap, r);

        let theta = acos(z.z / r);
        let phi = atan2(z.y, z.x);

        dr = pow(r, n - 1.0) * n * dr + 1.0;

        let zr = pow(r, n);
        let newTheta = theta * n;
        let newPhi = phi * n;

        z = zr * vec3f(
            sin(newTheta) * cos(newPhi),
            sin(newTheta) * sin(newPhi),
            cos(newTheta)
        );
        z += pos;

        iter += 1.0;
    }

    let dist = 0.5 * log(r) * r / dr;
    return FractalResult(dist, trap, iter / f32(maxIter));
}

fn boxFold(z: vec3f, foldLimit: f32) -> vec3f {
    return clamp(z, vec3f(-foldLimit), vec3f(foldLimit)) * 2.0 - z;
}

fn mandelbox(pos: vec3f, scale: f32, maxIter: i32, bail: f32) -> FractalResult {
    var z = pos;
    var dr = 1.0;
    var trap = 1e10;
    var iter = 0.0;

    let foldLimit = 1.0;
    let minRadius2 = 0.25;
    let fixedRadius2 = 1.0;

    for (var i = 0; i < maxIter; i++) {
        z = boxFold(z, foldLimit);

        let r2 = dot(z, z);
        if (r2 < minRadius2) {
            let factor = fixedRadius2 / minRadius2;
            z *= factor;
            dr *= factor;
        } else if (r2 < fixedRadius2) {
            let factor = fixedRadius2 / r2;
            z *= factor;
            dr *= factor;
        }

        z = z * scale + pos;
        dr = dr * abs(scale) + 1.0;

        let planeTrap = min(min(abs(z.x), abs(z.y)), abs(z.z));
        trap = min(trap, planeTrap);

        iter += 1.0;

        if (length(z) > bail) { break; }
    }

    let r = length(z);
    let dist = r / abs(dr);
    return FractalResult(dist, trap, iter / f32(maxIter));
}

fn computeFractal(p: vec3f) -> FractalResult {
    if (noiseType == 0) {
        return mandelbulb(p, power, iterations, bailout);
    } else {
        return mandelbox(p, power, iterations, bailout);
    }
}

fn computeGradient(p: vec3f, eps: f32) -> vec3f {
    let d0 = computeFractal(p).dist;
    let dx = computeFractal(p + vec3f(eps, 0.0, 0.0)).dist;
    let dy = computeFractal(p + vec3f(0.0, eps, 0.0)).dist;
    let dz = computeFractal(p + vec3f(0.0, 0.0, eps)).dist;
    return vec3f(dx - d0, dy - d0, dz - d0) / eps;
}

// ============================================================================
// COLLISION AVOIDANCE
// ============================================================================

fn applyCollisionAvoidance(pos: vec3f) -> vec3f {
    let fr = computeFractal(pos);

    if (fr.dist < SAFETY_RADIUS) {
        let grad = computeGradient(pos, 0.01);
        let pushDir = normalize(grad + vec3f(1e-6));
        let pushDist = SAFETY_RADIUS - fr.dist;
        return pos + pushDir * pushDist * 1.5;
    }

    return pos;
}

// ============================================================================
// MAIN
// ============================================================================

struct FragmentOutput {
    @location(0) color: vec4f,
    @location(1) geo: vec4f,
}

@fragment
fn main(@builtin(position) fragCoord: vec4f) -> FragmentOutput {
    let volSize = volumeSize;
    let volSizeF = f32(volSize);

    let pixelCoord = vec2i(fragCoord.xy);
    let vx = pixelCoord.x;
    let vy = pixelCoord.y % volSize;
    let vz = pixelCoord.y / volSize;

    if (vx >= volSize || vy >= volSize || vz >= volSize) {
        return FragmentOutput(
            vec4f(0.0),
            vec4f(0.5, 0.5, 0.5, 0.0)
        );
    }

    // Get camera state
    let cam = getCameraState(time);

    // Apply collision avoidance
    let camPos = applyCollisionAvoidance(cam.pos);

    // Build camera basis
    let camRight = normalize(cross(cam.dir, cam.up));
    let camUp = normalize(cross(camRight, cam.dir));

    // Convert voxel coords to normalized coords
    let normalizedCoord = (vec3f(f32(vx), f32(vy), f32(vz)) / (volSizeF - 1.0)) * 2.0 - 1.0;

    // VOI centered on camera
    let halfExtent = voiSize * 0.5;
    let voiOffset = cam.dir * halfExtent;

    let worldPos = camPos + voiOffset
                 + camRight * normalizedCoord.x * halfExtent
                 + camUp * normalizedCoord.y * halfExtent
                 + cam.dir * normalizedCoord.z * halfExtent;

    // Compute fractal
    let fr = computeFractal(worldPos);

    // Distance to density mapping
    let dist = fr.dist;
    let normalizedDist = 1.0 - clamp(dist * 2.0 + 0.5, 0.0, 1.0);

    let trap = clamp(fr.trap * 0.5, 0.0, 1.0);
    let iterRatio = fr.iterRatio;

    // Compute normal
    let eps = 0.02;
    let gradient = computeGradient(worldPos, eps);
    let normal = normalize(gradient + vec3f(1e-6));

    return FragmentOutput(
        vec4f(normalizedDist, trap, iterRatio, 1.0),
        vec4f(normal * 0.5 + 0.5, normalizedDist)
    );
}

// WGSL version – WebGPU
// Precompute pass: generate 3D fractal volume as 2D atlas
@group(0) @binding(0) var<uniform> volumeSize: i32;
@group(0) @binding(1) var<uniform> noiseType: i32;
@group(0) @binding(2) var<uniform> power: f32;
@group(0) @binding(3) var<uniform> iterations: i32;
@group(0) @binding(4) var<uniform> bailout: f32;
@group(0) @binding(5) var<uniform> juliaX: f32;
@group(0) @binding(6) var<uniform> juliaY: f32;
@group(0) @binding(7) var<uniform> juliaZ: f32;
@group(0) @binding(8) var<uniform> colorMode: i32;
@group(0) @binding(9) var<uniform> tileOffset: vec2<f32>;
@group(0) @binding(10) var<uniform> renderScale: f32;

const PI: f32 = 3.141592653589793;

// Mandelbulb distance estimator
// Returns (distance estimate, orbit trap distance, iteration ratio)
fn mandelbulb(pos: vec3<f32>, n: f32, maxIter: i32, bail: f32) -> vec3<f32> {
    var z = pos;
    var dr: f32 = 1.0;
    var r: f32 = 0.0;
    var trap: f32 = 1e10;
    var iter: f32 = 0.0;

    for (var i: i32 = 0; i < maxIter; i = i + 1) {
        r = length(z);
        if (r > bail) { break; }

        // Orbit trap - distance to origin
        trap = min(trap, r);

        // Convert to spherical coordinates
        let theta = acos(z.z / r);
        let phi = atan2(z.y, z.x);

        // Scale the running derivative
        dr = pow(r, n - 1.0) * n * dr + 1.0;

        // Scale and rotate the point
        let zr = pow(r, n);
        let newTheta = theta * n;
        let newPhi = phi * n;

        // Convert back to Cartesian coordinates
        z = zr * vec3<f32>(
            sin(newTheta) * cos(newPhi),
            sin(newTheta) * sin(newPhi),
            cos(newTheta)
        );
        z = z + pos;

        iter = iter + 1.0;
    }

    // Distance estimator
    let dist = 0.5 * log(r) * r / dr;

    return vec3<f32>(dist, trap, iter / f32(maxIter));
}

// Julia Mandelbulb - fixed c point
fn juliaBulb(pos: vec3<f32>, c: vec3<f32>, n: f32, maxIter: i32, bail: f32) -> vec3<f32> {
    var z = pos;
    var dr: f32 = 1.0;
    var r: f32 = 0.0;
    var trap: f32 = 1e10;
    var iter: f32 = 0.0;

    for (var i: i32 = 0; i < maxIter; i = i + 1) {
        r = length(z);
        if (r > bail) { break; }

        trap = min(trap, r);

        let theta = acos(z.z / r);
        let phi = atan2(z.y, z.x);

        dr = pow(r, n - 1.0) * n * dr + 1.0;

        let zr = pow(r, n);
        let newTheta = theta * n;
        let newPhi = phi * n;

        z = zr * vec3<f32>(
            sin(newTheta) * cos(newPhi),
            sin(newTheta) * sin(newPhi),
            cos(newTheta)
        );
        z = z + c;  // Add constant c instead of pos

        iter = iter + 1.0;
    }

    let dist = 0.5 * log(r) * r / dr;
    return vec3<f32>(dist, trap, iter / f32(maxIter));
}

// Box fold operation for Mandelbox/Mandelcube
fn boxFold(z: vec3<f32>, foldingLimit: f32) -> vec3<f32> {
    return clamp(z, vec3<f32>(-foldingLimit), vec3<f32>(foldingLimit)) * 2.0 - z;
}

// Sphere fold operation for Mandelbox
fn sphereFold(z: vec3<f32>, minRadius: f32, fixedRadius: f32) -> vec3<f32> {
    let r2 = dot(z, z);
    let minR2 = minRadius * minRadius;
    let fixedR2 = fixedRadius * fixedRadius;

    if (r2 < minR2) {
        return z * (fixedR2 / minR2);
    } else if (r2 < fixedR2) {
        return z * (fixedR2 / r2);
    }
    return z;
}

// Mandelcube (simplified Mandelbox-like) distance estimator
fn mandelcube(pos: vec3<f32>, scale: f32, maxIter: i32, bail: f32) -> vec3<f32> {
    var z = pos;
    var dr: f32 = 1.0;
    var trap: f32 = 1e10;
    var iter: f32 = 0.0;

    let foldingLimit: f32 = 1.0;
    let minRadius: f32 = 0.5;
    let fixedRadius: f32 = 1.0;

    for (var i: i32 = 0; i < maxIter; i = i + 1) {
        // Box fold
        z = boxFold(z, foldingLimit);

        // Sphere fold
        let r2 = dot(z, z);
        let minR2 = minRadius * minRadius;
        let fixedR2 = fixedRadius * fixedRadius;

        if (r2 < minR2) {
            let factor = fixedR2 / minR2;
            z = z * factor;
            dr = dr * factor;
        } else if (r2 < fixedR2) {
            let factor = fixedR2 / r2;
            z = z * factor;
            dr = dr * factor;
        }

        // Scale and translate
        z = z * scale + pos;
        dr = dr * abs(scale) + 1.0;

        trap = min(trap, length(z));
        iter = iter + 1.0;

        if (length(z) > bail) { break; }
    }

    let r = length(z);
    let dist = r / abs(dr);

    return vec3<f32>(dist, trap, iter / f32(maxIter));
}

// Julia Mandelcube - fixed c point
fn juliaCube(pos: vec3<f32>, c: vec3<f32>, scale: f32, maxIter: i32, bail: f32) -> vec3<f32> {
    var z = pos;
    var dr: f32 = 1.0;
    var trap: f32 = 1e10;
    var iter: f32 = 0.0;

    let foldingLimit: f32 = 1.0;
    let minRadius: f32 = 0.5;
    let fixedRadius: f32 = 1.0;

    for (var i: i32 = 0; i < maxIter; i = i + 1) {
        z = boxFold(z, foldingLimit);

        let r2 = dot(z, z);
        let minR2 = minRadius * minRadius;
        let fixedR2 = fixedRadius * fixedRadius;

        if (r2 < minR2) {
            let factor = fixedR2 / minR2;
            z = z * factor;
            dr = dr * factor;
        } else if (r2 < fixedR2) {
            let factor = fixedR2 / r2;
            z = z * factor;
            dr = dr * factor;
        }

        z = z * scale + c;  // Add constant c instead of pos
        dr = dr * abs(scale) + 1.0;

        trap = min(trap, length(z));
        iter = iter + 1.0;

        if (length(z) > bail) { break; }
    }

    let r = length(z);
    let dist = r / abs(dr);

    return vec3<f32>(dist, trap, iter / f32(maxIter));
}

// MRT output structure for volume cache and geometry buffer
struct FragOutput {
    @location(0) color: vec4<f32>,
    @location(1) geoOut: vec4<f32>,
}

@fragment
fn main(@builtin(position) position: vec4<f32>) -> FragOutput {
    let volSize = volumeSize;
    let scaledVolSize = i32(f32(volSize) * renderScale);
    let scaledVolSizeF = f32(scaledVolSize);

    // Atlas is scaledVolSize x (scaledVolSize * scaledVolSize)
    // Pixel (x, y) maps to 3D coordinate (x, y % scaledVolSize, y / scaledVolSize)
    let globalPixelCoord = position.xy + tileOffset;
    let pixelCoord = vec2<i32>(globalPixelCoord);

    // GLSL mod(x, y) = x - y * floor(x / y)
    let xF = f32(pixelCoord.x);
    let x = i32(xF - scaledVolSizeF * floor(xF / scaledVolSizeF));
    let y = pixelCoord.y % scaledVolSize;
    let z = pixelCoord.y / scaledVolSize;

    // Bounds check
    if (x >= scaledVolSize || y >= scaledVolSize || z >= scaledVolSize) {
        return FragOutput(vec4<f32>(0.0), vec4<f32>(0.5, 0.5, 0.5, 0.0));
    }

    // Convert to normalized 3D coordinates in [-1.5, 1.5] world space
    // Slightly larger than [-1,1] to capture the full fractal
    let p = (vec3<f32>(f32(x), f32(y), f32(z)) / (scaledVolSizeF - 1.0) * 2.0 - 1.0) * 1.5;

    // Julia constant from uniforms (normalized from -100..100 to -1..1)
    let juliaC = vec3<f32>(juliaX, juliaY, juliaZ) * 0.01;

    var result: vec3<f32>;

    // Select fractal noiseType
    if (noiseType == 0) {
        // Mandelbulb
        result = mandelbulb(p, power, iterations, bailout);
    } else if (noiseType == 1) {
        // Mandelcube (use power as scale, clamped to reasonable range)
        let scale = clamp(power * 0.25, -3.0, 3.0);
        result = mandelcube(p, scale, iterations, bailout);
    } else if (noiseType == 2) {
        // Julia Bulb
        result = juliaBulb(p, juliaC, power, iterations, bailout);
    } else {
        // Julia Cube
        let scale = clamp(power * 0.25, -3.0, 3.0);
        result = juliaCube(p, juliaC, scale, iterations, bailout);
    }

    // result.x = distance estimate (used for threshold)
    // result.y = orbit trap (for coloring)
    // result.z = iteration ratio (for coloring)

    // Normalize distance to 0-1 range for storage
    // Small distances = inside/near surface, large = outside
    let dist = result.x;
    let normalizedDist = 1.0 - clamp(dist * 2.0 + 0.5, 0.0, 1.0);

    // Normalize trap value
    let trap = clamp(result.y * 0.5, 0.0, 1.0);

    // Iteration ratio is already 0-1
    let iterRatio = result.z;

    // Compute analytical gradient using finite differences
    let eps = 0.01;
    var dx: vec3<f32>;
    var dy: vec3<f32>;
    var dz: vec3<f32>;

    if (noiseType == 0) {
        dx = mandelbulb(p + vec3<f32>(eps, 0.0, 0.0), power, iterations, bailout);
        dy = mandelbulb(p + vec3<f32>(0.0, eps, 0.0), power, iterations, bailout);
        dz = mandelbulb(p + vec3<f32>(0.0, 0.0, eps), power, iterations, bailout);
    } else if (noiseType == 1) {
        let scale = clamp(power * 0.25, -3.0, 3.0);
        dx = mandelcube(p + vec3<f32>(eps, 0.0, 0.0), scale, iterations, bailout);
        dy = mandelcube(p + vec3<f32>(0.0, eps, 0.0), scale, iterations, bailout);
        dz = mandelcube(p + vec3<f32>(0.0, 0.0, eps), scale, iterations, bailout);
    } else if (noiseType == 2) {
        dx = juliaBulb(p + vec3<f32>(eps, 0.0, 0.0), juliaC, power, iterations, bailout);
        dy = juliaBulb(p + vec3<f32>(0.0, eps, 0.0), juliaC, power, iterations, bailout);
        dz = juliaBulb(p + vec3<f32>(0.0, 0.0, eps), juliaC, power, iterations, bailout);
    } else {
        let scale = clamp(power * 0.25, -3.0, 3.0);
        dx = juliaCube(p + vec3<f32>(eps, 0.0, 0.0), juliaC, scale, iterations, bailout);
        dy = juliaCube(p + vec3<f32>(0.0, eps, 0.0), juliaC, scale, iterations, bailout);
        dz = juliaCube(p + vec3<f32>(0.0, 0.0, eps), juliaC, scale, iterations, bailout);
    }

    let gradient = vec3<f32>(dx.x - dist, dy.x - dist, dz.x - dist) / eps;
    let normal = normalize(gradient + vec3<f32>(0.000001));  // SDF gradient points outward

    // Output volume data based on colorMode
    // colorMode 0 = mono (grayscale), 1 = rgb (distance, trap, iteration)
    var color = vec4<f32>(normalizedDist, trap, iterRatio, 1.0);
    if (colorMode == 0) {
        color = vec4<f32>(normalizedDist, normalizedDist, normalizedDist, 1.0);
    }
    let geoOut = vec4<f32>(normal * 0.5 + 0.5, normalizedDist);

    return FragOutput(color, geoOut);
}

struct Uniforms {
    volumeSize: i32,
    heightScale: f32,
    baseHeight: f32,
}
@group(0) @binding(0) var<uniform> u: Uniforms;
@group(0) @binding(1) var heightTex: texture_2d<f32>;
@group(0) @binding(2) var tex: texture_2d<f32>;

struct FragmentOutput {
    @location(0) fragColor: vec4f,
    @location(1) geoOut: vec4f,
}

// Native atlases and 2D surfaces use the same logical texel coordinates on both backends.
// Volume z = 0 holds the image's top row, so a view from above along -Y,
// screen right on +X, shows the image as authored rather than mirrored.
fn imageTexel(column: vec2i, size: vec2i) -> vec2i {
    let image = vec2i(column.x, u.volumeSize - 1 - column.y);
    return clamp(((image * 2 + 1) * size) / (u.volumeSize * 2), vec2i(0), size - 1);
}

fn columnHeight(column: vec2i) -> f32 {
    let rgb = textureLoad(heightTex, imageTexel(column, vec2i(textureDimensions(heightTex))), 0).rgb;
    let luminance = dot(rgb, vec3f(0.2126, 0.7152, 0.0722));
    return floor(clamp(luminance * u.heightScale + u.baseHeight, 0.0, 1.0) * f32(u.volumeSize) + 0.5);
}

fn density(p: vec3i) -> f32 {
    if (any(p < vec3i(0)) || any(p >= vec3i(u.volumeSize))) { return 0.0; }
    return select(0.0, 1.0, f32(p.y) < columnHeight(p.xz));
}

@fragment
fn main(@builtin(position) position: vec4f) -> FragmentOutput {
    let atlas = vec2i(position.xy);
    let p = vec3i(atlas.x, atlas.y % u.volumeSize, atlas.y / u.volumeSize);
    let occupied = density(p);
    var out: FragmentOutput;
    out.fragColor = vec4f(0.0);
    out.geoOut = vec4f(0.5, 1.0, 0.5, 0.0);
    if (occupied == 0.0) { return out; }

    let color = textureLoad(tex, imageTexel(p.xz, vec2i(textureDimensions(tex))), 0).rgb;
    out.fragColor = vec4f(color, occupied);
    var normal = vec3f(
        density(p - vec3i(1, 0, 0)) - density(p + vec3i(1, 0, 0)),
        density(p - vec3i(0, 1, 0)) - density(p + vec3i(0, 1, 0)),
        density(p - vec3i(0, 0, 1)) - density(p + vec3i(0, 0, 1))
    );
    if (dot(normal, normal) > 0.0) { normal = normalize(normal); }
    else { normal = vec3f(0.0, 1.0, 0.0); }
    out.geoOut = vec4f(normal * 0.5 + 0.5, occupied);
    return out;
}

// WGSL version – WebGPU
// OCTAVES, COLOR_MODE, RIDGES are compile-time defines injected by the
// expander (see definition.js). They drove a ~1.7s background compile in
// Dawn before being promoted; baking them lets the optimizer fully unroll
// the fbm4D octave loop, dead-code-eliminate the unused color/ridges
// branches, and drop the overall compile cost dramatically.
@group(0) @binding(0) var<uniform> time: f32;
@group(0) @binding(1) var<uniform> scale: f32;
@group(0) @binding(2) var<uniform> seed: i32;
@group(0) @binding(3) var<uniform> volumeSize: i32;
@group(0) @binding(4) var<uniform> speed: f32;

// MRT output structure
struct FragmentOutput {
    @location(0) fragColor: vec4<f32>,
    @location(1) geoOut: vec4<f32>,
}

// Volume dimensions - stored as 2D atlas
// Atlas layout: volumeSize x (volumeSize * volumeSize)

const TAU: f32 = 6.283185307179586;
const W_PERIOD: f32 = 4.0;  // Period length in w-axis lattice units for seamless time loop

// Improved hash using multiple rounds of mixing (4D version)
fn hash4(p: vec4<f32>) -> f32 {
    let ps = p + f32(seed) * 0.1;
    var q = vec4<u32>(vec4<i32>(ps * 1000.0) + 65536);
    q = q * 1664525u + 1013904223u;
    q.x = q.x + q.y * q.z;
    q.y = q.y + q.z * q.w;
    q.z = q.z + q.w * q.x;
    q.w = q.w + q.x * q.y;
    q = q ^ (q >> vec4<u32>(16u));
    q.x = q.x + q.y * q.z;
    q.y = q.y + q.z * q.w;
    q.z = q.z + q.w * q.x;
    q.w = q.w + q.x * q.y;
    return f32(q.x ^ q.y ^ q.z ^ q.w) / 4294967295.0;
}

// Gradient from hash - returns normalized 4D vector
fn grad4(p: vec4<f32>) -> vec4<f32> {
    let h1 = hash4(p);
    let h2 = hash4(p + 127.1);
    let h3 = hash4(p + 269.5);
    let h4 = hash4(p + 419.2);
    let g = vec4<f32>(
        h1 * 2.0 - 1.0,
        h2 * 2.0 - 1.0,
        h3 * 2.0 - 1.0,
        h4 * 2.0 - 1.0
    );
    return normalize(g);
}

// Quintic interpolation for smooth transitions
fn quintic(t: f32) -> f32 {
    return t * t * t * (t * (t * 6.0 - 15.0) + 10.0);
}

// Wrap w index for periodicity at lattice level
fn wrapW(w: f32) -> f32 {
    return (w % W_PERIOD + W_PERIOD) % W_PERIOD;
}

// 4D gradient noise - Perlin-style with quintic interpolation
// w-axis is periodic with period W_PERIOD for seamless time looping
fn noise4D(p: vec4<f32>) -> f32 {
    let i = floor(p);
    let f = fract(p);

    let u = vec4<f32>(quintic(f.x), quintic(f.y), quintic(f.z), quintic(f.w));

    // Wrap w indices for periodicity
    let iw0 = wrapW(i.w);
    let iw1 = wrapW(i.w + 1.0);

    // 16 corners of 4D hypercube with wrapped w
    // w=0 corners
    let n0000 = dot(grad4(vec4<f32>(i.xyz, iw0) + vec4<f32>(0.0, 0.0, 0.0, 0.0)), f - vec4<f32>(0.0, 0.0, 0.0, 0.0));
    let n1000 = dot(grad4(vec4<f32>(i.xyz, iw0) + vec4<f32>(1.0, 0.0, 0.0, 0.0)), f - vec4<f32>(1.0, 0.0, 0.0, 0.0));
    let n0100 = dot(grad4(vec4<f32>(i.xyz, iw0) + vec4<f32>(0.0, 1.0, 0.0, 0.0)), f - vec4<f32>(0.0, 1.0, 0.0, 0.0));
    let n1100 = dot(grad4(vec4<f32>(i.xyz, iw0) + vec4<f32>(1.0, 1.0, 0.0, 0.0)), f - vec4<f32>(1.0, 1.0, 0.0, 0.0));
    let n0010 = dot(grad4(vec4<f32>(i.xyz, iw0) + vec4<f32>(0.0, 0.0, 1.0, 0.0)), f - vec4<f32>(0.0, 0.0, 1.0, 0.0));
    let n1010 = dot(grad4(vec4<f32>(i.xyz, iw0) + vec4<f32>(1.0, 0.0, 1.0, 0.0)), f - vec4<f32>(1.0, 0.0, 1.0, 0.0));
    let n0110 = dot(grad4(vec4<f32>(i.xyz, iw0) + vec4<f32>(0.0, 1.0, 1.0, 0.0)), f - vec4<f32>(0.0, 1.0, 1.0, 0.0));
    let n1110 = dot(grad4(vec4<f32>(i.xyz, iw0) + vec4<f32>(1.0, 1.0, 1.0, 0.0)), f - vec4<f32>(1.0, 1.0, 1.0, 0.0));
    // w=1 corners
    let n0001 = dot(grad4(vec4<f32>(i.xyz, iw1) + vec4<f32>(0.0, 0.0, 0.0, 0.0)), f - vec4<f32>(0.0, 0.0, 0.0, 1.0));
    let n1001 = dot(grad4(vec4<f32>(i.xyz, iw1) + vec4<f32>(1.0, 0.0, 0.0, 0.0)), f - vec4<f32>(1.0, 0.0, 0.0, 1.0));
    let n0101 = dot(grad4(vec4<f32>(i.xyz, iw1) + vec4<f32>(0.0, 1.0, 0.0, 0.0)), f - vec4<f32>(0.0, 1.0, 0.0, 1.0));
    let n1101 = dot(grad4(vec4<f32>(i.xyz, iw1) + vec4<f32>(1.0, 1.0, 0.0, 0.0)), f - vec4<f32>(1.0, 1.0, 0.0, 1.0));
    let n0011 = dot(grad4(vec4<f32>(i.xyz, iw1) + vec4<f32>(0.0, 0.0, 1.0, 0.0)), f - vec4<f32>(0.0, 0.0, 1.0, 1.0));
    let n1011 = dot(grad4(vec4<f32>(i.xyz, iw1) + vec4<f32>(1.0, 0.0, 1.0, 0.0)), f - vec4<f32>(1.0, 0.0, 1.0, 1.0));
    let n0111 = dot(grad4(vec4<f32>(i.xyz, iw1) + vec4<f32>(0.0, 1.0, 1.0, 0.0)), f - vec4<f32>(0.0, 1.0, 1.0, 1.0));
    let n1111 = dot(grad4(vec4<f32>(i.xyz, iw1) + vec4<f32>(1.0, 1.0, 1.0, 0.0)), f - vec4<f32>(1.0, 1.0, 1.0, 1.0));

    // Quadrilinear interpolation
    // First along x
    let nx000 = mix(n0000, n1000, u.x);
    let nx100 = mix(n0100, n1100, u.x);
    let nx010 = mix(n0010, n1010, u.x);
    let nx110 = mix(n0110, n1110, u.x);
    let nx001 = mix(n0001, n1001, u.x);
    let nx101 = mix(n0101, n1101, u.x);
    let nx011 = mix(n0011, n1011, u.x);
    let nx111 = mix(n0111, n1111, u.x);

    // Then along y
    let nxy00 = mix(nx000, nx100, u.y);
    let nxy10 = mix(nx010, nx110, u.y);
    let nxy01 = mix(nx001, nx101, u.y);
    let nxy11 = mix(nx011, nx111, u.y);

    // Then along z
    let nxyz0 = mix(nxy00, nxy10, u.z);
    let nxyz1 = mix(nxy01, nxy11, u.z);

    // Finally along w
    return mix(nxyz0, nxyz1, u.w);
}

// FBM using 4D noise with periodic w for time.
// OCTAVES is a compile-time const so the loop bound is static and the
// optimizer fully unrolls it. RIDGES is a compile-time bool so the per-octave
// branch is dead-code-eliminated.
fn fbm4D(p: vec4<f32>) -> f32 {
    var amplitude: f32 = 0.5;
    var frequency: f32 = 1.0;
    var sum: f32 = 0.0;
    var maxVal: f32 = 0.0;

    for (var i: i32 = 0; i < OCTAVES; i = i + 1) {
        let pos = vec4<f32>(p.xyz * frequency, p.w);
        var n = noise4D(pos);
        n = clamp(n * 1.5, -1.0, 1.0);
        if (RIDGES) {
            n = 1.0 - abs(n);
        } else {
            n = (n + 1.0) * 0.5;
        }
        sum = sum + n * amplitude;
        maxVal = maxVal + amplitude;
        frequency = frequency * 2.0;
        amplitude = amplitude * 0.5;
    }
    return sum / maxVal;
}

@fragment
fn main(@builtin(position) position: vec4<f32>) -> FragmentOutput {
    // Use uniform for volume size
    let volSize = volumeSize;
    let volSizeF = f32(volSize);

    // Atlas is volSize x (volSize * volSize)
    // Pixel (x, y) maps to 3D coordinate (x, y % volSize, y / volSize)

    let pixelCoord = vec2<i32>(position.xy);

    let x = pixelCoord.x;
    let y = pixelCoord.y % volSize;
    let z = pixelCoord.y / volSize;

    // Bounds check
    if (x >= volSize || y >= volSize || z >= volSize) {
        return FragmentOutput(vec4<f32>(0.0), vec4<f32>(0.5, 0.5, 0.5, 0.0));
    }

    // Convert to normalized 3D coordinates in [-1, 1] world space (bounding box)
    let p = vec3<f32>(f32(x), f32(y), f32(z)) / (volSizeF - 1.0) * 2.0 - 1.0;

    // Scale for noise density
    let scaledP = p * scale;

    // Linear time traversal with periodic w-axis
    // time goes 0->1, map to 0->W_PERIOD for one complete loop
    // speed multiplies time to control animation speed
    let w = time * speed * W_PERIOD;

    // Compute 4D FBM noise at this point with time as w
    let p4d = vec4<f32>(scaledP, w);
    let noiseVal = fbm4D(p4d);

    // Compute analytical gradient using finite differences in noise space
    let eps = 0.01 / scale;
    let nx = fbm4D(vec4<f32>(scaledP + vec3<f32>(eps, 0.0, 0.0), w));
    let ny = fbm4D(vec4<f32>(scaledP + vec3<f32>(0.0, eps, 0.0), w));
    let nz = fbm4D(vec4<f32>(scaledP + vec3<f32>(0.0, 0.0, eps), w));

    // Gradient points from low to high density
    let gradient = vec3<f32>(nx - noiseVal, ny - noiseVal, nz - noiseVal) / eps;

    // Normal points outward (from high to low density), encode in [0,1] range
    let normal = normalize(-gradient + vec3<f32>(1e-6));

    // Output volume data based on colorMode (compile-time const).
    var fragColor: vec4<f32>;
    if (COLOR_MODE == 0) {
        fragColor = vec4<f32>(noiseVal, noiseVal, noiseVal, 1.0);
    } else {
        // For RGB color mode, compute 3 different noise channels with offsets
        let g = fbm4D(vec4<f32>(scaledP, w) + vec4<f32>(0.0, 0.0, 0.0, 1.33));
        let b = fbm4D(vec4<f32>(scaledP, w) + vec4<f32>(0.0, 0.0, 0.0, 2.67));
        fragColor = vec4<f32>(noiseVal, g, b, 1.0);
    }

    // Output analytical geometry: normal.xyz encoded [0,1], density in w
    let geoOut = vec4<f32>(normal * 0.5 + 0.5, noiseVal);

    return FragmentOutput(fragColor, geoOut);
}

/*
 * 3D Reaction-Diffusion simulation shader (WGSL)
 * Implements Gray-Scott model in 3D with 6-neighbor Laplacian
 * Self-initializing: detects empty buffer and seeds on first frame
 */

@group(0) @binding(0) var<uniform> volumeSize: i32;
@group(0) @binding(1) var<uniform> seed: i32;
@group(0) @binding(2) var<uniform> feed: f32;
@group(0) @binding(3) var<uniform> kill: f32;
@group(0) @binding(4) var<uniform> rate1: f32;
@group(0) @binding(5) var<uniform> rate2: f32;
@group(0) @binding(6) var<uniform> speed: f32;
@group(0) @binding(7) var<uniform> weight: f32;
@group(0) @binding(8) var stateTex: texture_2d<f32>;
@group(0) @binding(9) var seedTex: texture_2d<f32>;  // 3D input volume atlas (inputTex3d)
@group(0) @binding(10) var<uniform> iterations: i32;
@group(0) @binding(11) var<uniform> colorMode: i32;
@group(0) @binding(12) var<uniform> resetState: i32;

// Hash for initialization
fn hash3(p: vec3<f32>, s: f32) -> f32 {
    var pp = p + s * 0.1;
    pp = fract(pp * vec3<f32>(0.1031, 0.1030, 0.0973));
    pp = pp + dot(pp, pp.yxz + 33.33);
    return fract((pp.x + pp.y) * pp.z);
}

// Helper to convert 3D voxel coords to 2D atlas texel coords with wrapping
fn atlasTexel(p: vec3<i32>, volSize: i32) -> vec2<i32> {
    // Wrap coordinates for periodic boundary
    let wrapped = vec3<i32>(
        (p.x + volSize) % volSize,
        (p.y + volSize) % volSize,
        (p.z + volSize) % volSize
    );
    return vec2<i32>(wrapped.x, wrapped.y + wrapped.z * volSize);
}

// Sample state at voxel coordinate with wrapping
fn sampleState(voxel: vec3<i32>, volSize: i32) -> vec4<f32> {
    return textureLoad(stateTex, atlasTexel(voxel, volSize), 0);
}

// Sample seed texture at voxel coordinate (for inputTex3d seeding)
fn sampleSeed(voxel: vec3<i32>, volSize: i32) -> vec4<f32> {
    return textureLoad(seedTex, atlasTexel(voxel, volSize), 0);
}

// 3D Laplacian using 6-neighbor stencil
// Standard discrete Laplacian for uniform 3D grid
fn laplacian3D(voxel: vec3<i32>, volSize: i32) -> vec2<f32> {
    let center = sampleState(voxel, volSize);

    // 6-neighbor stencil (face-adjacent neighbors)
    let xp = sampleState(voxel + vec3<i32>(1, 0, 0), volSize);
    let xn = sampleState(voxel + vec3<i32>(-1, 0, 0), volSize);
    let yp = sampleState(voxel + vec3<i32>(0, 1, 0), volSize);
    let yn = sampleState(voxel + vec3<i32>(0, -1, 0), volSize);
    let zp = sampleState(voxel + vec3<i32>(0, 0, 1), volSize);
    let zn = sampleState(voxel + vec3<i32>(0, 0, -1), volSize);

    // Standard discrete 3D Laplacian: sum of neighbors - 6 * center
    // State layout: .r = B (density), .a = A (chemical)
    let neighborSum = xp.ra + xn.ra + yp.ra + yn.ra + zp.ra + zn.ra;
    let lap = neighborSum - 6.0 * center.ra;

    return lap;
}

@fragment
fn main(@builtin(position) position: vec4<f32>) -> @location(0) vec4<f32> {
    let volSize = volumeSize;
    let volSizeF = f32(volSize);

    // Decode voxel position from atlas
    let pixelCoord = vec2<i32>(position.xy);
    let x = pixelCoord.x;
    let y = pixelCoord.y % volSize;
    let z = pixelCoord.y / volSize;
    let voxel = vec3<i32>(x, y, z);

    // Bounds check
    if (x >= volSize || y >= volSize || z >= volSize) {
        return vec4<f32>(0.0);
    }

    // Current state
    let state = sampleState(voxel, volSize);
    var b = state.r;  // Chemical B (density, used by render3d)
    var a = state.a;  // Chemical A (simulation state)

    // Self-initialization: detect empty buffer (first frame) or reset requested
    let bufferIsEmpty = (state.r == 0.0 && state.g == 0.0 && state.b == 0.0 && state.a == 0.0);

    if (bufferIsEmpty || resetState != 0) {
        a = 1.0;
        b = 0.0;

        if (resetState != 0) {
            // Reset behavior: reseed a 4x4x4 cube at the center of the volume.
            // For even sizes, this is indices [N/2-2 .. N/2+1] (inclusive).
            let start: i32 = max(0, (volSize / 2) - 2);
            let end: i32 = min(volSize - 1, start + 3);
            let inCenterCube = (x >= start && x <= end && y >= start && y <= end && z >= start && z <= end);
            if (inCenterCube) { b = 1.0; }
        } else {
            // First-frame init: if we have input from seedTex (inputTex3d), use it.
            let seedVal = sampleSeed(voxel, volSize);
            let hasSeedInput = (seedVal.r > 0.0 || seedVal.g > 0.0 || seedVal.b > 0.0);

            if (hasSeedInput) {
                let lum = 0.299 * seedVal.r + 0.587 * seedVal.g + 0.114 * seedVal.b;
                if (lum > 0.5) {
                    b = 1.0;
                }
            } else {
                // Fallback: sparse random seeding of B
                let p = vec3<f32>(f32(x), f32(y), f32(z));
                if (hash3(p, f32(seed)) > 0.97) {
                    b = 1.0;
                }
            }
        }

        return vec4<f32>(b, b, b, a);
    }

    // Compute Laplacian for diffusion
    let lap = laplacian3D(voxel, volSize);

    // Gray-Scott parameters (scaled from UI values)
    // Note: Laplacian in 3D is 6x larger than normalized form,
    // so we scale diffusion rates down by 6 to maintain stability
    let f = feed * 0.001;        // Feed rate
    let k = kill * 0.001;        // Kill rate
    let r1 = rate1 * 0.01 / 6.0;   // Diffusion rate A (scaled for 3D)
    let r2 = rate2 * 0.01 / 6.0;   // Diffusion rate B (scaled for 3D)
    // This pass is executed `iterations` times per frame (pipeline repeat).
    // Scale timestep per-iteration so "speed" behaves like a per-frame control.
    let iterF = max(1.0, f32(iterations));
    let s = (speed * 0.01) / iterF;

    // Gray-Scott reaction-diffusion equations
    // lap.x = Lap(B) from .r, lap.y = Lap(A) from .a
    var newA = clamp(a + (r1 * lap.y - a * b * b + f * (1.0 - a)) * s, 0.0, 1.0);
    var newB = clamp(b + (r2 * lap.x + a * b * b - (k + f) * b) * s, 0.0, 1.0);

    // Apply input weight blending from seedTex (inputTex3d)
    if (weight > 0.0) {
        let seedVal = sampleSeed(voxel, volSize);
        let seedLum = 0.299 * seedVal.r + 0.587 * seedVal.g + 0.114 * seedVal.b;
        // Seed influences chemical B (the visible one)
        newB = mix(newB, seedLum, weight * 0.01);
    }

    // .r = B (density for render3d), .a = A (simulation state)
    // .rgb = visualization colors, .a = chemical A
    let density = newB;
    var outRgb: vec3<f32>;
    if (colorMode == 0) {
        outRgb = vec3<f32>(density);
    } else {
        outRgb = vec3<f32>(density, newA, 1.0 - density);
    }

    return vec4<f32>(outRgb, newA);
}

/*
 * Precompute shader for nu/shape3d (WGSL)
 * Fills a 64x4096 2D atlas representing a 64^3 3D volume
 * Each texel stores the shape offset value for that 3D position
 * Atlas layout: pixel (x, y) maps to 3D coord (x, y % 64, floor(y / 64))
 */

@group(0) @binding(0) var<uniform> loopAOffset: i32;
@group(0) @binding(1) var<uniform> loopBOffset: i32;
@group(0) @binding(2) var<uniform> loopAScale: f32;
@group(0) @binding(3) var<uniform> loopBScale: f32;
@group(0) @binding(4) var<uniform> speedA: f32;
@group(0) @binding(5) var<uniform> speedB: f32;
@group(0) @binding(6) var<uniform> time: f32;
@group(0) @binding(7) var<uniform> volumeSize: i32;

const PI: f32 = 3.14159265359;
const TAU: f32 = 6.28318530718;

fn map_range(value: f32, inMin: f32, inMax: f32, outMin: f32, outMax: f32) -> f32 {
    return outMin + (outMax - outMin) * (value - inMin) / (inMax - inMin);
}

fn periodicFunction(p: f32) -> f32 {
    let x = TAU * p;
    return map_range(sin(x), -1.0, 1.0, 0.0, 1.0);
}

// ============================================
// 3D Polyhedral SDF Functions
// ============================================

// Tetrahedron (4 faces, 4 vertices)
fn tetrahedronSDF(p: vec3<f32>) -> f32 {
    let s = 0.5;
    return (max(abs(p.x + p.y) - p.z, abs(p.x - p.y) + p.z) - s) / sqrt(3.0);
}

// Cube / Hexahedron (6 faces, 8 vertices)
fn cubeSDF(p: vec3<f32>) -> f32 {
    let d = abs(p) - vec3<f32>(0.45);
    return length(max(d, vec3<f32>(0.0))) + min(max(d.x, max(d.y, d.z)), 0.0);
}

// Octahedron (8 faces, 6 vertices)
fn octahedronSDF(p: vec3<f32>) -> f32 {
    let ap = abs(p);
    let s = 0.5;
    return (ap.x + ap.y + ap.z - s) * 0.57735027;
}

// Dodecahedron (12 pentagonal faces, 20 vertices)
fn dodecahedronSDF(p: vec3<f32>) -> f32 {
    let ap = abs(p);
    let phi = (1.0 + sqrt(5.0)) * 0.5;  // Golden ratio

    let n1 = normalize(vec3<f32>(1.0, phi, 0.0));
    let n2 = normalize(vec3<f32>(0.0, 1.0, phi));
    let n3 = normalize(vec3<f32>(phi, 0.0, 1.0));

    var d = 0.0;
    d = max(d, dot(ap, n1));
    d = max(d, dot(ap, n2));
    d = max(d, dot(ap, n3));
    d = max(d, ap.x);
    d = max(d, ap.y);
    d = max(d, ap.z);

    return d - 0.45;
}

// Icosahedron (20 triangular faces, 12 vertices)
fn icosahedronSDF(p: vec3<f32>) -> f32 {
    let ap = abs(p);
    let phi = (1.0 + sqrt(5.0)) * 0.5;

    let n1 = normalize(vec3<f32>(phi, 1.0, 0.0));
    let n2 = normalize(vec3<f32>(1.0, 0.0, phi));
    let n3 = normalize(vec3<f32>(0.0, phi, 1.0));

    var d = 0.0;
    d = max(d, dot(ap, n1));
    d = max(d, dot(ap, n2));
    d = max(d, dot(ap, n3));
    d = max(d, dot(ap, normalize(vec3<f32>(1.0, 1.0, 1.0))));

    return d - 0.42;
}

// ============================================
// Other 3D Primitive SDFs
// ============================================

fn sphereSDF(p: vec3<f32>) -> f32 {
    return length(p) - 0.5;
}

fn torusSDF(p: vec3<f32>) -> f32 {
    let t = vec2<f32>(0.35, 0.12);
    let q = vec2<f32>(length(p.xz) - t.x, p.y);
    return length(q) - t.y;
}

fn cylinderSDF(p: vec3<f32>) -> f32 {
    let d = abs(vec2<f32>(length(p.xz), p.y)) - vec2<f32>(0.35, 0.45);
    return min(max(d.x, d.y), 0.0) + length(max(d, vec2<f32>(0.0)));
}

fn coneSDF(p: vec3<f32>) -> f32 {
    let h = 0.6;
    let r = 0.4;
    let c = normalize(vec2<f32>(h, r));
    let q = length(p.xz);
    return max(dot(c.xy, vec2<f32>(q, p.y)), -p.y - h * 0.5);
}

fn capsuleSDF(p: vec3<f32>) -> f32 {
    let h = 0.3;
    let r = 0.25;
    var pp = p;
    pp.y = pp.y - clamp(pp.y, -h, h);
    return length(pp) - r;
}

// Get SDF value for shape type
fn shapeSDF(p: vec3<f32>, shapeType: i32) -> f32 {
    // Platonic Solids
    if (shapeType == 10) { return tetrahedronSDF(p); }
    if (shapeType == 20) { return cubeSDF(p); }
    if (shapeType == 30) { return octahedronSDF(p); }
    if (shapeType == 40) { return dodecahedronSDF(p); }
    if (shapeType == 50) { return icosahedronSDF(p); }

    // Other Primitives
    if (shapeType == 100) { return sphereSDF(p); }
    if (shapeType == 110) { return torusSDF(p); }
    if (shapeType == 120) { return cylinderSDF(p); }
    if (shapeType == 130) { return coneSDF(p); }
    if (shapeType == 140) { return capsuleSDF(p); }

    return sphereSDF(p);
}

// Get SDF-based offset for a position
fn offset3D(p: vec3<f32>, freq: f32, loopOffset: i32) -> f32 {
    // Center at origin: [0,1] -> [-0.5, 0.5]
    let cp = p - vec3<f32>(0.5);

    // SDF is negative inside, positive outside
    // Convert to offset: invert and scale by freq for periodic shells
    let sdf = shapeSDF(cp, loopOffset);
    return (0.5 - sdf) * freq;
}

// Compute full output value for a position (for gradient computation)
fn computeValue(p: vec3<f32>, lf1: f32, lf2: f32) -> f32 {
    let offset1 = offset3D(p, lf1, loopAOffset);
    let offset2 = offset3D(p, lf2, loopBOffset);

    // Drive periodic function from SDF offset + time * speed
    // Speed is integer so time (0-1 loop) stays seamless
    let t1 = offset1 + time * floor(speedA);
    let t2 = offset2 + time * floor(speedB);

    let a = periodicFunction(t1);
    let b = periodicFunction(t2);

    return (a + b) * 0.5;
}

// MRT output structure for volume cache and geometry buffer
struct FragOutput {
    @location(0) color: vec4<f32>,
    @location(1) geoOut: vec4<f32>,
}

@fragment
fn main(@builtin(position) position: vec4<f32>) -> FragOutput {
    // Convert 2D fragment position to 3D volume coordinates
    let volSize = volumeSize;
    let volSizeF = f32(volSize);
    let x = i32(position.x);
    let yAtlas = i32(position.y);
    let y = yAtlas % volSize;
    let z = yAtlas / volSize;

    // Normalize to [0, 1]
    let p = vec3<f32>(f32(x), f32(y), f32(z)) / (volSizeF - 1.0);

    // Calculate frequencies from scale parameters
    let lf1 = map_range(loopAScale, 1.0, 100.0, 6.0, 1.0);
    let lf2 = map_range(loopBScale, 1.0, 100.0, 6.0, 1.0);

    // Compute value at this position
    let d = computeValue(p, lf1, lf2);

    // Compute analytical gradient using finite differences
    let eps = 1.0 / volSizeF;
    let dx = computeValue(p + vec3<f32>(eps, 0.0, 0.0), lf1, lf2);
    let dy = computeValue(p + vec3<f32>(0.0, eps, 0.0), lf1, lf2);
    let dz = computeValue(p + vec3<f32>(0.0, 0.0, eps), lf1, lf2);

    let gradient = vec3<f32>(dx - d, dy - d, dz - d) / eps;
    let normal = normalize(-gradient + vec3<f32>(0.000001));

    let color = vec4<f32>(d, d, d, 1.0);
    let geoOut = vec4<f32>(normal * 0.5 + 0.5, d);

    return FragOutput(color, geoOut);
}

